import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICustomerSignOut } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignOut";

/**
 * Validate error on unauthenticated logout attempt for customer session.
 *
 * This test ensures that when a logout is attempted without a valid authentication token (JWT) as a customer, the API correctly rejects the request, indicating that there is no active session or that the request is unauthenticated. This is important to ensure session security and correct error signaling.
 *
 * Steps:
 * 1. Attempt to call the logout endpoint without any authentication (no JWT in the connection).
 * 2. Confirm that an error is thrown rather than a successful response.
 */
export async function test_api_customer_logout_unauthenticated(
  connection: api.IConnection
) {
  // 1. Directly call signOut without prior authentication or JWT
  await TestValidator.error("logout without authentication produces error")(async () => {
    await api.functional.auth.customer.logout.signOut(connection);
  });
}

