  // 1. Prepare random credentials for non-existent admin email/password
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(14); // 14-char random password

  // 2. Attempt login and expect an authentication error
  await TestValidator.error("login with non-existent email should fail")(async () => {
    await api.functional.auth.admin.login.signIn(connection, {
      body: {
        email,
        password,
      } satisfies IAdminAuth.SignIn,
    });
  });
