import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate duplicate admin registration prevention.
 *
 * This test ensures that registering an admin with an email address that already exists in the system fails as expected, enforcing the unique constraint policy on admin emails. No new account or JWT should be created in this case.
 *
 * Business Context: Email uniqueness is critical to platform security and proper RBAC administration. This prevents accidental or malicious account collisions.
 *
 * Workflow:
 * 1. Register an admin with a random, valid business email and password.
 * 2. Attempt to register a second admin using the same email and a different password.
 * 3. Validate that the second registration attempt throws an error (unique constraint violation), and no new JWT or account is issued.
 *
 * Edge Cases:
 * - Make sure that the error arises at the registration call and is not a type error or a missing field error.
 */
export async function test_api_admin_registration_duplicate_email(
  connection: api.IConnection,
) {
  // 1. Register first admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const passwordA = "PasswordA#1234";
  const firstAdmin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: passwordA,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(firstAdmin);
  TestValidator.equals("admin email matches")(firstAdmin.email)(adminEmail);

  // 2. Attempt duplicate registration with same email
  const passwordB = "PasswordB#5678";
  await TestValidator.error("duplicate admin registration must fail")(
    async () => {
      await api.functional.auth.admin.register.signUp(connection, {
        body: {
          email: adminEmail,
          password: passwordB,
        } satisfies IAdminAuth.SignUp,
      });
    },
  );
}

