 * - As only the registration endpoint is available, only the error response can be tested directly.
 * - Cannot directly verify audit log or absence of new account due to lack of listing/lookup endpoint.
 */
export async function test_api_seller_registration_invalid_email_format(connection: api.IConnection) {
  // Step 1: Attempt to register with an invalid email address.
  const invalidEmail = "invalid-email-format"; // Not RFC/email compliant
  const signUpPayload: ISellerAuth.SignUp = {
    email: invalidEmail,
    password: "Str0ngPassw0rd!",
    companyName: "ABC Test Trading LLC",
    businessNumber: "1234567890",
