import type { ICustomerChangePassword } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerChangePassword";

/**
 * Validate that password change operation without authentication fails.
 *
 * This test verifies that attempting to change a customer password using the /auth/customer/password endpoint without supplying a valid authentication token (JWT) is properly rejected by the API. The operation must not succeed, and the response should indicate a lack of permission.
 *
 * Steps:
 * 1. Prepare a change password request body with random values (currentPassword, newPassword)
 * 2. Attempt to call the password change endpoint WITHOUT setting any authentication headers on the connection
 * 3. Expect the operation to fail
 * 4. Validate that the API response indicates failure (success: false)
 * 5. (Edge case) Optionally, repeat with syntactically valid but semantically invalid JWT
 */
export async function test_api_customer_change_password_unauthenticated(connection: api.IConnection) {
  // 1. Prepare request body with random but plausible values
  const body: ICustomerChangePassword.Request = {
    currentPassword: RandomGenerator.alphaNumeric(10),
    newPassword: RandomGenerator.alphaNumeric(12),
  };

  // 2. Attempt password change with NO authentication
  const unauthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  const result = await api.functional.auth.customer.password.changePassword(unauthConnection, { body });

  // 3. Validate failure response
  typia.assert(result);
  TestValidator.equals("unauthenticated password change should fail")(result.success)(false);

  // 4. Optionally: Try with an invalid JWT
  const bogusConnection = { ...connection, headers: { ...connection.headers, Authorization: "Bearer invalidtoken" } };
  const result2 = await api.functional.auth.customer.password.changePassword(bogusConnection, { body });
  typia.assert(result2);
  TestValidator.equals("invalid JWT should fail")(result2.success)(false);
}

