 * This test verifies that a shopping mall admin can successfully create a point wallet
 * for a newly registered customer, and that duplicate wallets for the same customer are
 * prevented by the backend business rules.
 *
 * Workflow:
 * 1. Register a new customer with valid information via the public registration endpoint
 *    (requirements: unique email, valid phone, legal name, nickname).
 * 2. Use the returned customer.id to create a point wallet via the admin endpoint.
 *    - Provide the customer_id and an initial balance.
 *    - Validate that the newly created wallet reflects the correct balance and is associated
 *      to the intended customer, and the data matches the output schema.
 * 3. Attempt to create a second wallet for the same customer.
 *    - Expect an error due to the business rule enforcing one wallet per customer.
 *    - Validate that the API responds with an error (using TestValidator.error) and that no second wallet is created.
 */
export async function test_api_point_wallet_creation_success_and_duplicate_failure(connection: api.IConnection) {
  // 1. Register a new customer
  const customerInput: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "testPW-1234",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const customerSignUpResult = await api.functional.auth.customer.register.signUp(connection, {
    body: customerInput,
  });
  typia.assert(customerSignUpResult);
  const customerId = customerSignUpResult.customer.id;

  // 2. Create a point wallet as admin
  const initialBalance = 10000;
  const wallet = await api.functional.shoppingMallAiBackend.admin.points.create(connection, {
    body: {
      customer_id: customerId,
      balance: initialBalance,
    },
  });
  typia.assert(wallet);
  TestValidator.equals("wallet-customer-id")(wallet.customer_id)(customerId);
  TestValidator.equals("wallet-balance")(wallet.balance)(initialBalance);

  // 3. Attempt to create a duplicate wallet for the same customer (should fail)
  await TestValidator.error("duplicate wallet creation must fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.points.create(connection, {
      body: {
        customer_id: customerId,
        balance: 50000,
      },
    });
  });
}

