/**
 * End-to-end validation for the admin login (sign in) API, covering both successful and failure authentication cases.
 *
 * This test simulates real-world admin login attempts (POST /auth/admin/login):
 * - A successful login with a freshly registered admin account (using correct email+password).
 * - Failed logins via (a) incorrect password, (b) non-existent email, (c) login for admin account intended as "locked" or “soft-deleted” (these will be simulated as failure due to current API limitations/no direct lock/delete endpoint).
 *
 * Steps:
 * 1. Register an admin with random business-compliant credentials.
 * 2. Attempt to log in with correct credentials—expect JWT token, successful response, and profile data. Validate returned JWT and profile fields.
 * 3. Attempt to log in with the right email but wrong password—expect error and NO JWT in the response.
 * 4. Attempt to log in with an email that does not exist—expect error and NO JWT.
 * 5. (Negative scenario) Attempt to log in with a “locked” or soft-deleted admin; as this cannot be setup directly with current API, this will be noted in code comments as not implementable.
 * 6. (Audit Check) Both successful and failure cases should return responses indicating audit logging is performed (as per business guarantee in API doc, though not directly queryable via POST/login response).
 */
export async function test_api_admin_login_success_and_failure_scenarios(connection: api.IConnection) {
  // 1. Register admin with random credentials
  const email = typia.random<string & tags.Format<"email">>();
  const password = `P@ss${typia.random<string>().slice(0,5)}`;
  const signUpOutput = await api.functional.auth.admin.register.signUp(connection, { body: { email, password } });
  typia.assert(signUpOutput);

  // 2. Login with correct credentials
