  TestValidator.equals("ip_address matches")(retrieved.ip_address)(logInput.ip_address);
  TestValidator.equals("operated_by_admin_id matches")(retrieved.operated_by_admin_id)(logInput.operated_by_admin_id);
  TestValidator.equals("event_context matches")(retrieved.event_context)(logInput.event_context);
  TestValidator.equals("event_at matches")(retrieved.event_at)(logInput.event_at);

