import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate failure scenario when a seller attempts to change their password with an incorrect current password.
 *
 * Business context:
 * Sellers must supply their actual current password when changing credentials. The system must prevent password update if the current password is incorrect, returning an authentication error and preserving all session, audit, and account state.
 *
 * Workflow:
 * 1. Register a new seller with valid details.
 * 2. Log in as the seller to receive a valid JWT authentication (session).
 * 3. Attempt to change the seller password, but provide an incorrect current password in the request body.
 * 4. Confirm that the password change operation is rejected with an error (runtime failure, not type violation).
 * 5. Optional: Verify that subsequent login with the original (correct) password still succeeds, ensuring no state change occurred.
 */
export async function test_api_seller_change_password_failure_incorrect_current_password(connection: api.IConnection) {
  // 1. Register a new seller
  const signUpInput: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "VerySecret123!",
    companyName: "AI E2E Test Seller",
    businessNumber: "1234567890",
    representativeName: "Test Owner",
    address: "1 AI Test Rd, Test City",
    phone: "01012345678"
  };
  const sellerResp = await api.functional.auth.seller.register.signUp(connection, { body: signUpInput });
  typia.assert(sellerResp);

  // 2. Log in as the seller with correct credentials
  const signInResp = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: signUpInput.email,
      password: signUpInput.password
    }
  });
  typia.assert(signInResp);

  // 3. Attempt to change password with wrong current password
  await TestValidator.error("password change with wrong current password must fail")(
    async () => {
      await api.functional.auth.seller.password.changePassword(connection, {
        body: {
          currentPassword: "WrongPassword!123",
          newPassword: "AnotherSecret123!"
        }
      });
    }
  );

  // 4. Verify login with the original password still works (no state change)
  const reSignInResp = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: signUpInput.email,
      password: signUpInput.password
    }
  });
  typia.assert(reSignInResp);
  TestValidator.equals("seller ID unchanged after failed password update")(signInResp.sellerId)(reSignInResp.sellerId);
}

