/**
 * Validate successful creation and persistence of a new business rule as an admin.
 *
 * This test covers the workflow of authenticating as an admin and then using the admin permissions
 * to create a new business rule (policy/compliance constraint) with all required fields. It ensures
 * proper field population, unique rule code guarantee, and that returned data reflects all submitted
 * attributes accurately for audit/compliance. Also checks system rejects duplicate codes.
 *
 * Steps:
 * 1. Authenticate as admin via /auth/admin/login to retrieve an admin JWT.
 * 2. Using the admin connection, issue POST /shoppingMallAiBackend/admin/businessRules with a unique
 *    rule_code and all required fields.
 * 3. Assert that response contains an object matching input fields, is persisted (UUID and timestamps present), and rule_code is as sent.
 * 4. Validate audit-related fields are present.
 * 5. Attempt to re-create a rule with the same rule_code and ensure it fails (error thrown or rejected).
 */
export async function test_api_businessrule_create_success(connection: api.IConnection) {
  // 1. Authenticate as admin to obtain JWT
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin!1234";
  // In this context, assume admin with these credentials already exists,
  // or use pre-provisioned admin for E2E.
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);

  // 2. Create a unique business rule
  const rule_code = `RULE_${RandomGenerator.alphaNumeric(8)}`;
  const ruleInput: IShoppingMallAiBackendBusinessRule.ICreate = {
    rule_code,
    rule_description: RandomGenerator.paragraph()(8),
    enforcement_status: "active",
    reason_for_change: RandomGenerator.paragraph()(3),
    effective_from: new Date().toISOString(),
    effective_to: null,
  };
  const output = await api.functional.shoppingMallAiBackend.admin.businessRules.create(connection, {
    body: ruleInput,
  });
  typia.assert(output);
  // 3. Assert output fields and persistence
  TestValidator.equals("rule_code matches")(output.rule_code)(ruleInput.rule_code);
  TestValidator.equals("rule_description matches")(output.rule_description)(ruleInput.rule_description);
  TestValidator.equals("enforcement_status matches")(output.enforcement_status)(ruleInput.enforcement_status);
  TestValidator.equals("reason_for_change matches")(output.reason_for_change)(ruleInput.reason_for_change);
  TestValidator.equals("effective_from matches")(output.effective_from)(ruleInput.effective_from);
  TestValidator.equals("effective_to matches")(output.effective_to)(ruleInput.effective_to);
  TestValidator.predicate("id is uuid")(output.id.length === 36 && output.id.includes("-"));
  TestValidator.predicate("created_at exists")(!!output.created_at && !isNaN(Date.parse(output.created_at)));
  TestValidator.predicate("updated_at exists")(!!output.updated_at && !isNaN(Date.parse(output.updated_at)));

  // 4. Audit-related property check (id, created_at, updated_at always present, see above)

  // 5. Duplicate rule_code should be rejected
  await TestValidator.error("creating rule with duplicate code should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.businessRules.create(connection, {
        body: ruleInput,
      });
    },
  );
}

