import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate an active, valid seller JWT token with the /auth/seller/validate endpoint.
 *
 * This test ensures the following end-to-end flow:
 * 1. A seller registers with complete, required details to acquire a seller account.
 * 2. The newly registered seller logs in with their credentials to obtain a valid JWT token. The token is returned in the response and set as the Authorization header for subsequent API requests.
 * 3. The test then calls the /auth/seller/validate endpoint with the active token in the Authorization header.
 * 4. The system must confirm that the token is valid, the status is active, and return the correct identity claims (sellerId, email, status, expiration timestamp).
 * 5. The returned fields are compared to ensure they match what was expected from registration/login. Further, it verifies that valid: true and all data is populated.
 *
 * This test also implies that audit logging for validation event occurs in the backend, although this cannot be directly tested via API response.
 */
export async function test_api_seller_token_validation_success_active_token(connection: api.IConnection) {
  // 1. Register a new seller
  const sellerData: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword123!",
    companyName: RandomGenerator.name(),
    businessNumber: ArrayUtil.repeat(10)(() => String(typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<9>>())).join(""),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  };
  const regResp: ISellerAuth.AuthResponseWithHeaders = await api.functional.auth.seller.register.signUp(connection, { body: sellerData });
  typia.assert(regResp);
  TestValidator.equals("email matches")(regResp.email)(sellerData.email);
  TestValidator.equals("company name matches")(regResp.companyName)(sellerData.companyName);
  TestValidator.equals("business number matches")(regResp.businessNumber)(sellerData.businessNumber);

  // 2. Login as the newly registered seller
  const loginResp: ISellerAuth.AuthResponse = await api.functional.auth.seller.login.signIn(connection, { body: { email: sellerData.email, password: sellerData.password } });
  typia.assert(loginResp);
  TestValidator.equals("email matches")(loginResp.email)(sellerData.email);
  TestValidator.equals("sellerId matches")(loginResp.sellerId)(regResp.sellerId);

  // 3. JWT token should be set in connection after login; call validate endpoint
  const validateResp: ISellerAuth.ValidateTokenResponse = await api.functional.auth.seller.validate.validateToken(connection);
  typia.assert(validateResp);
  TestValidator.equals("token is valid")(validateResp.valid)(true);
  TestValidator.equals("sellerId matches")(validateResp.sellerId)(regResp.sellerId);
  TestValidator.equals("email matches")(validateResp.email)(regResp.email);
  TestValidator.equals("status matches")(validateResp.status)(regResp.status);
  TestValidator.predicate("expiresAt is ISO string")(typeof validateResp.expiresAt === "string" && !isNaN(Date.parse(validateResp.expiresAt)));
  // NOTE: Audit log verification must be conducted via system backend as API does not expose it.
}

