import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachment";
import type { IShoppingMallAiBackendAttachmentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachmentLog";

/**
 * Validate hard deletion of an attachment log as an admin and confirm post-deletion inaccessibility and error handling.
 *
 * This test ensures that deleting an attachment log as an admin truly erases the log entry (hard delete semantics), that it can't be fetched or deleted again afterwards, that compliance/audit chains are respected, and that only applicable log/attachment relationships are affected. It also tests that the API enforces admin-only access and properly handles error cases around already-deleted, non-existent, or cross-attachment log deletion attempts. The flow covers both happy-path and error-path conditions, based strictly on available API surface.
 *
 * 1. Register an attachment (dependency)
 * 2. Create a log entry for that attachment (dependency)
 * 3. As admin, delete the specific log via its attachmentId and logId
 * 4. Attempt to delete the same log again and expect error
 * 5. Attempt to delete a non-existent log (random UUID) and expect error
 * 6. Register another attachment and log; then attempt to delete that log using the first attachment's ID (cross-attachment error); expect error
 */
export async function test_api_attachment_log_hard_delete_and_post_delete_access(connection: api.IConnection) {
  // 1. Register the first attachment
  const attachment = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, {
    body: {
      owner_id: typia.random<string & tags.Format<"uuid">>(),
      owner_type: "admin",
      file_name: RandomGenerator.alphaNumeric(16),
      file_size: 1024,
      mime_type: "application/pdf",
      storage_uri: `file://${RandomGenerator.alphaNumeric(24)}`,
      hash_sha256: RandomGenerator.alphaNumeric(64),
      uploaded_at: new Date().toISOString(),
      // Optional: expire_at, description omitted for baseline case
    } satisfies IShoppingMallAiBackendAttachment.ICreate
  });
  typia.assert(attachment);

  // 2. Create a log entry for that attachment
  const log = await api.functional.shoppingMallAiBackend.admin.attachments.logs.create(connection, {
    attachmentId: attachment.id,
    body: {
      event_type: "upload",
      ip_address: "127.0.0.1",
      event_at: new Date().toISOString()
      // operated_by_admin_id, event_context: omitted for default case
    } satisfies IShoppingMallAiBackendAttachmentLog.ICreate
  });
  typia.assert(log);

  // 3. Delete the log as admin (happy path)
  await api.functional.shoppingMallAiBackend.admin.attachments.logs.erase(connection, {
    attachmentId: attachment.id,
    attachmentLogId: log.id
  });

  // 4. Attempt to delete the same log again – must fail (already-deleted)
  await TestValidator.error("already deleted log should error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.attachments.logs.erase(connection, {
      attachmentId: attachment.id,
      attachmentLogId: log.id
    });
  });

  // 5. Attempt to delete a non-existent log (random UUID)
  await TestValidator.error("non-existent log should error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.attachments.logs.erase(connection, {
      attachmentId: attachment.id,
      attachmentLogId: typia.random<string & tags.Format<"uuid">>()
    });
  });

  // 6. Register a second attachment and create another log
  const otherAttachment = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, {
    body: {
      owner_id: typia.random<string & tags.Format<"uuid">>(),
      owner_type: "admin",
      file_name: RandomGenerator.alphaNumeric(16),
      file_size: 2048,
      mime_type: "application/pdf",
      storage_uri: `file://${RandomGenerator.alphaNumeric(24)}`,
      hash_sha256: RandomGenerator.alphaNumeric(64),
      uploaded_at: new Date().toISOString()
    } satisfies IShoppingMallAiBackendAttachment.ICreate
  });
  typia.assert(otherAttachment);

  const otherLog = await api.functional.shoppingMallAiBackend.admin.attachments.logs.create(connection, {
    attachmentId: otherAttachment.id,
    body: {
      event_type: "upload",
      ip_address: "127.0.0.1",
      event_at: new Date().toISOString()
    } satisfies IShoppingMallAiBackendAttachmentLog.ICreate
  });
  typia.assert(otherLog);

  // 7. Try to delete the second log using the first attachment's ID – must error (wrong attachment–log pair)
  await TestValidator.error("cross-attachment log deletion must error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.attachments.logs.erase(connection, {
      attachmentId: attachment.id,
      attachmentLogId: otherLog.id
    });
  });
}

