/**
 * Validate paginated and filtered search of product search keywords by admin
 *
 * This test covers the end-to-end workflow for an admin to search and filter keywords attached to a specific product. 
 * The process ensures that pagination and keyword-based filtering operate as intended, and validates business logic for keyword assignment and retrieval.
 *
 * Steps:
 * 1. Create a new product as a test target (with a valid seller).
 * 2. Attach multiple search keywords to the product.
 * 3. Search all keywords for this product with pagination (e.g., limit=2, page=1).
 * 4. For each keyword, perform a filtered search by partial or exact search_keyword.
 * 5. Confirm that the results match the expected keyword entries.
 * 6. Check that pagination returns the correct amount and structure.
 */
export async function test_api_product_search_keyword_search_by_admin(connection: api.IConnection) {
  // 1. Create a product to attach keywords
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(),
      status: "published",
      main_image_uri: null,
    },
  });
  typia.assert(product);

  // 2. Attach multiple keywords to the product
  const keywords = [
    "laptop",
    "gaming laptop",
    "ultrabook",
    "notebook",
    "touchscreen laptop"
  ];
  const createdKeywords = [];
  for (const keyword of keywords) {
    const kw = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.createProductSearchKeyword(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        search_keyword: keyword,
      },
    });
    typia.assert(kw);
    createdKeywords.push(kw);
  }

  // 3. Search all keywords for this product with pagination (limit=2, page=1)
  const page1 = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.searchProductSearchKeywords(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      page: 1,
      limit: 2,
    },
  });
  typia.assert(page1);
  TestValidator.equals("Pagination limit 2")(page1.pagination.limit)(2);
  TestValidator.equals("Pagination page 1")(page1.pagination.current)(1);
  TestValidator.predicate("Should have data")(Array.isArray(page1.data) && page1.data.length > 0);

  // 4. Search for each keyword using filter by search_keyword (partial/exact)
  for (const keyword of keywords) {
    const filtered = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.searchProductSearchKeywords(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        search_keyword: keyword.substr(0, 3), // partial match test
      },
    });
    typia.assert(filtered);
    TestValidator.predicate("Should find at least one matching keyword")(
      filtered.data.some(k => k.search_keyword.includes(keyword.substr(0, 3)))
    );
  }

  // 5. Check that all created keywords are present in the unfiltered (full) result
  const fullList = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.searchProductSearchKeywords(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      limit: 100,
      page: 1,
    },
  });
  typia.assert(fullList);
  for (const keyword of keywords) {
    TestValidator.predicate(`Full list should include '${keyword}'`)(
      fullList.data.some(k => k.search_keyword === keyword)
    );
  }
