import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for updating categories via admin API, covering valid update, duplicate code, permission denied, not found, and invalid parent checks.
 *
 * Steps:
 * 1. Register an admin user and save adminId.
 * 2. Register a second admin user (for later non-admin permission check).
 * 3. Create a root category (catA) as admin1.
 * 4. Create a second category (catB, can be used for duplicate code / as target for parent reparenting).
 * 5. Update catA's name as admin1 and verify the response updated.
 * 6. Update catA with catB's code (should error: duplicate).
 * 7. Update random (non-existent) categoryId (should error: not found).
 * 8. Try to update catA as admin2 (should error: permission denied or not found).
 * 9. Try to set catA's parent_id to a non-existent category (should error: invalid parent).
 * 10. Try cyclic parenting by setting catB's parent_id to catA (should succeed if valid, else error). Validate integrity.
 */
export async function test_api_category_update_valid_invalid_permission_and_conflict(connection: api.IConnection) {
  // 1. Register two admin users
  const adminEmail1 = typia.random<string & tags.Format<"email">>();
  const adminEmail2 = typia.random<string & tags.Format<"email">>();
  const admin1 = await api.functional.auth.admin.register.signUp(connection, { body: { email: adminEmail1, password: "1234" }});
  typia.assert(admin1);
  const admin2 = await api.functional.auth.admin.register.signUp(connection, { body: { email: adminEmail2, password: "1234" }});
  typia.assert(admin2);

  // 2. Create category catA
  const catAInput = {
    code: "code-catA",
    name: "Category A",
    created_by_admin_id: admin1.adminId,
    parent_id: null,
    display_order: 1,
    visible: true
  } satisfies IShoppingMallAiBackendCategory.ICreate;
  const catA = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, { body: catAInput });
  typia.assert(catA);

  // 3. Create category catB
  const catBInput = {
    code: "code-catB",
    name: "Category B",
    created_by_admin_id: admin1.adminId,
    parent_id: null,
    display_order: 2,
    visible: true
  } satisfies IShoppingMallAiBackendCategory.ICreate;
  const catB = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, { body: catBInput });
  typia.assert(catB);

  // 4. Update catA's name
  const updatedName = "Category A Updated";
  const updateA = await api.functional.shoppingMallAiBackend.admin.categories.updateCategory(connection, {
    categoryId: catA.id,
    body: { name: updatedName }
  });
  typia.assert(updateA);
