 * 2. Retrieve first page (defaults) and validate structure and pagination
 * 3. Apply filter (e.g., by role or status) and check that results respect filter
 * 4. Apply date range filter (joined_from, joined_to) and check results are within range
 * 5. Search with impossible criteria to expect empty result
 * 6. Attempt API as non-admin (JWT not present or invalid) and confirm access denied
 */
export async function test_api_admin_list_search_pagination_and_role_restriction(connection: api.IConnection) {
  // 1. Authenticate as an admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
