  TestValidator.predicate("valid pagination")(!!none.pagination);

  // 6. Access denied for non-admin token
  // Logout or clear Authorization header
  connection.headers.Authorization = undefined;
  await TestValidator.error("access denied for non-admin")(() =>
    api.functional.shoppingMallAiBackend.admin.admins.search(connection, { body: {} })
  );
