import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";

/**
 * Attempt to soft-delete a product review as a user who is NOT the review author, expecting permission denial.
 *
 * Business context:
 * - Only the author (customer) of a product review (or an admin) may soft-delete the review.
 * - Soft delete is done via DELETE /shoppingMallAiBackend/customer/productReviews/{productReviewId}.
 * - Access control must prevent deletion by users who are not the review's owner, returning an error (e.g., permission denied).
 *
 * Test workflow:
 * 1. Create a product review as Customer1 via POST /shoppingMallAiBackend/customer/productReviews.
 *    - Use random UUIDs for product_id and order_item_id as no setup APIs are available.
 *    - Fill all required and relevant optional fields.
 * 2. Attempt to DELETE the created review as Customer2 (simulated; in a real test would re-authenticate, but here, API does not provide customer authentication context).
 * 3. Validate that an authorization/permission error is thrown (error is expected; no error message validation).
 *
 * Notes:
 * - Only real API calls and types from the provided DTOs/functions are used.
 * - Test scenario focuses solely on access control error (do not validate error content, just that error is thrown).
 */
export async function test_api_product_review_customer_soft_delete_other_user_error(
  connection: api.IConnection,
) {
  // 1. Create a product review as Customer1
  const review = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      order_item_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Test review for access control",
      body: "Trying to test soft-delete from a non-author.",
      rating: 5,
      status: "normal",
      ai_sentiment_score: 0.85,
      ai_spam_score: 0.01,
    } satisfies IShoppingMallAiBackendProductReview.ICreate,
  });
  typia.assert(review);

  // 2. Simulate Customer2 context - re-authentication/customer boundaries cannot be performed; API does not support user switching. This is a logical placeholder for a different user.

  // 3. Attempt delete as non-author (Customer2) - must error
  await TestValidator.error("only author can soft-delete review")(() =>
    api.functional.shoppingMallAiBackend.customer.productReviews.erase(connection, {
      productReviewId: review.id,
    })
  );
}

