export async function test_api_compliance_event_update_successful(connection: api.IConnection) {
  // 1. Create a compliance event as a dependency (simulate admin action)
  const originalCreate: IShoppingMallAiBackendComplianceEvent =
    await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
      body: {
        event_type: "policy_update",
