  const newUsedAt = new Date(Date.now() + 1 * 3600000).toISOString(); // 1 hour ahead
  const updateUsed = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.update(connection, {
    issuedCouponId: issued.id,
    body: {
      status: "used",
      used_at: newUsedAt,
    },
  });
