  TestValidator.equals("status updated to used")(updateUsed.status)("used");
  TestValidator.equals("used_at updated")(updateUsed.used_at)(newUsedAt);
  TestValidator.predicate("updated_at advanced")(updateUsed.updated_at > issued.updated_at);

  // 3. Update expires_at to a new date
  const newExpiry = new Date(Date.now() + 21 * 86400000).toISOString(); // 21 days from now
  const updateExpiry = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.update(connection, {
