/**
 * Validate that creating a system setting with a duplicate conf_key fails as expected.
 *
 * This test verifies the business rule that conf_key must be unique across all system settings. It authenticates as an admin (test should use a known/builtin admin), creates a setting with a unique conf_key, then attempts to create another setting using the exact same conf_key. The test expects the API to reject the duplicate attempt and throw an appropriate error for uniqueness violation. Because API surface lacks audit log or direct list, error occurrence is sufficient for validation.
 *
 * Step-by-step:
 * 1. Authenticate as admin using valid credentials (test/builtin credential recommended for real runs).
 * 2. Create a system setting with a unique conf_key.
 * 3. Attempt to create a second setting using the same conf_key (should fail).
 * 4. Confirm that the error occurs and no duplicate is created (by API contract, cannot query all—no listing endpoint).
 */
export async function test_api_system_setting_creation_duplicate_key(
  connection: api.IConnection
) {
  // 1. Authenticate as admin (real test should provide known admin credentials)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "test1234!";
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(adminAuth);

  // 2. Create a unique system setting
  const confKey: string = `confkey_${typia.random<string>()}`;
  const settingInput: IShoppingMallAiBackendSystemSetting.ICreate = {
    conf_key: confKey,
    conf_value: typia.random<string>(),
    description: "E2E system setting creation (unique key)"
  };
  const created = await api.functional.shoppingMallAiBackend.admin.systemSettings.create(connection, {
    body: settingInput
  });
  typia.assert(created);

  // 3. Attempt to create another with the same conf_key (should trigger error)
  const duplicateInput: IShoppingMallAiBackendSystemSetting.ICreate = {
    conf_key: confKey,
    conf_value: typia.random<string>(),
    description: "E2E system setting duplicate key attempt"
  };
  await TestValidator.error("duplicate conf_key should not be allowed")(() =>
    api.functional.shoppingMallAiBackend.admin.systemSettings.create(connection, { body: duplicateInput })
  );
  // 4. No setting list endpoint; cannot verify directly that only one exists. Error is sufficient proof per scenario and spec.
}

