import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that unauthorized or anonymous users cannot update a seller's organization profile.
 *
 * This test ensures that only authenticated owners (correct session) can update their business profile. Any attempt by an unauthenticated actor or a user with invalid credentials must be strictly rejected, and the profile data must not change.
 *
 * Steps:
 * 1. Register (sign up) a true seller to own a seller profile.
 * 2. Attempt to update the profile with a PUT request while **not** authenticated (no token in headers) using the correct seller ID.
 *    - Expect an authorization/authentication error response (should NOT succeed).
 *    - Confirm that no fields are updated.
 * 3. (Edge case) Optionally: Attempt to update the profile using a different/fake seller's token if an authentication API existed. (SKIPPED: not implementable with current functions)
 * 4. (Omitted) Cannot implement audit log readout due to lack of API.
 *
 * Business logic: Unauthorized update attempts must not succeed and must never modify profile data. Attackers or anonymous clients must be blocked by security layer. Test focuses only on what is possible to verify with current API and DTOs.
 */
export async function test_api_seller_update_profile_unauthorized(connection: api.IConnection) {
  // 1. Register the owner seller
  const inputSignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPassword123!",
    companyName: "Acme Corp Unauthorized Test",
    businessNumber: "1234567890",
    representativeName: "Alice Malory",
    address: "100 Test Main Street, Cityville",
    phone: "010-5555-0101"
  } satisfies ISellerAuth.SignUp;
  const reg = await api.functional.auth.seller.register.signUp(connection, {
    body: inputSignUp
  });
  typia.assert(reg);

  // 2. Attempt unauthorized PUT (no authentication header)
  // Remove JWT token from connection.headers if set
  const connWithoutAuth = { ...connection, headers: { ...connection.headers } };
  if (connWithoutAuth.headers?.Authorization) delete connWithoutAuth.headers.Authorization;

  const updatePayload: IShoppingMallAiBackendSeller.IUpdate = {
    id: reg.sellerId,
    company_name: "Hacked Name Should Not Apply"
  };
  await TestValidator.error("unauthenticated update must fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.update(connWithoutAuth, { body: updatePayload });
    }
  );
}

