import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";

/**
 * Validate that an admin can successfully access the full detail of a specific product review by its productReviewId.
 *
 * This test simulates a business, compliance, and moderation workflow in the system:
 * 1. A product review is created by a customer (using the dependency endpoint).
 * 2. The admin fetches the same review in detail using the admin endpoint.
 * 3. The test verifies that the result is accessible and all major fields (author, product, order item, title, body, rating, status, AI moderation metadata, timestamps) match between creation and retrieval.
 * 4. This simulates an admin review detail screen for compliance or dispute/audit contexts.
 */
export async function test_api_product_review_admin_get_detail_success(connection: api.IConnection) {
  // 1. Create a product review as a customer
  const reviewToCreate: IShoppingMallAiBackendProductReview.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    order_item_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Test review for admin detail",
    body: "This is a test review body.",
    rating: 5,
    status: "normal",
    ai_sentiment_score: 0.75,
    ai_spam_score: 0.02,
  };
  const created: IShoppingMallAiBackendProductReview = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, { body: reviewToCreate });
  typia.assert(created);

  // 2. Admin retrieves review by productReviewId
  const fetched: IShoppingMallAiBackendProductReview = await api.functional.shoppingMallAiBackend.admin.productReviews.at(connection, { productReviewId: created.id });
  typia.assert(fetched);

  // 3. Validate all relevant fields match between created and fetched reviews
  TestValidator.equals("review id")(fetched.id)(created.id);
  TestValidator.equals("customer_id")(fetched.customer_id)(created.customer_id);
  TestValidator.equals("product_id")(fetched.product_id)(created.product_id);
  TestValidator.equals("order_item_id")(fetched.order_item_id)(created.order_item_id);
  TestValidator.equals("title")(fetched.title)(created.title);
  TestValidator.equals("body")(fetched.body)(created.body);
  TestValidator.equals("rating")(fetched.rating)(created.rating);
  TestValidator.equals("status")(fetched.status)(created.status);
  TestValidator.equals("ai_sentiment_score")(fetched.ai_sentiment_score)(created.ai_sentiment_score);
  TestValidator.equals("ai_spam_score")(fetched.ai_spam_score)(created.ai_spam_score);
  TestValidator.predicate("created_at exists")(
    typeof fetched.created_at === "string" && fetched.created_at.length > 0
  );
  TestValidator.predicate("updated_at exists")(
    typeof fetched.updated_at === "string" && fetched.updated_at.length > 0
  );
  // deleted_at is optional/null for a normal fresh review
  TestValidator.equals("deleted_at should be null")(fetched.deleted_at)(null);
}

