import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSnapshot";
import type { IPageIShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching product snapshot history as an admin with filters, pagination, edge and error cases
 *
 * This test function verifies that an admin can search product snapshot histories using various advanced search filters and options, including type, status, code, date range, as well as pagination and sorting. It also exercises business edge and error scenarios, such as searching snapshots for a deleted or non-existent product.
 *
 * Steps:
 * 1. Admin creates a product
 * 2. Admin creates several product snapshots with diverse attributes (type, status, code, timestamp)
 * 3. Search snapshots for the product with no filters, and verify all snapshots are returned
 * 4. Search with single and combined filters (snapshot_type, status, snapshot_code, date ranges, name) and assert outputs match criteria
 * 5. Test pagination logic, assert data window and empty page after consuming all data
 * 6. Test sorting logic via order_by/order_dir
 * 7. Simulate soft delete on product (manually set deleted_at) and check error/empty for snapshot search
 * 8. Attempt snapshot search with a fake/invalid productId, expect not found/error
 * 9. Validate uniqueness and filter edge with a uniquely coded snapshot
 */
export async function test_api_product_snapshot_search_with_permissions_and_filters_admin(connection: api.IConnection) {
  // 1. Admin creates a product
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.content()()(),
    main_image_uri: null,
    status: "published",
  };
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, { body: productInput });
  typia.assert(product);
  const productId = product.id;

  // 2. Admin creates diverse product snapshots
  const now = new Date();
  const snapshotVariants = [
    { code: "v1-create", type: "created", name: product.name, status: "published", delta: 0 },
    { code: "v2-edit", type: "modified", name: product.name + " update1", status: "published", delta: 60 },
    { code: "v3-status", type: "status_update", name: product.name + " updated2", status: "suspended", delta: 120 },
    { code: "v4-publish", type: "published", name: product.name + " repub", status: "published", delta: 180 },
    { code: "v5-special", type: "special-type", name: "Unique Edge Case", status: "draft", delta: 240 },
  ];

  const snapshots: IShoppingMallAiBackendProductSnapshot[] = [];
  for (const variant of snapshotVariants) {
    const createdAt = new Date(now.getTime() + variant.delta * 1000).toISOString();
    const snap = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.create(connection, {
      productId,
      body: {
        product_id: productId,
        snapshot_code: variant.code,
        snapshot_type: variant.type,
        name: variant.name,
        description: RandomGenerator.paragraph()(1),
        main_image_uri: null,
        status: variant.status,
      } satisfies IShoppingMallAiBackendProductSnapshot.ICreate,
    });
    typia.assert(snap);
    // Patch in custom created_at for search filtering (simulate varied creation times)
    // This assumes that the API under test allows test data to be visible with correct created_at. If not, test boundary conditions with actual returned created_at.
    (snap as any).created_at = createdAt;
    snapshots.push(snap);
  }

  // Helper: Find expected snapshots by filter
  const filterSnapshots = (filters: Partial<IShoppingMallAiBackendProductSnapshot.IRequest>) => {
    return snapshots.filter((snap) => {
      if (filters.snapshot_code && snap.snapshot_code !== filters.snapshot_code) return false;
      if (filters.snapshot_type && snap.snapshot_type !== filters.snapshot_type) return false;
      if (filters.name && snap.name !== filters.name) return false;
      if (filters.status && snap.status !== filters.status) return false;
      if (filters.created_at_from && snap.created_at < filters.created_at_from) return false;
      if (filters.created_at_to && snap.created_at > filters.created_at_to) return false;
      return true;
    });
  };

  // 3. Search snapshots for the product with no filters
  {
    const searchRes = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
      productId,
      body: {
        product_id: productId,
      },
    });
    typia.assert(searchRes);
    // All snapshots should appear
    TestValidator.equals("snapshot count")(searchRes.data.length)(snapshots.length);
    // Check IDs consistency
    const expectedIds = snapshots.map((snap) => snap.id).sort();
    const resIds = searchRes.data.map((it) => it.id).sort();
    TestValidator.equals("snapshot IDs")(resIds)(expectedIds);
  }

  // 4. Search with each filter and combined filters
  // snapshot_type
  for (const v of snapshotVariants) {
    const searchRes = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
      productId,
      body: { product_id: productId, snapshot_type: v.type },
    });
    typia.assert(searchRes);
    const expected = filterSnapshots({ snapshot_type: v.type });
    TestValidator.equals(`filtered by type(${v.type})`)(searchRes.data.length)(expected.length);
    TestValidator.predicate(`type match all snapshots filtered`) (
      searchRes.data.every((snap) => snap.snapshot_type === v.type)
    );
  }
  // status
  const uniqueStatuses = [...new Set(snapshotVariants.map((v) => v.status))];
  for (const status of uniqueStatuses) {
    const searchRes = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
      productId,
      body: { product_id: productId, status },
    });
    typia.assert(searchRes);
    const expected = filterSnapshots({ status });
    TestValidator.equals(`filtered by status(${status})`)(searchRes.data.length)(expected.length);
    TestValidator.predicate(`status match all snapshots filtered`) (
      searchRes.data.every((snap) => snap.status === status)
    );
  }
  // snapshot_code
  for (const v of snapshotVariants) {
    const searchRes = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
      productId,
      body: { product_id: productId, snapshot_code: v.code },
    });
    typia.assert(searchRes);
    const expected = filterSnapshots({ snapshot_code: v.code });
    TestValidator.equals(`filtered by code(${v.code})`)(searchRes.data.length)(expected.length);
    TestValidator.predicate(`code match all snapshots filtered`) (
      searchRes.data.every((snap) => snap.snapshot_code === v.code)
    );
  }
  // Date ranges
  {
    // Get the earliest and latest created_at
    const sorted = [...snapshots].sort((a, b) => a.created_at.localeCompare(b.created_at));
    const from = sorted[1].created_at;
    const to = sorted[3].created_at;
    const filterReq = { product_id: productId, created_at_from: from, created_at_to: to };
    const searchRes = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
      productId,
      body: filterReq,
    });
    typia.assert(searchRes);
    const expected = filterSnapshots({ created_at_from: from, created_at_to: to });
    TestValidator.equals("date range filtered count")(searchRes.data.length)(expected.length);
  }
  // Name field
  for (const v of snapshotVariants) {
    const searchRes = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
      productId,
      body: { product_id: productId, name: v.name },
    });
    typia.assert(searchRes);
    const expected = filterSnapshots({ name: v.name });
    TestValidator.equals(`filtered by name(${v.name})`)(searchRes.data.length)(expected.length);
    TestValidator.predicate(`name match all snapshots filtered`) (
      searchRes.data.every((snap) => snap.name === v.name)
    );
  }
  // Combined filter: status + type
  {
    const v = snapshotVariants[1];
    const searchRes = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
      productId,
      body: { product_id: productId, status: v.status, snapshot_type: v.type },
    });
    typia.assert(searchRes);
    const expected = filterSnapshots({ status: v.status, snapshot_type: v.type });
    TestValidator.equals("combined filter count")(searchRes.data.length)(expected.length);
  }

  // 5. Pagination logic: limit = 2, multiple pages
  {
    const total = snapshots.length;
    const limit = 2;
    let seen: string[] = [];
    for (let page = 1; page <= Math.ceil(total / limit) + 1; page++) {
      const searchRes = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
        productId,
        body: { product_id: productId, page, limit },
      });
      typia.assert(searchRes);
      const paginated = snapshots.slice((page - 1) * limit, page * limit);
      if (page > Math.ceil(total / limit)) {
        TestValidator.equals("empty last page")(searchRes.data.length)(0);
      } else {
        TestValidator.equals(`paged count page=${page}`)(searchRes.data.length)(paginated.length);
        for (const snap of searchRes.data) {
          if (seen.includes(snap.id))
            throw new Error("Duplicate snapshot across pages");
          seen.push(snap.id);
        }
      }
    }
  }

  // 6. Sorting logic: order_by name ascending/descending
  {
    for (const [order_by, order_dir] of [["name", "asc"], ["name", "desc"], ["created_at", "asc"], ["created_at", "desc"]]) {
      const searchRes = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
        productId,
        body: { product_id: productId, order_by, order_dir },
      });
      typia.assert(searchRes);
      const sortField = order_by as keyof IShoppingMallAiBackendProductSnapshot;
      const received = searchRes.data.map((it) => it[sortField]);
      const reference = [...received].sort((a, b) => order_dir === "asc" ? (a > b ? 1 : -1) : (a < b ? 1 : -1));
      TestValidator.equals(`order ${order_by} ${order_dir}`)(received)(reference);
    }
  }

  // 7. Simulate soft delete product (patch deleted_at) and check search error/empty
  {
    const deleted_product_id = typia.random<string & tags.Format<"uuid">>();
    // Simulate by searching for a non-existent (soft-deleted) productId
    const searchRes = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
      productId: deleted_product_id,
      body: { product_id: deleted_product_id },
    });
    typia.assert(searchRes);
    TestValidator.equals("search on deleted/nonexistent product")(searchRes.data.length)(0);
  }

  // 8. Invalid productId (obviously fake/invalid uuid)
  await TestValidator.error("snapshot search with invalid productId throws") (async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
      productId: "not-a-uuid" as any,
      body: { product_id: "not-a-uuid" as any },
    });
  });

  // 9. Uniqueness & filter edge: unique snapshot
  {
    const special = snapshots.find((s) => s.code === "v5-special" || s.snapshot_code === "v5-special");
    if (special) {
      const searchRes = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.search(connection, {
        productId,
        body: { product_id: productId, snapshot_code: special.snapshot_code, snapshot_type: special.snapshot_type },
      });
      typia.assert(searchRes);
      TestValidator.equals("unique edge filter count")(searchRes.data.length)(1);
      TestValidator.equals("unique edge id")(searchRes.data[0].id)(special.id);
    }
  }
}

