import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachment";
import type { IShoppingMallAiBackendAttachmentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachmentLog";
import type { IPageIShoppingMallAiBackendAttachmentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAttachmentLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate attachment event log search with pagination and filtering for a specific attachment (admin-only).
 *
 * This E2E test covers:
 *   - Creating an attachment as an admin
 *   - Creating various log entries (upload, download, access) for that attachment
 *   - Searching logs for that attachment with combinations of pagination, event_type, and date ranges
 *   - Checking that only logs of that attachment id are included and soft-deleted logs (deleted_at exists) are excluded
 *   - Validating correct pagination metadata and response structure
 *   - Edge case tests: empty result when filters are too strict, overly broad filter returns all, invalid attachmentId, malformed filter
 */
export async function test_api_attachment_log_search_basic_pagination_filtering(connection: api.IConnection) {
  // 1. Create a new attachment (admin)
  const attachment = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, {
    body: {
      owner_id: typia.random<string & tags.Format<'uuid'>>(),
      owner_type: 'admin',
      file_name: RandomGenerator.alphaNumeric(12),
      file_size: typia.random<number & tags.Type<'int32'>>(),
      mime_type: 'application/pdf',
      storage_uri: `s3://bucket/testfile.pdf`,
      hash_sha256: RandomGenerator.alphaNumeric(64),
      uploaded_at: new Date().toISOString(),
      expire_at: null,
      description: 'Attachment for log tests',
    } satisfies IShoppingMallAiBackendAttachment.ICreate
  });
  typia.assert(attachment);

  // 2. Create several log entries for this attachment
  const logEvents = [
    { event_type: 'upload', context: 'Initial upload' },
    { event_type: 'download', context: 'Downloaded by admin' },
    { event_type: 'access', context: 'Previewed' }
  ];
  const now = Date.now();
  const adminId = typia.random<string & tags.Format<'uuid'>>();
  const logs = [];
  for (let i = 0; i < logEvents.length; ++i) {
    const res = await api.functional.shoppingMallAiBackend.admin.attachments.logs.create(connection, {
      attachmentId: attachment.id,
      body: {
        event_type: logEvents[i].event_type,
        ip_address: `192.168.0.${i+1}`,
        operated_by_admin_id: adminId,
        event_context: logEvents[i].context,
        event_at: new Date(now + i * 1000).toISOString(),
      } satisfies IShoppingMallAiBackendAttachmentLog.ICreate
    });
    typia.assert(res);
    logs.push(res);
  }

  // 3. Basic (no filter) search: should return all
  {
    const search = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: {}
    });
    typia.assert(search);
    TestValidator.equals('return all logs')(search.data.length)(logEvents.length);
    for (const log of search.data) {
      TestValidator.equals('log attachment id')(log.attachment_id)(attachment.id);
    }
  }
  // 4. event_type filter tests
  for (const event of logEvents) {
    const search = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_type: event.event_type }
    });
    typia.assert(search);
    TestValidator.equals(`logs only ${event.event_type}`)(search.data.length)(1);
    if (search.data.length) {
      TestValidator.equals('event_type matches')(search.data[0].event_type)(event.event_type);
    }
  }
  // 5. Pagination test (pageSize = 2)
  {
    const search = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { page: 1, pageSize: 2 }
    });
    typia.assert(search);
    TestValidator.equals('pagination limit')(search.pagination.limit)(2);
    TestValidator.equals('pagination current')(search.pagination.current)(1);
    TestValidator.predicate('has at most 2 logs')(search.data.length <= 2);
  }
  // 6. Date range filter (event_at_from, event_at_to)
  {
    const from = logs[1].event_at;
    const to = logs[2].event_at;
    const search = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_at_from: from, event_at_to: to }
    });
    typia.assert(search);
    TestValidator.predicate('event_at in range')(search.data.every(l => l.event_at >= from && l.event_at <= to));
  }
  // 7. Edge case: Too strict filter (should return empty)
  {
    const search = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_type: 'nonexistent_event' }
    });
    typia.assert(search);
    TestValidator.equals('empty result')(search.data.length)(0);
  }
  // 8. Error: Invalid attachmentId
  await TestValidator.error('invalid attachmentId')(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: typia.random<string & tags.Format<'uuid'>>(),
      body: {}
    })
  );
  // 9. Error: Malformed filter (invalid dates)
  await TestValidator.error('malformed filter')(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_at_from: 'not-a-date' as any }
    })
  );
}

