/**
 * Test successful admin logout workflow and session invalidation.
 *
 * Validates that an authenticated admin can log out, their JWT is invalidated, and further access with the same token is rejected. Also ensures appropriate audit logging.
 *
 * Business process in detail:
 * 1. Register a new admin account via POST /auth/admin/register
 * 2. Log in as admin via POST /auth/admin/login to get a valid JWT (token is stored in connection.headers.Authorization)
 * 3. Perform logout via POST /auth/admin/logout
 * 4. Validate the signOut result (success: true)
 * 5. Attempt to call an authorized endpoint with the same JWT - expect authorization failure (error thrown)
 *    - We will test this by re-invoking /auth/admin/logout with the same token, which should now fail.
 * 6. (Business requirement) Confirm that audit log entries for logout are created - NOT IMPLEMENTED as no API is provided for this.
 */
export async function test_api_admin_auth_logout_success(connection: api.IConnection) {
  // 1. Register new admin
  const signUpInput: IAdminAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Test1234!@#" // Simple deterministic password for test repeatability
  };
  const registerOutput: IAdminAuth.JwtWithProfile = await api.functional.auth.admin.register.signUp(connection, {
    body: signUpInput,
  });
  typia.assert(registerOutput);
  TestValidator.equals("admin email matches")(registerOutput.email)(signUpInput.email);

  // 2. Log in as the new admin (optional - registration already issues a token, but we test both paths)
  const loginOutput: IAdminAuth.JwtWithProfile = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: signUpInput.email,
      password: signUpInput.password,
    },
  });
  typia.assert(loginOutput);
  TestValidator.equals("admin email matches after login")(loginOutput.email)(signUpInput.email);

  // 3. Perform logout via POST /auth/admin/logout
  const logoutResult: IAdminAuth.SignOutResult = await api.functional.auth.admin.logout.signOut(connection);
  typia.assert(logoutResult);
  TestValidator.equals("logout succeeded")(logoutResult.success)(true);

  // 4. Try using the same JWT again - must be rejected (simulate by retrying /auth/admin/logout)
  await TestValidator.error("should not be able to reuse token after logout")(
    async () => {
      await api.functional.auth.admin.logout.signOut(connection);
    },
  );

  // NOTE: Audit log entry confirmation skipped (no audit log API in test scope).
}

