import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test successful admin logout workflow and session invalidation.
 *
 * This test validates that an authenticated admin can successfully log out, their session (JWT) is invalidated, and any further access with the same token is rejected. 
 * 
 * Business workflow:
 * 1. Register a new admin via POST /auth/admin/register
 * 2. Log in as the new admin via POST /auth/admin/login to receive/latest JWT (even though registration issues one, tests both flows)
 * 3. Perform logout with POST /auth/admin/logout
 * 4. Confirm the logout result is successful
 * 5. Attempt to call an authenticated endpoint again with the same JWT – this should now fail with an error
 *
 * Notes:
