 * 1. Create a product review (as prerequisite, as if submitted immediately post-purchase).
 * 2. Simulate the passage of time so that the edit window is expired (this is done implicitly as we cannot manipulate time, assuming the backend rejects based on policy).
 * 3. Attempt to update the review's content (e.g., body, rating).
 * 4. Confirm the API responds with a clear error and does not allow the update to go through.
 */
export async function test_api_product_review_customer_update_after_window_error(connection: api.IConnection) {
  // 1. Create a new product review (dependency setup)
  const reviewCreate: IShoppingMallAiBackendProductReview = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      order_item_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Initial review title",
      body: "Initial review body content.",
      rating: 5,
      status: "normal",
      ai_sentiment_score: 0.9,
      ai_spam_score: 0.01
    } satisfies IShoppingMallAiBackendProductReview.ICreate
  });
  typia.assert(reviewCreate);

  // 2. Attempt to update the review after the (simulated) edit window is expired
  // (We do not actually wait, but expect backend to enforce the policy.)
  await TestValidator.error("should not allow update after edit window")(
