  const adminPassword = "ValidPassword123!";
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 2. Generate a random (definitely non-existent) coupon usage UUID.
