  // 3 & 4. Attempt to fetch and expect a 404 error.
  await TestValidator.error("should 404 for missing coupon usage")(() =>
    api.functional.shoppingMallAiBackend.admin.couponUsages.at(connection, {
      couponUsageId: fakeCouponUsageId,
    })
  );
  // 5. Note: audit logging should be validated by backend/log aggregator, not E2E.
