import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendComplianceEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceEvent";
import type { IShoppingMallAiBackendComplianceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceSnapshot";

/**
 * Validates that an admin can update the metadata or evidence payload of a compliance snapshot.
 *
 * Business Context:
 * - Compliance snapshots are attached to compliance events for audit, regulatory, and forensic traceability.
 * - Only admins are permitted to create compliance events/snapshots and update them.
 * - All changes must be logged and evidence payloads are usually immutable unless update is explicitly permitted.
 *
 * Test Workflow:
 * 1. Create a compliance event as an admin.
 * 2. Create a compliance snapshot under the event.
 * 3. Update the compliance snapshot using the update API, modifying allowed metadata or evidence fields.
 * 4. Validate the response reflects the updated metadata and, unless permitted, verify core evidence payloads are properly handled.
 * 5. Confirm type structure and field constraints on the returned snapshot.
 */
export async function test_api_compliance_event_snapshot_update_success(connection: api.IConnection) {
  // Step 1: Admin creates a compliance event
  const complianceEvent = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
    body: {
      event_type: "policy_update",
      actor_id: null, // System-initiated demo
      actor_type: "admin",
      target_type: "order",
      target_id: typia.random<string & tags.Format<"uuid">>(),
      event_payload: JSON.stringify({ policy: "returns", old: "7d", new: "30d" })
    } satisfies IShoppingMallAiBackendComplianceEvent.ICreate
  });
  typia.assert(complianceEvent);

  // Step 2: Admin attaches a compliance snapshot to the event
  const originalPayload = JSON.stringify({ orderId: typia.random<string & tags.Format<"uuid">>(), previousState: "pending", newState: "shipped" });
  const complianceSnapshot = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.create(connection, {
    complianceEventId: complianceEvent.id,
    body: {
      compliance_event_id: complianceEvent.id,
      entity_type: "order",
      entity_id: complianceEvent.target_id!,
      snapshot_payload: originalPayload,
    } satisfies IShoppingMallAiBackendComplianceSnapshot.ICreate
  });
  typia.assert(complianceSnapshot);

  // Step 3: Admin updates compliance snapshot (e.g., corrects the entity type or adds more detail to the payload)
  const updatePayload: IShoppingMallAiBackendComplianceSnapshot.IUpdate = {
    entity_type: "order_v2",
    entity_id: complianceEvent.target_id!,
    snapshot_payload: JSON.stringify({ orderId: typia.random<string & tags.Format<"uuid">>(), previousState: "pending", newState: "delivered", annotation: "corrected due to audit finding" })
  };

  const updatedSnapshot = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.update(connection, {
    complianceEventId: complianceEvent.id,
    complianceSnapshotId: complianceSnapshot.id,
    body: updatePayload,
  });
  typia.assert(updatedSnapshot);

  // Step 4: Validate that the update reflected the changes
  TestValidator.equals("entity_type updated")(updatedSnapshot.entity_type)(updatePayload.entity_type);
  TestValidator.equals("entity_id matches")(updatedSnapshot.entity_id)(updatePayload.entity_id);
  TestValidator.equals("snapshot_payload updated")(updatedSnapshot.snapshot_payload)(updatePayload.snapshot_payload);
  TestValidator.equals("compliance_event_id remains the same")(updatedSnapshot.compliance_event_id)(complianceEvent.id);

  // Audit: Confirm that only admin can perform update (cannot truly test non-admin here due to SDK limitations)
}

