 *
 * This test ensures that when an admin user attempts to delete a comment (using the admin endpoint) but supplies random/invalid UUIDs for both the articleId and commentId (thus, the resource does not exist), the API responds with a proper 404 Not Found error. This is necessary for compliance and auditing, to confirm the API never misreports success or gives non-standard error output.
 *
 * Business rationale: Regulatory or audit requirements frequently demand all destructive operations (such as deletion of comments) must return clearly distinguishable error signals for absent resources. This has critical implications for log reviews, abuse handling, and automated compliance. Therefore, it is essential to ensure that the endpoint fulfills these semantic assurances.
 *
 * Step-by-step process:
 * 1. Authenticate as an admin user if such authentication is required by the API (not handled here as no auth step or dependency was specified).
 * 2. Attempt to delete a comment with randomly generated UUIDs for both articleId and commentId that do not correspond to any existing article or comment in the system.
 * 3. Assert that an error is thrown (404 Not Found), which is a correct behavior for a non-existent resource deletion attempt. No additional validation of output payload is possible since error details/schema are not specified, but presence of error fulfills compliance and negative scenario guarantee.
 */
export async function test_api_article_comment_delete_not_found(connection: api.IConnection) {
  // Step 1: Construct random UUIDs for non-existent article and comment
  const articleId = typia.random<string & tags.Format<"uuid">>();
  const commentId = typia.random<string & tags.Format<"uuid">>();

  // Step 2: Attempt the delete operation and ensure it returns Not Found
  await TestValidator.error("Deleting non-existent comment should return 404")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.articles.comments.erase(connection, {
        articleId,
        commentId
      });
    }
  );
}

