import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import type { IPageIShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendMileageTransaction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates admin paginated & filtered search of mileage transactions in a mileage wallet.
 *
 * This test ensures that:
 * - Admin can create a mileage wallet for a test customer.
 * - Admin can add multiple transactions (accrual, redeem, correction, etc) to the wallet successfully.
 * - Admin can view all transactions using PATCH /shoppingMallAiBackend/admin/mileageWallets/{mileageWalletId}/mileageTransactions, unfiltered and with filters (type, amount, date) with proper pagination.
 * - Filters for transaction type, amount range, and date work as expected, returning only matching transactions.
 * - The list returned is paginated and each page contains the expected number of records.
 * - All inserted transaction types are visible and searchable by type.
 *
 * Test Steps:
 * 1. Admin creates a test customer_id (random UUID)
 * 2. Admin creates a mileage wallet for this customer
 * 3. Admin adds multiple transactions of various types ("accumulate", "redeem", "correction") with different amounts and dates
 * 4. Admin searches all transactions (unfiltered), checks that all data is present
 * 5. For each transaction type, filters by type and asserts only type-matching entries are returned
 * 6. Filters by min/max amount and by date to verify results are correct
 * 7. Asserts pagination (first page, page size, total records, total pages, etc.)
 * 8. Verifies that all admin operations succeed and data integrity is preserved
 */
export async function test_api_mileage_transaction_search_admin_scope(connection: api.IConnection) {
  // 1. Create a random customer ID
  const customerId = typia.random<string & tags.Format<"uuid">>();

  // 2. Admin creates the mileage wallet
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: customerId,
      wallet_program: "brand",
      wallet_status: "active",
      wallet_label: "Test Wallet",
      security_code: null,
    },
  });
  typia.assert(wallet);

  // 3. Admin creates multiple transactions of different types and values, with different creation dates
  const types = ["accumulate", "redeem", "correction"];
  const now = new Date();
  const transactions = [];
  for (let i = 0; i < 9; ++i) {
    const type = types[i % types.length];
    const amount = (i + 1) * 100 * (type === "redeem" ? -1 : 1); // redeem is negative
    const createdAt = new Date(now.getTime() - i * 24 * 3600 * 1000).toISOString();
    const txn = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(connection, {
      mileageWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        transaction_type: type,
        mileage_amount: amount,
        reference_id: null,
        transaction_reason: `${type} test transaction`,
      },
    });
    typia.assert(txn);
    transactions.push({ ...txn, forced_type: type, forced_amount: amount, forced_createdAt: createdAt });
  }

  // 4. List all transactions with no filters
  let pageSize = 5;
  const unfiltered = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.search(connection, {
    mileageWalletId: wallet.id,
    body: {
      page: 1,
      page_size: pageSize,
    },
  });
  typia.assert(unfiltered);
  TestValidator.predicate("unfiltered data includes all stored txns")(
    unfiltered.pagination.records >= transactions.length
  );

  // 5. Filter by each transaction type; assert only that type returned
  for (const type of types) {
    const filtered = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.search(connection, {
      mileageWalletId: wallet.id,
      body: {
        transaction_type: type,
        page: 1,
        page_size: pageSize,
      },
    });
    typia.assert(filtered);
    TestValidator.predicate(`all txn are type ${type}`)(
      filtered.data.every(t => t.transaction_type === type)
    );
  }

  // 6. Filter by amount range
  const minAmount = 200, maxAmount = 600;
  const filteredByAmount = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.search(connection, {
    mileageWalletId: wallet.id,
    body: {
      min_amount: minAmount,
      max_amount: maxAmount,
      page: 1,
      page_size: pageSize,
    },
  });
  typia.assert(filteredByAmount);
