/**
 * Validate hard deletion (irreversible delete) of a coin wallet snapshot as an admin and permissions/error coverage. 
 *
 * This test ensures that administrative users can delete a coin wallet snapshot and the deletion is enforced, while normal/non-admin users cannot perform the operation. It also validates error and edge scenarios.
 *
 * Step-by-step process:
 * 1. As an admin, create a new coin wallet for yourself (ensuring no customer/seller fields present).
 * 2. As an admin, create a valid coin wallet snapshot for this wallet.
 * 3. As admin, call delete for this snapshot (targeting /{coinWalletId}/coinSnapshots/{coinSnapshotId}).
 * 4. Attempt to read/fetch the snapshot again (should not be accessible; since no read API is present, skip direct read; if search were present, verify not listed).
 * 5. Try deleting the same snapshot again (should return error/confirmation of non-existence).
 * 6. Try deleting a snapshot from a non-existent wallet or with an invalid coinSnapshotId combination (should error).
 * 7. Simulate a non-admin user (or at least with-blanks) to confirm non-admins cannot delete snapshots (should error; if no user switching, explain limitation).
 * 8. Admin-initiated deletes should be audit-logged (but as audit API/logs aren't exposed here, note in comments that audit system must be checked).
 */
export async function test_api_coin_wallet_snapshot_deletion_hard_and_permission(connection: api.IConnection) {
  // 1. Create an admin-only coin wallet
  const wallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
      wallet_type: "event",
      wallet_status: "active",
      wallet_address: RandomGenerator.alphabets(10),
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate,
  });
  typia.assert(wallet);

  // 2. Create a snapshot for this wallet
  const snapshot = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.create(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      owner_admin_id: wallet.wallet_owner_admin_id,
      wallet_type: wallet.wallet_type,
      wallet_status: wallet.wallet_status,
      wallet_address: wallet.wallet_address,
      snapshot_balance: 123.45,
      snapshot_reason: "test deletion",
      snapshot_at: new Date().toISOString(),
    } satisfies IShoppingMallAiBackendCoinSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 3. Delete the snapshot (hard delete)
  await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.erase(connection, {
    coinWalletId: wallet.id,
    coinSnapshotId: snapshot.id,
  });

  // 4. Try deleting the same snapshot again (should result in error as snapshot no longer exists)
  await TestValidator.error("second deletion should fail")(() =>
