      coinWalletId: wallet.id,
      coinSnapshotId: snapshot.id,
    })
  );

  // 5. Try deleting a snapshot with a mismatched/non-existent wallet or snapshot id
  await TestValidator.error("non-existent wallet should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.erase(connection, {
      coinWalletId: typia.random<string & tags.Format<"uuid">>(),
      coinSnapshotId: snapshot.id,
    }),
  );
  await TestValidator.error("non-existent snapshot should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.erase(connection, {
      coinWalletId: wallet.id,
      coinSnapshotId: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 6. Permission: TEST skipped - No customer/seller permission simulation APIs available in this SDK scope.
  //    If switching to non-admin context was supported by the SDK, test would attempt deletion with such a user and expect an error.

  // 7. Audit: Deletion is required to be audit-logged, per system policy.
  //    As there is no API to fetch audit logs, this is documented here, but not verifiable.
}

