/**
 * Test that a customer can successfully create a new product review after purchasing the product.
 *
 * Business context:
 * Only customers who have actually completed a purchase for a given product can submit a review. The review requires the customer to specify a rating (1-5), review text, an optional title, and must reference the actual product and the purchased order item. AI moderation and compliance fields should be either auto-assigned or specifiable for audit purposes. The returned result must be the full review entity including the assigned id and moderation fields.
 *
 * Test Steps:
 * 1. Create a new order for a given (random) customer and product using the /customer/orders endpoint.
 * 2. Use the data from the created order to extract the required business references (customer id, product id, order item id, etc).
 * 3. Call the /customer/productReviews endpoint to submit a review with compliant data (including rating, title, body, references, and valid workflow status).
 * 4. Assert that the response contains a valid IShoppingMallAiBackendProductReview object, including the assigned review id, reference fields, persisted values, and that moderation/compliance info is present.
 * 5. Optionally, validate edge cases (e.g., correct status, non-null system fields like created_at).
 */
export async function test_api_product_review_customer_create_success(connection: api.IConnection) {
  // 1. Create a new order for a random customer and product
  const orderInput: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    order_group_id: null,
    order_number: RandomGenerator.alphaNumeric(10),
    total_amount: 49900,
    currency_code: "KRW",
    note: RandomGenerator.paragraph()(),
    current_status: "created",
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: orderInput,
  });
  typia.assert(order);

  // 2. Use the created order to extract business references
  const productId = typia.random<string & tags.Format<"uuid">>();
  const orderItemId = typia.random<string & tags.Format<"uuid">>();
  // Note: In a real system, order item and product relations would be derived from the order entity's items, but here we generate them as mocks (DTO does not support nesting or true reference extraction).

  // 3. Create a review with all required references/fields
  const reviewInput: IShoppingMallAiBackendProductReview.ICreate = {
    product_id: productId,
    order_item_id: orderItemId,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    rating: typia.random<number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>>(),
    status: "normal",
    ai_sentiment_score: 0.83,
    ai_spam_score: 0.04,
  };
  const review = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: reviewInput,
  });
  typia.assert(review);

  // 4. Assert all expected fields and business relations
  TestValidator.equals("customer_id matches")(review.customer_id)(order.customer_id);
  TestValidator.equals("status is normal")(review.status)("normal");
  TestValidator.equals("product_id matches")(review.product_id)(reviewInput.product_id);
  TestValidator.equals("order_item_id matches")(review.order_item_id)(reviewInput.order_item_id);
  TestValidator.equals("body matches")(review.body)(reviewInput.body);
  TestValidator.equals("rating matches")(review.rating)(reviewInput.rating);
  TestValidator.predicate("created_at exists")(!!review.created_at && typeof review.created_at === "string");
  TestValidator.predicate("id assigned")(!!review.id && typeof review.id === "string");
  TestValidator.predicate("AI moderation present")(
    typeof review.ai_sentiment_score === "number" && typeof review.ai_spam_score === "number"
  );
}

