 *
 * Business context:
 * Customers need to access their shopping cart in order to view products they intend to purchase, verify session state, and proceed to checkout. Access control is critical: users should only be able to access their own carts.
 *
 * Step-by-step process:
 * 1. Register and log in as a new customer (obtain valid JWT/Authorization header set in the connection).
 * 2. Create a new cart for this customer - capture the cart ID from the creation response.
 * 3. Fetch the cart detail using API GET /shoppingMallAiBackend/customer/carts/{cartId} as the customer.
 * 4. Validate that the response fields (id, status, session_token, created_at, updated_at, deleted_at) all match those returned from the cart creation step and that the record exists for the correct customer session.
 * 5. As a negative check, register a second different customer, and try to fetch the first customer's cart by its cartId (should fail with a business authorization error).
 */
export async function test_api_cart_customer_detail_success(connection: api.IConnection) {
  // 1. Register (sign up) as a new customer and obtain JWT
  const customerSignUpInput: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Test1234!", // Valid password
    name: RandomGenerator.name(),
    nickname: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  };
  const signUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: customerSignUpInput,
  });
  typia.assert(signUpResponse);

  // JWT should automatically be attached to connection by SDK after signUp

  // 2. Create a cart for this customer
  const cartCreateInput: IShoppingMallAiBackendCart.ICreate = {
    status: "active",
    session_token: null, // For authenticated customers, session_token may not be needed
  };
  const createdCart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: cartCreateInput,
  });
  typia.assert(createdCart);

  // 3. Retrieve cart details for the customer's own cart
  const fetchedCart = await api.functional.shoppingMallAiBackend.customer.carts.at(connection, {
    cartId: createdCart.id,
  });
  typia.assert(fetchedCart);

  // 4. Validate that all cart fields are as expected
  TestValidator.equals("cart.id matches")(fetchedCart.id)(createdCart.id);
  TestValidator.equals("cart.status matches")(fetchedCart.status)(createdCart.status);
  TestValidator.equals("cart.session_token matches")(fetchedCart.session_token)(createdCart.session_token);
  TestValidator.equals("cart.created_at matches")(fetchedCart.created_at)(createdCart.created_at);
  TestValidator.equals("cart.updated_at matches")(fetchedCart.updated_at)(createdCart.updated_at);
  TestValidator.equals("cart.deleted_at matches")(fetchedCart.deleted_at)(createdCart.deleted_at);

  // 5. Attempt unauthorized access: Register a second customer, try to fetch the first cart, expect error
  const otherCustomerSignUpInput: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Abc5678@",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  };
  await api.functional.auth.customer.register.signUp(connection, {
    body: otherCustomerSignUpInput,
  });
  // Token is now switched to the new customer account

  TestValidator.error("Unauthorized access to cart must fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.carts.at(connection, {
        cartId: createdCart.id,
      });
    }
  );
}

