    body: {
      favorite_product_id: null,
      favorite_inquiry_id: null,
      favorite_address_id: typia.random<string & tags.Format<"uuid">>(),
      target_type: "ADDRESS",
      snapshot_object_id: typia.random<string & tags.Format<"uuid">>(),
