      nickname: RandomGenerator.alphabets(10),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(registration);

  // 2. Log in as the customer
  const login = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: registration.customer.email,
      password: "password!2A"
    } satisfies ICustomerSignIn.Request
  });
  typia.assert(login);
  TestValidator.equals("customer.id")(login.customer.id)(registration.customer.id);

  // 3. Soft-delete the customer profile
  await api.functional.shoppingMallAiBackend.customer.customers.erase(connection, {
    customerId: registration.customer.id
  });

  // 4. Attempt to delete the already-deleted profile again
  await TestValidator.error("double erasure should fail")(
    () => api.functional.shoppingMallAiBackend.customer.customers.erase(connection, {
      customerId: registration.customer.id
    })
  );
}

