  typia.assert(wallet);

  // Step 2: Create a coin balance entry for this wallet
  const initialBalanceInput: IShoppingMallAiBackendCoinBalance.ICreate = {
    wallet_id: wallet.id,
    balance: 100,
    balance_at: new Date().toISOString(),
  };
  const balance = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.create(connection, { coinWalletId: wallet.id, body: initialBalanceInput });
