  TestValidator.equals("wallet_id immutable")(updatedBalance.wallet_id)(wallet.id);
  TestValidator.equals("id immutable")(updatedBalance.id)(balance.id);
  TestValidator.equals("created_at immutable")(updatedBalance.created_at)(balance.created_at);

  // Step 4: Try updating a non-existent balance (should fail)
  await TestValidator.error("not found for non-existent coinBalanceId")(
    async () =>
      await api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.update(connection, {
        coinWalletId: wallet.id,
        coinBalanceId: typia.random<string & tags.Format<"uuid">>(),
        body: updateInput,
      })
