  typia.assert(fakeWallet);

  await TestValidator.error("not found for mismatched coinWalletId")(
    async () =>
      await api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.update(connection, {
        coinWalletId: fakeWallet.id,
        coinBalanceId: balance.id,
        body: updateInput,
      })
  );

  // Step 6: (Simulated) Try the same call as a non-admin (should be forbidden if roles are enforced)
  // (No API for non-admin, so this is documented in scenario, not runnable here)
}

