  // 1. Create a product as seller
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    description: RandomGenerator.content()()(),
    main_image_uri: null,
    status: "draft"
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: productInput });
  typia.assert(product);
  TestValidator.equals("product name")(product.name)(productInput.name);
  TestValidator.equals("product status")(product.status)(productInput.status);
  // 2. Create a channel mapping for this product
  const channelId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const mappingInput: IShoppingMallAiBackendProductChannelMap.ICreate = {
    product_id: product.id,
    channel_id: channelId,
    status: "active"
  };
  const productChannelMap = await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.createProductChannelMap(connection, {
    productId: product.id,
    body: mappingInput
  });
  typia.assert(productChannelMap);
  TestValidator.equals("mapped product")(productChannelMap.product_id)(product.id);
  TestValidator.equals("channel")(productChannelMap.channel_id)(channelId);
  TestValidator.equals("map status")(productChannelMap.status)(mappingInput.status);
  // 3. Retrieve the mapping by id
  const retrieved = await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.at(connection, {
    productId: product.id,
    productChannelMapId: productChannelMap.id
  });
  typia.assert(retrieved);
  // 4. Validate key fields of the mapping
  TestValidator.equals("retrieved id")(retrieved.id)(productChannelMap.id);
  TestValidator.equals("retrieved product_id")(retrieved.product_id)(product.id);
  TestValidator.equals("retrieved channel_id")(retrieved.channel_id)(channelId);
  TestValidator.equals("retrieved status")(retrieved.status)(mappingInput.status);
  // 5. Validate audit fields
  TestValidator.predicate("created_at date-time")(typeof retrieved.created_at === "string" && !Number.isNaN(Date.parse(retrieved.created_at)));
  TestValidator.predicate("updated_at date-time")(typeof retrieved.updated_at === "string" && !Number.isNaN(Date.parse(retrieved.updated_at)));
}

