/**
 * Validate update failure due to resource not found when updating a product search keyword.
 *
 * This test verifies that the API correctly returns an error when attempting to update a product search keyword
 * using non-existent product or productSearchKeywordId values. It ensures resource integrity and that updates
 * are never allowed for missing or already-deleted records.
 *
 * Steps:
 * 1. Prepare random UUIDs not associated with any product or product search keyword (simulate missing records).
 * 2. Attempt to update a product search keyword using made-up IDs.
 * 3. Assert that the API throws an error indicating not found.
 * 4. Repeat with another set of random IDs to confirm error behavior.
 */
export async function test_api_product_search_keyword_update_not_found(
  connection: api.IConnection,
) {
  // 1. Prepare random UUIDs for productId and productSearchKeywordId (guaranteed non-existent)
  const nonExistentProductId: string = typia.random<string & tags.Format<"uuid">>();
  const nonExistentProductSearchKeywordId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Prepare update body with random search keyword
  const updateBody: IShoppingMallAiBackendProductSearchKeyword.IUpdate = {
    search_keyword: RandomGenerator.alphaNumeric(12),
  };

  // 3. Attempt to update using non-existent IDs, expecting a not found error
  await TestValidator.error("should throw not found error on update with invalid IDs")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.updateProductSearchKeyword(
        connection,
        {
          productId: nonExistentProductId,
          productSearchKeywordId: nonExistentProductSearchKeywordId,
          body: updateBody,
        },
      );
    },
  );

  // 4. Repeat with a second set of random non-existent IDs to reaffirm error behavior
  const anotherFakeProductId: string = typia.random<string & tags.Format<"uuid">>();
  const anotherFakeProductSearchKeywordId: string = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("should throw not found for another random ID combination")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.updateProductSearchKeyword(
        connection,
        {
          productId: anotherFakeProductId,
          productSearchKeywordId: anotherFakeProductSearchKeywordId,
          body: updateBody,
        },
      );
    },
  );
}

