    body: {
      wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
      wallet_type: "test-type",
      wallet_status: "active",
      wallet_address: RandomGenerator.alphaNumeric(16),
      wallet_label: "Test Wallet",
      security_code: null,
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate,
  });
  typia.assert(coinWallet);

  // 2. Create a coin wallet balance record
