import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";

/**
 * Validate admin behavior when attempting to delete a product inquiry that has already been deleted or does not exist.
 *
 * This test ensures compliance with business logic whereby a delete operation on a non-existent or already soft-deleted record results in a 'not found' or idempotent response. This prevents information disclosure, enforces audit/evidence policies, and ensures the API behaves as intended for admin users.
 *
 * Steps:
 * 1. Create a product inquiry as a customer (simulate with random UUIDs for customer_id and product_id).
 * 2. Soft-delete the inquiry as an admin (using DELETE endpoint).
 * 3. Attempt to delete the same inquiry again as admin to provoke the edge case (should get not found/idempotency response).
 * 4. Validate that the second deletion attempt does not succeed (i.e., error is thrown or idempotent/404 result occurs).
 */
export async function test_api_product_inquiry_delete_admin_not_found(connection: api.IConnection) {
  // 1. Create a new product inquiry as customer
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      product_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()().slice(0, 60),
      body: RandomGenerator.content()()().slice(0, 200),
      public: RandomGenerator.pick([true, false]),
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
  });
  typia.assert(inquiry);
  // 2. Soft delete the created inquiry as admin
  await api.functional.shoppingMallAiBackend.admin.productInquiries.erase(connection, {
    productInquiryId: inquiry.id,
  });
  // 3. Attempt to delete again (should be not found or idempotent)
  await TestValidator.error("Admin deleting already deleted inquiry should fail")(
    () => api.functional.shoppingMallAiBackend.admin.productInquiries.erase(connection, {
      productInquiryId: inquiry.id,
    })
  );
}

