/**
 * Comprehensive E2E test covering the update and soft-unfavorite flow for a customer's favorite product record.
 *
 * This test executes the following:
 * 1. Creates a new favorite product for an authenticated customer (prerequisite step).
 * 2. Updates the favorite (as owner) by setting deleted_at to a timestamp (soft-unfavorite) and verifies response.
 * 3. Validates the record's deleted_at field is updated as expected.
 * 4. Attempts to update the same record again (already unfavorited) and checks for error/validation response.
 * 5. Attempts to update a non-existent favoriteProductId and checks error handling.
 * 6. (If multi-customer context APIs existed) Would try updating as a different customer, but not implementable - skipped.
 *
 * Only the fields and flows possible given the real DTO and APIs are implemented.
 */
export async function test_api_favorite_product_update_and_soft_unfavorite(connection: api.IConnection) {
  // 1. Create a new favorite product for the authenticated customer
  const productId = typia.random<string & tags.Format<"uuid">>();
  const favorite = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: { product_id: productId } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate,
  });
  typia.assert(favorite);

  // 2. Soft-unfavorite (set deleted_at to now)
  const unfavoriteTimestamp = new Date().toISOString();
  const unfavorited = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.update(connection, {
    favoriteProductId: favorite.id,
    body: { deleted_at: unfavoriteTimestamp } satisfies IShoppingMallAiBackendFavoriteProduct.IUpdate,
