import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteAddress";

/**
 * Validates that a customer can successfully fetch the details of their own favorite address using the favorite address detail endpoint.
 * 
 * Business context: Customers may bookmark (favorite) frequently-used addresses for fast checkout and AI-driven suggestions.
 * This test ensures a customer can access details about their own favorite address, confirming all metadata and permissions are correct.
 * 
 * Step-by-step process:
 * 1. Simulate the customer creating a favorite address linkage by marking an existing address as favorite (using the POST endpoint).
 * 2. Retrieve the newly created favorite address's details by calling the detail (GET) endpoint with the returned id.
 * 3. Validate that all key fields (id, customer_id, address_id, created_at) are correctly returned and that deleted_at is either null or undefined for active entries.
 * 4. Ensure the response strictly matches the IShoppingMallAiBackendFavoriteAddress schema and ownership (customer_id) matches current user.
 */
export async function test_api_favorite_address_detail_success_owner_access(connection: api.IConnection) {
  // 1. Simulate favorite address creation (prerequisite setup)
  const reqBody = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    address_id: typia.random<string & tags.Format<"uuid">>()
  } satisfies IShoppingMallAiBackendFavoriteAddress.ICreate;
  const favorite: IShoppingMallAiBackendFavoriteAddress = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, { body: reqBody });
  typia.assert(favorite);

  // 2. Retrieve favorite address detail
  const detail: IShoppingMallAiBackendFavoriteAddress = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.at(connection, { favoriteAddressId: favorite.id });
  typia.assert(detail);

  // 3. Validate critical fields and ownership
  TestValidator.equals("favoriteAddress id matches")(detail.id)(favorite.id);
  TestValidator.equals("customer owner matches")(detail.customer_id)(favorite.customer_id);
  TestValidator.equals("address linkage matches")(detail.address_id)(favorite.address_id);
  TestValidator.equals("creation timestamp present")(typeof detail.created_at === "string")(true);
  TestValidator.equals("not deleted, still active")(detail.deleted_at === undefined || detail.deleted_at === null)(true);
}

