import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendArticleCategory";

/**
 * Test deletion of an article category which has non-deleted child categories.
 *
 * This test ensures that the system enforces referential integrity: an attempt to delete a parent category that still has children (child categories not soft/hard deleted) should be rejected. The API must return an error indicating that dependent child categories must be deleted first (integrity violation).
 *
 * Full business context:
 * - Categories are managed in a hierarchical tree (parent/child, not a flat list).
 * - Deleting a category with non-deleted descendants must fail.
 * - API is expected to respond with an error when integrity is violated.
 *
 * Steps:
 * 1. Create a parent article category (root or any level).
 * 2. Create a child article category that references the parent (parent_id = parent.id).
 * 3. Attempt to delete the parent category while the child still exists and is not deleted.
 * 4. Verify the API call fails (throws error), confirming integrity enforcement.
 */
export async function test_api_article_category_delete_with_children(connection: api.IConnection) {
  // 1. Create parent category
  const parentCategory = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
    body: {
      parent_id: null,
      name: `Parent Category ${typia.random<number>()}`,
      code: `parent_${typia.random<number>()}`,
      sort_order: 10,
      is_active: true
    } satisfies IShoppingMallAiBackendArticleCategory.ICreate
  });
  typia.assert(parentCategory);

  // 2. Create child category referencing parent
  const childCategory = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
    body: {
      parent_id: parentCategory.id,
      name: `Child Category ${typia.random<number>()}`,
      code: `child_${typia.random<number>()}`,
      sort_order: 20,
      is_active: true
    } satisfies IShoppingMallAiBackendArticleCategory.ICreate
  });
  typia.assert(childCategory);

  // 3. Attempt to delete the parent category (should fail due to integrity constraint)
  await TestValidator.error("Should not delete parent with non-deleted child")(() =>
    api.functional.shoppingMallAiBackend.admin.articleCategories.erase(connection, {
      categoryId: parentCategory.id as string & tags.Format<"uuid">
    })
  );
}

