/**
 * Validate that a seller cannot search order status histories for orders
 * they do not own (proper authorization is enforced).
 *
 * Scenario:
 *   1. As a customer, create a new order (which will not be attached to the test seller).
 *   2. (PRECONDITION/ASSUMPTION) Seller is authenticated, and the created order does NOT belong to this seller.
 *   3. Attempt to perform a PATCH search for order status histories on this unrelated order as the seller.
 *   4. Confirm that the operation is denied (HTTP 403 Forbidden or equivalent error), and that no sensitive data (order status histories) are disclosed.
 *
 * Steps:
 *   - Use the customer-side API to create an order, collecting its UUID.
 *   - Using the seller context (no affiliation to the customer nor their order), call
 *     api.functional.shoppingMallAiBackend.seller.orders.orderStatusHistories.search with that orderId and a basic search body.
 *   - Validate that the API responds with a permission error (not with actual data),
 *     e.g., TestValidator.error(...).
 *   - Ensure that no status data is returned/leaked.
 */
export async function test_api_order_status_history_seller_search_unauthorized(
  connection: api.IConnection,
) {
  // 1. As customer, create a new order owned by a random customer.
  const nonSellerOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      order_number: RandomGenerator.alphaNumeric(8),
      total_amount: typia.random<number>(),
      currency_code: "KRW",
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(nonSellerOrder);

  // 2. (PRECONDITION) Seller is (or remains) authenticated, but this order does NOT belong to them.

  // 3. Attempt to access order status histories for a non-affiliated order as seller.
  await TestValidator.error("seller cannot access non-owned order's status history")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.orders.orderStatusHistories.search(connection, {
        orderId: nonSellerOrder.id,
        body: {
          order_id: nonSellerOrder.id,
          page: 1,
          limit: 1,
        } satisfies IShoppingMallAiBackendOrderStatusHistory.IRequest,
      });
    }
  );
}

