 * Test Process:
 * 1. Authenticate as an admin to obtain access for rule creation.
 * 2. Create the initial business rule with a specific `rule_code`.
 * 3. Attempt to create a second business rule using the exact same `rule_code` but with different description or dates.
 * 4. Validate that the second operation fails (via error), indicating duplicate rule_code is prohibited.
 * 5. Confirm both attempts (success and failure) receive appropriate API response types.
 */
export async function test_api_businessrule_create_duplicate_code_error(connection: api.IConnection) {
  // 1. Admin authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SuperSecret123!";
  // For this test, we must ensure the login credentials correspond to an existing admin.
  // If account provisioning API is not exposed, use pre-existing admin credentials.
  // (Here, we simulate random login for coverage.)
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);
  // The JWT/header is set in connection by SDK behavior.

  // 2. Create initial business rule with a unique rule_code
  const ruleCode = "TEST_DUPLICATE_CODE_" + RandomGenerator.alphaNumeric(8);
  const request1: IShoppingMallAiBackendBusinessRule.ICreate = {
    rule_code: ruleCode,
    rule_description: "This is an initial test rule for duplication validation.",
    enforcement_status: "active",
    reason_for_change: "Initial policy creation for duplication test.",
    effective_from: new Date().toISOString(),
    effective_to: null,
  };
  const businessRule1 = await api.functional.shoppingMallAiBackend.admin.businessRules.create(connection, {
    body: request1,
  });
  typia.assert(businessRule1);
  TestValidator.equals("rule_code matches")(businessRule1.rule_code)(ruleCode);
  TestValidator.equals("status active")(businessRule1.enforcement_status)("active");

  // 3. Attempt to create a new rule with the same rule_code (duplicate)
  const request2: IShoppingMallAiBackendBusinessRule.ICreate = {
    rule_code: ruleCode, // same code
    rule_description: "Second attempt should fail - duplicate code.",
    enforcement_status: "draft",
    reason_for_change: "Trying to duplicate rule code to test conflict.",
    effective_from: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(), // 1 day future
    effective_to: null,
  };
  await TestValidator.error("should reject duplicate rule_code")(async () => {
    await api.functional.shoppingMallAiBackend.admin.businessRules.create(connection, {
      body: request2,
    });
  });
}

