  connection: api.IConnection,
) {
  // 1. Log in as a customer (non-admin)
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = RandomGenerator.alphaNumeric(12);
  let customerAuth;
  try {
    customerAuth = await api.functional.auth.customer.login.signIn(connection, {
      body: {
        email: customerEmail,
        password: customerPassword,
      } satisfies ICustomerSignIn.Request,
    });
    typia.assert(customerAuth);
  } catch {
    throw new Error(
      `Cannot perform permission negative test because customer login failed. Ensure a valid customer exists or pre-seed required credentials for this test.`,
    );
  }
  // Set customer token on connection
  connection.headers = connection.headers || {};
  connection.headers.Authorization = customerAuth.setHeaders.Authorization;

  // 2. Attempt to update a system setting as a non-admin
  const systemSettingId = typia.random<string & tags.Format<"uuid">>();
  const updateInput: IShoppingMallAiBackendSystemSetting.IUpdate = {
    conf_value: RandomGenerator.alphaNumeric(16),
    description: RandomGenerator.paragraph()(),
  };

  // 3. Expect permission error when attempting the update
  await TestValidator.error("non-admin permission denied for system setting update")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.systemSettings.update(
        connection,
        {
          systemSettingId,
          body: updateInput,
        },
      );
    },
  );
}

