 * 5. Validate DELETE returns no content (void)
 * 6. Optionally, re-fetch the inquiry directly (if the API allowed) to assert deleted_at is now set (not possible with current API access, so skipped).
 */
export async function test_api_product_inquiry_delete_customer_success(
  connection: api.IConnection,
) {
  // 1. Prepare test data for creating a new inquiry
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const product_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Customer creates a new product inquiry
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id,
      product_id,
      title: "Test inquiry for deletion",
      body: "Verifying that soft-delete sets deleted_at and hides the record.",
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
  });
  typia.assert(inquiry);

  // 3. Customer soft-deletes their own inquiry
