 * 1. Register a customer account via /auth/customer/register
 * 2. (Precondition) Assume an external link record for the customer exists (simulate creation for test)
 * 3. Admin updates the external link (provide new values for some fields)
 * 4. Assert that the response returns the correct new values and is of correct type
 * 5. Attempt update with invalid/missing fields, expect validation error
 * 6. Attempt update using a non-existent link id or customer id, expect not-found or permission error
 * 7. Optionally, check that business constraints (e.g., provider immutability) hold if relevant in test DTO
 */
export async function test_api_customer_external_link_admin_update_success_and_validation(connection: api.IConnection) {
  // 1. Register customer account
  const signUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(12),
      phone: RandomGenerator.mobile(),
    }
  });
  typia.assert(signUp);
  const customer = signUp.customer;

  // 2. Simulate creation of external link (cannot create via real API; fabricate a valid object for update)
  const extLink: IShoppingMallAiBackendCustomerExternalLink = {
    id: typia.random<string & tags.Format<"uuid">>(),
    customer_id: customer.id,
    provider: "google",
    external_id: RandomGenerator.alphaNumeric(18),
    linked_at: new Date().toISOString(),
    last_auth_at: new Date().toISOString(),
    metadata_json: JSON.stringify({ synced: true }),
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    deleted_at: null,
  };

  // 3. Admin updates the external link with new metadata and timestamp
  const updateBody: IShoppingMallAiBackendCustomerExternalLink.IUpdate = {
    id: extLink.id,
    last_auth_at: new Date().toISOString(),
    metadata_json: JSON.stringify({ synced: false, updated: true })
  };
  const updated = await api.functional.shoppingMallAiBackend.admin.customers.externalLinks.update(connection, {
    customerId: customer.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("id")(updated.id)(extLink.id);
  TestValidator.equals("customer_id")(updated.customer_id)(customer.id);
  TestValidator.equals("metadata_json")(updated.metadata_json)(updateBody.metadata_json);
  TestValidator.equals("last_auth_at")(updated.last_auth_at)(updateBody.last_auth_at);

  // 4. Failure: missing required 'id' property
  await TestValidator.error("missing id should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.customers.externalLinks.update(connection, {
      customerId: customer.id,
      body: {
        // id omitted intentionally
        metadata_json: "{}",
      } as any,
    })
  );

  // 5. Failure: invalid id format
  await TestValidator.error("invalid id format should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.customers.externalLinks.update(connection, {
      customerId: customer.id,
      body: {
        id: "not-a-uuid",
        metadata_json: "{}",
      } as any,
    })
  );

  // 6. Failure: non-existent link id
  await TestValidator.error("non-existent id should return not-found error")(() =>
    api.functional.shoppingMallAiBackend.admin.customers.externalLinks.update(connection, {
      customerId: customer.id,
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        metadata_json: JSON.stringify({ attempt: "fail" }),
      }
    })
  );

  // 7. Failure: wrong customer id (simulate unauthorized/not-owned)
  await TestValidator.error("wrong customer id should return not-found or permission error")(() =>
    api.functional.shoppingMallAiBackend.admin.customers.externalLinks.update(connection, {
      customerId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        id: extLink.id,
        metadata_json: JSON.stringify({ attempt: "wrong customer" }),
      }
    })
  );
}

