 * 3. Update the wallet's status and/or label fields using the update endpoint.
 * 4. Confirm the response immediately reflects the changes, and re-fetch (if possible) for persistence. (Audit logging can't be checked via API so it's out-of-scope for automated assertion unless specifically supported.)
 * 5. Confirm only allowed fields (status, label, security_code) are updatable and that attempts to change disallowed or out-of-bounds fields are rejected by the API.
 * 6. Confirm an update attempt for a non-existent or deleted mileage wallet ID returns a suitable error.
 */
export async function test_api_admin_mileage_wallet_update_attributes(connection: api.IConnection) {
  // 1. Register a new customer
  const signupReq: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "1234", // Use a fixed password for stable test context
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const signupResult = await api.functional.auth.customer.register.signUp(connection, { body: signupReq });
  typia.assert(signupResult);
