    await api.functional.shoppingMallAiBackend.admin.mileageWallets.update(connection, {
      mileageWalletId: nonExistId,
      body: {
        id: nonExistId,
        wallet_label: "Ghost Wallet"
      },
    });
  });

  // 6. Negative: Update logically deleted wallet
  // We'll simulate deletion by setting deleted_at manually if the API allowed, but since delete isn't exposed, this step is skipped.
}

