import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendComplianceEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceEvent";
import type { IShoppingMallAiBackendComplianceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceSnapshot";

/**
 * Validate that an admin can soft delete (logically remove) a compliance snapshot attached to a compliance event, following audit and legal compliance standards.
 *
 * Scenario:
 * 1. Create a compliance event as required by the system. This event includes required metadata (such as event_type, actor_type, target_type, etc.).
 * 2. Attach a compliance snapshot to this event. The snapshot contains entity_type, optional entity_id, and a serialized snapshot_payload as per regulatory evidence requirements.
 * 3. Perform a soft delete (logical removal) of this snapshot via the admin API, using the compliance event ID and the snapshot ID.
 * 4. Since there is no provided endpoint to fetch active/compliance snapshots after deletion, this test can only ensure the deletion completes without error, and errors are properly handled if the same or a non-existent snapshot is deleted again.
 * 5. Test that re-deleting the already deleted snapshot (idempotent delete) or an invalid snapshot ID yields an error (using TestValidator.error).
 */
export async function test_api_compliance_event_snapshot_delete_soft_delete(
  connection: api.IConnection,
) {
  // 1. Create a compliance event for testing
  const event = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
    body: {
      event_type: "policy_update",
      actor_id: null,
      actor_type: "admin",
      target_type: "order",
      target_id: null,
      event_payload: JSON.stringify({ info: "Initial policy update for testing." }),
    } satisfies IShoppingMallAiBackendComplianceEvent.ICreate,
  });
  typia.assert(event);

  // 2. Attach a compliance snapshot to this event
  const snapshot = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.create(connection, {
    complianceEventId: event.id,
    body: {
      compliance_event_id: event.id,
      entity_type: "order",
      entity_id: null,
      snapshot_payload: JSON.stringify({ orderState: "PRE_DELETION", comment: "Evidence before deletion." }),
    } satisfies IShoppingMallAiBackendComplianceSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 3. Perform soft deletion (logical remove) on the snapshot
  await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.erase(
    connection,
    {
      complianceEventId: event.id,
      complianceSnapshotId: snapshot.id,
    },
  );

  // 4. Try to soft-delete again (should yield error) -- idempotency or already deleted
  await TestValidator.error("Deleting an already deleted compliance snapshot should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.erase(
        connection,
        {
          complianceEventId: event.id,
          complianceSnapshotId: snapshot.id,
        },
      );
    },
  );

  // 5. Try to delete using a random non-existent snapshot id
  const nonExistentSnapshotId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Deleting a non-existent compliance snapshot should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.erase(
        connection,
        {
          complianceEventId: event.id,
          complianceSnapshotId: nonExistentSnapshotId,
        },
      );
    },
  );
}

