      product_id: typia.random<string & tags.Format<"uuid">>()
    } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate
  });
  typia.assert(favorite);

  // 2. Soft-delete (unfavorite) the favorite product
  await api.functional.shoppingMallAiBackend.customer.favoriteProducts.erase(connection, {
    favoriteProductId: favorite.id,
  });

  // 3. Attempt to soft-delete the same product again (idempotency check)
