        favoriteProductId: favorite.id,
      });
    },
  );

  // 4. Attempt to delete a favoriteProductId that never existed
  await TestValidator.error("Deleting a nonexistent favoriteProductId should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.favoriteProducts.erase(connection, {
        favoriteProductId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
