import type { IShoppingMallAiBackendComplianceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceSnapshot";

/**
 * Test successful creation of a new compliance snapshot associated with a compliance event.
 *
 * This test validates the workflow for creating a compliance audit snapshot under a parent compliance event. The process requires that we first generate a compliance event record with the minimum metadata required for compliance/audit traceability. Then, as an admin, we submit a valid snapshot payload attached to the event, and verify the correct creation, metadata, and evidence structure in the returned response.
 *
 * The detailed scenario is:
 * 1. Create a compliance event, simulating a regulatory or business event like a 'policy_update' or 'data_erasure_request'.
 * 2. Use the event's ID to create a compliance snapshot, filling all required fields with realistic, type-safe values that match the system's audit/evidence requirements.
 * 3. Validate that the API returns a snapshot object containing the correct metadata, matches the original payload and entity linkage, and that all mandatory audit evidence and timestamp fields are present and correctly formatted.
 * 4. Optionally, verify edge cases: entity_id can be null for global snapshots; snapshot_payload must be valid JSON.
 */
export async function test_api_compliance_snapshot_create_success(
  connection: api.IConnection,
) {
  // 1. Create a compliance event as prerequisite (e.g., simulating a 'policy_update' event).
  const complianceEventInput: IShoppingMallAiBackendComplianceEvent.ICreate = {
    event_type: "policy_update",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    actor_type: "admin",
    target_type: "system_policy",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    event_payload: JSON.stringify({ detail: "Test update for policy compliance." }),
  };
  const complianceEvent = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
    body: complianceEventInput,
  });
  typia.assert(complianceEvent);

  // 2. Use the event id to create a compliance snapshot.
  const snapshotInput: IShoppingMallAiBackendComplianceSnapshot.ICreate = {
    compliance_event_id: complianceEvent.id,
    entity_type: "system_policy",
    entity_id: complianceEvent.target_id,
    snapshot_payload: JSON.stringify({ policyData: "Sample snapshot for audit evidence." }),
  };
  const snapshot = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.create(connection, {
    complianceEventId: complianceEvent.id,
    body: snapshotInput,
  });
  typia.assert(snapshot);

  // 3. Validate returned metadata and evidence structure.
  TestValidator.equals("compliance_event_id")(snapshot.compliance_event_id)(complianceEvent.id);
  TestValidator.equals("entity_type linkage")(snapshot.entity_type)(snapshotInput.entity_type);
  TestValidator.equals("entity_id linkage")(snapshot.entity_id)(snapshotInput.entity_id);
  TestValidator.equals("snapshot_payload matches")(snapshot.snapshot_payload)(snapshotInput.snapshot_payload);
  TestValidator.predicate("created_at is ISO 8601 date-time")(!!Date.parse(snapshot.created_at));

  // 4. (Optional) Test edge case: entity_id can be null for a global snapshot
  const globalSnapshotInput: IShoppingMallAiBackendComplianceSnapshot.ICreate = {
    compliance_event_id: complianceEvent.id,
    entity_type: "system_global",
    entity_id: null,
    snapshot_payload: JSON.stringify({ global: true }),
  };
  const globalSnapshot = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.create(connection, {
    complianceEventId: complianceEvent.id,
    body: globalSnapshotInput,
  });
  typia.assert(globalSnapshot);
  TestValidator.equals("entity_id null for global snapshot")(globalSnapshot.entity_id)(null);
}

