 *
 * Business context:
 * In the shopping mall backend, product reviews can be created by customers and soft-deleted (status: deleted). Once deleted, even admins must not be able to modify the review; such actions must be rejected in compliance with audit and trust policies. This test validates
 * - An admin is prevented from updating a deleted review and must receive a business error (runtime error), not a type error.
 *
 * Steps:
 * 1. Create a product review as a customer (using valid product/order_item FK, random body/title/rating, status = normal)
 * 2. Delete (soft-delete) the created review as the customer (so status becomes deleted and deleted_at is set)
 * 3. As an admin, attempt to update the deleted review (modify body/title/rating/status)
 * 4. Validate that the update action is rejected and a proper error is thrown (TestValidator.error()).
 */
export async function test_api_product_review_admin_update_deleted_review_error(connection: api.IConnection) {
  // 1. Create a product review as customer
  const createInput: IShoppingMallAiBackendProductReview.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
