 *
 * Steps:
 * 1. Create a realistic paid order using the customer-orders API (simulate with valid, plausible data).
 * 2. As admin, create a new order snapshot:
 *    a. The request "snapshot_json" field is a full JSON-serialize of the created order.
 *    b. "snapshot_reason" is a plausible business reason (e.g., 'payment_complete').
 *    c. POST /shoppingMallAiBackend/admin/orders/{orderId}/orderSnapshots
 *    d. Validate that returned snapshot's order_id matches, snapshot_json is correct, and reason matches input.
 * 3. Negative: Try snapshot with a totally unknown orderId, should fail.
 * 4. Negative: Order-deleted/admin privilege edge cases omitted as the API does not expose corresponding flows.
 */
export async function test_api_order_snapshot_creation_by_admin_for_audit_evidence(
  connection: api.IConnection,
) {
