import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the search and filtering of coin wallet snapshots by an admin user, including pagination metadata, filter by reason, and access control.
 *
 * 1. Create a coin wallet intended for the test as an admin.
 * 2. Create several snapshots for that wallet, each with distinct reasons and timestamps:
 *    - Reason 'audit', date X
 *    - Reason 'incident', date Y, ...
 * 3. Issue a PATCH search request to /admin/coinWallets/{coinWalletId}/coinSnapshots with filters:
 *    - By snapshot_reason (returns only matching reason)
 *    - By snapshot_at_from/to (returns only in date range)
 *    - With limit & page for pagination
 * 4. Validate that:
 *    - Returned items only match the filtered reason/date
 *    - Pagination meta (current, limit, pages, records) refers to filtered set
 *    - All required schema fields are present in each snapshot and match corresponding test data
 * 5. Attempt the same search with an unauthorized user, expect access denial or error.
 */
export async function test_api_coin_wallet_snapshot_search_success_and_filtering(
  connection: api.IConnection,
) {
  // 1. Create a coin wallet
  const coinWallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
      wallet_type: "test-suite-type",
      wallet_status: "active",
      wallet_address: RandomGenerator.alphaNumeric(24),
      wallet_label: "Admin audit wallet for snapshot test",
      security_code: "123456",
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate
  });
  typia.assert(coinWallet);

  // 2. Insert multiple snapshots with distinguishable reasons and times
  const now = new Date();
  const snapshots = await ArrayUtil.asyncRepeat(5)(async (i) => {
    const reason = i % 2 === 0 ? "audit" : "incident";
    const snapshot_at = new Date(now.getTime() - i * 7 * 24 * 60 * 60 * 1000).toISOString(); // each a week before
    return await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.create(connection, {
      coinWalletId: coinWallet.id,
      body: {
        wallet_id: coinWallet.id,
        owner_admin_id: coinWallet.wallet_owner_admin_id!,
        wallet_type: coinWallet.wallet_type,
        wallet_status: coinWallet.wallet_status,
        wallet_address: coinWallet.wallet_address,
        wallet_label: coinWallet.wallet_label,
        security_code: coinWallet.security_code,
        snapshot_balance: 5000 + i * 1000,
        snapshot_reason: reason,
        snapshot_at,
      } satisfies IShoppingMallAiBackendCoinSnapshot.ICreate
    });
  });
  snapshots.forEach(typia.assert);

  // 3. Search snapshots by reason = 'audit'
  const auditResult = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.search(connection, {
    coinWalletId: coinWallet.id,
    body: {
      wallet_id: coinWallet.id,
      snapshot_reason: "audit",
      page: 1,
      limit: 10,
      sort: "snapshot_at desc"
    },
  });
  typia.assert(auditResult);
  auditResult.data.forEach((snap) => {
    TestValidator.equals("reason is audit")(snap.snapshot_reason)("audit");
    TestValidator.equals("wallet matches")(snap.wallet_id)(coinWallet.id);
  });
  TestValidator.predicate("all audit results")(auditResult.data.every((s) => s.snapshot_reason === "audit"));

  // 4. Filter by snapshot_at (range for 3rd/4th inserted)
  const from = snapshots[2].snapshot_at;
  const to = snapshots[3].snapshot_at;
  const rangeResult = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.search(connection, {
    coinWalletId: coinWallet.id,
    body: {
      wallet_id: coinWallet.id,
      snapshot_at_from: from,
      snapshot_at_to: to,
      limit: 10,
      page: 1,
      sort: "snapshot_at asc"
    },
  });
  typia.assert(rangeResult);
  TestValidator.predicate("within range")(rangeResult.data.every((snap) => snap.snapshot_at >= from && snap.snapshot_at <= to));

  // 5. Pagination test (limit = 2)
  const page1 = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.search(connection, {
    coinWalletId: coinWallet.id,
    body: {
      wallet_id: coinWallet.id,
      limit: 2,
      page: 1,
      sort: "snapshot_at desc"
    },
  });
  const page2 = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.search(connection, {
    coinWalletId: coinWallet.id,
    body: {
      wallet_id: coinWallet.id,
      limit: 2,
      page: 2,
      sort: "snapshot_at desc"
    },
  });
  typia.assert(page1);
  typia.assert(page2);
  TestValidator.equals("page 1 length")(page1.data.length)(2);
  TestValidator.equals("page 2 length")(page2.data.length)(2);
  TestValidator.equals("pagination meta")(page1.pagination.limit)(2);

  // 6. Unauthorized access attempt: assume removing admin token clears authorization
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers.Authorization;
  await TestValidator.error("unauthorized search must fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.search(unauthConnection, {
      coinWalletId: coinWallet.id,
      body: {
        wallet_id: coinWallet.id,
        limit: 1,
        page: 1,
      },
    });
  });
}

