/**
 * Validate admin retrieval of a specific mileage wallet's detailed information, including existence, all properties, and not-found handling.
 *
 * This test ensures that an admin can fetch full details for a particular mileage wallet, validates all critical properties, and confirms proper not-found/error behavior for nonexistent or deleted records.
 *
 * 1. Register a new customer using the customer registration API.
 * 2. Create a mileage wallet for the registered customer via the admin mileage wallet creation API.
 * 3. Retrieve the mileage wallet by its id using the admin detail endpoint, verifying:
 *    - All expected fields are present and accurate (customer_id, wallet_program, wallet_status, wallet_label, security_code, created_at, updated_at, deleted_at)
 *    - Business rule: The record matches the just-created wallet and references the correct customer.
 * 4. Attempt to retrieve a non-existent mileage wallet (random UUID) and confirm a not-found error is returned.
 * 5. (Edge) Optionally, soft-delete a mileage wallet (if this API is available; omit if not available in provided endpoints), and try to retrieve it to verify the correct system response respecting privacy and soft-deletion rules.
 */
export async function test_api_mileage_wallet_detail_access_and_not_found(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const customerSignUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
