  const walletCreateInput = {
    customer_id: customer.id,
    wallet_program: RandomGenerator.alphaNumeric(6),
    wallet_status: "active",
    wallet_label: "Test Wallet",
    security_code: null
  } satisfies IShoppingMallAiBackendMileageWallet.ICreate;
  const createdWallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, { body: walletCreateInput });
  typia.assert(createdWallet);

