    productId: product2.id,
    body: {
      product_id: product2.id,
      channel_id: mapping.channel_id, // intentional duplicate
      status: "active",
    },
  });
  typia.assert(mapping2);

  // Now attempt to update mapping2 to use the same channel id (if system prohibits this, error)
  await TestValidator.error("Duplicate channel mapping forbidden")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.updateProductChannelMap(connection, {
      productId: product2.id,
      productChannelMapId: mapping2.id,
      body: { status: "active" },
    });
  });
}

