import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendModerationEvent";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test the immutability enforcement of moderation event fields via the admin backend API.
 *
 * This test verifies that attempts to update immutable/modifiable-restricted fields (such as event_type and created_at)
 * in a moderation event are properly blocked at the API or business logic layer. The workflow simulates real-world admin
 * moderation actions, and robustly checks both error handling and immutability guarantee for audit-trace and compliance integrity.
 *
 * Test Workflow:
 * 1. Register and authenticate a new admin. Save adminId for audit linkage.
 * 2. As that admin, create a moderation event for a synthetic review/inquiry (randomly generate required IDs for a valid request).
 * 3. Attempt to update the moderation event, but include forbidden fields (event_type, created_at) in the update body. (Although
 *    TypeScript DTO enforces updatable fields only, simulate business logic violation by direct request—expect API or server to block.)
 * 4. Confirm via error assertion (TestValidator.error) that the API rejects the update, and that the moderation event record’s original
 *    immutable fields remain unchanged.
 *
 * This test is critical for legal/audit compliance and defensible trace of moderation actions, ensuring no admin can illicitly
 * rewrite the type or origin of a moderation action after its creation.
 */
export async function test_api_moderation_event_update_immutable_field_failure(connection: api.IConnection) {
  // 1. Register and authenticate a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Passw0rd!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminSignUp);
  const adminId = adminSignUp.adminId;

  // 2. Create a moderation event as the authenticated admin
  const eventType = "block"; // Example event_type
  const createBody = {
    actor_id: adminId,
    event_type: eventType,
    reason: "Initial moderation action.",
    // Randomly select either a review or inquiry as the moderation target
    target_inquiry_id: Math.random() > 0.5
      ? typia.random<string & tags.Format<"uuid">>()
      : null,
    target_review_id: Math.random() > 0.5
      ? typia.random<string & tags.Format<"uuid">>()
      : null,
    attached_ai_evidence_id: null,
    referenced_event_id: null,
  } satisfies IShoppingMallAiBackendModerationEvent.ICreate;
  // Ensure at least one of target_inquiry_id or target_review_id is not null
  if (createBody.target_inquiry_id == null && createBody.target_review_id == null) {
    createBody.target_review_id = typia.random<string & tags.Format<"uuid">>()
  }
  const moderationEvent = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, { body: createBody });
  typia.assert(moderationEvent);

  // 3. Attempt to update immutable fields via PUT (simulate by direct fetch, as SDK/DTO only accept allowed fields)
  // Prepare forbidden direct patch—this must be sent at runtime, not compile time.
  // We'll invoke fetch manually to circumvent type system (simulate raw PATCH/PUT with extra keys).
  const forbiddenUpdate = {
    reason: "Illicit field update.",
    event_type: "unblock", // Forbidden change
    created_at: new Date(Date.now() + 123456).toISOString(), // Forbidden change
  };
  // TestValidator.error: Expect error due to business/validation logic
  await TestValidator.error("modification of immutable fields must fail")(async () => {
    // Direct fetch to endpoint, since SDK DTO blocks this shape at compile time
    await fetch(
      `${connection.host}/shoppingMallAiBackend/admin/moderationEvents/${moderationEvent.id}`,
      {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          ...(connection.headers ?? {}),
        },
        body: JSON.stringify(forbiddenUpdate),
      },
    ).then(async r => {
      // Even if API returns 200, force rejection so error assertion triggers
      if (r.ok) {
        throw new Error("API allowed forbidden field update!");
      }
      // Optionally check for 4xx/5xx status
      // const errorBody = await r.text();
    });
  });

  // 4. Confirm record was NOT changed on immutable fields
  const refreshedEvent = await api.functional.shoppingMallAiBackend.admin.moderationEvents.update(connection, {
    moderationEventId: moderationEvent.id,
    body: {},
  });
  typia.assert(refreshedEvent);
  TestValidator.equals("event_type remains unchanged")(refreshedEvent.event_type)(eventType);
  TestValidator.equals("created_at remains unchanged")(refreshedEvent.created_at)(moderationEvent.created_at);
}

