    current_status: "created",
    // Optional fields
    order_group_id: undefined,
    note: undefined,
  };
  const createdOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderInput });
  typia.assert(createdOrder);

  // Step 2: Create snapshot as admin
  const snapshotPayload: IShoppingMallAiBackendOrderSnapshot.ICreate = {
    snapshot_json: JSON.stringify(createdOrder),
    snapshot_reason: "created",
  };
  const createdSnapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.create(connection, {
    orderId: createdOrder.id,
    body: snapshotPayload,
  });
  typia.assert(createdSnapshot);

  // Step 3: Retrieve snapshot as admin
  const fetchedSnapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.at(connection, {
    orderId: createdOrder.id,
    orderSnapshotId: createdSnapshot.id,
  });
  typia.assert(fetchedSnapshot);

  // Step 4: Audit/field integrity
  TestValidator.equals("order_id matches")(fetchedSnapshot.order_id)(createdOrder.id);
  TestValidator.equals("snapshot_id matches")(fetchedSnapshot.id)(createdSnapshot.id);
  TestValidator.equals("snapshot_reason matches")(fetchedSnapshot.snapshot_reason)(snapshotPayload.snapshot_reason);
  const fetchedOrder = JSON.parse(fetchedSnapshot.snapshot_json) as IShoppingMallAiBackendOrder;
  TestValidator.equals("order fields")(fetchedOrder)(createdOrder);

  // Step 5: Error fetch for non-existent snapshot/order
  const randomOrderId = typia.random<string & tags.Format<"uuid">>();
  const randomSnapshotId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("order not found")(() =>
    api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.at(connection, {
      orderId: randomOrderId,
      orderSnapshotId: createdSnapshot.id,
    })
  );
  await TestValidator.error("snapshot not found")(() =>
    api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.at(connection, {
      orderId: createdOrder.id,
      orderSnapshotId: randomSnapshotId,
    })
  );
  // Step 6: Insufficient permission test (not implemented here, as customer/admin login is not available in API SDK)
}

