import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderStatusHistory";
import type { IPageIShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderStatusHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate customer status history search for their orders.
 *
 * This test ensures that a customer can view the status history for their own order. The order is first created, then its status is changed multiple times (creating history records). The search endpoint is called, and all history records for that order are retrieved, verifying correct ordering, all fields, and pagination works. Access control is validated by confirming that only records for this specific order are returned.
 *
 * Test Steps:
 * 1. Create an order as a customer.
 * 2. Add several status history records for this order.
 * 3. Search order status histories using pagination (limit=2, multi-page if possible).
 * 4. Confirm all status history records are returned in the correct order with correct fields and values matching those created.
 * 5. Confirm pagination metadata is accurate.
 */
export async function test_api_order_status_history_search_customer_success(connection: api.IConnection) {
  // 1. Create an order as customer
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const initial_status = "created";
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 25000,
      currency_code: "KRW",
      current_status: initial_status,
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(order);

  // 2. Add multiple status history records for the order
  const statusSteps = [
    { previous: "created", next: "paid" },
    { previous: "paid", next: "shipped" },
    { previous: "shipped", next: "delivered" },
  ];
  const histories: IShoppingMallAiBackendOrderStatusHistory[] = [];
  for (const step of statusSteps) {
    const history = await api.functional.shoppingMallAiBackend.customer.orders.orderStatusHistories.create(connection, {
      orderId: order.id,
      body: {
        previous_status: step.previous,
        new_status: step.next,
        actor_type: "customer",
        actor_id: customer_id,
        occurred_at: new Date().toISOString(),
      } satisfies IShoppingMallAiBackendOrderStatusHistory.ICreate,
    });
    typia.assert(history);
    histories.push(history);
    // Add a small delay for realistic occurred_at spread
    await new Promise((res) => setTimeout(res, 5));
  }

  // 3. Search histories - limit = 2, should have 2 pages for 3 history records
  const limit = 2;
  const page1 = await api.functional.shoppingMallAiBackend.customer.orders.orderStatusHistories.search(connection, {
    orderId: order.id,
    body: {
      page: 1,
      limit,
      order_id: order.id,
    } satisfies IShoppingMallAiBackendOrderStatusHistory.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("page 1 size")(page1.data.length)(2);
  TestValidator.equals("pagination current")(page1.pagination.current)(1);
  TestValidator.equals("limit")(page1.pagination.limit)(limit);

  // 4. Second page (if available)
  let allPages: IShoppingMallAiBackendOrderStatusHistory[] = [
    ...page1.data,
  ];
  if (page1.pagination.pages > 1) {
    const page2 = await api.functional.shoppingMallAiBackend.customer.orders.orderStatusHistories.search(connection, {
      orderId: order.id,
      body: {
        page: 2,
        limit,
        order_id: order.id,
      } satisfies IShoppingMallAiBackendOrderStatusHistory.IRequest,
    });
    typia.assert(page2);
