 *
 * This test ensures that an authenticated admin can remove an order snapshot for audit or compliance justification. It requires an admin registration and authenticated session, and a created order snapshot record. The workflow covers privileged deletion, success confirmation, and post-condition validation (actual erasure or logical removal by soft-delete).
 *
 * Steps:
 * 1. Register a new admin account for test isolation and compliance visibility.
 * 2. Simulate access to an order (using a random UUID for test as real order creation is outside scope).
 * 3. Create a snapshot of this order for audit/review (simulate payload).
 * 4. Perform deletion as this admin on the snapshot, by id.
 * 5. Attempt to fetch the snapshot again to ensure it is removed or marked according to business rules.
 * 6. Validate that the delete operation was successful by confirming that the snapshot has been deleted or is not accessible anymore.
 * 7. Optionally, try deleting a non-existent snapshot to ensure proper error handling (should throw).
 */
export async function test_api_order_snapshot_delete_by_admin_for_compliance_removal(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongPass!123";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAuth);

  // 2. Generate a test order ID (simulate order existence)
  const orderId = typia.random<string & tags.Format<"uuid">>();

  // 3. Create an order snapshot as the admin
  const snapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.create(connection, {
    orderId,
    body: {
      snapshot_json: JSON.stringify({ order: orderId, time: new Date().toISOString() }),
      snapshot_reason: "unit-test: compliance delete",
    } satisfies IShoppingMallAiBackendOrderSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 4. Delete the snapshot as the admin
  await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.erase(connection, {
    orderId,
    orderSnapshotId: snapshot.id,
  });

  // 5. Try deleting the same snapshot again (should error, confirms idempotency/soft delete)
  await TestValidator.error("cannot delete already deleted snapshot")(() =>
    api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.erase(connection, {
      orderId,
      orderSnapshotId: snapshot.id,
    })
  );
}

