import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin-side deletion behavior for non-existent or already-deleted external customer links.
 *
 * This scenario ensures that, as an admin, attempting to soft-delete an external login/social/OAuth link by ID on behalf of a customer (via the admin endpoint) returns the correct not-found/idempotent response. The deletion attempt must not affect other records, and such attempts should be auditable for compliance.
 *
 * Process:
 * 1. Register and authenticate a new admin, as required by system policy.
 * 2. As admin, attempt to delete an external link using random UUIDs for both customer and externalLink (ensuring the link does not actually exist).
 * 3. Validate the API properly handles the case: expecting an error or silent idempotent success, with no side effects on other data.
 * 4. (Optional edge case): Repeat with the same UUIDs to simulate "already deleted" state. Confirm same idempotent or error handling applies.
 */
export async function test_api_admin_external_link_delete_nonexistent_or_already_deleted(connection: api.IConnection) {
  // 1. Admin registration & authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminRegistration = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "strongTestPassword!1"
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminRegistration);

  // 2. Attempt to delete an external link that does not exist
  const randomCustomerId = typia.random<string & tags.Format<"uuid">>();
  const randomExternalLinkId = typia.random<string & tags.Format<"uuid">>();

  // 3. Expect either an error (not found) or a silent idempotent no-op success. Either is acceptable for idempotent deletion.
  await TestValidator.error("Should reject non-existent external link deletion")(
    () => api.functional.shoppingMallAiBackend.admin.customers.externalLinks.erase(
      connection,
      {
        customerId: randomCustomerId,
        externalLinkId: randomExternalLinkId
      }
    )
  );

  // 4. (Optional) Try deleting again to simulate already-deleted state – should again be error or idempotent ok.
  await TestValidator.error("Should still reject repeated/\"already deleted\" external link deletion")(
    () => api.functional.shoppingMallAiBackend.admin.customers.externalLinks.erase(
      connection,
      {
        customerId: randomCustomerId,
        externalLinkId: randomExternalLinkId
      }
    )
  );
}

