/**
 * End-to-end test for the coupon history soft delete operation with admin constraints and audit requirements.
 *
 * This test ensures that:
 * 1. Admin is authenticated to perform soft-delete.
 * 2. A coupon history record can be created and soft-deleted.
 * 3. After deletion, the record is no longer fetchable via normal queries, but can still be present in audit logs as per compliance (subset of this check).
 * 4. Deleting a non-existent or already-deleted record responds with idempotent (ok) or not found result per API rules.
 * 5. Non-admin (unauthorized) delete attempts are rejected with a proper error.
 *
 * Process Steps:
 * 1. Login as admin with valid credentials.
 * 2. Create a new coupon history record via the admin API.
 * 3. Soft-delete the created coupon history record as admin.
 * 4. Verify delete is successful (no error thrown and returns void).
 * 5. (Best effort) Attempt to fetch the deleted coupon history record (should fail or not be present).
 * 6. Attempt to delete again the same coupon history record (should get not found/idempotent per API contract).
 * 7. Attempt to delete a random non-existent coupon history id (should get not found/idempotent per API contract).
 * 8. Attempt to perform delete without admin authentication (should fail as unauthorized).
 */
export async function test_api_coupon_history_soft_delete_and_constraints(connection: api.IConnection) {
  // 1. Login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "securePass123!";
  // Precondition: Admin must already exist for login – assumes admin user already provisioned with known credentials
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);

  // 2. Create a coupon history record
  const couponHistoryCreate = await api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
    body: {
      issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
      actor_id: adminAuth.adminId,
      actor_type: adminAuth.role,
      action: "issued",
      action_at: new Date().toISOString(),
      remarks: "E2E soft delete test",
    } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
  });
  typia.assert(couponHistoryCreate);

  // 3. Soft-delete the coupon history record
  await api.functional.shoppingMallAiBackend.admin.couponHistories.erase(connection, {
    couponHistoryId: couponHistoryCreate.id,
  });

  // 4. (Optional) Attempt to fetch deleted coupon history should fail or not be found (no GET method documented, so this step may be omitted or stubbed)
  // 5. Attempt to delete the same record again – should be idempotent or fail gracefully
  await api.functional.shoppingMallAiBackend.admin.couponHistories.erase(connection, {
    couponHistoryId: couponHistoryCreate.id,
  });

  // 6. Attempt to delete a random non-existent coupon history id
  await api.functional.shoppingMallAiBackend.admin.couponHistories.erase(connection, {
    couponHistoryId: typia.random<string & tags.Format<"uuid">>(),
  });

  // 7. Logout or clear authorization, then try to delete (simulate non-admin/unauthenticated)
  const unauthConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized delete fails")(() =>
    api.functional.shoppingMallAiBackend.admin.couponHistories.erase(unauthConnection, {
      couponHistoryId: couponHistoryCreate.id,
    }),
