import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendArticleCategory";
import type { IPageIShoppingMallAiBackendArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendArticleCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for advanced admin search & pagination on article categories.
 *
 * This test validates that the admin article category search endpoint supports multiple filter/search scenarios, including:
 *  - Partial search by code and name
 *  - Parent-child tree filtering (parent_id as root and nested)
 *  - Active/inactive status filter
 *  - Pagination robustness (more than one page, correct limit/page)
 *
 * The test ensures only admin can access, and invalid search input returns error.
 *
 * Steps:
 * 1. Create a root category (no parent)
 * 2. Create 5+ child categories with parent structure
 * 3. Create several more categories (different codes/names, a mix of active/inactive and roots/children)
 * 4. Perform search with:
 *     - Name partial match (should match relevant names only)
 *     - Code partial match (should match only code subset)
 *     - parent_id filter (tree separation, only matching children or roots)
 *     - is_active filter (return only active/inactive accordingly)
 *     - Combined filters (e.g. parent_id + is_active)
 *     - Pagination (limit=2, page=2, etc. check boundaries and total page count)
 * 5. Validate search results each time (correct hits, correct total count, records on correct page)
 * 6. Attempt search as unauthorized user (simulate) and expect error
 * 7. Send invalid search filter (e.g., negative limit or page, impossible filter) and expect error.
 */
export async function test_api_article_category_advanced_search_admin(connection: api.IConnection) {
  // 1. Create root category
  const root = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
    body: {
      parent_id: null,
      name: "RootCat",
      code: "ROOT",
      sort_order: 0,
      is_active: true,
    }
  });
  typia.assert(root);

  // 2. Create 5+ children under root
  const children = await Promise.all(ArrayUtil.repeat(5)(i =>
    api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
      body: {
        parent_id: root.id,
        name: `ChildCat${i+1}`,
        code: `CHILD${i+1}`,
        sort_order: i + 1,
        is_active: true,
      }
    })
  ));
  children.forEach(typia.assert);

  // 3. Create more categories (varied: roots, children, codes, names, is_active)
  const mixA = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
    body: {
      parent_id: null,
      name: "FAQ",
      code: "FAQA",
      sort_order: 99,
      is_active: false,
    }
  });
  typia.assert(mixA);
  const mixB = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
    body: {
      parent_id: mixA.id,
      name: "InactiveChild",
      code: "INACTIVECHILD",
      sort_order: 100,
      is_active: false,
    }
  });
  typia.assert(mixB);

  // 4a. Search by name (partial)
  let res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {body: {name: "ChildCat"}});
  typia.assert(res);
  TestValidator.predicate("all names include keyword")(
    res.data.every(c => c.name.includes("ChildCat"))
  );
  TestValidator.predicate("contains all children")(
    children.every(child => res.data.some(c => c.id === child.id))
  );

  // 4b. Search by code (partial)
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {body: {code: "CHILD"}});
  typia.assert(res);
  TestValidator.predicate("all codes include keyword")(
    res.data.every(c => c.code.includes("CHILD"))
  );

  // 4c. Filter by parent_id (should return only direct children of root)
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {body: {parent_id: root.id}});
  typia.assert(res);
  TestValidator.equals("direct child count")(res.data.length)(children.length);
  TestValidator.predicate("all have parent_id=root.id")(
    res.data.every(c => c.parent_id === root.id)
  );

  // 4d. Filter by is_active = false
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {body: {is_active: false}});
  typia.assert(res);
  TestValidator.predicate("all inactive")(
    res.data.every(c => c.is_active === false)
  );
  TestValidator.predicate("mixA and mixB are found")(
    [mixA.id, mixB.id].every(id => res.data.some(c => c.id === id))
  );

  // 4e. Combined filter: parent_id + is_active=false
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {body: {parent_id: mixA.id, is_active: false}});
  typia.assert(res);
  TestValidator.predicate("only InactiveChild returned")(
    res.data.length === 1 && res.data[0].id === mixB.id
  );

  // 4f. Pagination test: add extra categories for paging
  const pagecats = await Promise.all(ArrayUtil.repeat(4)(i =>
    api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
      body: {
        parent_id: null,
        name: `PageCat${i+1}`,
        code: `PAGE${i+1}`,
        sort_order: 100 + i,
        is_active: true,
      }
    })
  ));
  pagecats.forEach(typia.assert);

  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {body: {name: "PageCat", limit: 2, page: 1}});
  typia.assert(res);
  TestValidator.equals("should be limited to 2 results")(res.data.length)(2);
  TestValidator.equals("pagination info, page 1")(res.pagination.current)(1);
  TestValidator.equals("total pages at least 2")(
    res.pagination.pages >= 2
  )(true);

  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {body: {name: "PageCat", limit: 2, page: 2}});
  typia.assert(res);
  TestValidator.equals("should be limited to 2 results")(res.data.length)(2);
  TestValidator.equals("pagination info, page 2")(res.pagination.current)(2);

  // 5. Unauthorized access: simulate non-admin, or invalid token if available (expect error)
  if (connection.headers) {
    const fakeConnection = {...connection, headers: {...connection.headers, Authorization: "Bearer FAKEINVALIDTOKEN"}};
    await TestValidator.error("unauthorized fails")(
      () => api.functional.shoppingMallAiBackend.admin.articleCategories.search(fakeConnection, {body: {}})
    );
  }

  // 6. Invalid filter (e.g. negative page/limit) expect error
  await TestValidator.error("invalid limit")(
    () => api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {body: {limit: -1, page: 1}})
  );
  await TestValidator.error("invalid page")(
    () => api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {body: {limit: 1, page: -2}})
  );
  // Impossible filter (parent_id nonsense)
  await TestValidator.error("impossible parent_id")(
    () => api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {body: {parent_id: "deadbeef"}})
  );
}

