/**
 * Validate seller-side deletion of a non-existent (or already deleted) product inquiry.
 *
 * This test ensures that when a seller tries to delete a product inquiry that does not exist (for example, it has already been deleted), the API responds correctly, either by returning a not-found error or by operating idempotently without side effects.
 *
 * Step-by-step process:
 * 1. Register a new product as a seller.
 * 2. Register a product inquiry as a customer for that product.
 * 3. Delete the inquiry as a seller (soft delete).
 * 4. Attempt to delete the same inquiry again as a seller – this should trigger 'not found' or safe idempotent behavior.
 */
export async function test_api_product_inquiry_delete_seller_not_found(connection: api.IConnection) {
  // 1. Register a new product (simulate seller user context if authentication required)
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(2),
      main_image_uri: null,
      status: "published"
    }
  });
  typia.assert(product);

