  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: product.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(2),
      public: true,
    }
  });
  typia.assert(inquiry);

  // 3. Delete (soft delete) the inquiry as seller
  await api.functional.shoppingMallAiBackend.seller.productInquiries.erase(connection, { productInquiryId: inquiry.id });

  // 4. Try deleting again – should raise error or be idempotent
  await TestValidator.error("double delete yields error")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.productInquiries.erase(connection, { productInquiryId: inquiry.id });
    }
  );
}

