/**
 * Validate that a customer cannot access another customer's account history via the customer endpoint, enforcing strict permission.
 *
 * This test simulates two distinct customers using the customer API:
 * 1. Register two separate customer accounts (customerA and customerB).
 * 2. With customerA (active session), attempt to view the account history for customerB.
 * 3. The system must deny permission—history data for customerB must not be accessible to customerA under any scenario. No sensitive data should be returned.
 *
 * Steps:
 * 1. Register customerA. (JWT authorization for customerA is set)
 * 2. Register customerB. (JWT for customerB, but session remains as customerB after registration!)
 * 3. Switch session back to customerA (using API customer registration again for login/auth context—the API seems to use sign up to refresh tokens for the tests).
 * 4. Attempt to access the history of customerB using customerA's credentials, using the /shoppingMallAiBackend/customer/customers/{customerId}/histories endpoint, with customerId = customerB.id.
 * 5. Validate the response: access should be denied—either an error is thrown or response data is empty (depending on backend implementation).
 *
 * The key business rule is that customers must never be able to view or enumerate the histories of other customers, whether by brute force, enumeration, or API call misuse.
 */
export async function test_api_customer_history_search_permission_denied_for_others(connection: api.IConnection) {
  // 1. Register customerA
  const customerAEmail = typia.random<string & tags.Format<"email">>();
  const customerA = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerAEmail,
      password: "Password123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(10),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerA);

  // 2. Register customerB (and obtain its id for test)
  const customerBEmail = typia.random<string & tags.Format<"email">>();
  const customerB = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerBEmail,
      password: "Password123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(10),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerB);
  // After this registration, session is customerB (JWT in connection)

  // 3. Switch back to customerA context by logging in (simulated via signUp for test env)
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerAEmail,
      password: "Password123!",
      name: customerA.customer.name,
      nickname: customerA.customer.nickname,
      phone: customerA.customer.phone,
    } satisfies ICustomerSignUp.Request
  });

  // 4. Attempt to access the history of customerB using customerA's authorization
  //    - customerA is now authenticated in connection
  //    - Should fail with error or empty data
  await TestValidator.error("should deny access to other customer's history")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.histories.search(connection, {
      customerId: customerB.customer.id,
      body: {
        customer_id: customerB.customer.id,
        page: 1,
        limit: 5,
      } satisfies IShoppingMallAiBackendCustomerHistory.IRequest
    });
  });
}

