import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Test retrieval of self and another customer's profile by customerId.
 *
 * Validates that:
 * 1. A customer (after registration and login) can fetch their full profile via /shoppingMallAiBackend/customer/customers/{customerId}, with all fields (audit, sensitive) visible for themselves.
 * 2. The same customer cannot fetch another customer's profile: access is forbidden or certain fields are masked.
 * 3. Non-existent customerId returns not found or forbidden.
 * 4. Soft-deleted customers (deleted_at set) cannot be accessed or return not found/forbidden.
 *
 * Steps:
 * 1. Register Customer A and Customer B (receiving both customerIds and tokens).
 * 2. As Customer A:
 *   - Fetch /customer/customers/{customerA.id} -> all profile fields visible (e.g., audit fields).
 *   - Fetch /customer/customers/{customerB.id} -> access denied/fields masked or forbidden error (TestValidator.error)
 *   - Fetch with random UUID -> expect not found or forbidden (TestValidator.error)
 * 3. As Customer B:
 *   - (repeat analogue for self and other access)
 * 4. (Optionally, soft-delete Customer B in DB and verify fetch by Customer B or A is forbidden/not found.)
 *
 * Validation: Strictly check full field set visibility for self, absence/masking for other; and all error/forbidden behaviors.
 */
export async function test_api_customer_self_profile_access_and_forbidden(connection: api.IConnection) {
  // Register Customer A
  const customerAInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password1!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  } satisfies ICustomerSignUp.Request;
  const signUpA = await api.functional.auth.customer.register.signUp(connection, { body: customerAInput });
  typia.assert(signUpA);
  const customerA = signUpA.customer;
  const tokenA = signUpA.setHeaders.Authorization;

  // Register Customer B
  const customerBInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password1!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  } satisfies ICustomerSignUp.Request;
  const signUpB = await api.functional.auth.customer.register.signUp(connection, { body: customerBInput });
  typia.assert(signUpB);
  const customerB = signUpB.customer;
  const tokenB = signUpB.setHeaders.Authorization;

  // Helper for switching "connection" authorization tokens
  const setAuth = (token: string) => {
    connection.headers = { ...connection.headers, Authorization: token };
  };

  // ---- Test as Customer A ----
  setAuth(tokenA);
  // a) Self fetch: full profile should be available
  const profileA = await api.functional.shoppingMallAiBackend.customer.customers.at(connection, { customerId: customerA.id });
  typia.assert(profileA);
  TestValidator.equals("self profile - id")(profileA.id)(customerA.id);
  TestValidator.equals("self profile - email")(profileA.email)(customerA.email);
  TestValidator.equals("self profile - name")(profileA.name)(customerA.name);
  TestValidator.equals("self profile - phone")(profileA.phone)(customerA.phone);
  TestValidator.equals("self profile - status")(profileA.status)(customerA.status);
  // critical audit fields visible:
  TestValidator.equals("self profile - joined_at")(profileA.joined_at)(customerA.joined_at);
  TestValidator.equals("self profile - email_verified")(profileA.email_verified)(customerA.email_verified);
  // b) Try fetching Customer B: forbidden or masked
  TestValidator.error("cannot access another customer's profile")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.at(connection, { customerId: customerB.id })
  );
  // c) Try fetching random (nonexistent) UUID
  TestValidator.error("non-existent customerId forbidden/not found")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.at(connection, { customerId: typia.random<string & tags.Format<"uuid">>() })
  );

  // ---- Test as Customer B ----
  setAuth(tokenB);
  // a) Self fetch
  const profileB = await api.functional.shoppingMallAiBackend.customer.customers.at(connection, { customerId: customerB.id });
  typia.assert(profileB);
  TestValidator.equals("self profile - id")(profileB.id)(customerB.id);
  // b) Fetch Customer A: forbidden
  TestValidator.error("cannot access another customer's profile")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.at(connection, { customerId: customerA.id })
  );

  // Skipping soft-delete test (needs out-of-band DB access or an API that doesn't exist)
}

