 *   - Authorization: only inquiries favorited by the authenticated customer are returned
 *   - Exclusion of soft-deleted (unfavorited) records
 *   - Edge cases: empty sets, invalid pagination, and unauthenticated access
 *
 * Steps:
 * 1. Favorite multiple inquiries as the test customer
 * 2. Search with default (empty) filters, validate output contains only active, non-deleted records belonging to customer
 * 3. Search with filtering (inquiry_id, from_date—to_date, query)
 * 4. Test pagination (page, limit), verify limits and page boundaries
 * 5. Unfavorite (soft delete) a favorite and ensure search excludes it
 * 6. Attempt to search as unauthenticated or invalid user (expect error)
 * 7. Try out-of-bounds pagination (expect empty data)
 */
export async function test_api_favorite_inquiry_search_with_pagination_and_filtering(connection: api.IConnection) {
  // Step 1: Create three favorite inquiries for the current (authenticated) customer
  const favorite1 = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.create(connection, { body: { inquiry_id: typia.random<string & tags.Format<"uuid">>() } });
