  const ids = [favorite1.id, favorite2.id, favorite3.id];
  ids.forEach(id => TestValidator.predicate(`favorite id ${id} in the results`)(allPage.data.some(x => x.id === id && !x.deleted_at)));

  // Step 3: Filtered search by inquiry_id, by date, and by query
  {
    // By inquiry_id (should return only matching favorite)
