import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate failure of admin password change for invalid current password scenario.
 *
 * This test checks the system's behavior when an authenticated admin attempts to change their password but supplies an incorrect current password. It ensures security controls prevent password updates without legitimate credentials and returns a proper error response.
 *
 * 1. Register a new admin using unique credentials to establish an isolated admin account for testing.
 * 2. Login as the registered admin to obtain a valid session and set authentication headers on the connection.
 * 3. Attempt to change password using an incorrect current password and a valid, policy-compliant new password.
 * 4. Assert that the password change operation fails: the response indicates failure, and a meaningful error message is returned.
 * 5. Optionally, attempt to log in with the new password to confirm it has NOT been set.
 * 6. Optionally, attempt to log in with the original password to confirm it still works (i.e., password was not changed by the failed attempt).
 * 7. (If technically possible) Confirm that an audit log entry or security event was generated for this failed password change attempt.
 */
export async function test_api_admin_auth_change_password_invalid_current(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = "TestPassword!123";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);

  // 2. Log in as the newly registered admin
  const auth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(auth);

  // 3. Attempt to change password with an incorrect current password
  const wrongCurrentPassword = "TotallyWrongCurrentPassword!999";
  const newPassword = "NewPassword#567";
  const result = await api.functional.auth.admin.password.changePassword(connection, {
    body: {
      currentPassword: wrongCurrentPassword,
      newPassword,
    } satisfies IAdminAuth.ChangePassword,
  });
  typia.assert(result);

  // 4. Assert the password change was unsuccessful
  TestValidator.equals("password change should fail")(result.success)(false);
  TestValidator.predicate("error message present")(
    typeof result.message === "string" && result.message.length > 0,
  );

  // 5. Attempt to log in with the new password (should fail)
  await TestValidator.error("new password should not work")(async () => {
    await api.functional.auth.admin.login.signIn(connection, {
      body: {
        email,
        password: newPassword,
      } satisfies IAdminAuth.SignIn,
    });
  });

  // 6. Confirm login with original password still works
  const relogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(relogin);
}

