import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendComplianceEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceEvent";
import type { IShoppingMallAiBackendComplianceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceSnapshot";
import type { IPageIShoppingMallAiBackendComplianceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendComplianceSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates admin search, filtering, and pagination over compliance snapshots for a specific compliance event.
 *
 * This test simulates a realistic forensic/audit scenario: an admin creates a compliance event with multiple attached compliance snapshots (snapshots are evidence records of entity states under audit). The test then queries the system to search and paginate these snapshots, validating correct retrieval and the integrity of audit evidence.
 *
 * Steps:
 * 1. Create a compliance event for a test action (as admin)
 * 2. Attach multiple compliance snapshots representing different entities or payload states to that event
 * 3. Query (search) for compliance snapshots under that event
 *    - Test filtering by entity type and entity_id
 *    - Test pagination by page number and page_size
 *    - Check sort parameter usage
 * 4. Verify:
 *    - Only matching snapshots are returned (audit completeness)
 *    - Pagination metadata (page number, page size, total records, etc) is correct
 *    - Filtering (by entity_type/entity_id) returns only correct records
 *    - The data returned matches those written during step 2
 */
export async function test_api_compliance_event_compliance_snapshots_search_success(connection: api.IConnection) {
  // 1. Create compliance event
  const complianceEventInput = {
    event_type: "test_audit_automation",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    actor_type: "admin",
    target_type: "test_target_domain",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    event_payload: JSON.stringify({ info: "forensic event simulation" }),
  } satisfies IShoppingMallAiBackendComplianceEvent.ICreate;
  const event = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, { body: complianceEventInput });
  typia.assert(event);

  // 2. Attach multiple compliance snapshots (mixed entities, different IDs)
  const testEntities = [
    { entity_type: "customer", info: "customer audit" },
    { entity_type: "product", info: "product audit" },
    { entity_type: "order", info: "order audit" },
    { entity_type: "customer", info: "duplicate entity type" },
  ];
  const snapshots = await ArrayUtil.asyncMap(testEntities)(async (ent) => {
    const createInput = {
      compliance_event_id: event.id,
      entity_type: ent.entity_type,
      entity_id: typia.random<string & tags.Format<"uuid">>(),
      snapshot_payload: JSON.stringify({ label: ent.info, unix: Date.now() }),
    } satisfies IShoppingMallAiBackendComplianceSnapshot.ICreate;
    const snapshot = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.create(connection, {
      complianceEventId: event.id,
      body: createInput,
    });
    typia.assert(snapshot);
    return snapshot;
  });

  // 3a. Search all snapshots for this event
  const searchAllResult = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.searchByComplianceEvent(connection, {
    complianceEventId: event.id,
    body: {
      compliance_event_id: event.id,
      page: 1,
      page_size: 10,
      sort: "created_at:asc",
    },
  });
  typia.assert(searchAllResult);
  TestValidator.equals("All snapshots count")(searchAllResult.data.length)(snapshots.length);
  TestValidator.equals("Pagination total records")(searchAllResult.pagination.records)(snapshots.length);
  TestValidator.equals("First snapshot id matches")(searchAllResult.data[0].compliance_event_id)(event.id);

  // 3b. Filter by entity_type ("customer")
  const filterTypeResult = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.searchByComplianceEvent(connection, {
    complianceEventId: event.id,
    body: {
      compliance_event_id: event.id,
      entity_type: "customer",
    },
  });
  typia.assert(filterTypeResult);
  filterTypeResult.data.forEach((row) =>
    TestValidator.equals("entity_type matches")(row.entity_type)("customer")
  );
  TestValidator.predicate("Filter count matches")(
    filterTypeResult.data.length === snapshots.filter((s) => s.entity_type === "customer").length
  );

  // 3c. Filter by specific entity_id
  const entityIdToSearch = snapshots[2].entity_id;
  const entityIdResult = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.searchByComplianceEvent(connection, {
    complianceEventId: event.id,
    body: {
      compliance_event_id: event.id,
      entity_id: entityIdToSearch,
    },
  });
  typia.assert(entityIdResult);
  TestValidator.equals("Entity id count matches")(entityIdResult.data.length)(1);
  TestValidator.equals("Entity id matches")(entityIdResult.data[0].entity_id)(entityIdToSearch);

  // 3d. Test pagination (page 1, page_size 2)
  const pageSize = 2;
  const page1Result = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.searchByComplianceEvent(connection, {
    complianceEventId: event.id,
    body: {
      compliance_event_id: event.id,
      page: 1,
      page_size: pageSize,
    },
  });
  typia.assert(page1Result);
  TestValidator.equals("Page 1 correct length")(page1Result.data.length)(pageSize);
  TestValidator.equals("Page 1 page value")(page1Result.pagination.current)(1);

  // 3e. Test pagination (page 2)
  const page2Result = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.searchByComplianceEvent(connection, {
    complianceEventId: event.id,
    body: {
      compliance_event_id: event.id,
      page: 2,
      page_size: pageSize,
    },
  });
  typia.assert(page2Result);
  TestValidator.equals("Page 2 correct length")(page2Result.data.length)(snapshots.length - pageSize);
  TestValidator.equals("Page 2 page value")(page2Result.pagination.current)(2);
}

