import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import type { IShoppingMallAiBackendCoinBalance } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinBalance";
import type { IPageIShoppingMallAiBackendCoinBalance } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCoinBalance";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching and paginating coin wallet balance records for a specified wallet as an admin.
 *
 * This test validates that an admin can retrieve paginated and filtered results for wallet balances in the shopping mall system. It simulates the real-world scenario where balances are audited, filtered by date and balance range, and paged through for reporting or investigation purposes.
 *
 * Steps:
 * 1. Create a new coin wallet (admin-level wallet).
 * 2. Create multiple coin balance records for the created wallet, each with varying balances and timestamps.
 * 3. Use the search API (PATCH) to filter balances by:
 *    a. Balance date range (balance_at_from, balance_at_to)
 *    b. Balance value (min_balance, max_balance)
 *    c. Pagination (page, limit)
 * 4. Assert that only results that match the filter criteria and respect pagination are returned.
 * 5. Test error handling by:
 *    a. Using an invalid coinWalletId
 *    b. Passing invalid filters (e.g., min_balance > max_balance, limit = 0)
 *    c. (Cannot test lack of admin authorization in isolation; API does not expose user context for such a switch.)
 */
export async function test_api_coin_wallet_balance_search_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Create a new coin wallet (admin-level)
  const wallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
      wallet_type: "mainnet",
      wallet_status: "active",
      wallet_address: RandomGenerator.alphabets(12),
      wallet_label: "Admin Main Wallet",
      security_code: null
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate
  });
  typia.assert(wallet);

  // 2. Create multiple coin balance items for different timestamps and balances
  const timestamps = [
    new Date(Date.now() - 1000 * 3600 * 24).toISOString(),
    new Date().toISOString(),
    new Date(Date.now() + 1000 * 3600 * 24).toISOString(),
  ];
  const balances = [1000, 5000, 2000];
  const createdBalances = [] as IShoppingMallAiBackendCoinBalance[];
  for (let i = 0; i < 3; ++i) {
    const balance = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.create(connection, {
      coinWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        balance: balances[i],
        balance_at: timestamps[i]
      } satisfies IShoppingMallAiBackendCoinBalance.ICreate
    });
    typia.assert(balance);
    createdBalances.push(balance);
  }

  // 3. Search: filter by date range
  {
    const from = timestamps[0];
    const to = timestamps[1];
    const output = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
      coinWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        balance_at_from: from,
        balance_at_to: to,
        page: 1,
        limit: 10
      } satisfies IShoppingMallAiBackendCoinBalance.IRequest
    });
    typia.assert(output);
    TestValidator.predicate("date filtering")(
      output.data.every(b => b.balance_at >= from && b.balance_at <= to)
    );
  }

  // 4. Search: filter by balance range
  {
    const min = 1000;
    const max = 3000;
    const output = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
      coinWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        min_balance: min,
        max_balance: max,
        page: 1,
        limit: 10
      } satisfies IShoppingMallAiBackendCoinBalance.IRequest
    });
    typia.assert(output);
    TestValidator.predicate("balance range filtering")(
      output.data.every(b => b.balance >= min && b.balance <= max)
    );
  }

  // 5. Pagination test: set limit to 2, expect max 2 records
  {
    const output = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
      coinWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        page: 1,
        limit: 2
      } satisfies IShoppingMallAiBackendCoinBalance.IRequest
    });
    typia.assert(output);
    TestValidator.predicate("pagination")(
      output.data.length <= 2 && output.pagination.limit === 2
    );
  }

  // 6. Error: invalid coinWalletId (random UUID which doesn't exist)
  {
    await TestValidator.error("invalid coinWalletId")(() =>
      api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
        coinWalletId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          wallet_id: typia.random<string & tags.Format<"uuid">>(),
          page: 1,
          limit: 10
        } satisfies IShoppingMallAiBackendCoinBalance.IRequest
      })
    );
  }

  // 7. Error: min_balance > max_balance
  {
    await TestValidator.error("invalid balance range")(() =>
      api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
        coinWalletId: wallet.id,
        body: {
          wallet_id: wallet.id,
          min_balance: 2000,
          max_balance: 1000,
          page: 1,
          limit: 10
        } satisfies IShoppingMallAiBackendCoinBalance.IRequest
      })
    );
  }

  // 8. Error: limit = 0
  {
    await TestValidator.error("zero limit")(() =>
      api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
        coinWalletId: wallet.id,
        body: {
          wallet_id: wallet.id,
          page: 1,
          limit: 0
        } satisfies IShoppingMallAiBackendCoinBalance.IRequest
      })
    );
  }
}

