import type { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import type { IShoppingMallAiBackendCoinBalance } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinBalance";
import type { IPageIShoppingMallAiBackendCoinBalance } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCoinBalance";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching and paginating coin wallet balance records for a specified wallet as an admin.
 *
 * This test validates that an admin can retrieve paged and filtered results for wallet balances in the shopping mall system. Simulates scenarios where balances are reviewed for audits, analytics, or investigations. Ensures all search criteria (date range, balance range, paging) are honored, and appropriate error handling is in place.
 *
 * Step-by-step workflow:
 * 1. Create an admin coin wallet to associate balances for testing.
 * 2. Insert multiple coin balance records with varying balances and snapshot times.
 * 3. Search balances using:
 *    a. Date range filter (balance_at_from/to)
 *    b. Balance value range (min_balance/max_balance)
 *    c. Pagination (page/limit)
 * 4. Assert that search returns only balances that match filter constraints and result paging.
 * 5. Test error scenarios: invalid wallet id, illogical filters, and invalid pagination.
 */
export async function test_api_coin_wallet_balance_search_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Create a new admin coin wallet for testing
  const wallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
      wallet_type: "mainnet",
      wallet_status: "active",
      wallet_address: RandomGenerator.alphabets(12),
      wallet_label: "Admin Main Wallet",
      security_code: null,
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate,
  });
  typia.assert(wallet);

  // 2. Create several coin balance entries at different times/balances
  const timestamps = [
    new Date(Date.now() - 2 * 86400_000).toISOString(),
    new Date(Date.now() - 1 * 86400_000).toISOString(),
    new Date().toISOString(),
  ];
  const balances = [1000, 2500, 5000];
  const createdBalances: IShoppingMallAiBackendCoinBalance[] = [];
  for (let i = 0; i < 3; ++i) {
    const balance = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.create(connection, {
      coinWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        balance: balances[i],
        balance_at: timestamps[i],
      } satisfies IShoppingMallAiBackendCoinBalance.ICreate,
    });
    typia.assert(balance);
    createdBalances.push(balance);
  }

  // 3a. Search balances by date range (should get first 2 only)
  {
    const from = timestamps[0];
    const to = timestamps[1];
    const output = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
      coinWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        balance_at_from: from,
        balance_at_to: to,
        page: 1,
        limit: 10,
      } satisfies IShoppingMallAiBackendCoinBalance.IRequest,
    });
    typia.assert(output);
    TestValidator.predicate("date range filter")(
      output.data.every(b => b.balance_at >= from && b.balance_at <= to)
    );
  }

  // 3b. Search balances by balance value range (should get all balances >= 1000 && <= 3000)
  {
    const min = 1000;
    const max = 3000;
    const output = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
      coinWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        min_balance: min,
        max_balance: max,
        page: 1,
        limit: 10,
      } satisfies IShoppingMallAiBackendCoinBalance.IRequest,
    });
    typia.assert(output);
    TestValidator.predicate("balance value range filter")(
      output.data.every(b => b.balance >= min && b.balance <= max)
    );
  }

  // 3c. Test pagination (limit 2 results)
  {
    const output = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
      coinWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        page: 1,
        limit: 2,
      } satisfies IShoppingMallAiBackendCoinBalance.IRequest,
    });
    typia.assert(output);
    TestValidator.predicate("pagination")(
      output.data.length <= 2 && output.pagination.limit === 2
    );
  }

  // 4a. Error: invalid coinWalletId (random UUID, not linked to wallet)
  {
    await TestValidator.error("invalid wallet id")(() =>
      api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
        coinWalletId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          wallet_id: typia.random<string & tags.Format<"uuid">>(),
          page: 1,
          limit: 10,
        } satisfies IShoppingMallAiBackendCoinBalance.IRequest,
      })
    );
  }

  // 4b. Error: min_balance > max_balance
  {
    await TestValidator.error("invalid balance range: min > max")(() =>
      api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
        coinWalletId: wallet.id,
        body: {
          wallet_id: wallet.id,
          min_balance: 4000,
          max_balance: 1000,
          page: 1,
          limit: 10,
        } satisfies IShoppingMallAiBackendCoinBalance.IRequest,
      })
    );
  }

  // 4c. Error: limit == 0
  {
    await TestValidator.error("zero limit")(() =>
      api.functional.shoppingMallAiBackend.admin.coinWallets.coinBalances.search(connection, {
        coinWalletId: wallet.id,
        body: {
          wallet_id: wallet.id,
          page: 1,
          limit: 0,
        } satisfies IShoppingMallAiBackendCoinBalance.IRequest,
      })
    );
  }
}

