import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteNotification";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test unauthorized deletion of a favorite notification by a non-owner customer. 
 * 
 * This test validates security around favorite notification deletion:
 * 
 * 1. Register two customers (A and B).
 * 2. Customer A creates a favorite notification via the API (using dummy product/inquiry/address reference and notification meta).
 * 3. Attempt to delete Customer A's notification while authenticated as Customer B, expect a permission-denied error.
 * 4. Confirm that the notification still exists and was not deleted by reading/creating any notification list or attempting deletion with the owner.
 * 
 * Steps:
 * 1. Register Customer A (owner of notification) and get the JWT token in connection.headers.
 * 2. Create a favorite notification as Customer A; collect the ID.
 * 3. Register Customer B (not the owner) and get the JWT token in connection.headers.
 * 4. As Customer B, attempt to DELETE the notification by its ID. Assert an error is thrown.
 * 5. Switch back to Customer A, and try to delete the notification (should succeed for owner). Optionally confirm via error on duplicate delete.
 */
export async function test_api_favorite_notification_unauthorized_access(connection: api.IConnection) {
  // 1. Register Customer A
  const customerAEmail = typia.random<string & tags.Format<"email">>();
  const customerAPassword = "testPwA";
  const customerARes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerAEmail,
      password: customerAPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerARes);

  // 2. Create favorite notification as Customer A
  const notification = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, {
    body: {
      favorite_product_id: typia.random<string & tags.Format<"uuid">>(),
      notification_type: "RESTOCK",
      notification_channel: "PUSH",
      read: false,
    } satisfies IShoppingMallAiBackendFavoriteNotification.ICreate,
  });
  typia.assert(notification);

  // 3. Register Customer B
  const customerBEmail = typia.random<string & tags.Format<"email">>();
  const customerBPassword = "testPwB";
  const customerBRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerBEmail,
      password: customerBPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerBRes);

  // 4. As Customer B, attempt unauthorized DELETE (B does not own notification)
  // (Connection will have B's Authorization after their registration)
  await TestValidator.error("Non-owner cannot delete notification")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteNotifications.erase(connection, {
      favoriteNotificationId: notification.id as string & tags.Format<"uuid">,
    }),
  );

  // 5. Switch back to Customer A and delete the notification (should succeed)
  // There is no login function, so we re-register; connection may maintain owner context due to JWT overwriting in setHeaders
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerAEmail,
      password: customerAPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  // Should now be Customer A context again; deleting the notification should work
  await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.erase(connection, {
    favoriteNotificationId: notification.id as string & tags.Format<"uuid">,
  });
}

