import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendChannel";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test soft-delete (logical deletion) of a business channel, ensuring non-admin users are forbidden from deleting channels.
 *
 * This function validates RBAC compliance and audit-trail enforcement by simulating a regular customer registering, then attempting to soft-delete a channel via the admin-only endpoint (DELETE /shoppingMallAiBackend/admin/channels/{channelId}).
 *
 * Steps performed:
 * 1. Register a fake customer (regular user) and obtain JWT token.
 * 2. Using an admin-authorized connection, create a new channel (capture ID).
 * 3. Switch to the customer account (JWT) by setting Authorization header to that customer's JWT value.
 * 4. Attempt to DELETE the channel using the customer's connection. Expect error: permission denied.
 * 5. Validate that the error is thrown (TestValidator.error), and ideally that the error response includes a compliance/audit code signaling RBAC enforcement. (Content validation is limited to occurrence, not message value).
 */
export async function test_api_channel_soft_delete_unauthorized(connection: api.IConnection) {
  // 1. Register customer and extract JWT
  const signUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "xY9!example",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpResponse);
  const customerJwt = signUpResponse.setHeaders.Authorization;

  // 2. Register a channel as admin (simulate admin session)
  //    We can generate an admin-uuid randomly for IShoppingMallAiBackendChannel.ICreate, since no admin login function is provided.
  const channel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      created_by_admin_id: typia.random<string & tags.Format<"uuid">>(),
      description: RandomGenerator.paragraph()(),
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channel);

  // 3. Switch connection to customer (overwrite Authorization to the customer's JWT)
  const customerConn: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: customerJwt,
    },
  };

  // 4. Attempt channel DELETE (should fail, as only admins allowed)
  await TestValidator.error("Soft-delete forbidden for non-admin")(
    async () => await api.functional.shoppingMallAiBackend.admin.channels.erase(customerConn, { channelId: channel.id }),
  );
}

