import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import type { IShoppingMallAiBackendCoinTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinTransaction";
import type { IPageIShoppingMallAiBackendCoinTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCoinTransaction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching for coin transactions in a coin wallet with filters and pagination
 *
 * This test validates the admin ability to retrieve a filtered and paginated list of coin transactions for a specific coin wallet.
 *
 * Steps:
 * 1. Create a new coin wallet (admin)
 * 2. Insert at least one coin transaction into that wallet
 * 3. Search for transactions by:
 *    - Wallet ID only (should find the inserted transaction)
 *    - Using a specific transaction type filter (should match)
 *    - Using an incorrect transaction type (should return empty)
 *    - Using reference_id, transaction_reason, and creation date/time filters
 *    - Pagination and ordering (limit, page, order_by, order_dir)
 *    - Invalid filter parameter (should fail or return empty)
 * 4. Negative: Try searching in a non-existent wallet (should fail or return empty)
 * 5. (If technically feasible) Try as a non-admin (should be permission denied, but omitted as only admin APIs are available)
 */
export async function test_api_coin_wallet_transaction_search_with_filters(connection: api.IConnection) {
  // 1. Create a new coin wallet
  const createWalletBody: IShoppingMallAiBackendCoinWallet.ICreate = {
    wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
    wallet_type: "reward",
    wallet_status: "active",
    wallet_address: RandomGenerator.alphaNumeric(32),
    wallet_label: "Test Wallet",
    security_code: "1234",
  };
  const wallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, { body: createWalletBody });
  typia.assert(wallet);

  // 2. Insert a coin transaction
  const transactionType = "deposit";
  const referenceId = RandomGenerator.alphaNumeric(12);
  const reason = "test deposit";
  const transactionAmount = 100.0;
  const transactionBody: IShoppingMallAiBackendCoinTransaction.ICreate = {
    wallet_id: wallet.id,
    transaction_type: transactionType,
    transaction_amount: transactionAmount,
    balance_after_transaction: transactionAmount,
    reference_id: referenceId,
    transaction_reason: reason,
  };
  const transaction = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.create(connection, { coinWalletId: wallet.id, body: transactionBody });
  typia.assert(transaction);

  // 3a. Search for transactions by wallet ID (should find the transaction)
  let response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, { coinWalletId: wallet.id, body: { wallet_id: wallet.id } });
  typia.assert(response);
  TestValidator.predicate("Should find at least one transaction")(response.data.length >= 1);
  TestValidator.equals("transaction matches")(response.data[0].id)(transaction.id);

  // 3b. Filter by transaction_type (should match)
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, { coinWalletId: wallet.id, body: { wallet_id: wallet.id, transaction_type: transactionType } });
  typia.assert(response);
  TestValidator.predicate("Filter by transaction_type should return results")(response.data.length >= 1);
  TestValidator.equals("transaction_type matches")(response.data[0].transaction_type)(transactionType);

  // 3c. Filter by wrong transaction_type (should return none)
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, { coinWalletId: wallet.id, body: { wallet_id: wallet.id, transaction_type: "withdrawal" } });
  typia.assert(response);
  TestValidator.equals("No transaction should match wrong type")(response.data.length)(0);

  // 3d. Filter by reference_id (should return the inserted one)
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, { coinWalletId: wallet.id, body: { wallet_id: wallet.id, reference_id: referenceId } });
  typia.assert(response);
  TestValidator.predicate("Should filter by reference_id")(response.data.some(t => t.id === transaction.id));

  // 3e. Filter by transaction_reason (should match)
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, { coinWalletId: wallet.id, body: { wallet_id: wallet.id, transaction_reason: reason } });
  typia.assert(response);
  TestValidator.predicate("Should filter by transaction_reason")(response.data.some(t => t.id === transaction.id));

  // 3f. Filter by created_from and created_to (broad range to include, should match)
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      created_from: new Date(Date.now() - 60 * 60 * 1000).toISOString(),
      created_to: new Date(Date.now() + 60 * 60 * 1000).toISOString()
    }
  });
  typia.assert(response);
  TestValidator.predicate("Should find transaction by date range")(response.data.some(t => t.id === transaction.id));

  // 3g. Test pagination: use limit = 1, page = 1
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      limit: 1,
      page: 1
    }
  });
  typia.assert(response);
  TestValidator.equals("Pagination limit")(response.pagination.limit)(1);
  TestValidator.predicate("Page should include transaction")(response.data.some(t => t.id === transaction.id));

  // 3h. Test order_by and order_dir
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      order_by: "created_at",
      order_dir: "desc"
    }
  });
  typia.assert(response);
  TestValidator.predicate("Should sort by created_at")(Array.isArray(response.data));

  // 3i. Invalid filter (e.g., bad page number: page = -1)
  await TestValidator.error("Invalid pagination parameter should throw")(() =>
    api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
      coinWalletId: wallet.id,
      body: { wallet_id: wallet.id, page: -1 }
    })
  );

  // 4. Try searching in a non-existent wallet
  response = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.search(connection, {
    coinWalletId: typia.random<string & tags.Format<"uuid">>(),
    body: { wallet_id: typia.random<string & tags.Format<"uuid">>() }
  });
  typia.assert(response);
  TestValidator.equals("Search in non-existent wallet should return 0 results")(response.data.length)(0);
}

