import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendPoint";
import type { IShoppingMallAiBackendPointHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendPointHistory";
import type { IPageIShoppingMallAiBackendPointHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendPointHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the search and pagination of point wallet transaction histories (admin access only).
 *
 * This scenario assures that the admin can:
 *  - Retrieve transaction histories with no filter (all records)
 *  - Search by point wallet ID
 *  - Filter by change_type and actor_type
 *  - Filter by date range window
 *  - Paginate with specific page and limit
 *  - Retrieve empty results for unmatched queries
 *  - Handle malformed requests (e.g. impossible date range)
 *  - Be denied access if not an admin
 *
 * Steps:
 * 1. Create a point wallet for a test customer (admin privilege)
 * 2. Insert 3 point transaction histories for the wallet with distinct change_type and actor_type values
 * 3. Fetch all records (open search)
 * 4. Search by point_wallet_id and verify all created histories are returned
 * 5. Filter by change_type and verify subset, then by actor_type and verify subset
 * 6. Filter by date window (e.g. future date range returns empty)
 * 7. Paginate the results (limit = 2, test second page is as expected)
 * 8. Query with mismatched filters (no results expected)
 * 9. Attempt search as non-admin and expect access denied error
 * 10. Attempt search with malformed input and expect validation error
 */
export async function test_api_point_history_search_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a customer point wallet
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const wallet = await api.functional.shoppingMallAiBackend.admin.points.create(connection, {
    body: {
      customer_id: customerId,
      balance: 1000,
    },
  });
  typia.assert(wallet);

  // 2. Insert 3 transaction histories with distinct property combos
  const now = new Date();
  const h1 = await api.functional.shoppingMallAiBackend.admin.pointHistories.create(connection, {
    body: {
      point_wallet_id: wallet.id,
      change_type: "accrual",
      change_amount: 100,
      balance_after: 1100,
      actor_type: "admin",
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      remarks: "signup bonus",
    },
  });
  const h2 = await api.functional.shoppingMallAiBackend.admin.pointHistories.create(connection, {
    body: {
      point_wallet_id: wallet.id,
      change_type: "redemption",
      change_amount: -50,
      balance_after: 1050,
      actor_type: "customer",
      actor_id: customerId,
      remarks: "used points",
    },
  });
  const h3 = await api.functional.shoppingMallAiBackend.admin.pointHistories.create(connection, {
    body: {
      point_wallet_id: wallet.id,
      change_type: "manual",
      change_amount: 20,
      balance_after: 1070,
      actor_type: "admin",
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      remarks: "admin adjustment",
    },
  });
  typia.assert(h1); typia.assert(h2); typia.assert(h3);

  // 3. Fetch all point wallet histories (no filter)
  const allRes = await api.functional.shoppingMallAiBackend.admin.pointHistories.search(connection, { body: {} });
  typia.assert(allRes);
  TestValidator.predicate("should include at least the 3 just created")(
    [h1.id, h2.id, h3.id].every(id => allRes.data.some(ph => ph.id === id))
  );

  // 4. Search by point_wallet_id
  const byWallet = await api.functional.shoppingMallAiBackend.admin.pointHistories.search(connection, { body: { point_wallet_id: wallet.id } });
  typia.assert(byWallet);
  TestValidator.equals("all history for this wallet found")(byWallet.data.length)(3);
  const idsByWallet = byWallet.data.map(ph => ph.id);
  TestValidator.predicate("correct history records for point_wallet_id")(
    idsByWallet.includes(h1.id) && idsByWallet.includes(h2.id) && idsByWallet.includes(h3.id)
  );

  // 5. Filter by change_type and actor_type
  const byChangeType = await api.functional.shoppingMallAiBackend.admin.pointHistories.search(connection, {
    body: { point_wallet_id: wallet.id, change_type: "accrual" },
  });
  typia.assert(byChangeType);
  TestValidator.equals("1 accrual record found")(byChangeType.data.length)(1);
  TestValidator.equals("accrual id matches")(byChangeType.data[0].id)(h1.id);

  const byActorType = await api.functional.shoppingMallAiBackend.admin.pointHistories.search(connection, {
    body: { point_wallet_id: wallet.id, actor_type: "customer" },
  });
  typia.assert(byActorType);
  TestValidator.equals("1 customer actor record found")(byActorType.data.length)(1);
  TestValidator.equals("customer-redemption id matches")(byActorType.data[0].id)(h2.id);

  // 6. Filter by future date window (empty results expected)
  const futureFrom = new Date(now.getTime() + 1000 * 60 * 60 * 24).toISOString();
  const emptyRes = await api.functional.shoppingMallAiBackend.admin.pointHistories.search(connection, {
    body: { point_wallet_id: wallet.id, created_from: futureFrom },
  });
  typia.assert(emptyRes);
  TestValidator.equals("no records found for future range")(emptyRes.data.length)(0);

  // 7. Pagination: get first page (limit=2)
  const paged1 = await api.functional.shoppingMallAiBackend.admin.pointHistories.search(connection, {
    body: { point_wallet_id: wallet.id, page: 1, limit: 2 },
  });
  typia.assert(paged1);
  TestValidator.equals("first page has 2 histories")(paged1.data.length)(2);

  // Second page (should contain 1 remaining history)
  const paged2 = await api.functional.shoppingMallAiBackend.admin.pointHistories.search(connection, {
    body: { point_wallet_id: wallet.id, page: 2, limit: 2 },
  });
  typia.assert(paged2);
  TestValidator.equals("second page has 1 record")(paged2.data.length)(1);
  TestValidator.notEquals("paged2 record is not found in paged1")(
    paged2.data[0].id
  )(paged1.data[0].id);

  // 8. Query mismatch (actor_type that doesn't exist)
  const noRes = await api.functional.shoppingMallAiBackend.admin.pointHistories.search(connection, {
    body: { point_wallet_id: wallet.id, actor_type: "system" },
  });
  typia.assert(noRes);
  TestValidator.equals("no records for unused actor type")(noRes.data.length)(0);

  // 9. Attempt search as non-admin (simulate by removing admin token)
  const userConn = { ...connection, headers: { ...connection.headers } };
  delete userConn.headers.Authorization;
  await TestValidator.error("unauthorized access is denied")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.pointHistories.search(userConn, {
        body: { point_wallet_id: wallet.id },
      });
    }
  );

  // 10. Malformed request: invalid page (zero)
  await TestValidator.error("malformed input detected")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.pointHistories.search(connection, {
        body: { page: 0 },
      });
    }
  );
}

