import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderStatusHistory";
import type { IShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderSnapshot";
import type { IPageIShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieving a paginated and filtered list of order snapshot records for a specific order as a customer.
 *
 * Workflow Steps:
 * 1. Create a new order as a customer (ensure unique customer and order context)
 * 2. Perform multiple order status changes for the order (e.g., payment, shipment). Each state change should trigger a new snapshot for the order.
 * 3. Retrieve the order snapshot list using the PATCH endpoint with various parameters:
 *    a. No filters (should retrieve all snapshots for the order)
 *    b. Pagination parameters (page, limit) - check correct page sizes and navigation
 *    c. Filter by snapshot_reason (e.g., retrieve only "payment" state or similar - if test data allows)
 *    d. Filter by date (created_after, created_before spanning known intervals among the snapshots)
 * 4. Validate that all expected state changes (and thus snapshots) are present and accurately reflect the order's lifecycle events.
 * 5. Test that only the owning customer can access the order's snapshots; attempts with wrong orderId or without permission should error.
 * 6. Test invalid/misconfigured pagination (e.g., page=0, negative limit) results in errors as expected.
 */
export async function test_api_order_snapshot_history_pagination_and_filtering_customer(connection: api.IConnection) {
  // 1. Prepare test customer and create a new order
  const testCustomerId = typia.random<string & tags.Format<"uuid">>();
  const orderNumber = `ORD-${Date.now()}`;
  const initialStatus = "created";
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: testCustomerId,
      order_number: orderNumber,
      total_amount: 10000,
      currency_code: "USD",
      note: "Test order lifecycle",
      current_status: initialStatus
    }
  });
  typia.assert(order);
  const orderId = order.id;

  // 2. Mutate order status a few times to generate snapshots
  const statusChanges = [
    { previous_status: "created",  new_status: "pending", reason: "Customer started payment" },
    { previous_status: "pending",  new_status: "paid",    reason: "Customer paid" },
    { previous_status: "paid",     new_status: "shipped", reason: "Order shipped by system" }
  ];
  let currentStatus = initialStatus;
  let allHistories = [];
  for (const change of statusChanges) {
    const history = await api.functional.shoppingMallAiBackend.customer.orders.orderStatusHistories.create(connection, {
      orderId,
      body: {
        previous_status: change.previous_status,
        new_status: change.new_status,
        actor_type: "customer",
        actor_id: testCustomerId,
        event_context: change.reason,
        occurred_at: new Date(Date.now() + Math.floor(Math.random()*5000)).toISOString()
      }
    });
    typia.assert(history);
    currentStatus = change.new_status;
    allHistories.push(history);
  }

  // 3a. Retrieve all snapshots for this order (no filters)
  const allSnapshots = await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
    orderId,
    body: {}
  });
  typia.assert(allSnapshots);
  TestValidator.predicate("should have at least as many snapshots as status changes")(
    allSnapshots.data.length >= statusChanges.length);

  // 3b. Pagination: get only a subset of snapshots (limit=2 on first page)
  const pagedSnapshots = await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
    orderId,
    body: {
      page: 1,
      limit: 2
    }
  });
  typia.assert(pagedSnapshots);
  TestValidator.equals("limit is respected")(pagedSnapshots.pagination.limit)(2);
  TestValidator.predicate("page 1 size matches, not more than limit")(pagedSnapshots.data.length <= 2);

  // 3c. Filter by snapshot_reason (assume "shipped" will be present if statusChanges last event is "shipped")
  const reasonToFind = statusChanges[statusChanges.length-1].new_status;
  const reasonFiltered = await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
    orderId,
    body: {
      snapshot_reason: reasonToFind
    }
  });
  typia.assert(reasonFiltered);
  for (const snap of reasonFiltered.data) {
    TestValidator.equals("reason filter matches")(snap.snapshot_reason)(reasonToFind);
  }

  // 3d. Filter by date window (created_after, created_before)
  if (allSnapshots.data.length > 1) {
    const cutoff = allSnapshots.data[1].created_at;
    const dateFiltered = await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
      orderId,
      body: {
        created_after: cutoff
      }
    });
    typia.assert(dateFiltered);
    for (const snap of dateFiltered.data) {
      TestValidator.predicate("created_after is enforced")(snap.created_at > cutoff);
    }
  }

  // 4. Error: unauthorized orderId (random UUID)
  await TestValidator.error("should fail for non-existent order")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
        orderId: typia.random<string & tags.Format<"uuid">>(),
        body: {}
      });
    }
  );

  // 5. Error: misconfigured pagination (page=0)
  await TestValidator.error("zero page fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
        orderId,
        body: {
          page: 0,
          limit: 2
        }
      });
    }
  );

  // 6. Error: insufficient permissions (simulate by random orderId)
  await TestValidator.error("other user's order is forbidden")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
        orderId: typia.random<string & tags.Format<"uuid">>(),
        body: {}
      });
    }
  );
}

