import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderStatusHistory";
import type { IShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderSnapshot";
import type { IPageIShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieving a paginated and filtered list of order snapshot records for a specific order as a customer.
 *
 * Business context:
 * This test ensures that order snapshot history (audit trail) retrieval via PATCH endpoint works as expected for a customer. It verifies that business state changes (status updates) are properly snapshotted, that pagination and filtering features function, and that proper permissions are enforced. The test covers happy path, filter variations, and several negative/error edge cases.
 *
 * Steps:
 * 1. Create a unique customer/order context, then create a new order as that customer.
 * 2. Perform multiple order status transitions to generate a multi-step audit trail.
 * 3. Retrieve all snapshots for this order and validate their count and relation to status events.
 * 4. Test paginated retrieval with page+limit.
 * 5. Filter by snapshot_reason and verify all returned results are as requested.
 * 6. Filter by creation date (created_after), checking that only newer snapshots are returned.
 * 7. Attempt to query using an unauthorized or invalid orderId, expecting an error.
 * 8. Misconfigure pagination (e.g., page=0) and expect error.
 * 9. (If distinct forbidden vs not-found) Test forbidden access on other orders.
 */
export async function test_api_order_snapshot_history_pagination_and_filtering_customer(connection: api.IConnection) {
  // 1. Create a new order as a test customer
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const orderNo = `ORD-${Date.now()}`;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
      order_number: orderNo,
      total_amount: 12345,
      currency_code: "USD",
      note: "Testing snapshot audit trail",
      current_status: "created"
    } satisfies IShoppingMallAiBackendOrder.ICreate
  });
  typia.assert(order);
  const orderId = order.id;

  // 2. Add status history events to generate snapshots
  const statusFlows = [
    { previous_status: "created", new_status: "pending", context: "Started payment" },
    { previous_status: "pending", new_status: "paid",    context: "Payment completed" },
    { previous_status: "paid",    new_status: "shipped", context: "Order shipped" }
  ];
  for (const step of statusFlows) {
    const statusEvent = await api.functional.shoppingMallAiBackend.customer.orders.orderStatusHistories.create(connection, {
      orderId,
      body: {
        previous_status: step.previous_status,
        new_status: step.new_status,
        actor_type: "customer",
        actor_id: customerId,
        event_context: step.context,
        occurred_at: new Date(Date.now() + Math.floor(Math.random()*10000)).toISOString()
      } satisfies IShoppingMallAiBackendOrderStatusHistory.ICreate
    });
    typia.assert(statusEvent);
  }

  // 3. Query all snapshots for this order (all filters omitted)
  const allSnaps = await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
    orderId,
    body: {} satisfies IShoppingMallAiBackendOrderSnapshot.IRequest
  });
  typia.assert(allSnaps);
  TestValidator.predicate("snapshot count >= status flows")(allSnaps.data.length >= statusFlows.length);
  for (const snap of allSnaps.data)
    TestValidator.equals("order_id matches")(snap.order_id)(orderId);

  // 4. Paging test: page=1, limit=2
  const paged = await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
    orderId,
    body: {
      page: 1,
      limit: 2
    } satisfies IShoppingMallAiBackendOrderSnapshot.IRequest
  });
  typia.assert(paged);
  TestValidator.equals("page is 1")(paged.pagination.current)(1);
  TestValidator.equals("limit is 2")(paged.pagination.limit)(2);
  TestValidator.predicate("result count <= 2")(paged.data.length <= 2);

  // 5. Filter: by snapshot_reason (use statusFlows' last new_status)
  const latestReason = statusFlows[statusFlows.length-1].new_status;
  const filteredByReason = await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
    orderId,
    body: {
      snapshot_reason: latestReason
    } satisfies IShoppingMallAiBackendOrderSnapshot.IRequest
  });
  typia.assert(filteredByReason);
  for (const snap of filteredByReason.data)
    TestValidator.equals("reason matches")(snap.snapshot_reason)(latestReason);

  // 6. Filter: by created_after using second snapshot's timestamp, if available
  if (allSnaps.data.length > 1) {
    // Safely sort by created_at ascending for cutoff
    const sortedSnaps = [...allSnaps.data].sort((a,b) => a.created_at.localeCompare(b.created_at));
    const cutoff = sortedSnaps[1].created_at;
    const dateFiltered = await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
      orderId,
      body: {
        created_after: cutoff
      } satisfies IShoppingMallAiBackendOrderSnapshot.IRequest
    });
    typia.assert(dateFiltered);
    for (const snap of dateFiltered.data)
      TestValidator.predicate("created_after works")(snap.created_at > cutoff);
  }

  // 7. Error: invalid/non-existent orderId
  await TestValidator.error("non-existent order fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
        orderId: typia.random<string & tags.Format<"uuid">>(),
        body: {}
      });
    }
  );

  // 8. Error: page=0 triggers validation error
  await TestValidator.error("page=0 error")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
        orderId,
        body: {
          page: 0,
          limit: 2
        }
      });
    }
  );

  // 9. Error: querying other user's order (simulate by random UUID)
  await TestValidator.error("not your order error")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.search(connection, {
        orderId: typia.random<string & tags.Format<"uuid">>(),
        body: {}
      });
    }
  );
}

