  const reviewedVerification = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: verificationId,
      reviewed_by: adminAuth.name,
      reviewed_at: reviewedAt,
    },
  });
