    body: {
      id: verificationId,
      note: updatedNote,
    },
  });
  typia.assert(noteUpdated);
  TestValidator.equals("note updated")(noteUpdated.note)(updatedNote);
  TestValidator.predicate("updated_at should be refreshed after note")(noteUpdated.updated_at !== reviewedVerification.updated_at);

  // 3c. Update document_file_uri and status
  const newStatus = "approved";
  const newDocumentUri = "https://cdn.example.com/new-verification.pdf";
  const docStatusUpdated = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: verificationId,
      verification_status: newStatus,
      document_file_uri: newDocumentUri,
    },
  });
  typia.assert(docStatusUpdated);
  TestValidator.equals("verification_status updated")(docStatusUpdated.verification_status)(newStatus);
  TestValidator.equals("document_file_uri updated")(docStatusUpdated.document_file_uri)(newDocumentUri);

  // 4. Attempt update for non-existent record
  const nonExistentId = typia.random<string & tags.Format<'uuid'>>();
  await TestValidator.error("non-existent record update throws error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
      sellerId,
      body: {
        id: nonExistentId,
        verification_status: "rejected",
      }
    });
  });

  // 5. Simulate finalized/compliance-locked record - this is implementation-specific, but we simulate by updating to a finalized status then attempting another update.
  const finalizedStatus = "approved";
  const finalized = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: verificationId,
      verification_status: finalizedStatus,
    },
  });
  typia.assert(finalized);

  await TestValidator.error("finalized/compliance-locked record cannot be changed")(async () => {
    await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
      sellerId,
      body: {
        id: verificationId,
        note: "Cannot overwrite after finalized.",
      },
    });
  });
}

