import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";

/**
 * Validates that an admin user can delete a product bundle via the API,
 * ensuring that the bundle becomes inaccessible after deletion.
 *
 * Business context:
 * In shopping mall administration, product bundles can be managed
 * (created/deleted) by admins. This test simulates the full lifecycle:
 * 1. Admin creates a product (dependency)
 * 2. Admin adds a product bundle under the given product (dependency)
 * 3. Admin deletes the product bundle via the intended endpoint
 * 4. Verifies the bundle is no longer accessible (typically 404 or error)
 * 5. (If API present) Validates audit/event logging (but will omit this step if unimplementable)
 *
 * This ensures deletion is fully executed and prevents stale/inaccessible bundles in business systems.
 */
export async function test_api_product_bundle_delete_by_admin_success(
  connection: api.IConnection,
) {
  // Step 1: Admin creates a product
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // Step 2: Admin creates a bundle under the product
  const bundle = await api.functional.shoppingMallAiBackend.admin.products.productBundles.create(connection, {
    productId: product.id,
    body: {
      main_product_id: product.id,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(),
      bundle_policy: null,
      bundle_price: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProductBundle.ICreate,
  });
  typia.assert(bundle);

  // Step 3: Admin deletes the bundle
  await api.functional.shoppingMallAiBackend.admin.products.productBundles.erase(
    connection,
    {
      productId: product.id,
      productBundleId: bundle.id,
    },
