      body: { product_id: productId } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate,
    });
    typia.assert(duplicate);
    TestValidator.equals("duplicate record, should match first one")(duplicate.id)(favorite.id);
  } catch (err) {
    // Acceptable: error due to already favorited
    TestValidator.predicate("duplicate favorite throws error")(true);
  }

  // 5. Attempt to favorite with an invalid/malformed UUID
  TestValidator.error("malformed UUID should throw")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
      body: { product_id: "not-a-uuid" as any },
    })
  );

  // 6. Attempt to favorite a random (well-formed but likely non-existent) productId
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("favoriting non-existent product should fail")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
      body: { product_id: nonExistentId } as IShoppingMallAiBackendFavoriteProduct.ICreate,
    })
  );
}

