 * 1. Authenticate as a valid admin (obtain JWT).
 * 2. Using admin privileges, query the paginated admin list (search) to obtain a real adminId for positive test.
 * 3. Use the valid adminId to fetch details. Validate all non-sensitive profile/role fields return, and no sensitive fields such as password hash are included.
 * 4. Attempt to fetch details with a non-existent adminId (random UUID). Validate that a not-found error occurs.
 * 5. Simulate a session without admin token (e.g., clear Authorization header or use no JWT). Attempt to fetch adminId details and expect forbidden or unauthorized error.
 */
export async function test_api_admin_detail_success_and_error(
  connection: api.IConnection,
) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "testPassword1!";
  // Assume admin exists with these credentials, or patch search for existing admin below
  const login = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignIn,
  });
  typia.assert(login);
  // Admin JWT is now set in connection.headers

  // 2. Search admins to get a real adminId
  const search = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: {}
  });
  typia.assert(search);
  TestValidator.predicate("admin results exist")(search.data.length > 0);
  const validAdmin = search.data[0];
  TestValidator.predicate("admin id returned")(!!validAdmin.id);

  // 3. Success: fetch details for a valid adminId
  const detail = await api.functional.shoppingMallAiBackend.admin.admins.at(connection, {
    adminId: validAdmin.id,
  });
  typia.assert(detail);
  // Confirm presence of business fields, absence of sensitive fields (password hash not present in DTO)
  TestValidator.equals("id matches")(detail.id)(validAdmin.id);
  TestValidator.equals("has email")(detail.email)(validAdmin.email);
  TestValidator.equals("has name")(detail.name)(validAdmin.name);
