/**
 * Validate that a seller cannot delete a product inquiry not related to their own product.
 *
 * Business requirement: Product inquiries may only be deleted (soft deleted) by the seller who owns the related product. If a seller attempts to delete an inquiry on a product owned by a different seller, the operation must be rejected and a permission error must be returned.
 *
 * Test Steps:
 * 1. Simulate Seller A by generating a unique seller_id_A (in a real system, this would come from seller registration/login)
 * 2. Create a product as Seller A
 * 3. Simulate a customer by generating a unique customer_id
 * 4. Create a product inquiry for Seller A's product as the customer
 * 5. Simulate Seller B by generating a unique seller_id_B (different from seller_id_A)
 * 6. Attempt to delete the inquiry as Seller B (who does not own the product); verify that permission is denied
 */
export async function test_api_product_inquiry_delete_seller_permission_denied(
  connection: api.IConnection,
) {
  // 1. Simulate Seller A by generating a unique seller_id_A
  const seller_id_A = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a product as Seller A
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: seller_id_A,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 3. Simulate a customer by generating a unique customer_id
  const customer_id = typia.random<string & tags.Format<"uuid">>();

  // 4. Create a product inquiry for Seller A's product
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customer_id,
      product_id: product.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
  });
  typia.assert(inquiry);

  // 5. Simulate Seller B by generating a unique seller_id_B (ensure different from Seller A)
  let seller_id_B = typia.random<string & tags.Format<"uuid">>();
  while (seller_id_B === seller_id_A) seller_id_B = typia.random<string & tags.Format<"uuid">>();

  // 6. Attempt to delete the inquiry as Seller B (permission denied expected)
  await TestValidator.error("permission denied when seller attempts to delete another seller's inquiry")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.productInquiries.erase(connection, {
        productInquiryId: inquiry.id,
      });
    },
  );
}

