import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test admin-side error handling for attempting to add a cart item to an invalid (nonexistent) cart or specifying an invalid product ID.
 *
 * This test ensures that:
 * 1. Admin registration works and JWT is properly issued.
 * 2. Attempts to add a cart item referencing a random/nonexistent cartId or productId trigger errors rather than successful creation.
 * 3. The API returns explicit, non-informative error messages — i.e., it should state that the resource is not found or input invalid, without leaking system data.
 * 4. No cart item is created in case of error.
 *
 * Step-by-step process:
 * 1. Register a new admin and ensure authentication is set (JWT in header from response).
 * 2. Prepare two error test cases: (A) Use a random (very likely nonexistent) cartId with a random product_id. (B) Use a random cartId with another random product_id.
 * 3. Attempt to create a cart item for both cases via the admin endpoint; expect API to throw an error.
 * 4. Assert that an error (HttpError) is thrown for both attempts (and not a success response), without leaking internal state.
 */
export async function test_api_cart_item_create_admin_invalid_cart_or_product(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "test1234$";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);
  // Admin JWT is now present in connection.headers.Authorization

  // Helper to expect error when adding cart item
  async function expectCartItemCreationToFail(
    invalidCartId: string,
    invalidProductId: string,
  ) {
    await TestValidator.error("should fail when cartId or productId is invalid")(
      () =>
        api.functional.shoppingMallAiBackend.admin.carts.cartItems.create(
          connection,
          {
            cartId: invalidCartId,
            body: {
              product_id: invalidProductId,
              quantity: 1,
              unit_price: 1000,
              currency_code: "KRW",
            } satisfies IShoppingMallAiBackendCartItem.ICreate,
          },
        ),
    );
  }

  // 2. Try with random cartId, random productId (very likely both do not exist)
  const randomCartId = typia.random<string & tags.Format<"uuid">>();
  const randomProductId1 = typia.random<string & tags.Format<"uuid">>();
  await expectCartItemCreationToFail(randomCartId, randomProductId1);

  // 3. Try again with a new random productId but same random cartId
  const randomProductId2 = typia.random<string & tags.Format<"uuid">>();
  await expectCartItemCreationToFail(randomCartId, randomProductId2);

  // Note: Because we cannot call any API to list or get valid cart/product IDs, both cartId and productId are random UUIDs in each test.
}

