 * 7. Attempt to delete the tag from Seller A's product via the DELETE API.
 * 8. Assert that the operation fails due to insufficient permissions (using TestValidator.error()).
 */
export async function test_api_product_tag_delete_unauthorized_by_seller(connection: api.IConnection) {
  // Step 1: Register Seller A (the owner of the product)
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
