/**
 * Validate access control and detail retrieval of customer history events.
 *
 * Ensures that a customer can retrieve their own single history record in detail, but that unauthorized access (other customers, anonymous) is denied. Edge cases: non-existing or soft-deleted records must return appropriate errors.
 *
 * Test process:
 * 1. Register a customer account (Customer A) and ensure authorized session.
 * 2. Use the histories search API to fetch a page of available audit history records for Customer A; pick a valid historyId.
 * 3. Retrieve the selected history by ID as Customer A and assert all key fields (event_type, values, actor, time, context) are returned and match the list record. Confirm the history is not soft-deleted.
 * 4. Register another customer (Customer B) and attempt to access Customer A's historyId as Customer B — expect error (unauthorized/forbidden).
 * 5. Attempt to access the same history as an anonymous user (without auth) — expect error (unauthorized).
 * 6. Attempt to query a non-existent historyId for Customer A — expect not found/error.
 * 7. (If possible) Attempt to query a soft-deleted historyId for Customer A — expect not found/error. (Only feasible if soft-delete can be simulated from available APIs, otherwise skip this step.)
 */
export async function test_api_customer_history_detail_access_control(connection: api.IConnection) {
  // 1. Register Customer A
  const customerAInfo = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Passw0rd_!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerAInfo);
  const customerA = customerAInfo.customer;

  // 2. List histories as Customer A
  const historyPageA = await api.functional.shoppingMallAiBackend.customer.customers.histories.search(connection, {
    customerId: customerA.id,
    body: {
      customer_id: customerA.id,
      page: 1,
      limit: 5
    },
  });
  typia.assert(historyPageA);

  // Find a valid active history (not soft-deleted)
  const availableHistories = historyPageA.data.filter(h => !h.id.startsWith("00000000-"));
  if (!availableHistories.length)
    throw new Error("No history records available for testing.");
  const validHistory = availableHistories[0];

  // 3. Retrieve the history event detail as Customer A
  const fetchedDetail = await api.functional.shoppingMallAiBackend.customer.customers.histories.at(connection, {
    customerId: customerA.id,
    historyId: validHistory.id,
  });
  typia.assert(fetchedDetail);
  TestValidator.equals("customerId matches")(fetchedDetail.customer_id)(customerA.id);
  TestValidator.equals("history id matches")(fetchedDetail.id)(validHistory.id);
  TestValidator.equals("event_type matches")(fetchedDetail.event_type)(validHistory.event_type);
  TestValidator.equals("not soft deleted")(fetchedDetail.created_at != null)(true);

  // 4. Register Customer B
  const customerBInfo = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Passw0rd_!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
