  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerB.email,
      password: "Passw0rd_!",
      name: customerB.name,
      nickname: customerB.nickname,
      phone: customerB.phone,
    },
  }); // re-log as B (if token not already set)
  await TestValidator.error("Cannot access another customer's history")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.histories.at(connection, {
      customerId: customerA.id,
      historyId: validHistory.id,
    })
  );

  // 6. Try to access as anonymous (should fail)
  const anonConnection = { ...connection, headers: {} };
  await TestValidator.error("Unauthenticated cannot access history")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.histories.at(anonConnection, {
      customerId: customerA.id,
      historyId: validHistory.id,
    })
  );

  // 7. Try non-existent history id (should fail)
  await TestValidator.error("Non-existent history id errors")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.histories.at(connection, {
      customerId: customerA.id,
      historyId: typia.random<string & tags.Format<"uuid">>(), // random non-existent
    })
  );

  // 8. [Optional] If soft-delete simulation is feasible, attempt and test; skip due to API unavailability
}

