import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test soft-deleting one’s own address as a customer.
 *
 * 1. Register and log in as a customer.
 * 2. Create an address for this customer.
 * 3. List addresses and select the one to be deleted (verify its existence).
 * 4. Call DELETE /shoppingMallAiBackend/customer/customers/{customerId}/addresses/{addressId} with the correct customerId/addressId.
 * 5. Assert the address is removed from subsequent active address listing; expect deleted_at is set via re-listing that includes deleted addresses if possible.
 * 6. Register another customer, attempt to delete first customer’s address, ensure permission error occurs.
 * 7. Try soft-deleting a bogus/non-existent address as the original customer, expect not found or idempotency (error or safe no-op).
 */
export async function test_api_customer_address_soft_delete_by_owner_and_forbidden_access(connection: api.IConnection) {
  // 1. Register primary customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const signUpRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(signUpRes);
  const customer = signUpRes.customer;

  // 2. Create address for customer by simulating search with empty set
  const newAddress = {
    receiver_name: RandomGenerator.name(),
    receiver_phone: RandomGenerator.mobile(),
    postal_code: "12345",
    address_line1: "1 Test St",
    city: "TestCity",
    state: "TestState",
    country: "KR",
    is_primary: true,
  };
  // Use address-listing endpoint as only available way to inject test address via PATCH (simulate address creation if possible)
  await api.functional.shoppingMallAiBackend.customer.customers.addresses.patchByCustomerid(connection, {
    customerId: customer.id,
    body: newAddress satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });

  // 3. List addresses for the customer and get its id
  let addressList = await api.functional.shoppingMallAiBackend.customer.customers.addresses.patchByCustomerid(connection, {
    customerId: customer.id,
    body: {} satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(addressList);
  const addressToDelete = addressList.data[0];
  if (!addressToDelete) throw new Error("Created address not found");

  // 4. Delete the address
  await api.functional.shoppingMallAiBackend.customer.customers.addresses.eraseByCustomeridAndAddressid(connection, {
    customerId: customer.id,
    addressId: addressToDelete.id,
  });

  // 5. Verify address is removed from address list (active/non-deleted)
  addressList = await api.functional.shoppingMallAiBackend.customer.customers.addresses.patchByCustomerid(connection, {
    customerId: customer.id,
