import type { IShoppingMallAiBackendProductOptionStock } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOptionStock";

/**
 * Test the soft deletion (logical deletion) operation for a product option stock as performed by an admin.
 *
 * This test verifies a complete business flow for an inventory management scenario including normal and error paths for the soft delete behavior:
 *
 * 1. Create a new product using the admin endpoint.
 * 2. Create a product option linked to the created product.
 * 3. Add a product option stock for the product option.
 * 4. Soft delete the created product option stock using the admin delete endpoint.
 * 5. Re-fetch the deleted stock and assert its deleted_at value is set (i.e., the stock was marked as soft-deleted).
 * 6. Attempt to soft delete the same product option stock again and expect either idempotence (no error) or a proper error response (according to system design).
 * 7. Attempt to delete a non-existent productOptionStockId; expect an error.
 * 8. Attempt to delete a stock from a wrong productOptionId; expect an error.
 *
 * This covers both the standard operation and boundary/error cases for the inventory soft-delete workflow as used by admin users.
 */
export async function test_api_product_option_stock_soft_delete_by_admin(connection: api.IConnection) {
  // 1. Create a product
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "draft",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 2. Add a product option
  const option = await api.functional.shoppingMallAiBackend.admin.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: RandomGenerator.alphaNumeric(14),
      option_name: "Color",
      option_values: "Red|Green|Blue",
      extra_price: 100,
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProductOption.ICreate,
  });
  typia.assert(option);

  // 3. Add a product option stock
  const stock = await api.functional.shoppingMallAiBackend.admin.productOptions.productOptionStocks.create(connection, {
    productOptionId: option.id,
    body: {
      product_option_id: option.id,
      stock_count: 50,
      safety_stock: 10,
