  await TestValidator.error("Soft delete for non-existent stock should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.productOptions.productOptionStocks.erase(connection, {
        productOptionId: option.id,
        productOptionStockId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 8. Try deleting with incorrect productOptionId for an existing stock
  await TestValidator.error("Soft delete with incorrect productOptionId should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.productOptions.productOptionStocks.erase(connection, {
        productOptionId: typia.random<string & tags.Format<"uuid">>(),
        productOptionStockId: stock.id,
      });
    },
  );
}

