      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(10),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(respA);
  const customerA = respA.customer;
  // The connection is now authenticated as customerA (via setHeaders)

  // Register customerB
  const emailB = typia.random<string & tags.Format<"email">>();
  // Use a new connection instance or manually swap header for test isolation
  const respB = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: emailB,
      password: "Passw0rd!B",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(10),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(respB);
  const customerB = respB.customer;

  // Helper to swap connection's Authorization to customerA
  async function switchToA() {
    // Re-authorize as customerA if needed (simulate login if such endpoint exists)
    connection.headers.Authorization = respA.setHeaders.Authorization;
  }
  // Helper to swap to customerB
  async function switchToB() {
    connection.headers.Authorization = respB.setHeaders.Authorization;
  }

  // --- As customerA, list own external links, no filter ---
  await switchToA();
  const pageA1 = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.search(connection, {
    customerId: customerA.id,
