  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "testPassword123!";
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);

  // 2. Try to get channel details for a random (non-existent) channelId
  const nonExistentChannelId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent channel yields 404 not found")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.channels.at(connection, {
        channelId: nonExistentChannelId,
      });
    }
  );

  // 3. Create a new channel (will be soft-deleted soon)
  const channel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      created_by_admin_id: adminAuth.adminId,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channel);

  // 4. Soft-delete the channel
  await api.functional.shoppingMallAiBackend.admin.channels.erase(connection, {
    channelId: channel.id,
  });

  // 5. Try to get the details for this now soft-deleted channel
  await TestValidator.error("soft-deleted channel yields 404 not found")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.channels.at(connection, {
        channelId: channel.id,
      });
    }
  );
}

