      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "draft",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 2. Create product option under this product
  const productOption = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: RandomGenerator.alphaNumeric(10),
      option_name: "Color",
      option_values: "red,green,blue",
      extra_price: 500,
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProductOption.ICreate,
  });
  typia.assert(productOption);

  // 3. Successfully create a product option stock for the product option
  const createStockInput = {
    product_option_id: productOption.id,
    stock_count: 100,
    safety_stock: 10,
    inbound_count: 20,
    warehouse_location: "A-01",
    status: "active",
  } satisfies IShoppingMallAiBackendProductOptionStock.ICreate;

  const stock = await api.functional.shoppingMallAiBackend.seller.productOptions.productOptionStocks.create(connection, {
    productOptionId: productOption.id,
    body: createStockInput,
  });
  typia.assert(stock);
  TestValidator.equals("linked to correct product option")(stock.product_option_id)(productOption.id);
  TestValidator.equals("stock count matches")(stock.stock_count)(createStockInput.stock_count);
  TestValidator.equals("status matches")(stock.status)(createStockInput.status);

  // 4. Try to create a duplicate stock under the same product option (should fail by business rule)
  await TestValidator.error("duplicate stock creation should fail")(() =>
    api.functional.shoppingMallAiBackend.seller.productOptions.productOptionStocks.create(connection, {
      productOptionId: productOption.id,
      body: createStockInput,
    }),
  );

  // 5. Try to create a stock referencing a non-existent product option
  await TestValidator.error("creating stock for non-existent option should fail")(() =>
    api.functional.shoppingMallAiBackend.seller.productOptions.productOptionStocks.create(connection, {
      productOptionId: typia.random<string & tags.Format<"uuid">>(), // random UUID not belonging to any real product option
      body: {
        ...createStockInput,
        product_option_id: typia.random<string & tags.Format<"uuid">>(),
      },
    }),
  );

  // 6. Skipped: unauthorized user scenario, as no customer/admin endpoints are provided in current API set
}

