import type { IShoppingMallAiBackendSellerBusinessVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSellerBusinessVerification";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate the update and field validations of a seller's business verification record.
 *
 * This test checks if the seller can update their business verification, covering business status changes (such as approval, rejection, or resubmission), updating document files, and admin/reviewer comments.
 *
 * Steps:
 * 1. Authenticate as an existing seller using the /auth/seller/login endpoint.
 * 2. Create an initial business verification record (simulate or use update API with new info; no explicit create function, so use update as initial insert).
 * 3. Update the business verification with legitimate status changes (e.g., pending -> approved).
 * 4. Update allowed fields, such as uploading a new document, editing reviewer admin notes, or changing status.
 * 5. Validate that the returned object reflects updates and system fields (updated_at, reviewed_at, reviewed_by, etc.) are coherently modified.
 * 6. Try an invalid status transition or improper update (i.e., to a status not allowed by business logic, like 'invalid_status'), confirm error is raised.
 */
export async function test_api_seller_update_business_verification_success_and_field_validation(connection: api.IConnection) {
  // 1. Seller login
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPassword123!";
  // Seller must exist in the system. Simulate that, or assume in test fixture setup.
  const loginResponse = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email,
      password
    } satisfies ISellerAuth.SignIn
  });
  typia.assert(loginResponse);
  const sellerId = loginResponse.sellerId;

  // 2. Create initial business verification by update call (simulate insert):
  //    Only required fields should be set for a basic pending state.
  const baseVerification = await api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      verification_status: "pending",
      document_file_uri: "https://storage.test-server.com/docs/business-license.pdf"
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate
  });
  typia.assert(baseVerification);

  // 3. Update status to approved:
  const approvedVerification = await api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: baseVerification.id,
      verification_status: "approved",
      reviewed_by: "adminReviewer",
      reviewed_at: new Date().toISOString(),
      note: "All documents provided."
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate
  });
  typia.assert(approvedVerification);
  TestValidator.equals("verification status is approved")(approvedVerification.verification_status)("approved");
  TestValidator.equals("note updated")(approvedVerification.note)("All documents provided.");

  // 4. Update with a new document file URI (simulate resubmission w/ not changing status):
  const updatedDocVerification = await api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: baseVerification.id,
      document_file_uri: "https://storage.test-server.com/docs/business-license-v2.pdf",
      note: "Reuploaded clearer document."
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate
  });
  typia.assert(updatedDocVerification);
  TestValidator.equals("document file uri updated")(updatedDocVerification.document_file_uri)("https://storage.test-server.com/docs/business-license-v2.pdf");

  // 5. Attempt invalid update: set verification_status to an invalid value and confirm error
  await TestValidator.error("invalid status rejected")(() =>
    api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.update(connection, {
