import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";

/**
 * Validate that an admin can update business content or status of a product review for compliance purposes (e.g., redacting information, flagging, or adjusting AI moderation).
 *
 * Business context: This test ensures that admin moderation workflows for product reviews work as expected for compliance scenarios (including sensitive information redaction, policy flagging, and AI moderation adjustment). Only valid review fields should be modifiable, and no ownership changes are permitted. The review must reflect changes, and audit trail and policy rules must be enforced (to the extent verifiable via API contract).
 *
 * Test steps:
 * 1. Create a product review as a customer (this is a dependency/precondition).
 * 2. Perform an admin update on the review: redact content, adjust status and AI moderation fields.
 * 3. Assert that the updated review reflects all changes as expected and complies with business rules.
 * 4. Validate uneditable fields are not changed (such as customer_id, product_id, original created_at).
 */
export async function test_api_product_review_admin_update_content_compliance_success(connection: api.IConnection) {
  // 1. Create an initial product review as a customer (dependency)
  const reviewCreateInput: IShoppingMallAiBackendProductReview.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    order_item_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Initial review title",
    body: "Original review content for compliance adjustment.",
    rating: 4,
    status: "normal",
    ai_sentiment_score: 0.7,
    ai_spam_score: 0.1,
  };
  const originalReview: IShoppingMallAiBackendProductReview = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: reviewCreateInput,
  });
  typia.assert(originalReview);

  // 2. Admin updates: redact content, flag as blocked, adjust AI fields
  const reviewUpdateInput: IShoppingMallAiBackendProductReview.IUpdate = {
    title: "[REDACTED]",
    body: "Redacted for compliance (PII removed).",
    rating: 3,
    status: "blocked",
    ai_sentiment_score: null, // AI reanalysis pending
    ai_spam_score: 0.7,
  };
  const updatedReview: IShoppingMallAiBackendProductReview = await api.functional.shoppingMallAiBackend.admin.productReviews.update(connection, {
    productReviewId: originalReview.id,
    body: reviewUpdateInput,
  });
  typia.assert(updatedReview);

  // 3. Assert that changes are reflected correctly
  TestValidator.equals("title updated")(updatedReview.title)(reviewUpdateInput.title);
  TestValidator.equals("body updated")(updatedReview.body)(reviewUpdateInput.body);
  TestValidator.equals("status updated")(updatedReview.status)(reviewUpdateInput.status);
  TestValidator.equals("rating updated")(updatedReview.rating)(reviewUpdateInput.rating);
  TestValidator.equals("spam score updated")(updatedReview.ai_spam_score)(reviewUpdateInput.ai_spam_score);
  TestValidator.equals("sentiment score updated (nullable)")(updatedReview.ai_sentiment_score)(reviewUpdateInput.ai_sentiment_score);

  // 4. Assert that uneditable fields remain unchanged
  TestValidator.equals("id unchanged")(updatedReview.id)(originalReview.id);
  TestValidator.equals("customer unchanged")(updatedReview.customer_id)(originalReview.customer_id);
  TestValidator.equals("product unchanged")(updatedReview.product_id)(originalReview.product_id);
  TestValidator.equals("order item unchanged")(updatedReview.order_item_id)(originalReview.order_item_id);
  TestValidator.equals("created_at unchanged")(updatedReview.created_at)(originalReview.created_at);
}

