  };
  await TestValidator.error("cannot update soft-deleted stock")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productOptions.productOptionStocks.update(connection, {
      productOptionId: deletedStock.product_option_id,
      productOptionStockId: deletedStock.id,
      body: {
        stock_count: 100,
      } satisfies IShoppingMallAiBackendProductOptionStock.IUpdate,
    });
  });

