 * This test ensures that the customer registration, login, and token validation flows are working end-to-end:
 *
 * 1. Register a new customer using random credentials (email, password, name, nickname, phone).
 * 2. Log in using the newly registered credentials to receive a valid JWT token. The JWT is stored automatically in connection headers.
 * 3. Call the /auth/customer/validate endpoint with the session's JWT.
 * 4. Check that the validate endpoint confirms token validity, returns the expected customer entity/profile, and indicates the session is still active and not expired.
 * 5. Assert that the customer profile matches what was registered (except for possible timestamp or system fields).
 * 6. Assert the 'valid' property of the response is true. Assert 'customer' property is correctly populated in the response.
 */
export async function test_api_customer_validate_token_valid(connection: api.IConnection) {
  // 1. Register a new customer
  const customerSignUpInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword123!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphaNumeric(10),
    phone: RandomGenerator.mobile(),
