import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that admin users can retrieve complete customer profiles by ID, including sensitive fields, and verify proper error handling and security enforcement.
 *
 * This test checks multiple scenarios:
 * 1. Registers a new customer and logs in as an admin.
 * 2. As admin, fetches the profile of the just-created customer by their customerId; checks that all expected sensitive fields (email, phone, status, etc) are present and match the registration.
 * 3. Tries to fetch a customer using a non-existent customerId (random UUID); expects a not found error.
 * 4. Tries to fetch a customer after simulating their soft deletion (if physically possible, otherwise verifies deleted_at field and denied access if soft-deleted).
 * 5. Attempts access to the endpoint using a non-admin token (freshly registered customer); expects a permission denied error.
 *
 * Business Case:
 * - Ensures that only admin roles may access the full profile of any customer and that proper access controls, field exposures, and error handling are enforced for both existing and deleted customers.
 */
export async function test_api_customer_detail_admin_access_and_not_found(connection: api.IConnection) {
  // 1. Register a new customer
  const customerInput: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password123!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  };
  const customerSignup = await api.functional.auth.customer.register.signUp(connection, { body: customerInput });
  typia.assert(customerSignup);
  const customer = customerSignup.customer;

  // 2. Login as admin
  const adminLoginInput: IAdminAuth.SignIn = {
    email: process.env.ADMIN_EMAIL ?? "admin@company.com",
    password: process.env.ADMIN_PASSWORD ?? "admin1234!",
  };
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, { body: adminLoginInput });
  typia.assert(adminAuth);
  // Set admin Authorization header for subsequent calls
  connection.headers = { ...connection.headers, Authorization: adminAuth.setHeaders.Authorization };

  // 3. Fetch the created customer's profile as admin
  const profile = await api.functional.shoppingMallAiBackend.admin.customers.at(connection, { customerId: customer.id });
  typia.assert(profile);
  TestValidator.equals("retrieved customer profile matches")(profile.id)(customer.id);
  TestValidator.equals("email matches")(profile.email)(customer.email);
  TestValidator.equals("status active")(profile.status)("active");
  TestValidator.equals("email verified initial")(profile.email_verified)(false);
  TestValidator.equals("phone matches")(profile.phone)(customer.phone);

  // 4. Try fetching non-existent customer (should get not found)
  await TestValidator.error("not found for non-existent customer")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.customers.at(connection, {
        customerId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 5. Fetch as customer (not admin) to validate permission denied
  connection.headers = { ...connection.headers, Authorization: customerSignup.setHeaders.Authorization };
  await TestValidator.error("permission denied for non-admin user")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.customers.at(connection, {
        customerId: customer.id,
      });
    },
  );

  // 6. Try edge: attempt soft-deleted customer fetch (simulate deletion if deleted_at can be set)
  // The API does not expose a delete, so we just test presence of deleted_at as null
  TestValidator.equals("customer not soft deleted")(profile.deleted_at)(null);
}

