    await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.erase(connection, {
      channelCategoryMapId: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // (7) Skipped: Unauthorized/permission scenario and audit log verification are not possible with current API surface
}

