import type { IShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPaymentLog";

/**
 * Test detailed payment log retrieval as the rightful customer and verify metadata and access controls.
 * 
 * 1. Create a customer order with valid business data.
 * 2. Create an order payment attached to that order.
 * 3. Create a payment log entry for that payment.
 * 4. Retrieve the payment log detail as the customer (success expected) and assert correctness:
 *    - Check all returned metadata (log_type, log_context, occurred_at, ids) have proper values.
 *    - Ensure all fields comply with the IShoppingMallAiBackendOrderPaymentLog type.
 * 5. Attempt to retrieve the log as another customer (expect a permission error: access denied).
 * 6. Attempt to retrieve a payment log using a random (non-existent) log id (expect not found or error).
 */
export async function test_api_order_payment_log_detail_as_customer(connection: api.IConnection) {
  // Step 1: Create first customer and their order
  const customerId1 = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId1,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 50000,
      currency_code: "KRW",
      current_status: "created"
    } satisfies IShoppingMallAiBackendOrder.ICreate
  });
  typia.assert(order);

  // Step 2: Create an order payment for this order
  const payment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
      payment_method: "card",
      transaction_id: RandomGenerator.alphaNumeric(18),
      amount: 50000,
      currency_code: "KRW",
      payment_result: "completed"
    } satisfies IShoppingMallAiBackendOrderPayment.ICreate
  });
  typia.assert(payment);

  // Step 3: Create a payment log entry (for example, type=request)
  const log = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.create(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      log_type: "request",
      log_context: JSON.stringify({ message: "Payment requested" }),
      occurred_at: new Date().toISOString()
    } satisfies IShoppingMallAiBackendOrderPaymentLog.ICreate
  });
  typia.assert(log);

  // Step 4: Retrieve the log as the right customer, assert all metadata
  const detail = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.at(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    orderPaymentLogId: log.id
  });
