  // );
  // Omitted due to technical constraint - would require real auth switching.

  // Step 6: Fetch with invalid payment log id (non-existent), expect error
  const fakeLogId = typia.random<string & tags.Format<"uuid">>();
  if (fakeLogId !== log.id) {
    TestValidator.error("non-existent payment log fails")(
      async () => await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.at(connection, {
        orderId: order.id,
        orderPaymentId: payment.id,
        orderPaymentLogId: fakeLogId
      })
    );
  }
