  TestValidator.predicate("created_at is ISO date-time")(!!createdProduct.created_at);
  TestValidator.predicate("updated_at is ISO date-time")(!!createdProduct.updated_at);

  // 5. (Omitted) - Catalog search/list check is skipped due to missing standardized API/DTO for listing/search
}

