import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that the admin mileage transaction API correctly rejects invalid input scenarios.
 *
 * Business context: Admins can directly create mileage transactions for any customer's mileage wallet. The API must prevent invalid mileage transactions that could undermine data integrity or business rules, such as negative transaction amounts, non-existent wallets, or duplicate reference_id values.
 *
 * Steps covered:
 * 1. Register a new admin via the sign-up API to ensure privileged access.
 * 2. As admin, create a valid mileage wallet for a random customer for testing.
 * 3. Attempt to create a mileage transaction on a non-existent mileage wallet ID — expect error.
 * 4. Attempt to create a mileage transaction with a negative amount — expect error.
 * 5. Successfully create a valid mileage transaction with a unique reference_id.
 * 6. Attempt to create a second transaction for the same wallet with a duplicate reference_id — expect error.
 * 7. For each error, verify that the API returns an error and ensure failed transactions do not persist (where query/check is possible).
 */
export async function test_api_mileage_transaction_create_invalid_input_admin(
  connection: api.IConnection,
) {
  // 1. Register new admin for this test
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "QwErTy@123456";
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignup);

  // 2. Create a valid mileage wallet for test customer
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: customerId,
      wallet_program: "brand",
      wallet_status: "active",
      wallet_label: "Test Wallet",
    } satisfies IShoppingMallAiBackendMileageWallet.ICreate,
  });
  typia.assert(wallet);

  // 3. Try transaction on a non-existent wallet (should fail)
  await TestValidator.error("fail on non-existent mileage wallet")(async () => {
    await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(connection, {
      mileageWalletId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        wallet_id: typia.random<string & tags.Format<"uuid">>(),
        transaction_type: "accrue",
        mileage_amount: 100,
        reference_id: "fail-nonexistent-wallet",
        transaction_reason: "Negative test: non-existent wallet",
      } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
    });
  });

  // 4. Try transaction with a negative amount (should fail if validation present)
  await TestValidator.error("fail on negative mileage_amount")(async () => {
    await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(connection, {
      mileageWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        transaction_type: "accrue",
        mileage_amount: -999,
        reference_id: "fail-negative-amount",
        transaction_reason: "Negative test: negative mileage_amount",
      } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
    });
  });

  // 5. Valid transaction for further duplicate test
  const validReferenceId = "unique-test-ref-123";
  const transaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(connection, {
    mileageWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      transaction_type: "accrue",
      mileage_amount: 100,
      reference_id: validReferenceId,
      transaction_reason: "Valid base transaction",
    } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
  });
  typia.assert(transaction);
  TestValidator.equals("reference_id matches")(transaction.reference_id)(validReferenceId);

  // 6. Duplicate reference_id attempt (should fail if enforced)
  await TestValidator.error("fail on duplicate reference_id")(async () => {
    await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(connection, {
      mileageWalletId: wallet.id,
      body: {
