        transaction_type: "accrue",
        mileage_amount: 50,
        reference_id: validReferenceId,
        transaction_reason: "Negative test: duplicate reference_id",
      } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
    });
  });

  // Note: No SDK function to enumerate transactions for persistence check.
}

