/**
 * Validate that product creation enforces required field constraints for admins.
 *
 * This test ensures the backend rejects product creation requests with missing or invalid required fields—including blank name, missing code, or missing seller assignment—when requested by a valid admin. Each attempt must yield appropriate validation errors as per business rules, thus confirming system robustness and audit compliance.
 *
 * Test procedure:
 * 1. Register a new admin (unique email/password) to enable authenticated creation.
 * 2. Login as that admin to acquire a valid session for authorization.
 * 3. Attempt to create products where each of the following required fields is missing/invalid separately:
 *    a) 'name' is empty string
 *    b) 'code' is empty string
 *    c) 'seller_id' is empty string (invalid UUID)
 * 4. For each invalid create attempt, verify a validation error is thrown (using TestValidator.error()), confirming the field is strictly required/non-blank.
 *
 * Only fields defined in IShoppingMallAiBackendProduct.ICreate are tested. Field omission at TypeScript level is NOT attempted (as forbidden by policy).
 */
export async function test_api_admin_product_creation_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "AdminPW" +
    typia.random<string>().replace(/\W+/g, "").slice(0, 6);
  const signUpResult = await api.functional.auth.admin.register.signUp(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IAdminAuth.SignUp,
    },
  );
  typia.assert(signUpResult);

  // 2. Login as the new admin
  const signInResult = await api.functional.auth.admin.login.signIn(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IAdminAuth.SignIn,
    },
  );
  typia.assert(signInResult);

  // 3. Build valid product creation DTO
  const validProduct: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    code: "SKU-" + typia.random<string>().replace(/\W+/g, "").slice(0, 8),
    name: "Test Product " + typia.random<string>().slice(0, 4),
    status: "draft",
  };

  // a) Empty 'name' required field
  await TestValidator.error("Product creation should fail with empty name")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.create(
        connection,
        {
          body: { ...validProduct, name: "" },
        },
      );
    },
  );

  // b) Empty 'code' required field
  await TestValidator.error("Product creation should fail with empty code")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.create(
        connection,
        {
          body: { ...validProduct, code: "" },
        },
      );
    },
  );

  // c) Empty 'seller_id' (invalid UUID)
  await TestValidator.error(
    "Product creation should fail with empty seller_id (invalid UUID)",
  )(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.create(
      connection,
      {
        body: { ...validProduct, seller_id: "" as string & tags.Format<"uuid"> },
      },
    );
  });
}

