import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendArticle";
import type { IPageIShoppingMallAiBackendArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendArticle";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for advanced article search, filtering, and pagination in the shopping mall AI admin backend.
 *
 * Validates that an admin can:
 *   1. Register and authenticate
 *   2. (Preparation step) Assume diverse articles exist in the system with varied statuses, categories, authors, keywords, and created/updated timestamps (as no direct article creation/management endpoints are provided in the accessible API). This test will focus only on the aspects covered by the available API contract.
 *   3. Search using multiple filters (status, categoryID, keyword, author, date ranges) and pagination controls.
 *   4. Verify search result correctness: ensure all returned articles match specified filters (especially status and category), and that pagination metadata is correct (current, limit, records, pages).
 *
 * Implementation steps:
 *   - Register a new admin user for API access.
 *   - Authenticate using the new admin registration (done implicitly—session set in connection).
 *   - Test search functionality with different filters:
 *     * Single status filter (e.g., published-only)
 *     * Multiple status values (repeat test for another status, e.g., draft)
 *     * Filter by category_id, keyword, author_type/author_id, date range (created_from/to, updated_from/to)
 *     * Test pagination by using different page/limit combinations and verifying result lengths and metadata.
 *     * Test with nulls or omitted filters for unfiltered mode (should return all articles in system and proper pagination).
 *   - For each case: verify that every article in results matches requested filters, and that pagination information is consistent with data.
 *
 * Limitation: Actual article insertion/data manipulation is not possible in this test—no API for CRUD provided. Testing is limited to search/read API contract. If/when creation APIs exist, test should be extended to programmatically create known-attribute articles and validate search results accordingly.
 */
export async function test_api_admin_article_advanced_search_and_pagination(connection: api.IConnection) {
  // 1. Register & authenticate a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Test1234!";
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminSignup);
  // Session is now authenticated as this admin in connection

  // Define possible filter combinations for testing
  const filterSets: IShoppingMallAiBackendArticle.IRequest[] = [
    // 2.1: No filter (all articles, default pagination)
    {},
    // 2.2: Status filter: published
    { status: "published" },
    // 2.3: Status filter: draft
    { status: "draft" },
    // 2.4: Pagination (page 2, limit: 3)
    { page: 2, limit: 3 },
    // 2.5: Sort fields and direction (sort by created_at desc)
    { sort_by: "created_at", sort_dir: "desc" },
    // 2.6: Keyword filter
    { keyword: "sale" },
    // 2.7: Category filter (using a dummy/likely category_id—no controlled data)
    { category_id: typia.random<string>() },
    // 2.8: Author type and id filter (no controlled data, just API validation)
    { author_type: "admin", author_id: adminSignup.adminId },
    // 2.9: Date range filter (from now minus 7 days, to now)
    {
      created_from: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString() as string & tags.Format<"date-time">,
      created_to: new Date().toISOString() as string & tags.Format<"date-time">,
    },
  ];

  for (const filter of filterSets) {
    // 3. Perform search with filter
    const result = await api.functional.shoppingMallAiBackend.admin.articles.search(connection, {
      body: filter,
    });
    typia.assert(result);
    TestValidator.predicate("pagination present")(typeof result.pagination === "object");
    TestValidator.predicate("data is array")(Array.isArray(result.data));

    // 4. Validate that each result matches the intended filter (where feasible)
    if (filter.status) {
      for (const art of result.data)
        TestValidator.equals("status matches")(art.status)(filter.status);
    }
    if (filter.author_id) {
      for (const art of result.data)
        TestValidator.equals("author matches")(art.author_id)(filter.author_id);
    }
    if (filter.category_id) {
      for (const art of result.data)
