/**
 * Verify that a seller cannot update a product snapshot they do not own (ownership enforcement, 403 forbidden).
 *
 * Steps:
 * 1. Register Seller A (the owner who will create product and snapshot)
 * 2. Register Seller B (non-owner who will attempt forbidden update)
 * 3. Seller A creates a product
 * 4. Seller A creates a product snapshot for that product
 * 5. Seller B attempts to update Seller A's snapshot
 *
 * Expectations:
 * - The update call by Seller B must be rejected (403 Forbidden)
 * - No changes are made to the snapshot record
 */
export async function test_api_product_snapshot_update_forbidden_on_non_owned_product(connection: api.IConnection) {
    // 1. Register Seller A
    const sellerAEmail = typia.random<string & tags.Format<"email">>();
    const sellerACompany = RandomGenerator.alphaNumeric(8);
    const sellerAResponse = await api.functional.auth.seller.register.signUp(connection, {
        body: {
            email: sellerAEmail,
            password: "TestPassword123!",
            companyName: sellerACompany,
            businessNumber: RandomGenerator.alphaNumeric(10),
            representativeName: RandomGenerator.name(),
            address: RandomGenerator.alphaNumeric(12),
            phone: RandomGenerator.mobile(),
        } satisfies ISellerAuth.SignUp
    });
    typia.assert(sellerAResponse);

    // Set Seller A's Auth token
    connection.headers = {
        ...(connection.headers ?? {}),
        Authorization: sellerAResponse.setHeaders.Authorization,
    };
    const sellerAId = sellerAResponse.sellerId;

    // 2. Register Seller B
    const sellerBEmail = typia.random<string & tags.Format<"email">>();
    const sellerBCompany = RandomGenerator.alphaNumeric(8);
    const sellerBResponse = await api.functional.auth.seller.register.signUp(connection, {
        body: {
            email: sellerBEmail,
            password: "TestPassword123!",
            companyName: sellerBCompany,
            businessNumber: RandomGenerator.alphaNumeric(10),
            representativeName: RandomGenerator.name(),
            address: RandomGenerator.alphaNumeric(12),
            phone: RandomGenerator.mobile(),
        } satisfies ISellerAuth.SignUp
    });
    typia.assert(sellerBResponse);

    // Switch back to Seller A
    connection.headers = {
        ...(connection.headers ?? {}),
        Authorization: sellerAResponse.setHeaders.Authorization,
    };

    // 3. Seller A creates a product
    const productCreate = {
        seller_id: sellerAId,
        code: RandomGenerator.alphaNumeric(12),
        name: RandomGenerator.paragraph()(2),
        description: RandomGenerator.paragraph()(2),
        status: "published",
        main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate;
    const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
        body: productCreate,
    });
    typia.assert(product);

    // 4. Seller A creates a product snapshot
    const snapshotCreate = {
        product_id: product.id,
        snapshot_code: RandomGenerator.alphaNumeric(16),
        snapshot_type: "created",
        name: product.name,
        description: product.description,
        main_image_uri: product.main_image_uri,
        status: product.status,
    } satisfies IShoppingMallAiBackendProductSnapshot.ICreate;
    const snapshot = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.create(connection, {
        productId: product.id,
        body: snapshotCreate,
    });
    typia.assert(snapshot);

    const originalSnapshot = { ...snapshot };

    // 5. Switch to Seller B and attempt forbidden snapshot update
    connection.headers = {
        ...(connection.headers ?? {}),
        Authorization: sellerBResponse.setHeaders.Authorization,
    };
    const updateBody: IShoppingMallAiBackendProductSnapshot.IUpdate = {
        name: RandomGenerator.paragraph()(1) + "_FORBIDDEN_EDIT",
        description: "HACK_ATTEMPT",
        main_image_uri: "http://malicious.test/image.png",
        status: "discontinued",
    };
    await TestValidator.error("403 forbidden for non-owner snapshot update")(async () => {
        await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.update(connection, {
            productId: product.id,
            productSnapshotId: snapshot.id,
            body: updateBody,
        });
    });

    // 6. Switch back to Seller A and confirm the snapshot was not changed silently
    connection.headers = {
        ...(connection.headers ?? {}),
        Authorization: sellerAResponse.setHeaders.Authorization,
    };
    // There's no GET endpoint defined to reload the snapshot, so we skip this step.
}

