 *
 * Step-by-step workflow:
 * 1. Create a product as Seller A.
 * 2. Create a product option for the above product as Seller A.
 * 3. Create a product option stock for this product option as Seller A.
 * 4. Retrieve the product option stock detail as Seller A and verify:
 *    - All response fields are present and correct
 *    - Referential integrity: productOptionId matches, all required foreign keys are valid
 *    - Data matches creation inputs
 * 5. Attempt retrieval from a different seller account (Seller B) and expect a 403 or 404 error.
 * 6. Attempt retrieval as an entirely non-authenticated/anonymous connection if supported and expect a 403 or 404 error.
 */
export async function test_api_product_option_stock_detail_success_and_permission(connection: api.IConnection) {
  // 1. Create a product (Seller A is implicit through authentication context)
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(),
      main_image_uri: RandomGenerator.alphaNumeric(12),
      status: "draft",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 2. Create a product option under the product
  const productOption = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: RandomGenerator.alphaNumeric(8),
      option_name: "Color",
      option_values: "Red,Green,Blue",
      extra_price: 100,
      main_image_uri: RandomGenerator.alphaNumeric(10),
      status: "active",
    } satisfies IShoppingMallAiBackendProductOption.ICreate,
  });
  typia.assert(productOption);

  // 3. Create a product option stock for this option
  const productOptionStock = await api.functional.shoppingMallAiBackend.seller.productOptions.productOptionStocks.create(connection, {
    productOptionId: productOption.id,
    body: {
      product_option_id: productOption.id,
      stock_count: 50,
      safety_stock: 10,
      inbound_count: 5,
      warehouse_location: "A1-02-01",
      status: "active",
    } satisfies IShoppingMallAiBackendProductOptionStock.ICreate,
  });
  typia.assert(productOptionStock);

  // 4. Retrieve the product option stock detail as Seller A
