  TestValidator.equals("product option id matches")(output.product_option_id)(productOption.id);
  TestValidator.equals("stock id matches")(output.id)(productOptionStock.id);
  TestValidator.equals("stock count matches")(output.stock_count)(productOptionStock.stock_count);
  TestValidator.equals("warehouse location matches")(output.warehouse_location)(productOptionStock.warehouse_location);
  TestValidator.equals("status matches")(output.status)(productOptionStock.status);

  // 5. Attempt retrieval from another seller (should be forbidden or not found)
  // Simulate a different seller context (Seller B)
  const sellerBConnection = { ...connection, headers: { ...connection.headers, Authorization: "Bearer " + RandomGenerator.alphaNumeric(32) } };
  await TestValidator.error("access denied for non-owning seller")(async () => {
    await api.functional.shoppingMallAiBackend.seller.productOptions.productOptionStocks.at(sellerBConnection, {
      productOptionId: productOption.id,
      productOptionStockId: productOptionStock.id,
    });
  });

  // 6. Attempt retrieval as unauthenticated/anonymous (should be forbidden or not found)
  const anonymousConnection = { ...connection, headers: {} };
  await TestValidator.error("access denied for anonymous")(async () => {
    await api.functional.shoppingMallAiBackend.seller.productOptions.productOptionStocks.at(anonymousConnection, {
      productOptionId: productOption.id,
      productOptionStockId: productOptionStock.id,
    });
  });
