/**
 * Test creation and validation of product content creation by a seller.
 *
 * This test simulates a complete business workflow in which a new seller registers, creates a product, 
 * and then adds product content (such as an image or video) to the product. It validates both successful
 * content creation and expected error scenarios including missing fields, invalid values, and duplicate ordering.
 *
 * Steps:
 * 1. Register as a seller (Get seller ID and credentials)
 * 2. Create a product as the seller (Get product ID)
 * 3. Create valid product content for the product (image or video, with proper content_type/content_uri/content_order/status)
 * 4. Assert product content is created and all required fields are present and valid
 * 5. Test error: missing required field (e.g., missing content_type)
 * 6. Test error: invalid content_type (value not allowed by the platform)
 * 7. Test error: malformed content_uri (invalid format for a URI)
 * 8. Test error: duplicate content for the same product and same content_order (should be rejected)
 */
export async function test_api_product_content_creation_and_validation(connection: api.IConnection) {
  // 1. Register as a new seller
  const email = typia.random<string & tags.Format<"email">>();
  const signUpResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email,
