      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Create a product as the seller
  // Set Authorization header for this seller session
  connection.headers = {
    ...connection.headers,
    Authorization: signUpResponse.setHeaders.Authorization,
  };
  const sellerId = signUpResponse.sellerId;
  const createProduct = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(8),
