import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test that a seller can search for their own products using filter, pagination, and sort criteria, and verify that products outside of their scope are not included.
 * 
 * This test performs the following steps:
 * 1. Register two separate sellers (Seller A and Seller B)
 * 2. Authenticate as Seller A
 * 3. (Assume products are pre-existing or simulate existence for Seller A and B)
 * 4. Search with no filters and verify only Seller A products are returned
 * 5. Search using code/name/status filter for a Seller A product and expect a hit, then filter using Seller B's product attributes and expect no results
 * 6. Attempt to use sellerId filter (admin-only) as Seller A and assert results are still correctly scoped
 * 7. Attempt unauthorized access (simulate unauthenticated request) and expect access control error or empty result
 */
export async function test_api_seller_product_search_role_and_scope_enforcement(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAOutput = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerAOutput);
  const sellerAId = sellerAOutput.sellerId;

  // 2. Register Seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBOutput = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerBOutput);
  const sellerBId = sellerBOutput.sellerId;

  // 3. Authenticate as Seller A
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerAEmail,
      password: "Password123!",
    },
  });

  // 4. Search for all products as Seller A (should only get Seller A's products)
  const allAProducts = await api.functional.shoppingMallAiBackend.seller.products.search(connection, {
    body: {},
  });
  typia.assert(allAProducts);
  TestValidator.predicate("all returned products belong to Seller A")(allAProducts.data.every((p) => p.seller_id === sellerAId));

  // 5. Test filter that yields no results
  const nonExistentFilterResult = await api.functional.shoppingMallAiBackend.seller.products.search(connection, {
    body: { filter: { code: "non-existent-code-for-test" } },
  });
  typia.assert(nonExistentFilterResult);
  TestValidator.equals("no result for impossible code filter")(nonExistentFilterResult.data.length)(0);

  // 6. Attempt admin-only filter: sellerId as Seller A
  const sellerIdFilterResult = await api.functional.shoppingMallAiBackend.seller.products.search(connection, {
    body: { filter: { sellerId: sellerBId } },
  });
  typia.assert(sellerIdFilterResult);
  TestValidator.equals("no cross-seller data leakage")(sellerIdFilterResult.data.length)(0);

  // 7. Unauthorized access: temporarily remove auth header
  const noAuthConnection = { ...connection, headers: { ...connection.headers } };
  delete noAuthConnection.headers.Authorization;

  await TestValidator.error("unauthorized search fails or yields no data")(async () => {
    const out = await api.functional.shoppingMallAiBackend.seller.products.search(noAuthConnection, {
      body: {},
    });
    typia.assert(out);
    TestValidator.equals("unauthorized must yield no product data")(out.data.length)(0);
  });
}

