import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderSnapshot";

/**
 * Validate that a customer can retrieve the details of a specific order snapshot belonging to their own order.
 *
 * This test confirms that once a customer places an order and at least one snapshot has been created (via admin or system action), the customer can access the details of that snapshot using the correct orderId and orderSnapshotId. It also covers error scenarios including:
 *   - Nonexistent snapshot ID (404 or error expected)
 *   - Accessing a snapshot from an order not owned by the customer (403 or error expected)
 *   - Accessing a deleted/invalid snapshot (404 or error expected)
 *
 * Steps:
 * 1. Create a new order as a (simulated) customer (API: POST /shoppingMallAiBackend/customer/orders)
 * 2. Simulate/trigger a status change: create an order snapshot as admin for that order (API: POST /shoppingMallAiBackend/admin/orders/{orderId}/orderSnapshots)
 * 3. Read the snapshot as customer via /shoppingMallAiBackend/customer/orders/{orderId}/orderSnapshots/{orderSnapshotId}
 * 4. Validate that the returned details match the snapshot record (IDs, foreign keys, JSON fields etc)
 * 5. Negative: Try accessing with a bogus snapshotId (expect error)
 * 6. Negative: Try accessing a snapshot using a different orderId or from a non-customer context (access denied/error expected)
 *
 * Note: This scenario assumes connection context is always customer, as only the customer endpoint is being tested. No customer creation/auth endpoint is available so connection simulates that contextual permission.
 */
export async function test_api_order_snapshot_detail_customer_own_order_access(connection: api.IConnection) {
  // 1. Create a new order as a customer
  const orderCreate = typia.random<IShoppingMallAiBackendOrder.ICreate>();
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderCreate });
  typia.assert(order);

  // 2. Trigger a status event: create order snapshot as admin
  const snapshotBody = {
    snapshot_json: JSON.stringify(order),
    snapshot_reason: "created"
  } satisfies IShoppingMallAiBackendOrderSnapshot.ICreate;
  const snapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.create(connection, { orderId: order.id, body: snapshotBody });
  typia.assert(snapshot);

  // 3. Retrieve the snapshot detail as customer
  const acquired = await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.at(connection, { orderId: order.id, orderSnapshotId: snapshot.id });
  typia.assert(acquired);
  // 4. Validate detail fields
  TestValidator.equals("order_id linkage")(acquired.order_id)(order.id);
  TestValidator.equals("unique snapshot id")(acquired.id)(snapshot.id);
  TestValidator.equals("correct snapshot json")(acquired.snapshot_json)(snapshotBody.snapshot_json);
  TestValidator.equals("snapshot reason")(acquired.snapshot_reason)(snapshotBody.snapshot_reason);

  // 5. Error case: access with non-existent snapshotId
  await TestValidator.error("not found on bogus snapshot")(async () => {
    await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.at(connection, { orderId: order.id, orderSnapshotId: typia.random<string & tags.Format<"uuid">>() });
  });

  // 6. Error case: snapshot not belonging to this order
  // Create a second order and snapshot, then mismatch
  const anotherOrderCreate = typia.random<IShoppingMallAiBackendOrder.ICreate>();
  const anotherOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: anotherOrderCreate });
  typia.assert(anotherOrder);
  const anotherSnapshotBody = {
    snapshot_json: JSON.stringify(anotherOrder),
    snapshot_reason: "created"
  } satisfies IShoppingMallAiBackendOrderSnapshot.ICreate;
  const anotherSnapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.create(connection, { orderId: anotherOrder.id, body: anotherSnapshotBody });
  typia.assert(anotherSnapshot);
  // Try to retrieve this snapshot using the first orderId
  await TestValidator.error("snapshot does not belong to order")(async () => {
    await api.functional.shoppingMallAiBackend.customer.orders.orderSnapshots.at(connection, { orderId: order.id, orderSnapshotId: anotherSnapshot.id });
  });
}

