 *
 * This test validates that the backend enforces business-level uniqueness for product codes (SKU/external sync ID) within the seller API. The flow simulates a new seller onboarding, product registration, and attempts to register a duplicate product with the same code. The API must reject the duplicate and return an error according to contract, ensuring system integrity and uniqueness constraints on codes.
 * 
 * Steps:
 * 1. Register a new seller with unique credentials (email, business number, etc).
 * 2. Authenticate/login the seller to setup Authorization (JWT).
 * 3. Register a product with a generated unique SKU/code and minimum required fields.
 * 4. Attempt to create a second product with the exact same seller_id and SKU/code.
 * 5. Verify that the second registration attempt is rejected with a business error.
 */
export async function test_api_seller_product_creation_duplicate_code(
  connection: api.IConnection,
) {
  // 1. Register seller
  const sellerProfile = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "abcTest1234!",
    companyName: "AI Test LLC",
    businessNumber: RandomGenerator.alphaNumeric(10),
    representativeName: RandomGenerator.name(),
    address: "Test Address 101",
    phone: "010" + RandomGenerator.alphaNumeric(8),
  } satisfies ISellerAuth.SignUp;
  const sellerRegisterResp = await api.functional.auth.seller.register.signUp(
    connection,
    { body: sellerProfile },
  );
  typia.assert(sellerRegisterResp);
  const seller_id = sellerRegisterResp.sellerId;
  const seller_email = sellerRegisterResp.email;

  // 2. Authenticate as that seller
  const sellerLoginResp = await api.functional.auth.seller.login.signIn(
    connection,
    {
      body: {
        email: seller_email,
        password: sellerProfile.password,
      } satisfies ISellerAuth.SignIn,
    },
  );
  typia.assert(sellerLoginResp);

  // 3. Register a product as this seller
  const productCode = RandomGenerator.alphaNumeric(10);
  const productDraft = {
    seller_id: seller_id,
    code: productCode,
    name: "AI Widget Alpha",
    status: "draft",
    description: "First test product by automation",
    main_image_uri: null,
  } satisfies IShoppingMallAiBackendProduct.ICreate;
  const product1 = await api.functional.shoppingMallAiBackend.seller.products.create(
    connection,
    { body: productDraft },
  );
  typia.assert(product1);
  TestValidator.equals("sellerId matches")(product1.seller_id)(seller_id);
  TestValidator.equals("SKU/code matches")(product1.code)(productCode);

  // 4. Attempt to register another product with the same seller_id and code (should fail)
  const productDuplicateDraft = {
    seller_id: seller_id,
    code: productCode,
    name: "AI Widget Beta",
    status: "draft",
    description: "Duplicate test for SKU",
    main_image_uri: null,
  } satisfies IShoppingMallAiBackendProduct.ICreate;
  await TestValidator.error("duplicate product registration forbidden")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.create(
        connection,
        { body: productDuplicateDraft },
      );
    },
  );
}

