import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartItem";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that attempting to access a nonexistent cart item in a valid cart returns the appropriate error and does not leak sensitive data.
 *
 * This test ensures the system enforces cart item ownership boundaries and returns a clear not found error, matching business logic for security compliance.
 *
 * Step-by-step process:
 * 1. Register a new customer for test ownership context.
 * 2. Create a new cart for that customer (successfully authenticating the session).
 * 3. Attempt to fetch a cart item detail using a cartItemId that does not exist within the valid cart (use a fresh random UUID never assigned).
 * 4. Confirm that the server responds with a business error (typically not found—404 error), and that no cart or product data is returned. Confirm that no sensitive information about the cart or any other cart items is leaked in the response.
 * 5. Ensure system stability and error information is generic, revealing as little as possible about internal state.
 */
export async function test_api_cart_item_not_found_invalid_item_id(connection: api.IConnection) {
    // 1. Register test customer (authenticate automatically, JWT set)
    const customerEmail = typia.random<string & tags.Format<"email">>();
    const signup = await api.functional.auth.customer.register.signUp(connection, {
        body: {
            email: customerEmail,
            password: "TestPassword123!",
            name: RandomGenerator.name(),
            nickname: RandomGenerator.alphaNumeric(8),
            phone: RandomGenerator.mobile(),
        } satisfies ICustomerSignUp.Request,
    });
    typia.assert(signup);

    // 2. Create a new cart for this customer -- must be authorized (token set automatically from registration)
    const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
        body: {
            status: "active",
            session_token: null,
        } satisfies IShoppingMallAiBackendCart.ICreate,
    });
    typia.assert(cart);

    // 3. Attempt to fetch a cart item detail using a random (invalid) cartItemId in the valid cart
    const invalidCartItemId = typia.random<string & tags.Format<"uuid">>(); // Assumed not assigned
    await TestValidator.error("should return not found error for invalid cartItemId")(async () => {
        await api.functional.shoppingMallAiBackend.customer.carts.cartItems.at(connection, {
            cartId: cart.id,
            cartItemId: invalidCartItemId,
        });
    });
}

