import type { IShoppingMallAiBackendSellerBusinessVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSellerBusinessVerification";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that an admin user can retrieve the details of a seller's business verification record, including full audit and compliance information, file attachments, and deletion annotations.
 *
 * Steps:
 * 1. Authenticate as an admin to enable access to admin endpoints.
 * 2. Set up a business verification record for a seller using the admin function.
 * 3. Retrieve the detail of this business verification record as the admin.
 * 4. Assert that all system fields are present — document type, file URI, reviewer, status, notes, timestamps for creation/update, and any deletion markers.
 * 5. Confirm that accessing the record does not fail for non-deleted records and that soft-deleted records show deleted_at annotation.
 * 6. Confirm the record’s data integrity matches what was set up and/or updated.
 * 7. Confirm admin access triggers audit/compliance logging (if API exposes this).
 */
export async function test_api_admin_get_seller_business_verification_detail_success_and_compliance(connection: api.IConnection) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Password123!";
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(adminSignIn);
  // 2. Create a business verification record (PUT as admin)
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const verificationInput: IShoppingMallAiBackendSellerBusinessVerification.IUpdate = {
    id: typia.random<string & tags.Format<"uuid">>(),
    document_file_uri: "https://fileserver.test/kyc/license-file.pdf",
    verification_status: "pending",
    document_file_uri: "https://fileserver.test/kyc/license-file.pdf",
    reviewed_by: null,
    reviewed_at: null,
    note: null
  };
  const createdVerification = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
    sellerId,
    body: verificationInput
  });
  typia.assert(createdVerification);
  // 3. GET detail as admin
  const readVerification = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.at(connection, {
    sellerId,
    businessVerificationId: createdVerification.id
  });
  typia.assert(readVerification);
  // 4. Assert fields: id, seller_id, document_type, document_file_uri, verification_status, reviewed_by, reviewed_at, note, created_at, updated_at, deleted_at
  TestValidator.equals("id matches")(readVerification.id)(createdVerification.id);
  TestValidator.equals("seller_id matches")(readVerification.seller_id)(sellerId);
  TestValidator.equals("document_file_uri matches")(readVerification.document_file_uri)(verificationInput.document_file_uri);
  TestValidator.equals("status matches")(readVerification.verification_status)(verificationInput.verification_status);
  TestValidator.equals("reviewed_by matches")(readVerification.reviewed_by)(verificationInput.reviewed_by);
  TestValidator.equals("reviewed_at matches")(readVerification.reviewed_at)(verificationInput.reviewed_at);
  TestValidator.equals("note matches")(readVerification.note)(verificationInput.note);
  // Validate audit fields
  TestValidator.predicate("created_at valid")(!!readVerification.created_at);
  TestValidator.predicate("updated_at valid")(!!readVerification.updated_at);
  // 5. Simulate soft-delete and confirm deleted_at is annotated
  const deletedInput: IShoppingMallAiBackendSellerBusinessVerification.IUpdate = {
    id: createdVerification.id,
    verification_status: "rejected",
    note: "Soft deletion for compliance test",
    reviewed_by: "admin-qa",
    reviewed_at: new Date().toISOString(),
    document_file_uri: createdVerification.document_file_uri
  };
  // (Assume updating status to rejected and setting note simulates deletion)
  const deletedResult = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.update(connection, {
    sellerId,
    body: deletedInput
  });
  typia.assert(deletedResult);
  // GET again
  const readAfterDelete = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.at(connection, {
    sellerId,
    businessVerificationId: createdVerification.id
  });
  typia.assert(readAfterDelete);
  TestValidator.equals("deleted_at present")(typeof readAfterDelete.deleted_at === "string")(true);
  // 6. Check audit event or log (if such an API is available—skip if not present)
  // 7. Field-by-field integrity for compliance view
  // The response has all fields described by schema; any missing or anomalous values should fail validation.
}

