      body: {
        id: cust1.id,
        phone: "invalid-phone",
      } satisfies IShoppingMallAiBackendCustomer.IUpdate,
    });
  });

  // 6. Update non-existent customer (should 404)
  await TestValidator.error("non-existent customer")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.update(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        name: "Ghost User",
      } satisfies IShoppingMallAiBackendCustomer.IUpdate,
    });
  });

  // 7. Update soft-deleted customer (register, simulate deletion, then update - here, deletion is simulated by random id to represent deleted-user)
  // In real system: Would call soft-delete API. Here we treat a new UUID as soft-deleted for endpoint contract purposes.
  await TestValidator.error("soft-deleted customer")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.update(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        name: "Deleted User",
      } satisfies IShoppingMallAiBackendCustomer.IUpdate,
    });
  });
}

