/**
 * Validate customer-initiated cart item soft delete operation.
 *
 * This test covers the workflow where a customer removes an item from their shopping cart via a *soft deletion* API call. The process includes user registration, cart and cart item creation, and the logical deletion action. Critical validations include verifying the soft deletion sets the `deleted_at` timestamp, the item is omitted from active queries, the operation is preserved for audit/evidence, and other cart items remain unaffected.
 *
 * Step-by-step:
 * 1. Register a new customer (with unique email and phone for test isolation).
 * 2. Create a new cart for the customer with 'active' status.
 * 3. Add a cart item (with random product_id, pricing, and quantity).
 * 4. Delete the cart item via soft delete API.
 * 5. Re-query the cart item (using direct ID lookup if such endpoint existed, else skip direct get).
 * 6. (If possible) List all active cart items in the cart and confirm soft-deleted item is omitted, but data can be inspected for audit (by checking the deleted_at field post-deletion).
 * 7. Confirm other cart or cart item state is unaffected.
 */
export async function test_api_cart_item_soft_delete_by_customer_success(connection: api.IConnection) {
  // 1. Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPhone = RandomGenerator.mobile();
  const customerSignUp: ICustomerSignUp.Response = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "TestPassword!234",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: customerPhone,
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  TestValidator.equals("setHeaders present")(typeof customerSignUp.setHeaders.Authorization)("string");
  // The connection becomes authenticated due to auth token in headers

  // 2. Create a cart for the customer
  const cart: IShoppingMallAiBackendCart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    } satisfies IShoppingMallAiBackendCart.ICreate,
  });
  typia.assert(cart);
  TestValidator.equals("cart is active")(cart.status)("active");
  TestValidator.equals("deleted_at null (active cart)")(cart.deleted_at)(null);

  // 3. Add a cart item to the cart
  const cartItem: IShoppingMallAiBackendCartItem = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
    cartId: cart.id,
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      product_option_id: null,
      quantity: 1,
      unit_price: 9000.0,
      currency_code: "KRW",
      note: "Soft delete test",
    } satisfies IShoppingMallAiBackendCartItem.ICreate,
  });
  typia.assert(cartItem);
  TestValidator.equals("cartItem is present and not deleted")(cartItem.deleted_at)(null);
  TestValidator.equals("cart Id matches on cart item")(cartItem.quantity)(1);

  // 4. Perform soft delete on the cart item
  await api.functional.shoppingMallAiBackend.customer.carts.cartItems.erase(connection, {
    cartId: cart.id,
    cartItemId: cartItem.id,
  });

