  // 6. (Not implementable) There is no list endpoint for cart items to confirm omission from active queries, nor for audit inspection; asserted via step 4 is a no-op.

  // 7. The deletion must not affect other cart state; check cart still exists and is active.
  // As no method to get cart again is available, this is assumed by lack of error. Optionally, re-create a new item to validate cart is still usable.
  const cartItem2: IShoppingMallAiBackendCartItem = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
    cartId: cart.id,
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      product_option_id: null,
      quantity: 1,
      unit_price: 11000.0,
      currency_code: "KRW",
      note: "Reinsertion post-soft-delete test",
    } satisfies IShoppingMallAiBackendCartItem.ICreate,
  });
  typia.assert(cartItem2);
  TestValidator.equals("cart still active after soft delete")(cartItem2.deleted_at)(null);
  TestValidator.notEquals("new cartItemId")(cartItem2.id)(cartItem.id);
}

