  // 1. Admin creates a new channel
  const admin_id = typia.random<string & tags.Format<"uuid">>();
  const channelCreate = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.alphabets(8),
    created_by_admin_id: admin_id,
    description: RandomGenerator.paragraph()(),
    logo_url: null,
    active: true
  } satisfies IShoppingMallAiBackendChannel.ICreate;
  const channel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, { body: channelCreate });
