import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate update and permission logic for coin wallet updates (admin endpoint).
 *
 * This test ensures only allowed fields (wallet_status, wallet_label, security_code) of an admin-owned coin wallet are mutable and that update attempts on immutable fields (wallet_address, owner references) fail. It also verifies admin-only role access, update on non-existent and deleted wallets, and correct audit trail field behavior.
 *
 * Steps:
 * 1. Authenticate as admin (via /auth/admin/login)
 * 2. Create a coin wallet (with admin ownership, via /shoppingMallAiBackend/admin/coinWallets)
 * 3. Update allowed mutable fields (status, label, security_code) – verify update
 * 4. Attempt to update forbidden/immutable fields (simulate as business logic, expect server error)
 * 5. Attempt to update a non-existent wallet – expect not found/error
 * 6. Simulate deleted wallet then attempt update – expect error
 * 7. Verify audit trail behavior (updated_at > created_at)
 */
export async function test_api_coin_wallet_update_valid_and_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPW_!234";
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 2. Create a coin wallet (admin ownership)
  const createBody: IShoppingMallAiBackendCoinWallet.ICreate = {
    wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
    wallet_type: "mainnet",
    wallet_status: "active",
    wallet_address: typia.random<string>(),
    wallet_label: "Initial Coin Wallet",
    security_code: "1234",
  };
  const created = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, { body: createBody });
  typia.assert(created);
  TestValidator.equals("create fields match")(created.wallet_owner_admin_id)(createBody.wallet_owner_admin_id);
  TestValidator.equals("wallet_type match")(created.wallet_type)(createBody.wallet_type);
  TestValidator.equals("wallet_status match")(created.wallet_status)(createBody.wallet_status);
  TestValidator.equals("wallet_address match")(created.wallet_address)(createBody.wallet_address);
  TestValidator.equals("wallet_label match")(created.wallet_label)(createBody.wallet_label);
  TestValidator.equals("security_code match")(created.security_code)(createBody.security_code);

  // 3. Update allowed/mutable fields
  const updateBody: IShoppingMallAiBackendCoinWallet.IUpdate = {
    wallet_status: "locked",
    wallet_label: "Updated label",
    security_code: "9999",
  };
  const updated = await api.functional.shoppingMallAiBackend.admin.coinWallets.update(connection, {
    coinWalletId: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("status changed")(updated.wallet_status)(updateBody.wallet_status);
  TestValidator.equals("label changed")(updated.wallet_label)(updateBody.wallet_label);
  TestValidator.equals("security_code changed")(updated.security_code)(updateBody.security_code);
  TestValidator.equals("address unchanged")(updated.wallet_address)(created.wallet_address);
  TestValidator.equals("owner ID unchanged")(updated.wallet_owner_admin_id)(created.wallet_owner_admin_id);

  // 4. Attempt to update immutable fields (simulate forbidden change logic)
  await TestValidator.error("immutable fields cannot be updated")(async () => {
    // Even though TypeScript doesn't let us send forbidden fields, simulate bad API payload as any
    await api.functional.shoppingMallAiBackend.admin.coinWallets.update(connection, {
      coinWalletId: created.id,
      body: {
        wallet_status: "active",
        wallet_address: typia.random<string>(), // forbidden
        wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(), // forbidden
      } as any,
    });
  });

  // 5. Attempt update of non-existent wallet
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update on non-existent wallet fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.update(connection, {
      coinWalletId: randomId,
      body: updateBody,
    });
  });

  // 6. Simulate deleted wallet then try update (since no real delete, just try new wallet update expecting error for deleted_at logic)
  const toDelete = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, { body: { ...createBody, wallet_address: typia.random<string>() } });
  typia.assert(toDelete);
  // (If the API let us flag deleted_at, we'd set it and expect rejection. Here, just expect logic error for possibly soft-deleted wallets)
  await TestValidator.error("update on deleted wallet fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.update(connection, {
      coinWalletId: toDelete.id,
      body: updateBody,
    });
  });

  // 7. Verify audit trail works (updated_at should increase on successful update)
  TestValidator.predicate("updated_at advanced")(new Date(updated.updated_at).getTime() > new Date(updated.created_at).getTime());
}

