      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(intruderSignUpResponse);
  const intruderCustomer = intruderSignUpResponse.customer;
  const intruderCustomerId = intruderCustomer.id;
  // Sign-in as intruder is assumed to occur automatically after registration

