import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendPoint";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin's ability to retrieve a customer point wallet using a valid pointId.
 *
 * This test ensures that an admin can successfully fetch a customer's point wallet by pointId and that the returned details correctly represent the wallet's actual state. The test simulates real-world business workflow, including admin registration, customer onboarding, wallet creation for that customer, and verification of retrieval. It validates correct identity association, balance, and data consistency between creation and viewing endpoints.
 *
 * **Step-by-step process:**
 * 1. Register a new admin using a unique email/password (admin privileges are required for wallet creation and queries).
 * 2. Register a new customer with required fields (email, password, name, nickname, phone).
 * 3. As admin, create a new point wallet assigned to the customer's id with a chosen initial balance. Capture the returned pointId.
 * 4. Fetch the point wallet using the API under test by providing the extracted pointId.
 * 5. Assert that the fetched payload matches expected values: id, customer_id, balance, and updated_at.
 * 6. Validate no data mismatch between wallet creation and retrieval.
 */
export async function test_api_admin_view_point_wallet_valid_id(connection: api.IConnection) {
  // 1. Register the admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Password!123";

  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminReg);

  // 2. Register the customer account
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "customerPASS@123";
  const customerNickname = RandomGenerator.alphaNumeric(8);
  const customerName = RandomGenerator.name();
  const customerPhone = RandomGenerator.mobile();

  const customerReg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: customerName,
      nickname: customerNickname,
      phone: customerPhone
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerReg);
  const customerId = customerReg.customer.id;

  // 3. As admin, create a new point wallet for the above customer
  //    Use a random positive starting balance
  const initialBalance = typia.random<number & tags.Type<"uint32"> & tags.Minimum<1000> & tags.Maximum<100000>>();
  const createdWallet = await api.functional.shoppingMallAiBackend.admin.points.create(connection, {
    body: {
      customer_id: customerId,
      balance: initialBalance
    } satisfies IShoppingMallAiBackendPoint.ICreate
  });
  typia.assert(createdWallet);

  // 4. Retrieve the point wallet by pointId
  const fetchedWallet = await api.functional.shoppingMallAiBackend.admin.points.at(connection, {
    pointId: createdWallet.id
  });
  typia.assert(fetchedWallet);

  // 5. Validate returned data matches wallet creation
  TestValidator.equals("wallet id matches")(fetchedWallet.id)(createdWallet.id);
  TestValidator.equals("customer association matches")(fetchedWallet.customer_id)(customerId);
  TestValidator.equals("balance matches")(fetchedWallet.balance)(initialBalance);
  // updated_at validation is beyond initial balance but should be a correct ISO timestamp
  TestValidator.predicate("valid updated_at format")(
    typeof fetchedWallet.updated_at === "string" && !isNaN(Date.parse(fetchedWallet.updated_at))
  );
}

