/**
 * Validate update process of admin account profile fields (excluding password) as another admin user.
 *
 * This test covers several critical cases:
 *
 * 1. Successfully update permissible fields of an existing admin (role/status/name) as another admin, then verify updates via a subsequent search.
 * 2. Attempt update with missing or invalid fields (e.g., name=null, invalid role/status)—expect a validation failure.
 * 3. Attempt update with an ID that does not exist—expect not found error.
 * 4. Confirm that attempting to update password field is blocked for this endpoint.
 * 5. Attempt update with a non-admin (unauthorized) role/token—expect forbidden error.
 *
 * Steps:
 * 1. Login as an admin (to get privileges)
 * 2. Obtain an existing admin's id via admins search endpoint (for valid update)
 * 3. Update allowed fields (name, role, status) for that id (PUT /shoppingMallAiBackend/admin/admins) and verify changes via search
 * 4. Attempt update with body missing all allowed fields (should fail validation)
 * 5. Attempt update with invalid role/status values (should fail validation)
 * 6. Attempt update for a random UUID not corresponding to any admin (should fail not found)
 * 7. Attempt to supply a password change (should have no effect)
 * 8. Simulate update attempt when not authenticated as admin (e.g., remove Authorization header) and confirm forbidden
 */
export async function test_api_admin_update_profile_fields_and_error_handling(connection: api.IConnection) {
  // 1. Login as an admin to obtain privilege
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "test-Password123!";
  // Assume admin already exists. Otherwise, sign-up logic would be required.
  // For test, login as this admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignIn,
  });
  // 2. Obtain an existing admin's id (excluding the logged-in admin if possible)
  const adminList = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: { limit: 10 } satisfies IShoppingMallAiBackendAdmin.IRequest,
  });
  typia.assert(adminList);
  const targetAdmin = adminList.data.find(a => a.email !== adminEmail) ?? adminList.data[0];
  let baseAdmin = targetAdmin ?? adminList.data[0];
  typia.assert(baseAdmin);
  // 3. Update permissible fields (name, role, status)
  const updatedName = baseAdmin.name + "_updated";
  const updatedRole = baseAdmin.role === "operator" ? "auditor" : "operator";
  const updatedStatus = baseAdmin.status === "active" ? "suspended" : "active";
  const updateResult = await api.functional.shoppingMallAiBackend.admin.admins.update(connection, {
    body: { id: baseAdmin.id, name: updatedName, role: updatedRole, status: updatedStatus } satisfies IShoppingMallAiBackendAdmin.IUpdate,
  });
  typia.assert(updateResult);
  TestValidator.equals("admin name updated")(updateResult.name)(updatedName);
  TestValidator.equals("admin role updated")(updateResult.role)(updatedRole);
  TestValidator.equals("admin status updated")(updateResult.status)(updatedStatus);
  // 4. Fetch updated admin from list to confirm
  const adminAfter = (await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: { email: baseAdmin.email } satisfies IShoppingMallAiBackendAdmin.IRequest,
  })).data.find(a => a.id === baseAdmin.id);
  TestValidator.equals("name reflected")(adminAfter?.name)(updatedName);
  TestValidator.equals("role reflected")(adminAfter?.role)(updatedRole);
  TestValidator.equals("status reflected")(adminAfter?.status)(updatedStatus);
  // 5. Attempt update with missing all permitted fields (should fail)
  await TestValidator.error("update with missing fields fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.admins.update(connection, {
      body: { id: baseAdmin.id } satisfies IShoppingMallAiBackendAdmin.IUpdate,
    });
  });
  // 6. Attempt update with invalid role/status (should fail)
  await TestValidator.error("update with invalid role fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.admins.update(connection, {
      body: { id: baseAdmin.id, name: "Invalid", role: "banana", status: "apple" } satisfies IShoppingMallAiBackendAdmin.IUpdate,
    });
  });
  // 7. Attempt update for a non-existent admin id
  await TestValidator.error("update non-existent id fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.admins.update(connection, {
      body: { id: typia.random<string & tags.Format<"uuid">>(), name: "NotExist" } satisfies IShoppingMallAiBackendAdmin.IUpdate,
    });
  });
  // 8. Simulate update with password field—ensure it is ignored (IUpdate type does not contain password, so cannot send it; type violation, test is skipped)
  // 9. Simulate unauthorized role (remove Authorization header)
  const noAuthConnection = { ...connection, headers: { ...connection.headers } };
  delete noAuthConnection.headers["Authorization"];
  await TestValidator.error("update with no auth is forbidden")(async () => {
    await api.functional.shoppingMallAiBackend.admin.admins.update(noAuthConnection, {
      body: { id: baseAdmin.id, name: "UnauthorizedAttempt" } satisfies IShoppingMallAiBackendAdmin.IUpdate,
    });
  });
}

