import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAccessLog";
import type { IPageIShoppingMallAiBackendAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAccessLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate detailed access log retrieval by an authenticated admin.
 *
 * This test ensures that an authenticated admin user can successfully retrieve a specific access log entry by its accessLogId. It verifies that the admin receives a complete set of access log details without overexposure of sensitive data or omission of required audit fields.
 *
 * Steps:
 * 1. Admin login: Authenticate as an administrator and ensure the JWT is properly stored for use in authorization headers.
 * 2. Access log search: Search the access logs to obtain at least one valid log ID (accessLogId) required for the detail retrieval test.
 * 3. Access log detail: Fetch the full details for the selected accessLogId using the 'getByAccesslogid' endpoint.
 * 4. Validation: Assert all key audit fields are present and expected (id, occurred_at, actor_id, actor_type, access_type, source_ip, access_payload, etc.), and data matches the summary row in the log search results.
 */
export async function test_api_access_log_retrieve_valid_admin_access(
  connection: api.IConnection,
) {
  // 1. Admin login to obtain valid JWT and session
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "1234-AdminPass!";
  const adminAuth: IAdminAuth.JwtWithProfile = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);

  // 2. Access log search (to retrieve a valid log entry's ID for lookup)
  const searchResult = await api.functional.shoppingMallAiBackend.admin.accessLogs.search(connection, {
    body: {
      limit: 1, // ensure at least one record, ignoring filters for test coverage
      page: 0,
      // other fields left null for broad fetch
    } satisfies IShoppingMallAiBackendAccessLog.IRequest,
  });
  typia.assert(searchResult);
  TestValidator.predicate("at least one access log entry exists")(searchResult.data.length > 0);
  const pickedLog = searchResult.data[0];

  // 3. Retrieve detail for picked accessLogId
  const detail = await api.functional.shoppingMallAiBackend.admin.accessLogs.at(connection, {
    accessLogId: pickedLog.id,
  });
  typia.assert(detail);

  // 4. Validate critical audit fields are present and match the summary from search
  TestValidator.equals("accessLogId matches")(detail.id)(pickedLog.id);
  TestValidator.equals("occurred_at matches")(detail.occurred_at)(pickedLog.occurred_at);
  TestValidator.equals("actor_id matches")(detail.actor_id)(pickedLog.actor_id);
  TestValidator.equals("actor_type matches")(detail.actor_type)(pickedLog.actor_type);
  TestValidator.equals("access_type matches")(detail.access_type)(pickedLog.access_type);
  TestValidator.equals("source_ip matches")(detail.source_ip)(pickedLog.source_ip);
  TestValidator.equals("user_agent matches")(detail.user_agent)(pickedLog.user_agent);
  TestValidator.equals("location_label matches")(detail.location_label)(pickedLog.location_label);
  TestValidator.equals("access_payload matches")(detail.access_payload)(pickedLog.access_payload);

  // Make sure no non-permitted/sensitive fields are present (beyond schema)
  // The strict response typing (typia.assert) covers this automatically, but double check.
}

