/**
 * Validate failure on updating a non-existent order payment record (customer context).
 *
 * Business context:
 * Updating a payment record is allowed only for existing payment entries linked to real orders.
 * This test verifies that attempts to update a payment for a real order using a deliberately invalid/non-existent payment ID cleanly fail, with no side effects or data modification. This checks for client-side bugs, operator errors, or attack attempts against non-existent resources.
 *
 * Steps:
 * 1. Register a new customer (sign up), capturing new JWT for authorization.
 * 2. Create a valid order as the fresh customer (orders table).
 * 3. Attempt to update a payment using a random (non-existent) orderPaymentId, targeting the new orderId.
 * 4. Confirm API responds with a not found/validation error using TestValidator.error.
 * 5. (Omitted) No post-update validation, as reading/listing payments is not supported by current API.
 */
export async function test_api_order_payment_update_customer_not_found(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerPassword = "1234";
  const signUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(signUp);
  // Set Authorization header for the registered customer
  connection.headers = { ...connection.headers, Authorization: signUp.setHeaders.Authorization };

  // 2. Create a new order for the customer
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: signUp.customer.id,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 50000,
      currency_code: "KRW",
      current_status: "created",
    },
  });
  typia.assert(order);

  // 3. Attempt to update a payment with a clearly nonexistent paymentId
  const nonExistentPaymentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Updating non-existent order payment should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.update(connection, {
        orderId: order.id,
        orderPaymentId: nonExistentPaymentId,
        body: { payment_result: "completed", payment_context: null },
      });
    },
  );

  // 4. (Omitted) Post-verification of payment list/state not feasible: no query/read endpoint for orderPayments in current API contract.
}

