 *
 * Test necessity:
 * This test ensures that keyword uniqueness validation is enforced at the API/business level, not just in the client. Prevents business issues due to multiple duplicate keywords, which could break analytics/search.
 *
 * Step-by-step process:
 * 1. Register a new seller account to represent the authenticated acting seller.
 * 2. Create a product under the newly registered seller (must use returned seller_id).
 * 3. Add a search keyword (e.g., a random English or Korean word) for the product as the seller – the first attempt should succeed.
 * 4. Attempt to add the exact same keyword again for the same product as the same seller – the call must fail with a validation/duplicate error. This validates that the uniqueness constraint is enforced.
 */
export async function test_api_product_search_keyword_creation_duplicate_key(connection: api.IConnection) {
  // 1. Register a new seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerCompanyName = RandomGenerator.name() + " Co.";
  const sellerBusinessNumber = "" +
    typia.random<number & tags.Type<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>>()
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "StrongP@ssw0rd123",
      companyName: sellerCompanyName,
      businessNumber: sellerBusinessNumber,
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(1),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUp);
  TestValidator.equals("email")(sellerSignUp.email)(sellerEmail);
  const sellerId = sellerSignUp.sellerId;

  // 2. Create a product under this seller
  const productName = RandomGenerator.paragraph()();
  const productCode = RandomGenerator.alphaNumeric(8);
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: productName,
      status: "draft", // safe initial status
      description: RandomGenerator.content()()(1),
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);
  TestValidator.equals("seller_id")(product.seller_id)(sellerId);
  const productId = product.id;

  // 3. Add a search keyword
  const searchKeyword = RandomGenerator.alphabets(7).toLowerCase();
  const keywordResult1 = await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.createProductSearchKeyword(connection, {
    productId,
    body: {
      product_id: productId,
      search_keyword: searchKeyword,
    } satisfies IShoppingMallAiBackendProductSearchKeyword.ICreate,
  });
  typia.assert(keywordResult1);
  TestValidator.equals("keyword matches")(keywordResult1.search_keyword)(searchKeyword);
  TestValidator.equals("product_id matches")(keywordResult1.product_id)(productId);

  // 4. Add the same keyword again and expect an error
  await TestValidator.error("duplicate keyword must fail")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.createProductSearchKeyword(connection, {
      productId,
      body: {
        product_id: productId,
        search_keyword: searchKeyword,
      } satisfies IShoppingMallAiBackendProductSearchKeyword.ICreate,
    });
  });
}

