import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate seller profile update failure cases with invalid or non-compliant data submission.
 *
 * This test confirms that when a seller attempts to update their profile with invalid data – such as missing required fields, invalid business registration number, or malformed phone – the API responds with validation errors and does not update the seller profile.
 *
 * Steps:
 * 1. Register a new seller with valid data.
 * 2. Authenticate as the newly registered seller.
 * 3. Attempt to update the profile with invalid data:
 *    a. Omit required fields (e.g., missing company name via null).
 *    b. Supply an invalid business registration number (bad format/length).
 *    c. Pass null where not allowed (e.g., representative name).
 *    d. Set an invalid phone format (e.g., random string).
 * 4. Confirm the API responds with an error in each case (TestValidator.error) and (if possible) that seller profile is unchanged.
 *    Note: As there is no profile fetch/read method in the API, post-update state verification cannot be performed.
 */
export async function test_api_seller_update_profile_invalid_data(connection: api.IConnection) {
  // Step 1: Register a new seller with valid data
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "ValidPass123$";
  const registerResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(registerResp);

  // Step 2: Authenticate as the seller
  const loginResp = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(loginResp);
  const sellerId: string = registerResp.sellerId;

  // Step 3a: Omit company_name by setting it null (treated invalid by backend)
  await TestValidator.error("missing company_name (set null)")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.update(connection, {
        body: {
          id: sellerId,
          company_name: null,
        } satisfies IShoppingMallAiBackendSeller.IUpdate,
      });
    }
  );

  // Step 3b: Invalid (non-numeric/short) business registration number
  await TestValidator.error("invalid business number format")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.update(connection, {
        body: {
          id: sellerId,
          business_number: "A12B34C", // Clearly not valid (should be digits)
        } satisfies IShoppingMallAiBackendSeller.IUpdate,
      });
    }
  );

  // Step 3c: Null for representative_name
  await TestValidator.error("null representative name")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.update(connection, {
        body: {
          id: sellerId,
          representative_name: null,
        } satisfies IShoppingMallAiBackendSeller.IUpdate,
      });
    }
  );

  // Step 3d: Phone in invalid format
  await TestValidator.error("invalid phone")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.update(connection, {
        body: {
          id: sellerId,
          phone: "not-a-phone!!!",
        } satisfies IShoppingMallAiBackendSeller.IUpdate,
      });
    }
  );

  // Step 4: Unable to validate data unchanged due to lack of profile-read endpoint.
}

