import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartItem";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate retrieval of full shopping cart item details by customer for their own cart.
 *
 * This test verifies that a customer can successfully sign up, create a shopping cart, add an item to the cart, and retrieve the full details of that cart item. The scenario ensures proper linkage across authentication, cart, and cart item creation, and confirms that the retrieved cart item details correspond accurately to what was created (product, quantity, option, unit price, currency, timestamps, etc).
 *
 * 1. Register a customer and obtain authorization (JWT/headers set by API on registration response).
 * 2. Create a new cart as the now-authenticated customer (should auto-link to customer).
 * 3. Add a cart item by specifying a new product_id (random UUID), with realistic quantity and price/currency in the request body. Optionally, a product_option_id and note can be provided as random or null.
 * 4. Retrieve the cart item by its cartId and cartItemId.
 * 5. Assert that every field (product_id, product_option_id, quantity, unit_price, currency_code, note, and timestamps) matches exactly what was created in step 3. All type and value validations should pass.
 */
export async function test_api_cart_item_retrieve_success_customer(connection: api.IConnection) {
  // Step 1: Customer registration
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const signUpResp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "password123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(signUpResp);
  // Authorization token is automatically set in connection headers

  // Step 2: Create cart
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active"
    } satisfies IShoppingMallAiBackendCart.ICreate
  });
  typia.assert(cart);

  // Step 3: Add cart item
  const cartItemReq: IShoppingMallAiBackendCartItem.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
    product_option_id: Math.random() < 0.5 ? typia.random<string & tags.Format<"uuid">>() : null,
    quantity: 1,
    unit_price: 1234.56,
    currency_code: "KRW",
    note: Math.random() < 0.5 ? RandomGenerator.paragraph()() : null
  };
  const cartItem = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
    cartId: cart.id,
    body: cartItemReq
  });
  typia.assert(cartItem);

  // Step 4: Retrieve cart item detail
  const retrievedItem = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.at(connection, {
    cartId: cart.id,
    cartItemId: cartItem.id
  });
  typia.assert(retrievedItem);

  // Step 5: Assert all details match
  TestValidator.equals("product_id")(retrievedItem.product_id)(cartItemReq.product_id);
  TestValidator.equals("product_option_id")(retrievedItem.product_option_id ?? null)(cartItemReq.product_option_id ?? null);
  TestValidator.equals("quantity")(retrievedItem.quantity)(cartItemReq.quantity);
  TestValidator.equals("unit_price")(retrievedItem.unit_price)(cartItemReq.unit_price);
  TestValidator.equals("currency_code")(retrievedItem.currency_code)(cartItemReq.currency_code);
  TestValidator.equals("note")(retrievedItem.note ?? null)(cartItemReq.note ?? null);
}

