import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteProduct";
import type { IShoppingMallAiBackendFavoriteNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteNotification";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that the owner customer can successfully retrieve the details of a notification related to one of their favorite records.
 *
 * Business context:
 * Notifications tied to favorited products (such as price drop, restock, inquiry reply) are central to timely user engagement in a shopping mall environment. Access to notification details must be tightly scoped to the owner customer for both business value and privacy/security. 
 *
 * Steps:
 * 1. Register (sign up) a new customer – capture customer identity so all following actions are properly scoped.
 * 2. Mark a product as favorite – simulate customer behavior that establishes the precondition for future notifications. Use random product_id for isolation.
 * 3. Manually trigger a favorite notification for that favorite object – create a notification with references to the just-created favorite and set appropriate event type, channel, and read (false).
 * 4. Use the notification's id to retrieve its detail by the owner customer – call the GET endpoint.
 * 5. Validate returned notification fields (references, event type, channel, created_at, read, etc.) and that all sensitive fields are present only for the owner.
 * 6. (Edge) As negative case: (not implementable with available APIs) Attempt to access with another customer should be denied, but can't be covered without a co-authenticated GET – skip this.
 */
export async function test_api_favorite_notification_detail_access_by_owner_customer(
  connection: api.IConnection,
) {
  // 1. Register a new customer (sign up)
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerRegisterOutput = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "TestPassword!1",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerRegisterOutput);
  const customer = customerRegisterOutput.customer;
  // Connection auto-authorized due to registration

  // 2. Mark a product as favorite
  const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate,
  });
  typia.assert(favoriteProduct);

  // 3. Create a notification tied to this favorite
  const notification = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, {
    body: {
      favorite_product_id: favoriteProduct.id,
      notification_type: "RESTOCK",
      notification_channel: "PUSH",
      read: false,
      delivery_metadata: JSON.stringify({ info: "Simulated delivery metadata for test" }),
    } satisfies IShoppingMallAiBackendFavoriteNotification.ICreate,
  });
  typia.assert(notification);

  // 4. Retrieve notification details by owner customer
  const output = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.at(connection, {
    favoriteNotificationId: notification.id as string & tags.Format<"uuid">,
  });
  typia.assert(output);

  // 5. Validate returned fields
  TestValidator.equals("correct notification id")(output.id)(notification.id);
  TestValidator.equals("correct event type")(output.notification_type)(notification.notification_type);
  TestValidator.equals("correct channel")(output.notification_channel)(notification.notification_channel);
  TestValidator.equals("correct read state")(output.read)(false);
  TestValidator.equals("reference to favorite product")(output.favorite_product_id)(favoriteProduct.id);
  if (notification.delivery_metadata)
    TestValidator.equals("delivery_metadata present")(output.delivery_metadata)(notification.delivery_metadata);
  TestValidator.predicate("created_at is ISO8601 and recent")(!!Date.parse(output.created_at));
  // No negative access test (other customer access forbidden) – not implementable here.
}

