import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendFavoriteInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteInquiry";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test retrieval of a favorited product inquiry detail by the owning customer.
 *
 * This test confirms that:
 * 1. A customer can retrieve a favorite inquiry by ID after registering, submitting an inquiry, and favoriting it.
 * 2. The returned data contains all expected favorite inquiry attributes, including favorited timestamp and references.
 * 3. Only the owning customer can access their own favorite inquiries (ownership/authorization is enforced).
 * 4. Behavior for requesting a not-found or deleted favorite inquiry returns appropriate error.
 *
 * Steps:
 * 1. Register a customer (collect JWT Authorization automatically).
 * 2. Create a product inquiry for that customer.
 * 3. Favorite that inquiry (obtain favoriteInquiryId).
 * 4. Retrieve the favorite inquiry by ID as the customer and check return values.
 * 5. Attempt to retrieve a non-existent favoriteInquiryId (should error as not found).
 * 6. Attempt to retrieve a just created favorite after soft deleting it (should error as not found or unauthorized).
 */
export async function test_api_favorite_inquiry_retrieve_success_customer(
  connection: api.IConnection,
) {
  // 1. Register customer
  const signUpBody: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword1234!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const signUpResp = await api.functional.auth.customer.register.signUp(connection, {
    body: signUpBody,
  });
  typia.assert(signUpResp);
  const customer = signUpResp.customer;

  // 2. Create a product inquiry
  const inquiryBody: IShoppingMallAiBackendProductInquiry.ICreate = {
    customer_id: customer.id,
    product_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(1),
    public: true,
  };
  const productInquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: inquiryBody,
  });
  typia.assert(productInquiry);

  // 3. Favorite the inquiry
  const favoriteCreateBody: IShoppingMallAiBackendFavoriteInquiry.ICreate = {
    inquiry_id: productInquiry.id,
  };
  const favoriteInquiry = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.create(connection, {
    body: favoriteCreateBody,
  });
  typia.assert(favoriteInquiry);

  // 4. Retrieve the favorite inquiry (success case)
  const fetchedFavorite = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.at(connection, {
    favoriteInquiryId: favoriteInquiry.id,
  });
  typia.assert(fetchedFavorite);
  TestValidator.equals("ownership")(fetchedFavorite.customer_id)(customer.id);
  TestValidator.equals("favorited inquiry reference")(fetchedFavorite.inquiry_id)(productInquiry.id);
  TestValidator.equals("unfavorited (deleted_at)")(fetchedFavorite.deleted_at)(null);

