    } satisfies IShoppingMallAiBackendCouponUsage.IRequest,
  });
  typia.assert(searchResult);
  if (searchResult.data.length >= 2) {
    TestValidator.predicate("sorted asc")(
      new Date(searchResult.data[0].used_at) <= new Date(searchResult.data[1].used_at)
    );
  }

  // 9. Error handling: Invalid input - page=0 (violates Minimum<1>), negative limit, malformed UUID
  await TestValidator.error("page=0 should error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
