  // 1. Register a new admin
  const signUpOutput = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "test-password-1234",
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(signUpOutput);
  const adminId = signUpOutput.adminId;

  // 2. Create a channel with this admin as creator
  const channel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: RandomGenerator.alphabets(8),
      name: RandomGenerator.name(),
      created_by_admin_id: adminId,
      description: RandomGenerator.paragraph()(),
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channel);

  // 3. Create a section within this channel
  const section = await api.functional.shoppingMallAiBackend.admin.channels.sections.createSection(connection, {
    channelId: channel.id,
    body: {
      code: RandomGenerator.alphabets(6),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
      visible: true,
      channel_id: channel.id,
      created_by_admin_id: adminId,
    } satisfies IShoppingMallAiBackendSection.ICreate,
  });
  typia.assert(section);

