  await api.functional.shoppingMallAiBackend.admin.channels.sections.eraseSection(connection, {
    channelId: channel.id,
    sectionId: section.id,
  });

  // 5. Attempt to fetch the deleted section – expect error
  await TestValidator.error("should error when fetching deleted section")(() =>
    api.functional.shoppingMallAiBackend.admin.channels.sections.at(connection, {
      channelId: channel.id,
      sectionId: section.id,
    }),
  );

  // 6. Attempt to fetch with an invalid random UUID – expect error
