import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * E2E test for verifying update of cart snapshot metadata by customer
 *
 * This test validates that a customer can update only the allowed mutable fields (such as snapshot_reason) of a cart snapshot they own, but cannot change immutable fields such as the raw cart state or timestamps. It also covers error scenarios related to snapshot ownership and existence.
 *
 * Step-by-step process:
 * 1. Register a customer, obtaining session/JWT tokens upon success.
 * 2. Create a cart for this customer session.
 * 3. Produce an initial cart snapshot for this cart with a valid JSON state and snapshot_reason ('checkout').
 * 4. Update the snapshot's snapshot_reason (should succeed) and verify the change is reflected.
 * 5. Try to update immutable fields (e.g. snapshot_json, created_at): these updates must be rejected or ignored; test that validation occurs and fails properly.
 * 6. Attempt to update a snapshot owned by a different customer and one that doesn't exist, verifying correct error responses (e.g. forbidden or not found).
 */
export async function test_api_cart_snapshot_customer_update_metadata(
  connection: api.IConnection,
) {
  // 1. Register customer
  const customerRequest: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "password123",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  };
  const customerResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: customerRequest,
  });
  typia.assert(customerResponse);

  // At this point, connection.headers.Authorization contains JWT for auth

  // 2. Create cart for this customer
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    },
  });
  typia.assert(cart);

  // 3. Create cart snapshot
  const initialSnapshot = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.create(connection, {
    cartId: cart.id,
    body: {
      cart_id: cart.id,
      snapshot_json: JSON.stringify(cart),
      snapshot_reason: "checkout",
    },
  });
  typia.assert(initialSnapshot);

  // 4. Update snapshot_reason (allowed field)
  const updatedReason = "compliance adjustment";
  const updatedSnapshot = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.update(connection, {
    cartId: cart.id,
    cartSnapshotId: initialSnapshot.id,
    body: { snapshot_reason: updatedReason },
  });
  typia.assert(updatedSnapshot);
  TestValidator.equals("snapshot_reason updated")(updatedSnapshot.snapshot_reason)(updatedReason);

  // 5. Attempt to update immutable fields (should be rejected by backend)
  await TestValidator.error("should not allow updating snapshot_json, created_at")(
    async () => {
      // @ts-expect-error: intentionally wrong, but check only runtime
      await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.update(connection, {
        cartId: cart.id,
        cartSnapshotId: initialSnapshot.id,
        body: {
          // snapshot_json is not allowed by DTO, but in test, we check backend validation
          // @ts-expect-error
          snapshot_json: JSON.stringify({ fake: "evidence tampering" }),
          // @ts-expect-error
          created_at: new Date().toISOString(),
        },
      });
    },
  );

  // 6. Register a second customer
  const otherCustomerRequest: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "password321",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  };
  const otherCustomerResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: otherCustomerRequest,
  });
  typia.assert(otherCustomerResponse);

  // Switch connection to second customer (token automatically set)
  // 7. Attempt to update first customer's snapshot (should fail with forbidden)
  await TestValidator.error("should forbid updating snapshot not owned by user")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.update(connection, {
        cartId: cart.id,
        cartSnapshotId: initialSnapshot.id,
        body: { snapshot_reason: "malicious update" },
      });
    },
  );

  // 8. Try to update non-existent snapshot id (should fail with not found)
  await TestValidator.error("should fail on non-existent snapshot ID")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.update(connection, {
        cartId: cart.id,
        cartSnapshotId: typia.random<string & tags.Format<"uuid">>(),
        body: { snapshot_reason: "non-existent update" },
      });
    },
  );
}

