import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate creation of a new coupon snapshot as an admin, including normal and duplicate/conflict scenarios.
 *
 * Business context: Coupon snapshots are used for audit, compliance, and rollback tracking when coupons are issued or events occur. Only admins can create snapshots. Each snapshot must point to a legitimate issued coupon and record the full state at the time of the event.
 *
 * Steps:
 * 1. Admin authentication: Sign in as an admin and apply the JWT to the connection context (ensure Authorization header is set).
 * 2. Prepare valid coupon reference: Issue a valid coupon using admin API (with necessary references to template/customer).
 * 3. Create a valid coupon snapshot: Use correct references from issued coupon, set context fields, expect successful creation. Validate response matches the submitted state and includes system/audit fields like id, created_at, etc.
 * 4. Attempt duplicate/inappropriate snapshot: Try to create a snapshot with the same id or refer to the same event, or reference a non-existent issued coupon id. Ensure system returns validation or conflict error (use TestValidator.error and validate the error is thrown, but do not check error text).
 * 5. Edge case: Omit a required field in the creation payload. Confirm the API rejects the request (again, TestValidator.error, without relying on error wording).
 */
export async function test_api_coupon_snapshot_creation_success_and_duplicate(connection: api.IConnection) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'SecureP@ssw0rd';
  // Assume admin exists, use given credentials
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);
  // Apply JWT if needed (simulated; system automatically updates connection)

  // 2. Issue a coupon (create issued coupon)
  const issuedCoupon = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.create(connection, {
    body: {
      coupon_template_id: typia.random<string & tags.Format<'uuid'>>(),
      customer_id: typia.random<string & tags.Format<'uuid'>>(),
      code: 'ISSUED' + typia.random<string>(),
      expires_at: new Date(Date.now() + 86400 * 1000).toISOString(),
      status: 'issued',
    } satisfies IShoppingMallAiBackendIssuedCoupon.ICreate,
  });
  typia.assert(issuedCoupon);

  // 3. Create valid snapshot
  const snapshotInput = {
    issued_coupon_id: issuedCoupon.id,
    coupon_template_code: 'TEMPLATE-CODE-' + typia.random<string>(),
    issued_coupon_code: issuedCoupon.code,
    customer_id: issuedCoupon.customer_id,
    status: issuedCoupon.status,
    valid_from: issuedCoupon.issued_at,
    valid_until: issuedCoupon.expires_at,
    action: 'issued',
  } satisfies IShoppingMallAiBackendCouponSnapshot.ICreate;

  const snapshot = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, { body: snapshotInput });
  typia.assert(snapshot);
  TestValidator.equals('issued_coupon_id matches')(snapshot.issued_coupon_id)(snapshotInput.issued_coupon_id);
  TestValidator.equals('coupon_template_code')(snapshot.coupon_template_code)(snapshotInput.coupon_template_code);
  TestValidator.equals('issued_coupon_code')(snapshot.issued_coupon_code)(snapshotInput.issued_coupon_code);
  TestValidator.equals('customer_id')(snapshot.customer_id)(snapshotInput.customer_id);
  TestValidator.equals('status')(snapshot.status)(snapshotInput.status);
  TestValidator.equals('valid_from')(snapshot.valid_from)(snapshotInput.valid_from);
  TestValidator.equals('valid_until')(snapshot.valid_until)(snapshotInput.valid_until);
  TestValidator.equals('action')(snapshot.action)(snapshotInput.action);

  // 4. Attempt duplicate snapshot (reference same issued_coupon_id, code, and event)
  await TestValidator.error('duplicate coupon snapshot should fail')(() =>
    api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, {
      body: snapshotInput
    })
  );

