import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate creation of a new coupon snapshot as an admin—success, duplicate, and input error cases.
 *
 * Business context:
 * Coupon snapshots serve auditing, rollback, and compliance tracking in the system. Only admins can create snapshots, which must reference real, issued coupons and reflect coupon state history at the time of key events.
 *
 * Steps:
 * 1. Admin login—obtain JWT to enable admin-only coupon snapshot actions.
 * 2. Issue a coupon (creates valid reference data).
 * 3. Create a valid coupon snapshot (expect success).
 * 4. Attempt to create a duplicate snapshot (expect validation/conflict error).
 * 5. Attempt to create a snapshot for a fake/non-existent issued coupon (expect error).
 * 6. Edge: Omit a required field in snapshot input (expect input validation error).
 */
export async function test_api_coupon_snapshot_creation_success_and_duplicate(
  connection: api.IConnection,
) {
  // 1. Admin login (credentials assumed to exist in test env)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestSecure!P@ss1";
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);
  // JWT/Authorization is managed in the connection by SDK

  // 2. Issue a new coupon (get a valid coupon to snapshot)
  const issuedCoupon = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.create(connection, {
    body: {
      coupon_template_id: typia.random<string & tags.Format<"uuid">>(),
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      code: "CPN-" + typia.random<string>(),
      expires_at: new Date(Date.now() + 7 * 86400 * 1000).toISOString(),
      status: "issued",
    } satisfies IShoppingMallAiBackendIssuedCoupon.ICreate,
  });
  typia.assert(issuedCoupon);

  // 3. Create a valid coupon snapshot
  const snapshotInput = {
    issued_coupon_id: issuedCoupon.id,
    coupon_template_code: "TEMPLATE-" + typia.random<string>(),
    issued_coupon_code: issuedCoupon.code,
    customer_id: issuedCoupon.customer_id,
    status: issuedCoupon.status,
    valid_from: issuedCoupon.issued_at,
    valid_until: issuedCoupon.expires_at,
    action: "issued",
  } satisfies IShoppingMallAiBackendCouponSnapshot.ICreate;

  const createdSnapshot = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, {
    body: snapshotInput,
  });
  typia.assert(createdSnapshot);
  TestValidator.equals("issued_coupon_id matches")(createdSnapshot.issued_coupon_id)(snapshotInput.issued_coupon_id);
  TestValidator.equals("coupon_template_code")(createdSnapshot.coupon_template_code)(snapshotInput.coupon_template_code);
  TestValidator.equals("issued_coupon_code")(createdSnapshot.issued_coupon_code)(snapshotInput.issued_coupon_code);
  TestValidator.equals("customer_id")(createdSnapshot.customer_id)(snapshotInput.customer_id);
  TestValidator.equals("status")(createdSnapshot.status)(snapshotInput.status);
  TestValidator.equals("valid_from")(createdSnapshot.valid_from)(snapshotInput.valid_from);
  TestValidator.equals("valid_until")(createdSnapshot.valid_until)(snapshotInput.valid_until);
  TestValidator.equals("action")(createdSnapshot.action)(snapshotInput.action);

  // 4. Duplicate snapshot (same reference data)
  await TestValidator.error("duplicate coupon snapshot should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, {
      body: snapshotInput,
    }),
