  // 5. Non-existent issued_coupon_id
  const fakeSnapshotInput = {
    ...snapshotInput,
    issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
  };
  await TestValidator.error("non-existent issued_coupon_id should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, {
      body: fakeSnapshotInput,
    }),
  );

  // 6. Omit required field—remove status
  const { status: _omit, ...missingFieldInput } = snapshotInput;
  // @ts-expect-error: intentionally missing 'status', should cause runtime validation error
  await TestValidator.error("missing required field should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, {
      body: missingFieldInput,
    }),
