import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test soft-deletion (logical delete) of a favorite snapshot as the customer owner.
 *
 * This test verifies that an authenticated customer can logically delete (soft delete) a snapshot of their favorited product, and checks that:
 *   1. The snapshot is marked as deleted (deleted_at is set after deletion).
 *   2. The snapshot is no longer returned from any query for active/undeleted records.
 *   3. It is still present in historical/audit queries.
 *   4. Permission: Only the owning customer (or an admin, not covered in this single test) can perform the delete.
 *   5. Audit/logging occurs for the deletion operation.
 *
 * Steps:
 * 1. Register a new customer (as an end-user).
 * 2. Customer favorites a (random) product (simulate a product by random UUID).
 * 3. Customer creates a snapshot of that favorited product.
 * 4. Customer calls DELETE for that snapshot (soft delete).
 * 5. Re-attempt to access the deleted snapshot (should still exist for audit, but marked deleted).
 * 6. Query for active snapshots (if query is available, not covered here as no listing API).
 * 7. Attempt delete as anonymous/other user (not covered here as no other user or admin API available).
 * 8. Assert: deleted_at is set, snapshot is still present, owner permission enforced (by success), and data contracts are maintained.
 */
export async function test_api_favorite_snapshot_soft_delete_by_owner(connection: api.IConnection) {
  // 1. Register new customer
  const signUpReq = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "test-password-1A$",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
