  const customer = signUpResp.customer;
  // Set JWT header for further calls
  connection.headers = { ...connection.headers, Authorization: signUpResp.setHeaders.Authorization };

  // 2. Customer favorites a product
  const productId = typia.random<string & tags.Format<"uuid">>();
  const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: { product_id: productId } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate,
  });
  typia.assert(favoriteProduct);
  TestValidator.equals("favorite owner matches")(favoriteProduct.customer_id)(customer.id);
  TestValidator.equals("product matches")(favoriteProduct.product_id)(productId);
  TestValidator.equals("favorite not deleted")(favoriteProduct.deleted_at)(null);

  // 3. Customer creates a favorite snapshot
  const serializedObject = JSON.stringify({ product_id: productId, favorited_at: favoriteProduct.created_at });
  const snapshotReq = {
    favorite_product_id: favoriteProduct.id,
    favorite_inquiry_id: null,
    favorite_address_id: null,
    target_type: "PRODUCT",
    snapshot_object_id: productId,
    serialized_object: serializedObject,
  } satisfies IShoppingMallAiBackendFavoriteSnapshot.ICreate;
  const favoriteSnapshot = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: snapshotReq,
  });
