 *
 * This test ensures that an admin can create a new product option stock under a valid,
 * existing product option, and that all required fields and reference integrity are enforced.
 * Business constraints such as uniqueness of stock per product option and proper error handling
 * for missing or deleted references are validated.
 *
 * Step-by-step process:
 * 1. Admin creates a product (prerequisite for product option)
 * 2. Admin creates a product option for that product
 * 3. Admin creates a stock for the product option (main positive case)
 * 4. Assert all required fields are in response and reference linkage is correct
 * 5. Attempt to create a stock using a non-existent product option ID and verify error is thrown
 * 6. (if possible) Attempt to create a stock using a deleted product option and verify error is thrown
 * 7. Attempt to create another stock for the same product option with the same field values and verify business uniqueness constraint is enforced
 */
export async function test_api_admin_create_product_option_stock_and_reference_validation(connection: api.IConnection) {
