  TestValidator.equals("fk linkage, product_option_id matches")(stock.product_option_id)(productOption.id);
  TestValidator.equals("stock_count matches")(stock.stock_count)(stockInput.stock_count);
  TestValidator.equals("warehouse_location matches")(stock.warehouse_location)(stockInput.warehouse_location);

