  const fakeOptionId = typia.random<string & tags.Format<"uuid">>();
  const stockInputFake = {...stockInput, product_option_id: fakeOptionId };
  await TestValidator.error("creating stock with non-existent option should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.productOptions.productOptionStocks.create(connection, {
        productOptionId: fakeOptionId,
        body: stockInputFake,
      });
    }
  );

  // 5. Error: attempt to create duplicate stock for the same product option (should be rejected by business constraint if not allowed)
  await TestValidator.error("creating duplicate stock for the same product option should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.productOptions.productOptionStocks.create(connection, {
        productOptionId: productOption.id,
        body: stockInput,
      });
    }
  );
}

