  // 1. Register a new seller
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword1!",
      companyName: RandomGenerator.name(),
      businessNumber: "100-12-" + typia.random<string>().slice(0,3),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(sellerSignUp);

  // 2. Seller creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerSignUp.sellerId,
      code: "SKU-" + RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "draft",
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 3. Seller creates a product snapshot
  const productSnapshot = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      snapshot_code: RandomGenerator.alphaNumeric(10),
      snapshot_type: "created",
      name: product.name,
      description: product.description ?? null,
      main_image_uri: product.main_image_uri ?? null,
      status: product.status,
    } satisfies IShoppingMallAiBackendProductSnapshot.ICreate
  });
  typia.assert(productSnapshot);

  // 4. As admin, delete the product snapshot
  await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.erase(connection, {
    productId: product.id,
    productSnapshotId: productSnapshot.id
  });

  // 5. As admin, attempt to delete the already deleted snapshot again
  await TestValidator.error("Deleting an already deleted snapshot should error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.erase(connection, {
        productId: product.id,
        productSnapshotId: productSnapshot.id
      });
    }
  );
}

