export async function test_api_product_search_keyword_search_by_seller(connection: api.IConnection) {
  // 1. Seller registration
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const signUpResult = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: "1112233333",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.name() + " Street",
      phone: "0212345678",
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResult);
  TestValidator.equals("email")(signUpResult.email)(sellerEmail);
  const sellerId = signUpResult.sellerId;

  // 2. Seller creates a product
  const productName = RandomGenerator.paragraph()(3);
  const productCode = RandomGenerator.alphaNumeric(10);
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: productName,
      status: "published",
      description: RandomGenerator.content()(2)(2),
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);
  TestValidator.equals("product seller_id")(product.seller_id)(sellerId);
  TestValidator.equals("product code")(product.code)(productCode);

  // 3. Assign multiple search keywords
  const keywords = [
    "alpha-keyword-1",
    "beta-keyword-2",
    "gamMa-special-3",
    "delta_findme_4",
    "epsilon-zeta-5"
  ];
  const keywordRecords = [];
  for (const kw of keywords) {
    const record = await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.createProductSearchKeyword(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        search_keyword: kw,
      } satisfies IShoppingMallAiBackendProductSearchKeyword.ICreate,
    });
    typia.assert(record);
    TestValidator.equals("assigned kw product_id")(record.product_id)(product.id);
    TestValidator.equals("assigned search_keyword")(record.search_keyword)(kw);
    keywordRecords.push(record);
  }

  // 4. Retrieve ALL search keywords for the product (no filters)
  const searchAll = await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.searchProductSearchKeywords(connection, {
    productId: product.id,
    body: { product_id: product.id } satisfies IShoppingMallAiBackendProductSearchKeyword.IRequest,
  });
  typia.assert(searchAll);
  const returnedKeywords = searchAll.data.map(d => d.search_keyword);
  for (const kw of keywords) {
    TestValidator.predicate(`keyword '${kw}' found in unfiltered result`)(returnedKeywords.includes(kw));
  }
  TestValidator.equals("all-records count")(returnedKeywords.length)(keywords.length);

  // 5a. Pagination test: get page 1 of size 2
  const pageSize = 2;
  const page1 = await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.searchProductSearchKeywords(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      page: 1,
      limit: pageSize,
      sort: "search_keyword",
      direction: "asc",
    } satisfies IShoppingMallAiBackendProductSearchKeyword.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("pagination page size")(page1.data.length)(pageSize);
  TestValidator.equals("pagination current")(page1.pagination.current)(1);
  TestValidator.equals("pagination limit")(page1.pagination.limit)(pageSize);
  TestValidator.predicate("pagination result subset")(page1.data.every(x => returnedKeywords.includes(x.search_keyword)));

  // 5b. Filtering test: filter search_keyword contains 'findme'
  const filterKw = "findme";
  const filterRes = await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.searchProductSearchKeywords(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      search_keyword: filterKw,
    } satisfies IShoppingMallAiBackendProductSearchKeyword.IRequest,
  });
  typia.assert(filterRes);
  TestValidator.predicate("filtered results only match substring")(filterRes.data.every(k => k.search_keyword.includes(filterKw)));
  TestValidator.equals("filtered count matches actual")(filterRes.data.length)(keywords.filter(k => k.includes(filterKw)).length);
}

