  typia.assert(wallet);

  // 3. Create valid mileage transaction as the customer
  const txnCreate: IShoppingMallAiBackendMileageTransaction.ICreate = {
    wallet_id: wallet.id,
    transaction_type: "accumulate",
    mileage_amount: 100,
