import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrderGroup } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderGroup";
import type { IPageIShoppingMallAiBackendOrderGroup } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderGroup";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates seller-specific searching and paging of order groups.
 *
 * This test covers the end-to-end workflow for a seller retrieving paginated and filtered order groups they belong to. The seller is registered, assigned to several order groups by an admin, and then performs order group searches with filter and pagination parameters. The test ensures only correctly assigned groups are returned per filter, and unrelated groups are NOT returned.
 *
 * Steps:
 * 1. Register a new seller account and authenticate.
 * 2. As an admin, create multiple order groups that are considered 'assigned' to the seller (using unique group names and references).
 * 3. (Optionally) Create a group NOT assigned to this seller to check exclusion.
 * 4. As the seller, search for order groups using no filters – should receive all assigned groups paged.
 * 5. Search with filters (by group_name, by external_reference, by created_at range, with sorting and pagination).
 * 6. At each search, validate that only groups assigned to this seller are included, and unassigned groups are excluded.
 * 7. Verify pagination works (page, pageSize, limit matches count, etc). */
export async function test_api_seller_search_order_groups_success(connection: api.IConnection) {
  // 1. Seller registration
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "TestPassword123!",
      companyName: "TEST_CO_"+RandomGenerator.alphaNumeric(6),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    }
  });
  typia.assert(signUpResp);
  // Seller's JWT and profile
  const sellerJwt = signUpResp.jwt;
  const sellerId = signUpResp.sellerId;

  // Patch connection for seller auth
  const sellerConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: `Bearer ${sellerJwt}`,
    }
  };

  // 2. Admin creates/assigns multiple order groups for this seller
  // (In real life, assignment might require mapping, but here creation suffices for test)
  const orderGroups = [];
  for (let i = 0; i < 3; ++i) {
    const group = await api.functional.shoppingMallAiBackend.admin.orderGroups.create(connection, {
      body: {
        group_name: `seller-group-${i}-${RandomGenerator.alphaNumeric(5)}`,
        external_reference: `ref-${i}-${RandomGenerator.alphaNumeric(6)}`,
        meta_info: null,
      }
    });
    typia.assert(group);
    orderGroups.push(group);
  }
  // A group not linked to this seller: to ensure exclusion logic
  const unrelatedGroup = await api.functional.shoppingMallAiBackend.admin.orderGroups.create(connection, {
    body: {
      group_name: "unrelated-group-"+RandomGenerator.alphaNumeric(5),
      external_reference: "not-linked-ref-"+RandomGenerator.alphaNumeric(5),
      meta_info: null
    }
  });
  typia.assert(unrelatedGroup);

  // 4. As seller, search order groups no filters (should only see relevant groups, not unrelated)
  const allGroupsResult = await api.functional.shoppingMallAiBackend.seller.orderGroups.index(sellerConnection, {
    body: { }
  });
  typia.assert(allGroupsResult);
  // Confirm unrelated group is not seen
  TestValidator.predicate("does not include unrelated group")(allGroupsResult.data.every(g => g.id !== unrelatedGroup.id));

  // 5. Search with filters (group_name, external_reference, created_at -- partial match, date range, pagination)
  // 5a. group_name
  const nameFiltered = await api.functional.shoppingMallAiBackend.seller.orderGroups.index(sellerConnection, {
    body: {
      group_name: orderGroups[0].group_name
    }
  });
  typia.assert(nameFiltered);
  TestValidator.predicate("filtered by group name, only assigned group is returned")(
    nameFiltered.data.length === 1 && nameFiltered.data[0].id === orderGroups[0].id
  );

  // 5b. external_reference
  const refFiltered = await api.functional.shoppingMallAiBackend.seller.orderGroups.index(sellerConnection, {
    body: {
      external_reference: orderGroups[1].external_reference ?? undefined
    }
  });
  typia.assert(refFiltered);
  TestValidator.predicate("filtered by reference, only assigned group is returned")(
    refFiltered.data.length === 1 && refFiltered.data[0].id === orderGroups[1].id
  );

  // 5c. created_at date range (covers all created groups)
  const fromDate = orderGroups[0].created_at;
  const toDate = orderGroups[2].created_at;
  const dateFiltered = await api.functional.shoppingMallAiBackend.seller.orderGroups.index(sellerConnection, {
    body: {
      created_at_gte: fromDate,
      created_at_lte: toDate,
    }
  });
  typia.assert(dateFiltered);
  // Should contain all assigned groups only
  const assignedIds = orderGroups.map(g => g.id);
  TestValidator.predicate("date filter only includes assigned groups")(
    dateFiltered.data.every(g => assignedIds.includes(g.id)) && dateFiltered.data.every(g => g.id !== unrelatedGroup.id)
  );

  // 5d. Pagination test: limit results per page
  const paged = await api.functional.shoppingMallAiBackend.seller.orderGroups.index(sellerConnection, {
    body: {
      page: 1,
      pageSize: 2,
      sort: "-created_at"
    }
  });
  typia.assert(paged);
  TestValidator.equals("per-page limit matches")(
    paged.data.length
  )(2);
  TestValidator.equals("page tracking")(
    paged.pagination.current
  )(1);
  TestValidator.equals("global total count matches assigned")(
    paged.pagination.records
  )(assignedIds.length);
}

