import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates that an admin can update mutable fields (such as transaction_reason) of a mileage transaction,
 * but is prevented from changing immutable/financial fields (like mileage_amount or transaction_type). The test also ensures
 * the transaction is correctly updated in the system. Audit log validation is outside the allowed API surface.
 *
 * Business context:
 * Mileage transactions record loyalty operations (accrual, redemption, adjustment) tied to a wallet. Update is allowed for certain non-financial metadata fields,
 * but core finance details (amount/type) are locked for integrity. Only admins may update.
 *
 * Step-by-step flow:
 * 1. Register a new admin and authenticate to get JWT/session
 * 2. Create a mileage wallet for a random customer (simulate with random UUID)
 * 3. Create a new mileage transaction on that wallet as admin
 * 4. Attempt to update allowed field (transaction_reason) -> expect a successful update
 * 5. Validate the field was updated, and immutable fields remain unchanged
 * 6. (Error test omitted – as only legal fields are allowed by DTO structure, type safety blocks amount/type mutation)
 */
export async function test_api_mileage_transaction_update_success_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin (simulate with random credentials)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAuth);

  // (JWT is set in connection via setHeaders)

  // 2. Create a mileage wallet for testing (simulate random customer)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const walletProgram = "test_program_" + typia.random<string>();
  const walletStatus = "active";
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(
    connection,
    {
      body: {
        customer_id: customerId,
        wallet_program: walletProgram,
        wallet_status: walletStatus,
        wallet_label: "Test Wallet",
        security_code: null,
      } satisfies IShoppingMallAiBackendMileageWallet.ICreate,
    },
  );
  typia.assert(wallet);

  // 3. Create a mileage transaction
  const transactionType = "accumulate";
  const mileageAmount = 100;
  const transactionReason = "Initial grant";
  const referenceId = typia.random<string & tags.Format<"uuid">>();
  const transaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(
    connection,
    {
      mileageWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        transaction_type: transactionType,
        mileage_amount: mileageAmount,
        reference_id: referenceId,
        transaction_reason: transactionReason,
      } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
    },
  );
  typia.assert(transaction);

  // 4. Update transaction_reason (the only mutable field)
  const newReason = "Admin post-correction note";
  const updatedTransaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.update(
    connection,
    {
      mileageWalletId: wallet.id,
      mileageTransactionId: transaction.id,
      body: {
        id: transaction.id,
        transaction_reason: newReason,
      } satisfies IShoppingMallAiBackendMileageTransaction.IUpdate,
    },
  );
  typia.assert(updatedTransaction);

  // 5. Validate only the mutable field was changed.
  TestValidator.equals("transaction_reason updated")(
    updatedTransaction.transaction_reason,
  )(newReason);
  TestValidator.equals("amount remains the same")(
    updatedTransaction.mileage_amount,
  )(mileageAmount);
  TestValidator.equals("type remains the same")(
    updatedTransaction.transaction_type,
  )(transactionType);
  TestValidator.equals("reference remains the same")(
    updatedTransaction.reference_id,
  )(referenceId);
}

