import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test duplicate favorite notification event creation handling for a favorite product by a customer.
 *
 * This test verifies that the system does not allow duplicate notification creation (for the same favorite object/event/channel tuple) or, if allowed, deduplicates them according to business rules. It covers both idempotency and proper error reporting in the event of duplicates.
 *
 * Steps:
 * 1. Register a new customer and prepare a valid session.
 * 2. The authenticated customer marks a random product as favorite.
 * 3. Trigger a favorite notification event (e.g., "PRICE_DROP") for that favorited product.
 * 4. Immediately attempt to create the same notification event again with the exact same parameters for the same product favorite (matching product/event/channel).
 * 5. Validate one of the following, per business rule:
 *    - The API returns the existing notification (idempotency/deduplication), OR
 *    - The API returns a duplicate error (with appropriate status semantics).
 *
 * Edge Cases:
 * - Changes in minor properties (read = true vs. false, delivery_metadata) are ignored for duplicate determination.
 * - If duplicate detection is by (product,event_type,channel), ensure that even attempting to create unread/read versions is still detected as duplicate if all else matches.
 */
export async function test_api_favorite_notification_duplicate_event_handling(
  connection: api.IConnection,
) {
  // 1. Register a customer (dependency)
  const signUpInput: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const signUpResult = await api.functional.auth.customer.register.signUp(connection, { body: signUpInput });
  typia.assert(signUpResult);
  TestValidator.equals("customer email matches")(signUpResult.customer.email)(signUpInput.email);

  // 2. Customer favorites a product
  const favoriteProductInput: IShoppingMallAiBackendFavoriteProduct.ICreate = {
    product_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, { body: favoriteProductInput });
  typia.assert(favoriteProduct);
  TestValidator.equals("favorite product id matches")(favoriteProduct.product_id)(favoriteProductInput.product_id);

  // 3. Create a favorite notification event (PRICE_DROP)
  const notificationInput: IShoppingMallAiBackendFavoriteNotification.ICreate = {
    favorite_product_id: favoriteProduct.id,
    notification_type: "PRICE_DROP",
    notification_channel: "PUSH",
    read: false,
  };
  const notification1 = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, { body: notificationInput });
  typia.assert(notification1);
  TestValidator.equals("favorite product id in notification")(notification1.favorite_product_id)(favoriteProduct.id);
  TestValidator.equals("notification type matches")(notification1.notification_type)(notificationInput.notification_type);
  TestValidator.equals("notification channel matches")(notification1.notification_channel)(notificationInput.notification_channel);

  // 4. Attempt to create a duplicate notification (same favorite, type, channel)
  await TestValidator.error("duplicate notification creation should be blocked or deduplicated")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, { body: notificationInput });
    }
  );
}

