    body: {
      email: customerAEmail,
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    }
  });
  typia.assert(customerARegister);
  const customerAId = customerARegister.customer.id;

  // 2. Register Customer B (unauthorized user)
  const customerBEmail = typia.random<string & tags.Format<"email">>();
  const customerBRegister = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerBEmail,
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    }
  });
  typia.assert(customerBRegister);

  // 3. (Still as Customer B) Save their token for later, then switch back to Customer A session
  const customerBToken = customerBRegister.setHeaders.Authorization;
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerAEmail,
      password: "TestPassword123!",
      name: customerARegister.customer.name,
      nickname: customerARegister.customer.nickname,
      phone: customerARegister.customer.phone
    }
  }).catch(() => null); // Re-register to refresh token if needed (simulate login)
  connection.headers.Authorization = customerARegister.setHeaders.Authorization;

  // 4. Customer A creates a review
  const reviewCreation = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      order_item_id: typia.random<string & tags.Format<"uuid">>(),
