 * 1. Create a business channel (A) as a prerequisite.
 * 2. Create a category (X) as a prerequisite.
 * 3. Create the initial mapping from A↔X.
 * 4. Create another channel (B) and category (Y) for update and duplicate conflict scenarios.
 * 5. Update the mapping by changing category/X→Y (still channel A): should succeed, verify that result reflects new category Y and audit fields are updated.
 * 6. Create a new mapping for (B↔Y).
 * 7. Attempt to update existing mapping to (B↔Y), which should cause duplicate error; validate error handling.
 * 8. Attempt to update with non-existent mapping id (random UUID), expect error and validate.
 *
 * Every change must be validated and typia.asserted, and audit fields (updated_at) should advance. All non-successful cases must be tested via TestValidator.error.
 */
export async function test_api_channel_category_map_update_success_and_invalid(connection: api.IConnection) {
  // 1. Create channel A
  const adminId: string = typia.random<string & tags.Format<"uuid">>();
  const channelA = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: `chnl-a-${RandomGenerator.alphaNumeric(10)}`,
      name: `ChannelA-${RandomGenerator.alphabets(5)}`,
      created_by_admin_id: adminId,
      description: RandomGenerator.paragraph()(),
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channelA);

  // 2. Create category X
  const categoryX = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: null,
      created_by_admin_id: adminId,
      code: `cat-x-${RandomGenerator.alphaNumeric(8)}`,
      name: `CatX-${RandomGenerator.alphabets(4)}`,
      description: RandomGenerator.paragraph()(),
      display_order: 1,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(categoryX);

  // 3. Create initial mapping A↔X
  const mappingAX = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.createChannelCategoryMap(connection, {
    body: {
      channel_id: channelA.id,
      category_id: categoryX.id,
    } satisfies IShoppingMallAiBackendChannelCategoryMap.ICreate,
  });
  typia.assert(mappingAX);

  // 4. Create channel B and category Y
  const channelB = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: `chnl-b-${RandomGenerator.alphaNumeric(10)}`,
      name: `ChannelB-${RandomGenerator.alphabets(5)}`,
      created_by_admin_id: adminId,
      description: RandomGenerator.paragraph()(),
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channelB);

  const categoryY = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: null,
      created_by_admin_id: adminId,
      code: `cat-y-${RandomGenerator.alphaNumeric(8)}`,
      name: `CatY-${RandomGenerator.alphabets(4)}`,
      description: RandomGenerator.paragraph()(),
      display_order: 2,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(categoryY);

