/**
 * Validate that a seller can retrieve all details for a specific product option they own via GET /shoppingMallAiBackend/seller/products/{productId}/productOptions/{productOptionId}.
 *
 * Business purpose:
 *  - Ensures sellers can access product option details for management and auditing.
 *  - Confirms owner-only access and correct field-level integrity.
 *
 * Steps:
 * 1. Register a new seller with unique business credentials.
 * 2. Authenticate the seller to receive valid session/JWT for protected API access.
 * 3. As seller, create a product using API, saving its product id for parent linkage.
 * 4. As seller, create a new product option for the above product via products/{productId}/productOptions, saving option id for retrieval.
 * 5. Retrieve option details using /shoppingMallAiBackend/seller/products/{productId}/productOptions/{productOptionId}.
 * 6. Verify that every field matches the data in DB (should be identical to the create result), covering referential and field-level integrity.
 * 7. Optionally, try accessing with a non-owner (should fail - omitted here, implement only as feasible). 
 */
export async function test_api_seller_get_own_product_option_success(connection: api.IConnection) {
  // 1. Register a new seller
  const signUpInput: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password123!",
    companyName: RandomGenerator.name(),
    businessNumber: (1000000000 + Math.floor(Math.random() * 9000000000)).toString(),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  };
  const registerResult = await api.functional.auth.seller.register.signUp(connection, { body: signUpInput });
  typia.assert(registerResult);
  const sellerId = registerResult.sellerId;
  // 2. Authenticate as this seller
  const loginResult = await api.functional.auth.seller.login.signIn(connection, { body: { email: signUpInput.email, password: signUpInput.password } });
  typia.assert(loginResult);
  // 3. Create a product as seller
  const createProductInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: sellerId,
    code: "SKU-" + Math.floor(Math.random() * 1000000),
    name: RandomGenerator.name(),
    description: RandomGenerator.content()()(),
    status: "published",
    main_image_uri: null,
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: createProductInput });
  typia.assert(product);
  // 4. Create a product option under this product
  const createOptionInput: IShoppingMallAiBackendProductOption.ICreate = {
    product_id: product.id,
    sku: "OPT-" + Math.floor(Math.random() * 1000000),
    option_name: "Color",
    option_values: "Red,Blue,Green",
    extra_price: 1500.50,
    status: "active",
    main_image_uri: null,
  };
  const option = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, { productId: product.id, body: createOptionInput });
  typia.assert(option);
  // 5. Retrieve the option by ID
  const fetched = await api.functional.shoppingMallAiBackend.seller.products.productOptions.at(connection, { productId: product.id, productOptionId: option.id });
  typia.assert(fetched);
  // 6. Deep compare database state and input entity
  TestValidator.equals("product option id matches")(fetched.id)(option.id);
  TestValidator.equals("parent product id matches")(fetched.product_id)(product.id);
  TestValidator.equals("sku matches")(fetched.sku)(createOptionInput.sku);
  TestValidator.equals("option name matches")(fetched.option_name)(createOptionInput.option_name);
  TestValidator.equals("option values matches")(fetched.option_values)(createOptionInput.option_values);
  TestValidator.equals("extra price matches")(fetched.extra_price)(createOptionInput.extra_price);
  TestValidator.equals("main image uri matches")(fetched.main_image_uri)(createOptionInput.main_image_uri);
  TestValidator.equals("status matches")(fetched.status)(createOptionInput.status);
  // Timestamps created_at and updated_at must be valid date-times
  TestValidator.predicate("created_at valid datetime")(!!Date.parse(fetched.created_at));
  TestValidator.predicate("updated_at valid datetime")(!!Date.parse(fetched.updated_at));
  // deleted_at is null at create
  TestValidator.equals("deleted_at is null at create")(fetched.deleted_at)(null);
}

