    body: {
      email: customerAEmail,
      password: "Password123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerARes);
  const customerA = customerARes.customer;

  // 2. Register customerB
  const customerBEmail = typia.random<string & tags.Format<"email">>();
  const customerBRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerBEmail,
      password: "Password123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerBRes);
  const customerB = customerBRes.customer;

