 *   1. Register a new customer (sign-up)
 *   2. Customer creates an order
 *   3. Customer creates a payment for the order
 *   4. Customer updates mutable fields (e.g., payment_result/status, payment_context)
 *   5. Validate that fields are updated; audit fields (updated_at) are changed
 *   6. Validate that immutable fields (e.g., amount, provider_id, transaction_id) remain unchanged
 */
export async function test_api_order_payment_update_customer_success(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "Test1234!";
  const registerResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(registerResponse);
  TestValidator.equals("registered email")(registerResponse.customer.email)(email);
  // Keep customerId for later
  const customerId = registerResponse.customer.id;

  // 2. Create an order for the customer
  const orderNumber = `ORD-${Date.now()}-${RandomGenerator.alphaNumeric(4)}`;
  const orderResponse = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
      order_number: orderNumber,
      total_amount: 10000.0,
      currency_code: "KRW",
      current_status: "created",
    },
  });
  typia.assert(orderResponse);
  TestValidator.equals("order customer ID")(orderResponse.customer_id)(customerId);
  const orderId = orderResponse.id;

  // 3. Create a payment for the order
  const paymentProviderId = typia.random<string & tags.Format<"uuid">>();
  const transactionId = `TXN-${Date.now()}-${RandomGenerator.alphaNumeric(6)}`;
  const paymentResponse = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId,
    body: {
      order_id: orderId,
      payment_provider_id: paymentProviderId,
      payment_method: "card",
      transaction_id: transactionId,
      amount: 10000.0,
      currency_code: "KRW",
      payment_result: "pending",
      payment_context: JSON.stringify({ comment: "initial payment" }),
    },
  });
  typia.assert(paymentResponse);
  const orderPaymentId = paymentResponse.id;

  // 4. Update mutable payment fields
  await new Promise((resolve) => setTimeout(resolve, 1000)); // ensure updated_at will actually change
  const updateBody = {
    payment_result: "completed",
    payment_context: JSON.stringify({ comment: "updated after success from gateway" }),
  } satisfies IShoppingMallAiBackendOrderPayment.IUpdate;
  const updatedPayment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.update(connection, {
    orderId,
    orderPaymentId,
    body: updateBody,
  });
  typia.assert(updatedPayment);

  // 5. Validate updated fields
  TestValidator.equals("payment result updated")(updatedPayment.payment_result)("completed");
  TestValidator.equals("payment context updated")(updatedPayment.payment_context)(updateBody.payment_context);
  TestValidator.predicate("updated_at has changed")(updatedPayment.updated_at !== paymentResponse.updated_at);

  // 6. Immutable fields must not have changed
  TestValidator.equals("amount unchanged")(updatedPayment.amount)(paymentResponse.amount);
  TestValidator.equals("currency unchanged")(updatedPayment.currency_code)(paymentResponse.currency_code);
  TestValidator.equals("order_id unchanged")(updatedPayment.order_id)(paymentResponse.order_id);
  TestValidator.equals("payment_provider_id unchanged")(updatedPayment.payment_provider_id)(paymentResponse.payment_provider_id);
  TestValidator.equals("payment_method unchanged")(updatedPayment.payment_method)(paymentResponse.payment_method);
  TestValidator.equals("transaction_id unchanged")(updatedPayment.transaction_id)(paymentResponse.transaction_id);
}

