/**
 * Validate admin retrieval of paginated and filtered customer audit/history events.
 *
 * This test ensures that after registering both an admin and a customer (and by consequence, generating some history events), the admin can:
 * 1. Query all audit/history events for the target customer via the admin endpoint (search).
 * 2. Use filtering by event_type (e.g., 'created') and a time window (occurred_from/to) and confirm that results:
 *    - Only show events for the correct customer
 *    - Include correct event type (if filtered)
 *    - Occurred within the specified time window (if filtered)
 *    - Include all required audit metadata fields (id, occurred_at, triggered_by, etc)
 *    - Pagination metadata (page, limit, etc.) matches the request
 * 3. Attempt to access the endpoint as a non-admin (customer) and confirm access is denied (error thrown)
 *
 * Steps:
 * 1. Register an admin (capture Authorization header so all following requests are as ADMIN).
 * 2. Register a customer (capture the customer ID and know that 'created' event(s) are generated).
 * 3. As ADMIN, fetch history events for the customer, paginated (e.g., limit=5 on page 1).
 * 4. Validate all events belong to the customer and pagination is correct.
 * 5. Filter for event_type='created'. Validate only 'created' events are returned.
 * 6. Optionally (if feasible), filter by a short time range that should include only registration.
 * 7. As CUSTOMER, attempt the same call and verify that access is denied (error is thrown).
 */
export async function test_api_admin_customer_history_search_pagination_and_filtering(connection: api.IConnection) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'adminP@ss1!';
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Register a customer
  const customerEmail = typia.random<string & tags.Format<'email'>>();
  const customerPassword = 'customerP@ss01!';
  const signUpReq = {
    email: customerEmail,
    password: customerPassword,
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphaNumeric(8),
    phone: RandomGenerator.mobile(),
  } satisfies ICustomerSignUp.Request;
  const customerSignUpRes = await api.functional.auth.customer.register.signUp(connection, { body: signUpReq });
  typia.assert(customerSignUpRes);
  const customerId = customerSignUpRes.customer.id;

  // 3. As ADMIN, get full history events for this customer, with pagination
  // Simulate admin login by ensuring Authorization is the admin JWT
  connection.headers = { ...connection.headers, Authorization: adminSignUp.setHeaders.Authorization };

  const pageLimit = 5;
  const page1Histories = await api.functional.shoppingMallAiBackend.admin.customers.histories.search(connection, {
    customerId,
    body: {
      customer_id: customerId,
      limit: pageLimit,
      page: 1,
    },
  });
  typia.assert(page1Histories);
