import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendModerationEvent";
import type { IShoppingMallAiBackendAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAppeal";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate soft deletion (erase) of an appeal record by admin and corresponding compliance/audit behaviors.
 *
 * 1. Register an admin (who will be authorized to delete appeals)
 * 2. Log in as that admin to obtain JWT (auth handled auto by SDK)
 * 3. Create a moderation event, required for the new appeal
 * 4. Create an appeal record, linked to the moderation event and admin as appellant
 * 5. Execute the soft delete (erase) operation on the appeal
 * 6. [Not available: There is no standard query/get API for appeals, so we are unable to confirm direct unavailability post-delete. Log/audit-only post-conditions are not API-testable.]
 * 7. Attempt to delete the same (already deleted) appeal should result in an error (e.g., not found or policy error)
 * 8. Attempt to delete a non-existent appealId (random UUID) should return an error as well
 *
 * Notes:
 * - There is no API for direct retrieval/listing of appeals or for explicit deleted_at fetch, so deletion must be validated by error on repeat/fake deletes and lack of further mutation, not by retrieval.
 * - Business expectations of audit log/compliance are out of scope for API test
 */
export async function test_api_admin_appeal_soft_delete_and_compliance(
  connection: api.IConnection,
) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1AdminSecret!";
  const registerRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(registerRes);

  // 2. Login as admin
  const loginRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(loginRes);

  // 3. Create moderation event (admin will be the actor)
  const moderationEvent = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
    body: {
      actor_id: registerRes.adminId,
      event_type: "block",
      // The scenario requires at least one of these two. We'll pick target_inquiry_id for coverage.
      target_inquiry_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "AI detected potential violation for test",
    } satisfies IShoppingMallAiBackendModerationEvent.ICreate,
  });
  typia.assert(moderationEvent);

  // 4. Create appeal (admin is also appellant)
  const appeal = await api.functional.shoppingMallAiBackend.admin.appeals.create(connection, {
    body: {
      moderation_event_id: moderationEvent.id,
      appellant_id: registerRes.adminId,
      status: "pending",
      decision_comment: null,
    } satisfies IShoppingMallAiBackendAppeal.ICreate,
  });
  typia.assert(appeal);

  // 5. Soft delete (erase) appeal
  await api.functional.shoppingMallAiBackend.admin.appeals.erase(connection, {
    appealId: appeal.id,
  });

  // 6. Try to delete again (should get error)
  await TestValidator.error("repeat delete of already deleted appeal should fail")(
    () => api.functional.shoppingMallAiBackend.admin.appeals.erase(connection, { appealId: appeal.id })
  );

  // 7. Try to delete a non-existent appealId
  await TestValidator.error("deleting non-existent appeal should fail")(
    () => api.functional.shoppingMallAiBackend.admin.appeals.erase(connection, { appealId: typia.random<string & tags.Format<"uuid">>() })
  );
}

