/**
 * Validates that admin cannot update immutable or locked mileage transactions via the admin API.
 *
 * - Purpose: Ensure that attempts to change immutable fields (e.g., transaction_type, mileage_amount) or update finalized/locked transactions are correctly rejected.
 * - Context: Only documentation-permitted fields (like transaction_reason) can be modified. transaction_type and amount are immutable after creation. Once a transaction is finalized/locked (by business rule, e.g., by time elapsed, status, or explicit lock), it must not allow edits. All such attempts must be rejected with a meaningful error, and nothing in the transaction should change. Audit logs are expected for compliance.
 *
 * Test Process:
 * 1. Register an admin to obtain privileges and authorization.
 * 2. Admin creates a customer mileage wallet (using required customer_id, program, and status).
 * 3. Admin adds a mileage transaction in that wallet (setting type, amount, etc.).
 * 4. Attempt to update immutable fields (e.g., transaction_type, mileage_amount) using the update endpoint and expect rejection.
 * 5. Attempt to update a valid mutable field (transaction_reason) and expect success.
 * 6. Simulate locking/finalization if possible and attempt another update, expect rejection.
 * 7. After failed update(s), re-fetch the transaction and verify it is unchanged except for permitted field edits.
 */
export async function test_api_mileage_transaction_update_invalid_admin_attempt(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword123!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminAuth);

  // 2. Create mileage wallet
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      wallet_program: "brand",
      wallet_status: "active"
    } satisfies IShoppingMallAiBackendMileageWallet.ICreate
  });
  typia.assert(wallet);

  // 3. Create mileage transaction
  const transaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(connection, {
    mileageWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      transaction_type: "accumulate",
      mileage_amount: 1000,
      reference_id: null,
      transaction_reason: "Initial points"
    } satisfies IShoppingMallAiBackendMileageTransaction.ICreate
  });
  typia.assert(transaction);

  // 4. Attempt to update immutable fields (should fail)
  await TestValidator.error("transaction_type is immutable")(() =>
    api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.update(connection, {
