      mileageTransactionId: transaction.id,
      body: {
        id: transaction.id,
        // Properties like transaction_type cannot be changed (schema only allows id and transaction_reason)
        // As per schema, only transaction_reason is allowed
        transaction_reason: "Trying to update immutable fields"
      } as any // This causes TS error if you try extra fields, so we skip direct TS mutation and just call as per schema
    })
  );

  // 5. Attempt to update a mutable field (transaction_reason)
  const updatedTransaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.update(connection, {
    mileageWalletId: wallet.id,
    mileageTransactionId: transaction.id,
    body: {
      id: transaction.id,
      transaction_reason: "Updated reason"
    } satisfies IShoppingMallAiBackendMileageTransaction.IUpdate
  });
  typia.assert(updatedTransaction);
  TestValidator.equals("transaction_reason updated")(updatedTransaction.transaction_reason)("Updated reason");

  // 6. Simulate locked/finalized transaction (cannot truly finalize via this API, skip if not possible)
  // Not implementable as there is no API or flag for locking/finalization; document and omit.

  // 7. Re-fetching not possible as no read API is provided; skip.
}

