import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponTemplate";
import type { IPageIShoppingMallAiBackendCouponTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCouponTemplate";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test advanced search, filtering, and pagination of coupon templates for admin users.
 *
 * This scenario ensures that the coupon template search endpoint (PATCH /shoppingMallAiBackend/admin/couponTemplates) supports multiple filtering criteria, paginates results correctly, and enforces admin-only access.
 * It checks both cases where matches are found and where no matches are present, across various filter permutations.
 * Steps:
 * 1. Register a new admin account and authenticate (obtain JWT for requests).
 * 2. As admin, create several coupon templates with diverse codes, names, types, validity ranges, and active/inactive status.
 * 3. Search coupon templates with various filters: by name, code, type, is_active, and validity period windows.
 * 4. Confirm that only coupon templates meeting the criteria are returned, and pagination metadata reflects expected records.
 * 5. Simulate search edge cases that should return zero results (e.g., unmatched name/code/type, out-of-window dates).
 * 6. Attempt to search as non-admin (or unauthenticated) and validate unauthorized access is rejected.
 */
export async function test_api_coupon_template_advanced_search_filtering_pagination(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword1!";
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignUp,
  });
  typia.assert(signUpResponse);
  // 2. Authenticate the admin to get a fresh JWT (simulate separate session)
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignIn,
  });
  typia.assert(signInResponse);
  // 3. Register coupon templates with varied attributes for the search tests
  const now = new Date();
  const templates: IShoppingMallAiBackendCouponTemplate[] = [];
  for (let i = 0; i < 5; ++i) {
    const template: IShoppingMallAiBackendCouponTemplate = await api.functional.shoppingMallAiBackend.admin.couponTemplates.create(connection, {
      body: {
        code: `CODE${i}` + RandomGenerator.alphaNumeric(6),
        name: `Special Offer ${i}`,
        description: i % 2 === 0 ? `Even-index description ${i}` : null,
        type: i % 2 === 0 ? "discount" : "gift",
        discount_amount: i % 2 === 0 ? 10 * (i + 1) : null,
        discount_percent: i % 2 === 1 ? 5 * (i + 1) : null,
        min_purchase_amount: i % 2 === 0 ? 50 * (i + 1) : null,
        valid_from: new Date(now.getTime() + i * 60000).toISOString(),
        valid_until: new Date(now.getTime() + (i + 60) * 60000).toISOString(),
        max_issue_count: i % 3 === 0 ? 100 + i : null,
        is_active: i % 2 === 0,
      } satisfies IShoppingMallAiBackendCouponTemplate.ICreate,
    });
    typia.assert(template);
    templates.push(template);
  }
  // 4. Search by code partial match - should return all with the prefix
  const searchByCode = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: { code: "CODE", limit: 10 } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(searchByCode);
  TestValidator.predicate("code partial match includes all templates with 'CODE' prefix")(searchByCode.data.length >= 1);
  for (const t of searchByCode.data) TestValidator.predicate("code contains prefix")(t.code.includes("CODE"));
  // 5. Filter by type (e.g., 'discount') and is_active status
  const searchDiscountActive = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: { type: "discount", is_active: true, limit: 10 } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(searchDiscountActive);
  for (const t of searchDiscountActive.data) {
    TestValidator.equals("filter by type")(t.type)("discount");
    TestValidator.equals("filter by active")(t.is_active)(true);
  }
  // 6. Pagination test: request with limit 2, ensure only 2 per page and correct page meta
  const searchPaged = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: { limit: 2, page: 1 } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(searchPaged);
  TestValidator.equals("pagination limit")(searchPaged.pagination.limit)(2);
  TestValidator.predicate("pagination: at most 2")(searchPaged.data.length <= 2);
  // 7. Edge case: filter by unmatched name → expect 0
  const nomatch = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: { name: "ThisNameDoesNotExist" } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(nomatch);
  TestValidator.equals("no results for unmatched name")(nomatch.pagination.records)(0);
  TestValidator.equals("empty data for no match")(nomatch.data.length)(0);
  // 8. Valid_from/out-of-window search (dateless window should exclude all)
  const farPast = new Date(now.getTime() - 3600 * 1000 * 24 * 30).toISOString();
  const farFuture = new Date(now.getTime() - 3600 * 1000 * 24 * 29).toISOString();
  const dateNoResult = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: { valid_from_min: farPast, valid_from_max: farFuture } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(dateNoResult);
  TestValidator.equals("no matches for out-of-window date")(dateNoResult.pagination.records)(0);
  // 9. Unauthorized search: simulate removed auth header
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers["Authorization"];
  await TestValidator.error("unauthorized access fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(unauthConn, {
      body: { limit: 1 } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
    });
  });
}

