/**
 * Validate that an authenticated customer can successfully create a payment record for their own order.
 *
 * Test Flow:
 * 1. Register a new customer using the public customer registration API (obtain JWT on registration).
 * 2. Using the authenticated session, create a new order owned by that customer, making sure all required order fields are populated with realistic business values.
 * 3. Attempt to create an order payment for the created order, supplying valid values for provider, payment method, amount, etc.
 * 4. Validate that:
 *    - The response contains a payment record (IShoppingMallAiBackendOrderPayment) with all fields populated (id, order_id, payment_provider_id, amount, etc.)
 *    - The order_id references the correct order
 *    - Audit fields (created_at, updated_at) are present and properly formatted
 *    - Business fields (payment_method, payment_result, amount, currency_code) are accurately echoed from supplied values
 *    - The payment is owned by the correct customer (only possible for orders owned by the current session)
 * 5. Try a negative test: attempt to create a payment with an incorrect order_id (either a random UUID or one not owned by the customer) and verify an error is thrown (error only, not error message or structure).
 */
export async function test_api_order_payment_create_customer_success(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const customerInput: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const register: ICustomerSignUp.Response = await api.functional.auth.customer.register.signUp(connection, { body: customerInput });
  typia.assert(register);
  // Attach Authorization header so session is authenticated from this point
  connection.headers = {
    ...connection.headers,
    Authorization: register.setHeaders.Authorization,
  };
  const customer = register.customer;

  // 2. Create a new order for this customer
  const orderInput: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customer.id,
    order_number: RandomGenerator.alphaNumeric(16),
    total_amount: 99900,
    currency_code: "KRW",
    current_status: "created",
  };
  const order: IShoppingMallAiBackendOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderInput });
  typia.assert(order);

  // 3. Create a payment record for the new order
  const paymentInput: IShoppingMallAiBackendOrderPayment.ICreate = {
    order_id: order.id,
    payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
    payment_method: "card",
    transaction_id: RandomGenerator.alphaNumeric(20),
    amount: order.total_amount,
    currency_code: order.currency_code,
    payment_result: "completed",
  };
  const payment: IShoppingMallAiBackendOrderPayment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, { orderId: order.id, body: paymentInput });
  typia.assert(payment);
  // Validate main business/audit fields in the payment record
  TestValidator.equals("order_id matches")(payment.order_id)(order.id);
  TestValidator.equals("amount")(payment.amount)(order.total_amount);
  TestValidator.equals("currency_code")(payment.currency_code)(order.currency_code);
  TestValidator.equals("payment_method")(payment.payment_method)(paymentInput.payment_method);
  TestValidator.equals("payment_result")(payment.payment_result)(paymentInput.payment_result);
  TestValidator.equals("payment_provider_id")(payment.payment_provider_id)(paymentInput.payment_provider_id);
  TestValidator.equals("transaction_id")(payment.transaction_id)(paymentInput.transaction_id);
  // Check for audit trail fields
  TestValidator.predicate("created_at is ISO string")((typeof payment.created_at === 'string') && (/\d{4}-\d{2}-\d{2}T/.test(payment.created_at)));
  TestValidator.predicate("updated_at is ISO string")((typeof payment.updated_at === 'string') && (/\d{4}-\d{2}-\d{2}T/.test(payment.updated_at)));
  // Confirm soft delete is not set
  TestValidator.equals("payment deleted_at is null or undefined")(payment.deleted_at ?? null)(null);

  // 4. Negative test: use random orderId not owned by this customer
  await TestValidator.error("Creating payment for unrelated order should fail")(async () => {
    await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
      orderId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        ...paymentInput,
        order_id: typia.random<string & tags.Format<"uuid">>(),
      },
    });
  });
}

