  const _resetToA = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerAEmail,
      password: "1234!@#Abc",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  // Now authenticated as Customer A again.
  const productInquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerAId,
