          status: productInquiry.status as "waiting" | "answered" | "blocked" | "under_review" | "deleted", // Cast as appropriate enum
          actor_id: customerBId,
          ai_sentiment_score: productInquiry.ai_sentiment_score ?? null,
          ai_spam_score: productInquiry.ai_spam_score ?? null,
          changed_at: new Date().toISOString() as string & tags.Format<"date-time">,
        } satisfies IShoppingMallAiBackendInquirySnapshot.ICreate,
      });
    }
  );
