/**
 * Validates deletion of product search keywords by a seller, including permissions and existence constraints.
 *
 * Business context: Sellers enrich their product searchability by assigning keywords. They need the ability to remove obsolete or mistyped keywords securely. The action must be limited to the owning seller and ensure referential integrity; error handling and audit recording are critical for compliance and troubleshooting.
 *
 * Test steps:
 * 1. Register a new seller (for authentication and seller context).
 * 2. Create a product with that seller as owner.
 * 3. Add a search keyword to the created product; capture returned IDs.
 * 4. Delete the product search keyword mapping (main subject under test).
 * 5. Attempt to fetch (list) product search keywords for that product, asserting the keyword is no longer present.
 * 6. Attempt deletion of a non-existent keyword, expecting an error.
 * 7. Register a second seller and create a product+keyword under this different seller.
 * 8. Attempt to delete that keyword from the original seller account; expect a permissions error.
 * 9. Attempt to delete a keyword without authentication or as a totally unrelated user; expect an auth/perm error.
 * 10. (If possible) Check or assert that necessary audit/log properties are present in responses or server logs per schema (if available or exposed via API).
 */
export async function test_api_product_search_keyword_seller_delete(connection: api.IConnection) {
  // 1. Register seller
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, { body: {
    email: typia.random<string & tags.Format<"email">>(),
    password: "SellerPassword123!",
    companyName: RandomGenerator.name(),
    businessNumber: typia.random<string>(),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile()
  } satisfies ISellerAuth.SignUp });
