    seller_id: sellerId,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    main_image_uri: null,
    status: "draft"
  } satisfies IShoppingMallAiBackendProduct.ICreate });
  typia.assert(product);

  // 3. Add a search keyword to the product
  const keyword1 = await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.createProductSearchKeyword(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      search_keyword: RandomGenerator.alphabets(10)
    } satisfies IShoppingMallAiBackendProductSearchKeyword.ICreate
  });
  typia.assert(keyword1);

  // 4. Delete the product search keyword
  await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.erase(connection, {
    productId: product.id,
    productSearchKeywordId: keyword1.id
  });

  // 5. VERIFY: No keyword listing endpoint provided, so skipping keyword list assertion.
