    await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.erase(connection, {
      productId: product.id,
      productSearchKeywordId: typia.random<string & tags.Format<"uuid">>()
    });
  });

  // 7. Register second seller, create product+keyword
  const seller2SignUp = await api.functional.auth.seller.register.signUp(connection, { body: {
    email: typia.random<string & tags.Format<"email">>(),
    password: "AnotherSellerPass!",
    companyName: RandomGenerator.name(),
    businessNumber: typia.random<string>(),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile()
  } satisfies ISellerAuth.SignUp });
  typia.assert(seller2SignUp);
  const seller2Id = seller2SignUp.sellerId;
  const product2 = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: {
    seller_id: seller2Id,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    main_image_uri: null,
    status: "draft"
  } satisfies IShoppingMallAiBackendProduct.ICreate });
  typia.assert(product2);
  const keyword2 = await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.createProductSearchKeyword(connection, {
    productId: product2.id,
    body: {
      product_id: product2.id,
      search_keyword: RandomGenerator.alphabets(8)
    } satisfies IShoppingMallAiBackendProductSearchKeyword.ICreate
  });
  typia.assert(keyword2);

  // 8. Attempt to delete another seller's keyword (should fail)
  await TestValidator.error("delete keyword from non-owned product fails")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.erase(connection, {
      productId: product2.id,
      productSearchKeywordId: keyword2.id
    });
  });

  // 9. Skipped: cannot unauthenticate or impersonate unrelated user in this SDK context.
  // 10. Skipped: audit log properties not exposed by any available endpoint.
