/**
 * Validate the creation of a payment log for a customer order payment.
 *
 * Business context: Creating a payment log (audit/event) is an essential step in tracking payment events (e.g., 'PAYMENT_REQUEST', 'PAYMENT_COMPLETED') for compliance and operational traceability. The test should simulate a real workflow where a customer registers, creates an order, pays for it, and then logs an event on the payment lifecycle.
 *
 * Step-by-step process:
 * 1. Register a new customer (and acquire JWT authorization for subsequent requests)
 * 2. Create a new order under that customer using valid data
 * 3. Create an order payment for that order (simulate a payment attempt or completion)
 * 4. Create a payment log (e.g., 'PAYMENT_REQUEST') for the new order payment, include realistic context JSON, and use the current timestamp for occurred_at
 * 5. Verify all expected response fields: id, order_payment_id, log_type, log_context, occurred_at
 * 6. Ensure the log is associated with the correct order payment
 * 7. (If the list/search API were available, confirm the log can be retrieved as part of the payment log history)
 */
export async function test_api_order_payment_log_creation_success(connection: api.IConnection) {
  // Step 1: Register customer
  const customerEmail = typia.random<string & tags.Format<'email'>>();
  const customerNickname = RandomGenerator.name();
  const customerSignup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "1234password!",
      name: RandomGenerator.name(),
      nickname: customerNickname,
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignup);
  const customer = customerSignup.customer;

  // Auth header (JWT) is now set in connection automatically

  // Step 2: Create order
  const orderData: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customer.id,
    order_number: `ORDER-${Date.now()}`,
    total_amount: 7777,
    currency_code: 'KRW',
    current_status: "created",
    // optional: order_group_id, note
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: orderData,
  });
  typia.assert(order);

  // Step 3: Create order payment
  const paymentData: IShoppingMallAiBackendOrderPayment.ICreate = {
    order_id: order.id,
    payment_provider_id: typia.random<string & tags.Format<'uuid'>>(),
    payment_method: "card",
    transaction_id: `TX-${Math.floor(Math.random() * 10000000)}`,
    amount: order.total_amount,
    currency_code: order.currency_code,
    payment_result: "completed",
    payment_context: JSON.stringify({ gateway: "NICEPAY", ref: RandomGenerator.alphaNumeric(10) }),
  };
  const payment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: paymentData,
  });
  typia.assert(payment);

  // Step 4: Create payment log
  const logNow = new Date().toISOString();
  const logData: IShoppingMallAiBackendOrderPaymentLog.ICreate = {
    log_type: "PAYMENT_REQUEST",
    log_context: JSON.stringify({ action: "initiated", detail: "Initial payment request sent" }),
    occurred_at: logNow,
  };
  const log = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.create(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: logData,
  });
  typia.assert(log);

  // Step 5: Validate response fields and associations
  TestValidator.equals("order_payment association")(log.order_payment_id)(payment.id);
  TestValidator.equals("log_type")(log.log_type)(logData.log_type);
  TestValidator.predicate("log_context structure")(!!log.log_context && log.log_context.includes("initiated"));
  TestValidator.equals("occurred_at value")(log.occurred_at)(logNow);
  TestValidator.predicate("id format")(!!log.id && /^[0-9a-fA-F-]{36}$/.test(log.id));

  // Step 6: (If list endpoint existed, would retrieve logs and confirm new log presence)
}

