import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import type { IShoppingMallAiBackendReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendReviewSnapshot";
import type { IPageIShoppingMallAiBackendReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendReviewSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that a seller cannot access review snapshots for a product they do not own.
 *
 * Business context:
 * Seller review snapshots are allowed only for reviews on products owned by the authenticating seller. This test ensures access control and compliance with data isolation principles, preventing disclosure of other sellers’ product review history. If a seller attempts to access review snapshots for another seller’s product, the system must deny permission (typically an HTTP 403 Forbidden or equivalent error).
 *
 * Steps:
 * 1. Register two sellers (Seller A and Seller B) with distinct emails and realistic "company" information.
 * 2. (Assume) Both sellers will have at least one product in the system due to dependency; however, the explicit product creation endpoint is not exposed in SDK, so test will use review creation to simulate a product "owned" by Seller A.
 * 3. Simulate a customer review for Seller A’s product (so, a known valid review for a known product ID).
 * 4. As Seller B, attempt to retrieve review snapshots for the review on Seller A’s product via the PATCH /shoppingMallAiBackend/seller/productReviews/{productReviewId}/reviewSnapshots endpoint.
 * 5. Validate that the API responds with an error (forbidden access due to lack of ownership).
 *
 * This test validates negative access control (security) around the review snapshots API (seller scope), catching accidental or malicious exposure of audit trail data across seller boundaries.
 */
export async function test_api_seller_review_snapshot_access_for_unowned_product(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerA = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "strongpasswordA!", // Strong password for testing
      companyName: RandomGenerator.name(),
      businessNumber: typia.random<string>(),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(20),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerA);

  // 2. Register Seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerB = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "strongpasswordB!",
      companyName: RandomGenerator.name(),
      businessNumber: typia.random<string>(),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(20),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerB);

  // 3. Create a review (simulate customer review on Seller A's product)
  const productId = typia.random<string & tags.Format<"uuid">>();
  const orderItemId = typia.random<string & tags.Format<"uuid">>();
  const reviewInput = {
    product_id: productId,
    order_item_id: orderItemId,
    title: "Good Product",
    body: "Nice product and fast shipping!",
    rating: 5,
    status: "normal",
  } satisfies IShoppingMallAiBackendProductReview.ICreate;
  const review = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, { body: reviewInput });
  typia.assert(review);

  // 4. As Seller B, attempt to fetch review snapshots for Seller A's product's review
  // Switch the connection to Seller B's credentials, simulating authorization as Seller B
  connection.headers = { ...connection.headers, Authorization: sellerB.setHeaders.Authorization };
  await TestValidator.error("seller cannot access another seller's review snapshot")(async () => {
    await api.functional.shoppingMallAiBackend.seller.productReviews.reviewSnapshots.search(connection, {
      productReviewId: review.id,
      body: {
        review_id: review.id,
      } satisfies IShoppingMallAiBackendReviewSnapshot.IRequest,
    });
  });
}

