import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendComplianceEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceEvent";
import type { IShoppingMallAiBackendComplianceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceSnapshot";
import type { IPageIShoppingMallAiBackendComplianceSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendComplianceSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for searching and paginating compliance snapshots with filters as admin.
 *
 * This scenario tests the full admin workflow for querying compliance snapshots:
 * 1. Create at least two compliance events with unique attributes.
 * 2. For each event, create at least one compliance snapshot (with distinct entity_type, entity_id, and payload).
 * 3. Search for compliance snapshots using the PATCH /shoppingMallAiBackend/admin/complianceSnapshots endpoint:
 *    - No filters (should return all created snapshots, paginated).
 *    - Filter by compliance_event_id (should return only snapshots for that event).
 *    - Filter by entity_type (should return snapshots of that type).
 *    - Filter by date range (created_from, created_to).
 *    - Paginate (page, page_size), checking records and pages counts.
 *    - Request sorting (sort by created_at desc).
 * 4. Attempt to use malformed filters (e.g., invalid UUIDs, inverted date window, negative page) and assert error is returned.
 * 5. Assert that only an admin user can access this endpoint (other user types, if present, should fail with forbidden or unauthorized errors).
 * 6. Ensure evidence snapshot_payload is present but does not leak sensitive non-permitted data.
 *
 * Steps:
 * - Create two compliance events with different event_types, actor, and targets.
 * - Create compliance snapshots for each event, using different entity_type and entity_id.
 * - Search all snapshots without filter; assert all previously created ones are found.
 * - Filter by compliance_event_id; assert only relevant snapshots are returned.
 * - Filter by entity_type; results should only include correct types.
 * - Filter by creation window; only snapshots within window are present.
 * - Paginate: query first and second pages, check pagination meta.
 * - Sort DESC by created_at; check ordering.
 * - Try malformed search (invalid event ID, invalid date, negative page, etc.), assert error response.
 * - (If possible): Attempt as non-admin and expect error.
 */
export async function test_api_compliance_snapshot_search_with_filters(connection: api.IConnection) {
  // 1. Create at least two compliance events with different properties
  const event1 = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
    body: {
      event_type: "policy_update",
      actor_type: "admin",
      target_type: "customer",
      event_payload: JSON.stringify({ foo: 1 })
    }
  });
  typia.assert(event1);

  const event2 = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
    body: {
      event_type: "data_erasure_request",
      actor_type: "admin",
      target_type: "order",
      event_payload: JSON.stringify({ bar: 2 })
    }
  });
  typia.assert(event2);

  // 2. For each event, create at least one compliance snapshot
  const entityId1 = typia.random<string & tags.Format<"uuid">>();
  const entityId2 = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const payload1 = JSON.stringify({ state: "pre", special: Math.random() });
  const payload2 = JSON.stringify({ state: "post", special: Math.random() });

  const snapshot1 = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.create(connection, {
    complianceEventId: event1.id,
    body: {
      compliance_event_id: event1.id,
      entity_type: "customer",
      entity_id: entityId1,
      snapshot_payload: payload1
    }
  });
  typia.assert(snapshot1);

  const snapshot2 = await api.functional.shoppingMallAiBackend.admin.complianceEvents.complianceSnapshots.create(connection, {
    complianceEventId: event2.id,
    body: {
      compliance_event_id: event2.id,
      entity_type: "order",
      entity_id: entityId2,
      snapshot_payload: payload2
    }
  });
  typia.assert(snapshot2);

  // 3A. Search for all compliance snapshots (no filters)
  const allSnapshotsPage = await api.functional.shoppingMallAiBackend.admin.complianceSnapshots.search(connection, {
    body: {}
  });
  typia.assert(allSnapshotsPage);
  TestValidator.predicate("all snapshots present")(allSnapshotsPage.data.some(s => s.id === snapshot1.id) && allSnapshotsPage.data.some(s => s.id === snapshot2.id));

  // 3B. Search with compliance_event_id filter
  const filteredByEvent = await api.functional.shoppingMallAiBackend.admin.complianceSnapshots.search(connection, {
    body: { compliance_event_id: event1.id }
  });
  typia.assert(filteredByEvent);
  TestValidator.predicate("only event1 snapshots")(filteredByEvent.data.every(s => s.compliance_event_id === event1.id));

  // 3C. Search with entity_type filter
  const filteredByType = await api.functional.shoppingMallAiBackend.admin.complianceSnapshots.search(connection, {
    body: { entity_type: "order" }
  });
  typia.assert(filteredByType);
  TestValidator.predicate("only order type")(filteredByType.data.every(s => s.entity_type === "order"));

  // 3D. Search with date filter (created_from/created_to)
  const isoNow = now.toISOString();
  const dateRangeSnapshots = await api.functional.shoppingMallAiBackend.admin.complianceSnapshots.search(connection, {
    body: { created_from: isoNow, created_to: isoNow }
  });
  typia.assert(dateRangeSnapshots);
  TestValidator.predicate("created date filter")(
