 *
 * 1. Admin logs in and gets JWT.
 * 2. Create a customer order as test fixture (~simulate a customer pre-created in the DB).
 * 3. As admin, create a payment record for this order using admin endpoint.
 * 4. Retrieve the payment by its ID as admin.
 * 5. Validate that all fields match and audit information is present (created/updated/deleted fields).
 * 6. Attempt to retrieve a payment by a nonexistent payment ID (expect error).
 * 7. Attempt to retrieve a payment for a nonexistent order ID (expect error).
 * 8. (Privilege error case) Re-authenticate as normal customer, and confirm that customer cannot access this payment via the admin API.
 */
export async function test_api_admin_order_payment_detail_access_and_error(
  connection: api.IConnection,
) {
  // 1. Admin logs in and gets JWT.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin123!";
  // (Assume this admin is already registered in DB for test infra.)
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);
  TestValidator.equals("admin JWT format")(typeof adminAuth.jwt)("string");

  // 2. Create customer order via customer API.
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const orderCreate: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customerId,
    order_group_id: null,
