  TestValidator.equals("currency match")(payment.currency_code)(order.currency_code);
  TestValidator.equals("created_at exists")(typeof payment.created_at)("string");
  TestValidator.equals("updated_at exists")(typeof payment.updated_at)("string");

  // 4. Retrieve the payment by its ID as admin.
  const found = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.at(
    connection,
    {
      orderId: order.id,
      orderPaymentId: payment.id,
    },
  );
  typia.assert(found);
  TestValidator.equals("fetched id matches")(found.id)(payment.id);
  TestValidator.equals("fetched data matches")(found)(payment);

  // 5. (Audit fields checked above)

  // 6. Retrieve with nonexistent payment ID (should error).
  await TestValidator.error("nonexistent payment id")(async () => {
    await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.at(
      connection,
      {
        orderId: order.id,
        orderPaymentId: typia.random<string & tags.Format<"uuid">>(), // Random likely not existing
      },
    );
  });

