import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that creating a payment log is only permitted by the payment's owning customer.
 *
 * This test performs end-to-end validation that RBAC and ownership are enforced for payment log creation by attempting to create a log entry with the JWT of a different customer.
 *
 * **Test process:**
 * 1. Register first customer (owner of the payment)
 * 2. Register second customer (will attempt forbidden action)
 * 3. Create an order as the first customer
 * 4. Create a payment for that order as the first customer
 * 5. As the second customer, attempt to create a payment log for the other customer's payment (should be denied)
 * 6. Confirm that the creation is rejected and does not leak payment log data
 */
export async function test_api_order_payment_log_creation_invalid_permission(connection: api.IConnection) {
  // 1. Register first customer
  const customer1Email = typia.random<string & tags.Format<"email">>();
  const signUpResp1 = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer1Email,
      password: "testPassword1!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpResp1);
  const customer1 = signUpResp1.customer;
  // JWT is set in connection

  // 2. Register second customer (their JWT will replace in connection)
  const customer2Email = typia.random<string & tags.Format<"email">>();
  const signUpResp2 = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer2Email,
      password: "testPassword2!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpResp2);
  const customer2 = signUpResp2.customer;

  // Switch back to first customer's JWT (normally you'd use a login API – here, re-register resets JWT)
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer1Email,
      password: "testPassword1!",
      name: customer1.name,
      nickname: customer1.nickname,
      phone: customer1.phone
    } satisfies ICustomerSignUp.Request,
  });

  // 3. Create order as customer 1
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customer1.id,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 50000,
      currency_code: "KRW",
      current_status: "created"
    } satisfies IShoppingMallAiBackendOrder.ICreate
  });
  typia.assert(order);

  // 4. Create payment for the order
  const payment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
      payment_method: "card",
      transaction_id: RandomGenerator.alphaNumeric(16),
      amount: order.total_amount,
      currency_code: order.currency_code,
      payment_result: "pending"
    } satisfies IShoppingMallAiBackendOrderPayment.ICreate
  });
  typia.assert(payment);

  // 5. Switch to second customer by registering/joining again (will set auth token)
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer2Email,
      password: "testPassword2!",
      name: customer2.name,
      nickname: customer2.nickname,
      phone: customer2.phone
    } satisfies ICustomerSignUp.Request
  });

  // 6. Attempt to create a payment log for customer 1's payment (as customer 2). Expect rejection.
  await TestValidator.error("should not allow creating payment log as non-owner")(
    () => api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: payment.id,
      body: {
        log_type: "request",
        log_context: JSON.stringify({ test: "unauthorized log creation attempt" }),
        occurred_at: new Date().toISOString()
      } satisfies IShoppingMallAiBackendOrderPaymentLog.ICreate
    })
  );
}

