import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate access denial when a customer tries to view a mileage transaction belonging to another customer's wallet.
 *
 * This test ensures that mileage transaction records are accessible only by the customer who owns the wallet or by administrators, enforcing privacy boundaries between customer accounts.
 * It simulates two separately registered customers (A and B), each with their own wallet and transaction. The test confirms that Customer A cannot view a transaction from Customer B's wallet and receives an appropriate permission error.
 *
 * Steps:
 * 1. Register Customer A and Customer B using unique emails and credentials. Save both customer entities and their authentication tokens.
 * 2. As an admin, create a mileage wallet for each customer.
 * 3. As Customer B (using their credentials), create a transaction within Customer B's wallet.
 * 4. Switch back to Customer A (using their credentials), and attempt to fetch the transaction from Customer B's wallet using the GET endpoint.
 * 5. Validate the system returns a permission error and Customer A cannot access the transaction details for Customer B's wallet.
 */
export async function test_api_mileage_transaction_detail_access_forbidden(connection: api.IConnection) {
  // 1. Register Customer A
  const emailA: string = typia.random<string & tags.Format<"email">>();
  const reqA: ICustomerSignUp.Request = {
    email: emailA,
    password: "customerApass123!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const regResA = await api.functional.auth.customer.register.signUp(connection, { body: reqA });
  typia.assert(regResA);

  // 2. Register Customer B
  const emailB: string = typia.random<string & tags.Format<"email">>();
  const reqB: ICustomerSignUp.Request = {
    email: emailB,
    password: "customerBpass123!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const regResB = await api.functional.auth.customer.register.signUp(connection, { body: reqB });
  typia.assert(regResB);

  // 3. Create wallets for both customers (as admin)
  const walletA = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: regResA.customer.id,
      wallet_program: RandomGenerator.alphabets(6),
      wallet_status: "active",
      wallet_label: "Customer A Wallet",
      security_code: null,
    }
  });
  typia.assert(walletA);

  const walletB = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: regResB.customer.id,
      wallet_program: RandomGenerator.alphabets(6),
      wallet_status: "active",
      wallet_label: "Customer B Wallet",
      security_code: null,
    }
  });
  typia.assert(walletB);

  // 4. Switch to Customer B (new connection with Customer B's JWT)
  connection.headers = { ...connection.headers, Authorization: regResB.setHeaders.Authorization };
  // Create a transaction in Customer B's wallet
  const transactionB = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.create(connection, {
    mileageWalletId: walletB.id,
    body: {
      wallet_id: walletB.id,
      transaction_type: "accumulate",
      mileage_amount: 100,
      reference_id: null,
      transaction_reason: "Bonus miles for new customer"
    }
  });
  typia.assert(transactionB);

  // 5. Set connection to Customer A's JWT
  connection.headers = { ...connection.headers, Authorization: regResA.setHeaders.Authorization };

  // Try to GET transaction from Customer B's wallet as Customer A
  await TestValidator.error("forbidden access to another customer's mileage transaction")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.at(connection, {
        mileageWalletId: walletB.id,
        mileageTransactionId: transactionB.id,
      });
    }
  );
}

