import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that an admin can successfully and irreversibly hard-delete a favorite notification.
 *
 * Business context: Favorite notifications are generated for customers (e.g., for product restock, price drop, inquiry replies), and may be deleted either by their owner (the customer) or by an admin with proper privileges. Hard deletion is irreversible, and regulatory compliance requires the removal to be recorded in audit logs.
 *
 * Test process:
 * 1. Register a new admin (for authorization to perform deletion).
 * 2. Register a customer (the notification recipient).
 * 3. As the customer, create a favorite notification (using the creation API with a valid notification payload).
 * 4. Switch to admin authentication context.
 * 5. Delete the favorite notification using its id, via the admin delete endpoint.
 * 6. (Attempt to fetch the notification by id, or produce a negative result – not possible with provided APIs, so this is omitted.)
 * 7. (Query audit/logging is mentioned in scenario, but API to query logs is not supplied, so this is omitted.)
 *
 * Steps 6 and 7 cannot be technically implemented with the currently available API surface. The test will focus on the setup, deletion, and verifying no errors or type assertion failures occur on delete.
 */
export async function test_api_admin_favorite_notification_delete_success(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminRegRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "1234",
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminRegRes);

  // 2. Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerRegRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "1234",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerRegRes);
  const customer = customerRegRes.customer;

  // 3. As the customer, create a favorite notification
  // The notification must reference a favorite object (product, inquiry, or address)
  // For this test, we create a dummy favorite_product_id
  const notificationCreate: IShoppingMallAiBackendFavoriteNotification.ICreate = {
    favorite_product_id: typia.random<string>(),
    notification_type: "RESTOCK", // sample allowed type
    notification_channel: "EMAIL", // sample allowed channel
    read: false,
    // Optionally: delivery_metadata not set
  };
  // Switch to customer session by updating the connection's Authorization header
  connection.headers = {
    ...connection.headers,
    Authorization: customerRegRes.setHeaders.Authorization,
  };
  const createdNotification = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, {
    body: notificationCreate,
  });
  typia.assert(createdNotification);

  // 4. Switch to admin authentication context
  connection.headers = {
    ...connection.headers,
    Authorization: adminRegRes.setHeaders.Authorization,
  };

  // 5. Hard-delete the favorite notification via the admin API
  await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.erase(connection, {
    favoriteNotificationId: createdNotification.id as string & tags.Format<"uuid">,
  });
  // No output to assert as erase returns void. If it doesn't throw, test passes for implementation.
}

