  const fakeCustomerId = typia.random<string & tags.Format<"uuid">>();
  const forbidden = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.search(connection, {
    body: {
      customer_id: fakeCustomerId
    }
  });
