    connection,
    {
      productId: product.id,
      productSnapshotId: snapshot.id,
    }
  );
  // Soft-delete has no output; verify deletion by querying with seller/user should not show it
  // (Assuming a listing/query endpoint for historical snapshots, which is not in provided SDK; we skip this but outline in documentation)
