import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSnapshot";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that a seller cannot access a product snapshot belonging to another seller.
 *
 * This test covers resource-level access control enforcement for product snapshots in the seller domain. It ensures the API robustly prevents unauthorized sellers from viewing product-specific history or evidence for products they don't own, supporting compliance and business confidentiality requirements.
 *
 * Workflow:
 * 1. Register Seller A (the owner of the product and its snapshot).
 * 2. Register Seller B (a second, unrelated seller).
 * 3. As Seller A, create a product (and retain its productId).
 * 4. As Seller A, create a product snapshot for the product (and retain the productSnapshotId).
 * 5. As Seller B, attempt to retrieve the snapshot for Seller A's product using the respective productId and productSnapshotId.
 * 6. Validation: The GET request must fail with a 403 Forbidden error.
 *
 * Business importance: Confirms that evidence/snapshot records are only available to product owners or privileged accounts. Failure here indicates a serious security/control flaw.
 */
export async function test_api_product_snapshot_detail_access_by_non_owner_seller_forbidden(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerA = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerA);

  // 2. Register Seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerB = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: "0987654321",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerB);

  // 3. As Seller A: set Authorization and create product
  connection.headers = { ...connection.headers, Authorization: sellerA.setHeaders.Authorization };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerA.sellerId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    },
  });
  typia.assert(product);

  // 4. As Seller A: create product snapshot
  const snapshot = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      snapshot_code: RandomGenerator.alphaNumeric(12),
      snapshot_type: "created",
      name: product.name,
      description: product.description,
      main_image_uri: product.main_image_uri,
      status: product.status,
    },
  });
  typia.assert(snapshot);

  // 5. As Seller B: set Authorization to Seller B and attempt snapshot access
  connection.headers = { ...connection.headers, Authorization: sellerB.setHeaders.Authorization };
  await TestValidator.error("seller B forbidden from another seller's snapshot")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.at(connection, {
      productId: product.id,
      productSnapshotId: snapshot.id,
    });
  });
}

