  // 1. Register a seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "AutoBeTest!234";
  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(1),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Log in as seller to set session (token gets attached to connection automatically)
  const signInResp = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create a seller product
  const productDraft = {
    seller_id: signUpResp.sellerId,
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.paragraph()(2),
    status: "published",
    main_image_uri: null,
  } satisfies IShoppingMallAiBackendProduct.ICreate;
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: productDraft });
  typia.assert(product);

  // 4. Create the first product option with a generated SKU
  const optionSku = RandomGenerator.alphaNumeric(12);
  const optionDraft: IShoppingMallAiBackendProductOption.ICreate = {
    product_id: product.id,
    sku: optionSku,
    option_name: `Color-Red`,
    option_values: "red",
    extra_price: 1000.0,
    main_image_uri: null,
    status: "active",
  };
  const firstOption = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: optionDraft,
  });
  typia.assert(firstOption);
  TestValidator.equals("option sku should match")(firstOption.sku)(optionSku);

  // 5. Attempt to create duplicate SKU under same product, expect error
  await TestValidator.error("duplicate SKU under same product should fail")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        sku: optionSku,
        option_name: `Color-Blue`,
        option_values: "blue",
        extra_price: 1200.0,
        main_image_uri: null,
        status: "active",
      } satisfies IShoppingMallAiBackendProductOption.ICreate,
    });
  });
}

