import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * End-to-end test of product review search functionality for customers with various filter, pagination, and security conditions.
 *
 * This test ensures that a customer can:
 *   - Search their own product reviews using available filters: product, rating, status, AI moderation, full-text.
 *   - Receive correct results when filters match multiple, single, or zero reviews.
 *   - Pagination and ordering work as expected (e.g., new/old first, rating order).
 *   - Cannot access (see) reviews by other customers.
 *   - Invalid filters or unauthorized access returns an error.
 *
 * Steps:
 * 1. Log in a test customer (dependency: customer login)
 * 2. Create three distinct reviews for different products and ratings
 * 3. Search with various criteria:
 *     a. By product – expect exactly one result for each product
 *     b. By rating range (covering all, single, or none)
 *     c. By status (e.g., only "normal" or none when status mismatches)
 *     d. By keywords (in title/body of specific review)
 *     e. By impossible criteria – expect no results
 *     f. Pagination: limit=1, limit=2, check records & total
 *     g. Sort by rating (asc/desc) and verify order
 * 4. Ensure all returned reviews belong to logged-in customer and no review from other users is present
 * 5. Attempt to use another customer's id in filter and check for error or empty results
 * 6. Attempt invalid parameter values and expect error responses
 */
export async function test_api_product_review_search_various_filters(connection: api.IConnection) {
  // 1. Log in test customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPass!1";
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email,
      password
    }
  });

  // 2. Create reviews for setup
  const productA = typia.random<string & tags.Format<"uuid">>();
  const productB = typia.random<string & tags.Format<"uuid">>();
  const productC = typia.random<string & tags.Format<"uuid">>();
  const orderItemA = typia.random<string & tags.Format<"uuid">>();
  const orderItemB = typia.random<string & tags.Format<"uuid">>();
  const orderItemC = typia.random<string & tags.Format<"uuid">>();
  const baseBody = "This review body is unique: " + typia.random<string>();
  const review1 = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: productA,
      order_item_id: orderItemA,
      title: "Great Shoe",
      body: baseBody + " #A",
      rating: 5,
      status: "normal"
    }
  });
  typia.assert(review1);
  const review2 = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: productB,
      order_item_id: orderItemB,
      title: "Bad phone",
      body: baseBody + " #B",
      rating: 2,
      status: "blocked"
    }
  });
  typia.assert(review2);
  const review3 = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: productC,
      order_item_id: orderItemC,
      title: "Okay bag",
      body: baseBody + " #C",
      rating: 3,
      status: "normal"
    }
  });
  typia.assert(review3);

  // 3a. Filter by product
  const byProduct = await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
    body: {
      product_id: productA,
      page: 1,
      limit: 10
    }
  });
  typia.assert(byProduct);
  TestValidator.equals("byProduct count")(byProduct.data.length)(1);
  TestValidator.equals("byProduct id")(byProduct.data[0].id)(review1.id);

  // 3b. Filter by rating range (should match review1: 5 and review3: 3)
  const byRating = await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
    body: {
      rating_from: 3,
      rating_to: 5,
      page: 1,
      limit: 10
    }
  });
  typia.assert(byRating);
  TestValidator.predicate("byRating contains review1 and review3")(
    byRating.data.some(r => r.id === review1.id) && byRating.data.some(r => r.id === review3.id)
  );

  // 3c. Filter by status=blocked (should match review2 only)
  const byStatus = await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
    body: {
      status: "blocked",
      page: 1,
      limit: 10
    }
  });
  typia.assert(byStatus);
  TestValidator.equals("byStatus count")(byStatus.data.length)(1);
  TestValidator.equals("byStatus id")(byStatus.data[0].id)(review2.id);

  // 3d. Filter by full-text keyword (match title/body of review2)
  const byKeyword = await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
    body: {
      search: baseBody + " #B",
      page: 1,
      limit: 10
    }
  });
  typia.assert(byKeyword);
  TestValidator.equals("byKeyword count")(byKeyword.data.length)(1);
  TestValidator.equals("byKeyword id")(byKeyword.data[0].id)(review2.id);

  // 3e. Filter by impossible condition (no result)
  const byNone = await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
    body: {
      rating_from: 1,
      rating_to: 1,
      page: 1,
      limit: 10
    }
  });
  typia.assert(byNone);
  TestValidator.equals("byNone count")(byNone.data.length)(0);

  // 3f. Pagination tests
  const paged1 = await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
    body: {
      page: 1,
      limit: 2
    }
  });
  typia.assert(paged1);
  TestValidator.equals("paged1 count")(paged1.data.length)(2);
  const paged2 = await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
    body: {
      page: 2,
      limit: 2
    }
  });
  typia.assert(paged2);
  TestValidator.equals("paged2 count")(paged2.data.length)(1);
  // paged1 and paged2 pagination.records refer to same total, so sum not needed.

  // 3g. Sort by rating desc/asc
  const sortedDesc = await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
    body: {
      sort_by: "rating",
      sort_direction: "desc",
      page: 1,
      limit: 10
    }
  });
  typia.assert(sortedDesc);
  TestValidator.predicate("desc order")(sortedDesc.data[0].rating >= sortedDesc.data[sortedDesc.data.length - 1].rating);
  const sortedAsc = await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
    body: {
      sort_by: "rating",
      sort_direction: "asc",
      page: 1,
      limit: 10
    }
  });
  typia.assert(sortedAsc);
  TestValidator.predicate("asc order")(sortedAsc.data[0].rating <= sortedAsc.data[sortedAsc.data.length - 1].rating);

  // 4. Ensure all reviews in paged1 and paged2 belong to this customer
  for (const r of paged1.data.concat(paged2.data)) {
    TestValidator.predicate("customer_id matches")(!!r.customer_id);
  }

  // 5. Try searching with another (random) customer_id – should be empty or forbidden
  const otherCustomerId = typia.random<string & tags.Format<"uuid">>();
  const byOther = await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
    body: {
      customer_id: otherCustomerId,
      page: 1,
      limit: 10
    }
  });
  typia.assert(byOther);
  TestValidator.equals("byOther count")(byOther.data.length)(0);

  // 6. Invalid parameter: invalid limit value (e.g. 500, which exceeds max=100)
  await TestValidator.error("invalid limit fails")(async () => {
    await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
      body: {
        limit: 500,
        page: 1
      }
    });
  });

  // 6b. Invalid sort_by value
  await TestValidator.error("invalid sort_by fails")(async () => {
    await api.functional.shoppingMallAiBackend.customer.productReviews.search(connection, {
      body: {
        sort_by: "not_a_field" as any,
        page: 1,
        limit: 10
      } as any
    });
  });
}

