/**
 * Validate seller-side listing and searching of product bundles.
 *
 * This test case covers the whole business journey: registering a seller, creating a product,
 * creating multiple product bundles, and verifying paginated+filtered search as the seller.
 *
 * 1. Register a new seller (to set up all subsequent steps fully isolated)
 * 2. Create a product under the registered seller's context
 * 3. Create several bundles for the created product (vary code, name, and status)
 * 4. As the seller, search bundles for that product using:
 *    - No filters (default list)
 *    - Status filter (should match returned status only)
 *    - Name substring filter (should match bundles by name substring)
 *    - Pagination (limit, page selection)
 * 5. For each search:
 *    - Confirm returned bundles are only for the product
 *    - Confirm that filter/pagination options affect the result as expected
 *    - Check that each listed bundle's summary matches the earlier creation step for data integrity
 */
export async function test_api_product_bundle_list_success_seller(
  connection: api.IConnection,
) {
  // 1. Register seller
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPass!1",
      companyName: RandomGenerator.name(),
      businessNumber: ("" + typia.random<number & tags.Type<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>>()),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    }
  });
  typia.assert(sellerSignUp);
  const sellerId = sellerSignUp.sellerId;

  // 2. Create Product under seller
  const productCreate = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      status: "draft",
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
    }
  });
  typia.assert(productCreate);
  const productId = productCreate.id;

  // 3. Create 3 product bundles with different names and statuses
  const statuses = ["active", "hidden", "discontinued"];
  const createdBundles: IShoppingMallAiBackendProductBundle[] = [];
  for (let idx = 0; idx < 3; ++idx) {
    const bundle = await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, {
      productId,
      body: {
        main_product_id: productId,
        code: RandomGenerator.alphaNumeric(6) + idx,
        name: `Bundle_${idx}_${RandomGenerator.alphabets(3)}`,
        description: idx % 2 === 0 ? RandomGenerator.paragraph()() : null,
        bundle_policy: idx % 2 ? null : RandomGenerator.paragraph()(),
        bundle_price: idx === 1 ? 9999 + idx : null,
        status: statuses[idx],
      }
    });
    typia.assert(bundle);
    createdBundles.push(bundle);
  }

  // 4. List bundles - default (no filters)
  const searchAll = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: {
      page: 1,
      limit: 100,
    }
  });
  typia.assert(searchAll);
  // Should return all created bundles for this product
  const returnedIds = searchAll.data.map((b) => b.id);
  for (const bundle of createdBundles) {
    TestValidator.predicate("bundle returned in search")(returnedIds.includes(bundle.id));
  }
  for (const summary of searchAll.data) {
    TestValidator.equals("product id matches in summary")(summary.main_product_id)(productId);
  }

  // 5. Filter by status: Check 'active' status only
  const searchActive = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { status: "active" }
  });
  typia.assert(searchActive);
  for (const summary of searchActive.data) {
    TestValidator.equals("status is active")(summary.status)("active");
  }

  // 6. Filter by name substring (ensure matches at least one bundle's name)
  const nameSubstring = createdBundles[1].name.slice(3, 6); // middle 3 chars
  const searchByName = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { name: nameSubstring }
  });
  typia.assert(searchByName);
  const nameFilteredIds = searchByName.data.map((x) => x.id);
  TestValidator.predicate("at least one bundle matches name substring")(
    nameFilteredIds.includes(createdBundles[1].id)
  );

  // 7. Pagination test (limit 1)
  const page1 = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { page: 1, limit: 1 }
  });
  typia.assert(page1);
  TestValidator.equals("returned records 1")(page1.data.length)(1);
  const page2 = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { page: 2, limit: 1 }
  });
  typia.assert(page2);
  TestValidator.equals("returned records 1")(page2.data.length)(1);
  TestValidator.notEquals("page 1 and 2 different bundle")(
    page1.data[0].id
  )(page2.data[0].id);
}

