import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendChannel";
import type { IShoppingMallAiBackendSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSection";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates successful update of a channel section by an admin in the shopping mall AI backend.
 *
 * This test covers the entire flow required for an admin to update a section:
 * 1. Register a new admin and obtain credentials.
 * 2. Create a new channel as the registered admin.
 * 3. Create an initial section for the new channel.
 * 4. Update the section's name, description, display_order, and visible status via the update API. Attempt to update 'code' (should NOT be changed per business immutability rules).
 * 5. Verify the API returns the updated fields, and updated_at is changed.
 * 6. Confirm the 'code' remains unchanged.
 * 7. (If possible) Confirm audit event handling (if auditable via API or visible in returned object; otherwise, skip this as out of technical scope).
 *
 * This test ensures business rules around section updates including immutability for 'code', correctness of modification, and proper authentication, are enforced.
 */
export async function test_api_channel_section_update_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "1234Admin!";
  const adminResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminResp);
  const adminId = adminResp.adminId;

  // 2. Create a new channel as admin
  const channelReq: IShoppingMallAiBackendChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: "Test Channel",
    created_by_admin_id: adminId,
    description: "Initial Channel for Section Update Test",
    logo_url: null,
    active: true,
  };
  const channel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: channelReq,
  });
  typia.assert(channel);
  TestValidator.equals("created_by_admin_id reflects admin")(channel.created_by_admin_id)(adminId);

  // 3. Create initial section for the channel
  const sectionCreateReq: IShoppingMallAiBackendSection.ICreate = {
    code: RandomGenerator.alphaNumeric(6),
    name: "Initial Section",
    description: "Original description",
    display_order: 1,
    visible: true,
    channel_id: channel.id,
    created_by_admin_id: adminId,
  };
  const section = await api.functional.shoppingMallAiBackend.admin.channels.sections.createSection(connection, {
    channelId: channel.id,
    body: sectionCreateReq,
  });
  typia.assert(section);
  TestValidator.equals("created_by_admin_id in section matches")(section.created_by_admin_id)(adminId);
  TestValidator.equals("code is set correctly")(section.code)(sectionCreateReq.code);

  // 4. Update the section: update name, description, display_order, visible; attempt to set code - code should remain immutable
  const sectionUpdateReq: IShoppingMallAiBackendSection.IUpdate = {
    code: RandomGenerator.alphaNumeric(6), // Attempt to change code (should not update)
    name: "Updated Section Name",
    description: "Updated description",
    display_order: 2,
    visible: false,
  };
  const updatedSection = await api.functional.shoppingMallAiBackend.admin.channels.sections.updateSection(connection, {
    channelId: channel.id,
    sectionId: section.id,
    body: sectionUpdateReq,
  });
  typia.assert(updatedSection);

  // 5. Verify updated fields were changed, updated_at timestamp is updated
  TestValidator.equals("name updated") (updatedSection.name) (sectionUpdateReq.name);
  TestValidator.equals("description updated") (updatedSection.description) (sectionUpdateReq.description);
  TestValidator.equals("display_order updated") (updatedSection.display_order) (sectionUpdateReq.display_order);
  TestValidator.equals("visible updated") (updatedSection.visible) (sectionUpdateReq.visible);
  TestValidator.predicate("updated_at should be changed") (updatedSection.updated_at !== section.updated_at);

  // 6. Code should remain unchanged, enforcing immutability
  TestValidator.equals("code remains immutable") (updatedSection.code) (section.code);

  // 7. (Omitted) Audit log confirmation cannot be programmatically validated since no log API/field is exposed. If present, add appropriate retrieval/assertion here.
}

