import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendModerationEvent";
import type { IShoppingMallAiBackendAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAppeal";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate the creation of appeals by a seller against a moderation event and rejection of duplicates or unauthorized attempts.
 *
 * - Ensures a seller can successfully create an appeal for a moderation event they are involved in.
 * - Verifies the appeal is correctly linked to the seller and the target event; checks appeal metadata & audit fields.
 * - Attempts to create a duplicate appeal for the same event and expects error response.
 * - Validates that a seller cannot appeal an unrelated moderation event (not their own).
 *
 * Test Steps:
 * 1. Register and authenticate a seller; store ID for use as actor in moderation event and as appellant in appeal.
 * 2. Create a moderation event (with seller's ID as actor).
 * 3. Seller creates a valid appeal for that moderation event.
 * 4. Validate response fields: correct linkage to seller and event, metadata (status, created_at, updated_at).
 * 5. Attempt to create a second (duplicate) appeal for the same event and expect error.
 * 6. Register & authenticate another seller. Create another moderation event (with unrelated actor).
 * 7. First seller attempts to appeal unrelated event—expect error.
 */
export async function test_api_appeal_creation_valid_and_duplicate(connection: api.IConnection) {
  // 1. Register a seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "TestByE2E!1";
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: "1312312345",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerSignUp);
  const sellerId = sellerSignUp.sellerId;

  // Authenticate seller
  const sellerLogin = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    },
  });
  typia.assert(sellerLogin);

  // 2. Create moderation event linked to seller
  const modEvent = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
    body: {
      actor_id: sellerId,
      event_type: "block",
      target_review_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(modEvent);

  // 3. Seller creates an appeal for mod event
  const appealCreateBody = {
    moderation_event_id: modEvent.id,
    appellant_id: sellerId,
    status: "pending",
  } satisfies IShoppingMallAiBackendAppeal.ICreate;
  const appeal = await api.functional.shoppingMallAiBackend.seller.appeals.create(connection, {
    body: appealCreateBody,
  });
  typia.assert(appeal);

  // 4. Validate appeal links and audit fields
  TestValidator.equals("moderation_event_id")(appeal.moderation_event_id)(modEvent.id);
  TestValidator.equals("appellant_id")(appeal.appellant_id)(sellerId);
  TestValidator.equals("status")(appeal.status)("pending");
  TestValidator.predicate("created_at present")(!!appeal.created_at);
  TestValidator.predicate("updated_at present")(!!appeal.updated_at);

  // 5. Attempt second/duplicate appeal for same event
  await TestValidator.error("duplicate appeal rejected")(async () => {
    await api.functional.shoppingMallAiBackend.seller.appeals.create(connection, {
      body: appealCreateBody,
    });
  });

  // 6. Register another (unrelated) seller, create unrelated event
  const anotherEmail = typia.random<string & tags.Format<"email">>();
  const anotherPassword = "TestByE2E!2";
  const anotherSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: anotherEmail,
      password: anotherPassword,
      companyName: RandomGenerator.name(),
      businessNumber: "9876543210",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(anotherSignUp);
  const unrelatedId = anotherSignUp.sellerId;
  // Create event for unrelated seller
  const unrelatedEvent = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
    body: {
      actor_id: unrelatedId,
      event_type: "block",
      target_inquiry_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(unrelatedEvent);

  // 7. First seller tries to appeal unrelated event → error
  await TestValidator.error("appeal unrelated event rejected")(async () => {
    await api.functional.shoppingMallAiBackend.seller.appeals.create(connection, {
      body: {
        moderation_event_id: unrelatedEvent.id,
        appellant_id: sellerId,
        status: "pending",
      },
    });
  });
}

