import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSeller";
import type { IPageIShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSeller";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate admin seller search/pagination/filter/sort endpoint with multi-role permission enforcement.
 *
 * Goal:
 * - Admin can paginate, filter, and sort sellers by all supported options.
 * - Search by company name, status, join date, email verification, email, and business number.
 * - Pagination and correct sorting are accurate by result set and meta data.
 * - Non-admin users cannot access and are denied.
 * - Malformed filters, empty sets, invalid paging all produce robust error handling.
 *
 * Steps:
 * 1. Register admin and obtain admin privilege.
 * 2. Register at least two sellers with distinct attributes (companyName/status/verified).
 * 3. As admin, search: a) no filters b) company name filter (partial) c) status filter d) emailVerified filter e) registration range f) paging (limit/page) g) orderBy/orderDir.
 * 4. Validate for each: result is accurate, pagination metadata is correct, summary fields present and plausible.
 * 5. As seller (non-admin), attempt search and ensure permission denied.
 * 6. Pass invalid/malformed filters: e.g., unknown status value, bad date, limit=0/page<0 etc; test error handling without breaking.
 * 7. Use filters that return empty result.
 */
export async function test_api_admin_paginated_seller_search_with_filters(connection: api.IConnection) {
  // 1. Register a new admin and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);

  // 2. Register two sellers with distinct companies/status/email verified
  const seller1Email = typia.random<string & tags.Format<"email">>();
  const seller2Email = typia.random<string & tags.Format<"email">>();
  const companyName1 = RandomGenerator.alphabets(10);
  const companyName2 = RandomGenerator.alphabets(12);
  const businessNumber1 = RandomGenerator.alphaNumeric(10);
  const businessNumber2 = RandomGenerator.alphaNumeric(10);
  const seller1 = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller1Email,
      password: "Password123!",
      companyName: companyName1,
      businessNumber: businessNumber1,
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller1);
  const seller2 = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller2Email,
      password: "Password123!",
      companyName: companyName2,
      businessNumber: businessNumber2,
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller2);

  // 3. As admin, search all with no filters
  const allSellers = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: {},
  });
  typia.assert(allSellers);
  TestValidator.predicate("Both registered sellers present in admin search")(allSellers.data.some(s => s.email === seller1Email) && allSellers.data.some(s => s.email === seller2Email));
  TestValidator.predicate("Pagination meta available")(typeof allSellers.pagination.current === "number");

  // 4a. Partial company name search
  const filterResult = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: {
      company_name: companyName1.slice(0, 5),
    },
  });
  typia.assert(filterResult);
  TestValidator.predicate("Company name partial filter yields expected seller")(filterResult.data.every(s => s.company_name.includes(companyName1.slice(0, 5))));

  // 4b. Status filter - as registration is always initial (e.g. 'pending' or 'active' depending on impl), so use seller1's status
  if (allSellers.data.length > 0) {
    const knownStatus = allSellers.data[0].status;
    const statusFiltered = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
      body: { status: knownStatus },
    });
    typia.assert(statusFiltered);
    TestValidator.predicate("Status filter is respected")(statusFiltered.data.every(s => s.status === knownStatus));
  }

  // 4c. Email verified filter - check both options
  const filteredVerified = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: { email_verified: true },
  });
  typia.assert(filteredVerified);
  TestValidator.predicate("All returned sellers are email verified or empty")(filteredVerified.data.every(s => s.email_verified === true));
  const filteredUnverified = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: { email_verified: false },
  });
  typia.assert(filteredUnverified);
  TestValidator.predicate("All returned sellers are unverified or empty")(filteredUnverified.data.every(s => s.email_verified === false));

  // 4d. Joined registration window
  const now = new Date();
  const isoNow = now.toISOString();
  const veryOldPast = new Date(2000, 1, 1).toISOString();
  const fullRange = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: {
      joined_at_from: veryOldPast,
      joined_at_to: isoNow,
    }
  });
  typia.assert(fullRange);
  TestValidator.predicate("All results joined in window")(fullRange.data.every(s => s.joined_at >= veryOldPast && s.joined_at <= isoNow));

  // 4e. Email filter (partial and exact)
  const partialEmail = seller1Email.split("@")[0];
  const filteredByEmail = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: { email: partialEmail },
  });
  typia.assert(filteredByEmail);
  TestValidator.predicate("All results match email fragment")(filteredByEmail.data.every(s => s.email.includes(partialEmail)));

  // 4f. Business number filter
  const filteredByBusiness = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: { business_number: businessNumber1 },
  });
  typia.assert(filteredByBusiness);
  TestValidator.predicate("All results match business number")(filteredByBusiness.data.every(s => s.business_number === businessNumber1));

  // 4g. Pagination params (limit/page)
  const paged = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: {
      limit: 1,
      page: 1,
    },
  });
  typia.assert(paged);
  TestValidator.equals("Paged result limit")(paged.data.length)(1);

  // 4h. Order by company_name desc
  const ordered = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: {
      orderBy: "company_name",
      orderDir: "desc",
    },
  });
  typia.assert(ordered);
  if (ordered.data.length > 1) {
    TestValidator.predicate("Descending order by company name")(ordered.data.every((s, i, arr) => i == 0 || arr[i-1].company_name >= s.company_name));
  }

  // 5. Non-admin permission: use seller1's connection
  // Assume re-login as seller will swap connection credentials
  await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      companyName: RandomGenerator.alphabets(8),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  TestValidator.error("Seller (non-admin) is forbidden")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
        body: {},
      });
    }
  );

  // 6. Bad filter values
  TestValidator.error("Unknown status value")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
        body: {
          status: "not-a-status",
        },
      });
    }
  );
  TestValidator.error("Malformed date")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
        body: {
          joined_at_from: "not-a-date",
        },
      });
    }
  );
  TestValidator.error("Zero/negative limit")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
        body: {
          limit: 0,
        },
      });
    }
  );
  TestValidator.error("Negative page")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
        body: {
          page: -1,
        },
      });
    }
  );

  // 7. Filter that returns empty result
  const emptyResult = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: {
      company_name: "NO-COMPANY-WITH-THIS-NAME",
    },
  });
  typia.assert(emptyResult);
  TestValidator.equals("Empty data array for non-matching company")(emptyResult.data.length)(0);
}

