 * - Non-admin users cannot access and are denied.
 * - Malformed filters, empty sets, invalid paging all produce robust error handling.
 *
 * Steps:
 * 1. Register admin and obtain admin privilege.
 * 2. Register at least two sellers with distinct attributes.
 * 3. As admin, search: a) no filters b) company name c) status d) emailVerified e) registration window f) paging g) orderBy/orderDir.
 * 4. Validate each: correct results, pagination meta, valid summaries.
 * 5. As seller (non-admin), attempt search and ensure forbidden.
 * 6. Submit invalid/malformed filters for error behavior.
 * 7. Use filter that yields empty result.
 */
export async function test_api_admin_paginated_seller_search_with_filters(connection: api.IConnection) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);

  // 2. Register two sellers with different company names/business numbers
  const seller1Email = typia.random<string & tags.Format<"email">>();
  const seller2Email = typia.random<string & tags.Format<"email">>();
  const companyName1 = RandomGenerator.alphabets(10);
  const companyName2 = RandomGenerator.alphabets(12);
  const businessNumber1 = RandomGenerator.alphaNumeric(10);
  const businessNumber2 = RandomGenerator.alphaNumeric(10);
  const seller1 = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller1Email,
      password: "Password123!",
      companyName: companyName1,
      businessNumber: businessNumber1,
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller1);

  const seller2 = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller2Email,
      password: "Password123!",
      companyName: companyName2,
      businessNumber: businessNumber2,
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller2);

  // 3. Admin searches with no filters
  const allSellers = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: {},
  });
  typia.assert(allSellers);
  TestValidator.predicate("Both registered sellers present in admin search")(
    allSellers.data.some(s => s.email === seller1Email) &&
    allSellers.data.some(s => s.email === seller2Email)
  );
  TestValidator.predicate("Pagination meta available")(typeof allSellers.pagination.current === "number");

  // 4a. Partial company name search
  const filterResult = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: { company_name: companyName1.slice(0, 5) },
  });
  typia.assert(filterResult);
  TestValidator.predicate("All results contain company name fragment")(
    filterResult.data.every(s => s.company_name.includes(companyName1.slice(0, 5)))
  );

  // 4b. Status filter - using known value from seller summaries
  if (allSellers.data.length > 0) {
    const knownStatus = allSellers.data[0].status;
    const statusFiltered = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
      body: { status: knownStatus },
    });
    typia.assert(statusFiltered);
    TestValidator.predicate("Status filter is respected")(
      statusFiltered.data.every(s => s.status === knownStatus)
    );
  }

  // 4c. Email verified true/false
  {
    const filteredVerified = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
      body: { email_verified: true },
    });
    typia.assert(filteredVerified);
    TestValidator.predicate("All results are verified emails")(
      filteredVerified.data.every(s => s.email_verified === true)
    );
  }
  {
    const filteredUnverified = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
      body: { email_verified: false },
    });
    typia.assert(filteredUnverified);
    TestValidator.predicate("All results are unverified emails")(
      filteredUnverified.data.every(s => s.email_verified === false)
    );
  }

  // 4d. Registered join range (window)
  const now = new Date();
  const isoNow = now.toISOString();
  const ancient = new Date(2000, 1, 1).toISOString();
  const dateFiltered = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: { joined_at_from: ancient, joined_at_to: isoNow },
  });
  typia.assert(dateFiltered);
  TestValidator.predicate("All joined in date window")(
    dateFiltered.data.every(s => s.joined_at >= ancient && s.joined_at <= isoNow)
  );

  // 4e. Email partial search
  const fragment = seller1Email.split("@")[0];
  const emailFiltered = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: { email: fragment },
  });
  typia.assert(emailFiltered);
  TestValidator.predicate("Email partial filter matches")(
    emailFiltered.data.every(s => s.email.includes(fragment))
  );

  // 4f. Business number exact
  const businessFiltered = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: { business_number: businessNumber1 },
  });
  typia.assert(businessFiltered);
  TestValidator.predicate("Business number filter matches")(
    businessFiltered.data.every(s => s.business_number === businessNumber1)
  );

  // 4g. Pagination (limit/page)
  const paged = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: { limit: 1, page: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("Paging result to 1 record")(paged.data.length)(1);

  // 4h. Ordering by company name desc
  const ordered = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: { orderBy: "company_name", orderDir: "desc" },
  });
  typia.assert(ordered);
  if (ordered.data.length > 1) {
    TestValidator.predicate("Names sorted desc")(
      ordered.data.every((s, i, arr) => i === 0 || arr[i-1].company_name >= s.company_name)
    );
  }

  // 5. Non-admin user (new seller) should be forbidden
  await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      companyName: RandomGenerator.alphabets(8),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  TestValidator.error("Seller access is forbidden")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, { body: {} });
    }
  );

  // 6. Malformed filters/error handling
  TestValidator.error("Unknown status")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
        body: { status: "not-a-status" },
      });
    }
  );
  TestValidator.error("Bad date")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
        body: { joined_at_from: "bad-date" },
      });
    }
  );
  TestValidator.error("Zero limit")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
        body: { limit: 0 },
      });
    }
  );
  TestValidator.error("Negative page")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
        body: { page: -1 },
      });
    }
  );

  // 7. Empty result set when filtering non-existent company name
  const emptyResult = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: { company_name: "ZZZ-NO-MATCH-" },
  });
  typia.assert(emptyResult);
  TestValidator.equals("No sellers match for fake name")(emptyResult.data.length)(0);
}

