import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendModerationEvent";
import type { IShoppingMallAiBackendAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAppeal";
import type { IPageIShoppingMallAiBackendAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAppeal";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate paginated, filtered retrieval of appeal records by an admin.
 *
 * Tests that an admin can search and paginate appeals by filters such as status, appellant ID, decision comment, and date range. The workflow includes:
 *  1. Register and authenticate as admin (for audit-trail and permissions)
 *  2. Create multiple moderation events via the admin endpoint
 *  3. Submit several appeals by acting as customer (to provide data for admin search)
 *  4. As admin, perform a sequence of PATCH /shoppingMallAiBackend/admin/appeals requests with different filter criteria:
 *      - Filter by status (e.g., 'pending', 'approved')
 *      - Filter by appellant_id
 *      - Filter by text in decision_comment
 *      - Filter by date range (from_date, to_date)
 *      - Pagination tests (page, limit)
 *  5. Verify that each query only returns the correct/expected appeals and that result counts and paging meta are correct
 *  6. Check that audit trail and system compliance (recording of query action) take place (to the extent observable)
 */
export async function test_api_appeal_search_filtered_pagination(connection: api.IConnection) {
  // 1. Register admin (authenticate)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "P@ssw0rd123";
  const adminRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(adminRes);
  // The returned JWT sets Authorization automatically in connection.headers

  // 2. Create multiple moderation events
  const actorId = typia.random<string & tags.Format<"uuid">>(); // Stand-in for moderation actor
  const targetInquiryId = typia.random<string & tags.Format<"uuid">>();
  const events: IShoppingMallAiBackendModerationEvent[] = [];
  for (let i = 0; i < 3; ++i) {
    const ev = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
      body: {
        actor_id: actorId,
        event_type: i === 0 ? "block" : (i === 1 ? "warn" : "edit"),
        target_inquiry_id: i % 2 ? null : targetInquiryId,
        target_review_id: i % 2 ? typia.random<string & tags.Format<"uuid">>() : null,
        reason: i === 2 ? "Incorrectly flagged review" : null,
        attached_ai_evidence_id: null,
        referenced_event_id: null,
      }
    });
    typia.assert(ev);
    events.push(ev);
  }

  // 3. Submit appeals for these events (via customer)
  const appellantId = typia.random<string & tags.Format<"uuid">>();
  const appeals: IShoppingMallAiBackendAppeal[] = [];
  for (const [i, event] of events.entries()) {
    const statusArr = ["pending", "approved", "rejected"] as const;
    const status = statusArr[i % statusArr.length];
    const decision_comment = i === 1 ? "Admin rejected previous block" : null;
    const appeal = await api.functional.shoppingMallAiBackend.customer.appeals.create(connection, {
      body: {
        moderation_event_id: event.id,
        appellant_id: appellantId,
        status,
        decision_comment,
      }
    });
    typia.assert(appeal);
    appeals.push(appeal);
  }

  // 4. Perform various filtered admin searches - by status, appellant_id, comment, date, pagination

  // (a) Filter by status
  for (const status of ["pending", "approved", "rejected"]) {
    const res = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, { body: { status } });
    typia.assert(res);
    TestValidator.predicate(`All appeals have status = ${status}`)(res.data.every(a => a.status === status));
  }

  // (b) Filter by appellant_id
  const resByAppellant = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, { body: { appellant_id: appellantId } });
  typia.assert(resByAppellant);
  TestValidator.predicate("All appeals belong to appellant_id")(resByAppellant.data.every(a => a.appellant_id === appellantId));

  // (c) Filter by decision_comment substring
  const commentSubstring = "rejected";
  const resByComment = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, { body: { decision_comment: commentSubstring } });
  typia.assert(resByComment);
  TestValidator.predicate(`All appeals with decision_comment containing '${commentSubstring}'`)(
    resByComment.data.every(a => a.decision_comment && a.decision_comment.includes(commentSubstring))
  );

  // (d) Filter by date range
  const fromDate = new Date(Date.now() - 86400000).toISOString();
  const toDate = new Date(Date.now() + 86400000).toISOString();
  const resByDate = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, { body: { from_date: fromDate, to_date: toDate } });
  typia.assert(resByDate);
  TestValidator.predicate("All appeals in date range")(resByDate.data.every(a => a.created_at >= fromDate && a.created_at <= toDate));

  // (e) Pagination: limit to 2 per page and check that paging meta/logic work
  const paged1 = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, { body: { page: 1, limit: 2 } });
  typia.assert(paged1);
  TestValidator.equals("limit == 2")(paged1.pagination.limit)(2);
  TestValidator.equals("page = 1")(paged1.pagination.current)(1);

  if (paged1.pagination.pages > 1) {
    const paged2 = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, { body: { page: 2, limit: 2 } });
    typia.assert(paged2);
    TestValidator.equals("limit == 2")(paged2.pagination.limit)(2);
    TestValidator.equals("page = 2")(paged2.pagination.current)(2);
  }

  // 5. Confirm (indirectly) audit logging: Not directly observable here, but registering/admin workflow implies audit.
}

