import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate customer order item list retrieval with pagination and filtering.
 *
 * This scenario tests the ability for a customer to:
 * 1. Log in and acquire a session (auth).
 * 2. Create an order as their own customer entity.
 * 3. Add multiple (3+) items to that order (distinct products/snapshots/prices).
 * 4. Retrieve the list of all items for that order using PATCH
 *    a. Confirm all created items are listed when pagination covers them
 *    b. Confirm page-limited responses respect "page" and "pageSize"
 *    c. Filter by product_id and confirm correct item(s) returned
 *    d. Validate access control (only able to access own order's items)
 * 5. Type and business rule validations on all responses.
 */
export async function test_api_order_item_list_by_customer(connection: api.IConnection) {
  // 1. Log in as customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "1qaz2wsx!";
  // (User is presumed to exist in this seed environment, or create one if sign-up supported)
  const signIn = await api.functional.auth.customer.login.signIn(connection, {
    body: { email, password } satisfies ICustomerSignIn.Request,
  });
  typia.assert(signIn);
  // Set Authorization header
  connection.headers = { ...connection.headers, Authorization: signIn.setHeaders.Authorization };

  // 2. Create an order for this customer
  const orderCreate: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: signIn.customer.id,
    order_group_id: null,
    order_number: RandomGenerator.alphaNumeric(10),
    total_amount: 0,
    currency_code: 'KRW',
    note: null,
    current_status: "created",
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderCreate });
  typia.assert(order);
  // Collect created item info for assertion
  const createdItems: IShoppingMallAiBackendOrderItem[] = [];

  // 3. Add multiple items to this order
  for (let i = 0; i < 5; ++i) {
    // Simulate different products for filtering
    const product_id = typia.random<string & tags.Format<"uuid">>();
    const itemCreate: IShoppingMallAiBackendOrderItem.ICreate = {
      order_id: order.id,
      product_id,
      product_snapshot_id: typia.random<string & tags.Format<"uuid">>(),
      quantity: 1,
      unit_price: 10000 + i * 1000,
      currency_code: 'KRW',
      note: i % 2 ? RandomGenerator.paragraph()(1) : null
    };
    const item = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.create(connection, { orderId: order.id, body: itemCreate });
    typia.assert(item);
    createdItems.push(item);
  }

  // 4a. Retrieve all items without filtering (page large enough)
  const allItems = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.index(connection, {
    orderId: order.id,
    body: { order_id: order.id, page: 1, pageSize: 10 } satisfies IShoppingMallAiBackendOrderItem.IRequest,
  });
  typia.assert(allItems);
  TestValidator.equals("all items count")(allItems.data.length)(createdItems.length);
  // Validate returned items match what was created
  for (const item of createdItems) {
    const match = allItems.data.find(i => i.id === item.id);
    TestValidator.predicate("item returned")(!!match);
    if (match) TestValidator.equals("item fields")(match.product_id)(item.product_id);
  }

  // 4b. Pagination
  const page2 = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.index(connection, {
    orderId: order.id,
    body: { order_id: order.id, page: 2, pageSize: 2 } satisfies IShoppingMallAiBackendOrderItem.IRequest,
