    body: {
      channel_id: channelA.id,
      category_id: categoryY.id,
    } satisfies IShoppingMallAiBackendChannelCategoryMap.ICreate,
  });
  typia.assert(mappingAY);

  const mappingBX = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.createChannelCategoryMap(connection, {
    body: {
      channel_id: channelB.id,
      category_id: categoryX.id,
    } satisfies IShoppingMallAiBackendChannelCategoryMap.ICreate,
  });
  typia.assert(mappingBX);

  // 5a. Filter by channel_id = channelA.id
  let search = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.searchChannelCategoryMap(connection, {
    body: { channel_id: channelA.id } satisfies IShoppingMallAiBackendChannelCategoryMap.IRequest,
  });
  typia.assert(search);
  TestValidator.predicate("all mappings are for channel A")(search.data.every(m => m.channel_id === channelA.id));

  // 5b. Filter by category_id = categoryX.id
  search = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.searchChannelCategoryMap(connection, {
    body: { category_id: categoryX.id } satisfies IShoppingMallAiBackendChannelCategoryMap.IRequest,
  });
  typia.assert(search);
  TestValidator.predicate("all mappings are for category X")(search.data.every(m => m.category_id === categoryX.id));

  // 5c. active=true
  search = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.searchChannelCategoryMap(connection, {
    body: { active: true } satisfies IShoppingMallAiBackendChannelCategoryMap.IRequest,
  });
  typia.assert(search);
  TestValidator.predicate("all mappings are active")(search.data.every(m => !m.deleted_at));

  // 5d. active=false (should be none unless a mapping got deleted)
  search = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.searchChannelCategoryMap(connection, {
    body: { active: false } satisfies IShoppingMallAiBackendChannelCategoryMap.IRequest,
  });
  typia.assert(search);
  TestValidator.predicate("no mapping is active")(search.data.length === 0);

  // 5e. channel_id=A, active=true
  search = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.searchChannelCategoryMap(connection, {
    body: { channel_id: channelA.id, active: true } satisfies IShoppingMallAiBackendChannelCategoryMap.IRequest,
  });
  typia.assert(search);
  TestValidator.predicate("mapping for channel A and active")(search.data.every(m => m.channel_id === channelA.id && !m.deleted_at));

  // 5f. Pagination test - page=2, pageSize=1, active=true
  search = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.searchChannelCategoryMap(connection, {
    body: { active: true, page: 2, pageSize: 1 } satisfies IShoppingMallAiBackendChannelCategoryMap.IRequest,
  });
  typia.assert(search);
  TestValidator.equals("pagination info: page 2")(search.pagination.current)(2);
  TestValidator.equals("limit per page")(search.pagination.limit)(1);

  // 6. All returned mappings have channel/category ids, proper audit timestamps.
  TestValidator.predicate("all have channel/category and audit fields")(search.data.every(m => m.channel_id && m.category_id && m.created_at && m.updated_at));
}

