 * Validate advanced product inquiry search for seller context.
 *
 * The seller must only see product inquiries for their products, filtered by various criteria (product_id, keywords, public/private, AI scores, date, status). Unowned product searches must be rejected or show zero results. Pagination, sorting, and access control are all verified.
 *
 * Steps:
 * 1. Register a new seller (so all products will belong to this seller)
 * 2. Simulate two products (UUIDs) 'owned' by this seller
 * 3. Register a customer (simulate, since customer auth is out of scope)
 * 4. The customer creates several product inquiries for each product and some for unrelated (fake) products
 * 5. As the seller, search for product inquiries:
 *   a. Filter by owned product1 — should return only relevant results
 *   b. Filter by owned product2 — should return only relevant results
 *   c. Use search keyword filter (title/body terms)
 *   d. Use AI threshold filter (min_ai_sentiment_score/max_ai_sentiment_score)
 *   e. Use "public" filters, date range, status, pagination, and sorting
 *   f. Try to search for a product the seller does not own (should yield error or empty)
 *   g. Try unauthorized filters (such as customer_id filter)—should be rejected with error
 *   h. Confirm result fields, ordering, and data integrity
 */
export async function test_api_product_inquiry_advanced_filter_search_seller(connection: api.IConnection) {
  // 1. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const signUpBody: ISellerAuth.SignUp = {
    email: sellerEmail,
    password: "Password123!",
    companyName: RandomGenerator.alphabets(8) + " Inc.",
    businessNumber: ArrayUtil.repeat(10)(() => String(typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<9>>())).join(""),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(10),
    phone: RandomGenerator.mobile()
  };
  const sellerResp = await api.functional.auth.seller.register.signUp(connection, { body: signUpBody });
  typia.assert(sellerResp);
  connection.headers = { ...(connection.headers ?? {}), Authorization: sellerResp.setHeaders.Authorization };
  const sellerProduct1 = typia.random<string & tags.Format<"uuid">>();
  const sellerProduct2 = typia.random<string & tags.Format<"uuid">>();

  // 2. Register a customer and simulate their UUID
  const customerId = typia.random<string & tags.Format<"uuid">>();

  // 3. Customer submits multiple inquiries for both seller products, some public and some private
  const inquiries = await ArrayUtil.asyncRepeat(5)(async (_, i) =>
    await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
      body: {
        customer_id: customerId,
        product_id: i < 3 ? sellerProduct1 : sellerProduct2,
        title: `Inquiry Title ${i}`,
        body: `Details about inquiry ${i} for product`,
        public: i % 2 === 0
      }
    })
  );
  const unrelatedProductId = typia.random<string & tags.Format<"uuid">>();
  await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: unrelatedProductId,
      title: "Unrelated Inquiry",
      body: "This product does not belong to the seller.",
      public: true
    }
  });

