  const resActorType = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { actor_type: null }
  });
  typia.assert(resActorType);

  // 6. Filter by a real and non-existent actor_id
  const realActorId = actors[0];
  const resActor = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { actor_id: realActorId }
  });
  typia.assert(resActor);
  TestValidator.predicate("actor_id result matches only actor")(
    resActor.data.every(ev => ev.actor_id === realActorId)
  );
  const resFakeActor = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { actor_id: typia.random<string & tags.Format<'uuid'>>() }
  });
  typia.assert(resFakeActor);
  TestValidator.equals("fake actor_id yields empty")(resFakeActor.data.length)(0);

  // 7. Filter by review/inquiry
  const resReview = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { target_review_id: targetReviewIds[1] }
  });
  typia.assert(resReview);
  TestValidator.predicate("review filter matches")(
    resReview.data.every(ev => ev.target_review_id === targetReviewIds[1])
  );
  const resInquiry = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { target_inquiry_id: targetInquiryIds[0] }
  });
  typia.assert(resInquiry);
  TestValidator.predicate("inquiry filter matches")(
    resInquiry.data.every(ev => ev.target_inquiry_id === targetInquiryIds[0])
  );

  // 8. Filter by reason (partial match, as system may match substrings, but here we require full match for assertion)
  const reasonQuery = reasons[0];
  const resReason = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { reason: reasonQuery }
  });
  typia.assert(resReason);
  TestValidator.predicate("reason filter matches")(
    resReason.data.every(ev => ev.reason === reasonQuery)
  );

  // 9. Date-range: filter from baseDate - 5 days to baseDate inclusive
  const fromDate = new Date(baseDate.getTime() - 5 * 86400000).toISOString();
  const toDate = baseDate.toISOString();
  const resDateRange = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: {
      from_date: fromDate,
      to_date: toDate
    }
  });
  typia.assert(resDateRange);
  TestValidator.predicate("date-range results in correct window")(
    resDateRange.data.every(ev => ev.created_at >= fromDate && ev.created_at <= toDate)
  );

  // 10. Paginate with limit (page size)
  const resPaginate = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: {
      page: 1,
      limit: 5
    }
  });
  typia.assert(resPaginate);
  TestValidator.equals("pagination matches page size")(resPaginate.data.length)(5);
  TestValidator.equals("pagination meta limit")(resPaginate.pagination.limit)(5);
  TestValidator.equals("pagination meta page")(resPaginate.pagination.current)(1);

  // 11. Edge: Search with non-existent criteria yields empty
  const resNone = await api.functional.shoppingMallAiBackend.admin.moderationEvents.search(connection, {
    body: { event_type: "___NON_EXISTENT___" }
  });
  typia.assert(resNone);
  TestValidator.equals("non-existent filter yields empty")(resNone.data.length)(0);

  // 12. All responses are paginated and only permissible admin-level data returns (type assertions done above)
}

