  // 3. Create a favorite snapshot (type PRODUCT, serialize favorite product as JSON string)
  const serializedObject = JSON.stringify(favorite);
  const snapshot = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: {
      favorite_product_id: favorite.id,
      favorite_inquiry_id: null,
      favorite_address_id: null,
      target_type: "PRODUCT",
      snapshot_object_id: productId,
      serialized_object: serializedObject
    } satisfies IShoppingMallAiBackendFavoriteSnapshot.ICreate
  });
  typia.assert(snapshot);

