import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IPageIShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductInquiry";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for admin's advanced filter and search functionality over product inquiries.
 *
 * - Registers an admin to obtain authorization for privileged search.
 * - Creates several product inquiries as different customers with varied statuses, public/private settings, AI sentiment/spam scores, and titles/bodies for coverage.
 * - Tests system-wide search as admin via /shoppingMallAiBackend/admin/productInquiries (PATCH).
 * - Validates support for all filterable fields: status (e.g., 'waiting', 'answered', 'blocked'), public/private, product_id, customer_id, AI moderation thresholds, search keyword, date windows, etc.
 * - Verifies pagination delivers distinct, deterministic results and supports sort_by/sort_order.
 * - Checks invalid/malformed filter cases result in error responses (e.g., invalid status, out-of-range dates, illegal page value).
 * - Ensures the search response contains inquiries matching the search criteria and verifies auditability by asserting that queries are accepted and structured as expected.
 */
export async function test_api_product_inquiry_advanced_filter_search_admin(connection: api.IConnection) {
  // 1. Register an admin user and set up authenticated connection for admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'A1strongPW!';
  const adminResult = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminResult);

  // 2. Prepare inquiry dataset with different combinations for multiple products/customers/statuses
  const customerAId = typia.random<string & tags.Format<'uuid'>>();
  const productAId = typia.random<string & tags.Format<'uuid'>>();
  const productBId = typia.random<string & tags.Format<'uuid'>>();

  // Make inquiries for product A and B by customer A
  const inquiryWaiting = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerAId,
      product_id: productAId,
      title: "How long is delivery?",
      body: "Could you please estimate shipping time for product A?",
      public: true,
    },
  });
  typia.assert(inquiryWaiting);

  const inquiryAnswered = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerAId,
      product_id: productBId,
      title: "Is product B eco-friendly?",
      body: "I want to check material source and green certification for B.",
      public: false,
    },
  });
  typia.assert(inquiryAnswered);

  // Another customer & mixed public/private
  const customerBId = typia.random<string & tags.Format<'uuid'>>();
  const inquiryBlocked = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerBId,
      product_id: productAId,
      title: "Blocked post sample",
      body: "This content should be blocked by admin.",
      public: false,
    },
  });
  typia.assert(inquiryBlocked);

  // 3. System-wide search as admin: all inquiries, various filters
  // (a) Simple filter: status, product_id, public
  const searchRes1 = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      product_id: productAId,
      status: inquiryWaiting.status,
      public: true,
      page: 1,
      page_size: 10,
      sort_by: "created_at",
      sort_order: "desc",
    },
  });
  typia.assert(searchRes1);
  TestValidator.predicate("filter status/product_id/public finds correct inquiry")(searchRes1.data.some(d => d.id === inquiryWaiting.id));

  // (b) Filter by customer_id, private
  const searchRes2 = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      customer_id: customerAId,
      public: false,
      search: "eco-friendly",
      page: 1,
      page_size: 5,
      sort_by: "title",
      sort_order: "asc",
    },
  });
  typia.assert(searchRes2);
  TestValidator.predicate("keyword-based search for private")(searchRes2.data.some(d => d.id === inquiryAnswered.id));

  // (c) Pagination deterministic results
  const pageSize = 1;
  const paged1 = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      page: 1,
      page_size: pageSize,
      sort_by: "created_at",
      sort_order: "asc",
    },
  });
  const paged2 = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      page: 2,
      page_size: pageSize,
      sort_by: "created_at",
      sort_order: "asc",
    },
  });
  typia.assert(paged1);
  typia.assert(paged2);
  TestValidator.notEquals("pagination delivers different results")(paged1.data[0]?.id)(paged2.data[0]?.id);

  // (d) Date window filter
  const createdFrom = new Date(Date.now() - 1000 * 60 * 10).toISOString();
  const createdTo = new Date(Date.now() + 1000 * 60 * 10).toISOString();
  const searchResDate = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      created_from: createdFrom,
      created_to: createdTo,
      page: 1,
      page_size: 10,
    },
  });
  typia.assert(searchResDate);
  TestValidator.predicate("date window returns data")(searchResDate.data.length > 0);

  // (e) AI sentiment filter
  const searchResAi = await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
    body: {
      min_ai_sentiment_score: -1,
      max_ai_sentiment_score: 1,
      page: 1,
      page_size: 10,
    },
  });
  typia.assert(searchResAi);
  TestValidator.predicate("AI score search covers data")(searchResAi.data.length > 0);

  // (f) Edge: illegal status filter triggers error
  await TestValidator.error("illegal status filter")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
      body: {
        status: "$illegal_status$",
        page: 1,
        page_size: 2,
      },
    });
  });

  // (g) Edge: invalid page
  await TestValidator.error("negative page value rejected")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.search(connection, {
      body: {
        page: -1,
        page_size: 10,
      },
    });
  });
}

