import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerAddress";
import type { IPageIShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerAddress";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validate customer self-address search, filtering, and privacy enforcement.
 *
 * This test simulates a real end-user scenario in a shopping mall backend, where a logged-in customer manages and queries their own delivery addresses using advanced filters and pagination, while enforcing strict privacy (no cross-customer data access).
 *
 * Business and test flow:
 * 1. Register a new customer (using unique randomized email/phone).
 * 2. Immediately log in using the registered credentials to obtain a valid JWT/Authorization session.
 * 3. Create multiple addresses for the logged-in customer, mixing values for alias, city, is_primary, etc.
 * 4. Query the customer's address book with no filter to fetch all addresses (paginated, page 1, limit 10), and verify the result includes all and only the customer's own addresses.
 * 5. Query using filter(s) (alias partial, city, is_primary true/false) and check the result matches the expected subset of created addresses.
 * 6. Query with pagination (smaller limit), verify the correct subset and pagination metadata are returned.
 * 7. Attempt to fetch addresses using a different (unauthorized/invalid) customerId and confirm that the query is denied or returns no information (privacy protected, error thrown).
 * 8. Try common error edge cases: missing/invalid filter, unauthorized session, and verify appropriate error responses (error is thrown, not successful response).
 */
export async function test_api_customer_self_search_addresses_and_privacy(connection: api.IConnection) {
  // 1. Register customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "Abc123!@#";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  const customer = customerSignUp.customer;
  const customerId = customer.id;

  // 2. Login immediately with new account
  const customerSignIn = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies ICustomerSignIn.Request,
  });
  typia.assert(customerSignIn);

  // 3. Create several addresses for the logged-in customer
  const createdAddresses: IShoppingMallAiBackendCustomerAddress[] = [];
  for (let i = 0; i < 4; ++i) {
    const isPrimary = i === 0; // First is primary
    const alias = ["Home", "Office", "Parents", null][i];
    const city = ["Seoul", "Busan", "Incheon", "Daegu"][i];
    const address = await api.functional.shoppingMallAiBackend.customer.customers.addresses.putByCustomerid(connection, {
      customerId,
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        receiver_name: RandomGenerator.name(),
        receiver_phone: RandomGenerator.mobile(),
        postal_code: String(10000 + i),
        address_line1: RandomGenerator.paragraph()(8),
        address_line2: i % 2 === 0 ? null : RandomGenerator.alphaNumeric(5),
        city,
        state: "Seoul",
        country: "KR",
        is_primary: isPrimary,
        alias,
      } satisfies IShoppingMallAiBackendCustomerAddress.IUpdate,
    });
    typia.assert(address);
    createdAddresses.push(address);
  }

  // 4. Query: fetch all addresses with no filter
  const searchAll = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
    customerId,
    body: {
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(searchAll);
  TestValidator.equals("address count")(searchAll.data.length)(createdAddresses.length);
  for (const addr of searchAll.data) {
    TestValidator.equals("customer linkage")(addr.customer_id)(customerId);
  }

  // 5. Query: filter by alias partial match
  const aliasSubset = createdAddresses.filter(a => a.alias && String(a.alias).includes("Home"));
  const searchAlias = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
    customerId,
    body: { alias: "Home" } satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(searchAlias);
  TestValidator.equals("filter by alias")(searchAlias.data.length)(aliasSubset.length);
  for (const addr of searchAlias.data) TestValidator.equals("alias contains")(String(addr.alias).includes("Home"))(true);

  // 6. Query: filter by city
  const searchCity = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
    customerId,
    body: { city: "Busan" } satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(searchCity);
  TestValidator.equals("filter city count")(searchCity.data.length)(createdAddresses.filter(a => a.city === "Busan").length);

  // 7. Query: filter primary only
  const searchPrimary = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
    customerId,
    body: { is_primary: true } satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(searchPrimary);
  TestValidator.equals("primary only")(searchPrimary.data.length)(1);
  for (const addr of searchPrimary.data) TestValidator.equals("is primary")(addr.is_primary)(true);

  // 8. Query: pagination (limit = 2, page 2)
  const searchPaginated = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
    customerId,
    body: { page: 2, limit: 2 } satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(searchPaginated);
  TestValidator.equals("pagination subset")(searchPaginated.pagination.current)(2);
  TestValidator.equals("pagination limit")(searchPaginated.data.length)(2);

  // 9. Privacy: Query as another customer (should fail or return no data)
  const otherSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Qwerty1234!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(otherSignUp);
  const otherCustomer = otherSignUp.customer;
  const otherSignIn = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: otherCustomer.email,
      password: "Qwerty1234!",
    } satisfies ICustomerSignIn.Request,
  });
  typia.assert(otherSignIn);

  TestValidator.error("privacy breach forbidden")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
      customerId,
      body: {} as IShoppingMallAiBackendCustomerAddress.IRequest,
    });
  });

  // 10. Invalid customerId (random non-existent UUID)
  const fakeCustomerId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("invalid customerId should fail")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
      customerId: fakeCustomerId,
      body: {} as IShoppingMallAiBackendCustomerAddress.IRequest,
    });
  });
}

