import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import type { IShoppingMallAiBackendReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendReviewSnapshot";
import type { IPageIShoppingMallAiBackendReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendReviewSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * E2E – Customer Review Snapshot Pagination & Filtering
 *
 * This test validates that a customer can retrieve paginated, filterable audit history (snapshots) of their own product review. It performs all business preconditions: customer registration, review creation, several updates (triggers review snapshots), and then exercises snapshot search with various filters and pagination, checking integrity each time.
 *
 * Steps:
 * 1. Register a new customer.
 * 2. As that customer, create a product review for a purchased product/order item.
 * 3. Update the review several times (to create multiple snapshots with different timestamps, status, ratings).
 * 4. Retrieve the snapshot list for the review with:
 *    - No filter (all snapshots, all fields, default sort/pagination)
 *    - Pagination: page=1, limit=2 (check snapshot counts)
 *    - Filtering: by rating, status, actor_id (should only show matches)
 *    - Filtering: by changed_at_from/to (date/time range: narrow to 1 update)
 *    - Ensure all returned snapshots match search criteria and pagination metadata is correct
 * 5. Optionally, check out-of-range page (should return empty or expected behavior).
 *
 * This validates both evidence chain integrity and review history user feature.
 */
export async function test_api_customer_review_snapshot_history_pagination_and_filtering(connection: api.IConnection) {
  // Step 1: Register customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "Test1234@" + typia.random<string>();
  const signUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile()
    }
  });
  typia.assert(signUpResponse);

  const customer = signUpResponse.customer;
  // connection.headers.Authorization now contains JWT for this customer.

  // Step 2: Create a review (simulate a purchased product/order item, using random UUIDs)
  const product_id = typia.random<string & tags.Format<"uuid">>();
  const order_item_id = typia.random<string & tags.Format<"uuid">>();
  const initialReview = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id,
      order_item_id,
      title: "Great Product!",
      body: "This is my honest review.",
      rating: 5,
      status: "normal"
    }
  });
  typia.assert(initialReview);
  const productReviewId = initialReview.id;

  // Step 3: Update the review several times (different ratings/status)
  await api.functional.shoppingMallAiBackend.customer.productReviews.update(connection, {
    productReviewId,
    body: { title: "Updated once", body: "Edit 1", rating: 4, status: "normal" }
  });
  // Second update (change rating and status)
  await api.functional.shoppingMallAiBackend.customer.productReviews.update(connection, {
    productReviewId,
    body: { title: "Second edit", body: "Edit 2", rating: 2, status: "blocked" }
  });
  // Third update (change again)
  await api.functional.shoppingMallAiBackend.customer.productReviews.update(connection, {
    productReviewId,
    body: { title: "Final edit", body: "Edit 3", rating: 3, status: "normal" }
  });

  // Step 4a: Retrieve all snapshots
  let result = await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.search(connection, {
    productReviewId,
    body: { review_id: productReviewId }
  });
  typia.assert(result);
  TestValidator.predicate("at least 4 snapshots expected")(result.data.length >= 4);
  for (const item of result.data) {
    TestValidator.equals("review_id matches")(item.review_id)(productReviewId);
  }

  // Step 4b: Pagination limit=2
  const paginateResult = await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.search(connection, {
    productReviewId,
    body: { review_id: productReviewId, page: 1, limit: 2 }
  });
  typia.assert(paginateResult);
  TestValidator.equals("pagination limit respected")(paginateResult.data.length)(2);
  TestValidator.equals("pagination meta reflects limit")(paginateResult.pagination.limit)(2);

  // Step 4c: Filter by rating=2 & status="blocked"
  const filterResult = await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.search(connection, {
    productReviewId,
    body: { review_id: productReviewId, rating: 2, status: "blocked" }
  });
  typia.assert(filterResult);
  for (const item of filterResult.data) {
    TestValidator.equals("review_id matches")(item.review_id)(productReviewId);
    TestValidator.equals("rating matches")(item.rating)(2);
    TestValidator.equals("status matches")(item.status)("blocked");
  }

  // Step 4d: Filter by actor_id (should only be customer.id)
  const actorIdResult = await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.search(connection, {
    productReviewId,
    body: { review_id: productReviewId, actor_id: customer.id }
  });
  typia.assert(actorIdResult);
  for (const item of actorIdResult.data) {
    TestValidator.equals("actor matches")(item.actor_id)(customer.id);
  }

  // Step 4e: Filter for narrow changed_at window (use changed_at from any known snapshot)
  if (result.data.length > 2) {
    const targetSnapshot = result.data[2];
    const timeStart = targetSnapshot.changed_at;
    const timeEnd = targetSnapshot.changed_at;
    const dateFilterResult = await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.search(connection, {
      productReviewId,
      body: {
        review_id: productReviewId,
        changed_at_from: timeStart,
        changed_at_to: timeEnd
      }
    });
    typia.assert(dateFilterResult);
    for (const item of dateFilterResult.data) {
      TestValidator.equals("in date window")(item.changed_at)(timeStart);
    }
  }

  // Step 5: Pagination out-of-range
  const outOfRangeResult = await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.search(connection, {
    productReviewId,
    body: { review_id: productReviewId, page: 99 }
  });
  typia.assert(outOfRangeResult);
  TestValidator.equals("empty on out-of-bounds page")(outOfRangeResult.data.length)(0);
}

