import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteProduct";
import type { IShoppingMallAiBackendFavoriteSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteSnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that attempting to update immutable or disallowed fields of a favorite snapshot
 * via the admin API results in validation error.
 *
 * This test ensures the API enforces immutability by rejecting updates that try to modify
 * properties other than the allowed 'serialized_object'. Attempts to change properties
 * such as 'id', 'favorite_product_id', 'favorite_inquiry_id', 'favorite_address_id',
 * 'target_type', 'snapshot_object_id', or 'created_at' must be rejected.
 *
 * Workflow:
 * 1. Register a customer and receive authentication
 * 2. Customer creates a favorite product (requires random product_id)
 * 3. Customer creates a favorite snapshot for this product
 * 4. Attempt to update the favorite snapshot as admin, sending a payload that includes both:
 *    - a valid update (changing 'serialized_object')
 *    - invalid updates to immutable/disallowed properties ('id', 'target_type', etc)
 * 5. Assert the API rejects the update request (400/422), and error states which fields are invalid
 */
export async function test_api_favorite_snapshot_update_invalid_fields_rejected(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const signUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "testPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(signUpResponse);

  // 2. Favorite a product for this customer
  const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>()
    },
  });
  typia.assert(favoriteProduct);

  // 3. Create a favorite snapshot record
  const snapshot = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: {
      favorite_product_id: favoriteProduct.id,
      favorite_inquiry_id: null,
      favorite_address_id: null,
      target_type: "PRODUCT",
      snapshot_object_id: favoriteProduct.product_id,
      serialized_object: JSON.stringify({ foo: "bar" }),
    },
  });
  typia.assert(snapshot);

  // 4. Attempt to update the snapshot, sending both allowed and illegal fields
  // Only 'serialized_object' can be updated; others are immutable/invalid for update
  // We'll pass extra fields in 'body' to simulate illegal update
