/**
 * Test a successful update to an existing order item by an admin user.
 *
 * Business context:
 * - Validates that an admin can modify an order item (editable fields: quantity and note) after item creation.
 * - Ensures all workflow prerequisites are done: admin registration/login, order and item creation.
 * - The update must be reflected in the returned entity and should be fully auditable.
 *
 * Steps:
 * 1. Register a new admin (and authenticate, loads Authorization header)
 * 2. Create a customer order using valid business/order info
 * 3. Add an item to the order
 * 4. As admin, update either the quantity or note of the order item
 * 5. Verify that the update response contains the expected changes
 * 6. Confirm audit-equivalent fields (updated_at) reflects modification
 * 7. Optionally, test that unchanged fields remain intact
 */
export async function test_api_admin_update_order_item_success(connection: api.IConnection) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongP@ssw0rd";
  const adminProfile = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminProfile);

  // 2. Create new order as customer (bypass - direct call as backend)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const orderBody: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customerId,
    order_group_id: null,
    order_number: RandomGenerator.alphaNumeric(12),
    total_amount: 0,
    currency_code: "USD",
    note: null,
    current_status: "created",
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: orderBody,
  });
  typia.assert(order);

  // 3. Add item to the created order
  const productId = typia.random<string & tags.Format<"uuid">>();
  const productSnapshotId = typia.random<string & tags.Format<"uuid">>();
  const orderItemBody: IShoppingMallAiBackendOrderItem.ICreate = {
    order_id: order.id,
    product_id: productId,
    product_snapshot_id: productSnapshotId,
    quantity: 2,
    unit_price: 100.0,
    currency_code: "USD",
    note: null,
  };
  const orderItem = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.create(connection, {
    orderId: order.id,
    body: orderItemBody,
  });
  typia.assert(orderItem);

  // 4. Update the order item as admin
  const updatedQuantity = orderItem.quantity + 1;
  const updatedNote = "Changed by admin for compliance reason";
  const orderItemUpdated = await api.functional.shoppingMallAiBackend.admin.orders.orderItems.update(connection, {
    orderId: order.id,
    orderItemId: orderItem.id,
    body: {
      quantity: updatedQuantity,
      note: updatedNote,
    },
  });
  typia.assert(orderItemUpdated);

  // 5. Validate changed fields
  TestValidator.equals("quantity updated")(
    orderItemUpdated.quantity
  )(
    updatedQuantity
  );
  TestValidator.equals("note updated")(
    orderItemUpdated.note
  )(
    updatedNote
  );

  // 6. Confirm 'updated_at' is changed
  TestValidator.predicate("updated_at changed")(
    orderItemUpdated.updated_at !== orderItem.updated_at
  );
  // 7. Unchanged fields remain the same
  TestValidator.equals("order_id unchanged")(orderItemUpdated.order_id)(orderItem.order_id);
  TestValidator.equals("product_id unchanged")(orderItemUpdated.product_id)(orderItem.product_id);
  TestValidator.equals("unit_price unchanged")(orderItemUpdated.unit_price)(orderItem.unit_price);
  TestValidator.equals("currency_code unchanged")(orderItemUpdated.currency_code)(orderItem.currency_code);
}

