  TestValidator.equals("updated body")(updated_inquiry.body)(updated_fields.body);
  TestValidator.equals("public updated")(updated_inquiry.public)(updated_fields.public);
  TestValidator.equals("status updated")(updated_inquiry.status)(updated_fields.status);
  TestValidator.equals("customer invariant")(updated_inquiry.customer_id)(inquiry.customer_id);
  TestValidator.equals("product invariant")(updated_inquiry.product_id)(inquiry.product_id);
