/**
 * Validate edge-case deletion of mileage transactions.
 *
 * This test ensures that the mileage transaction deletion endpoint behaves correctly in the following edge scenarios:
 *  - Attempting to delete a non-existent transaction
 *  - Attempting to delete a transaction that belongs to a different customer (ownership violation)
 *
 * The API must return appropriate error responses (not found, permission denied) and not alter system data for such attempts.
 *
 * Steps:
 * 1. Register two distinct customers (customerA, customerB)
 * 2. As ADMIN, create a mileage wallet for each customer
 * 3. As customerA, create a mileage transaction in their wallet
 * 4. As customerB, create a mileage transaction in their wallet
 * 5. As customerA:
 *    a) Attempt to delete a non-existent transaction from their own wallet (expect error)
 *    b) Attempt to delete customerB's transaction from customerB's wallet (expect error)
 *    c) Successfully delete their own transaction as sanity check (no error)
 * 6. For each error, use TestValidator.error to assert correct behavior
 */
export async function test_api_mileage_transaction_delete_nonexistent_or_not_owner(
  connection: api.IConnection,
) {
  // 1. Register two distinct customers
  const customerAInfo = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "PasswordA#1!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphaNumeric(10),
    phone: RandomGenerator.mobile(),
  };
  const customerAReg = await api.functional.auth.customer.register.signUp(connection, {
    body: customerAInfo satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerAReg);
  const customerAId = customerAReg.customer.id;

  const customerBInfo = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "PasswordB#1!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphaNumeric(10),
    phone: RandomGenerator.mobile(),
  };
  const customerBReg = await api.functional.auth.customer.register.signUp(connection, {
    body: customerBInfo satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerBReg);
  const customerBId = customerBReg.customer.id;

  // 2. As ADMIN, create mileage wallets for each customer
  const walletA = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: customerAId,
      wallet_program: "brand",
      wallet_status: "active",
    } satisfies IShoppingMallAiBackendMileageWallet.ICreate,
  });
  typia.assert(walletA);
  const walletB = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: customerBId,
      wallet_program: "brand",
      wallet_status: "active",
    } satisfies IShoppingMallAiBackendMileageWallet.ICreate,
  });
  typia.assert(walletB);

  // 3. As customerA, create a mileage transaction in their wallet
  // Switch to customerA by registering again (this sets Authorization)
  await api.functional.auth.customer.register.signUp(connection, {
    body: customerAInfo satisfies ICustomerSignUp.Request,
  });
  const mileageTxA = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.create(connection, {
    mileageWalletId: walletA.id,
    body: {
      wallet_id: walletA.id,
      transaction_type: "accumulate",
      mileage_amount: 500,
      transaction_reason: "Signup bonus",
    } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
  });
  typia.assert(mileageTxA);

  // 4. As customerB, create a mileage transaction in their wallet
  await api.functional.auth.customer.register.signUp(connection, {
    body: customerBInfo satisfies ICustomerSignUp.Request,
  });
  const mileageTxB = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.create(connection, {
    mileageWalletId: walletB.id,
    body: {
      wallet_id: walletB.id,
      transaction_type: "accumulate",
      mileage_amount: 700,
      transaction_reason: "Test case",
    } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
  });
  typia.assert(mileageTxB);

  // 5. As customerA, test DELETE edge cases
  // Switch to customerA
  await api.functional.auth.customer.register.signUp(connection, {
    body: customerAInfo satisfies ICustomerSignUp.Request,
  });

  // (a) Attempt to delete non-existent transaction
  await TestValidator.error("delete non-existent transaction as customerA")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.erase(connection, {
        mileageWalletId: walletA.id,
        mileageTransactionId: typia.random<string & tags.Format<"uuid">>(), // random UUID not belonging to any tx
      });
    }
  );

  // (b) Attempt to delete customerB's transaction using customerA
  await TestValidator.error("delete transaction belonging to another customer should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.erase(connection, {
        mileageWalletId: walletB.id,
        mileageTransactionId: mileageTxB.id,
      });
    }
  );

  // (c) Successfully delete own transaction as a sanity check
  await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.erase(connection, {
    mileageWalletId: walletA.id,
    mileageTransactionId: mileageTxA.id,
  });
}

