 * Verify that an authenticated admin can soft-delete any cart by cartId.
 *
 * This test covers the following flow:
 * 1. Register a new customer and confirm registration response (JWT + profile)
 * 2. Log in as the customer to obtain session if needed
 * 3. Create a cart as the authenticated customer
 * 4. Register an admin account and confirm registration response
 * 5. Log in as the admin to obtain authorization
 * 6. As admin, soft-delete the customer's cart by cartId
 * 7. Attempt to operate on the cart (e.g., re-delete or use it) — should fail
 * 8. Assert that the targeted cart is now marked with `deleted_at` or is excluded from list/search if applicable
 * 9. Confirm that admin compliance/audit log reflects the deletion (if endpoint or data exposed)
 *
 * Edge cases:
 * - Attempting to re-delete a deleted cart returns error
 * - Only admin (not customer) can soft-delete others' carts
 * - Invalid cartId returns appropriate error
 */
export async function test_api_cart_erase_by_admin(connection: api.IConnection) {
  // 1. Customer registration
  const customerEmail = typia.random<string & tags.Format<"email">>();
