  const customerName = RandomGenerator.name();
  const customerPhone = RandomGenerator.mobile();

  const customerRegisterResp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: customerName,
      nickname: customerNickname,
      phone: customerPhone,
    },
  });
  typia.assert(customerRegisterResp);
  const customerId = customerRegisterResp.customer.id;
  TestValidator.equals("customer email matches")(customerRegisterResp.customer.email)(customerEmail);

  // 2. Customer login
  const customerLoginResp = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    },
  });
  typia.assert(customerLoginResp);

  // 3. Create cart as customer
