  const cartId = cartCreateResp.id;
  TestValidator.equals("cart status before delete")(cartCreateResp.status)("active");
  TestValidator.equals("cart deleted_at should be null before delete")(cartCreateResp.deleted_at)(null);

  // 4. Register admin
