    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminLoginResp);

  // Auth token switch to admin happens automatically upon login

  // 6. Soft-delete the cart as admin
  await api.functional.shoppingMallAiBackend.admin.carts.erase(connection, {
    cartId: cartId,
  });

  // 7. Attempt to delete again should fail (error expected)
  await TestValidator.error("re-delete should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.carts.erase(connection, { cartId })
  );

  // 8. (No direct search/list API; but re-fetch as customer for after-deletion check, if available)
  // Optionally, attempt to operate on cart as customer — should be blocked if logic enforced
}

