 * Validate that adding an order item with invalid references fails as expected (admin endpoint).
 *
 * This test ensures system integrity by confirming that an admin cannot attach an order item with references to a nonexistent product or product_snapshot, which would break relational and audit integrity.
 * The business workflow being tested is full RBAC admin interaction: registration, authentication, and use of protected CRUD endpoints.
 *
 * Step-by-step process:
 * 1. Register a new admin, then login to obtain JWT/Authorization for privileged endpoints
 * 2. Register a new customer, then login as the customer and create an order (orderId is thus real & valid)
 * 3. Switch back to admin account (login)
 * 4. Attempt to add a new order item to the existing order using a fake/nonexistent product_id and product_snapshot_id value (random UUIDs)
 * 5. Confirm this operation fails (should throw error: validation error or not found)
 */
export async function test_api_order_item_add_by_admin_invalid_references(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin123!";
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword }
  });

  // 2. Login as admin (to test RBAC and make sure session is fresh before protected endpoints)
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword }
  });

  // 3. Register customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Customer123!";
  const customerSignUpRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile()
    }
  });
  typia.assert(customerSignUpRes);

  // 4. Login as customer
  await api.functional.auth.customer.login.signIn(connection, {
    body: { email: customerEmail, password: customerPassword }
  });

  // 5. Create customer order to generate a valid orderId
  const orderReq: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customerSignUpRes.customer.id,
    order_number: RandomGenerator.alphaNumeric(12),
    total_amount: 10000,
    currency_code: "USD",
    current_status: "created"
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderReq });
  typia.assert(order);

  // 6. Switch back to admin account to access protected endpoint
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword }
  });

  // 7. Attempt to add an invalid order item to the valid order (invalid product refs)
  const invalidOrderItem: IShoppingMallAiBackendOrderItem.ICreate = {
    order_id: order.id,
    product_id: typia.random<string & tags.Format<"uuid">>(), // fake/nonexistent
    product_snapshot_id: typia.random<string & tags.Format<"uuid">>(), // fake/nonexistent
    quantity: 1,
    unit_price: 1000,
    currency_code: "USD"
  };
  await TestValidator.error("should fail for invalid product references")(
    () => api.functional.shoppingMallAiBackend.admin.orders.orderItems.create(connection, {
      orderId: order.id,
      body: invalidOrderItem
    })
  );
}

