import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerAddress";
import type { IPageIShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerAddress";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBackendFavoriteAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteAddress";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate restoring and updating a customer favorite address, including ownership and error handling cases.
 *
 * This test simulates the full customer workflow for favorite address management:
 * - Customer registration and auth (JWT is auto-handled)
 * - Admin creates customer addresses (emulates real onboarding flow)
 * - Customer marks an address as favorite
 * - Customer unfavorites (soft-deletes) the favorite address
 * - Customer restores their favorite address using PUT (deleted_at: null)
 * - Confirms the favorite is active again in system
 * - Validates forbidden actions: modifying another user’s favorite or already deleted record
 *   (as the API supports only soft-delete/restore; no extra metadata)
 *
 * Steps:
 * 1. Register new customer and authenticate, saving Authorization
 * 2. Create multiple addresses for this customer (via admin endpoint)
 * 3. Favorite one address
 * 4. Soft-delete (unfavorite) it
 * 5. Restore via PUT (set deleted_at: null)
 * 6. Confirm active state and that it appears in favorites list
 * 7. Check error on restoring favorite for another user
 * 8. Check error on restoring a non-existent/deleted favorite
 */
export async function test_api_favorite_address_update_restore(connection: api.IConnection) {
  // 1. Customer registration
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "pw" + RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(6),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignUp);
  const customer = customerSignUp.customer;

  // 2. Create two addresses for the customer using admin endpoint
  const page = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId: customer.id,
    body: {
      customer_id: customer.id,
      page: 1,
      limit: 1,
    },
  });
  typia.assert(page);

  // Emulate address creation by picking/generated from paginator result, or use typia.random to mock if empty
  const baseAddress: IShoppingMallAiBackendCustomerAddress =
    page.data[0] ?? {
      id: typia.random<string & tags.Format<"uuid">>(),
      customer_id: customer.id,
      alias: null,
      receiver_name: RandomGenerator.name(),
      receiver_phone: RandomGenerator.mobile(),
      postal_code: "12345",
      address_line1: RandomGenerator.paragraph()(),
      address_line2: null,
      city: "Seoul",
      state: "Seoul",
      country: "KR",
      is_primary: true,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      deleted_at: null,
    };

  // 3. Mark address as favorite
  const favorite = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, {
    body: {
      customer_id: customer.id,
      address_id: baseAddress.id,
    },
  });
  typia.assert(favorite);
  TestValidator.equals("favorite ownership")(favorite.customer_id)(customer.id);
  TestValidator.equals("active favorite")(favorite.deleted_at)(null);

  // 4. Unfavorite (soft-delete)
  const deletedFavorite = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.update(connection, {
    favoriteAddressId: favorite.id,
    body: {
      deleted_at: new Date().toISOString(),
    },
  });
  typia.assert(deletedFavorite);
  TestValidator.predicate("soft deleted")(typeof deletedFavorite.deleted_at === "string");

  // 5. Restore (set deleted_at: null)
  const restored = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.update(connection, {
    favoriteAddressId: favorite.id,
    body: { deleted_at: null },
  });
  typia.assert(restored);
  TestValidator.equals("restored")(restored.deleted_at)(null);

  // 6. Confirm active (fetch all and check existence)
  const afterRestorePage = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId: customer.id,
    body: { customer_id: customer.id, page: 1, limit: 10 },
  });
  typia.assert(afterRestorePage);
  // Just presence validate, since no favorite-list endpoint provided in API spec
  TestValidator.predicate("favorite address exists after restore")(
    afterRestorePage.data.some((a) => a.id === baseAddress.id)
  );

  // 7. Error: try to restore favorite owned by another user
  const otherUserEmail = typia.random<string & tags.Format<"email">>();
  const otherUserSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: otherUserEmail,
      password: "pw" + RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(6),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(otherUserSignUp);
  TestValidator.error("cannot restore favorite owned by other user")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.update(connection, {
      favoriteAddressId: favorite.id,
      body: { deleted_at: null },
    });
  });

  // 8. Error: restore for deleted/non-existent favorite
  const randomUuid = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("restoring non-existent favorite fails")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.update(connection, {
      favoriteAddressId: randomUuid,
      body: { deleted_at: null },
    });
  });
}

