import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderItem";
import type { IPageIShoppingMallAiBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates that an admin can search and retrieve the complete list of order items by orderId, with full access and correct business data.
 *
 * This scenario covers end-to-end administrator ability to view all items in a customer order, including:
 * 1. Authenticating as admin
 * 2. Creating an order as a customer
 * 3. Adding multiple items to that order
 * 4. Using the admin endpoint to query all items in that order
 * 5. Validating that all items are visible, business fields are correct, and pagination/filter options work
 * 6. Checking that pagination and filtering behave as expected for an admin.
 */
export async function test_api_order_item_search_by_admin(connection: api.IConnection) {
  // 1. Authenticate as admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "AdminPassword123!";
  // Precondition: ensure such admin exists in fixture or seed (not possible to register via public API, so test assumes presence)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 2. Create an order as a customer
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const uniqueOrderNumber = `ORD-${Date.now()}`;
  const orderCreateInput = {
    customer_id: customerId,
    order_number: uniqueOrderNumber,
    total_amount: 0, // initial, will sum up as items are added
    currency_code: "USD",
    current_status: "created",
  } satisfies IShoppingMallAiBackendOrder.ICreate;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderCreateInput });
  typia.assert(order);

  // 3. Add multiple items to the order
  const itemsData = ArrayUtil.repeat(3)(() => ({
    order_id: order.id,
    product_id: typia.random<string & tags.Format<"uuid">>(),
    product_snapshot_id: typia.random<string & tags.Format<"uuid">>(),
    quantity: typia.random<number & tags.Type<"int32">>(),
    unit_price: Math.floor(Math.random() * 100) + 1,
    currency_code: "USD",
    note: RandomGenerator.content()()(),
  }) satisfies IShoppingMallAiBackendOrderItem.ICreate);
  const orderItems = [] as IShoppingMallAiBackendOrderItem[];
  for (const item of itemsData) {
    const created = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.create(connection, {
      orderId: order.id,
      body: item,
    });
    typia.assert(created);
    orderItems.push(created);
  }

  // 4. Admin queries all items in that order
  const adminResult = await api.functional.shoppingMallAiBackend.admin.orders.orderItems.index(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      page: 1,
      pageSize: 100,
    } satisfies IShoppingMallAiBackendOrderItem.IRequest,
  });
  typia.assert(adminResult);
  TestValidator.equals("all items present")(adminResult.data.length)(orderItems.length);
  for (const created of orderItems) {
    const found = adminResult.data.find((r) => r.id === created.id);
    TestValidator.predicate("item found by admin")(!!found);
    if (found) {
      TestValidator.equals("business data match")(found.product_id)(created.product_id);
      TestValidator.equals("business data match")(found.quantity)(created.quantity);
      TestValidator.equals("business data match")(found.unit_price)(created.unit_price);
      TestValidator.equals("business data match")(found.currency_code)(created.currency_code);
    }
  }

  // 5. Admin can paginate and filter
  const firstItem = orderItems[0];
  const pagedResult = await api.functional.shoppingMallAiBackend.admin.orders.orderItems.index(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      product_id: firstItem.product_id,
      page: 1,
      pageSize: 1,
    } satisfies IShoppingMallAiBackendOrderItem.IRequest,
  });
  typia.assert(pagedResult);
  TestValidator.equals("paged single item")(pagedResult.data.length)(1);
  const pagedItem = pagedResult.data[0];
  TestValidator.equals("single filtered")(pagedItem.id)(firstItem.id);
}

