 * 4. As admin, perform a valid status transition to move the order from its initial state to a valid next state (e.g. 'created' → 'shipped').
 * 5. Attempt to create an order status history using an invalid transition (e.g., 'shipped' → 'created') as admin, which should be rejected.
 * 6. Assert that this operation results in an error (exception thrown), confirming that invalid transitions are enforced and not permitted.
 */
export async function test_api_admin_create_order_status_history_invalid_transition(connection: api.IConnection) {
  // 1. Register admin account and obtain authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin123!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAuth);
  // The Authorization header for admin is automatically set in the connection
  const adminId = adminAuth.adminId;

  // 2. Register customer account
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Customer123!";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;

  // 3. Place an order as customer (will have initial status 'created')
  const orderNumber = `ORD-${RandomGenerator.alphaNumeric(10)}`;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
      order_number: orderNumber,
      total_amount: 10000,
      currency_code: "KRW",
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
