      new_status: "shipped",
      actor_type: "admin",
      actor_id: adminId,
      event_context: "Valid transition to shipped for shipping workflow.",
      occurred_at: new Date().toISOString(),
    } satisfies IShoppingMallAiBackendOrderStatusHistory.ICreate,
  });
  typia.assert(validStatusHistory);

