  await TestValidator.error("Invalid order status transition should result in error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.create(connection, {
        orderId: orderId,
        body: {
          previous_status: "shipped",
          new_status: "created",
          actor_type: "admin",
          actor_id: adminId,
          event_context: "Attempting forbidden status rollback.",
          occurred_at: new Date().toISOString(),
        } satisfies IShoppingMallAiBackendOrderStatusHistory.ICreate,
      });
    },
  );
}

