 * This test verifies Role-Based Access Control (RBAC) enforcement. It performs the following:
 *
 * 1. Register an admin (setup for potential cleanup/validation if needed)
 * 2. Register a new customer (non-admin user)
 * 3. Attach an external link to the customer (the link to be targeted)
 * 4. As the customer (with their JWT), attempt to call the admin-only soft-delete endpoint for the external link
 * 5. Validate that the API blocks the operation (permission denied error)
 * 6. Confirm the external link record remains undeleted (deleted_at is still null)
 */
export async function test_api_admin_external_link_delete_permission_denied(connection: api.IConnection) {
  // 1. Register an admin (for setup, not used directly in this test, but ensures RBAC context is defined)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin-Password-123";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword }
  });
  typia.assert(adminSignUp);

  // 2. Register a customer (the non-admin who will own the external link)
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "customer-Password-456";
  const customerName = RandomGenerator.name();
  const customerNickname = RandomGenerator.alphaNumeric(8);
  const customerPhone = RandomGenerator.mobile();
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: customerName,
      nickname: customerNickname,
      phone: customerPhone
    }
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;
  // Use the JWT token provided for the customer
  connection.headers = {
    ...connection.headers,
    Authorization: customerSignUp.setHeaders.Authorization
  };

  // 3. Attach an external link to the customer
  const provider = "test-provider";
  const externalId = RandomGenerator.alphaNumeric(12);
  const linkedAt = new Date().toISOString();
  const attachResult = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(connection, {
    customerId: customerId,
    body: {
      id: typia.random<string & tags.Format<"uuid">>(), // The API expects us to supply the link ID (simulate creating one)
      provider: provider,
      external_id: externalId,
      linked_at: linkedAt,
      metadata_json: JSON.stringify({ testing: true })
    }
  });
  typia.assert(attachResult);
  const externalLinkId = attachResult.id;

  // 4. As the customer, attempt to delete the external link using the admin-only endpoint
  await TestValidator.error("customer RBAC: permission denied for admin endpoint")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.externalLinks.erase(connection, {
      customerId: customerId,
      externalLinkId: externalLinkId
    });
  });

