  const linkReadback = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(connection, {
    customerId: customerId,
    body: { id: externalLinkId }
  });
  typia.assert(linkReadback);
  TestValidator.equals("not deleted")(linkReadback.deleted_at)(null);
