import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import type { IPageIShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendMileageTransaction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Tests customer-scoped filtered, paginated search of mileage transactions in a wallet.
 *
 * 1. Register a new customer and get automatic login/JWT.
 * 2. Create a mileage wallet for that customer via admin API.
 * 3. Add multiple transactions (with different types, amounts, and timestamps) into the wallet as that customer.
 * 4. Search transactions with filters (transaction_type, date range, amount range, pagination).
 * 5. Validate only the customer’s own wallet data is returned, that filters/paging work as expected, and that there is no data leakage across customers.
 *
 * Business validation points:
 * - Customer cannot view other wallets’ transactions.
 * - Transaction_type filter returns only expected types.
 * - Date and amount range filters restrict results correctly.
 * - Paging yields correct page sizes/counts.
 * - All API responses have proper typing and structure.
 * - Negative/positive scenarios: E.g., insufficient/no match for some filters, unauthorized access.
 */
export async function test_api_mileage_transaction_search_customer_scope(connection: api.IConnection) {
  // 1. Register new customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPassword123!";
  const nickname = RandomGenerator.name();
  const signUpRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname,
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpRes);
  const customer = signUpRes.customer;

  // 2. Create mileage wallet for customer (as admin)
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: customer.id,
      wallet_program: "brand",
      wallet_status: "active",
      wallet_label: "Test Customer Wallet",
      security_code: null,
    } satisfies IShoppingMallAiBackendMileageWallet.ICreate,
  });
  typia.assert(wallet);

  // 3. Add several transactions of various types/amounts/times
  const now = new Date();
  const transactionTypes = ["accumulate", "redeem", "expire", "correction"];
  const createdTransactions: IShoppingMallAiBackendMileageTransaction[] = [];
  for (let i=0; i<10; ++i) {
    const transaction_type = RandomGenerator.pick(transactionTypes);
    const mileage_amount = (i % 2 === 0 ? 100 : -50) + i*3;
    const transaction = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.create(connection, {
      mileageWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        transaction_type,
        mileage_amount,
        reference_id: null,
        transaction_reason: `Reason ${i}`,
      } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
    });
    typia.assert(transaction);
    createdTransactions.push(transaction);
  }

  // 4. Search/filter: transaction_type
  const typeFilter = transactionTypes[0];
  const byType = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.search(connection, {
    mileageWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      transaction_type: typeFilter,
    } satisfies IShoppingMallAiBackendMileageTransaction.IRequest,
  });
  typia.assert(byType);
  TestValidator.predicate("transaction_type filter applied")(
    byType.data.every(tr => tr.transaction_type === typeFilter)
  );

  // 5. Search/filter: date range
  const start = new Date(now.getTime() - 1000 * 60 * 60).toISOString();
  const end = new Date(now.getTime() + 1000 * 60 * 60 * 2).toISOString();
  const byDate = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.search(connection, {
    mileageWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      created_from: start,
      created_to: end,
    } satisfies IShoppingMallAiBackendMileageTransaction.IRequest,
  });
  typia.assert(byDate);
  TestValidator.predicate("created_at in range")(
    byDate.data.every(tr => tr.created_at >= start && tr.created_at <= end)
  );

  // 6. Search/filter: min/max amount
  const min_amount = 97, max_amount = 105;
  const byAmount = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.search(connection, {
    mileageWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      min_amount,
      max_amount,
    } satisfies IShoppingMallAiBackendMileageTransaction.IRequest,
  });
  typia.assert(byAmount);
  TestValidator.predicate("amount range filter")(
    byAmount.data.every(tr => tr.mileage_amount >= min_amount && tr.mileage_amount <= max_amount)
  );

  // 7. Paging works
  const pageSize = 3;
  const page1 = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.search(connection, {
    mileageWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      page: 1,
      page_size: pageSize,
      sort_by: "created_at",
      sort_order: "asc",
    },
  });
  typia.assert(page1);
  TestValidator.equals("page size 1st page")(page1.data.length)(Math.min(pageSize, createdTransactions.length));

  const page2 = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.search(connection, {
    mileageWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      page: 2,
      page_size: pageSize,
      sort_by: "created_at",
      sort_order: "asc",
    },
  });
  typia.assert(page2);
  TestValidator.equals("page size 2nd page")(page2.data.length)(
    Math.min(pageSize, createdTransactions.length - pageSize)
  );

  // 8. Data isolation: attempt to access other wallet's transactions (simulate by using random UUID)
  TestValidator.error("cannot view other wallets' data")(async () => {
    await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.search(connection, {
      mileageWalletId: typia.random<string & tags.Format<"uuid">>(),
      body: {}, // intentionally empty/wrong
    });
  });
}

