import type { IShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartItem";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test updating a cart item as an admin for a non-existent cartItemId in a given cart.
 *
 * Business context:
 * This test ensures that the API correctly rejects attempts by an admin to update a cart item that does not exist within a valid cart. It validates robust error handling for entity-not-found conditions and security for write operations.
 *
 * Steps:
 * 1. Register an admin user (admin registration)
 * 2. Register a customer (customer registration)
 * 3. Provision a cart for the customer
 * 4. As the admin, attempt to update a cart item using a random, non-existent cartItemId for the valid cartId
 * 5. Verify that the update operation fails gracefully, asserting a proper error/exception is thrown due to the cartItem not existing for that cart
 */
export async function test_api_cart_item_update_by_admin_not_found_error(connection: api.IConnection) {
  // 1. Register an admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123!";
  const adminProfile = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminProfile);

  // 2. Register a customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "CustomerPassword123!";
  const customerProfile = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerProfile);

  // Set Authorization header for customer
  connection.headers = {
    ...connection.headers,
    Authorization: customerProfile.setHeaders.Authorization,
  };

  // 3. Create a cart for the customer
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    } satisfies IShoppingMallAiBackendCart.ICreate,
  });
  typia.assert(cart);

  // 4. Switch Authorization to admin
  connection.headers = {
    ...connection.headers,
    Authorization: adminProfile.setHeaders.Authorization,
  };

  // 5. Attempt to update a non-existent cart item as admin
  const nonExistentCartItemId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("should throw error for non-existent cartItemId")(async () => {
    await api.functional.shoppingMallAiBackend.admin.carts.cartItems.update(connection, {
      cartId: cart.id,
      cartItemId: nonExistentCartItemId,
      body: {
        quantity: 2,
      } satisfies IShoppingMallAiBackendCartItem.IUpdate,
    });
  });
}

