import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import type { IShoppingMallAiBackendReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendReviewSnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate customer-driven creation of a product review snapshot.
 *
 * Business context:
 * - Only a customer who has purchased a product may leave a review, and only for that product/order item.
 * - Each significant change to a product review's business fields (content, rating, status, moderation) requires creation of a new immutable snapshot, which acts as historical evidence for audit, legal, and dispute-tracing purposes.
 *
 * Steps implemented and validated:
 * 1. Register a new customer account via the registration endpoint.
 * 2. Place an order for the customer (minimum fields, using unique order_number, status, and amount for validity).
 * 3. Submit a product review for the purchased product/order item, verifying correct creation.
 * 4. Perform a snapshot of the review using its current state (all business fields and AI moderation info).
 * 5. Validate that the returned snapshot entity:
 *      - Has the expected body, rating, status, and actor fields (matches review at snapshot time).
 *      - Links to the parent review (review_id).
 *      - Includes timestamp and optional AI moderation scores if present.
 *      - Is owned by the correct actor (the customer who wrote the review).
 * 6. Optionally: Attempt to retrieve the snapshot (if API supports), or in lieu, validate audit log presence (not implementable if no read/list endpoint exists).
 */
export async function test_api_product_review_snapshot_creation_success_customer(connection: api.IConnection) {
  // 1. Customer registration
  const signUpRequest: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const { customer } = await api.functional.auth.customer.register.signUp(connection, { body: signUpRequest });
  typia.assert(customer);

  // 2. Create order for customer
  const orderCreate: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customer.id,
    order_group_id: null,
    order_number: RandomGenerator.alphaNumeric(16),
    total_amount: 20000, // minimal nonzero order
    currency_code: "KRW",
    note: null,
    current_status: "created",
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderCreate });
  typia.assert(order);

  // 3. Leave a product review
  // Note: Due to lack of product/order item creation APIs, we use order.id as stand-in for both product_id and order_item_id to satisfy required foreign-key shape.
  const reviewCreate: IShoppingMallAiBackendProductReview.ICreate = {
    product_id: order.id as unknown as string & tags.Format<"uuid">,
    order_item_id: order.id as unknown as string & tags.Format<"uuid">,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    rating: 5,
    status: "normal",
  };
  const review = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, { body: reviewCreate });
  typia.assert(review);

  // 4. Create review snapshot with review's current state
  const snapshotCreate: IShoppingMallAiBackendReviewSnapshot.ICreate = {
    review_id: review.id,
    body: review.body,
    rating: review.rating,
    status: review.status,
    actor_id: review.customer_id,
    ai_sentiment_score: review.ai_sentiment_score ?? null,
    ai_spam_score: review.ai_spam_score ?? null,
    changed_at: review.updated_at,
  };
  const snapshot = await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.create(connection, { productReviewId: review.id, body: snapshotCreate });
  typia.assert(snapshot);

  // 5. Validate returned snapshot accuracy
  TestValidator.equals("snapshot.review_id matches")(snapshot.review_id)(review.id);
  TestValidator.equals("snapshot.body matches")(snapshot.body)(review.body);
  TestValidator.equals("snapshot.rating matches")(snapshot.rating)(review.rating);
  TestValidator.equals("actor_id matches")(snapshot.actor_id)(review.customer_id);
  TestValidator.equals("status matches")(snapshot.status)(review.status);
  if (review.ai_sentiment_score !== undefined)
    TestValidator.equals("ai_sentiment_score matches")(snapshot.ai_sentiment_score)(review.ai_sentiment_score ?? null);
  if (review.ai_spam_score !== undefined)
    TestValidator.equals("ai_spam_score matches")(snapshot.ai_spam_score)(review.ai_spam_score ?? null);
  TestValidator.equals("changed_at matches review updated_at")(snapshot.changed_at)(review.updated_at);
}

