import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderStatusHistory";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin update of order status history and appropriate permissions.
 *
 * This test ensures that an admin can successfully update only the permitted
 * fields (event_context) of an existing order status history record, while attempts
 * to modify forbidden fields, non-existent records, or using unauthorized roles are
 * properly rejected. The procedure also verifies audit and compliance measures.
 *
 * Steps:
 * 1. Register a new admin; record JWT for further admin actions.
 * 2. Register a customer for order placement; get the customer id and JWT.
 * 3. As customer, create a new order (records initial status).
 * 4. As customer, create a new order status history for some status transition (e.g., 'created'→'pending').
 * 5. As admin, update the status history event_context for the record created above — expect success, changed event_context is reflected.
 * 6. Attempt to update forbidden fields (previous_status, new_status, etc.) as admin — forbidden by DTO, skip at compile but doc why cannot test.
 * 7. Attempt update as customer instead of admin — expect error, not authorized.
 * 8. Attempt to update with invalid orderStatusHistoryId — expect error, no record found or forbidden.
 * 9. If feasible, validate audit trail by observing the returned entity, as status history record should reflect history of changes (not possible if only single update is stored in model, note this limitation in comments).
 */
export async function test_api_order_status_history_update_by_admin_success_and_permissions(connection: api.IConnection) {
  // 1. Register admin account
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = '1234';
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);
  // Set Authorization header to admin JWT for further admin requests
  connection.headers = {
    ...connection.headers,
    Authorization: adminSignUp.setHeaders.Authorization,
  };

  // 2. Register customer
  const customerEmail = typia.random<string & tags.Format<'email'>>();
  const customerPassword = '5678';
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: 'John Doe',
      nickname: 'johnny',
      phone: '01012345678',
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);

  // 3. As customer, create order
  connection.headers = {
    ...connection.headers,
    Authorization: customerSignUp.setHeaders.Authorization,
  };
  const orderCreateBody = {
    customer_id: customerSignUp.customer.id,
    order_number: 'ORD-' + typia.random<string>(),
    total_amount: 12345,
    currency_code: 'USD',
    note: 'Test order',
    current_status: 'created',
  } satisfies IShoppingMallAiBackendOrder.ICreate;
  const createdOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderCreateBody });
  typia.assert(createdOrder);

  // 4. As customer, create status history record: 'created' → 'pending'
  const nowString = new Date().toISOString();
  const statusHistoryBody = {
    previous_status: 'created',
    new_status: 'pending',
    actor_type: 'customer',
    actor_id: customerSignUp.customer.id,
    event_context: 'Customer advances order',
    occurred_at: nowString,
  } satisfies IShoppingMallAiBackendOrderStatusHistory.ICreate;
  const orderStatusHistory = await api.functional.shoppingMallAiBackend.customer.orders.orderStatusHistories.create(connection, {
    orderId: createdOrder.id,
    body: statusHistoryBody,
  });
  typia.assert(orderStatusHistory);

  // 5. As admin, update status history event_context (only permitted field)
  connection.headers = {
    ...connection.headers,
    Authorization: adminSignUp.setHeaders.Authorization,
  };
  const adminUpdateBody = {
    event_context: 'Updated by admin for compliance',
  } satisfies IShoppingMallAiBackendOrderStatusHistory.IUpdate;
  const updatedStatusHistory = await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.update(connection, {
    orderId: createdOrder.id,
    orderStatusHistoryId: orderStatusHistory.id,
    body: adminUpdateBody,
  });
  typia.assert(updatedStatusHistory);
  TestValidator.equals('event_context updated')(updatedStatusHistory.event_context)('Updated by admin for compliance');

  // 6. Attempt to update forbidden fields — compile-time impossible due to DTO limitations
  // (Cannot include previous_status, new_status in IUpdate, this is enforced at TS level.)

  // 7. Try update as customer (expect error)
  connection.headers = {
    ...connection.headers,
    Authorization: customerSignUp.setHeaders.Authorization,
  };
  TestValidator.error('non-admin forbidden for update')(async () => {
    await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.update(connection, {
      orderId: createdOrder.id,
      orderStatusHistoryId: orderStatusHistory.id,
      body: adminUpdateBody,
    });
  });

  // 8. Try update non-existent status history id as admin (expect error)
  connection.headers = {
    ...connection.headers,
    Authorization: adminSignUp.setHeaders.Authorization,
  };
  TestValidator.error('updating non-existent record fails')(async () => {
    await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.update(connection, {
      orderId: createdOrder.id,
      orderStatusHistoryId: typia.random<string & tags.Format<'uuid'>>(),
      body: adminUpdateBody,
    });
  });

  // 9. (Audit trail validation limited — model only returns one record, no version history in response)
  // If the full audit trail or versioning is returned, assert here. Otherwise not possible, so document.
}

