import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartItem";
import type { IPageIShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCartItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validates that a customer can retrieve, filter, and paginate their own cart items.
 *
 * This test covers the following business process:
 * 1. Register a new customer account.
 * 2. Login with the registered account to ensure authorized access.
 * 3. Create a new cart for the customer.
 * 4. Add multiple items with varying product and product_option IDs to the cart for realistic multi-product test conditions.
 * 5. Issue search queries (PATCH on cartItems):
 *    - a) No filters: retrieve all cart items, verify pagination, data content, and ownership (only customer’s items are returned)
 *    - b) Filter by product_id: verify only items matching product are returned
 *    - c) Filter by product_option_id: verify only items for the option are returned
 *    - d) Pagination test: limit < total count, page 2 returns correct results
 * 6. For each query and filter, validate integrity: correct count, exact items, and data consistency
 */
export async function test_api_cart_cartitem_search_by_owner(connection: api.IConnection) {
  // 1. Register a new customer account (signUp)
  const signUpRequest: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "test-password-123!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const signUpResp = await api.functional.auth.customer.register.signUp(connection, { body: signUpRequest });
  typia.assert(signUpResp);
  TestValidator.equals("email match")(signUpResp.customer.email)(signUpRequest.email);

  // 2. Login as the customer for fresh auth header
  const loginResp = await api.functional.auth.customer.login.signIn(connection, {
    body: { email: signUpRequest.email, password: signUpRequest.password },
  });
  typia.assert(loginResp);
  TestValidator.equals("login email match")(loginResp.customer.email)(signUpRequest.email);

  // 3. Create a new cart for this customer
  const cartCreateReq: IShoppingMallAiBackendCart.ICreate = {
    status: "active",
    session_token: null,
  };
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, { body: cartCreateReq });
  typia.assert(cart);

  // 4. Add multiple items with different products/options
  // We'll add 4 items:
  // - Two with different product_ids
  // - Two with same product_id but different product_option_ids
  const productIds = [typia.random<string & tags.Format<"uuid">>(), typia.random<string & tags.Format<"uuid">>()];
  const optionIds = [typia.random<string & tags.Format<"uuid">>(), typia.random<string & tags.Format<"uuid">>()];
  const baseUnitPrice = 10000;
  const currency = "KRW";
  // Add 1: product[0], no option
  const item1 = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
    cartId: cart.id,
    body: {
      product_id: productIds[0],
      product_option_id: null,
      quantity: 2,
      unit_price: baseUnitPrice,
      currency_code: currency,
      note: "First item no option",
    },
  });
  typia.assert(item1);

  // Add 2: product[0], option[0]
  const item2 = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
    cartId: cart.id,
    body: {
      product_id: productIds[0],
      product_option_id: optionIds[0],
      quantity: 1,
      unit_price: baseUnitPrice + 1000,
      currency_code: currency,
      note: "Second item with option 0",
    },
  });
  typia.assert(item2);

  // Add 3: product[0], option[1]
  const item3 = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
    cartId: cart.id,
    body: {
      product_id: productIds[0],
      product_option_id: optionIds[1],
      quantity: 3,
      unit_price: baseUnitPrice + 2000,
      currency_code: currency,
      note: "Third item with option 1",
    },
  });
  typia.assert(item3);

  // Add 4: product[1], no option
  const item4 = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
    cartId: cart.id,
    body: {
      product_id: productIds[1],
      product_option_id: null,
      quantity: 1,
      unit_price: baseUnitPrice,
      currency_code: currency,
      note: "Fourth item product 1",
    },
  });
  typia.assert(item4);

  // 5a. Retrieve all cart items, unfiltered search
  const searchAll = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: {},
  });
  typia.assert(searchAll);
  TestValidator.equals("should return all 4 items")(searchAll.data.length)(4);
  const allItemIds = [item1.id, item2.id, item3.id, item4.id];
  for (const found of searchAll.data) {
    TestValidator.predicate("all items owned")(allItemIds.includes(found.id));
    TestValidator.equals("cartId match")(cart.id)(cart.id);
  }

  // 5b. Filter by product_id (productIds[0])
  const searchByProduct = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: { product_id: productIds[0] },
  });
  typia.assert(searchByProduct);
  // Should include only item1, item2, item3
  TestValidator.equals("product filter count")(searchByProduct.data.length)(3);
  for (const found of searchByProduct.data) {
    TestValidator.equals("filtered product")(found.product_id)(productIds[0]);
  }

  // 5c. Filter by product_option_id (optionIds[1]) (should only include item3)
  const searchByOption = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: {
      product_option_id: optionIds[1],
    },
  });
  typia.assert(searchByOption);
  TestValidator.equals("option filter count")(searchByOption.data.length)(1);
  TestValidator.equals("option id matches")(searchByOption.data[0].id)(item3.id);

  // 5d. Pagination test: limit=2 should return only first 2 items, page 2 returns next 2
  const paged1 = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: {
      limit: 2,
      page: 1,
      sort_field: "created_at",
      sort_dir: "asc",
    },
  });
  typia.assert(paged1);
  TestValidator.equals("limit page 1 count")(paged1.data.length)(2);
  const paged2 = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: {
      limit: 2,
      page: 2,
      sort_field: "created_at",
      sort_dir: "asc",
    },
  });
  typia.assert(paged2);
  // All items across pages 1 and 2 must match set of 4, no duplication
  const combinedPaged = [...paged1.data, ...paged2.data];
  TestValidator.equals("paged ids")(combinedPaged.map(i => i.id).sort())(allItemIds.sort());
}

