 * 3. Login as Seller A and create a new product.
 * 4. As Seller A, add a product content to the product.
 * 5. Logout (if necessary) and login as Seller B.
 * 6. As Seller B (who does not own the product), attempt to delete Seller A's product content. This should fail with a permission error.
 * 7. Login back as Seller A and verify that the product content still exists by (optionally) attempting deletion (should succeed for the owner), or by verifying via API if there is a content listing/read function.
 *
 * Validations:
 * - The cross-owner deletion attempt by Seller B must fail with a permission-related error.
 * - The product content must still exist after the failed deletion attempt, as verified by the owner.
 */
export async function test_api_product_content_delete_not_owned_by_seller(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAemail = typia.random<string & tags.Format<"email">>();
  const sellerApassword = "Password123!"; // static for login simplicity
  const sellerA = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAemail,
      password: sellerApassword,
      companyName: RandomGenerator.company(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerA);

  // 2. Register Seller B
  const sellerBemail = typia.random<string & tags.Format<"email">>();
  const sellerBpassword = "Password123!";
  const sellerB = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBemail,
      password: sellerBpassword,
      companyName: RandomGenerator.company(),
      businessNumber: "0987654321",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerB);

  // 3. Login as Seller A (ensure token is set)
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerAemail,
      password: sellerApassword,
    } satisfies ISellerAuth.SignIn,
  });

  // 4. Seller A creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerA.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(1),
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 5. Seller A creates product content
  const content = await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      content_type: "gallery_image",
      content_uri: "https://cdn.example.com/images/" + RandomGenerator.alphaNumeric(8),
      content_order: 1,
      content_description: RandomGenerator.paragraph()(1),
      status: "active",
    } satisfies IShoppingMallAiBackendProductContent.ICreate,
  });
  typia.assert(content);

  // 6. Login as Seller B (sets token)
  await api.functional.auth.seller.login.signIn(connection, {
    body: { email: sellerBemail, password: sellerBpassword } satisfies ISellerAuth.SignIn,
  });

  // 7. Seller B attempts to delete Seller A's product content (should FAIL - permission error)
  await TestValidator.error("Seller B cannot delete Seller A's product content")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productContents.erase(connection, {
      productId: product.id,
      productContentId: content.id,
    }),
  );

  // 8. Login again as Seller A to ensure content is present (no GET/list endpoint so attempt DELETE - should succeed)
  await api.functional.auth.seller.login.signIn(connection, {
    body: { email: sellerAemail, password: sellerApassword } satisfies ISellerAuth.SignIn,
  });
  await api.functional.shoppingMallAiBackend.seller.products.productContents.erase(connection, {
    productId: product.id,
    productContentId: content.id,
  });
  // If no error thrown, deletion by owner succeeded; permission logic is enforced.
}

