import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { IPageIShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendInquirySnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for admin searching paginated/filtered inquiry snapshots for any product inquiry,
 * testing positive and negative scenarios.
 * 
 * Business context:
 * - Product inquiries are tracked and all changes are audit-logged by snapshots (for evidence/regulatory/compliance)
 * - Admin should be able to search/filter all snapshots for any inquiry with pagination
 *
 * Test Steps:
 * 1. Register an admin (and get adminId)
 * 2. As customer, create a product inquiry (keep all UUIDs)
 * 3. As customer, update/edit inquiry multiple times (body, status, public), which generate snapshots
 * 4. As admin, manually create another snapshot for the inquiry
 * 5. As admin, retrieve (search) all snapshots for the inquiry with:
 *    - default: paginated unfiltered
 *    - filtered by actor_id (customer or admin)
 *    - filtered by status (e.g. 'waiting', 'blocked', etc)
 *    - sorted and paginated
 *    - filter by changed_at (time window)
 * 6. Assert that snapshots include the expected events in correct order and filtering/pagination works
 * 7. Negative: search as non-admin (should fail) and with malformed filter (should error)
 */
export async function test_api_inquiry_snapshot_admin_search_advanced_audit_evidence(connection: api.IConnection) {
  // 1. Register Admin
  const adminInfo = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongP@ss1!"
    }
  });
  typia.assert(adminInfo);

  // 2. Create Inquiry as Customer (simulate customer uuid/product uuid)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const productId = typia.random<string & tags.Format<"uuid">>();
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: productId,
      title: "Test Inquiry Title",
      body: "What is the size of the red L shirt?",
      public: true
    }
  });
  typia.assert(inquiry);

  // 3. Multiple Inquiry Edits (generates snapshots)
  const update1 = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      title: "Test Inquiry Title UPDATED 1",
      status: "waiting"
    }
  });
  typia.assert(update1);

  const update2 = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      status: "blocked",
      body: "Spam content for block test"
    }
  });
  typia.assert(update2);

  // 4. Admin manually creates another snapshot
  await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.create(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      title: update2.title,
      body: update2.body,
      public: update2.public,
      status: update2.status,
      actor_id: adminInfo.adminId,
      changed_at: new Date().toISOString()
    }
  });

  // 5. Admin searches (PATCH) inquiry snapshots for this inquiry (no filters)
  const resultAll = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id
    }
  });
  typia.assert(resultAll);
  TestValidator.predicate("at least three snapshots for this inquiry")(resultAll.data.length >= 3);

  // 5b. Filter by actor_id (admin)
  const filterAdmin = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      actor_id: adminInfo.adminId
    }
  });
  typia.assert(filterAdmin);
  TestValidator.predicate("admin snapshot found")(filterAdmin.data.some(s => s.actor_id === adminInfo.adminId));

  // 5c. Filter by status
  const filterBlocked = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      status: "blocked"
    }
  });
  typia.assert(filterBlocked);
  TestValidator.predicate("at least one blocked snapshot")(filterBlocked.data.some(s => s.status === "blocked"));

  // 5d. Pagination (limit 1, page 1)
  const paged = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      limit: 1,
      page: 1
    }
  });
  typia.assert(paged);
  TestValidator.equals("one result per page")(paged.data.length)(1);

  // 5e. Sorted by changed_at desc
  await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      sort_by: "changed_at",
      sort_direction: "desc"
    }
  });

  // 6. Negative scenario: search as non-admin (simulate by disconnecting admin token, expect error)
  connection.headers.Authorization = undefined;
  await TestValidator.error("non-admin cannot search snapshots")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
      productInquiryId: inquiry.id,
      body: {
        inquiry_id: inquiry.id
      }
    });
  });

  // 7. Negative scenario: malformed filter (missing required inquiry_id)
  connection.headers.Authorization = adminInfo.setHeaders.Authorization;
  await TestValidator.error("malformed filter causes error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
      productInquiryId: inquiry.id,
      body: {} as any
    });
  });
}

