/**
 * Validate that an admin can update a favorite notification event record for a customer.
 *
 * Business context:
 * - Admin notification updates are necessary for correcting, auditing, or force marking as read, editing metadata, or fixing delivery errors.
 * - Auditing and event traceability are critical; notification history must be preserved per compliance rules.
 *
 * Workflow:
 * 1. Register a new admin account (get admin JWT and privilege).
 * 2. Register a new customer account (simulate a real user who will receive the notification).
 * 3. Customer favorites a product (as the favorite triggers notification infrastructure).
 * 4. Create a favorite notification event for this favorite (mimic a real notification triggered by a system event like RESTOCK/PRICE_DROP).
 * 5. As ADMIN, update the notification record: mark as read, update delivery channel, and metadata.
 * 6. Confirm that the updated fields are persisted and reflect the changes.
 * 7. (Optionally check that non-updated fields remain unchanged for confidence).
 */
export async function test_api_admin_favorite_notification_update_success(connection: api.IConnection) {
  // 1. Admin registers and receives JWT
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'AdminPass123!';
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);
  // Set admin Authorization header for following requests
  connection.headers = { ...connection.headers, Authorization: adminSignUp.setHeaders.Authorization };

  // 2. Register new customer
  const customerEmail = typia.random<string & tags.Format<'email'>>();
  const customerPassword = 'CustomerPass456!';
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  // Now customer is authorized; but for following steps as customer, set Authorization to their token.
  connection.headers = { ...connection.headers, Authorization: customerSignUp.setHeaders.Authorization };
  const customerId = customerSignUp.customer.id;

  // 3. Customer favorites a product. (Simulate a favoritable product ID)
  const productId = typia.random<string & tags.Format<'uuid'>>();
  const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: {
      product_id: productId,
    } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate,
  });
  typia.assert(favoriteProduct);

  // 4. Customer/Service creates a notification for this favorite event
  const favoriteNotification = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, {
    body: {
      favorite_product_id: favoriteProduct.id,
      notification_type: 'PRICE_DROP', // valid example type
      notification_channel: 'EMAIL',
      read: false,
      delivery_metadata: 'Initial trigger',
    } satisfies IShoppingMallAiBackendFavoriteNotification.ICreate,
  });
  typia.assert(favoriteNotification);
  // Save original state to compare after update
  const originalNotification = { ...favoriteNotification };

  // 5. Switch back to admin privilege for update
  connection.headers = { ...connection.headers, Authorization: adminSignUp.setHeaders.Authorization };

  // 6. Update notification: mark as read + update delivery channel/meta
  const updateBody: IShoppingMallAiBackendFavoriteNotification.IUpdate = {
    read: true,
    notification_channel: 'PUSH',
    delivery_metadata: 'Manually reviewed and resent',
  };
  const updatedNotification = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.update(connection, {
    favoriteNotificationId: favoriteNotification.id as string & tags.Format<'uuid'>,
    body: updateBody,
  });
  typia.assert(updatedNotification);

  // 7. Assert updated fields reflect change, non-updated fields remain intact
  TestValidator.equals('read flag')(updatedNotification.read)(true);
  TestValidator.equals('notification_channel')(updatedNotification.notification_channel)('PUSH');
  TestValidator.equals('delivery_metadata')(updatedNotification.delivery_metadata)('Manually reviewed and resent');
  // Check updatedNotification.id matches
  TestValidator.equals('id')(updatedNotification.id)(favoriteNotification.id);
  // Non-updated fields remain unchanged
  TestValidator.equals('notification_type')(updatedNotification.notification_type)(originalNotification.notification_type);
  TestValidator.equals('favorite_product_id')(updatedNotification.favorite_product_id)(originalNotification.favorite_product_id);
  TestValidator.equals('created_at')(updatedNotification.created_at)(originalNotification.created_at);
}

