import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import type { IShoppingMallAiBackendProductOptionStock } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOptionStock";
import type { IPageIShoppingMallAiBackendProductOptionStock } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductOptionStock";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate searching for product option stocks when there are no stocks present or when filters intentionally yield no results.
 *
 * Business context:
 * Sellers manage inventory for various product options (color, size, etc.), where each option can have multiple stock locations or records. This test verifies that when the seller queries stock records for a newly created product option (for which no stocks exist), the API should return an empty result gracefully. It also verifies that applying an impossible filter on a non-empty option returns an empty page as well, instead of error or invalid data.
 *
 * Step-by-step process:
 * 1. Register a new seller account.
 * 2. Log the seller in.
 * 3. Create a product under the seller account.
 * 4. Add a product option for the created product (do not create any stocks for this option).
 * 5. Use the search API (PATCH /shoppingMallAiBackend/seller/productOptions/{productOptionId}/productOptionStocks) as the seller with a filter that cannot possibly match any records (e.g., a random status, or a fake warehouse location).
 * 6. Verify that the returned result page is empty (data array is empty, pagination 'records' count is 0).
 */
export async function test_api_product_option_stock_search_no_records_seller(
  connection: api.IConnection,
) {
  // 1. Register a new seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "sellerTest1234";
  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: "E2E Test Seller Co.",
      businessNumber: "1234567890",
      representativeName: "Test Owner",
      address: "Seoul, S. Korea",
      phone: "010-1234-5678"
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(signUpResp);

  // 2. Log the seller in (refreshes session, although signUp already issues JWT)
  const signInResp = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword
    } satisfies ISellerAuth.SignIn
  });
  typia.assert(signInResp);

  // 3. Create a product under this seller
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: signUpResp.sellerId,
      code: "CODE-" + typia.random<string>(),
      name: "Stockless Product",
      description: "A product for E2E no-stocks testing.",
      main_image_uri: null,
      status: "draft"
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 4. Add a product option for this product
  const productOption = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: "SKU-" + typia.random<string>(),
      option_name: "Color",
      option_values: "Blue",
      extra_price: 0,
      main_image_uri: null,
      status: "active"
    } satisfies IShoppingMallAiBackendProductOption.ICreate
  });
  typia.assert(productOption);

  // 5. Search for product option stocks for this new option, filtering by an impossible warehouse location
  const impossibleWarehouse = "WAREHOUSE_DOES_NOT_EXIST";
  const resultPage = await api.functional.shoppingMallAiBackend.seller.productOptions.productOptionStocks.search(connection, {
    productOptionId: productOption.id,
    body: {
      filter: {
        warehouse_location: impossibleWarehouse
      },
      page: 1,
      pageSize: 10
    } satisfies IShoppingMallAiBackendProductOptionStock.IRequest
  });
  typia.assert(resultPage);
  // 6. Verify that results are empty
  TestValidator.equals("stock result array is empty")(resultPage.data.length)(0);
  TestValidator.equals("stock record count is zero")(resultPage.pagination.records)(0);
}

