 * In a shopping mall backend system, only authenticated admins can perform deletions on any cart items. If an admin attempts to delete a cart item that does not exist (invalid cartItemId) within an existing cart, the API must return a proper error (e.g., not found or business rule violation).
 *
 * Step-by-step test workflow:
 * 1. Register and authenticate as an admin.
 * 2. Register a customer account for test context.
 * 3. Create a shopping cart for the created customer.
 * 4. As admin, attempt to delete a cart item from the cart using a non-existent cartItemId (random valid UUID that does not match any actual item).
 * 5. Assert that the API throws an error (not success), validating proper system-level error handling for this scenario.
 */
export async function test_api_cart_item_delete_by_admin_nonexistent_cartitem_error(connection: api.IConnection) {
  // 1. Register and authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPW123!";
  const adminRegisterRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminRegisterRes);
  // Connection is now authenticated as the admin via token in headers

  // 2. Register a test customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerRegisterRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "customerPW123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerRegisterRes);
  const customer = customerRegisterRes.customer;

  // 3. Create a cart for the customer. This test assumes the admin session can create a cart (test setup context).
  const cartCreateRes = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      // session_token is omitted for authenticated context
    } satisfies IShoppingMallAiBackendCart.ICreate,
  });
  typia.assert(cartCreateRes);

  // 4. Attempt as admin to delete a non-existent cart item from this cart
  const nonExistentCartItemId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Deleting non-existent cart item should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.carts.cartItems.erase(connection, {
      cartId: cartCreateRes.id,
      cartItemId: nonExistentCartItemId,
    })
  );
}

