import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderStatusHistory";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates that an admin can register a new order status history entry for a valid status transition.
 *
 * Business context:
 * - Status histories are a crucial audit trail for workflow actions on customer orders. Admins may record changes such as payment confirmation or shipping events, and these should accurately reflect in the order's audit history with proper actor metadata.
 *
 * Workflow:
 * 1. Register an admin user.
 * 2. Register a customer.
 * 3. Place an order as the customer.
 * 4. Using admin privileges, issue an order status transition (e.g., from 'pending' to 'paid').
 * 5. Validate the response: fields previous_status, new_status, actor_type, actor_id, occurred_at. Confirm that actor_type is 'admin', and that 'before' and 'after' statuses and audit fields are correct.
 */
export async function test_api_admin_create_order_status_history_valid_transition(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "Password_1234";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);
  const adminId = adminSignUp.adminId;

  // 2. Register a customer
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "CusTomer@4567",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  const customer = customerSignUp.customer;

  // 3. Place an order as the customer (switch connection to customer session)
  const prevAuthorization = connection.headers?.Authorization;
  connection.headers = {
    ...connection.headers,
    Authorization: customerSignUp.setHeaders.Authorization,
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customer.id,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 50000,
      currency_code: "KRW",
      current_status: "pending",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(order);
  const orderId = order.id;
  const previousStatus = order.current_status;

  // 4. Switch back to admin session for status update
  connection.headers = {
    ...connection.headers,
    Authorization: adminSignUp.setHeaders.Authorization,
  };
  const newStatus = "paid";
  const occurredAt = new Date().toISOString();
  const statusHistory = await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.create(connection, {
    orderId,
    body: {
      previous_status: previousStatus,
      new_status: newStatus,
      actor_type: "admin",
      actor_id: adminId,
      event_context: "Payment confirmed by admin for testing",
      occurred_at: occurredAt,
    } satisfies IShoppingMallAiBackendOrderStatusHistory.ICreate,
  });
  typia.assert(statusHistory);

  // 5. Validate status history fields and business logic
