import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that a seller can successfully retrieve the details of an order status history record for an order they own.
 *
 * Business context: Sellers must be able to audit the workflow and track all state changes for orders associated with their products. This test ensures compliance, auditability, and correct application of business access controls.
 *
 * Steps:
 * 1. Register a seller account (to own product/orders).
 * 2. Register a product for this seller.
 * 3. Register a customer account (to place the order).
 * 4. Place an order as the customer for the seller's product (and get order ID).
 * 5. As the seller, update the status of the order – this will create a status history record.
 * 6. Retrieve the status history record by orderId and statusHistoryId as the seller.
 * 7. Assert that all important fields (before/after status, actor_type, actor_id, context, occurred_at) are correct and match the generated record.
 */
export async function test_api_order_status_history_detail_retrieval_by_seller_success(connection: api.IConnection) {
  // 1. Register seller
  const seller_signup = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "securePass!23",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    }
  });
  typia.assert(seller_signup);
  // Set seller's authentication context
  connection.headers = { ...connection.headers, Authorization: seller_signup.setHeaders.Authorization };
  const seller_id = seller_signup.sellerId;

  // 2. Register product for seller
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.content()()(1),
      main_image_uri: null,
      status: "published"
    }
  });
  typia.assert(product);

  // 3. Register customer
  const customer_signup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "customerPW#1",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(10),
      phone: RandomGenerator.mobile()
    }
  });
  typia.assert(customer_signup);
  const customer = customer_signup.customer;
  // Switch to customer session
  connection.headers = { ...connection.headers, Authorization: customer_signup.setHeaders.Authorization };

  // 4. Customer places an order for the seller's product
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customer.id,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 59900,
      currency_code: "KRW",
      current_status: "created"
    }
  });
  typia.assert(order);
  // Save order id
  const order_id = order.id;

  // 5. Switch back to seller session for status update
  connection.headers = { ...connection.headers, Authorization: seller_signup.setHeaders.Authorization };

  // 6. Seller updates (changes) the order status -- create status history
  const status_before = order.current_status;
  const status_after = "paid";
  const event_context = "Payment received via gateway";
  const status_history = await api.functional.shoppingMallAiBackend.seller.orders.orderStatusHistories.create(connection, {
    orderId: order_id,
    body: {
      previous_status: status_before,
      new_status: status_after,
      actor_type: "seller",
      actor_id: seller_id,
      event_context,
      occurred_at: new Date().toISOString()
    }
  });
  typia.assert(status_history);

  // 7. Seller requests details of this status change
  const result = await api.functional.shoppingMallAiBackend.seller.orders.orderStatusHistories.at(connection, {
    orderId: order_id,
    orderStatusHistoryId: status_history.id
  });
  typia.assert(result);
  // 8. Assert field correctness
  TestValidator.equals("orderId matches")(result.order_id)(order_id);
  TestValidator.equals("previous_status matches")(result.previous_status)(status_before);
  TestValidator.equals("new_status matches")(result.new_status)(status_after);
  TestValidator.equals("actor_type is seller")(result.actor_type)("seller");
  TestValidator.equals("actor_id matches")(result.actor_id)(seller_id);
  TestValidator.equals("event_context matches")(result.event_context)(event_context);
  TestValidator.equals("occurred_at matches")(result.occurred_at)(status_history.occurred_at);
}

