import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSnapshot";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates admin access to product snapshot details (regardless of product owner).
 *
 * This test verifies that an authenticated admin user can retrieve the full details of a product snapshot—
 * even if that product does not belong to them. This ensures the evidence/audit system remains accessible
 * to platform admins for compliance, analytics, or legal scenarios. The following real-world sequence is simulated:
 *
 * 1. An admin account is registered/authenticated (sets up the Authorization header for admin privileges)
 * 2. A seller account is registered/authenticated (separate credentials)
 * 3. The seller creates a new product
 * 4. The seller captures a product snapshot as evidence
 * 5. The admin requests the detail for that snapshot using the platform-admin endpoint
 *
 * Each step includes strict type/data validation to guarantee that entities exist and are correctly linked.
 * The admin's ability to retrieve the snapshot is confirmed by strict field validation, ensuring audit/evidence
 * fields are present, match the details created, and that platform permissions work as intended.
 */
export async function test_api_product_snapshot_detail_access_by_admin_success(
  connection: api.IConnection
) {
  // 1. Register admin (platform administrator for test)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminTestPW!123";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(admin);

  // 2. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "sellerTestPW!456";
  const seller = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: "AI Demo Seller LLC",
      businessNumber: "1234567890",
      representativeName: "Jane Seller",
      address: "42 Example Road, Cloud District",
      phone: "010-1234-5678"
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(seller);

  // 3. Seller creates a product (must use their sellerId)
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: seller.sellerId,
      code: "SKU-" + typia.random<string>(),
      name: "Snapshot Admin Access Test Product",
      description: "Product created for verifying admin snapshot access.",
      main_image_uri: null,
      status: "published"
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 4. Seller creates a snapshot for the product
  const snapshot = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      snapshot_code: "v1.0.0",
      snapshot_type: "created",
      name: product.name,
      description: product.description,
      main_image_uri: product.main_image_uri,
      status: product.status
    } satisfies IShoppingMallAiBackendProductSnapshot.ICreate
  });
  typia.assert(snapshot);

  // 5. Swap session to admin before admin API usage
  connection.headers = { ...connection.headers, Authorization: admin.setHeaders.Authorization };

  // 6. Admin retrieves the full product snapshot detail
  const output = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.at(connection, {
    productId: product.id,
    productSnapshotId: snapshot.id
  });
  typia.assert(output);
  TestValidator.equals("snapshot id matches")(output.id)(snapshot.id);
  TestValidator.equals("product id matches")(output.product_id)(product.id);
  TestValidator.equals("snapshot code matches")(output.snapshot_code)(snapshot.snapshot_code);
  TestValidator.equals("snapshot type matches")(output.snapshot_type)(snapshot.snapshot_type);
  TestValidator.equals("name matches")(output.name)(snapshot.name);
  TestValidator.equals("description matches")(output.description)(snapshot.description);
  TestValidator.equals("main image uri matches")(output.main_image_uri)(snapshot.main_image_uri);
  TestValidator.equals("status matches")(output.status)(snapshot.status);
  TestValidator.predicate("created_at is present string")(typeof output.created_at === "string");
}

