import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that updating a seller's profile via the admin endpoint fails on invalid data.
 *
 * This test ensures that the admin update fails when:
 * - the payload includes a duplicate `business_number` (matching another seller)
 * - the payload uses a malformed or empty `company_name`
 * - the payload is missing required fields (e.g., omits the `id`)
 *
 * Validation errors should be triggered and no unintended/partial updates occur.
 * Note: Profile readback is omitted as no GET endpoint is provided.
 *
 * Steps:
 * 1. Register an admin account.
 * 2. Log in as that admin (JWT set on connection).
 * 3. Register a first seller.
 * 4. Register a second seller (for duplication test).
 * 5. Try to update the first seller with (a) a duplicate business_number, (b) malformed company_name, and (c) missing required field.
 * 6. Ensure all invalid cases trigger proper errors.
 */
export async function test_api_admin_update_seller_profile_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin@12345!";
  const adminResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminResult);

  // 2. Admin login
  const loginResult = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(loginResult);

  // 3. Register first seller
  const seller1Email = typia.random<string & tags.Format<"email">>();
  const seller1 = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller1Email,
      password: "Seller1Pass@123",
      companyName: "Test Company 1",
      businessNumber: typia.random<string>(),
      representativeName: "Alice Admin",
      address: "123 Main Street",
      phone: "010-1111-2222",
    },
  });
  typia.assert(seller1);

  // 4. Register second seller (for duplicate business_number)
  const seller2Email = typia.random<string & tags.Format<"email">>();
  const duplicateBusinessNumber = typia.random<string>();
  const seller2 = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller2Email,
      password: "Seller2Pass@123",
      companyName: "Test Company 2",
      businessNumber: duplicateBusinessNumber,
      representativeName: "Bob Manager",
      address: "987 Side Avenue",
      phone: "010-3333-4444",
    },
  });
  typia.assert(seller2);

  // 5a. Attempt to update seller1 with duplicate business number
  await TestValidator.error("duplicate business_number should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.sellers.update(connection, {
      body: {
        id: seller1.sellerId,
        business_number: duplicateBusinessNumber,
      },
    });
  });

  // 5b. Attempt to update seller1 with malformed company_name
  await TestValidator.error("malformed company_name should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.sellers.update(connection, {
      body: {
        id: seller1.sellerId,
        company_name: "",
      },
    });
  });

  // 5c. Attempt to update with missing required id (compile error normally; tested for runtime)
  await TestValidator.error("missing id should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.sellers.update(connection, {
      body: {
        company_name: "Should Fail",
      } as any,
    });
  });
  // 6. No readback possible (no GET endpoint present)
}

