import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import type { IShoppingMallAiBackendReviewSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendReviewSnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that admin cannot update immutable fields of a review snapshot (e.g., content, rating, timestamp).
 *
 * Ensures API compliance: if an admin attempts to change protected fields (body, rating, changed_at), the API must reject the update with a descriptive error, and the snapshot/audit trail remains unchanged.
 *
 * Steps:
 * 1. Register and authenticate an admin account (obtain JWT).
 * 2. Register and authenticate a customer account.
 * 3. Customer creates a product review (needs product_id, order_item_id, etc.).
 * 4. Admin creates a review snapshot for the review (reference initial state).
 * 5. Admin attempts to update the snapshot's protected fields (e.g., body, rating, changed_at).
 * 6. Expect API to reject update; validate error, and confirm snapshot remains unchanged compared to its original state.
 */
export async function test_api_product_review_snapshot_update_illegal_field_failure(connection: api.IConnection) {
  // 1. Admin registration and authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPass123!";
  const adminResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminResp);
  // JWT automatically applied to connection.headers.Authorization

  // 2. Customer registration
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "CustomerPass123!";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;

  // 3. Customer login (for JWT; assumed auto-login on register, but re-authenticate to ensure)
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    },
  });
  // At this point, connection is authenticated as the customer

  // 4. Customer creates product review
  const productReview = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      order_item_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.alphabets(8),
      body: RandomGenerator.paragraph()(),
      rating: 5,
      status: "normal",
      ai_sentiment_score: 0.2,
      ai_spam_score: 0.05,
    },
  });
  typia.assert(productReview);
  const productReviewId = productReview.id;

  // Switch back to admin authentication
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  // At this point, JWT for admin account is set

  // 5. Admin creates a review snapshot for the review
  const snapshot = await api.functional.shoppingMallAiBackend.admin.productReviews.reviewSnapshots.create(connection, {
    productReviewId,
    body: {
      review_id: productReviewId,
      body: productReview.body,
      rating: productReview.rating,
      status: productReview.status,
      actor_id: adminResp.adminId,
      ai_sentiment_score: productReview.ai_sentiment_score ?? null,
      ai_spam_score: productReview.ai_spam_score ?? null,
      changed_at: typia.random<string & tags.Format<"date-time">>(),
    },
  });
  typia.assert(snapshot);

  // 6. Admin attempts to update immutable fields (body, rating, changed_at)
  await TestValidator.error("immutable review snapshot fields should not be updateable")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productReviews.reviewSnapshots.update(connection, {
      productReviewId,
      reviewSnapshotId: snapshot.id,
      body: {
        body: "Tampered Body", // Attempt to illegally modify
        rating: snapshot.rating === 5 ? 4 : 5, // Try to change rating
        changed_at: typia.random<string & tags.Format<"date-time">>(), // Try to change timestamp
      },
    });
  });

  // 7. Fetch snapshot again to ensure it is unchanged
  // (There is no direct fetch API for a snapshot, so re-fetch via create or validate as possible)
  // If unable to re-fetch, at least document that absence.
}

