import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that attempting to delete a favorite snapshot (by admin) that has already been soft-deleted returns a proper error or safe idempotent response.
 *
 * Business context:
 * - Favorite snapshots provide audit, rollback, or evidentiary records.
 * - Snapshots must not be physically removed, but should be soft-deleted (marked deleted).
 * - Deleting an already soft-deleted snapshot should NOT permanently alter state, must not error fatally, and should respond cleanly (ideally with idempotent not found or already-deleted indication).
 *
 * Step-by-step process:
 * 1. Register a new customer (so a customer can have favorites).
 * 2. As the customer, favorite a random product (use random UUID for product).
 * 3. As the customer, create a favorite snapshot for this favorite product.
 * 4. As admin, delete the favorite snapshot—this performs the first (valid) deletion.
 * 5. Immediately attempt to delete the same snapshot again (simulate double-deletion).
 * 6. Validate that the second deletion does not return a fatal error, but either (a) responds with a clean error code (such as not found or already deleted), or (b) is a no-op (idempotent safe deletion behavior as per API contract).
 *
 * The test validates safe data management for admin double-deletion workflows, ensuring auditing and compliance integrity for soft-deleted favorite snapshots.
 */
export async function test_api_favorite_snapshot_admin_delete_fail_on_already_deleted(
  connection: api.IConnection,
) {
  // 1. Register a customer who can favorite products
  const customerSignUpEmail: string = typia.random<string & tags.Format<"email">>();
  const signUpResult = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerSignUpEmail,
      password: "pw1234!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpResult);

  // 2. As customer, mark a product as favorite
  const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(favoriteProduct);

  // 3. Create a favorite snapshot for the favorite product
  const snapshot = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: {
      favorite_product_id: favoriteProduct.id,
      favorite_inquiry_id: null,
      favorite_address_id: null,
      target_type: "PRODUCT",
      snapshot_object_id: favoriteProduct.product_id,
      serialized_object: JSON.stringify({ id: favoriteProduct.product_id }),
    },
  });
  typia.assert(snapshot);

  // 4. As admin, delete the favorite snapshot for the first time (should succeed)
  await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.erase(connection, {
    favoriteSnapshotId: snapshot.id,
  });

  // 5. Attempt to delete the same favorite snapshot again (should produce safe error or idempotent result)
  await TestValidator.error("Deleting already deleted snapshot must not succeed twice")(() =>
    api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.erase(connection, {
      favoriteSnapshotId: snapshot.id,
    })
  );
}

