/**
 * Test seller inquiry update – answering product inquiry flow
 *
 * This test covers the end-to-end process for a seller to update one of their product inquiries, adding an answer and setting status to 'answered'.
 *
 * - Step 1: Seller registers and receives authentication.
 * - Step 2: Seller creates a product, which becomes inquiry-eligible.
 * - Step 3: Customer registers and is authenticated.
 * - Step 4: Customer submits a product inquiry for the above product.
 * - Step 5: Seller updates the inquiry (answers), changing its status to 'answered' and confirming the update is correct in response.
 * - Step 6: Validates that inquiry state reflects the answer and status change.
 */
export async function test_api_seller_product_inquiry_update_seller_response(connection: api.IConnection) {
  // 1. Seller registration (get ID & JWT)
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "TestPw1234!";
  const sellerReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(20),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerReg);
  TestValidator.equals("email")(sellerReg.email)(sellerEmail);

  // Mutate connection with seller JWT
  connection.headers = { ...(connection.headers ?? {}), Authorization: sellerReg.setHeaders.Authorization };

  // 2. Seller creates product
  const productCreate = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerReg.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(20),
      main_image_uri: null,
      status: "published", // Assume valid status for test
    },
  });
  typia.assert(productCreate);
  TestValidator.equals("seller-id")(productCreate.seller_id)(sellerReg.sellerId);

  // 3. Customer registration (get JWT)
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "CusPw1234!";
  const customerReg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerReg);
  TestValidator.equals("customer email")(customerReg.customer.email)(customerEmail);

  // Switch connection to customer JWT
  connection.headers = { ...(connection.headers ?? {}), Authorization: customerReg.setHeaders.Authorization };

  // 4. Customer creates product inquiry
  const inquiryCreate = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerReg.customer.id,
      product_id: productCreate.id,
      title: "Question about product",
      body: "Is this product waterproof?",
      public: true,
    },
  });
  typia.assert(inquiryCreate);
