  // 5. Switch back to seller JWT for response
  connection.headers = { ...(connection.headers ?? {}), Authorization: sellerReg.setHeaders.Authorization };

  // 6. Seller updates inquiry by setting status to 'answered' and adds an answer (answer_id simulated)
  const updatedInquiry = await api.functional.shoppingMallAiBackend.seller.productInquiries.update(connection, {
    productInquiryId: inquiryCreate.id,
    body: {
      status: "answered",
    },
  });
  typia.assert(updatedInquiry);
  TestValidator.equals("status is answered")(updatedInquiry.status)("answered");
  TestValidator.equals("same inquiry id")(updatedInquiry.id)(inquiryCreate.id);
  TestValidator.equals("product id matches")(updatedInquiry.product_id)(productCreate.id);
  TestValidator.equals("customer id matches")(updatedInquiry.customer_id)(customerReg.customer.id);
  // At this point, the update should be audit-logged as per API guarantee.
}

