import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate repeated deletion (idempotent soft delete) of a customer favorite snapshot
 *
 * This test ensures that a soft-deleted (logically deleted) favorite snapshot cannot be deleted again and that the API properly enforces idempotency/compliance with logical deletion protocols.
 * Business context: A favorite snapshot is created for compliance/evidence/audit when a customer favorites a product. Logical deletion allows audit trails to persist, and repeated delete attempts must yield a proper response (error or idempotent not found) rather than performing a hard delete or breaking consistency.
 *
 * Step-by-step process:
 * 1. Register a new customer (simulate login-authorization via returned JWT in setHeaders)
 * 2. Create a favoriteProducts entry (mark a product as favorite for this customer)
 * 3. Create a favoriteSnapshots record for the product-favorite
 * 4. Perform a DELETE (soft delete) on the favorite snapshot
 * 5. Attempt a second DELETE for the same snapshot id (should yield an error, typically NotFound or no-op response)
 * 6. Validate that the error is thrown as expected (using TestValidator.error)
 */
export async function test_api_favorite_snapshot_delete_fail_on_already_deleted(connection: api.IConnection) {
  // 1. Register customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "pAssw0rd123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerRes);

  // After registration, token issued automatically. All subsequent calls use the same connection object (token in headers)

  // 2. Mark a random product as favorite (simulate with random product_id)
  const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate,
  });
  typia.assert(favoriteProduct);

  // 3. Create a favorite snapshot for the favorite product
  const serializedObject = JSON.stringify({ product_id: favoriteProduct.product_id });
  const snapshot = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: {
      favorite_product_id: favoriteProduct.id,
      favorite_inquiry_id: null,
      favorite_address_id: null,
      target_type: "PRODUCT",
      snapshot_object_id: favoriteProduct.product_id,
      serialized_object: serializedObject,
    } satisfies IShoppingMallAiBackendFavoriteSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 4. Soft delete (logical delete) the favorite snapshot
  await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.erase(connection, {
    favoriteSnapshotId: snapshot.id,
  });

  // 5. Attempt to soft-delete again (expected: error)
  await TestValidator.error("second soft delete must fail")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.erase(connection, {
      favoriteSnapshotId: snapshot.id,
    })
  );
}

