 * 2. Log in as that seller
 * 3. Create a new product as the seller
 * 4. Create a valid channel as the admin (needed for the mapping)
 * 5. Map the product to the channel as the seller
 * 6. Perform a DELETE (soft-delete) for the product-channel mapping as the seller
 * 7. (Validation step) Attempt to use the API to fetch active mappings/products/channels as seller and verify the mapping is no longer present (i.e., deleted_at is set)
 * 8. (Compliance evidence) Confirm soft-deleted mapping still exists in data
 */
export async function test_api_product_channel_map_soft_delete_by_seller(connection: api.IConnection) {
  // 1. Register a seller account
  const sellerEmail: string = typia.random<string & tags.Format<"email">>()
