  // 2. Log in as that seller
  const signInOutput = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    },
  });
  typia.assert(signInOutput);

  // 3. Create a new product as the seller
  const productCreateInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: signUpOutput.sellerId,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.content()()(1),
    main_image_uri: null,
    status: "published",
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: productCreateInput,
  });
  typia.assert(product);

  // 4. Create a valid channel as the admin. (simulate admin context by directly calling function, no login)
  const adminId: string = typia.random<string & tags.Format<"uuid">>()
  const channelCreateInput: IShoppingMallAiBackendChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(6),
