import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that customers cannot update their favorite snapshots via the admin update endpoint.
 *
 * This test simulates a business scenario where a user attempts to update the state of their own favorite snapshot using an endpoint reserved for admin-level operations. It ensures that security boundaries are enforced: only administrators may alter favoriteSnapshots through this admin API, and end-customers are strictly forbidden from such actions.
 *
 * Steps:
 * 1. Register a new customer (obtains an authenticated customer connection)
 * 2. Create a favorite product for this customer
 * 3. Create a favorite snapshot associated with this favorite product
 * 4. As the same customer, attempt to call the admin favorite snapshot update endpoint
 * 5. Assert that the action is forbidden (proper error is thrown)
 */
export async function test_api_favorite_snapshot_update_forbidden_for_non_admin(connection: api.IConnection) {
  // 1. Register a customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "pass-" + RandomGenerator.alphaNumeric(8);
  const result = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(10),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(result);
  // The connection is now authorized as this customer

  // 2. Create a favorite product for this customer
  const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(favoriteProduct);

  // 3. Create a favorite snapshot for this favorite product
  const favoriteSnapshot = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: {
      favorite_product_id: favoriteProduct.id,
      favorite_inquiry_id: null,
      favorite_address_id: null,
      target_type: "PRODUCT",
      snapshot_object_id: favoriteProduct.product_id,
      serialized_object: JSON.stringify({ favoriteProduct }),
    },
  });
  typia.assert(favoriteSnapshot);

  // 4. As the customer, attempt to update the favorite snapshot using the admin endpoint
  await TestValidator.error("customer cannot update favoriteSnapshot as admin")(
    () => api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.update(connection, {
      favoriteSnapshotId: favoriteSnapshot.id,
      body: {
        serialized_object: JSON.stringify({ corrected: true }),
      },
    })
  );
}

