import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates admin audit access to full product inquiry detail.
 *
 * Ensures that an admin can: (1) register, (2) product and inquiry are created, and (3) the admin retrieves all fields from a product inquiry regardless of ownership for audit and compliance. Checks all main and audit fields (AI scoring, status, public flag, answer reference, timestamps, customer/product IDs).
 *
 * 1. Register an admin to get admin access.
 * 2. Register a seller (used to create a product).
 * 3. Register a customer (who will later submit the inquiry).
 * 4. As the seller, register a product to be inquired about.
 * 5. As the customer, create a product inquiry on that product.
 * 6. Switch to admin context and fetch the inquiry by its ID using admin endpoint.
 * 7. Assert that all fields returned match the created inquiry, and critical audit/AI/status fields are present and populated as expected.
 */
export async function test_api_admin_product_inquiry_detail_audit_access(connection: api.IConnection) {
  // 1. Register admin (for audit access)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin!1234";
  const adminRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminRes);

  // 2. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Seller!1234";
  const sellerRes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: "AutoTest Seller",
      businessNumber: `${typia.random<string>().slice(0,10)}`,
      representativeName: "Test Owner",
      address: "123 AutoTest St, TestCity",
      phone: "01012345678"
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerRes);
  const sellerId = sellerRes.sellerId;

  // 3. Register customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Customer!1234";
  const customerRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: "AutoTest Customer",
      nickname: "auto_cust",
      phone: "01087654321",
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerRes);
  const customerId = customerRes.customer.id;

  // 4. Seller creates product
  // Use the seller's JWT for authentication
  connection.headers["Authorization"] = sellerRes.setHeaders.Authorization;
  const productCode = `SKU-${typia.random<string>().slice(0,8)}`;
  const productRes = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: "Test Product For Inquiry",
      description: "Description for audit test product.",
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productRes);
  const productId = productRes.id;

  // 5. Customer creates inquiry on the product
  // Switch to customer JWT
  connection.headers["Authorization"] = customerRes.setHeaders.Authorization;
  const inquiryTitle = "Test Inquiry For Audit";
  const inquiryBody = "Does this product support audit logging?";
  const inquiryRes = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: productId,
      title: inquiryTitle,
      body: inquiryBody,
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
  });
  typia.assert(inquiryRes);
  const inquiryId = inquiryRes.id;

  // 6. Admin retrieves the inquiry by ID for audit
  // Switch back to admin JWT
  connection.headers["Authorization"] = adminRes.setHeaders.Authorization;
  const got = await api.functional.shoppingMallAiBackend.admin.productInquiries.at(connection, {
    productInquiryId: inquiryId,
  });
  typia.assert(got);

  // 7. Validate all key fields match and audit/Ai/status fields are present
  TestValidator.equals("customer_id")(got.customer_id)(customerId);
  TestValidator.equals("product_id")(got.product_id)(productId);
  TestValidator.equals("title")(got.title)(inquiryTitle);
  TestValidator.equals("body")(got.body)(inquiryBody);
  TestValidator.equals("public")(got.public)(true);
  // Audit/status/AI fields should be present (not necessarily non-null for AI fields)
  TestValidator.equals("status is string")(typeof got.status)("string");
  TestValidator.equals("created_at is ISO date")(!!Date.parse(got.created_at))(true);
  TestValidator.equals("updated_at is ISO date")(!!Date.parse(got.updated_at))(true);
  // AI fields: nullable, but key exists
  TestValidator.predicate("ai_sentiment_score key exists")("ai_sentiment_score" in got);
  TestValidator.predicate("ai_spam_score key exists")("ai_spam_score" in got);
  // answer_id and deleted_at are optional (nullable)
  TestValidator.predicate("answer_id key exists")("answer_id" in got);
  TestValidator.predicate("deleted_at key exists")("deleted_at" in got);
}

