 * 3. Attempt to create a transaction with a reference to a non-existent point wallet. Confirm error is returned.
 * 4. Attempt to create a transaction with missing required fields. Confirm error is returned.
 * 5. Attempt to create a duplicate transaction (if possible under business rules). Confirm error is returned or business logic prevents creation.
 * 6. Optionally, test out-of-bounds balance adjustment and confirm explicit error is returned.
 */
export async function test_api_point_history_creation_success_and_duplicate_validation(
  connection: api.IConnection,
) {
  // 1. Create a customer point wallet as admin precondition
  const walletInput: IShoppingMallAiBackendPoint.ICreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
