import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that an admin can soft/hard delete an order status history record with proper compliance.
 *
 * Business/Workflow:
 * - Order status history records must be deletable by an admin (via API), who is authenticated.
 * - The deleted record should either:
 *     a) Be soft deleted (deleted_at timestamp updated), or
 *     b) Be hard deleted (removed from returned view/database/query).
 *
 * Steps:
 * 1. Register an admin (get adminId/JWT).
 * 2. Register a customer.
 * 3. As customer, create a valid order (get orderId).
 * 4. As customer, create an order status history record (get orderStatusHistoryId).
 * 5. As admin, call the erase endpoint targeting that orderStatusHistory record.
 * 6. Validate successful deletion: If soft delete, confirm "deleted_at" on the record is non-null (by business design). If hard delete, ensure a subsequent query (if supported) no longer shows the record. Either way, deletion should not throw errors; operation must be audit/compliance-eligible.
 * 7. Attempt to delete a non-existent record: Ensure meaningful error (not found).
 * 8. Attempt to delete same record again: Ensure already-deleted error or no-op.
 * 9. Negative: Try erase as a customer (non-admin): Should be forbidden.
 */
export async function test_api_order_status_history_erase_soft_delete_and_compliance(connection: api.IConnection) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, { body: { email: adminEmail, password: "1234pass" } });
  typia.assert(adminSignUp);

  // 2. Register a customer
  const customerSignUpBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "pw12341234",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.name(),
    phone: RandomGenerator.mobile()
  } satisfies ICustomerSignUp.Request;
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, { body: customerSignUpBody });
  typia.assert(customerSignUp);

  // Switch to customer session
  connection.headers = { ...connection.headers, Authorization: customerSignUp.setHeaders.Authorization };
  const customerId = customerSignUp.customer.id;

  // 3. Create an order for that customer
  const createOrderBody = {
    customer_id: customerId,
    order_group_id: null,
    order_number: `ORD-${Date.now()}`,
    total_amount: 7000,
    currency_code: "KRW",
    note: "test order",
    current_status: "created"
  } satisfies IShoppingMallAiBackendOrder.ICreate;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: createOrderBody });
  typia.assert(order);
  const orderId = order.id;

  // 4. Create an order status history for the order
  const now = new Date().toISOString();
  const orderStatusCreateBody = {
    previous_status: "created",
    new_status: "processing",
    actor_type: "customer",
    actor_id: customerId,
    event_context: "Initial processing stage",
    occurred_at: now
  } satisfies IShoppingMallAiBackendOrderStatusHistory.ICreate;
  const history = await api.functional.shoppingMallAiBackend.customer.orders.orderStatusHistories.create(connection, { orderId, body: orderStatusCreateBody });
  typia.assert(history);
  const orderStatusHistoryId = history.id;

