  await TestValidator.error("Re-delete already deleted history")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.erase(connection, {
        orderId, orderStatusHistoryId
      });
    }
  );

  // 9. Try delete as customer (unauthorized): forbidden
  connection.headers = { ...connection.headers, Authorization: customerSignUp.setHeaders.Authorization };
  await TestValidator.error("Customer cannot erase status history")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.erase(connection, {
        orderId, orderStatusHistoryId
      });
    }
  );
}

