  // 3.1. Try to create product missing name
  await TestValidator.error("missing name is rejected")(() =>
    api.functional.shoppingMallAiBackend.seller.products.create(connection, {
      body: {
        seller_id: sellerId,
        code: RandomGenerator.alphaNumeric(10),
        // name: intentionally omitted
        status: "draft",
      } as any,
    })
  );

  // 3.2. Try to create product missing code
  await TestValidator.error("missing code is rejected")(() =>
    api.functional.shoppingMallAiBackend.seller.products.create(connection, {
      body: {
        seller_id: sellerId,
        name: RandomGenerator.paragraph()(2),
        // code: intentionally omitted
        status: "draft",
      } as any,
    })
  );

  // 3.3. Try to create product missing status
