    api.functional.shoppingMallAiBackend.seller.products.create(connection, {
      body: {
        seller_id: sellerId,
        code: RandomGenerator.alphaNumeric(10),
        name: RandomGenerator.paragraph()(2),
        // status: intentionally omitted
      } as any,
    })
  );

  // 3.4. Try blank/empty strings for required fields
  await TestValidator.error("blank name is rejected")(() =>
    api.functional.shoppingMallAiBackend.seller.products.create(connection, {
      body: {
        seller_id: sellerId,
        code: RandomGenerator.alphaNumeric(10),
        name: "",
        status: "draft",
      } as any,
    })
  );
  await TestValidator.error("blank code is rejected")(() =>
    api.functional.shoppingMallAiBackend.seller.products.create(connection, {
      body: {
        seller_id: sellerId,
        code: "",
        name: RandomGenerator.paragraph()(2),
        status: "draft",
      } as any,
    })
  );
  await TestValidator.error("blank status is rejected")(() =>
    api.functional.shoppingMallAiBackend.seller.products.create(connection, {
      body: {
        seller_id: sellerId,
        code: RandomGenerator.alphaNumeric(10),
        name: RandomGenerator.paragraph()(2),
        status: "",
      } as any,
    })
  );
}

