import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSellerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSellerHistory";
import type { IPageIShoppingMallAiBackendSellerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSellerHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate admin's advanced search/filter functionality for seller audit/history records.
 *
 * This test covers the business workflow that:
 * - Ensures at least one seller exists and has multiple diverse history events (e.g., registration, login)
 * - Registers and logs in as an admin (to get admin JWT)
 * - Uses the protected PATCH /shoppingMallAiBackend/admin/sellers/{sellerId}/histories endpoint to perform various searches:
 *   1. No filters (returns all), validate results and pagination meta
 *   2. Filter by event type (e.g., login or registered). All results must match the event_type
 *   3. Filter by occurred_at date range (returns only matching)
 *   4. Pagination behavior (limit/page)
 *   5. Edge: empty results set
 *   6. Error: attempt search with a non-admin or invalid/empty token, must receive error
 *   7. Error: attempt search for a sellerId that doesn't exist, should receive empty results or a handled error
 *
 *   Each result contains audit info (event_type, occurred_at, triggered_by, meta). Event field matching and meta verification is included.
 *
 * Steps:
 * 1. Register and login as admin (obtain Authorization)
 * 2. Register a seller
 * 3. Seller logs in (ensures at least 2+ history events for seller)
 * 4. Admin: search seller's histories (various filters)
 * 5. Validate filtering, pagination, edge and error cases
 */
export async function test_api_admin_seller_history_advanced_search(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Password123!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);
  TestValidator.equals("admin email")(adminSignUp.email)(adminEmail);

  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);
  TestValidator.equals("admin login email")(adminSignIn.email)(adminEmail);

  // 2. Register a seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "SellerPassword1!";
  const sellerReq: ISellerAuth.SignUp = {
    email: sellerEmail,
    password: sellerPassword,
    companyName: "Test Company",
    businessNumber: "1234567890",
    representativeName: "Test Rep",
    address: "123 Test St, City",
    phone: "010-1234-5678"
  };
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: sellerReq
  });
  typia.assert(sellerSignUp);
  TestValidator.equals("seller email after signup")(sellerSignUp.email)(sellerEmail);

  // 3. Seller logs in to generate login event
  const sellerSignIn = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(sellerSignIn);
  TestValidator.equals("sellerId after login")(sellerSignIn.sellerId)(sellerSignUp.sellerId);
  const sellerId = sellerSignIn.sellerId;

  // 4. Admin: search seller's histories - all
  // Note: Already authenticated as admin, so no manual header management is needed.
  const allHistories = await api.functional.shoppingMallAiBackend.admin.sellers.histories.search(connection, {
    sellerId,
    body: {
      seller_id: sellerId
    } satisfies IShoppingMallAiBackendSellerHistory.IRequest
  });
  typia.assert(allHistories);
  TestValidator.equals("sellerId in results matches")(allHistories.data.length === 0 ? sellerId : allHistories.data[0].seller_id)(sellerId);

  // 5. Filter by event type (if there are known ones)
  if (allHistories.data.length > 0) {
    const someEventType = allHistories.data[0].event_type;
    const filteredByType = await api.functional.shoppingMallAiBackend.admin.sellers.histories.search(connection, {
      sellerId,
      body: {
        seller_id: sellerId,
        event_type: someEventType
      }
    });
    typia.assert(filteredByType);
    for (const item of filteredByType.data) {
      TestValidator.equals("event_type matches")(item.event_type)(someEventType);
    }
  }

  // 6. Filter by occurred_at (date range)
  if (allHistories.data.length > 0) {
    const dates = allHistories.data
      .map(r => r.occurred_at)
      .sort();
    const minDate = dates[0];
    const maxDate = dates[dates.length - 1];
    const byDateRange = await api.functional.shoppingMallAiBackend.admin.sellers.histories.search(connection, {
      sellerId,
      body: {
        seller_id: sellerId,
        occurred_from: minDate,
        occurred_to: maxDate
      }
    });
    typia.assert(byDateRange);
    for (const row of byDateRange.data) {
      TestValidator.predicate("occurred_at >= from")(row.occurred_at.localeCompare(minDate) >= 0);
      TestValidator.predicate("occurred_at <= to")(row.occurred_at.localeCompare(maxDate) <= 0);
    }
  }

  // 7. Pagination test
  const paged = await api.functional.shoppingMallAiBackend.admin.sellers.histories.search(connection, {
    sellerId,
    body: {
      seller_id: sellerId,
      page: 1,
      limit: 1
    }
  });
  typia.assert(paged);
  TestValidator.equals("paged limit")(paged.pagination.limit)(1);
  TestValidator.equals("paged current")(paged.pagination.current)(1);

  // 8. Empty set (page out of bounds)
  const emptyPage = await api.functional.shoppingMallAiBackend.admin.sellers.histories.search(connection, {
    sellerId,
    body: {
      seller_id: sellerId,
      page: 100,
      limit: 1
    }
  });
  typia.assert(emptyPage);
  TestValidator.equals("empty set on high page")(emptyPage.data.length)(0);

  // 9. Error: Unauthenticated (simulate by clearing Authorization)
  // We clone the connection and manually clear Authorization to simulate a logged-out state
  const cloneConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthenticated admin is not allowed")(async () =>
    api.functional.shoppingMallAiBackend.admin.sellers.histories.search(cloneConn, {
      sellerId,
      body: { seller_id: sellerId }
    })
  );

  // 10. Error: Nonexistent seller
  // Use a UUID that should not overlap any present sellerId
  const fakeSellerId = typia.random<string & tags.Format<"uuid">>();
  const searchFake = await api.functional.shoppingMallAiBackend.admin.sellers.histories.search(connection, {
    sellerId: fakeSellerId,
    body: { seller_id: fakeSellerId }
  });
  typia.assert(searchFake);
  TestValidator.equals("no data for nonexistent seller")(searchFake.data.length)(0);
}

