      reviewSnapshotId,
    })
  );

  // 8. Original seller tries random snapshotId (should be not-found)
  connection.headers = {
    ...connection.headers,
    Authorization: sellerSignUpRes.setHeaders.Authorization,
  };
  await TestValidator.error("not found for random snapshot id")(() =>
    api.functional.shoppingMallAiBackend.seller.productReviews.reviewSnapshots.at(connection, {
      productReviewId,
      reviewSnapshotId: typia.random<string & tags.Format<"uuid">>(),
    })
  );
