import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPayment";
import type { IPageIShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderPayment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test searching for order payment records with filters, pagination, and permissions enforcement.
 *
 * Verifies both successful and error paths in payment record search for customer orders.
 *
 * 1. Register and authenticate a customer (Customer A).
 * 2. Create a valid order for Customer A.
 * 3. Add two distinct payments to this order (with different methods, dates, and statuses).
 * 4. Search payments by orderId (should get both payments, correct pagination, all data).
 * 5. Search payments filtered by payment method and/or status (should get only matching payment(s)).
 * 6. Search with a created_at_from and/or created_at_to filter (filter by date window).
 * 7. Create a second customer (Customer B) and a separate order for Customer B.
 * 8. Attempt to search (as Customer A) for payments from Customer B's order (should fail with permission error).
 * 9. Attempt to search for payments for a non-existent order (should get not found error or empty result, per business logic).
 */
export async function test_api_customer_order_payment_search_success_and_permission_error(connection: api.IConnection) {
  // 1. Register and authenticate Customer A
  const customerAEmail = typia.random<string & tags.Format<"email">>();
  const customerAPassword = RandomGenerator.alphaNumeric(12);
  const signUpA = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerAEmail,
      password: customerAPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(10),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(signUpA);
  // After sign up, session JWT is in connection.headers.Authorization
  const customerA = signUpA.customer;

  // 2. Create order for Customer A
  const orderA = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerA.id,
      order_number: RandomGenerator.alphaNumeric(10),
      total_amount: 10000,
      currency_code: "KRW",
      current_status: "created"
    } satisfies IShoppingMallAiBackendOrder.ICreate
  });
  typia.assert(orderA);

  // 3. Create two payments for the order (one per method/result)
  const payment1 = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: orderA.id,
    body: {
      order_id: orderA.id,
      payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
      payment_method: "card",
      transaction_id: RandomGenerator.alphaNumeric(18),
      amount: 10000,
      currency_code: orderA.currency_code,
      payment_result: "completed",
      payment_context: "first payment - credit card"
    } satisfies IShoppingMallAiBackendOrderPayment.ICreate
  });
  typia.assert(payment1);

  // Intentionally use different payment_method/result/date
  await new Promise(res => setTimeout(res, 1000)); // ensure created_at is different
  const payment2 = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: orderA.id,
    body: {
      order_id: orderA.id,
      payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
      payment_method: "bank_transfer",
      transaction_id: RandomGenerator.alphaNumeric(18),
      amount: 5000,
      currency_code: orderA.currency_code,
      payment_result: "pending",
      payment_context: "second payment - bank transfer"
    } satisfies IShoppingMallAiBackendOrderPayment.ICreate
  });
  typia.assert(payment2);

  // 4. Unfiltered search: Should get both payments
  const searchAll = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.search(connection, {
    orderId: orderA.id,
    body: {
      order_id: orderA.id,
      page: 1,
      limit: 10
    } satisfies IShoppingMallAiBackendOrderPayment.IRequest
  });
  typia.assert(searchAll);
  TestValidator.predicate("Both payments listed as expected")(searchAll.data.length === 2);

  // 5. Filter by payment_method
  const filterByCard = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.search(connection, {
    orderId: orderA.id,
    body: {
      order_id: orderA.id,
      payment_method: "card",
      page: 1,
      limit: 10
    } satisfies IShoppingMallAiBackendOrderPayment.IRequest
  });
  typia.assert(filterByCard);
  TestValidator.predicate("Only card payment returned")(filterByCard.data.length === 1 && filterByCard.data[0].payment_method === "card");

  // 6. Filter by created_at range (only payment2 should match if filtering after payment1's created_at)
  const createdAtFrom = new Date(new Date(payment1.created_at).getTime() + 500).toISOString();
  const filterByTime = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.search(connection, {
    orderId: orderA.id,
    body: {
      order_id: orderA.id,
      created_at_from: createdAtFrom,
      page: 1,
      limit: 10
    } satisfies IShoppingMallAiBackendOrderPayment.IRequest
  });
  typia.assert(filterByTime);
  TestValidator.predicate("Results filtered to payment2 by date")(
    filterByTime.data.length === 1 && filterByTime.data[0].id === payment2.id
  );

  // 7. Register/Authenticate Customer B
  const customerBEmail = typia.random<string & tags.Format<"email">>();
  const customerBPassword = RandomGenerator.alphaNumeric(12);
  const signUpB = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerBEmail,
      password: customerBPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(10),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(signUpB);
  const customerB = signUpB.customer;

  // 8. Create order for Customer B
  const orderB = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerB.id,
      order_number: RandomGenerator.alphaNumeric(10),
      total_amount: 20000,
      currency_code: "KRW",
      current_status: "created"
    } satisfies IShoppingMallAiBackendOrder.ICreate
  });
  typia.assert(orderB);

  // 9. As Customer A, attempt to search payments on Customer B's order (should result in permission error)
  // Session is still as Customer A (no re-authentication to B)
  await TestValidator.error("Should not allow searching another user's order payments")(async () => {
    await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.search(connection, {
      orderId: orderB.id,
      body: {
        order_id: orderB.id,
        page: 1,
        limit: 10
      } satisfies IShoppingMallAiBackendOrderPayment.IRequest
    });
  });

  // 10. Attempt to search payments for a non-existent order
  const fakeOrderId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Searching non-existent order should fail or return empty")(async () => {
    await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.search(connection, {
      orderId: fakeOrderId,
      body: {
        order_id: fakeOrderId,
        page: 1,
        limit: 10
      } satisfies IShoppingMallAiBackendOrderPayment.IRequest
    });
  });
}

