import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPayment";
import type { IShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPaymentLog";
import type { IPageIShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderPaymentLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * End-to-end test for searching order payment logs as a customer
 *
 * This test verifies:
 * - A customer can search payment log records tied to their own order/payment with various filters (log type, date range, paging, etc.)
 * - Filtering by log_type, occurred_at date ranges, and basic paging (page/limit) works as expected
 * - The result set and pagination meta are correct
 * - Logs not matching filter are not present in the result
 * - Unmatched filter returns empty set and pagination is consistent
 * - Malformed filter/pagination input is handled gracefully
 * - Unauthorized access to another customers logs is denied
 *
 * The flow involves:
 * 1. Create an order (as a customer)
 * 2. Create a payment on the order
 * 3. Add several payment log entries for the payment (with various log_type, dates, and log_context/keywords)
 * 4. Exercise search with:
 *    a. no filters (should return all logs)
 *    b. filter by log_type (returns only matching types)
 *    c. filter by occurred_at_from/to (date ranges)
 *    d. filter with page/limit for pagination
 *    e. filter by impossible values (empty result)
 *    f. malformed page/limit (invalid: zero, negative, over max) - test for error/handling
 * 5. Attempt search as a different customer (should get forbidden error)
 *
 * Assertions:
 * - Each search result's data matches expected logs and respects filter
 * - Pagination meta matches the expected record count and page count
 * - Forbidden error when searching someone else's order/payment logs
 * - 0 results returned for impossible filters (no data, correct paging)
 * - System responds gracefully to malformed pagination/filter (error thrown)
 */
export async function test_api_order_payment_log_search_with_filtering_as_customer(
  connection: api.IConnection,
) {
  // 1. Create first customer and their order
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id,
      order_number: `ORD-${RandomGenerator.alphaNumeric(8)}`,
      total_amount: 10000,
      currency_code: "KRW",
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(order);

  // 2. Create payment for the order
  const payment_provider_id = typia.random<string & tags.Format<"uuid">>();
  const orderPayment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id,
      payment_method: "card",
      transaction_id: `TXN-${RandomGenerator.alphaNumeric(10)}`,
      amount: 10000,
      currency_code: "KRW",
      payment_result: "completed",
    } satisfies IShoppingMallAiBackendOrderPayment.ICreate,
  });
  typia.assert(orderPayment);

  // 3. Insert multiple log entries (different types, dates, context)
  const logs = await ArrayUtil.asyncRepeat(5)(async (i) => {
    const log_types = ["request", "response", "error", "event"]; 
    const type = RandomGenerator.pick(log_types);
    const logDate = new Date(Date.now() - i * 1000 * 60 * 60).toISOString();
    const log = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: orderPayment.id,
      body: {
        log_type: type,
        log_context: `Context ${i} - ${RandomGenerator.paragraph()()}`,
        occurred_at: logDate,
      } satisfies IShoppingMallAiBackendOrderPaymentLog.ICreate,
    });
    typia.assert(log);
    return log;
  });
  // 4. Search all logs without filter
  const searchAll = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: orderPayment.id,
    body: {
      order_payment_id: orderPayment.id,
    } satisfies IShoppingMallAiBackendOrderPaymentLog.IRequest,
  });
  typia.assert(searchAll);
  TestValidator.equals("all logs present")(searchAll.pagination.records)(logs.length);

  // 5. Search by log_type, should return only the correct type
  const typeToTest = logs[0].log_type;
  const searchType = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: orderPayment.id,
    body: {
      order_payment_id: orderPayment.id,
      log_type: typeToTest,
    },
  });
  typia.assert(searchType);
  TestValidator.predicate("all logs log_type matches")(searchType.data.every(l => l.log_type === typeToTest));

  // 6. Search with occurred_at_from/occurred_at_to (date window)
  // Pick dates around the 3rd log
  const fromDate = logs[3].occurred_at;
  const toDate = logs[1].occurred_at;
  const searchByDate = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: orderPayment.id,
    body: {
      order_payment_id: orderPayment.id,
      occurred_at_from: fromDate,
      occurred_at_to: toDate,
    },
  });
  typia.assert(searchByDate);
  TestValidator.predicate("logs within date window")(searchByDate.data.every(l => l.occurred_at >= fromDate && l.occurred_at <= toDate));

  // 7. Search with pagination (page=1, limit=2)
  const paged = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: orderPayment.id,
    body: {
      order_payment_id: orderPayment.id,
      page: 1,
      limit: 2,
    },
  });
  typia.assert(paged);
  TestValidator.equals("paged result length")(paged.data.length)(2);
  TestValidator.predicate("pagination meta: correct total records")(paged.pagination.records === logs.length);

  // 8. Search for impossible log_type value, expect 0 results
  const impossible = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: orderPayment.id,
    body: {
      order_payment_id: orderPayment.id,
      log_type: "nonexistent_type",
    },
  });
  typia.assert(impossible);
  TestValidator.equals("no data for impossible filter")(impossible.data.length)(0);

  // 9. Malformed page/limit (page=0, limit=201) (should throw error)
  await TestValidator.error("invalid pagination throws error")(async () => {
    await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
      orderId: order.id,
      orderPaymentId: orderPayment.id,
      body: {
        order_payment_id: orderPayment.id,
        page: 0,             // invalid (should fail)
        limit: 201,          // invalid (max=200)
      },
    });
  });

  // 10. Attempt to search as another customer (simulate by using a different random UUID)
  const otherCustomerOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      order_number: `ORD-${RandomGenerator.alphaNumeric(8)}`,
      total_amount: 5000,
      currency_code: "KRW",
      current_status: "created",
    },
  });
  const otherOrderPayment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
    orderId: otherCustomerOrder.id,
    body: {
      order_id: otherCustomerOrder.id,
      payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
      payment_method: "bank_transfer",
      transaction_id: `TXN-${RandomGenerator.alphaNumeric(10)}`,
      amount: 5000,
      currency_code: "KRW",
      payment_result: "completed",
    },
  });
  await TestValidator.error("forbidden to search another customer's logs")(async () => {
    await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.orderPaymentLogs.search(connection, {
      orderId: otherCustomerOrder.id,
      orderPaymentId: otherOrderPayment.id,
      body: {
        order_payment_id: otherOrderPayment.id,
      },
    });
  });
}

