import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * End-to-end test for listing and filtering a customer's favorite addresses, supporting business pagination and filter scenarios.
 *
 * Business goals:
 * - Ensure favorite address listing/filtering works for an authenticated customer only (privacy)
 * - Correctly returns only active favorites, not soft-deleted
 * - Filtering: supports alias, created_at date range, and pagination on PATCH endpoint
 * - Negative test: handles invalid filters, rejects unauthenticated access
 *
 * Workflow:
 * 1. Register a new customer/account (retains connection authorization)
 * 2. Add/associate several addresses to the customer account (imitate address book)
 * 3. Mark a subset of these addresses as favorites
 * 4. Run PATCH favoriteAddresses with default (no filters): must return all active favorite records for this customer
 * 5. Run PATCH again (with alias, created_at_from/created_at_to, pagination - eg limit=2) and verify only valid/filtered records are returned
 * 6. Negative: try with invalid filter parameters (such as `limit=0`, bad UUID, or sort_dir not 'asc'/'desc'), expect errors
 * 7. Negative: logout/remove Authorization, try listing again — must be denied (unauthenticated)
 */
export async function test_api_favorite_addresses_list_pagination_filtering(connection: api.IConnection) {
  // STEP 1: Register account
  const signup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(signup);

  const customerId = signup.customer.id;

  // STEP 2: Create multiple addresses for this customer using admin patch endpoint
  const addressesResp = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: {},
  });
  typia.assert(addressesResp);

  // For the test, we cannot programmatically create addresses (no create endpoint),
  // But the test scenario assumes already-initialized test DB, so fallback to using what exists.
  const addresses = addressesResp.data;
  // If the test DB is empty for that customer, we can't proceed. Validate.
  if (!addresses.length) throw new Error("No addresses found for test customer; skipping favorite test.");

  // STEP 3: Mark some addresses as favorites (mark at least 2, keep their IDs)
  const favoriteTargets = addresses.slice(0, Math.min(2, addresses.length));
  for (let addr of favoriteTargets) {
    const fav = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, {
      body: { customer_id: customerId, address_id: addr.id },
    });
    typia.assert(fav);
    TestValidator.equals("favorite was linked to customer")(fav.customer_id)(customerId);
    TestValidator.equals("favorite address is correct")(fav.address_id)(addr.id);
  }

  // STEP 4: List all favorites (no filter) — verify all just-created favorites are present, deleted not shown
  const allFavsResp = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
    body: { customer_id: customerId },
  });
  typia.assert(allFavsResp);
  const allFavIds = allFavsResp.data.map((f) => f.address_id);
  for (const favTarget of favoriteTargets)
    TestValidator.predicate("favorite present in unfiltered list")(allFavIds.includes(favTarget.id));

  // STEP 5: Filtering/pagination. Pick an alias of first address if present
  if (favoriteTargets[0].alias) {
    const filterByAlias = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
      body: { customer_id: customerId, alias: favoriteTargets[0].alias },
    });
    typia.assert(filterByAlias);
    TestValidator.predicate("filtered by alias contains correct address")(
      filterByAlias.data.some((fa) => fa.address_id === favoriteTargets[0].id)
    );
  }

  // Filtering by created_at date range: using the created_at of one favorite
  if (allFavsResp.data.length > 0) {
    const dateFrom = allFavsResp.data[0].created_at;
    const dateTo = allFavsResp.data[0].created_at;
    const filterByDate = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
      body: { customer_id: customerId, created_at_from: dateFrom, created_at_to: dateTo },
    });
    typia.assert(filterByDate);
    TestValidator.predicate("date range filter has correct favorite")(
      filterByDate.data.length > 0
    );
  }

  // Pagination test (limit = 1)
  const pagedFav = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
    body: { customer_id: customerId, limit: 1, page: 1 },
  });
  typia.assert(pagedFav);
  TestValidator.equals("pagination limit 1")(pagedFav.data.length)(1);

  // STEP 6: Negative case — invalid limit (0)
  await TestValidator.error("invalid limit rejected")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
      body: { customer_id: customerId, limit: 0 },
    });
  });
  // Negative case — bad sort_dir
  await TestValidator.error("bad sort_dir rejected")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
      body: { customer_id: customerId, sort_dir: "invalid_dir" as any },
    });
  });

  // Negative: unauthenticated (remove Authorization)
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthenticated listing denied")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(unauthConn, {
      body: { customer_id: customerId }
    });
  });
}

