import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that an admin can soft-delete any product via the admin API.
 *
 * Business context:
 * Administrators are empowered to soft-delete (not hard-delete) products system-wide to support regulatory compliance, audit trails, and rollback. Soft deletion is implemented by setting the deleted_at timestamp field, leaving data intact for audits. The action must be reflected in audit/compliance logs. Once deleted, the product is to be excluded from any active product search results.
 *
 * Step-by-step process:
 * 1. Register an admin (using /auth/admin/register) to represent a privileged user who will later execute the deletion.
 * 2. Register a seller (using /auth/seller/register), as only sellers can create products.
 * 3. The seller logs in (using /auth/seller/login) and creates a new product (using /shoppingMallAiBackend/seller/products).
 * 4. The admin logs in (using /auth/admin/login), switching the connection context to admin privilege.
 * 5. The admin calls the DELETE /shoppingMallAiBackend/admin/products/{productId} endpoint to soft-delete the seller's product.
 * 6. Validate that DELETE returns no body (void) and does not error for a valid, not-yet-deleted product.
 * 7. (If auxiliary read/search APIs were available in the SDK, confirm that deleted_at is set and the product is excluded from active search; here, we can only assert via the deletion response and side-effects.)
 * 8. Confirm that the overall workflow only uses real SDKs and DTOs provided.
 */
export async function test_api_admin_product_soft_delete_success(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPass123!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Register seller
