import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test that an admin can create a snapshot for any product inquiry, capturing the state for compliance.
 *
 * Business context:
 * - Only admins (with permission) can create snapshots for product inquiries, regardless of the product's seller or inquiry owner.
 * - The snapshot should save the current state of the inquiry (title, body, public flag, status, AI fields, and timestamps) as immutable evidence.
 *
 * Step-by-step process:
 * 1. Register an admin account (to obtain Authorization for privileged request).
 * 2. Register a seller account (seller must exist for product creation).
 * 3. Register a product with the seller account.
 * 4. Register a customer account (customer must exist for inquiry creation).
 * 5. Create a product inquiry as the customer, targeting the seller's product.
 * 6. As the admin, create an inquiry snapshot using the inquiry's state and admin credentials.
 * 7. Assert that the returned snapshot entity matches the input data and is properly logged for compliance (i.e., actor_id is admin, fields match inquiry, correct status, etc).
 */
export async function test_api_inquiry_snapshot_creation_admin_success(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongAdminPW!2024";
  const adminSignUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUpRes);

  // Set admin credentials in connection
  connection.headers = { ...connection.headers, Authorization: adminSignUpRes.setHeaders.Authorization };

  // 2. Register seller
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const sellerSignUpRes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "StrongSellerPW!2024",
      companyName: "AI-Test Corp.",
      businessNumber: "8888888888",
      representativeName: "Seller Rep",
      address: "Seoul, South Korea",
      phone: "010-1234-5678",
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUpRes);

  // 3. Create product as the seller
  connection.headers = { ...connection.headers, Authorization: sellerSignUpRes.setHeaders.Authorization };
  const productCreateRes = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerSignUpRes.sellerId,
      code: "TESTSKU" + typia.random<number>(),
      name: "Test Product Admin Snapshot",
      description: "This product is for the admin snapshot E2E test.",
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productCreateRes);

  // 4. Register customer
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerSignUpRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "CustomerPW!2024",
      name: "Test Customer",
      nickname: "test_customer_nickname",
      phone: "010-9876-5432",
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUpRes);

  // 5. Create product inquiry as the customer
  connection.headers = { ...connection.headers, Authorization: customerSignUpRes.setHeaders.Authorization };
  const inquiryRes = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerSignUpRes.customer.id,
      product_id: productCreateRes.id,
      title: "Does this product support AI features?",
      body: "I would like to know more about any AI integrations in this product.",
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
  });
  typia.assert(inquiryRes);

  // 6. As the admin, create an inquiry snapshot
  connection.headers = { ...connection.headers, Authorization: adminSignUpRes.setHeaders.Authorization };

  // The snapshot should reflect the current state of the inquiry
  const snapshotReq: IShoppingMallAiBackendInquirySnapshot.ICreate = {
    inquiry_id: inquiryRes.id,
    title: inquiryRes.title,
    body: inquiryRes.body,
    public: inquiryRes.public,
    status: inquiryRes.status as "waiting" | "answered" | "blocked" | "under_review" | "deleted",
    actor_id: adminSignUpRes.adminId,
    ai_sentiment_score: inquiryRes.ai_sentiment_score ?? null,
    ai_spam_score: inquiryRes.ai_spam_score ?? null,
    changed_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };

  const snapshotRes = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.create(connection, {
    productInquiryId: inquiryRes.id,
    body: snapshotReq,
  });
  typia.assert(snapshotRes);

  // 7. Assertions: Validate the snapshot is logged and fields match
  TestValidator.equals("inquiry id")(snapshotRes.inquiry_id)(snapshotReq.inquiry_id);
  TestValidator.equals("title")(snapshotRes.title)(snapshotReq.title);
  TestValidator.equals("body")(snapshotRes.body)(snapshotReq.body);
  TestValidator.equals("public")(snapshotRes.public)(snapshotReq.public);
  TestValidator.equals("status")(snapshotRes.status)(snapshotReq.status);
  TestValidator.equals("actor id is admin")(snapshotRes.actor_id)(adminSignUpRes.adminId);
  TestValidator.equals("AI sentiment score")(snapshotRes.ai_sentiment_score)(snapshotReq.ai_sentiment_score);
  TestValidator.equals("AI spam score")(snapshotRes.ai_spam_score)(snapshotReq.ai_spam_score);
  TestValidator.predicate("changed_at is ISO string")(
    !isNaN(Date.parse(snapshotRes.changed_at))
  );
}

