import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderItem";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that an admin user can retrieve order item details for any order, regardless of ownership.
 *
 * This test ensures privileged (admin) access works to retrieve all business/audit fields for individual order line items, across customer ownership boundaries, and that admin access is logged for compliance.
 *
 * Steps:
 * 1. Register a new admin account with unique credentials.
 * 2. Log in as the new admin to issue JWT and set Authorization.
 * 3. Register a new customer to act as order owner.
 * 4. Log in as the customer and set Authorization.
 * 5. Customer creates a new order (using their unique UUID, business logic etc.)
 * 6. Customer adds one order item to this order (with clear product_id, price, currency, etc.).
 * 7. Switch to admin (must use admin login/JWT in connection headers).
 * 8. Use the admin endpoint to GET the order item by orderId and orderItemId.
 * 9. Assert all returned fields are non-null and match expectations (order linkage, ownership, price, quantity etc.).
 * 10. Confirm access is properly permitted for admin, and that a compliance/audit action is performed according to policy (such as a successful response implies audit logging).
 */
export async function test_api_order_item_detail_success_admin_access(connection: api.IConnection) {
  // 1. Register admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "securePassword1!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Admin login to get fresh JWT
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "customerPass#1";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);

  // 4. Customer login to get JWT
  const customerLogin = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    } satisfies ICustomerSignIn.Request,
  });
  typia.assert(customerLogin);

  // 5. Customer creates order
  const orderCreate = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerLogin.customer.id,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 10000,
      currency_code: "KRW",
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(orderCreate);

  // 6. Customer creates order item
  const orderItemCreate = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.create(connection, {
    orderId: orderCreate.id,
    body: {
      order_id: orderCreate.id,
      product_id: typia.random<string & tags.Format<"uuid">>(),
      product_snapshot_id: typia.random<string & tags.Format<"uuid">>(),
      quantity: 1,
      unit_price: 10000,
      currency_code: "KRW",
    } satisfies IShoppingMallAiBackendOrderItem.ICreate,
  });
  typia.assert(orderItemCreate);

  // 7. Switch to admin by logging in again
  const adminLogin2 = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin2);

  // 8. Admin fetches order item detail
  const fetchedOrderItem = await api.functional.shoppingMallAiBackend.admin.orders.orderItems.at(connection, {
    orderId: orderCreate.id,
    orderItemId: orderItemCreate.id,
  });
  typia.assert(fetchedOrderItem);

  // 9. Assert all relevant fields are present and match created data
  TestValidator.equals("order_id")(fetchedOrderItem.order_id)(orderCreate.id);
  TestValidator.equals("id")(fetchedOrderItem.id)(orderItemCreate.id);
  TestValidator.equals("product_id")(fetchedOrderItem.product_id)(orderItemCreate.product_id);
  TestValidator.equals("quantity")(fetchedOrderItem.quantity)(orderItemCreate.quantity);
  TestValidator.equals("unit_price")(fetchedOrderItem.unit_price)(orderItemCreate.unit_price);
  TestValidator.equals("currency_code")(fetchedOrderItem.currency_code)(orderItemCreate.currency_code);
  // Confirm admin access successful and all business/audit fields viewable
  TestValidator.predicate("access compliance: created_at")(typeof fetchedOrderItem.created_at === "string");
  TestValidator.predicate("access compliance: updated_at")(typeof fetchedOrderItem.updated_at === "string");
}

