      body: {
        issued_coupon_id: issuedCoupon.id,
        actor_id: adminLogin.adminId,
        actor_type: "robot",
        action: "issued",
        action_at: now,
      } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
    })
  );

