/**
 * Test soft deletion (erase) of a product review snapshot by an admin in the AI shopping mall backend.
 *
 * Full end-to-end business process:
 * 1. Register an admin (receives JWT Authorization in header).
 * 2. Register a customer who will author a review (receives JWT Authorization, customer profile).
 * 3. Authenticate as the customer (has JWT Authorization, for review creation).
 * 4. As the customer, create a new product review (providing valid product/order item IDs, review body, rating, etc).
 * 5. As admin, create a review snapshot for the newly created review (captures current review state into an audit/evidence snapshot).
 * 6. As admin, request soft-delete (erase) of the snapshot. Ensure the DELETE operation completes successfully, and that:
 *     - The erased snapshot does not appear in normal snapshot queries (business-level, not directly testable if no query endpoint exists).
 *     - The action is auditable (may not be directly testable without audit log query API).
 *     - Other snapshots (if present) are still accessible (requires creating a second snapshot).
 *     - If the snapshot is in compliance lock/legal hold, deletion is denied (simulate by testing error on locked snapshot if permitted by API, else skip).
 *
 * Focus is on testing the entire workflow to just before/after the soft delete. Where post-conditions rely on query/list endpoints that do not exist in the provided API, just assert that the DELETE executes with no error.
 *
 * Steps:
 * 1. Register admin (store access token and profile for use).
 * 2. Register customer (store access token/profile for subsequent authentication).
 * 3. Customer login (ensure proper authentication for review creation step).
 * 4. Create product review as customer (requires UUIDs for product and order item; use random but valid values).
 * 5. Switch context back to admin for privileged actions.
 * 6. Admin creates first review snapshot for that review.
 * 7. Admin creates a second review snapshot for the same review (verifying multi-snapshot deletion, step 7-8 below).
 * 8. Admin soft-deletes first snapshot; assert DELETE succeeds.
 * 9. (Optional) Attempt query/list—skipped if no such endpoint is available.
 * 10. Try to soft-delete a locked snapshot (if simulateable; API may not expose such a lock—skip if not feasible).
 */
export async function test_api_product_review_snapshot_soft_delete_success(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin123!";
  const adminProfile = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(adminProfile);
  // Set Authorization for admin context
  connection.headers = { ...(connection.headers ?? {}), Authorization: adminProfile.setHeaders.Authorization };
  const adminId = adminProfile.adminId;

  // 2. Register customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Customer123!";
  const customerProfile = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile()
    }
  });
  typia.assert(customerProfile);
  const customerId = customerProfile.customer.id;
  const customerAuth = customerProfile.setHeaders.Authorization;

  // 3. Customer login to get new JWT (simulate actual login flow)
  const loginResp = await api.functional.auth.customer.login.signIn(connection, {
    body: { email: customerEmail, password: customerPassword }
  });
  typia.assert(loginResp);
  connection.headers = { ...(connection.headers ?? {}), Authorization: loginResp.setHeaders.Authorization };

  // 4. As customer, create product review
  const productReview = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
      order_item_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
      rating: 5,
      status: "normal"
    } satisfies IShoppingMallAiBackendProductReview.ICreate
  });
  typia.assert(productReview);

  // Save review id for snapshot actions
  const reviewId = productReview.id;

  // Switch back to admin context (for privileged actions)
  connection.headers = { ...(connection.headers ?? {}), Authorization: adminProfile.setHeaders.Authorization };

  // 5. Admin creates the first review snapshot
  const reviewSnapshot1 = await api.functional.shoppingMallAiBackend.admin.productReviews.reviewSnapshots.create(connection, {
    productReviewId: reviewId,
    body: {
      review_id: reviewId,
      body: productReview.body,
      rating: productReview.rating,
      status: productReview.status,
      actor_id: adminId,
      changed_at: new Date().toISOString()
    } satisfies IShoppingMallAiBackendReviewSnapshot.ICreate
  });
  typia.assert(reviewSnapshot1);

  // 6. Admin creates a second snapshot for the same review.
  const reviewSnapshot2 = await api.functional.shoppingMallAiBackend.admin.productReviews.reviewSnapshots.create(connection, {
    productReviewId: reviewId,
    body: {
      review_id: reviewId,
      body: productReview.body + " (update)",
      rating: productReview.rating,
      status: productReview.status,
      actor_id: adminId,
      changed_at: new Date(Date.now() + 1000).toISOString() // slightly later time
    } satisfies IShoppingMallAiBackendReviewSnapshot.ICreate
  });
  typia.assert(reviewSnapshot2);

  // 7. Admin soft deletes the first snapshot
  await api.functional.shoppingMallAiBackend.admin.productReviews.reviewSnapshots.erase(connection, {
    productReviewId: reviewId,
    reviewSnapshotId: reviewSnapshot1.id
  });

  // 8. Optionally verify that other snapshots remain accessible—cannot do without a query endpoint

  // 9. (Optional) Simulate compliance lock/legal hold test—cannot perform without such API or flag in DTOs
}

