import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrderGroup } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderGroup";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validates access control and data retrieval for customer order group details.
 *
 * This test covers:
 * 1. Registration and authentication for a customer who can access the order group.
 * 2. Creation of an order group assigned to that customer.
 * 3. Successful retrieval of the order group by its owner, verifying all core fields and metadata.
 * 4. Attempted access by another (unauthorized) customer, which should result in permission denial.
 * 5. Negative edge: access with invalid UUID format (should error).
 * 6. Negative edge: access with well-formed but non-existent order group ID (should error).
 */
export async function test_api_customer_order_group_get_success_and_access_control(connection: api.IConnection) {
  // 1. Register and authenticate the owner customer
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const ownerPassword = "P@ssw0rd#1";
  const ownerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: ownerEmail,
      password: ownerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile()
    }
  });
  typia.assert(ownerSignUp);

  // Ensure JWT is set (automatic on result)
  TestValidator.predicate("owner JWT set")(typeof connection.headers?.Authorization === "string");

  // 2. Create an order group (admin capability)
  const orderGroupRequest = {
    group_name: "E2E Test Batch " + RandomGenerator.alphaNumeric(6),
    external_reference: RandomGenerator.alphaNumeric(10),
    meta_info: JSON.stringify({ purpose: "e2e test", customerEmail: ownerEmail })
  } satisfies IShoppingMallAiBackendOrderGroup.ICreate;
  const createdGroup = await api.functional.shoppingMallAiBackend.admin.orderGroups.create(connection, { body: orderGroupRequest });
  typia.assert(createdGroup);

  // 3. The owner customer logs in again (simulate independent session)
  await api.functional.auth.customer.login.signIn(connection, { body: { email: ownerEmail, password: ownerPassword } });

  // 4. Retrieve the order group as the owner
  const fetchedGroup = await api.functional.shoppingMallAiBackend.customer.orderGroups.at(connection, { orderGroupId: createdGroup.id });
  typia.assert(fetchedGroup);
  // Validate key fields match
  TestValidator.equals("order group id matches")(fetchedGroup.id)(createdGroup.id);
  TestValidator.equals("order group name matches")(fetchedGroup.group_name)(orderGroupRequest.group_name);
  TestValidator.equals("external reference matches")(fetchedGroup.external_reference)(orderGroupRequest.external_reference);
  TestValidator.equals("meta_info matches")(fetchedGroup.meta_info)(orderGroupRequest.meta_info);

  // 5. Register and authenticate another customer (should not have access)
  const intruderEmail = typia.random<string & tags.Format<"email">>();
  const intruderPassword = "P@ssw0rd#2";
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: intruderEmail,
      password: intruderPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile()
    }
  });
  await api.functional.auth.customer.login.signIn(connection, { body: { email: intruderEmail, password: intruderPassword } });

  // 6. Intruder tries to fetch the order group (should fail)
  await TestValidator.error("unauthorized access by other customer")(() =>
