 * 3. Successful retrieval of the order group by its owner, verifying all core fields and metadata.
 * 4. Attempted access by another (unauthorized) customer, which should result in permission denial.
 * 5. Negative edge: access with invalid UUID format (should error).
 * 6. Negative edge: access with well-formed but non-existent order group ID (should error).
 */
export async function test_api_customer_order_group_get_success_and_access_control(connection: api.IConnection) {
