import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import type { IPageIShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductReview";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate seller's ability to search and filter reviews for their own products only. This test features:
 * 
 * - Seller authentication and product registration
 * - Customers leaving reviews on those products
 * - Search with a variety of filters: by product, customer, rating range, status, and date range
 * - Confirm only reviews for products the seller owns are returned
 * - Test pagination by limiting results and fetching multiple pages
 * - Validate empty result sets (seller with no reviews/products)
 * - Attempt to search with out-of-range filters and confirm error responses
 * - Ensure sellers cannot retrieve reviews for products they do NOT own
 *
 * Steps:
 * 1. Log in as seller (create test seller login info)
 * 2. Register one or more test products to the seller account, collecting their UUIDs
 * 3. Simulate multiple customers leaving reviews for these products, collecting review/customer IDs
 * 4. Perform paginated search with no filters (all owned product reviews) and confirm all returned reviews belong to owned products
 * 5. Search with product_id filter for a specific owned product, validate results match only that product
 * 6. Filter by customer_id (a known customer who left a review), confirm only reviews by that customer
 * 7. Filter by rating range (e.g., only 5-star reviews)
 * 8. Filter by date range using created_at_from / created_at_to
 * 9. Test review status filters (e.g., "blocked")
 * 10. Test pagination (limit=1), fetch multiple pages, expect correct per-page behavior
 * 11. Search with a large page number (expect no results)
 * 12. Attempt search with invalid rating range (e.g. rating_from=0), expect error
 * 13. Attempt to access reviews for product the seller does NOT own, verify no results
 * 14. Optionally, create a second seller, register a product, and confirm reviews for first seller's products are not visible to them
 */
export async function test_api_seller_product_review_search_for_owned_products(connection: api.IConnection) {
  // 1. Log in as seller (create account credentials)
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "1234";
  const sellerAuth = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword
    }
  });
  typia.assert(sellerAuth);
  const sellerId = sellerAuth.sellerId;

  // 2. Register products for this seller
  const product1 = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()(1)(),
      status: "published"
    }
  });
  const product2 = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()(1)(),
      status: "published"
    }
  });
  typia.assert(product1);
  typia.assert(product2);

  // 3. Simulate customers and reviews
  const customerId1 = typia.random<string & tags.Format<"uuid">>();
  const customerId2 = typia.random<string & tags.Format<"uuid">>();
  const orderItemId1 = typia.random<string & tags.Format<"uuid">>();
  const orderItemId2 = typia.random<string & tags.Format<"uuid">>();

  const review1 = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: product1.id,
      order_item_id: orderItemId1,
      title: "Excellent!",
      body: "Fantastic product - highly recommend!",
      rating: 5,
      status: "normal",
      ai_sentiment_score: 0.9,
      ai_spam_score: 0.1
    }
  });
  const review2 = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: product2.id,
      order_item_id: orderItemId2,
      title: "Not bad",
      body: "Fine, but could be better.",
      rating: 3,
      status: "normal",
      ai_sentiment_score: 0.2,
      ai_spam_score: 0.2
    }
  });
  typia.assert(review1);
  typia.assert(review2);
  // Add a "blocked" review
  const review3 = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: product1.id,
      order_item_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Spam Review",
      body: "Buy now cheap!",
      rating: 1,
      status: "blocked",
      ai_sentiment_score: -0.6,
      ai_spam_score: 0.95
    }
  });
  typia.assert(review3);

  // 4. Unfiltered search for all reviews on owned products
  const searchAll = await api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
    body: {
      page: 1,
      limit: 100
    }
  });
  typia.assert(searchAll);
  for (const r of searchAll.data) {
    TestValidator.equals("owned product only")(sellerId)([product1.id, product2.id].includes(r.product_id) ? sellerId : "");
  }

  // 5. Filter by product_id (product1)
  const product1Reviews = await api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
    body: {
      product_id: product1.id,
      page: 1,
      limit: 100
    }
  });
  typia.assert(product1Reviews);
  for (const r of product1Reviews.data) {
    TestValidator.equals("product_id matches")(r.product_id)(product1.id);
  }

  // 6. Filter by customer_id (should be empty since random UUIDs used for customers, but test path anyway)
  const customerEmpty = await api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
    body: {
      customer_id: customerId2,
      page: 1,
      limit: 100
    }
  });
  typia.assert(customerEmpty);

  // 7. Filter by rating range (only 5-star reviews)
  const fiveStarReviews = await api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
    body: {
      rating_from: 5,
      rating_to: 5,
      page: 1,
      limit: 100
    }
  });
  typia.assert(fiveStarReviews);
  for (const r of fiveStarReviews.data) {
    TestValidator.equals("rating is 5")(r.rating)(5);
  }

  // 8. Filter by created_at (using review1's created_at)
  const createdAtDate = review1.created_at;
  const dateFiltered = await api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
    body: {
      created_at_from: createdAtDate,
      created_at_to: createdAtDate,
      page: 1,
      limit: 100
    }
  });
  typia.assert(dateFiltered);
  for (const r of dateFiltered.data) {
    TestValidator.predicate("created_at in range")(r.created_at >= createdAtDate && r.created_at <= createdAtDate);
  }

  // 9. Status filter (blocked reviews)
  const blockedReviews = await api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
    body: {
      status: "blocked",
      page: 1,
      limit: 100
    }
  });
  typia.assert(blockedReviews);
  for (const r of blockedReviews.data) {
    TestValidator.equals("blocked review status")(r.status)("blocked");
  }

  // 10. Pagination (limit = 1)
  const page1 = await api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
    body: {
      page: 1,
      limit: 1
    }
  });
  typia.assert(page1);
  if (page1.pagination.pages > 1) {
    const page2 = await api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
      body: {
        page: 2,
        limit: 1
      }
    });
    typia.assert(page2);
    TestValidator.notEquals("page1 != page2")(page1.data[0]?.id)(page2.data[0]?.id);
  }

  // 11. Large page number (expect empty)
  const largePage = await api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
    body: {
      page: 9999,
      limit: 100
    }
  });
  typia.assert(largePage);
  TestValidator.equals("empty data for large page")(largePage.data.length)(0);

  // 12. Invalid filter (rating out of range)
  await TestValidator.error("invalid rating range")(() =>
    api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
      body: {
        rating_from: 0, // Invalid, minimum is 1
        page: 1,
        limit: 10
      }
    })
  );

  // 13. Seller cannot retrieve reviews for another seller's product
  const otherSellerEmail = typia.random<string & tags.Format<"email">>();
  const otherSellerPassword = "1234";
  const otherSellerAuth = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: otherSellerEmail,
      password: otherSellerPassword
    }
  });
  typia.assert(otherSellerAuth);
  const otherSellerId = otherSellerAuth.sellerId;
  const otherProduct = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: otherSellerId,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()(1)(),
      status: "published"
    }
  });
  typia.assert(otherProduct);
  // Search as other seller for reviews on seller1 products
  const otherSellerSearch = await api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
    body: {
      product_id: product1.id,
      page: 1,
      limit: 100
    }
  });
  typia.assert(otherSellerSearch);
  TestValidator.equals("no cross-seller review access")(otherSellerSearch.data.length)(0);

  // 14. Seller with no products (newly made) gets empty review listing
  const newSellerEmail = typia.random<string & tags.Format<"email">>();
  const newSellerPassword = "5678";
  const newSellerAuth = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: newSellerEmail,
      password: newSellerPassword
    }
  });
  typia.assert(newSellerAuth);
  const newSellerSearch = await api.functional.shoppingMallAiBackend.seller.productReviews.search(connection, {
    body: {
      page: 1,
      limit: 10
    }
  });
  typia.assert(newSellerSearch);
  TestValidator.equals("new seller has no reviews")(newSellerSearch.data.length)(0);
}

