 *
 * This test ensures that only the seller of a product can create a snapshot of a product review related to their product, and that the resulting snapshot contains the business fields and values consistent with the current product review state. It also prepares for negative permission checks.
 *
 * 1. Register a seller (obtain seller ID/JWT)
 * 2. Register a product using the seller account
 * 3. Register a customer (obtain customer ID/JWT)
 * 4. Customer creates an order for the above product
 * 5. Customer writes a product review for their order
 * 6. Seller (as the owner) creates a review snapshot for that review: All fields should match business expectation (actor, body, rating, status, audit fields).
 * 7. Assert that the snapshot is properly linked to the review and includes expected current field values.
 * 8. Verify that the actor is the seller.
 * 9. (Omit negative/unauthorized test here, focus on happy path)
 */
export async function test_api_product_review_snapshot_creation_success_seller(
  connection: api.IConnection,
) {
  // 1. Register a seller
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "SellerPW1!@#",
      companyName: RandomGenerator.alphabets(10),
      businessNumber: "1234567890",
