 * 2. Register a customer and log in as the customer
 * 3. Customer creates a product review (requires valid product and order item references—simulate random UUID for this demo)
 * 4. As admin, create a snapshot for the review to represent the audit trail
 * 5. As admin, update mutable metadata fields on the snapshot (e.g. actor_id, status, ai_sentiment_score, ai_spam_score)
 * 6. Verify that updates are reflected and core review content (body, rating, changed_at) are unchanged unless explicitly allowed
 * 7. Confirm audit integrity: original (immutable) snapshot fields remain valid, and updated mutable fields reflect changes
 *
 * Edge case: Attempt update of immutable fields (body/rating/changed_at) and verify that the API either ignores or blocks illegal updates; only metadata must change. (Only implement if allowed by IUpdate schema.)
 */
export async function test_api_product_review_snapshot_metadata_update_success(connection: api.IConnection) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
