    // Note: Attempting to change immutable fields (e.g. body, rating, changed_at) is only allowed if schema/classes allow; skip otherwise.
  };
  const updatedSnapshot = await api.functional.shoppingMallAiBackend.admin.productReviews.reviewSnapshots.update(connection, {
    productReviewId: productReview.id,
    reviewSnapshotId: snapshot.id,
    body: updateRequest
  });
  typia.assert(updatedSnapshot);

  // 7. Validate that updates are reflected and audit fields retained
  TestValidator.equals("ai_sentiment_score updated")(updatedSnapshot.ai_sentiment_score)(0.9);
  TestValidator.equals("ai_spam_score updated")(updatedSnapshot.ai_spam_score)(0.1);
  TestValidator.equals("actor_id updated")(updatedSnapshot.actor_id)(newActorId);
  TestValidator.equals("status updated")(updatedSnapshot.status)("blocked");
  // Validate immutable fields remain unchanged
  TestValidator.equals("body unchanged")(updatedSnapshot.body)(snapshot.body);
  TestValidator.equals("rating unchanged")(updatedSnapshot.rating)(snapshot.rating);
  TestValidator.equals("changed_at unchanged")(updatedSnapshot.changed_at)(snapshot.changed_at);
}

