import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that product inquiry editing is forbidden to non-owners.
 *
 * - Business Rule: Only the customer who originally created a product inquiry can update it. Other customers attempting to update should be denied.
 *
 * Test Steps:
 * 1. Register a new seller.
 * 2. Seller creates a product.
 * 3. Register Customer A (the owner of the inquiry).
 * 4. Customer A creates a product inquiry on the product.
 * 5. Register Customer B (a different customer).
 * 6. Customer B attempts to update the inquiry created by Customer A; expect error/denial.
 */
export async function test_api_customer_product_inquiry_update_forbidden_non_owner(connection: api.IConnection) {
  // 1. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "pw" + typia.random<string & tags.Pattern<"^[a-zA-Z0-9]{6,}">>();
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: "" + (1000000000 + Math.floor(Math.random() * 8999999999)),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(1),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(sellerSignUp);

  // 2. Seller creates a product
  // (Inject seller_id from registration response)
  const productCreate = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerSignUp.sellerId,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(productCreate);

  // 3. Register Customer A (original owner of the inquiry)
  const customerAEmail = typia.random<string & tags.Format<"email">>();
  const customerAPassword = "pw" + typia.random<string & tags.Pattern<"^[a-zA-Z0-9]{6,}">>();
  const customerA = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerAEmail,
      password: customerAPassword,
      name: RandomGenerator.name(),
