 * 5. As the admin (switch context), call the admin cartItems get-by-id endpoint with cartId and cartItemId.
 * 6. Assert that all expected fields are returned and audit fields are present and well-formed.
 * 7. Confirm that access is granted even though the admin is not the cart owner.
 */
export async function test_api_cart_item_retrieve_admin_access_success(connection: api.IConnection) {
