 * It specifically validates:
 * - Admin access ignores cart ownership and is able to fetch details of any cart item in the system.
 * - All business fields of the cart item (product references, quantity, pricing, note, timestamps, etc.) are correctly returned.
 * - Compliance/audit fields like created_at and updated_at are present and well-formed.
 *
 * Workflow:
 * 1. Register a customer and capture their JWT.
 * 2. Register an admin for privileged access and capture their JWT.
 * 3. As the customer, create a shopping cart.
 * 4. As the customer, add a cart item to the cart (specifying sample product, option, and pricing data).
 * 5. As the admin, fetch the cart item detail via the admin API using both cartId and cartItemId.
 * 6. Validate that all data fields are returned correctly and compliance audit fields are populated.
 * 7. Confirm that admin access to the cart item succeeds even though the admin is not the cart owner.
 */
export async function test_api_cart_item_retrieve_admin_access_success(connection: api.IConnection) {
  // 1. Register a customer and obtain their JWT for authentication
  const customerEmail = typia.random<string & tags.Format<'email'>>();
  const customerPassword = 'Customer123!';
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignUp);
  const customerToken = customerSignUp.setHeaders.Authorization;

  // 2. Register an admin and obtain their JWT
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'Admin123!';
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminSignUp);
  const adminToken = adminSignUp.setHeaders.Authorization;

  // 3. Create a shopping cart as the customer
  const customerConnection: api.IConnection = {
    ...connection,
    headers: { ...connection.headers, Authorization: customerToken },
  };
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(customerConnection, {
    body: {
      status: 'active',
      session_token: null,
    } satisfies IShoppingMallAiBackendCart.ICreate,
  });
  typia.assert(cart);

  // 4. Add a cart item to the customer's cart
  const cartItemCreate: IShoppingMallAiBackendCartItem.ICreate = {
    product_id: typia.random<string & tags.Format<'uuid'>>(),
    product_option_id: null, // testing with no options
    quantity: 2,
    unit_price: 5000.0,
    currency_code: 'KRW',
    note: 'Test product in cart',
  };
  const cartItem = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(customerConnection, {
    cartId: cart.id,
    body: cartItemCreate,
  });
  typia.assert(cartItem);

  // 5. As the admin, fetch the cart item details by cartId and cartItemId
  const adminConnection: api.IConnection = {
    ...connection,
    headers: { ...connection.headers, Authorization: adminToken },
  };
  const fetched = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.at(adminConnection, {
    cartId: cart.id,
    cartItemId: cartItem.id,
  });
  typia.assert(fetched);

  // 6. Validate that the fetched data matches what was added
  TestValidator.equals('cart item id')(fetched.id)(cartItem.id);
  TestValidator.equals('product_id')(fetched.product_id)(cartItemCreate.product_id);
  TestValidator.equals('product_option_id')(fetched.product_option_id)(cartItemCreate.product_option_id);
  TestValidator.equals('quantity')(fetched.quantity)(cartItemCreate.quantity);
  TestValidator.equals('unit_price')(fetched.unit_price)(cartItemCreate.unit_price);
  TestValidator.equals('currency_code')(fetched.currency_code)(cartItemCreate.currency_code);
  TestValidator.equals('note')(fetched.note)(cartItemCreate.note);

  // 7. Compliance/audit fields must be present and correctly formatted
  TestValidator.predicate('created_at is ISO string')(typeof fetched.created_at === 'string' && fetched.created_at.length > 0);
  TestValidator.predicate('updated_at is ISO string')(typeof fetched.updated_at === 'string' && fetched.updated_at.length > 0);
  // deleted_at may be null or timestamp for deleted, so skip assertion

  // 8. Assert that access by admin (not cart owner) succeeded without error
}

