import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductCategoryMap";
import type { IPageIShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductCategoryMap";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * E2E: Validate admin-side search/filtering of product-category mappings.
 *
 * This test verifies that product-category mapping search for a given product works correctly in the admin context, including all advanced filter features.
 * Business workflow:
 * 1. Register a seller (required to create a product).
 * 2. As this seller, create a new product (with random info).
 * 3. Create 3 unique category IDs (simulate categories by uuid strings since no API exists in input for category creation/listing) and associate them as mappings to the product (mix of primary/secondary).
 * 4. As admin, search for product-category mappings with:
 *    a. No filters: Should return all 3 mappings.
 *    b. Filter by specific category_id: Should return only the matching mapping.
 *    c. Filter by primary=true: Should return only mappings with primary=true
 *    d. Filter by primary=false: Should return only mappings with primary=false
 *    e. Paginate (limit=2, page=1): Should return the first 2 mappings, meta shows total=3.
 *    f. Search for a non-existent category_id: Should return 0 mappings.
 *    g. Search for mismatched primary/category flag: Should return 0 mappings as well.
 *
 * Logic checks for each case using TestValidator.equals and typia.assert().
 */
export async function test_api_product_category_map_search_by_admin_with_filters(
  connection: api.IConnection,
) {
  // 1. Register a seller
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "12345678",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile()
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(sellerSignUp);

  // 2. Create a product as the seller
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerSignUp.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 3. Create 3 category mappings for product (simulate unique category ids)
  const categoryIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  // - mapping 1: primary true, categoryIds[0]
  const mapPrimary = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      category_id: categoryIds[0],
      primary: true
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate
  });
  typia.assert(mapPrimary);
  // - mapping 2: primary false, categoryIds[1]
  const mapSecondary1 = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      category_id: categoryIds[1],
      primary: false
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate
  });
  typia.assert(mapSecondary1);
  // - mapping 3: primary false, categoryIds[2]
  const mapSecondary2 = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      category_id: categoryIds[2],
      primary: false
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate
  });
  typia.assert(mapSecondary2);

  // 4a. Search with no filters: should return all 3
  const allMaps = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.search(connection, {
    productId: product.id,
    body: { product_id: product.id } satisfies IShoppingMallAiBackendProductCategoryMap.IRequest
  });
  typia.assert(allMaps);
  TestValidator.equals("all mappings - count")(allMaps.data.length)(3);

  // 4b. Filter by category_id (categoryIds[1])
  const filteredByCategory = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.search(connection, {
    productId: product.id,
    body: { product_id: product.id, category_id: categoryIds[1] } satisfies IShoppingMallAiBackendProductCategoryMap.IRequest
  });
  typia.assert(filteredByCategory);
  TestValidator.equals("filter category_id count")(filteredByCategory.data.length)(1);
  TestValidator.equals("filter category_id check")(filteredByCategory.data[0].category_id)(categoryIds[1]);

  // 4c. Filter by primary=true
  const filteredPrimaryTrue = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.search(connection, {
    productId: product.id,
    body: { product_id: product.id, primary: true } satisfies IShoppingMallAiBackendProductCategoryMap.IRequest
  });
  typia.assert(filteredPrimaryTrue);
  TestValidator.equals("filter primary true count")(filteredPrimaryTrue.data.length)(1);
  TestValidator.equals("filter primary true mapping")(filteredPrimaryTrue.data[0].category_id)(categoryIds[0]);

  // 4d. Filter by primary=false
  const filteredPrimaryFalse = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.search(connection, {
    productId: product.id,
    body: { product_id: product.id, primary: false } satisfies IShoppingMallAiBackendProductCategoryMap.IRequest
  });
  typia.assert(filteredPrimaryFalse);
  TestValidator.equals("filter primary false count")(filteredPrimaryFalse.data.length)(2);
  TestValidator.predicate("secondary mappings all have primary=false")(filteredPrimaryFalse.data.every(m => !m.primary));

  // 4e. Pagination (limit=2, page=1)
  const paged = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.search(connection, {
    productId: product.id,
    body: { product_id: product.id, limit: 2, page: 1 } satisfies IShoppingMallAiBackendProductCategoryMap.IRequest
  });
  typia.assert(paged);
  TestValidator.equals("pagination limit")(paged.data.length)(2);
  TestValidator.equals("pagination total")(paged.pagination.records)(3);

  // 4f. Filter by non-existent category_id
  const notFoundCategory = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.search(connection, {
    productId: product.id,
    body: { product_id: product.id, category_id: typia.random<string & tags.Format<"uuid">>() } satisfies IShoppingMallAiBackendProductCategoryMap.IRequest
  });
  typia.assert(notFoundCategory);
  TestValidator.equals("nonexistent category count")(notFoundCategory.data.length)(0);

  // 4g. Filter by mismatched category_id and primary=true
  const mismatched = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.search(connection, {
    productId: product.id,
    body: { product_id: product.id, category_id: categoryIds[2], primary: true } satisfies IShoppingMallAiBackendProductCategoryMap.IRequest
  });
  typia.assert(mismatched);
  TestValidator.equals("mismatched filter count")(mismatched.data.length)(0);
}

