import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteProduct";
import type { IShoppingMallAiBackendFavoriteNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteNotification";
import type { IPageIShoppingMallAiBackendFavoriteNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendFavoriteNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate the admin favorite notification search endpoint with advanced filters and pagination.
 *
 * This scenario tests that the admin can search/view all favorite notification records across the system, with comprehensive use of filters, pagination, and security validation. It covers realistic business flows, data creation, filtering, edge cases, and permissions.
 *
 * Steps:
 * 1. Register multiple customers with diverse profile data to represent notification recipients.
 * 2. For each customer, create different favorite types—at least product, and optionally address/inquiry if supported by the schema—by favoriting various objects.
 * 3. For each favorite, generate a variety of notification events using several combinations of notification type (e.g. RESTOCK, PRICE_DROP, INQUIRY_REPLY, ADDRESS_CHANGED), channel (EMAIL/SMS/PUSH), and read states.
 * 4. As admin, search for all notifications, verify structure, filter correctness, and ensure pagination produces accurate metadata. Try:
 *    - No filters (all notifications, check total)
 *    - Filter by notification_type (e.g. PRICE_DROP)
 *    - Filter by read/unread
 *    - Filter by associated favorite product
 *    - Filter by created_at_from and created_at_to (date range)
 *    - Small limit/page to trigger multi-page
 * 5. Assert:
 *    - Data returned matches all provided filters
 *    - Security: No data is returned that is forbidden/sensitive (compare to DTO spec)
 *    - Pagination metadata is accurate, and sum of paged data matches full count
 * 6. Negative tests:
 *    - Query with an impossible/nonexistent filter should return empty result
 *    - Missing required/invalid filter parameters result in expected error response
 */
export async function test_api_favorite_notifications_admin_search_all_users(connection: api.IConnection) {
  // 1. Register customers and prepare favorite products
  const customers: IShoppingMallAiBackendCustomer[] = [];
  const favoriteProducts: IShoppingMallAiBackendFavoriteProduct[] = [];
  const notifications: IShoppingMallAiBackendFavoriteNotification[] = [];
  const notificationTypes = [
    "RESTOCK",
    "PRICE_DROP",
    "INQUIRY_REPLY",
    "ADDRESS_CHANGED"
  ];
  const channels = ["EMAIL", "SMS", "PUSH"];

  for (let i = 0; i < 3; i++) {
    const registRes = await api.functional.auth.customer.register.signUp(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "password",
        name: RandomGenerator.name(),
        nickname: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request
    });
    typia.assert(registRes);
    customers.push(registRes.customer);

    // Each customer favorites a product
    const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
      body: {
        product_id: typia.random<string & tags.Format<"uuid">>()
      } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate
    });
    typia.assert(favoriteProduct);
    favoriteProducts.push(favoriteProduct);

    // Create multiple notifications per favorite
    for (const notification_type of notificationTypes) {
      for (const channel of channels) {
        const notification = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, {
          body: {
            favorite_product_id: favoriteProduct.id,
            notification_type,
            notification_channel: channel,
            read: Math.random() < 0.5,
            delivery_metadata: Math.random() < 0.5 ? JSON.stringify({ key: RandomGenerator.alphabets(5) }) : null
          } satisfies IShoppingMallAiBackendFavoriteNotification.ICreate
        });
        typia.assert(notification);
        notifications.push(notification);
      }
    }
  }

  // 4. Perform admin search queries with varied filters

  // a. No filters
  const resp1 = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
    body: {} satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
  });
  typia.assert(resp1);
  TestValidator.predicate("returns all notifications")(resp1.data.length > 0);

  // b. Filter by notification_type
  const notificationType = notificationTypes[1];
  const resp2 = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
    body: { notification_type: notificationType } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
  });
  typia.assert(resp2);
  for (const noti of resp2.data) TestValidator.equals("type match")(noti.notification_type)(notificationType);

  // c. Filter by 'read' state
  const resp3 = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
    body: { read: true } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
  });
  typia.assert(resp3);
  for (const noti of resp3.data) TestValidator.equals("is read")(noti.read)(true);

  // d. Filter by favorite_product_id
  const filteredFavoriteId = favoriteProducts[0].id;
  const resp4 = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
    body: { favorite_product_id: filteredFavoriteId } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
  });
  typia.assert(resp4);
  for (const noti of resp4.data) TestValidator.equals("favorite product id matches")(noti.favorite_product_id)(filteredFavoriteId);

  // e. Filter by created_at date window
  const from = notifications[0].created_at;
  const to = notifications[notifications.length - 1].created_at;
  const resp5 = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
    body: { created_at_from: from, created_at_to: to } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
  });
  typia.assert(resp5);
  for (const noti of resp5.data) {
    TestValidator.predicate("created_at within window")(noti.created_at >= from && noti.created_at <= to);
  }

  // f. Small pagination (limit 2)
  const resp6 = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
    body: { limit: 2 } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
  });
  typia.assert(resp6);
  TestValidator.equals("pagination limit")(resp6.pagination.limit)(2);

  // g. Pagination across multiple pages
  const resp7 = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
    body: { page: 2, limit: 2 } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
  });
  typia.assert(resp7);
  TestValidator.equals("pagination page")(resp7.pagination.current)(2);

  // 5. Security: Assert no forbidden/sensitive fields are present in each notification object according to DTO spec
  for (const resp of [resp1, resp2, resp3, resp4, resp5, resp6, resp7]) {
    for (const n of resp.data) {
      // Should not have internal tokens, passwords, etc, only properties defined in IShoppingMallAiBackendFavoriteNotification
      for (const key of Object.keys(n)) {
        TestValidator.predicate(`allowed field: ${key}`)([
          "id",
          "favorite_product_id",
          "favorite_inquiry_id",
          "favorite_address_id",
          "notification_type",
          "notification_channel",
          "read",
          "delivery_metadata",
          "created_at"
        ].includes(key as any));
      }
    }
  }

  // 6. Negative/edge cases
  // Impossible filter: a nonsense notification_type
  const resp8 = await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
    body: { notification_type: "THIS_DOES_NOT_EXIST" } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
  });
  typia.assert(resp8);
  TestValidator.equals("empty on impossible type")(resp8.data.length)(0);

  // Missing/invalid filter: invalid limit (zero or negative)
  await TestValidator.error("invalid limit rejected")(async () => {
    await api.functional.shoppingMallAiBackend.admin.favoriteNotifications.search(connection, {
      body: { limit: 0 } satisfies IShoppingMallAiBackendFavoriteNotification.IRequest
    });
  });
}

