import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderSnapshot";
import type { IPageIShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate advanced search, pagination, and authorization for order snapshots API as an admin.
 *
 * This test ensures that admins can search and paginate order snapshot data for a specific order with various filters, and that proper error/authorization rules are enforced.
 *
 * Step-by-step:
 * 1. Register a new admin and a customer.
 * 2. As the customer, create a new order.
 * 3. As admin, create at least two order snapshots for the order with different reasons and timestamps.
 * 4. As admin, search for snapshots for the given order (no filters) and validate that all are returned, paging info matches, and data structure is correct.
 * 5. Search with filters (e.g., snapshot_reason, date range, pagination limit), verify results match criteria and correct pagination.
 * 6. Try to search with invalid filters (invalid date format, negative page/limit) and verify error is returned.
 * 7. Try searching snapshots for a random non-existing orderId and check that results (likely empty) are handled gracefully, or error if appropriate.
 * 8. Switch to non-admin (customer) context and attempt the same search; ensure authorization (forbidden) error is thrown.
 */
export async function test_api_order_snapshot_advanced_search_pagination_and_authorization_admin(
  connection: api.IConnection
) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SuperSecret123!";
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminSignup);
  // Admin token is set in connection

  // 2. Register a customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "UserSecret123!";
  const customerSignup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignup);
  const customerId = customerSignup.customer.id;

  // 3. As customer, create an order
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  }); // Switch to customer
  const orderCreateInput = {
    customer_id: customerId,
    order_number: `ORD-${Date.now()}`,
    total_amount: typia.random<number>(),
    currency_code: "USD",
    current_status: "created",
  } satisfies IShoppingMallAiBackendOrder.ICreate;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: orderCreateInput,
  });
  typia.assert(order);
  const orderId = order.id;

  // 4. As admin, switch back
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 5. Create two order snapshots with different reasons
  const firstSnapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.create(connection, {
    orderId,
    body: {
      snapshot_json: JSON.stringify(order),
      snapshot_reason: "created",
    },
  });
  typia.assert(firstSnapshot);
  await new Promise((r) => setTimeout(r, 1200)); // Ensure timestamp difference
  order.current_status = "paid";
  const secondSnapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.create(connection, {
    orderId,
    body: {
      snapshot_json: JSON.stringify(order),
      snapshot_reason: "paid",
    },
  });
  typia.assert(secondSnapshot);

  // 6. Search snapshots (no filters)
  const allResults = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.search(connection, {
    orderId,
    body: {},
  });
  typia.assert(allResults);
  TestValidator.equals("snapshots count")(allResults.data.length)(2);
  TestValidator.equals("pagination total")(allResults.pagination.records)(2);

  // 7. Filter by reason
  const filteredResults = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.search(connection, {
    orderId,
    body: { snapshot_reason: "created" },
  });
  typia.assert(filteredResults);
  TestValidator.equals("one created reason")(filteredResults.data.length)(1);
  TestValidator.equals("reason same")(filteredResults.data[0].snapshot_reason)("created");

  // 8. Filter by date
  const firstTs = firstSnapshot.created_at;
  const dateResults = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.search(connection, {
    orderId,
    body: { created_after: firstTs },
  });
  typia.assert(dateResults);
  TestValidator.equals("only second after first")(dateResults.data.length)(1);
  TestValidator.equals("id match")(dateResults.data[0].id)(secondSnapshot.id);

  // 9. Pagination (limit = 1)
  const pagedResults = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.search(connection, {
    orderId,
    body: { limit: 1 },
  });
  typia.assert(pagedResults);
  TestValidator.equals("paged one result")(pagedResults.data.length)(1);
  TestValidator.equals("pagination pages")(pagedResults.pagination.pages)(2);

  // 10. Invalid filter (negative page) → error
  await TestValidator.error("negative page for snapshot search")(() =>
    api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.search(connection, {
      orderId,
      body: { page: -1 },
    })
  );

  // 11. Non-existent orderId → empty or error
  const fakeOrderId = typia.random<string & tags.Format<"uuid">>();
  const noSnapshotsResults = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.search(connection, {
    orderId: fakeOrderId,
    body: {},
  });
  typia.assert(noSnapshotsResults);
  TestValidator.equals("empty results for non-existent order")(noSnapshotsResults.data.length)(0);

  // 12. Switch to customer context, attempt search (should fail with authorization)
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  });
  await TestValidator.error("customer forbidden for snapshot search")(() =>
    api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.search(connection, {
      orderId,
      body: {},
    })
  );
}

