import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import type { IPageIShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductOption";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that an admin can search and paginate product options for any product across the catalog, not just their own. 
 *
 * This test ensures that:
 * - Role permissions are enforced: only an admin can perform the global option search.
 * - Seller can successfully create a product and attach multiple options to it.
 * - The admin can search for product options with filters (SKU, status) and pagination across all products (not scoped only to their own).
 * - Query logic works: The response contains only the expected options and respects pagination and filter constraints.
 *
 * 1. Register a new admin account and login to get an admin connection.
 * 2. Register a seller account and login to get a seller-authenticated connection.
 * 3. Seller creates a new product with a unique SKU.
 * 4. Seller creates two options for their product: e.g., distinct SKU and status.
 * 5. Switch to the admin connection (admin should have global visibility).
 * 6. Admin searches options for the seller's product by filtering for one option's SKU (should get only that option).
 * 7. Admin searches with a status filter and page size 1 (should get a single-page result with pageSize respected).
 * 8. Admin searches with no filters but pageSize 1, then fetch page 2 (should get the other option in the second page).
 * 9. For each search, validate the returned option(s) match expected data, and pagination info is correct.
 */
export async function test_api_admin_search_product_options_all_products(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPass123!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as admin to populate Authorization
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });

  // 3. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "sellerpass1!";
  const sellerCompany = RandomGenerator.alphabets(8) + " Inc.";
  const seller = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: sellerCompany,
      businessNumber: RandomGenerator.sample(["1234567890","2345678901","3456789012"])(1)[0],
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller);

  // 4. Login as seller
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuth.SignIn,
  });

  // 5. Seller creates product
  const productCode = RandomGenerator.alphaNumeric(7);
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: seller.sellerId,
      code: productCode,
      name: "test-e2e product " + RandomGenerator.alphabets(5),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 6. Seller creates two options for the product
  const optionA: IShoppingMallAiBackendProductOption = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: productCode + "-RED",
      option_name: "Color",
      option_values: "Red",
      extra_price: 1000.0,
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProductOption.ICreate,
  });
  typia.assert(optionA);

  const optionB: IShoppingMallAiBackendProductOption = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: productCode + "-BLUE",
      option_name: "Color",
      option_values: "Blue",
      extra_price: 2000.0,
      main_image_uri: null,
      status: "inactive",
    } satisfies IShoppingMallAiBackendProductOption.ICreate,
  });
  typia.assert(optionB);

  // 7. Switch back to admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });

  // 8. Admin searches for only optionA with SKU filter
  {
    const result = await api.functional.shoppingMallAiBackend.admin.products.productOptions.search(connection, {
      productId: product.id,
      body: {
        filter: {
          sku: optionA.sku,
        },
        page: 1,
        pageSize: 10,
      } satisfies IShoppingMallAiBackendProductOption.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("optionA sku search count")(result.data.length)(1);
    TestValidator.equals("optionA sku search item")(result.data[0].sku)(optionA.sku);
  }

  // 9. Admin searches for inactive status, pageSize 1, should get only optionB
  {
    const result = await api.functional.shoppingMallAiBackend.admin.products.productOptions.search(connection, {
      productId: product.id,
      body: {
        filter: {
          status: "inactive",
        },
        page: 1,
        pageSize: 1,
      } satisfies IShoppingMallAiBackendProductOption.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("inactive status")(result.data.length)(1);
    TestValidator.equals("status value")(result.data[0].status)("inactive");
    TestValidator.equals("sku value")(result.data[0].sku)(optionB.sku);
  }

  // 10. Admin searches with no filter, pageSize 1, fetch page 2 (should get the second option). Order by SKU for deterministic paging.
  {
    const resultPage1 = await api.functional.shoppingMallAiBackend.admin.products.productOptions.search(connection, {
      productId: product.id,
      body: {
        page: 1,
        pageSize: 1,
        sort: [{ field: "sku", direction: "asc" }],
      } satisfies IShoppingMallAiBackendProductOption.IRequest,
    });
    typia.assert(resultPage1);
    TestValidator.equals("page 1 count")(resultPage1.data.length)(1);
    const resultPage2 = await api.functional.shoppingMallAiBackend.admin.products.productOptions.search(connection, {
      productId: product.id,
      body: {
        page: 2,
        pageSize: 1,
        sort: [{ field: "sku", direction: "asc" }],
      } satisfies IShoppingMallAiBackendProductOption.IRequest,
    });
    typia.assert(resultPage2);
    TestValidator.equals("page 2 count")(resultPage2.data.length)(1);
    TestValidator.notEquals("different SKU in pages")(resultPage1.data[0].sku)(resultPage2.data[0].sku);
    // Optionally confirm that the returned options are the expected ones
    const skus = [resultPage1.data[0].sku, resultPage2.data[0].sku].sort();
    const expectedSkus = [optionA.sku, optionB.sku].sort();
    TestValidator.equals("all returned skus between both pages")(skus)(expectedSkus);
  }
}

