import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendComplianceEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceEvent";
import type { IPageIShoppingMallAiBackendComplianceEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendComplianceEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate searching of compliance event logs with advanced filters.
 *
 * This test verifies that only authenticated admin users can access
 * the compliance event log endpoint, and that advanced filtering via event type,
 * actor details, and date range returns only the correct matching records.
 *
 * The test also checks that unauthorized access is not permitted, verifies 
 * pagination and flexible search options, and ensures output respects compliance,
 * privacy, and audit requirements.
 *
 * Steps:
 * 1. Register and authenticate a new admin (acquire Authorization).
 * 2. Create several compliance event records of varying types/actors/timestamps.
 * 3. Attempt searching as unauthorized user and validate error is thrown.
 * 4. As admin, search:
 *    a. By event type (only events of that type returned)
 *    b. By actor ID (only events from that actor)
 *    c. By created_at date range (subset returned)
 *    d. By pagination (page/limit)
 *    e. By partial/keyword queries if available via event_type or other fields
 * 5. Verify responses are accurate—only correct events are returned, paging metadata is accurate.
 * 6. Ensure no privacy-violating/leaked fields, and all key audit info is present.
 */
export async function test_api_compliance_event_search_by_filter(connection: api.IConnection) {
  // 1. Register and authenticate a new admin
  const email = typia.random<string & tags.Format<'email'>>();
  const password = 'Secr3tPassword!';
  const reg = await api.functional.auth.admin.register.signUp(connection, {
    body: { email, password } satisfies IAdminAuth.SignUp,
  });
  typia.assert(reg);
  const adminId = reg.adminId;

  // 2. Create several compliance events with different characteristics
  // Use the Authorization header from new admin
  connection.headers = {
    ...connection.headers,
    Authorization: reg.setHeaders?.Authorization ?? `Bearer ${reg.jwt}`,
  };

  const now = new Date();
  const eventTypes = [
    'policy_update',
    'data_erasure_request',
    'access_review',
    'data_export',
  ];

  const createdEvents: IShoppingMallAiBackendComplianceEvent[] = [];
  for (let i = 0; i < eventTypes.length; ++i) {
    // Optional payload for one event, omitted for others
    const event_payload = i % 2 === 0 ? JSON.stringify({ field: `payload${i}` }) : null;
    const event = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
      body: {
        event_type: eventTypes[i],
        actor_id: adminId,
        actor_type: 'admin',
        target_type: 'customer',
        target_id: typia.random<string & tags.Format<'uuid'>>(),
        event_payload,
      } satisfies IShoppingMallAiBackendComplianceEvent.ICreate,
    });
    typia.assert(event);
    createdEvents.push(event);
  }

  // 3. Attempt search as unauthorized (no Authorization header)
  const unauthorizedConn = { ...connection, headers: { ...connection.headers } };
  delete unauthorizedConn.headers.Authorization;
  await TestValidator.error('unauthorized search fails')(async () => {
    await api.functional.shoppingMallAiBackend.admin.complianceEvents.search(unauthorizedConn, {
      body: {},
    });
  });

  // 4a. Search by event type
  const typeIndex = 1; // Use a non-trivial event_type
  const byType = await api.functional.shoppingMallAiBackend.admin.complianceEvents.search(connection, {
    body: { event_type: eventTypes[typeIndex] } satisfies IShoppingMallAiBackendComplianceEvent.IRequest,
  });
  typia.assert(byType);
  TestValidator.predicate(`only '${eventTypes[typeIndex]}' events returned`)(byType.data.every(ev => ev.event_type === eventTypes[typeIndex]));

  // 4b. Search by actor ID
  const byActor = await api.functional.shoppingMallAiBackend.admin.complianceEvents.search(connection, {
    body: { actor_id: adminId } satisfies IShoppingMallAiBackendComplianceEvent.IRequest,
  });
  typia.assert(byActor);
  TestValidator.predicate('all events are by the registered admin')(byActor.data.every(ev => ev.actor_id === adminId));

  // 4c. Search by created_at date range
  const fiveMinAgo = new Date(now.valueOf() - 5 * 60000).toISOString();
  const fiveMinLater = new Date(now.valueOf() + 5 * 60000).toISOString();
  const byDate = await api.functional.shoppingMallAiBackend.admin.complianceEvents.search(connection, {
    body: { created_from: fiveMinAgo, created_to: fiveMinLater } satisfies IShoppingMallAiBackendComplianceEvent.IRequest,
  });
  typia.assert(byDate);
  TestValidator.predicate('all events within date window')(
    byDate.data.every(ev => ev.created_at >= fiveMinAgo && ev.created_at <= fiveMinLater)
  );

  // 4d. Pagination tests (page/limit)
  const byPage = await api.functional.shoppingMallAiBackend.admin.complianceEvents.search(connection, {
    body: { page: 1, limit: 2 } satisfies IShoppingMallAiBackendComplianceEvent.IRequest,
  });
  typia.assert(byPage);
  TestValidator.equals('pagination limit is 2')(byPage.pagination.limit)(2);
  TestValidator.predicate('data<=limit')(byPage.data.length <= 2);

  // 4e. Partial/keyword match (simulate event_type includes 'data')
  const byKeyword = await api.functional.shoppingMallAiBackend.admin.complianceEvents.search(connection, {
    body: { event_type: 'data' } satisfies IShoppingMallAiBackendComplianceEvent.IRequest,
  });
  typia.assert(byKeyword);
  TestValidator.predicate('all returned match partial event_type')(
    byKeyword.data.every(ev => ev.event_type.includes('data'))
  );

  // 5. Output structure + audit/privacy tests
  [byType, byActor, byDate, byPage, byKeyword].forEach(page => {
    typia.assert(page);
    page.data.forEach(ev => {
      TestValidator.predicate('has id')(!!ev.id);
      TestValidator.predicate('event_type present')(!!ev.event_type);
      TestValidator.predicate('actor_type present')(!!ev.actor_type);
      TestValidator.predicate('target_type present')(!!ev.target_type);
      TestValidator.predicate('created_at present')(!!ev.created_at);
    });
  });
}

