      note: null,
      current_status: "created",
    },
  });
  typia.assert(order);

  // 5. Seller creates N = 3 distinct snapshots of the order, with different reasons
  const snapshots = [];
  for (let i = 0; i < 3; i++) {
    const reason = ["created", "paid", "shipped"][i];
    // snapshot_json stores full order state as JSON, emulate with serialized order
