  TestValidator.equals("paid reason snap")(filtered.data[0].snapshot_reason)("paid");

  // 6.3. Date filtering: created_after, created_before
  const { created_at: firstTime } = snapshots[0];
  const { created_at: lastTime } = snapshots[2];
  const after1 = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
