  // 6.4. Limit/pagination: limit 2, page 1, page 2
  const page1 = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
    orderId: order.id,
    body: { limit: 2, page: 1 },
  });
  typia.assert(page1);
  TestValidator.equals("pagination page 1")(page1.data.length)(2);
  const page2 = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
    orderId: order.id,
    body: { limit: 2, page: 2 },
  });
  typia.assert(page2);
  TestValidator.predicate("pagination page 2")(page2.data.length >= 1);

  // 6.5. Sorting by created_at desc
  const desc = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.search(connection, {
