/**
 * Validates that deleting an order which is already soft-deleted behaves as expected (idempotent or error), without side effects, and ensures audit logging for compliance.
 *
 * Real-world business rationale: To maintain compliance and audit integrity, repeated deletions of soft-deleted orders should either be idempotent (succeed with no effect) or return a suitable error, but never cause additional side effects. Every deletion attempt must be recorded for audit purposes.
 *
 * Test Steps:
 * 1. Authenticate as an admin user via /auth/admin/login (to gain authorization for deletion).
 * 2. Create a customer order (to ensure a live target for deletion).
 * 3. Perform a DELETE as admin on the created order (first deletion, expect successful soft-delete).
 * 4. Attempt to DELETE the same order again as admin (test idempotency/error behavior).
 * 5. Confirm that the second DELETE does not visibly alter the state (e.g., deleted_at timestamp unchanged) and raises a business error or is idempotent.
 * 6. (Note: Audit log verification is mentioned but direct log inspection is not feasible here; audit log compliance is assumed if API end behavior matches doc contract).
 */
export async function test_api_order_delete_already_deleted(connection: api.IConnection) {
  // 1. Authenticate as admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "test_password_1234";
