    currency_code: "USD",
    note: "E2E double-delete test order",
    current_status: "created",
  } satisfies IShoppingMallAiBackendOrder.ICreate;
  const newOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: createOrderBody });
  typia.assert(newOrder);

  // 3. First deletion as admin (soft-delete)
  await api.functional.shoppingMallAiBackend.admin.orders.erase(connection, {
    orderId: newOrder.id,
