  // 8. Malformed request: page as string
  await TestValidator.error("malformed page param triggers validation error")(() =>
    api.functional.shoppingMallAiBackend.admin.categories.searchCategories(connection, {
      body: {
        name: "Category",
        page: "notANumber" as any,
        pageSize: 1,
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCategory";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test admin category creation: valid creation, duplicate rejection, parent_id validation, non-admin permission enforcement.
 *
 * This E2E test verifies the business logic and authorization of the shopping mall category creation API for the admin backend. It covers:
 *   1. A valid admin creates a root category and all persisted fields match input.
 *   2. Creating a duplicate code is correctly rejected.
 *   3. Using a nonexistent parent_id fails with error.
 *   4. Non-admin actors cannot create categories.
 *
 * Step-by-step process:
 * 1. Register an admin; capture JWT and adminId from the response.
 * 2. Use this admin to create an initial category (with no parent_id).
 *    - Confirm fields returned (code, name, created_by_admin_id, etc.) match inputs.
 * 3. Attempt to create a category with duplicate code (expect error).
 * 4. Attempt to create a category with an invalid parent_id (expect error).
 * 5. Attempt to create a category using a fresh unauthenticated connection (no admin JWT; expect permission error).
 */
export async function test_api_category_creation_valid_duplicate_and_invalid_parent(connection: api.IConnection) {
  // 1. Register a new admin and retrieve JWT profile
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const signUpResp: IAdminAuth.JwtWithProfile = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(signUpResp);
  const adminId = signUpResp.adminId;

  // 2. Admin creates a new root category (no parent_id)
  // Use a unique code
  const uniqueCode = RandomGenerator.alphaNumeric(8);
  const inputCategory: IShoppingMallAiBackendCategory.ICreate = {
    code: uniqueCode,
    name: RandomGenerator.name(),
    description: RandomGenerator.content()()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    visible: true,
    created_by_admin_id: adminId,
    parent_id: null // root category
  };
  const created: IShoppingMallAiBackendCategory = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: inputCategory
  });
  typia.assert(created);
  // Assert critical fields match
  TestValidator.equals("code matches")(created.code)(inputCategory.code);
  TestValidator.equals("name matches")(created.name)(inputCategory.name);
  TestValidator.equals("created_by_admin_id matches")(created.created_by_admin_id)(adminId);
  TestValidator.equals("parent_id matches")(created.parent_id)(null);
  TestValidator.equals("visible matches")(created.visible)(inputCategory.visible);
  TestValidator.equals("display_order matches")(created.display_order)(inputCategory.display_order);
  if (typeof inputCategory.description === "string")
    TestValidator.equals("description matches")(created.description)(inputCategory.description);

  // 3. Attempt to create category with the same code (should fail)
  const dupInput: IShoppingMallAiBackendCategory.ICreate = {
    code: uniqueCode, // same code
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    visible: true,
    created_by_admin_id: adminId
  };
  await TestValidator.error("duplicate code should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
      body: dupInput
    });
  });

  // 4. Attempt to create with invalid parent_id (should fail)
  const invalidParentId = typia.random<string & tags.Format<"uuid">>();
  const invalidParentInput: IShoppingMallAiBackendCategory.ICreate = {
    code: RandomGenerator.alphaNumeric(9),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    visible: true,
    created_by_admin_id: adminId,
    parent_id: invalidParentId
  };
  await TestValidator.error("invalid parent_id should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
      body: invalidParentInput
    });
  });

  // 5. Try category creation as non-admin (simulate by using a fresh plain connection)
  const plainInput: IShoppingMallAiBackendCategory.ICreate = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    visible: true,
    created_by_admin_id: adminId // This is technically still the admin's UUID, but the JWT is missing
  };
  // Remove/set empty Authorization header to simulate non-admin (no JWT)
  const plainConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("non-admin should be denied")(async () => {
    await api.functional.shoppingMallAiBackend.admin.categories.createCategory(plainConnection, {
      body: plainInput
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCategory";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate soft-deleting (logical delete) of a category entity as an admin, and permission enforcement.
 *
 * This test confirms:
 * 1. Admin can create a root category, soft-delete it, and the operation completes with no error (deleted_at cannot be fetched directly as there is no list/search API).
 * 2. Deleting a non-existent or already-deleted category returns a runtime business error.
 * 3. If a parent category has an active child, deleting the parent fails (blocked or cascades with error, depending on backend logic).
 * 4. Permission is properly enforced: Non-admin users (or missing Authorization) cannot soft-delete categories.
 *
 * Test Steps:
 * 1. Register a new admin and extract adminId for creation privilege.
 * 2. Create a root category as admin, and then soft-delete it by UUID.
 * 3. Soft-delete using random (non-existent) UUID is denied (error).
 * 4. Create a parent & child category, attempt to delete the parent (expect error if active child exists).
 * 5. Attempt deletion as non-admin (remove Authorization); must be denied.
 */
export async function test_api_category_soft_delete_success_dependency_and_not_found(connection: api.IConnection) {
  // 1. Register admin and obtain adminId, privilege
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPwd123!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAuth);
  const adminId = adminAuth.adminId;

  // 2. Create a root category as admin
  const categoryCode = RandomGenerator.alphaNumeric(9);
  const category = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: null,
      created_by_admin_id: adminId,
      code: categoryCode,
      name: RandomGenerator.name(),
      description: "Root category for soft-delete E2E test.",
      display_order: 1,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(category);

  // 3. Soft-delete the category as admin (should succeed)
  await api.functional.shoppingMallAiBackend.admin.categories.eraseCategory(connection, {
    categoryId: category.id,
  });

  // 4. Try to delete a non-existent or already deleted category — expect error
  await TestValidator.error("delete of non-existent category fails")(() =>
    api.functional.shoppingMallAiBackend.admin.categories.eraseCategory(connection, {
      categoryId: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 5. Parent-child delete: create parent and child, attempt parent deletion
  const parentCode = RandomGenerator.alphaNumeric(7);
  const parent = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: null,
      created_by_admin_id: adminId,
      code: parentCode,
      name: RandomGenerator.name(),
      description: "Parent category (for child block test).",
      display_order: 2,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(parent);
  const childCode = RandomGenerator.alphaNumeric(7);
  const child = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: parent.id,
      created_by_admin_id: adminId,
      code: childCode,
      name: RandomGenerator.name(),
      description: "Child category of parent (active)",
      display_order: 3,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(child);
  await TestValidator.error("cannot delete parent with active child — expect block or cascade failure")(() =>
    api.functional.shoppingMallAiBackend.admin.categories.eraseCategory(connection, {
      categoryId: parent.id,
    })
  );

  // 6. Permission enforcement: try as non-admin (no Authorization header)
  const noAuthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined }};
  await TestValidator.error("permission denied for non-admin")(() =>
    api.functional.shoppingMallAiBackend.admin.categories.eraseCategory(noAuthConnection, {
      categoryId: child.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IPageIShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomer";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate the admin panel's customer search API with advanced filters and pagination, ensuring correct response structure and error handling.
 *
 * This test simulates a realistic admin interaction with the customer search panel. Key business points:
 * - Admin login is required for all operations (authenticated scenario).
 * - All available search/filter options (email, nickname, verified status, joined date, pagination) are tested.
 * - Response structure (pagination meta and summary record array) is validated.
 * - Scenario covers positive flows (varied filter use, pagination) and negative ones (malformed filter, unauthorized request).
 * - Coverage includes privacy guarantees (actual masking is backend's duty; schema shape is enforced), and forbidden soft-deleted users (by filter logic).
 *
 * Steps:
 * 1. Authenticate as admin and verify the access token.
 * 2. Search customers with no filter, confirm list shape/contents.
 * 3. Search by partial email.
 * 4. Search by partial nickname.
 * 5. Search by phone-verified status.
 * 6. Search by join date window.
 * 7. Paginate with custom limit/page.
 * 8. Confirm soft-deleted/withdrawn accounts do not surface when excluded by status.
 * 9. Trigger and assert filter/type error.
 * 10. Check unauthorized access error is handled as expected.
 */
export async function test_api_customer_search_admin_filter_pagination(connection: api.IConnection) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPass123!";
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);
  TestValidator.equals("setHeaders.Authorization is Bearer token")(true)(
    typeof adminSignIn.setHeaders.Authorization === "string" && adminSignIn.setHeaders.Authorization.startsWith("Bearer ")
  );

  // 2. All customer search: no filter (should produce some records)
  const respAll = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
    body: {},
  });
  typia.assert(respAll);
  TestValidator.predicate("pagination fields ok")(
    typeof respAll.pagination.current === "number" &&
    typeof respAll.pagination.limit === "number" &&
    typeof respAll.pagination.records === "number" &&
    typeof respAll.pagination.pages === "number"
  );
  TestValidator.predicate("summary records array present")(
    Array.isArray(respAll.data)
  );
  if (respAll.data.length > 0) {
    for (const customer of respAll.data) {
      typia.assert(customer);
    }
  }

  // 3. Filter by partial email
  const filterEmail = respAll.data.length > 0 ? respAll.data[0].email.slice(0, 4) : "a";
  const respByEmail = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
    body: { email: filterEmail },
  });
  typia.assert(respByEmail);
  for (const customer of respByEmail.data) {
    TestValidator.predicate("email partial match")(
      customer.email.includes(filterEmail)
    );
  }

  // 4. Filter by partial nickname
  if (respAll.data.length > 0) {
    const filterNickname = respAll.data[0].nickname.slice(0, 2);
    const respByNick = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
      body: { nickname: filterNickname },
    });
    typia.assert(respByNick);
    for (const customer of respByNick.data) {
      TestValidator.predicate("nickname partial match")(
        customer.nickname.includes(filterNickname)
      );
    }
  }

  // 5. Filter by phone_verified true
  const respByPhoneVerified = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
    body: { phone_verified: true },
  });
  typia.assert(respByPhoneVerified);
  for (const customer of respByPhoneVerified.data) {
    TestValidator.predicate("phone string format")(
      typeof customer.phone === "string"
    );
  }

  // 6. Registration date window: pick customer date and filter by that
  if (respAll.data.length > 0) {
    const anyCustomer = respAll.data[0];
    const joined_at = anyCustomer.joined_at;
    const respByDate = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
      body: { joined_from: joined_at, joined_to: joined_at },
    });
    typia.assert(respByDate);
    for (const customer of respByDate.data) {
      TestValidator.equals("joined_at matches filter")(customer.joined_at)(joined_at);
    }
  }

  // 7. Pagination: set page and limit
  const respPaging = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
    body: { page: 1, pageSize: 2 },
  });
  typia.assert(respPaging);
  TestValidator.equals("limit matches pageSize")(respPaging.pagination.limit)(2);
  TestValidator.equals("current page is 1")(respPaging.pagination.current)(1);
  TestValidator.predicate("max 2 records on page")(respPaging.data.length <= 2);

  // 8. Check status filter for 'withdrawn' exclusion
  if (respAll.data.find((c) => c.status === "withdrawn")) {
    const respNoWithdrawn = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
      body: { status: "active" },
    });
    typia.assert(respNoWithdrawn);
    for (const customer of respNoWithdrawn.data) {
      TestValidator.notEquals("No withdrawn/soft-deleted in active filter")(customer.status)("withdrawn");
    }
  }

  // 9. Malformed filter: wrong type for email_verified
  await TestValidator.error("malformed filter triggers error")(
    async () => {
      // @ts-expect-error Intentionally wrong type
      // @ts-ignore
      await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
        body: { email_verified: "YES_WRONG_TYPE" },
      });
    }
  );

  // 10. Unauthorized access rejection
  const anonymousConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized access rejected")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.customers.search(anonymousConnection, {
        body: {},
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSeller";
import type { IPageIShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSeller";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBackendSellerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSellerHistory";
import type { IPageIShoppingMallAiBackendSellerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSellerHistory";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test the retrieval and access control of a seller history record by admin.
 *
 * This function validates the following scenario flows:
 * 1. Admin successfully fetches an existing seller history record and checks all fields.
 * 2. Attempt to fetch a non-existent history record (should receive not found error).
 * 3. Attempt to fetch with a valid historyId under a mismatched sellerId (should receive not found/forbidden).
 * 4. Access control: ensure only admins can fetch seller history records—other roles must be denied.
 *
 * Steps:
 * 1. Log in as admin and get token.
 * 2. Query/search for an existing seller with history (using admin).
 * 3. Fetch admin side seller history event list for that seller. Require at least one event to continue.
 * 4. Use a valid sellerId/historyId pair for positive case.
 * 5. Attempt fetch with random, non-existent historyId for negative case.
 * 6. Attempt fetch with valid historyId, but wrong sellerId.
 * 7. Log out/revert and use a connection without admin JWT, repeat fetch attempt (should be denied).
 */
export async function test_api_seller_history_detail_success_and_access_control(connection: api.IConnection) {
  // 1. Log in as admin to acquire token
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234";
  // Simulate (or require) the existence of admin credentials in test environment
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);

  // 2. Search for a seller with existing action history
  const sellersPage = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
    body: {
      page: 1,
      limit: 10
    } satisfies IShoppingMallAiBackendSeller.IRequest,
  });
  typia.assert(sellersPage);
  const seller = sellersPage.data.find((s) => s.status === "active") ?? sellersPage.data[0];
  TestValidator.predicate("seller exists")(!!seller);

  // 3. Fetch history list for this seller (require at least one record)
  const sellerHistoriesPage = await api.functional.shoppingMallAiBackend.admin.sellers.histories.search(connection, {
    sellerId: seller.id,
    body: {
      seller_id: seller.id,
      page: 1,
      limit: 5
    } satisfies IShoppingMallAiBackendSellerHistory.IRequest,
  });
  typia.assert(sellerHistoriesPage);
  const history = sellerHistoriesPage.data[0];
  TestValidator.predicate("At least one history record exists")(!!history);

  // 4. Success case: fetch the history by correct sellerId/historyId
  const fetched = await api.functional.shoppingMallAiBackend.admin.sellers.histories.at(connection, {
    sellerId: seller.id,
    historyId: history.id,
  });
  typia.assert(fetched);
  TestValidator.equals("seller_id matches")(fetched.seller_id)(seller.id);
  TestValidator.equals("historyId matches")(fetched.id)(history.id);

  // 5. Negative case: fetch with random (non-existent) historyId
  await TestValidator.error("not found for random historyId")(() =>
    api.functional.shoppingMallAiBackend.admin.sellers.histories.at(connection, {
      sellerId: seller.id,
      historyId: typia.random<string & tags.Format<"uuid">>()
    })
  );

  // 6. Negative case: mismatch sellerId/historyId
  // Find or generate another seller
  let otherSellerId = null;
  if (sellersPage.data.length > 1) {
    otherSellerId = sellersPage.data.find((s) => s.id !== seller.id)?.id;
  } else {
    // Try to get another seller by re-querying next page
    const moreSellersPage = await api.functional.shoppingMallAiBackend.admin.sellers.search(connection, {
      body: { page: 2, limit: 10 } satisfies IShoppingMallAiBackendSeller.IRequest,
    });
    typia.assert(moreSellersPage);
    otherSellerId = moreSellersPage.data.find((s) => s.id !== seller.id)?.id;
  }
  if (otherSellerId) {
    await TestValidator.error("historyId not belonging to other seller should fail")(() =>
      api.functional.shoppingMallAiBackend.admin.sellers.histories.at(connection, {
        sellerId: otherSellerId!,
        historyId: history.id,
      })
    );
  }

  // 7. Access control: use connection without valid admin JWT
  // Remove Authorization header to simulate unauthenticated/non-admin
  const nonAdminConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("forbidden for non-admin")(() =>
    api.functional.shoppingMallAiBackend.admin.sellers.histories.at(nonAdminConnection, {
      sellerId: seller.id,
      historyId: history.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAdmin";
import type { IPageIShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate the admin list search endpoint with pagination, filtering, date range, no-match, and role-based access.
 *
 * This test verifies that an authenticated admin can search for admin users, apply search criteria, and that non-admins are denied access. Confirm pagination metadata is correct, filters work as expected, and security is enforced.
 *
 * Steps:
 * 1. Authenticate as admin (login via /auth/admin/login)
 * 2. Retrieve first page (defaults) and validate structure and pagination
 * 3. Apply filter (e.g., by role or status) and check that results respect filter
 * 4. Apply date range filter (joined_from, joined_to) and check results are within range
 * 5. Search with impossible criteria to expect empty result
 * 6. Attempt API as non-admin (JWT not present or invalid) and confirm access denied
 */
export async function test_api_admin_list_search_pagination_and_role_restriction(connection: api.IConnection) {
  // 1. Authenticate as an admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "testPassword123!";
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);

  // The JWT is stored in connection.headers automatically

  // 2. Retrieve first page with default filters
  const defaultPage = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: {},
  });
  typia.assert(defaultPage);
  TestValidator.predicate("pagination metadata exists")(!!defaultPage.pagination);
  TestValidator.predicate("data is array")(Array.isArray(defaultPage.data));

  // 3. Filtering by role and status, if at least one admin exists
  if (defaultPage.data.length > 0) {
    const firstAdmin = defaultPage.data[0];
    const filtered = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
      body: {
        role: firstAdmin.role,
        status: firstAdmin.status,
      },
    });
    typia.assert(filtered);
    TestValidator.predicate("all match role")(
      filtered.data.every(a => a.role === firstAdmin.role)
    );
    TestValidator.predicate("all match status")(
      filtered.data.every(a => a.status === firstAdmin.status)
    );
  }

  // 4. Filtering by joined date range, if there is at least one admin
  if (defaultPage.data.length > 0) {
    const firstAdmin = defaultPage.data[0];
    const joinedAt: string = firstAdmin.joined_at;
    const byJoinDate = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
      body: {
        joined_from: joinedAt,
        joined_to: joinedAt,
      },
    });
    typia.assert(byJoinDate);
    TestValidator.predicate("all within date range")(
      byJoinDate.data.every(
        a => a.joined_at >= joinedAt && a.joined_at <= joinedAt
      )
    );
  }

  // 5. No-match search returns empty data
  const none = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: {
      email: "impossible_email_address@noexist.example.com",
    },
  });
  typia.assert(none);
  TestValidator.equals("empty data")(none.data.length)(0);
  TestValidator.predicate("valid pagination")(!!none.pagination);

  // 6. Access denied for non-admin token
  connection.headers.Authorization = undefined;
  await TestValidator.error("access denied for non-admin")(() =>
    api.functional.shoppingMallAiBackend.admin.admins.search(connection, { body: {} })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAdmin";
import type { IPageIShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate fetching details of a specific admin account by adminId.
 *
 * Business context: Only authenticated admin users with sufficient permissions can fetch admin user details. Required for admin management and auditing, but sensitive credentials (e.g., password hash) must remain undisclosed. The test also validates proper error handling and access control.
 *
 * Test steps:
 * 1. Authenticate as a valid admin via login (obtain JWT).
 * 2. Query the paginated admin list (search) to obtain a real adminId for positive test.
 * 3. Use the valid adminId to fetch details. Validate all profile, role, and status fields are present, but no sensitive fields such as password hash exist.
 * 4. Attempt to fetch details with a non-existent adminId (random UUID). Validate that a not-found error occurs.
 * 5. Simulate a session without admin token (removing Authorization header) and attempt to fetch details, expecting unauthorized/forbidden error.
 */
export async function test_api_admin_detail_success_and_error(
  connection: api.IConnection,
) {
  // 1. Get a valid admin credentials from search results
  const searchResult = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: {}
  });
  typia.assert(searchResult);
  TestValidator.predicate("At least one admin exists")(searchResult.data.length > 0);
  const validAdmin = searchResult.data[0];
  TestValidator.predicate("Admin ID exists")(!!validAdmin.id);

  // 2. Log in as admin (ensure Authorization header is set)
  const login = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: validAdmin.email, password: "admin" } satisfies IAdminAuth.SignIn,
  });
  typia.assert(login);
  // Now connection.headers.Authorization is set for admin session

  // 3. Success: fetch details for the valid adminId
  const detail = await api.functional.shoppingMallAiBackend.admin.admins.at(connection, {
    adminId: validAdmin.id,
  });
  typia.assert(detail);
  // Business field assertions
  TestValidator.equals("Admin ID matches")(detail.id)(validAdmin.id);
  TestValidator.equals("Email matches")(detail.email)(validAdmin.email);
  TestValidator.equals("Name matches")(detail.name)(validAdmin.name);
  TestValidator.equals("Role present")(typeof detail.role)("string");
  TestValidator.equals("Status present")(typeof detail.status)("string");
  TestValidator.equals("Joined_at present")(typeof detail.joined_at)("string");
  // Ensure no sensitive password field exists
  TestValidator.equals("Password field is absent")("password_hash" in detail)(false);

  // 4. Attempt to fetch with a non-existent adminId (random UUID)
  const randomAdminId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Not found with random adminId")(async () => {
    await api.functional.shoppingMallAiBackend.admin.admins.at(connection, {
      adminId: randomAdminId,
    });
  });

  // 5. Simulate missing Authorization (not logged in)
  const connectionNoAuth = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("Unauthorized when not admin")(async () => {
    await api.functional.shoppingMallAiBackend.admin.admins.at(connectionNoAuth, {
      adminId: validAdmin.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAdmin";
import type { IPageIShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate soft-deletion and idempotency for admin accounts (set deleted_at field).
 *
 * This test covers the admin deletion workflow and all error/idempotency cases:
 *
 * 1. Log in as admin with sufficient privileges
 * 2. List current admins and select a non-self, active admin as the target
 * 3. Soft delete the selected admin by adminId
 * 4. Search for the same admin and ensure it no longer appears in unfiltered result
 * 5. Repeat the delete—should return error (not found/idempotent)
 * 6. Attempt to delete a random, non-existent adminId and expect error
 * 7. Remove JWT from connection and attempt deletion—should fail for insufficient permissions
 * 8. (Note: Audit/history endpoint is not present for programmatic test)
 *
 * Prerequisites: The E2E infrastructure must contain at least two valid admin accounts: one to act as operator (test runner), and one to be the deletion target. If the infra creates/cleans up its own admin(s), this test must adapt accordingly.
 */
export async function test_api_admin_soft_delete_and_idempotency(
  connection: api.IConnection,
) {
  // 1. Login as a privileged admin user
  // NOTE: The test requires a valid admin for login; actual E2E infra should provide secrets/config or guarantee setup.
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin_password_123";
  const auth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(auth);

  // 2. Fetch admins, pick another active (non-self, not deleted) admin for deletion
  const page = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: { status: "active", page: 1, limit: 10 },
  });
  typia.assert(page);
  const candidates = page.data.filter(
    (a) => a.email !== adminEmail && !a.deleted_at,
  );
  if (!candidates.length) throw new Error("No other active admin available for deletion test.");
  const target = candidates[0];

  // 3. Soft delete the selected admin
  await api.functional.shoppingMallAiBackend.admin.admins.erase(connection, {
    adminId: target.id,
  });

  // 4. Search; deleted admin should not be found among active accounts
  const after = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: { status: "active", email: target.email, page: 1, limit: 10 },
  });
  typia.assert(after);
  TestValidator.equals("deleted admin not returned")(
    after.data.findIndex((a) => a.id === target.id),
  )(-1);

  // 5. Repeat delete: should throw (idempotent or not found)
  await TestValidator.error("repeat delete fails")(
    async () =>
      await api.functional.shoppingMallAiBackend.admin.admins.erase(connection, {
        adminId: target.id,
      }),
  );

  // 6. Delete non-existent adminId: expect error
  await TestValidator.error("random adminId delete fails")(
    async () =>
      await api.functional.shoppingMallAiBackend.admin.admins.erase(connection, {
        adminId: typia.random<string & tags.Format<"uuid">>(),
      }),
  );

  // 7. Remove JWT/Authorization; expect forbidden error on erase
  const noAuth: api.IConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete noAuth.headers["Authorization"];
  await TestValidator.error("forbidden without admin JWT")(
    async () =>
      await api.functional.shoppingMallAiBackend.admin.admins.erase(noAuth, {
        adminId: target.id,
      }),
  );

  // 8. Audit/history confirmation (manual)
  // NOTE: No endpoint or event inspection for audit/history available in current SDK
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachment";
import type { IShoppingMallAiBackendAttachmentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachmentLog";
import type { IPageIShoppingMallAiBackendAttachmentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAttachmentLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test: Validate log search for attachment (admin only) with pagination/filtering
 *
 * Business context:
 * Attachment audit log search is security-critical. Admins must be able to search event logs
 * for a given attachment file, filtering by business event, date, operator, and paging. Result
 * must always be for the correct attachment, only include valid logs (exclude soft-deleted ones),
 * and supply correct pagination meta.
 *
 * Steps:
 * 1. Create a new attachment as admin
 * 2. Create multiple log entries (upload, download, access) for that attachment with different event_types, contexts, and timestamps
 * 3. Search logs for the attachment:
 *    a. Without filter (should see all logs)
 *    b. Filtering by event_type
 *    c. Pagination (pageSize)
 *    d. Date/time range filter
 *    e. Edge: filter with no matches
 * 4. Validate every result has the correct attachment_id and no soft-deletion
 * 5. Validate all pagination metadata on response
 * 6. Error case: invalid attachmentId
 * 7. Error case: malformed filter (bad date)
 */
export async function test_api_attachment_log_search_basic_pagination_filtering(connection: api.IConnection) {
  // 1. Create a new attachment as admin
  const attachment = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, {
    body: {
      owner_id: typia.random<string & tags.Format<'uuid'>>(),
      owner_type: 'admin',
      file_name: RandomGenerator.alphaNumeric(14),
      file_size: typia.random<number & tags.Type<'int32'>>(),
      mime_type: 'application/pdf',
      storage_uri: `s3://e2e-test-bucket/file-${Date.now()}.pdf`,
      hash_sha256: RandomGenerator.alphaNumeric(64),
      uploaded_at: new Date(Date.now() - 86400000).toISOString(),
      expire_at: null,
      description: 'E2E: attachment for log search test',
    } satisfies IShoppingMallAiBackendAttachment.ICreate
  });
  typia.assert(attachment);

  // 2. Create multiple log entries (simulate upload, download, access)
  const event_types = ['upload', 'download', 'access'];
  const logs = [];
  const adminId = typia.random<string & tags.Format<'uuid'>>();
  const baseTimestamp = Date.now() - 100000;
  for (let i = 0; i < event_types.length; ++i) {
    const created = await api.functional.shoppingMallAiBackend.admin.attachments.logs.create(connection, {
      attachmentId: attachment.id,
      body: {
        event_type: event_types[i],
        ip_address: `192.168.1.${i+1}`,
        operated_by_admin_id: adminId,
        event_context: `Automated log ${i+1}`,
        event_at: new Date(baseTimestamp + i * 1000).toISOString(),
      } satisfies IShoppingMallAiBackendAttachmentLog.ICreate
    });
    typia.assert(created);
    logs.push(created);
  }

  // 3a. Search logs for the attachment with no filter (all logs)
  {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: {}
    });
    typia.assert(found);
    TestValidator.equals('returns all logs')(found.data.length)(logs.length);
    found.data.forEach(x => {
      TestValidator.equals('correct attachment_id')(x.attachment_id)(attachment.id);
      TestValidator.equals('no soft delete')(x.deleted_at)(undefined);
    });
    TestValidator.equals('pagination current')(found.pagination.current)(1);
    TestValidator.equals('pagination limit')(found.pagination.limit)(25);
    TestValidator.equals('pagination records')(found.pagination.records)(logs.length);
    // Should be only one page (<=25)
    TestValidator.equals('pagination pages')(found.pagination.pages)(1);
  }

  // 3b. Filter by event_type
  for (let i = 0; i < event_types.length; ++i) {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_type: event_types[i] }
    });
    typia.assert(found);
    TestValidator.equals(`1 log for event_type ${event_types[i]}`)(found.data.length)(1);
    found.data.forEach(x => {
      TestValidator.equals('event_type')(x.event_type)(event_types[i]);
      TestValidator.equals('correct attachment_id')(x.attachment_id)(attachment.id);
      TestValidator.equals('no soft delete')(x.deleted_at)(undefined);
    });
    // Pagination meta (should still be one page, but records=1)
    TestValidator.equals('pagination records')(found.pagination.records)(1);
    TestValidator.equals('pagination pages')(found.pagination.pages)(1);
  }

  // 3c. Pagination: pageSize=2
  {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { page: 1, pageSize: 2 }
    });
    typia.assert(found);
    TestValidator.equals('pageSize')(found.pagination.limit)(2);
    TestValidator.equals('first page')(found.pagination.current)(1);
    TestValidator.predicate('at most 2 logs')(found.data.length <= 2);
    found.data.forEach(x => {
      TestValidator.equals('no soft delete')(x.deleted_at)(undefined);
    });
  }

  // 3d. Date/time range filter: should find logs in selected range
  {
    const from = logs[1].event_at;
    const to = logs[2].event_at;
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_at_from: from, event_at_to: to }
    });
    typia.assert(found);
    found.data.forEach(l => {
      TestValidator.predicate('event_at after from')(l.event_at >= from);
      TestValidator.predicate('event_at before to')(l.event_at <= to);
    });
    found.data.forEach(x => {
      TestValidator.equals('correct attachment_id')(x.attachment_id)(attachment.id);
      TestValidator.equals('no soft delete')(x.deleted_at)(undefined);
    });
  }

  // 3e. Empty result when event_type does not exist
  {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_type: 'nonexistent_event' }
    });
    typia.assert(found);
    TestValidator.equals('empty for nonexistent type')(found.data.length)(0);
    TestValidator.equals('records 0')(found.pagination.records)(0);
    TestValidator.equals('pages 0')(found.pagination.pages)(0);
  }

  // 4. Error: invalid attachment id
  await TestValidator.error('attachment id does not exist')(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: typia.random<string & tags.Format<'uuid'>>(),
      body: {}
    })
  );

  // 5. Error: malformed filter (bad date)
  await TestValidator.error('malformed filter')(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_at_from: 'not-a-date' as any }
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachment";
import type { IShoppingMallAiBackendAttachmentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachmentLog";

/**
 * Validate detailed access control and existence logic for attachment log retrieval.
 *
 * Ensures a single attachment log can be fetched by attachmentId and logId with complete information.
 * Tests positive (success) and negative (failure/forbidden/not found) scenarios:
 *   1. Successfully create a test attachment (as admin).
 *   2. Register a log entry for this attachment (as admin).
 *   3. Retrieve this log by attachmentId and attachmentLogId (expect all fields: event_type, ip_address, operated_by_admin_id, event_context, event_at).
 *   4. Attempt to access with wrong logId (expect 404 or error).
 *   5. Attempt to access with wrong attachmentId (expect 404 or error).
 *   6. (If possible) Remove log or attachment, then try retrieve (expect error).
 *   7. Attempt as unauthorized user (simulate role switch) to confirm admin-only access (expect forbidden/unauthorized).
 * Each step includes full response structure validation and business logic checks.
 */
export async function test_api_attachment_log_detail_access_control_and_existence(connection: api.IConnection) {
  // 1. Create a test attachment
  const attachment = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, {
    body: typia.random<IShoppingMallAiBackendAttachment.ICreate>()
  });
  typia.assert(attachment);

  // 2. Register a log entry for this attachment
  const logInput: IShoppingMallAiBackendAttachmentLog.ICreate = {
    event_type: "upload",
    ip_address: "127.0.0.1",
    operated_by_admin_id: attachment.owner_id,
    event_context: "Initial upload",
    event_at: attachment.uploaded_at,
  };
  const log = await api.functional.shoppingMallAiBackend.admin.attachments.logs.create(connection, {
    attachmentId: attachment.id,
    body: logInput
  });
  typia.assert(log);

  // 3. Retrieve log detail by attachmentId and attachmentLogId
  const retrieved = await api.functional.shoppingMallAiBackend.admin.attachments.logs.at(connection, {
    attachmentId: attachment.id,
    attachmentLogId: log.id
  });
  typia.assert(retrieved);
  TestValidator.equals("fetched log matches created log")(retrieved.id)(log.id);
  TestValidator.equals("event_type matches")(retrieved.event_type)(logInput.event_type);
  TestValidator.equals("ip_address matches")(retrieved.ip_address)(logInput.ip_address);
  TestValidator.equals("operated_by_admin_id matches")(retrieved.operated_by_admin_id)(logInput.operated_by_admin_id);
  TestValidator.equals("event_context matches")(retrieved.event_context)(logInput.event_context);
  TestValidator.equals("event_at matches")(retrieved.event_at)(logInput.event_at);

  // 4. Attempt with incorrect logId (should error/404)
  await TestValidator.error("wrong logId should not resolve")(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.at(connection, {
      attachmentId: attachment.id,
      attachmentLogId: typia.random<string & tags.Format<"uuid">>()
    })
  );

  // 5. Attempt with incorrect attachmentId (should error/404)
  await TestValidator.error("wrong attachmentId should not resolve")(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.at(connection, {
      attachmentId: typia.random<string & tags.Format<"uuid">>(),
      attachmentLogId: log.id
    })
  );

  // 6. (Negative: delete is not available in API, so skip actual remove tests)

  // 7. Attempt as unauthorized user (simulate by clearing connection.headers.Authorization if possible)
  const unauthorizedConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthorized access should be denied")(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.at(unauthorizedConnection, {
      attachmentId: attachment.id,
      attachmentLogId: log.id
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IPageIShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCart";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test admin cart search endpoint handles invalid or malformed criteria gracefully.
 *
 * Business context: Admins may sometimes send request bodies with unknown or incorrectly typed fields to the PATCH /shoppingMallAiBackend/admin/carts endpoint (e.g., typo in filter name, wrong type (string instead of int for page/limit)). The API should validate incoming requests, return a validation error with proper description/code (e.g., 400 Bad Request), and avoid processing the request. The endpoint must not leak sensitive data or mistakenly accept/broadcast malformed queries. Auditing (error logging) is out of test scope and verified in service logs.
 *
 * Test Steps:
 * 1. Authenticate as admin using /auth/admin/login (dependency).
 * 2. Attempt to search carts with a request body containing an unrecognized field (e.g., {'foo': 'bar'}) and expect a runtime error.
 * 3. Attempt to search carts with a request body where 'page' is an invalid type (e.g., string instead of integer) and expect a runtime error.
 * 4. Verify both attempts raise errors and do NOT return a normal paginated cart result.
 */
export async function test_api_cart_admin_search_invalid_filter_error(connection: api.IConnection) {
