  TestValidator.predicate("cart updated_at is ISO8601")(typeof cart.updated_at === "string" && !isNaN(Date.parse(cart.updated_at)));
  if (cart.deleted_at !== undefined && cart.deleted_at !== null) {
    // If soft deletion ever returned, ensure it's ISO format
    TestValidator.predicate("deleted_at ISO8601")(typeof cart.deleted_at === "string" && !isNaN(Date.parse(cart.deleted_at)));
  }

  // Step 3: Attempt to create a second 'active' cart for the same customer
  TestValidator.error("Only one active cart per customer - duplication blocked")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
        body: {
          status: "active",
          session_token: null,
        }
      });
    }
  );
}

