import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerHistory";
import type { IPageIShoppingMallAiBackendCustomerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin access for retrieving customer history event details via GET /shoppingMallAiBackend/admin/customers/{customerId}/histories/{historyId}.
 *
 * This test ensures:
 *  - Admins can fetch full event details (event type, values, timestamps, actor) for a real, existing event not soft-deleted.
 *  - Non-admin (regular customer) requests are denied with proper error response.
 *  - Non-existent or soft-deleted history records result in correct error codes (not found/forbidden).
 *
 * Scenario covers:
 * 1. Register admin, obtain admin token.
 * 2. Register customer, obtain customerId.
 * 3. As admin, list customer's histories, pick a valid (not soft-deleted) event; save one valid historyId.
 * 4. As admin, fetch event detail for chosen (customerId, historyId) and validate all major fields.
 * 5. As customer (non-admin), attempt the same request—expect access denied error.
 * 6. As admin, attempt to fetch with a non-existent historyId—expect not found error.
 * 7. As admin, attempt to fetch with a soft-deleted history event, if one is present—expect not found or forbidden error.
 *
 * Steps 2-4 ensure the normal positive path. Steps 5-7 validate error handling and RBAC access control.
 *
 * If soft-deleted events aren't available, skip that negative case.
 */
export async function test_api_admin_access_customer_history_event(connection: api.IConnection) {
  // 1. Register admin; obtain admin JWT and set in connection.headers
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "TestAdminPw123!"
    }
  });
  typia.assert(adminSignUp);
  // 2. Register customer, extract customerId
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "TestCustomerPw123!",
      name: "Test Customer",
      nickname: "customer_" + Math.random().toString(36).substring(2, 8),
      phone: "010-" + Math.floor(1000 + Math.random()*9000) + "-" + Math.floor(1000 + Math.random()*9000)
    }
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;
  // 3. As admin: list customer histories
  const histories = await api.functional.shoppingMallAiBackend.admin.customers.histories.search(connection, {
    customerId,
    body: { customer_id: customerId }
  });
  typia.assert(histories);
  // Find a not-soft-deleted history event
  const validHistory = histories.data.find(h => !h.deleted_at);
  if (!validHistory) throw new Error("No valid history event found for customer");
  const historyId = validHistory.id;
  // 4. As admin, fetch event detail
  const detail = await api.functional.shoppingMallAiBackend.admin.customers.histories.at(connection, {
    customerId,
    historyId,
  });
  typia.assert(detail);
  TestValidator.equals("customerId")(detail.customer_id)(customerId);
  TestValidator.equals("historyId")(detail.id)(historyId);
  TestValidator.predicate("event_type should exist")(typeof detail.event_type === "string" && detail.event_type.length > 0);
  TestValidator.predicate("occurred_at should be ISO")(!!Date.parse(detail.occurred_at));
  // 5. As customer: try to fetch event detail, expect error
  connection.headers.Authorization = customerSignUp.setHeaders.Authorization;
  await TestValidator.error("customer forbidden from admin detail fetch")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.histories.at(connection, {
      customerId,
      historyId,
    });
  });
  // 6. As admin: try to fetch non-existent event, expect error
  connection.headers.Authorization = adminSignUp.setHeaders.Authorization;
  const fakeHistoryId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("historyId not found")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.histories.at(connection, {
      customerId,
      historyId: fakeHistoryId,
    });
  });
  // 7. If found, try to fetch soft-deleted event
  const softDeleted = histories.data.find(h => h.deleted_at);
  if (softDeleted) {
    await TestValidator.error("cannot fetch soft-deleted history")(async () => {
      await api.functional.shoppingMallAiBackend.admin.customers.histories.at(connection, {
        customerId,
        historyId: softDeleted.id,
      });
    });
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
