import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate updating an existing product content by the owner seller, and business/permission enforcement.
 *
 * This test covers:
 * 1. Register seller A
 * 2. Seller A creates a product
 * 3. Seller A adds product content (record initial values)
 * 4. Seller A updates content (change content_type, description, status)
 *    - Validate response reflects changes
 * 5. Attempt update as another seller (Seller B) – expect permission denial (error)
 * 6. Attempt update with invalid values (e.g. missing required, nonsense content_type, content_order negative)
 *    - Expect schema/business validation errors
 * 7. Soft-delete content (simulate by updating content's deleted_at if API allowed, else skip)
 *    - Attempt update after deletion, expect not found/error
 *
 * All steps assert correct type and expected business logic.
 */
export async function test_api_product_content_update_and_permissions(connection: api.IConnection) {
  // 1. Register seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "TestPassword1!",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.address(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerAReg);
  const sellerAId = sellerAReg.sellerId;

  // 2. Seller A creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "draft",
    },
  });
  typia.assert(product);
  const productId = product.id;

  // 3. Seller A adds a product content entity
  const contentCreateBody = {
    product_id: productId,
    content_type: "gallery_image",
    content_uri: "https://cdn.example.com/img1.jpg",
    content_order: 0,
    content_description: "Initial main image for product",
    status: "active",
  };
  const content = await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
    productId,
    body: contentCreateBody,
  });
  typia.assert(content);

  // 4. Seller A issues a valid update to the content
  const updateBody = {
    content_type: "main_image",
    content_description: "Changed to main image, updated text",
    status: "pending",
  };
  const updatedContent = await api.functional.shoppingMallAiBackend.seller.products.productContents.update(connection, {
    productId,
    productContentId: content.id,
    body: updateBody,
  });
  typia.assert(updatedContent);
  TestValidator.equals("content_type updated")(updatedContent.content_type)("main_image");
  TestValidator.equals("description updated")(updatedContent.content_description)("Changed to main image, updated text");
  TestValidator.equals("status updated")(updatedContent.status)("pending");

  // 5. Register a different seller (Seller B) for permission denial test
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "TestPassword1!",
      companyName: RandomGenerator.name(),
      businessNumber: "9876543210",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.address(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerBReg);
  // Swap to Seller B's JWT for next request
  connection.headers.Authorization = sellerBReg.setHeaders.Authorization;

  // 6. Seller B attempts update – expect permission denial
  await TestValidator.error("permission denial for non-owner update")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.update(connection, {
      productId,
      productContentId: content.id,
      body: {
        content_type: "gallery_image",
        status: "hidden",
      },
    });
  });

  // 7. Attempt update with invalid schema (negative content_order)
  connection.headers.Authorization = sellerAReg.setHeaders.Authorization; // switch back to seller A
  await TestValidator.error("invalid content_order rejected")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.update(connection, {
      productId,
      productContentId: content.id,
      body: {
        content_order: -1, // negative not allowed
      },
    });
  });
  // 8. Attempt update with invalid content_type value
  await TestValidator.error("invalid content_type rejected")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productContents.update(connection, {
      productId,
      productContentId: content.id,
      body: {
        content_type: "not_a_real_type",
      },
    });
  });

  // 9. (If API allowed) soft-delete content then attempt update (simulate by setting deleted_at if field/external call available)
  // For this test, simulate soft-delete by direct update (if API allowed) -- else, skip with a comment.
  // Skipping direct deletion as API is not present (only test not-found/update-after-deletion logic if API exists).
}

