    customerId,
    body: { city: cityA },
  });
  typia.assert(byCity);
  TestValidator.predicate(`all city == ${cityA}`)(byCity.data.every(a => a.city === cityA));

  // 7. Filter by state
  const byState = await api.functional.shoppingMallAiBackend.admin.customers.addresses.patchByCustomerid(connection, {
    customerId,
    body: { state: stateB },
  });
  typia.assert(byState);
  TestValidator.predicate(`all state == ${stateB}`)(byState.data.every(a => a.state === stateB));

  // 8. Filter by is_primary true
  const primaries = await api.functional.shoppingMallAiBackend.admin.customers.addresses.patchByCustomerid(connection, {
    customerId,
    body: { is_primary: true },
  });
  typia.assert(primaries);
  TestValidator.predicate("all primary")(primaries.data.every(a => a.is_primary));
  TestValidator.equals("single primary")(primaries.data.length)(1);

  // 9. Pagination: limit=2, page=2
  const paged = await api.functional.shoppingMallAiBackend.admin.customers.addresses.patchByCustomerid(connection, {
    customerId,
    body: { limit: 2, page: 2 },
  });
  typia.assert(paged);
  TestValidator.equals("page size")(paged.pagination.limit)(2);
  TestValidator.equals("page 2")(paged.pagination.current)(2);
  TestValidator.equals("pagination total records")(paged.pagination.records)(addresses.length);
  TestValidator.equals("pagination total pages")(paged.pagination.pages)(Math.ceil(addresses.length / 2));

  // 10. Query with non-existent customerId (expect error)
  const badCustomerId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent customerId fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.addresses.patchByCustomerid(connection, {
      customerId: badCustomerId,
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerAddress";
import type { IPageIShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerAddress";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validate customer self-address search, advanced filtering, pagination, and privacy enforcement.
 *
 * Simulates a real-world workflow in a shopping mall backend: a customer registers and logs in,
 * adds multiple delivery addresses, and then tests the self-address listing endpoint with diverse
 * filters and paginations—also verifying privacy boundaries so addresses remain accessible only
 * to their owner.
 *
 * Test flow:
 * 1. Register a customer (random email/phone).
 * 2. Log in to activate session and JWT.
 * 3. Add several addresses—mixing alias, city, and is_primary.
 * 4. List all addresses for the customer (plain, no filter, page 1/limit 10), checking all addresses returned belong to the customer.
 * 5. List by alias partial and verify result contains only the expected subset.
 * 6. List by city, verify only city-matching addresses are in result.
 * 7. Filter by is_primary and ensure only the primary address appears.
 * 8. Paginate with limit and second page; verify correct subset and pagination metadata.
 * 9. Attempt to fetch with other customer session and confirm privacy enforcement (error thrown or forbidden).
 * 10. Try with a non-existent/fake customerId and confirm error is raised.
 */
export async function test_api_customer_self_search_addresses_and_privacy(
  connection: api.IConnection,
) {
  // 1. Register a new customer account
  const email = typia.random<string & tags.Format<"email">>();
  const password = "Abc123!@#";
  const signUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUp);
  const customer = signUp.customer;
  const customerId = customer.id;

  // 2. Login as that customer to activate JWT in connection
  const signIn = await api.functional.auth.customer.login.signIn(connection, {
    body: { email, password } satisfies ICustomerSignIn.Request,
  });
  typia.assert(signIn);

  // 3. Add several (4) customer addresses
  const addressInputs = [
    { alias: "Home", city: "Seoul", is_primary: true },
    { alias: "Office", city: "Busan", is_primary: false },
    { alias: "Parents", city: "Incheon", is_primary: false },
    { alias: null, city: "Daegu", is_primary: false },
  ];
  const created: IShoppingMallAiBackendCustomerAddress[] = [];
  for (let i = 0; i < addressInputs.length; ++i) {
    const input = addressInputs[i];
    const addr = await api.functional.shoppingMallAiBackend.customer.customers.addresses.putByCustomerid(
      connection,
      {
        customerId,
        body: {
          id: typia.random<string & tags.Format<"uuid">>(),
          receiver_name: RandomGenerator.name(),
          receiver_phone: RandomGenerator.mobile(),
          postal_code: String(53000 + i),
          address_line1: RandomGenerator.paragraph()(6),
          address_line2: i % 2 === 0 ? null : RandomGenerator.alphaNumeric(4),
          city: input.city,
          state: "Seoul",
          country: "KR",
          is_primary: input.is_primary,
          alias: input.alias,
        } satisfies IShoppingMallAiBackendCustomerAddress.IUpdate,
      },
    );
    typia.assert(addr);
    created.push(addr);
  }

  // 4. List all addresses for this customer
  const resultAll = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(
    connection,
    {
      customerId,
      body: { page: 1, limit: 10 } satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
    },
  );
  typia.assert(resultAll);
  TestValidator.equals("total count")(resultAll.data.length)(created.length);
  for (const addr of resultAll.data)
    TestValidator.equals("owner check")(addr.customer_id)(customerId);

  // 5. List by alias partial match
  const aliasQuery = "Home";
  const expectedAlias = created.filter(
    (a) => typeof a.alias === "string" && a.alias.includes(aliasQuery),
  );
  const aliasResult = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(
    connection,
    { customerId, body: { alias: aliasQuery } satisfies IShoppingMallAiBackendCustomerAddress.IRequest },
  );
  typia.assert(aliasResult);
  TestValidator.equals("alias filter count")(aliasResult.data.length)(
    expectedAlias.length,
  );
  for (const addr of aliasResult.data)
    TestValidator.equals("alias contains")(typeof addr.alias === "string" && addr.alias.includes(aliasQuery))(true);

  // 6. List by city
  const cityQuery = "Busan";
  const expectedCity = created.filter((a) => a.city === cityQuery);
  const cityResult = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(
    connection,
    { customerId, body: { city: cityQuery } satisfies IShoppingMallAiBackendCustomerAddress.IRequest },
  );
  typia.assert(cityResult);
  TestValidator.equals("city count")(cityResult.data.length)(expectedCity.length);

  // 7. Primary only
  const primaryResult = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(
    connection,
    { customerId, body: { is_primary: true } satisfies IShoppingMallAiBackendCustomerAddress.IRequest },
  );
  typia.assert(primaryResult);
  TestValidator.equals("primary count")(primaryResult.data.length)(1);
  for (const addr of primaryResult.data) TestValidator.equals("is primary")(addr.is_primary)(true);

  // 8. Paginate: page 2, limit 2
  const paged = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(
    connection,
    { customerId, body: { page: 2, limit: 2 } satisfies IShoppingMallAiBackendCustomerAddress.IRequest },
  );
  typia.assert(paged);
  TestValidator.equals("pagination page")(paged.pagination.current)(2);
  TestValidator.equals("pagination limit")(paged.data.length)(2);

  // 9. Privacy check—another customer tries to access
  const badEmail = typia.random<string & tags.Format<"email">>();
  const badPass = "Qwerty1234!";
  const signUp2 = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: badEmail,
      password: badPass,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUp2);
  const signIn2 = await api.functional.auth.customer.login.signIn(connection, {
    body: { email: badEmail, password: badPass } satisfies ICustomerSignIn.Request,
  });
  typia.assert(signIn2);
  TestValidator.error("privacy denial")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(
      connection,
      { customerId, body: {} as IShoppingMallAiBackendCustomerAddress.IRequest },
    );
  });

  // 10. Invalid customerId
  const fakeCustomerId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("bad customer ID")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(
      connection,
      { customerId: fakeCustomerId, body: {} as IShoppingMallAiBackendCustomerAddress.IRequest },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
