import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSnapshot";
import type { IPageIShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test that product snapshot search for sellers works with filters, pagination, and access control.
 *
 * This test verifies:
 * - A seller sees only their product's snapshots, with filtering and pagination working.
 * - Other sellers cannot access snapshots of a product they do not own (permission enforcement).
 * - Filtering returns only the expected record(s).
 * - Searches with no matches return empty results.
 * - Historical snapshots remain accessible after soft deletion unless business logic restricts.
 *
 * Step-by-step process:
 * 1. Register seller1 and create a product (product1).
 * 2. Create multiple snapshots on product1, with varied data (snapshot_code, type, created_at).
 * 3. Filter/search snapshot history by snapshot_code, snapshot_type, and created_at interval.
 * 4. Confirm only matching results are returned and pagination metadata is present.
 * 5. Confirm a non-matching filter returns empty results.
 * 6. Register seller2, create product2, and a snapshot.
 * 7. Attempt to view product2's snapshots from seller1's context—verify permission error.
 * 8. Simulate soft delete on product1 and confirm that snapshot history remains accessible if business logic allows.
 */
export async function test_api_product_snapshot_search_with_permissions_and_filters_seller(connection: api.IConnection) {
  // 1. Register seller1
  const sellerEmail1 = typia.random<string & tags.Format<'email'>>();
  const seller1 = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail1,
      password: 'testpw123',
      companyName: RandomGenerator.company(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(seller1);
  connection.headers.Authorization = seller1.setHeaders.Authorization;

  // 2. Create product1
  const product1 = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: seller1.sellerId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.paragraph()(3),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: 'published',
    },
  });
  typia.assert(product1);

  // 3. Create multiple, diverse snapshots on product1
  const now = new Date();
  const snapshotData = [
    {
      snapshot_code: 'init-a',
      snapshot_type: 'created',
      name: 'Init Product',
      description: 'Initial snapshot',
      main_image_uri: null,
      status: 'draft',
      created_at: new Date(now.getTime() - 1000 * 60 * 60 * 24 * 2).toISOString(),
    },
    {
      snapshot_code: 'pub-b',
      snapshot_type: 'published',
      name: 'Public Product',
      description: 'Published version',
      main_image_uri: null,
      status: 'published',
      created_at: new Date(now.getTime() - 1000 * 60 * 60 * 24).toISOString(),
    },
    {
      snapshot_code: 'mod-c',
      snapshot_type: 'modified',
      name: 'Modified Product',
      description: 'After edit',
      main_image_uri: null,
      status: 'published',
      created_at: now.toISOString(),
    },
  ];
  for (const snap of snapshotData) {
    const snapRes = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.create(connection, {
      productId: product1.id,
      body: {
        product_id: product1.id,
        snapshot_code: snap.snapshot_code,
        snapshot_type: snap.snapshot_type,
        name: snap.name,
        description: snap.description,
        main_image_uri: snap.main_image_uri,
        status: snap.status,
      },
    });
    typia.assert(snapRes);
  }

  // 4. Search for snapshot by snapshot_code
  let searchRes = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.search(connection, {
    productId: product1.id,
    body: {
      product_id: product1.id,
      snapshot_code: 'pub-b',
    },
  });
  typia.assert(searchRes);
  TestValidator.predicate('only pub-b found')(searchRes.data.every(x => x.snapshot_code === 'pub-b'));
  TestValidator.predicate('pagination metadata present')(searchRes.pagination.current === 1);

  // 5. Filter by created_at interval (expect mod-c, only snapshot at "now")
  searchRes = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.search(connection, {
    productId: product1.id,
    body: {
      product_id: product1.id,
      created_at_from: now.toISOString(),
      created_at_to: now.toISOString(),
    },
  });
  typia.assert(searchRes);
  TestValidator.predicate('found only mod-c')(searchRes.data.every(x => x.snapshot_code === 'mod-c'));

  // 6. Filter by non-matching code (empty)
  searchRes = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.search(connection, {
    productId: product1.id,
    body: {
      product_id: product1.id,
      snapshot_code: 'nonexistent',
    },
  });
  typia.assert(searchRes);
  TestValidator.equals('empty')(searchRes.data.length)(0);

  // 7. Register seller2 and create product2 and a snapshot
  const sellerEmail2 = typia.random<string & tags.Format<'email'>>();
  const seller2 = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail2,
      password: 'testpw123',
      companyName: RandomGenerator.company(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(seller2);
  connection.headers.Authorization = seller2.setHeaders.Authorization;

  const product2 = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: seller2.sellerId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.paragraph()(3),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: 'published',
    },
  });
  typia.assert(product2);
  await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.create(connection, {
    productId: product2.id,
    body: {
      product_id: product2.id,
      snapshot_code: 'other-x',
      snapshot_type: 'created',
      name: 'Other Seller Product',
      description: null,
      main_image_uri: null,
      status: 'published',
    },
  });

  // 8. Switch back to seller1 and attempt to access product2's snapshots (should fail)
  connection.headers.Authorization = seller1.setHeaders.Authorization;
  await TestValidator.error('seller1 cannot access seller2 product snapshots')(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.search(connection, {
      productId: product2.id,
      body: { product_id: product2.id },
    });
  });

  // 9. Simulate soft delete and test snapshot access remains (business logic may differ)
  // If a real delete endpoint exists, this would call it
  // For now, just attempt to read snapshots again — expect accessible unless logic restricts
  searchRes = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.search(connection, {
    productId: product1.id,
    body: { product_id: product1.id },
  });
  typia.assert(searchRes);
  TestValidator.predicate('snapshots remain accessible after (simulated) deletion')(searchRes.data.length >= 1);
}

