import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSeller";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates that an admin can update the profile of a seller organization, ensuring correct compliance and audit behavior.
 *
 * This covers these major flows:
 * 1. Register and authenticate an admin (to perform updates on behalf of the platform)
 * 2. Register a new seller – ensuring a seller exists to be updated
 * 3. As admin, update the seller's profile (e.g., company name, address, and status)
 * 4. Verify that the response reflects the updates and still conforms to all type and business requirements
 *    (e.g., update logged in history, but since there is NO direct endpoint to validate log, we can only do positive tests)
 * 5. All updates must be type-safe, and edge cases (e.g., null, unchanged fields) should be handled gracefully
 */
export async function test_api_admin_update_seller_profile_success(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPW!234";
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignup);

  // 2. Login as the admin (to ensure a VALID JWT is set on connection)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register a seller that will be updated
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "sellerPW!345";
  const origCompanyName = "Original Company " + RandomGenerator.alphabets(6);
  const sellerSignup = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: origCompanyName,
      businessNumber: "1" + typia.random<string>().substring(0, 9),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignup);

  // 4. Prepare update fields (admin updating profile)
  const updateCompanyName = origCompanyName + " Updated";
  const updateAddress = RandomGenerator.paragraph()(12);
  const updateStatus = "active";
  const updateBody: IShoppingMallAiBackendSeller.IUpdate = {
    id: sellerSignup.sellerId,
    company_name: updateCompanyName,
    address: updateAddress,
    status: updateStatus,
  };

  // 5. As ADMIN, call the update endpoint for the seller
  const updatedSeller = await api.functional.shoppingMallAiBackend.admin.sellers.update(connection, {
    body: updateBody,
  });
  typia.assert(updatedSeller);

  // 6. Validate that the returned object matches the update
  TestValidator.equals("company name")(updatedSeller.company_name)(updateCompanyName);
  TestValidator.equals("address")(updatedSeller.address)(updateAddress);
  TestValidator.equals("status")(updatedSeller.status)(updateStatus);
  TestValidator.equals("id")(updatedSeller.id)(sellerSignup.sellerId);

  // 7. Non-updated fields remain unchanged (except those possibly system-modified, e.g. updated_at)
  TestValidator.equals("email")(updatedSeller.email)(sellerSignup.email);
  TestValidator.equals("business number")(updatedSeller.business_number)(sellerSignup.businessNumber);
  TestValidator.equals("representative name")(updatedSeller.representative_name)(sellerSignup.representativeName);
  TestValidator.equals("phone")(updatedSeller.phone)(sellerSignup.phone);

  // 8. Confirm types/format
  typia.assert<IShoppingMallAiBackendSeller>(updatedSeller);

  // NOTE: We cannot directly validate that seller_histories log is updated, but assume audit log works if no error.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSellerBusinessVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSellerBusinessVerification";
import type { IPageIShoppingMallAiBackendSellerBusinessVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSellerBusinessVerification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that an authenticated seller can retrieve their own business verification records with filtering and pagination.
 *
 * This test ensures:
 * 1. A seller account can be registered and authenticated.
 * 2. The seller can successfully create at least one business verification record.
 * 3. The seller can query for their business verifications, filter by document type and status, and receive valid paginated results.
 * 4. The returned data must only be the seller's own records with valid compliance state.
 *
 * Steps:
 * 1. Register a new seller account with random data.
 * 2. Login as the seller, ensuring authentication JWT is set in the connection context.
 * 3. Create a business verification record for this seller with a random document type/status.
 * 4. Search for business verifications, filtering explicitly by the seller's id, document type, verification status, and using typical pagination parameters (page & limit).
 * 5. Assert the results: at least one record matches, all have the correct seller_id, all fields are valid, and results respect the filters specified.
 */
export async function test_api_seller_business_verifications_search_success(connection: api.IConnection) {
  // 1. Register a new seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Test1234!";
  const companyName = RandomGenerator.name();
  const businessNumber = ArrayUtil.repeat(10)(() => Math.floor(Math.random()*10)).join("");
  const representativeName = RandomGenerator.name();
  const address = RandomGenerator.paragraph()(1);
  const phone = RandomGenerator.mobile();

  const signUpResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName,
      businessNumber,
      representativeName,
      address,
      phone,
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Login as the seller
  const signInResponse = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(signInResponse);

  const sellerId = signInResponse.sellerId;

  // 3. Create a business verification record for the seller
  const verificationType = RandomGenerator.pick([
    "business_license", "identity_card", "bankbook", "tax_certificate"
  ]);
  const verificationStatus = RandomGenerator.pick([
    "pending", "approved", "rejected", "reupload_required"
  ]);
  const documentFileUri = `https://files.example.com/${RandomGenerator.alphaNumeric(20)}`;
  const verificationNote = RandomGenerator.paragraph()();

  const updateResponse = await api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.putBySellerid(connection, {
    sellerId,
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      verification_status: verificationStatus,
      document_file_uri: documentFileUri,
      document_type: verificationType,
      note: verificationNote,
      reviewed_by: null,
      reviewed_at: null,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate,
  });
  typia.assert(updateResponse);

  // 4. Search for business verifications filtered by seller_id, document_type, and verification_status
  const searchResponse = await api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.patchBySellerid(connection, {
    sellerId,
    body: {
      seller_id: sellerId,
      document_type: verificationType,
      verification_status: verificationStatus,
      page: 1,
      limit: 10,
      orderBy: "created_at",
      orderDir: "desc",
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IRequest,
  });
  typia.assert(searchResponse);

  // 5. Assert results: at least one record matches, correct seller_id, correct types/status, valid pagination
  const { data, pagination } = searchResponse;
  TestValidator.predicate("at least one verification record is found")(data.length > 0);
  data.forEach((item) => {
    TestValidator.equals("seller_id matches")(item.seller_id)(sellerId);
    TestValidator.equals("document_type matches")(item.document_type)(verificationType);
    TestValidator.equals("verification_status matches")(item.verification_status)(verificationStatus);
  });
  TestValidator.equals("page number")(pagination.current)(1);
  TestValidator.equals("limit")(pagination.limit)(10);
}

