import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSellerBusinessVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSellerBusinessVerification";
import type { IPageIShoppingMallAiBackendSellerBusinessVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSellerBusinessVerification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that searching for business verification records as an unauthorized user (without authentication) does not succeed and does not return sensitive data.
 *
 * This test simulates an attempt to fetch a seller's business verification records via the PATCH endpoint as an unauthenticated actor. It first creates a seller account (dependency step) to ensure the seller exists, but then clears authentication context to simulate search from an unauthorized perspective.
 *
 * 1. Register a new seller using the public registration endpoint.
 * 2. Attempt to search business verification records for this seller (using their ID) without authentication.
 * 3. Assert that an authorization error occurs and that no sensitive data is returned in the response.
 *
 * The test ensures that only authorized actors (the seller themselves or a platform admin) can access seller KYC/business compliance submissions, in accordance with platform security and privacy requirements.
 */
export async function test_api_seller_business_verifications_search_unauthorized(connection: api.IConnection) {
  // 1. Register a new seller (with valid business and contact info)
  const signUpResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "A_securePassword123!",
      companyName: RandomGenerator.name(),
      businessNumber: (
        typia.random<number & tags.Pattern<"^[0-9]{10}$">>() as unknown as string
      ),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Simulate unauthorized search by clearing Authorization header
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: { ...connection.headers, Authorization: undefined },
  };

  // 3. Attempt to search business verification records for the registered seller, expect authorization error
  await TestValidator.error("Unauthorized search should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.search(
        unauthConnection,
        {
          sellerId: signUpResponse.sellerId,
          body: {},
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCategory";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductCategoryMap";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Verify uniqueness enforcement when updating product-category mapping.
 *
 * This test ensures that the system would enforce uniqueness constraints on product-category mappings on update,
 * but per API/DTO, only the 'primary' flag can be updated. Changing the category for an existing mapping is not possible,
 * so it is impossible to trigger a uniqueness violation on update as described in the scenario.
 *
 * Thus, the test builds all dependencies and validates that the update endpoint does not allow mutation of category_id/product_id, and that other business logic (like toggling 'primary') is accepted. Attempting to pass invalid keys for update is rejected by TypeScript at compile time, not at runtime, so the uniqueness test cannot be performed.
 *
 * Steps:
 * 1. Register admin and seller accounts for test setup authentication.
 * 2. Create two categories as admin.
 * 3. Create a product as admin (assigning seller_id returned from seller register).
 * 4. Create two product-category mappings for the product, each with a unique category.
 * 5. Attempt to update a mapping by changing its 'primary' value (the only allowed update field).
 * 6. Confirm that the update takes effect (i.e., 'primary' is changed), validating the only permitted update path.
 */
export async function test_api_product_category_map_update_duplicate_mapping_error(
  connection: api.IConnection,
) {
  // 1. Register admin account.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "admin-Password!123"
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminSignup);

  // 2. Register a seller account.
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerSignup = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "SellerPass123!",
      companyName: RandomGenerator.company(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignup);

  // 3. Create two categories as admin (requires admin connection).
  const category1 = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      created_by_admin_id: adminSignup.adminId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      display_order: 1,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate
  });
  typia.assert(category1);

  const category2 = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      created_by_admin_id: adminSignup.adminId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      display_order: 2,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate
  });
  typia.assert(category2);

  // 4. Create a product (assign to seller).
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerSignup.sellerId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 5. Create two product-category mappings (with distinct categories).
  const mapping1 = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      category_id: category1.id,
      primary: true,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate
  });
  typia.assert(mapping1);

  const mapping2 = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      category_id: category2.id,
      primary: false,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate
  });
  typia.assert(mapping2);

  // 6. Update the second mapping's 'primary' field to true (the only permitted update).
  const updatedMapping2 = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.update(connection, {
    productId: product.id,
    productCategoryMapId: mapping2.id,
    body: {
      primary: true,
    } satisfies IShoppingMallAiBackendProductCategoryMap.IUpdate
  });
  typia.assert(updatedMapping2);
  TestValidator.equals("primary field changed")(updatedMapping2.primary)(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import type { IPageIShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCoinWallet";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test advanced searching for coin wallets in admin panel.
 *
 * This test validates that the coin wallet search API supports advanced filtering (by wallet type, status, owner IDs) and that only admins can use this endpoint. It also tests pagination, ownership privacy, error responses for invalid filters, and proper authorization enforcement.
 *
 * 1. Log in as admin to get authentication token.
 * 2. Create wallets for admin, seller, and customer with different types and statuses for meaningful search conditions.
 * 3. As admin, search with filters: by wallet_type, wallet_status, or owner ID, and verify all returned wallets match the filter.
 * 4. Search with invalid filter values and confirm results are empty.
 * 5. Attempt unauthorized search (non-admin) and confirm error is thrown.
 */
export async function test_api_coin_wallet_search_with_advanced_filters(connection: api.IConnection) {
  // 1. Admin login to acquire access token
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Test1234!";
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);

  // 2. Create admin wallet
  const adminWallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_admin_id: adminAuth.adminId,
      wallet_type: "mainnet",
      wallet_status: "active",
      wallet_address: typia.random<string>(),
      wallet_label: "Admin Wallet",
      security_code: null,
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate,
  });
  typia.assert(adminWallet);

  // 2. Create seller wallet
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const sellerWallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_seller_id: sellerId,
      wallet_type: "event",
      wallet_status: "locked",
      wallet_address: typia.random<string>(),
      wallet_label: "Seller Wallet",
      security_code: null,
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate,
  });
  typia.assert(sellerWallet);

  // 2. Create customer wallet
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const customerWallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_customer_id: customerId,
      wallet_type: "reward",
      wallet_status: "active",
      wallet_address: typia.random<string>(),
      wallet_label: "Customer Wallet",
      security_code: null,
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate,
  });
  typia.assert(customerWallet);

  // 3. Search by wallet_type
  const resByType = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_type: "mainnet", limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resByType);
  TestValidator.predicate("wallet_type filter")(resByType.data.every((w) => w.wallet_type === "mainnet"));

  // 3. Search by wallet_status
  const resByStatus = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_status: "active", limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resByStatus);
  TestValidator.predicate("wallet_status filter")(resByStatus.data.every((w) => w.wallet_status === "active"));

  // 3. Search by admin owner id
  const resByAdminId = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_owner_admin_id: adminAuth.adminId, limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resByAdminId);
  TestValidator.predicate("admin owner id filter")(resByAdminId.data.every((w) => w.wallet_owner_admin_id === adminAuth.adminId));

  // 3. Search by seller owner id
  const resBySellerId = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_owner_seller_id: sellerId, limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resBySellerId);
  TestValidator.predicate("seller owner id filter")(resBySellerId.data.every((w) => w.wallet_owner_seller_id === sellerId));

  // 3. Search by customer owner id
  const resByCustomerId = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_owner_customer_id: customerId, limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resByCustomerId);
  TestValidator.predicate("customer owner id filter")(resByCustomerId.data.every((w) => w.wallet_owner_customer_id === customerId));

  // 4. Search with invalid type filter
  const resByInvalidType = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_type: "not_a_real_type", limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resByInvalidType);
  TestValidator.equals("no wallets for invalid type")(resByInvalidType.data.length)(0);

  // 4. Search with impossible admin owner id
  const resImpossibleAdmin = await api.functional.shoppingMallAiBackend.admin.coinWallets.search(connection, {
    body: { wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(), limit: 10 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
  });
  typia.assert(resImpossibleAdmin);
  TestValidator.equals("no wallets for impossible admin owner id")(resImpossibleAdmin.data.length)(0);

  // 5. Attempt unauthorized search as non-admin
  const noAuthConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthorized access prevented")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.search(noAuthConn, {
      body: { limit: 5 } satisfies IShoppingMallAiBackendCoinWallet.IRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
