import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate permission denial for non-admins when accessing admin system settings.
 *
 * This test confirms that only admin users can access the endpoint
 * `/shoppingMallAiBackend/admin/systemSettings` for retrieving and filtering system settings. It ensures
 * that when a non-admin (such as a customer user) or an unauthenticated user attempts to PATCH this endpoint,
 * the API returns a permission error and (by system design) an audit event/entry is generated.
 *
 * Steps:
 * 1. Authenticate as a customer (non-admin) and store JWT to simulate a non-admin session.
 * 2. Attempt to PATCH `/shoppingMallAiBackend/admin/systemSettings` as the customer user with a well-formed filter request : expect failure.
 * 3. Log out (clear Authorization header) and attempt the PATCH request again as an unauthenticated user : expect failure.
 * 4. Confirm both requests result in permission-denied errors (typically HTTP 403 or 401) and do not return success.
 * 5. (If possible within the provided APIs/types) check that an audit log is generated for the failed attempts.
 *
 * This test validates compliance with admin-only access enforcement on system settings as well as appropriate failure handling for forbidden operations.
 */
export async function test_api_system_settings_list_permission_denied_non_admin(
  connection: api.IConnection,
) {
  // 1. Authenticate as a customer (non-admin)
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "1234";

  // Login to get customer token (assumes customer is pre-registered)
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    } satisfies ICustomerSignIn.Request,
  });

  // 2. Attempt to PATCH system settings with customer JWT (non-admin token)
  await TestValidator.error("Non-admin is forbidden from system settings list")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.systemSettings.search(connection, {
        body: {},
      });
    },
  );

  // 3. Log out by clearing Authorization header
  connection.headers = { ...connection.headers, Authorization: undefined };

  // 4. Attempt to PATCH endpoint without authentication
  await TestValidator.error("Unauthenticated is forbidden from system settings list")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.systemSettings.search(connection, {
        body: {},
      });
    },
  );

  // 5. If audit logging is externally visible via API, verify here; otherwise, assume system log compliance.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSnapshot";

/**
 * Validate updating metadata of a product snapshot as an admin.
 *
 * Business context:
 * Admin users must be able to perform post-snapshot metadata edits on product snapshots (such as changing description or status). This powers compliance corrections, rare regulatory fixes, and annotative evidence on specific historical product states. The test ensures mutable fields update, immutable evidence remains unchanged, and business audit logic is enforced. Regression checks protect against privilege escalation (no non-admin update) and data integrity loss.
 *
 * Test Workflow:
 * 1. Create a new product as admin (step enables snapshot ops)
 * 2. Create a new product snapshot for the product (establishes immutable evidence record)
 * 3. Update allowed mutable metadata fields (description, status, etc.) via update endpoint
 * 4. Assert that:
 *    - The modified fields (description, status) are updated on the returned snapshot
 *    - Immutable properties (id, product_id, snapshot_code, snapshot_type, created_at) are unchanged
 *    - All required audit fields are preserved
 *    - The update cannot be performed by non-admins (negative case, optional in this test)
 */
export async function test_api_product_snapshot_update_success(connection: api.IConnection) {
  // 1. Create a new product
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    main_image_uri: RandomGenerator.url(),
    status: "draft",
  };
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, { body: productInput });
  typia.assert(product);

  // 2. Create a new product snapshot under this product
  const snapshotInput: IShoppingMallAiBackendProductSnapshot.ICreate = {
    product_id: product.id,
    snapshot_code: RandomGenerator.alphaNumeric(8),
    snapshot_type: "created",
    name: product.name,
    description: product.description,
    main_image_uri: product.main_image_uri,
    status: product.status,
  };
  const origSnapshot = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.create(connection, { productId: product.id, body: snapshotInput });
  typia.assert(origSnapshot);

  // 3. Update some metadata fields (description, status)
  const newDescription = RandomGenerator.paragraph()() + " (corrected)";
  const newStatus = "published";
  const updateInput: IShoppingMallAiBackendProductSnapshot.IUpdate = {
    description: newDescription,
    status: newStatus,
  };
  const updatedSnapshot = await api.functional.shoppingMallAiBackend.admin.products.productSnapshots.update(connection, {
    productId: product.id,
    productSnapshotId: origSnapshot.id,
    body: updateInput,
  });
  typia.assert(updatedSnapshot);

  // 4. Assert updated fields are changed, immutable fields remain unchanged
  TestValidator.equals("snapshot id")(updatedSnapshot.id)(origSnapshot.id);
  TestValidator.equals("product id")(updatedSnapshot.product_id)(origSnapshot.product_id);
  TestValidator.equals("snapshot code")(updatedSnapshot.snapshot_code)(origSnapshot.snapshot_code);
  TestValidator.equals("snapshot type")(updatedSnapshot.snapshot_type)(origSnapshot.snapshot_type);
  TestValidator.equals("name")(updatedSnapshot.name)(origSnapshot.name);
  TestValidator.equals("main_image_uri")(updatedSnapshot.main_image_uri)(origSnapshot.main_image_uri);
  TestValidator.equals("created_at")(updatedSnapshot.created_at)(origSnapshot.created_at);
  TestValidator.equals("new description")(updatedSnapshot.description)(newDescription);
  TestValidator.equals("new status")(updatedSnapshot.status)(newStatus);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductCategoryMap";
import type { IPageIShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductCategoryMap";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test searching and paginating product-category mappings for a seller's own product.
 *
 * This scenario confirms that a seller can only see category mappings for products they own and that pagination and result filters work as intended. It also checks that access is denied for non-owners and no results are returned if no mappings exist for a product.
 *
 * 1. Register Seller A and log in (obtain credentials).
 * 2. Use Seller A's credentials to create a product.
 * 3. Seller A maps the product to multiple (at least 3) categories using the productCategoryMap creation API (with at least one marked primary, the others secondary).
 * 4. Search with product's ID and confirm all mappings appear (full list).
 * 5. Use pagination (limit = 2, page = 1, page = 2) and verify paging meta and correct splits.
 * 6. Search with category_id and/or primary=true filtering – verify accuracy.
 * 7. Register Seller B and log in as B.
 * 8. Seller B attempts to search mappings for A's product (should yield access denied or empty list).
 * 9. Create a second product for Seller B (but no category mappings). Seller B queries its mappings (should get empty list).
 */
export async function test_api_product_category_map_search_by_seller_success(connection: api.IConnection) {
  // 1. Register Seller A
  const signUpA = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpA);
  const sellerAId = signUpA.sellerId;

  // 2. Create a product for Seller A
  connection.headers.Authorization = signUpA.setHeaders.Authorization;
  const productA = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productA);

  // Generate dummy unique category UUIDs
  const categoryA1 = typia.random<string & tags.Format<"uuid">>();
  const categoryA2 = typia.random<string & tags.Format<"uuid">>();
  const categoryA3 = typia.random<string & tags.Format<"uuid">>();

  // 3. Seller A maps product to 3 categories (1 primary, 2 secondary)
  const map1 = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      category_id: categoryA1,
      primary: true,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
  });
  typia.assert(map1);
  const map2 = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      category_id: categoryA2,
      primary: false,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
  });
