import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendChannel";
import type { IShoppingMallAiBackendSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSection";
import type { IPageIShoppingMallAiBackendSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test paginated & filtered section search for an admin-managed channel.
 *
 * This test validates the admin API to search and paginate product curation sections by channel, including all search, filtering, and pagination parameters. Asserts that only correct and visible sections are returned, boundary cases (empty/partial/full page) are handled, soft-deleted (simulated) sections are absent, and response metadata matches the seeded data.
 *
 * Business context: Admins need to retrieve channel sections for campaigns, curation widgets, or operational UIs. The API must support robust filtering, pagination, and comply with business/integrity rules, including soft-deletion semantics.
 *
 * Steps:
 * 1. Register a new admin and authenticate (adminId)
 * 2. Create a business channel under the admin (channelId)
 * 3. Create seven sections under this channel with varying codes, names, display_orders and visibility flags
 * 4. Simulate soft-deletion of one section (remove its id from expected results)
 * 5. Perform paginated and filtered searches using the API:
 *    - Unfiltered (should return all but soft-deleted, correct ordering, correct meta)
 *    - By code (exact match, partial match)
 *    - By name (exact/partial)
 *    - By display_order
 *    - By visible flag (true/false)
 *    - Paginated: page 1, 2, "too far" (empty page), page-sized (exact boundary), partial page
 * 6. For each search, validate:
 *    - Data matches expected sections for filter/pagination
 *    - Pagination info is correct (current, pages, limit, records)
 *    - Soft-deleted section is absent
 *    - All item fields (code, name, display_order, visible) are as seeded
 */
export async function test_api_channel_sections_search_and_filter_pagination_success(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Password123!@#";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAuth);

  // 2. Create channel
  const channel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      name: "E2E Test Channel",
      created_by_admin_id: adminAuth.adminId,
      description: "Channel for E2E test of section listing/search",
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channel);

  // 3. Seed 7 sections under this channel
  const baseCodes = ["best", "sale", "promo", "summer", "winter", "latest", "hidden"];
  const baseNames = ["Best Sellers", "On Sale", "Promotions", "Summer Specials", "Winter Deals", "Latest", "Hidden Section"];
  const baseVisible = [true, true, true, true, false, true, true];
  const baseDisplayOrders = [1, 2, 3, 4, 5, 10, 99];
  const seededSections: IShoppingMallAiBackendSection[] = [];
  for (let i = 0; i < 7; ++i) {
    const section = await api.functional.shoppingMallAiBackend.admin.channels.sections.createSection(connection, {
      channelId: channel.id,
      body: {
        code: baseCodes[i],
        name: baseNames[i],
        description: `Description of ${baseNames[i]}`,
        display_order: baseDisplayOrders[i],
        visible: baseVisible[i],
        channel_id: channel.id,
        created_by_admin_id: adminAuth.adminId,
      } satisfies IShoppingMallAiBackendSection.ICreate,
    });
    typia.assert(section);
    seededSections.push(section);
  }

  // 4. Simulate soft deletion by marking the 5th (index 4) section as soft-deleted (remove from expected, not real API)
  const softDeletedSection = seededSections[4]; // "winter"
  const activeSections = seededSections.filter((s) => s.id !== softDeletedSection.id);

  // Helper: sort by display_order ASC, code as tiebreaker
  const getSorted = (sections: typeof activeSections) => {
    return [...sections].sort((a, b) => a.display_order !== b.display_order
      ? a.display_order - b.display_order : a.code.localeCompare(b.code));
  };

  // Pagination helper
  const paginate = (arr: typeof activeSections, page: number, limit: number) => {
    const sorted = getSorted(arr);
    const start = (page - 1) * limit;
    const paged = sorted.slice(start, start + limit);
    return paged;
  };

  // 5a. Unfiltered: get all, limit 10 (should return all but soft-deleted)
  {
    const body = { page: 1, limit: 10 } satisfies IShoppingMallAiBackendSection.IRequest;
    const out = await api.functional.shoppingMallAiBackend.admin.channels.sections.search(connection, {
      channelId: channel.id,
      body,
    });
    typia.assert(out);
    TestValidator.equals("record count")(out.pagination.records)(activeSections.length);
    TestValidator.equals("data count")(out.data.length)(activeSections.length);
    const sorted = getSorted(activeSections);
    for (let i = 0; i < out.data.length; ++i) {
      const res = out.data[i], exp = sorted[i];
      TestValidator.equals(`code#${i}`)(res.code)(exp.code);
      TestValidator.equals(`name#${i}`)(res.name)(exp.name);
      TestValidator.equals(`order#${i}`)(res.display_order)(exp.display_order);
      TestValidator.equals(`visible#${i}`)(res.visible)(exp.visible);
    }
  }

  // 5b. By code (exact, partial)
  {
    // exact
    const code = activeSections[2].code;
    const body = { code } satisfies IShoppingMallAiBackendSection.IRequest;
    const out = await api.functional.shoppingMallAiBackend.admin.channels.sections.search(connection, {
      channelId: channel.id,
      body,
    });
    typia.assert(out);
    TestValidator.equals("single record")(out.pagination.records)(1);
    TestValidator.equals("code matches")(out.data[0]?.code)(code);
    // partial (simulate by code substring matching, e.g., 'sale' should match 'sale')
    const partial = code.slice(0, 3);
    // Note: API may need exact; partial only if supported. We'll just run it for coverage.
    const body2 = { code: partial } satisfies IShoppingMallAiBackendSection.IRequest;
    const out2 = await api.functional.shoppingMallAiBackend.admin.channels.sections.search(connection, {
      channelId: channel.id,
      body: body2,
    });
    typia.assert(out2);
  }

  // 5c. By name (full, partial)
  {
    // full
    const name = activeSections[5].name;
    const body = { name } satisfies IShoppingMallAiBackendSection.IRequest;
    const out = await api.functional.shoppingMallAiBackend.admin.channels.sections.search(connection, {
      channelId: channel.id,
      body,
    });
    typia.assert(out);
    TestValidator.equals("single record")(out.pagination.records)(1);
    TestValidator.equals("name matches")(out.data[0]?.name)(name);
    // partial
    const partial = name.split(" ")[0];
    const body2 = { name: partial } satisfies IShoppingMallAiBackendSection.IRequest;
    const out2 = await api.functional.shoppingMallAiBackend.admin.channels.sections.search(connection, {
      channelId: channel.id,
      body: body2,
    });
    typia.assert(out2);
  }

  // 5d. By display_order
  {
    // Should get the one section with a specific display_order
    const displayOrder = activeSections[1].display_order;
    const body = { display_order: displayOrder } satisfies IShoppingMallAiBackendSection.IRequest;
    const out = await api.functional.shoppingMallAiBackend.admin.channels.sections.search(connection, {
      channelId: channel.id,
      body,
    });
    typia.assert(out);
    TestValidator.equals("record count")(out.pagination.records)(1);
    TestValidator.equals("order")(out.data[0]?.display_order)(displayOrder);
  }

  // 5e. By visible (true/false)
  {
    for (const visible of [true, false]) {
      const exps = activeSections.filter((s) => s.visible === visible);
      const body = { visible } satisfies IShoppingMallAiBackendSection.IRequest;
      const out = await api.functional.shoppingMallAiBackend.admin.channels.sections.search(connection, {
        channelId: channel.id,
        body,
      });
      typia.assert(out);
      TestValidator.equals("visible record count")(out.pagination.records)(exps.length);
      for (const item of out.data) {
        TestValidator.equals(`visible")(item.visible)(visible);
      }
    }
  }

  // 5f. Pagination: 3/page, test page 1 (full), 2 (partial), 3 (empty)
  {
    const limit = 3;
    for (let page = 1; page <= 3; ++page) {
      const body = { page, limit } satisfies IShoppingMallAiBackendSection.IRequest;
      const out = await api.functional.shoppingMallAiBackend.admin.channels.sections.search(connection, {
        channelId: channel.id,
        body,
      });
      typia.assert(out);
      const paged = paginate(activeSections, page, limit);
      TestValidator.equals(`page ${page} count")(out.data.length)(paged.length);
    }
  }

  // 6. Confirm soft-deleted section is never shown
  {
    const body = { } satisfies IShoppingMallAiBackendSection.IRequest;
    const out = await api.functional.shoppingMallAiBackend.admin.channels.sections.search(connection, {
      channelId: channel.id,
      body,
    });
    typia.assert(out);
    for (const item of out.data) {
      if (item.id === softDeletedSection.id)
        throw new Error("Soft-deleted section returned in listing");
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendBusinessRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendBusinessRule";
import type { IPageIShoppingMallAiBackendBusinessRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendBusinessRule";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for searching and paginating business rules as an admin.
 *
 * This test validates the admin search endpoint for business rules, covering filtering, pagination, permissions,
 * and error handling.
 *
 * Steps:
 * 1. Create at least two distinct business rules using the admin create endpoint. Each uses different values for code, description, and status.
 * 2. Search by rule_code to confirm only the matching rule is returned.
 * 3. Search by partial rule_description keyword to check that relevant rules are returned.
 * 4. Search by enforcement_status to confirm only matching statuses appear.
 * 5. Paginate with page_size=1 to confirm pagination works and total record count is accurate.
 * 6. Try search filters that yield zero results (nonexistent code).
 * 7. Pass malformed filters (e.g., bad date strings) to validate error handling (if supported by implementation).
 * 8. Attempt search as a non-admin (simulate with stripped headers or a fresh connection) to confirm permission error is thrown.
 */
export async function test_api_business_rules_search_and_filter(connection: api.IConnection) {
  // 1. Create two distinct business rules as admin
  const now = new Date().toISOString();
  const rule1 = await api.functional.shoppingMallAiBackend.admin.businessRules.create(connection, {
    body: {
      rule_code: `RULE_${RandomGenerator.alphabets(6)}`,
      rule_description: `Compliance requirement A - ${RandomGenerator.content()()()}`,
      enforcement_status: "active",
      reason_for_change: null,
      effective_from: now,
      effective_to: null
    } satisfies IShoppingMallAiBackendBusinessRule.ICreate
  });
  typia.assert(rule1);

  const rule2 = await api.functional.shoppingMallAiBackend.admin.businessRules.create(connection, {
    body: {
      rule_code: `RULE_${RandomGenerator.alphabets(6)}`,
      rule_description: `Technical sunset; keyword: SpecialX - ${RandomGenerator.content()()()}`,
      enforcement_status: "retired",
      reason_for_change: "Sunset per annual audit",
      effective_from: now,
      effective_to: null
    } satisfies IShoppingMallAiBackendBusinessRule.ICreate
  });
  typia.assert(rule2);

  // 2. Search by rule_code (should only match rule1)
  const searchByCode = await api.functional.shoppingMallAiBackend.admin.businessRules.search(connection, {
    body: {
      rule_code: rule1.rule_code
    } satisfies IShoppingMallAiBackendBusinessRule.IRequest
  });
  typia.assert(searchByCode);
  TestValidator.equals("rule_code search count")(searchByCode.data.length)(1);
  TestValidator.equals("rule_code match")(searchByCode.data[0].id)(rule1.id);

  // 3. Search by description keyword (should match rule2 because of "SpecialX")
  const searchByDesc = await api.functional.shoppingMallAiBackend.admin.businessRules.search(connection, {
    body: {
      rule_description: "SpecialX"
    } satisfies IShoppingMallAiBackendBusinessRule.IRequest
  });
  typia.assert(searchByDesc);
  TestValidator.predicate("description keyword search finds rule2")(
    searchByDesc.data.some(r => r.id === rule2.id)
  );

  // 4. Search by enforcement_status (should match only rule1 for "active")
  const searchByStatus = await api.functional.shoppingMallAiBackend.admin.businessRules.search(connection, {
    body: {
      enforcement_status: "active"
    } satisfies IShoppingMallAiBackendBusinessRule.IRequest
  });
  typia.assert(searchByStatus);
  TestValidator.predicate("status filter includes rule1 only")(
    searchByStatus.data.some(r => r.id === rule1.id)
  );
  TestValidator.predicate("status filter excludes retired")(
    searchByStatus.data.every(r => r.enforcement_status === "active")
  );

  // 5. Paginate with page_size=1
  const pageSearch = await api.functional.shoppingMallAiBackend.admin.businessRules.search(connection, {
    body: {
      page: 1,
      page_size: 1
    } satisfies IShoppingMallAiBackendBusinessRule.IRequest
  });
  typia.assert(pageSearch);
  TestValidator.equals("page_size=1")(pageSearch.data.length)(1);
  TestValidator.predicate("pagination records >= 2")(pageSearch.pagination.records >= 2);

  // 6. Filter yields empty set
  const empty = await api.functional.shoppingMallAiBackend.admin.businessRules.search(connection, {
    body: {
      rule_code: "NOT_FOUND_CODE_123"
    } satisfies IShoppingMallAiBackendBusinessRule.IRequest
  });
  typia.assert(empty);
  TestValidator.equals("empty results")(empty.data.length)(0);

  // 7. Malformed filter: bad effective_from date
  await TestValidator.error("malformed date param should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.businessRules.search(connection, {
      body: {
        effective_from: "bad-date" as any
      } satisfies IShoppingMallAiBackendBusinessRule.IRequest
    });
  });

  // 8. Attempt search as non-admin (simulate by stripping headers)
  const unauthConnection = { ...connection, headers: {} };
  await TestValidator.error("non-admin permission denied")(async () => {
    await api.functional.shoppingMallAiBackend.admin.businessRules.search(unauthConnection, {
      body: {} as IShoppingMallAiBackendBusinessRule.IRequest
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Ensure that sellers cannot retrieve details of orders irrelevant to their own products.
 *
 * Business context: In a multi-seller marketplace, data privacy and business separation require that sellers may only view orders containing their own products. This test validates that access controls are enforced at the API level.
 *
 * Process:
 * 1. Register Seller A and Seller B with unique business data.
 * 2. Seller A logs in and creates a product.
 * 3. Register and log in as a customer.
 * 4. Customer creates an order for Seller A's product.
 * 5. Seller B logs in and attempts to access the order detail; this access should be forbidden.
 *
 * This scenario demonstrates that a seller cannot retrieve details of an order that is not associated with their products, enforcing business-level data privacy.
 */
export async function test_api_seller_order_detail_forbidden_not_owner(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAPassword = "passwordA123!";
  const sellerAReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
      companyName: RandomGenerator.company(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerAReg);

  // 2. Register Seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBPassword = "passwordB123!";
  const sellerBReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: sellerBPassword,
      companyName: RandomGenerator.company(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerBReg);

  // 3. Seller A logs in
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
    },
  });

  // 4. Seller A creates a product
  const productA = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAReg.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: "Seller A Product",
      description: RandomGenerator.paragraph()(),
      status: "published",
    },
  });
  typia.assert(productA);

  // 5. Register and log in as customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "custPass123!";
  const customerReg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerReg);
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    },
  });

  // 6. Customer creates an order for Seller A's product (minimal info due to schema limits)
  const orderNumber = RandomGenerator.alphaNumeric(12);
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerReg.customer.id,
      order_number: orderNumber,
      total_amount: 10000,
      currency_code: "KRW",
      current_status: "created",
    },
  });
  typia.assert(order);

  // 7. Seller B logs in
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerBEmail,
      password: sellerBPassword,
    },
  });

  // 8. Seller B tries to access Seller A's order and should receive forbidden error
