import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validate that a customer can successfully update (change status) of their order before the order has been fulfilled.
 *
 * Business context:
 * This test ensures that customers are able to update their own orders, specifically by changing the status (such as marking an order as cancelled) prior to fulfillment or shipment. This aligns with e-commerce best practices for customer order flexibility and supports self-service order management.
 *
 * Workflow Steps:
 * 1. Register a new customer account with required fields using /auth/customer/register.
 * 2. Login as this customer to gain authentication and session token using /auth/customer/login.
 * 3. Create a new order for this customer using /shoppingMallAiBackend/customer/orders (supplying customer_id, order_number, total_amount, currency, and initial status such as 'created').
 * 4. Use the order's id to call /shoppingMallAiBackend/customer/orders/{orderId} (PUT) to update the current_status property (e.g., change from 'created' to 'cancelled') and optionally update the note field.
 * 5. Validate that the update was successful by confirming the response has the new status and note, and that audit fields (updated_at) reflects the change (is newer than created_at).
 * 6. Check negative scenario: try updating the order when not authenticated (expect error or rejection).
 */
export async function test_api_customer_order_update_status_change(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "p@ssW0rd--1";
  const registerResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(registerResponse);
  const customer = registerResponse.customer;

  // 2. Login to set authentication (explicit session)
  const loginResponse = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies ICustomerSignIn.Request,
  });
  typia.assert(loginResponse);
  // After login, connection.headers.Authorization is set for the session

  // 3. Create a new order for this customer
  const initialStatus = "created";
  const orderNumber = RandomGenerator.alphaNumeric(12);
  const totalAmount = 10000;
  const currency = "KRW";
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customer.id,
      order_number: orderNumber,
      total_amount: totalAmount,
      currency_code: currency,
      current_status: initialStatus,
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(order);
  TestValidator.equals("order owner")(order.customer_id)(customer.id);
  TestValidator.equals("initial status")(order.current_status)(initialStatus);

  // 4. Update the order status to 'cancelled' with a customer note
  const newStatus = "cancelled";
  const note = "Customer requested cancellation before fulfillment.";
  const updateResponse = await api.functional.shoppingMallAiBackend.customer.orders.update(connection, {
    orderId: order.id,
    body: {
      current_status: newStatus,
      note,
    } satisfies IShoppingMallAiBackendOrder.IUpdate,
  });
  typia.assert(updateResponse);
  TestValidator.equals("order id after update")(updateResponse.id)(order.id);
  TestValidator.equals("updated status")(updateResponse.current_status)(newStatus);
  TestValidator.equals("updated note")(updateResponse.note)(note);
  TestValidator.predicate("updated_at newer than created_at")(
    new Date(updateResponse.updated_at).getTime() > new Date(order.created_at).getTime()
  );

  // 5. Negative scenario: try updating order unauthenticated (expect failure)
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  unauthConnection.headers.Authorization = undefined;
  await TestValidator.error("fail to update without auth")(async () =>
    api.functional.shoppingMallAiBackend.customer.orders.update(unauthConnection, {
      orderId: order.id,
      body: { current_status: "cancelled_by_guest" },
    })
  );
}

