/**
 * Validate successful seller password change operation.
 *
 * This test covers the business logic and security workflow of seller password change:
 * - Register a new seller account with unique credentials
 * - Authenticate (login) with those credentials to obtain JWT/session
 * - Use the authenticated session to perform a password change, supplying the correct current password and a policy-compliant strong new password
 * - Validate the response indicates password change succeeded
 * - (DB side: password_hash must update, seller_histories should log event, and session is reset, but these cannot be verified via the API directly.)
 * - Confirm that a login with the new password is accepted and issues a new JWT (i.e., session reset works)
 * - Confirm that a login with the old password is now rejected (if login API returns error on credentials failure)
 *
 * Steps:
 * 1. Register seller (capture credentials)
 * 2. Login as seller (obtain token)
 * 3. Change password using correct current password and valid new password
 * 4. Login again with new password (should succeed)
 * 5. Attempt login with old password (should fail)
 */
export async function test_api_seller_change_password_success(connection: api.IConnection) {
  // 1. Register a new seller account
  const sellerEmail = typia.random<string & tags.Format<'email'>>();
  const initialPassword = 'Initial@12345';
  const newPassword = 'NewPass!2345';
  const companyName = RandomGenerator.company();
  const businessNumber = (
    String(1000000000 + Math.floor(Math.random() * 9000000000))
  );

  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: initialPassword,
      companyName,
      businessNumber,
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(20),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResp);
  TestValidator.equals('seller email matches')(signUpResp.email)(sellerEmail);
  TestValidator.equals('company name matches')(signUpResp.companyName)(companyName);

  // 2. Login as seller with the initial password
  const signInResp = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: initialPassword
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(signInResp);
  TestValidator.equals('auth company name')(signInResp.companyName)(companyName);
  const sellerId = signInResp.sellerId;

  // 3. Authenticated: Change password using correct current password and strong new password
  const passwordChangeResp = await api.functional.auth.seller.password.changePassword(connection, {
    body: {
      currentPassword: initialPassword,
      newPassword: newPassword
    } satisfies ISellerAuth.ChangePassword,
  });
  typia.assert(passwordChangeResp);
  TestValidator.equals('password change success')(passwordChangeResp.success)(true);

  // 4. Login with new password: should succeed, session reset must work
  const newLoginResp = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: newPassword
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(newLoginResp);
  TestValidator.equals('new login sellerId')(newLoginResp.sellerId)(sellerId);
  TestValidator.equals('company name after password change')(newLoginResp.companyName)(companyName);

  // 5. Login with old password: should fail
  await TestValidator.error('old password should fail login')(async () => {
    await api.functional.auth.seller.login.signIn(connection, {
      body: {
        email: sellerEmail,
        password: initialPassword,
      } satisfies ISellerAuth.SignIn,
    });
  });
}

