import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartItem";
import type { IPageIShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCartItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validates that a customer can retrieve, filter, and paginate their own cart items.
 *
 * This test ensures:
 * - A customer can only see their cart items
 * - Filtering by product_id and product_option_id works correctly
 * - Pagination returns the right number of items and no duplications across pages
 * - All returned items genuinely belong to the cart
 *
 * Step-by-step:
 * 1. Register and authenticate a new customer
 * 2. Create a cart for the customer
 * 3. Add four items (different products/options) to the cart
 * 4. Search all (unfiltered), by product_id, by product_option_id, and with pagination
 * 5. Validate filter/pagination/ownership logic with assertions
 */
export async function test_api_cart_cartitem_search_by_owner(connection: api.IConnection) {
  // 1. Register a new customer account
  const signUpReq: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword!123",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const signUpResp = await api.functional.auth.customer.register.signUp(connection, { body: signUpReq });
  typia.assert(signUpResp);
  TestValidator.equals("sign up email")(signUpResp.customer.email)(signUpReq.email);

  // 2. Authenticate as the customer
  const loginResp = await api.functional.auth.customer.login.signIn(connection, {
    body: { email: signUpReq.email, password: signUpReq.password },
  });
  typia.assert(loginResp);
  TestValidator.equals("login email matches")(loginResp.customer.email)(signUpReq.email);

  // 3. Create a new cart for the customer
  const cartReq: IShoppingMallAiBackendCart.ICreate = {
    status: "active",
    session_token: null,
  };
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, { body: cartReq });
  typia.assert(cart);

  // 4. Add 4 items: 2 with product[0] (with and without options), 1 with product[1], 1 with product[0] option[1]
  const productIds = [typia.random<string & tags.Format<"uuid">>(), typia.random<string & tags.Format<"uuid">>()];
  const optionIds = [typia.random<string & tags.Format<"uuid">>(), typia.random<string & tags.Format<"uuid">>()];
  const basePrice = 9900;
  const currency = "KRW";
  const items = [
    // item0: product0, no option
    await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
      cartId: cart.id,
      body: {
        product_id: productIds[0], product_option_id: null, quantity: 2, unit_price: basePrice, currency_code: currency, note: "p0/noopt"
      },
    }),
    // item1: product0, option0
    await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
      cartId: cart.id,
      body: {
        product_id: productIds[0], product_option_id: optionIds[0], quantity: 1, unit_price: basePrice + 1000, currency_code: currency, note: "p0/opt0"
      },
    }),
    // item2: product0, option1
    await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
      cartId: cart.id,
      body: {
        product_id: productIds[0], product_option_id: optionIds[1], quantity: 3, unit_price: basePrice + 2000, currency_code: currency, note: "p0/opt1"
      },
    }),
    // item3: product1, no option
    await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
      cartId: cart.id,
      body: {
        product_id: productIds[1], product_option_id: null, quantity: 1, unit_price: basePrice, currency_code: currency, note: "p1/noopt"
      },
    }),
  ];
  items.forEach(typia.assert);

  // 5a. Unfiltered search: should return all four
  const allSearch = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.search(connection, {
    cartId: cart.id, body: {} });
  typia.assert(allSearch);
  TestValidator.equals("all items returned")(allSearch.data.length)(4);
  const expectedIds = items.map(i=>i.id).sort();
  TestValidator.equals("all item ids present")(allSearch.data.map(i=>i.id).sort())(expectedIds);
  allSearch.data.forEach(result => {
    TestValidator.equals("cart id match")(result)(expect.objectContaining({cart_id: cart.id}));
    TestValidator.predicate("item id is known")(expectedIds.includes(result.id));
  });

  // 5b. Filter by product_id[0]; returns item0/1/2
  const filterProduct = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.search(connection, {
    cartId: cart.id, body: { product_id: productIds[0] }, });
  typia.assert(filterProduct);
  TestValidator.equals("product0 filter count")(filterProduct.data.length)(3);
  filterProduct.data.forEach(item => TestValidator.equals("correct product")(item.product_id)(productIds[0]));

  // 5c. Filter by option_id[1]; returns only item2
  const filterOption = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.search(connection, {
    cartId: cart.id, body: { product_option_id: optionIds[1] }, });
  typia.assert(filterOption);
  TestValidator.equals("option1 filter count")(filterOption.data.length)(1);
  TestValidator.equals("option1 id match")(filterOption.data[0].id)(items[2].id);

  // 5d. Pagination: limit 2
  const paged1 = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.search(connection, {
    cartId: cart.id, body: { limit: 2, page: 1, sort_field: "created_at", sort_dir: "asc" }, });
  const paged2 = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.search(connection, {
    cartId: cart.id, body: { limit: 2, page: 2, sort_field: "created_at", sort_dir: "asc" }, });
  typia.assert(paged1);
  typia.assert(paged2);
  TestValidator.equals("page1 count")(paged1.data.length)(2);
  TestValidator.equals("page2 count")(paged2.data.length)(2);
  // Pages should be disjoint
  const pagedIds = [...paged1.data.map(i=>i.id), ...paged2.data.map(i=>i.id)].sort();
  TestValidator.equals("paged all ids")(pagedIds)(expectedIds);
}

