  // 3a. Search by partial name
  const nameRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { name: "Part", page: 1, limit: 10 },
  });
  typia.assert(nameRes);
  for (const s of nameRes.data) TestValidator.predicate("name contains 'Part'")(s.name.includes("Part"));

  // 3b. Filter by code (exact)
  const codeRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { code: "PARTNER002" },
  });
  typia.assert(codeRes);
  TestValidator.equals("one PARTNER002 result")(codeRes.data.length)(1);
  TestValidator.equals("code matches")(codeRes.data[0].code)("PARTNER002");

  // 3c. Filter by activation status (inactive)
  const inactiveRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { active: false },
  });
  typia.assert(inactiveRes);
  for (const s of inactiveRes.data) TestValidator.equals("inactive only")(s.active)(false);

  // 3d. Filter by creator (adminId)
  const creatorRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { created_by_admin_id: adminJwt.adminId },
  });
  typia.assert(creatorRes);
  for (const s of creatorRes.data) TestValidator.equals("created_by_admin_id matches")(s.created_by_admin_id)(adminJwt.adminId);

  // 3e. Combine filters (active + name partial)
  const combineRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { active: true, name: "Vert" },
  });
  typia.assert(combineRes);
  for (const s of combineRes.data) {
    TestValidator.equals("active & Vert")(s.active)(true);
    TestValidator.predicate("name contains 'Vert'")(s.name.includes("Vert"));
  }

  // 3f. Pagination (limit=2)
  const pagedRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { limit: 2, page: 1 },
  });
  typia.assert(pagedRes);
  TestValidator.predicate("limit respected")(pagedRes.data.length <= 2);
  TestValidator.predicate("pagination object")(typeof pagedRes.pagination.current === "number");

  // 4. Soft delete exclusion cannot be tested without a delete API
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendChannel";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate error handling for admin channel creation with invalid/missing fields or violated business rules.
 *
 * Tests that submitting a channel creation request with: (1) missing required fields, (2) a business-unique code that already exists, and (3) invalid data type, results in validation or business logic error response. No channel must be created for incorrect input, and appropriate error is surfaced as per compliance and schema requirements.
 *
 * Steps:
 * 1. Log in as an admin using test credentials, keep their adminId for valid requests.
 * 2. Attempt to create a channel with missing required field 'name'.
 * 3. Attempt to create a channel with empty 'name'.
 * 4. Create a channel with a valid unique 'code', then attempt to create another with the same 'code'.
 * 5. Attempt to create a channel with invalid data type (e.g., non-boolean for 'active').
 * 6. Verify each call returns an error and no channel is created for invalid input.
 * 7. Confirm the original channel is present (where applicable) and no partial/incomplete entries were created for failures.
 */
export async function test_api_channel_creation_invalid_fields_error(connection: api.IConnection) {
  // 1. Log in as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234abcd";
  // (Assume a valid admin is pre-created for login test, otherwise would require sign up API)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // Prepare a base valid channel DTO
  const validChannelInput = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(2),
    created_by_admin_id: adminLogin.adminId,
    active: true,
    description: null,
    logo_url: null,
  } satisfies IShoppingMallAiBackendChannel.ICreate;

  // 2. Missing required field: name — should fail
  await TestValidator.error("missing name should fail")(async () => {
    const input = { ...validChannelInput };
    // @ts-expect-error
    delete input.name;
    await api.functional.shoppingMallAiBackend.admin.channels.create(connection, { body: input as any });
  });

  // 3. Empty name field — should fail
  await TestValidator.error("empty name should fail")(async () => {
    const input = { ...validChannelInput, name: "" };
    await api.functional.shoppingMallAiBackend.admin.channels.create(connection, { body: input });
  });

  // 4. Create valid channel, then test duplicate code
  const createdChannel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: validChannelInput,
  });
  typia.assert(createdChannel);

  // Try creating another channel with the same code (should fail for uniqueness)
  await TestValidator.error("duplicate code should fail")(async () => {
    const input = { ...validChannelInput, name: RandomGenerator.paragraph()(2) };
    await api.functional.shoppingMallAiBackend.admin.channels.create(connection, { body: input });
  });

  // 5. Invalid data type: active is a number instead of boolean — should fail
  await TestValidator.error("non-boolean active should fail")(async () => {
    // @ts-expect-error
    const input = { ...validChannelInput, code: RandomGenerator.alphaNumeric(8), active: 123 };
    await api.functional.shoppingMallAiBackend.admin.channels.create(connection, { body: input as any });
  });

  // 6. All invalid requests must yield errors; only the original valid channel exists if listing was available.
}

