 * 3. Customer A favorites two of those products
 * 4. Retrieve favorites list with pagination, limiting to 1 per page; validate page boundaries and correctness
 * 5. Test product_id and date range filters to validate filtering
 * 6. Register and login as Customer B; confirm empty favorites for isolation
 * 7. Switch back and forth between customers; verify segregation of favorites
 * 8. Attempt list access without login; confirm proper denial (error thrown)
 *
 * All API responses are strictly type-asserted; random UUIDs and business data are used where required. The test checks data, pagination, and security correctness for both happy-path and security edge cases.
 */
export async function test_api_favorite_products_pagination_filtering_security(connection: api.IConnection) {
  // 1. Customer A registration (auto-authenticated, JWT in headers)
  const customerA_email: string = typia.random<string & tags.Format<"email">>();
  const customerA_password: string = RandomGenerator.alphaNumeric(10);
  const customerA_nickname: string = RandomGenerator.alphaNumeric(8);
  const customerA_phone: string = RandomGenerator.mobile();
  const customerA_register = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerA_email,
      password: customerA_password,
      name: RandomGenerator.name(),
      nickname: customerA_nickname,
      phone: customerA_phone
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerA_register);
  const customerA = customerA_register.customer;

  // 2. Admin creates 3 products assigned to synthetic (random) sellers
  const syntheticSellerIds = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const createdProducts = await ArrayUtil.asyncMap(syntheticSellerIds)(async (sellerId, idx) =>
    await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
      body: {
        seller_id: sellerId,
        code: RandomGenerator.alphaNumeric(12) + idx,
        name: RandomGenerator.paragraph()(1),
        description: RandomGenerator.content()()(1),
        main_image_uri: null,
        status: "published"
      } satisfies IShoppingMallAiBackendProduct.ICreate
    })
  );
  typia.assert(createdProducts);

  // 3. Customer A favorites first and last product
  for (const productIdx of [0, 2]) {
    const favoriteOut = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
      body: {
        product_id: createdProducts[productIdx].id
      } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate
    });
    typia.assert(favoriteOut);
  }

  // 4. Retrieve favorites paginated (page=1, limit=1), expect only 1 on first page, correct pagination metadata
  let favoritesPage1 = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: {
      page: 1,
      limit: 1
    }
  });
  typia.assert(favoritesPage1);
  TestValidator.equals("favorites pagination page 1")(favoritesPage1.pagination.current)(1);
  TestValidator.equals("limit")(favoritesPage1.pagination.limit)(1);
  TestValidator.predicate("should have at least 1 favorite")(favoritesPage1.data.length >= 1);

  // Validate product_id of favorite matches first or last product
  TestValidator.predicate("product id matches favorited item")(
    createdProducts
      .map(p => p.id)
      .includes(favoritesPage1.data[0].product_id)
  );

  // 5. Retrieve page 2, verify record count
  let favoritesPage2 = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: {
      page: 2,
      limit: 1
    }
  });
  typia.assert(favoritesPage2);
  TestValidator.equals("favorites pagination page 2")(favoritesPage2.pagination.current)(2);
  TestValidator.equals("limit")(favoritesPage2.pagination.limit)(1);
  TestValidator.predicate("should have at least 1 favorite")(favoritesPage2.data.length >= 1);

  TestValidator.equals("pagination record count")(favoritesPage1.pagination.records + favoritesPage2.pagination.records)(favoritesPage2.pagination.records * 2);

  // 6. Filter by specific product_id
  for (const selected of [0, 2]) {
    let filtered = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
      body: {
        product_id: createdProducts[selected].id
      }
    });
    typia.assert(filtered);
    TestValidator.predicate("filtered data has correct product")(
      filtered.data.every(fav => fav.product_id === createdProducts[selected].id)
    );
  }

  // 7. Filter by favorited date (from_date = now -10m, to_date = now)
  const fromDate = new Date(Date.now() - 10 * 60 * 1000).toISOString();
  const toDate = new Date().toISOString();
  const filteredByDate = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: {
      from_date: fromDate,
      to_date: toDate
    }
  });
  typia.assert(filteredByDate);
  TestValidator.predicate("all favorites within date range")(
    filteredByDate.data.every(fav => fav.created_at >= fromDate && fav.created_at <= toDate)
  );

  // 8. Register and authenticate Customer B
  const customerB_email: string = typia.random<string & tags.Format<"email">>();
  const customerB_password: string = RandomGenerator.alphaNumeric(10);
  const customerB_nickname: string = RandomGenerator.alphaNumeric(8);
  const customerB_phone: string = RandomGenerator.mobile();
  const customerB_register = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerB_email,
      password: customerB_password,
      name: RandomGenerator.name(),
      nickname: customerB_nickname,
      phone: customerB_phone
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerB_register);

  // 9. Authenticate as Customer B
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerB_email,
      password: customerB_password
    } satisfies ICustomerSignIn.Request
  });

  // 10. Customer B - retrieve favorites (should be empty)
  const customerB_favorites = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: {}
  });
  typia.assert(customerB_favorites);
  TestValidator.equals("customer B has no favorites")(customerB_favorites.data.length)(0);

  // 11. Switch back to Customer A via login
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerA_email,
      password: customerA_password
    } satisfies ICustomerSignIn.Request
  });

  // 12. Retrieve A's favorites - ensure visible again
  const revisitA_favorites = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: {}
  });
  typia.assert(revisitA_favorites);
  TestValidator.predicate("customer A sees their favorites again")(revisitA_favorites.data.length >= 2);

  // 13. Clear Authorization and verify request fails (security - unauthorized)
  const unauthConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthorized fails")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(unauthConn, {
      body: {}
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendErrorLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendErrorLog";
import type { IPageIShoppingMallAiBackendErrorLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendErrorLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for searching error logs with filter conditions and pagination in the admin backend.
 *
 * This test ensures that admins can retrieve error logs filtered by various criteria such as error code,
 * severity, root cause entity, time window, and pagination. Edge cases are checked for invalid parameters,
 * insufficient privileges, and empty sets.
 *
 * Steps:
 * 1. Authenticate as admin and obtain a JWT token for privileged access.
 * 2. Perform a PATCH search on error logs with representative filters (error code, severity, entity, timestamps, pagination).
 * 3. Validate that the data, pagination fields, and filters are respected in results.
 * 4. Perform a search with impossible filters and confirm an empty result set is returned.
 * 5. Attempt search with invalid parameters (e.g., negative limit) and expect an error.
 * 6. Attempt search without authentication and verify that authorization error is thrown.
 */
export async function test_api_error_log_search_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Admin login to obtain authentication for the subsequent error log search
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminTestPassword123!";
  // (Assume admin account pre-exists due to lack of admin signup endpoint)
  const loginOutput = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(loginOutput);
  // Set Authorization header for admin
  connection.headers = {
    ...connection.headers,
    Authorization: loginOutput.setHeaders.Authorization,
  };

  // 2. Search error logs with representative filter criteria
  const now = new Date();
  const fromDate = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 30).toISOString(); // 30 days ago
  const toDate = now.toISOString();
  const filterRequest: IShoppingMallAiBackendErrorLog.IRequest = {
    error_code: "API_ERR_001",
    severity_level: "error",
    root_cause_entity_type: "order",
    occurred_at_from: fromDate,
    occurred_at_to: toDate,
    sort_by: "occurred_at",
    order: "desc",
    page: 0,
    limit: 10,
  };
  const result = await api.functional.shoppingMallAiBackend.admin.errorLogs.search(connection, {
    body: filterRequest,
  });
  typia.assert(result);
  // 3. Validate the returned results
  TestValidator.predicate("pagination matches page/limit")(
    result.pagination.limit === 10,
  );
  TestValidator.equals("page number is 1-based")(result.pagination.current)(1); // 1-based per contract
  TestValidator.predicate("summary rows match error_code & severity")(
    result.data.every(
      (item) => item.error_code === filterRequest.error_code && item.severity_level === filterRequest.severity_level,
    ),
  );

  // 4. Edge case: filter returns no results
  const emptyFilter = { ...filterRequest, error_code: "NON_EXISTENT_CODE" };
  const emptyResult = await api.functional.shoppingMallAiBackend.admin.errorLogs.search(connection, {
    body: emptyFilter,
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty data")(emptyResult.data.length)(0);

  // 5. Edge case: search with invalid parameter (negative limit)
  const invalidFilter = { ...filterRequest, limit: -10 };
  await TestValidator.error("invalid limit")(async () => {
    await api.functional.shoppingMallAiBackend.admin.errorLogs.search(connection, {
      body: invalidFilter,
    });
  });

  // 6. Edge case: missing privileges (no admin Authorization header)
  const connNoAuth = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("authorization required")(async () => {
    await api.functional.shoppingMallAiBackend.admin.errorLogs.search(connNoAuth, {
      body: filterRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IPageIShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductInquiry";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test advanced product inquiry search for a customer.
 *
 * This test ensures an authenticated customer can retrieve only their own product inquiries using advanced search, full-text, and pagination filters. It covers:
 * - Ownership enforcement: only own inquiries are visible, even with direct filters.
 * - Advanced filters: product_id, status, public/private, date range.
 * - Full-text keyword search in inquiry title/body.
 * - Pagination and summary data are validated.
 * - Attempts to use unauthorized filters (such as another user's customer_id) or invalid filters are prevented or constrained.
 *
 * Steps:
 * 1. Register a customer and auto-authenticate.
 * 2. Create several product inquiries for two products (mixing public/private, titles containing test keywords, different creation dates).
 * 3. Register a second customer and create their inquiry.
 * 4. Search for own inquiries and check that only the authenticated customer's data appears.
 * 5. Apply a filter by product_id and verify only those inquiries are returned.
 * 6. Do a keyword search on title/body and check correct matching.
 * 7. Filter by status (acquired from a created inquiry for realism).
 * 8. Filter by creation date range.
 * 9. Apply pagination and check pagination info and counts.
 * 10. Attempt to filter/search as another customer—confirm only own data is accessible.
 * 11. Try using an invalid filter (e.g., status with nonsense value) and ensure error or no results.
 */
export async function test_api_product_inquiry_advanced_filter_search_customer(
  connection: api.IConnection,
) {
  // 1. Register a customer (auto-authentication, JWT header set)
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerPassword = "TestPw@32145";
  const signUpRes = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: customerEmail,
        password: customerPassword,
        name: RandomGenerator.name(),
        nickname: RandomGenerator.alphaNumeric(8),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );
  typia.assert(signUpRes);
  const customerId = signUpRes.customer.id;

  // 2. Create inquiries under this customer
  const productIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const inquiries: IShoppingMallAiBackendProductInquiry[] = [];
  for (const idx of [0, 1, 2, 3, 4]) {
    const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(
      connection,
      {
        body: {
          customer_id: customerId,
          product_id: productIds[idx % 2],
          title: idx === 2 ? "Alpha keyword inquiry" : `Standard Query #${idx}`,
          body: idx === 3 ? "Body mentioning Alpha string." : RandomGenerator.paragraph()(),
          public: idx % 2 === 1,
        } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
      },
    );
    typia.assert(inquiry);
    inquiries.push(inquiry);
  }

  // 3. Register a second customer and create their inquiry
  const otherEmail: string = typia.random<string & tags.Format<"email">>();
  const otherPassword = "TestOther@12345";
  const secondSignUp = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: otherEmail,
        password: otherPassword,
        name: RandomGenerator.name(),
        nickname: RandomGenerator.alphaNumeric(8),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );
  typia.assert(secondSignUp);
  const otherCustomerId = secondSignUp.customer.id;

  const otherInquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(
    connection,
    {
      body: {
        customer_id: otherCustomerId,
        product_id: productIds[0],
        title: "Someone else's inquiry",
        body: "Non-related content.",
        public: true,
      } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
    },
  );
  typia.assert(otherInquiry);

  // Switch back to original customer by registering anew (token will be replaced)
  await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: customerEmail,
        password: customerPassword,
        name: RandomGenerator.name(),
        nickname: RandomGenerator.alphaNumeric(8),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );

  // 4. Search for own inquiries (filter = none)
  const allOwn = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: {},
    },
  );
  typia.assert(allOwn);
  for (const i of allOwn.data)
    TestValidator.equals("customer id is self")(i.customer_id)(customerId);

  // 5. Filter by product_id
  const prodIdx = productIds[1];
  const byProduct = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: { product_id: prodIdx },
    },
  );
  typia.assert(byProduct);
  for (const i of byProduct.data) {
    TestValidator.equals("ownership")(i.customer_id)(customerId);
    TestValidator.equals("product id")(i.product_id)(prodIdx);
  }

  // 6. Full-text search (title/body contains "Alpha")
  const alphaSearch = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: { search: "Alpha" },
    },
  );
  typia.assert(alphaSearch);
  for (const i of alphaSearch.data) {
    TestValidator.equals("ownership")(i.customer_id)(customerId);
    TestValidator.predicate("contains Alpha in title or body")(
      i.title.includes("Alpha") || (i.body && i.body.includes("Alpha")),
    );
  }

  // 7. Filter by status
  const testStatus = inquiries[0].status;
  const byStatus = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: { status: testStatus },
    },
  );
  typia.assert(byStatus);
  for (const i of byStatus.data) {
    TestValidator.equals("ownership")(i.customer_id)(customerId);
    TestValidator.equals("status")(i.status)(testStatus);
  }

  // 8. Date range filter
  const rangeFrom = inquiries[0].created_at;
  const rangeTo = inquiries[inquiries.length - 1].created_at;
  const byRange = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: { created_from: rangeFrom, created_to: rangeTo },
    },
  );
  typia.assert(byRange);
  for (const i of byRange.data) {
    TestValidator.equals("ownership")(i.customer_id)(customerId);
  }

  // 9. Pagination check
  const paged = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: {
        page: 1,
        page_size: 2,
        sort_by: "created_at",
        sort_order: "asc",
      },
    },
  );
  typia.assert(paged);
  TestValidator.equals("page limit")(paged.pagination.limit)(2);
  TestValidator.equals("page current")(paged.pagination.current)(1);
  TestValidator.predicate("page size at most 2")(paged.data.length <= 2);

  // 10. Attempt to search as other customer (should return only own data)
  const bogus = await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
    connection,
    {
      body: { customer_id: otherCustomerId },
    },
  );
  typia.assert(bogus);
  for (const i of bogus.data)
    TestValidator.equals("customer always filtered to self")(i.customer_id)(customerId);

  // 11. Invalid status filter (should error or return zero results)
  await TestValidator.error("invalid status triggers error or empty result")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.productInquiries.search(
        connection,
        {
          body: { status: "not_a_real_status_value" },
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IPageIShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductInquiry";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate advanced product inquiry search for seller context.
 *
 * The seller must only see product inquiries for their products, filtered by various criteria (product_id, keywords, public/private, AI scores, date, status). Unowned product searches must be rejected or show zero results. Pagination, sorting, and access control are all verified.
 *
 * Steps:
 * 1. Register a new seller (so all products will belong to this seller)
 * 2. Simulate two products (UUIDs) 'owned' by this seller
 * 3. Register a customer (simulate, since customer auth is out of scope)
 * 4. The customer creates several product inquiries for each product and some for unrelated (fake) products
 * 5. As the seller, search for product inquiries:
 *   a. Filter by owned product1 — should return only relevant results
 *   b. Filter by owned product2 — should return only relevant results
 *   c. Use search keyword filter (title/body terms)
 *   d. Use AI threshold filter (min_ai_sentiment_score/max_ai_sentiment_score)
 *   e. Use "public" filters, date range, status, pagination, and sorting
 *   f. Try to search for a product the seller does not own (should yield error or empty)
 *   g. Try unauthorized filters (such as customer_id filter)—should be rejected with error
 *   h. Confirm result fields, ordering, and data integrity
 */
export async function test_api_product_inquiry_advanced_filter_search_seller(connection: api.IConnection) {
  // 1. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const signUpBody: ISellerAuth.SignUp = {
    email: sellerEmail,
    password: "Password123!",
    companyName: RandomGenerator.alphabets(8) + " Inc.",
    businessNumber: ArrayUtil.repeat(10)(() => String(typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<9>>())).join(""),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(10),
    phone: RandomGenerator.mobile()
  };
  const sellerResp = await api.functional.auth.seller.register.signUp(connection, { body: signUpBody });
  typia.assert(sellerResp);
  connection.headers = { ...(connection.headers ?? {}), Authorization: sellerResp.setHeaders.Authorization };
  const sellerProduct1 = typia.random<string & tags.Format<"uuid">>();
  const sellerProduct2 = typia.random<string & tags.Format<"uuid">>();

  // 2. Register a customer and simulate their UUID
  const customerId = typia.random<string & tags.Format<"uuid">>();

  // 3. Customer submits multiple inquiries for both seller products, some public and some private
  const inquiries = await ArrayUtil.asyncRepeat(5)(async (_, i) =>
    await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
      body: {
        customer_id: customerId,
        product_id: i < 3 ? sellerProduct1 : sellerProduct2,
        title: `Inquiry Title ${i}`,
        body: `Details about inquiry ${i} for product`,
        public: i % 2 === 0
      }
    })
  );
  const unrelatedProductId = typia.random<string & tags.Format<"uuid">>();
  await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: unrelatedProductId,
      title: "Unrelated Inquiry",
      body: "This product does not belong to the seller.",
      public: true
    }
  });

  // 4a. Seller searches for product1 inquiries
  const resProduct1 = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { product_id: sellerProduct1, page: 1, page_size: 10 }
  });
  typia.assert(resProduct1);
  TestValidator.predicate("Only inquiries for product 1")(resProduct1.data.every(q => q.product_id === sellerProduct1));

  // 4b. Seller searches for product2 inquiries
  const resProduct2 = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { product_id: sellerProduct2, page: 1, page_size: 10 }
  });
  typia.assert(resProduct2);
  TestValidator.predicate("Only inquiries for product 2")(resProduct2.data.every(q => q.product_id === sellerProduct2));

  // 4c. Filter by keyword present in one of the titles
  const keyword = "Title 2";
  const resKeyword = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { search: keyword, page: 1, page_size: 5 }
  });
  typia.assert(resKeyword);
  TestValidator.predicate("Title/body filter")(resKeyword.data.some(q => q.title.includes(keyword) || q.body.includes(keyword)));

  // 4d. Filter by AI sentiment (simulate fake data)
  // Set inquiries to have known AI sentiment
  // Not possible to update AI score here, but confirm that filter works (should not error, result may be empty)
  await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { min_ai_sentiment_score: 0.5 }
  });

  // 4e. Filter by "public" status
  const resPublic = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { public: true, page: 1, page_size: 10 }
  });
  typia.assert(resPublic);
  TestValidator.predicate("All inquiries public")(resPublic.data.every(q => q.public === true));

  // 4f. Sort by creation date descending
  const resSorted = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { sort_by: "created_at", sort_order: "desc", page: 1, page_size: 10 }
  });
