  for (let i = 1; i < resSorted.data.length; ++i) {
    TestValidator.predicate(`Sort order desc`)(resSorted.data[i - 1].created_at >= resSorted.data[i].created_at);
  }

  // 4g. Try to search for a product the seller does NOT own
  const resUnowned = await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, {
    body: { product_id: unrelatedProductId }
  });
  typia.assert(resUnowned);
  TestValidator.equals("Inquiries for unowned product")(resUnowned.data.length)(0);

  // 4h. Try unauthorized filter (customer_id as seller) - should error
  await TestValidator.error("Customer ID filter forbidden for seller context")(
    async () => 
      await api.functional.shoppingMallAiBackend.seller.productInquiries.search(connection, { body: { customer_id: customerId } })
  );

  // 4i. Check audit: not implementable (no endpoint), so skip.
}

