import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendIssuedCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendIssuedCoupon";
import type { IShoppingMallAiBackendCouponSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponSnapshot";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate creation of a new coupon snapshot as an admin—success, duplicate, and input error cases.
 *
 * Business context:
 * Coupon snapshots serve auditing, rollback, and compliance tracking in the system. Only admins can create snapshots, which must reference real, issued coupons and reflect coupon state history at the time of key events.
 *
 * Steps:
 * 1. Admin login—obtain JWT to enable admin-only coupon snapshot actions.
 * 2. Issue a coupon (creates valid reference data).
 * 3. Create a valid coupon snapshot (expect success).
 * 4. Attempt to create a duplicate snapshot (expect validation/conflict error).
 * 5. Attempt to create a snapshot for a fake/non-existent issued coupon (expect error).
 * 6. Edge: Omit a required field in snapshot input (expect input validation error).
 */
export async function test_api_coupon_snapshot_creation_success_and_duplicate(
  connection: api.IConnection,
) {
  // 1. Admin login (credentials assumed to exist in test env)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestSecure!P@ss1";
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);
  // JWT/Authorization is managed in the connection by SDK

  // 2. Issue a new coupon (get a valid coupon to snapshot)
  const issuedCoupon = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.create(connection, {
    body: {
      coupon_template_id: typia.random<string & tags.Format<"uuid">>(),
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      code: "CPN-" + typia.random<string>(),
      expires_at: new Date(Date.now() + 7 * 86400 * 1000).toISOString(),
      status: "issued",
    } satisfies IShoppingMallAiBackendIssuedCoupon.ICreate,
  });
  typia.assert(issuedCoupon);

  // 3. Create a valid coupon snapshot
  const snapshotInput = {
    issued_coupon_id: issuedCoupon.id,
    coupon_template_code: "TEMPLATE-" + typia.random<string>(),
    issued_coupon_code: issuedCoupon.code,
    customer_id: issuedCoupon.customer_id,
    status: issuedCoupon.status,
    valid_from: issuedCoupon.issued_at,
    valid_until: issuedCoupon.expires_at,
    action: "issued",
  } satisfies IShoppingMallAiBackendCouponSnapshot.ICreate;

  const createdSnapshot = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, {
    body: snapshotInput,
  });
  typia.assert(createdSnapshot);
  TestValidator.equals("issued_coupon_id matches")(createdSnapshot.issued_coupon_id)(snapshotInput.issued_coupon_id);
  TestValidator.equals("coupon_template_code")(createdSnapshot.coupon_template_code)(snapshotInput.coupon_template_code);
  TestValidator.equals("issued_coupon_code")(createdSnapshot.issued_coupon_code)(snapshotInput.issued_coupon_code);
  TestValidator.equals("customer_id")(createdSnapshot.customer_id)(snapshotInput.customer_id);
  TestValidator.equals("status")(createdSnapshot.status)(snapshotInput.status);
  TestValidator.equals("valid_from")(createdSnapshot.valid_from)(snapshotInput.valid_from);
  TestValidator.equals("valid_until")(createdSnapshot.valid_until)(snapshotInput.valid_until);
  TestValidator.equals("action")(createdSnapshot.action)(snapshotInput.action);

  // 4. Duplicate snapshot (same reference data)
  await TestValidator.error("duplicate coupon snapshot should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, {
      body: snapshotInput,
    }),
  );

  // 5. Non-existent issued_coupon_id
  const fakeSnapshotInput = {
    ...snapshotInput,
    issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
  };
  await TestValidator.error("non-existent issued_coupon_id should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, {
      body: fakeSnapshotInput,
    }),
  );

  // 6. Omit required field—remove status
  const { status: _omit, ...missingFieldInput } = snapshotInput;
  // @ts-expect-error: intentionally missing 'status', should cause runtime validation error
  await TestValidator.error("missing required field should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, {
      body: missingFieldInput,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteProduct";
import type { IShoppingMallAiBackendFavoriteSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteSnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validate retrieval of a favorite snapshot record by its unique ID as the owning customer.
 *
 * Business context: Favorite snapshot records store the state of a customer’s favorite (e.g., product) at a specific point in time, serving as evidence or for audit/history. Access is tightly controlled so that only the owner-customer (or authorized admin) can fetch their own snapshot data.
 *
 * Test necessity: Fetching a snapshot must be strictly limited to authorized users, and records must properly reflect the serialized state. Security and data integrity are paramount because these records can serve as legal or auditing evidence.
 *
 * Step-by-step process:
 * 1. Register a new customer (the owner) and log in
 * 2. As the customer, favorite a product (requires a random product UUID)
 * 3. Create a favorite snapshot for the favorited product, serializing the favorite product as JSON
 * 4. Fetch the snapshot by its ID as the customer (should succeed):
 *    - Validate all fields
 *    - Confirm correct reference IDs, target_type, and historical serialized_object
 * 5. Attempt to fetch a non-existent favorite snapshot ID (should error)
 * 6. Register/login a different customer; attempt to fetch the snapshot (should error due to lack of ownership)
 * 7. Simulate soft-delete by unfavoriting/removing the original favorite product; try fetching snapshot (should still allow fetch if snapshot record is not deleted)
 * 8. (if possible) Simulate deleting the snapshot, then try fetching (should error)
 * 9. Attempt fetching without authentication (should error)
 */
export async function test_api_favorite_snapshot_get_by_owner(connection: api.IConnection) {
  // 1. Register a new customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "Password1234@";
  const signUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(signUp);
  // Token auto-attached to connection headers.

  // 2. Favorite a product to create favorite product record
  const productId = typia.random<string & tags.Format<"uuid">>();
  const favorite = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: { product_id: productId } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate
  });
  typia.assert(favorite);

  // 3. Create a favorite snapshot (type PRODUCT, serialize favorite product as JSON string)
  const serializedObject = JSON.stringify(favorite);
  const snapshot = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: {
      favorite_product_id: favorite.id,
      favorite_inquiry_id: null,
      favorite_address_id: null,
      target_type: "PRODUCT",
      snapshot_object_id: productId,
      serialized_object: serializedObject
    } satisfies IShoppingMallAiBackendFavoriteSnapshot.ICreate
  });
  typia.assert(snapshot);

  // 4. Fetch snapshot by its ID as owner -- should succeed
  const fetched = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.at(connection, {
    favoriteSnapshotId: snapshot.id
  });
  typia.assert(fetched);
  TestValidator.equals("fetched snapshot")(fetched)(snapshot);
  // Validate content matches
  TestValidator.equals("serialized object")(fetched.serialized_object)(serializedObject);

  // 5. Fetch non-existent ID (should error)
  await TestValidator.error("non-existent ID")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.at(connection, {
      favoriteSnapshotId: typia.random<string & tags.Format<"uuid">>()
    });
  });

  // 6. Register/login a different customer, attempt to fetch (should error)
  const otherEmail = typia.random<string & tags.Format<"email">>();
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: otherEmail,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile()
    }
  });
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: otherEmail,
      password
    }
  });
  await TestValidator.error("not the owner, should not access")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.at(connection, {
      favoriteSnapshotId: snapshot.id
    });
  });

  // 7. Simulate soft-delete by removing/unfavoriting the product
  // There is no delete/unfavorite API, but favoriteProducts record has deleted_at: just simulate via test data
  // We cannot actually remove via provided API, so skip actual removal logic.

  // 8. Simulate deleting the snapshot itself: no API for this, so skip.

  // 9. Attempt fetch without authentication (simulate by clearing token)
  const guestConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthenticated fetch should fail")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.at(guestConnection, {
      favoriteSnapshotId: snapshot.id
    });
  });
}

