import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAccessLog";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that sensitive access logs cannot be read by unauthorized identities and that system enforces audit and compliance requirements.
 *
 * This scenario verifies that the /shoppingMallAiBackend/admin/accessLogs/{accessLogId} endpoint denies access to all non-admin tokens. The endpoint must return an error for all types of unauthorized access (customer, seller, no token, revoked JWT). Additionally, the test validates that no access log details are accidentally returned, and that the forbidden attempt itself is auditable for compliance (though deeper audit log assertion is out-of-scope for standard black-box E2E).
 *
 * Test workflow:
 * 1. Register a customer to obtain a non-admin JWT token.
 * 2. Attempt to retrieve a randomly-generated access log by ID using this customer token (should fail: permission denied).
 * 3. Repeat with no Authorization header (should fail: permission denied).
 * 4. Simulate a revoked JWT by tampering with a valid token and repeat the request (should fail: permission denied).
 * 5. Confirm no access log details are present in the forbidden response for each scenario.
 */
export async function test_api_access_log_retrieve_unauthorized_access(connection: api.IConnection) {
  // 1. Register a customer to obtain a valid JWT token
  const signUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      name: "Test User",
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpResponse);
  const customerToken = signUpResponse.setHeaders.Authorization;

  // Generate a random access log UUID to use in forbidden access attempts
  const accessLogId = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt with non-admin customer JWT
  await TestValidator.error("non-admin user cannot access access logs")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.accessLogs.at({
        ...connection,
        headers: { ...connection.headers, Authorization: customerToken },
      }, { accessLogId });
    }
  );

  // 3. Attempt with NO token (unauthenticated)
  await TestValidator.error("unauthenticated client cannot access access logs")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.accessLogs.at({
        ...connection,
        headers: { ...connection.headers, Authorization: undefined },
      }, { accessLogId });
    }
  );

  // 4. Attempt with tampered (revoked) JWT
  const tamperedToken = customerToken.slice(0, -5) + "abcde"; // Tamper tail of the JWT
  await TestValidator.error("revoked or tampered JWT cannot access access logs")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.accessLogs.at({
        ...connection,
        headers: { ...connection.headers, Authorization: tamperedToken },
      }, { accessLogId });
    }
  );

  // 5. (Implicit) No log details must ever be returned in any error case
  // TestValidator.error() ensures that no log info leaks on error.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartItem";
import type { IPageIShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCartItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin search, filter, and pagination for cart items in a given cart.
 *
 * Business purpose:
 * Ensure that an admin can successfully paginate and search for cart items belonging to a specific cart using allowed search filters: product_id, product_option_id, created_at(date range), and with pagination (page/limit).  
 * This test covers the business scenario that an admin should see all items in a given cart and can filter down as required for support/audit/business operations.
 *
 * Step-by-step process:
 * 1. Register a customer (owner of the cart)
 * 2. Register an admin (will perform the search as admin)
 * 3. As customer, create a cart
 * 4. As customer, add multiple cart items into this cart (distinct product_ids, quantities, and optionally product_option_id)
 * 5. As admin, search for cart items in that cart:
 *    a. No filters, page/limit specified — validate ALL items visible, correct page & total
 *    b. Filter by product_id of one created item, validate only that item (or those items if same id used multiple times) are returned
 *    c. Filter by created_at_from/created_at_to covering specific range, validate correct items are returned by timestamp
 * 6. For all cases: assert that the items returned satisfy the filter, and pagination metadata is accurate.
 */
export async function test_api_cart_item_search_filter_pagination_success_admin(connection: api.IConnection) {
  // 1. Register a customer and receive JWT for customer actions
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Cpw123!" + typia.random<string>();
  const customerReg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name() + typia.random<string>(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerReg);

  // Authenticate as this customer for following steps
  connection.headers = { ...(connection.headers ?? {}), Authorization: customerReg.setHeaders.Authorization };

  // 2. Register an admin and store the Authorization header (for later)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Apw123!" + typia.random<string>();
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminReg);
  const adminJwt = adminReg.setHeaders.Authorization;

  // 3. Customer creates a cart
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    },
  });
  typia.assert(cart);

  // 4. Customer adds several cart items (distinct product_id, qty, option)
  const products = ArrayUtil.repeat(5)(() => ({ product_id: typia.random<string & tags.Format<"uuid">>(), product_option_id: typia.random<string & tags.Format<"uuid">>(), quantity: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(), unit_price: 10000 + typia.random<number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<1000>>(), currency_code: "KRW", note: RandomGenerator.paragraph()(10) }));
  const now = new Date();

  // Use precise timestamp for each insertion (for deterministic date filter tests)
  const insertedItems: { item: IShoppingMallAiBackendCartItem; inserted_at: Date }[] = [];
  for (const prod of products) {
    // Wait one ms to ensure unique timestamps
    await new Promise((resolve) => setTimeout(resolve, 2));
    const created = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
      cartId: cart.id,
      body: {
        ...prod,
      },
    });
    typia.assert(created);
    insertedItems.push({ item: created, inserted_at: new Date(created.created_at) });
  }

  // 5. Switch to admin account (set Authorization header)
  connection.headers = { ...(connection.headers ?? {}), Authorization: adminJwt };

  // ----
  // 5a. Search for all items in the cart (no filters)
  const pageLimit = 2;
  const noFilterPage1 = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: { page: 1, limit: pageLimit },
  });
  typia.assert(noFilterPage1);
  TestValidator.equals("pagination.records count matches items")(
    noFilterPage1.pagination.records,
  )(insertedItems.length);
  TestValidator.equals("pagination.current page is correct")(noFilterPage1.pagination.current)(1);
  TestValidator.equals("pagination.limit is correct")(noFilterPage1.pagination.limit)(pageLimit);
  // Data matches expected items
  TestValidator.equals("first page data matches")(
    noFilterPage1.data.map((it) => it.id),
  )(insertedItems.map((x) => x.item.id).slice(0, pageLimit));

  // ----
  // 5a-2. Page 2 - should have remaining items
  const noFilterPage2 = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: { page: 2, limit: pageLimit },
  });
  typia.assert(noFilterPage2);
  TestValidator.equals("pagination.current page is 2")(noFilterPage2.pagination.current)(2);
  // Data matches expected items
  TestValidator.equals("page 2 data matches")(
    noFilterPage2.data.map((it) => it.id),
  )(insertedItems.map((x) => x.item.id).slice(pageLimit, pageLimit * 2));

  // ----
  // 5b. Filter by product_id of first inserted item
  const filterProductId = insertedItems[0].item.product_id;
  const filteredByProductId = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: { product_id: filterProductId },
  });
  typia.assert(filteredByProductId);
  // Should only find items with this product_id
  TestValidator.predicate("all items have correct product_id")(
    filteredByProductId.data.every((it) => it.product_id === filterProductId),
  );

  // ----
  // 5c. Date range filter: items inserted strictly after first (should yield 4)
  const createdDates = insertedItems.map((x) => x.inserted_at).sort((a, b) => a.getTime() - b.getTime());
  const afterFirst = createdDates[1].toISOString();
  const filteredByDateFrom = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: { created_at_from: afterFirst },
  });
  typia.assert(filteredByDateFrom);
  // Should contain all except the first item
  TestValidator.equals("date-from filter matches correct items")(
    filteredByDateFrom.data.length,
  )(insertedItems.length - 1);
  filteredByDateFrom.data.forEach((item) => {
    TestValidator.predicate("created_at >= from")(
      new Date(item.created_at).getTime() >= new Date(afterFirst).getTime(),
    );
  });

  // 5d. Date range filter: between 2nd and 4th item inclusively
  const from = createdDates[1].toISOString();
  const to = createdDates[3].toISOString();
  const range = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: { created_at_from: from, created_at_to: to },
  });
  typia.assert(range);
  // The items between 2nd and 4th inclusively
  const expectedInRange = insertedItems.filter((x) => x.inserted_at >= new Date(from) && x.inserted_at <= new Date(to));
  TestValidator.equals("date range matches")(
    range.data.map((it) => it.id),
    expectedInRange.map((x) => x.item.id),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * E2E test: ensure that a seller cannot delete product content owned by another seller.
 *
 * Business context:
 * Only the owner seller of a product (and its product content) should be able to delete their own product content. If another seller attempts to delete this content, the API must return a permission error and the content should remain intact in the system.
 *
 * Steps:
 * 1. Register Seller A.
 * 2. Register Seller B.
 * 3. Login as Seller A and create a new product.
 * 4. As Seller A, add a product content to the product.
 * 5. Logout (if necessary) and login as Seller B.
 * 6. As Seller B (who does not own the product), attempt to delete Seller A's product content. This should fail with a permission error.
 * 7. Login back as Seller A and verify that the product content still exists by (optionally) attempting deletion (should succeed for the owner), or by verifying via API if there is a content listing/read function.
 *
 * Validations:
 * - The cross-owner deletion attempt by Seller B must fail with a permission-related error.
 * - The product content must still exist after the failed deletion attempt, as verified by the owner.
 */
export async function test_api_product_content_delete_not_owned_by_seller(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAemail = typia.random<string & tags.Format<"email">>();
  const sellerApassword = "Password123!"; // static for login simplicity
  const sellerA = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAemail,
      password: sellerApassword,
      companyName: RandomGenerator.company(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerA);

  // 2. Register Seller B
  const sellerBemail = typia.random<string & tags.Format<"email">>();
  const sellerBpassword = "Password123!";
  const sellerB = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBemail,
      password: sellerBpassword,
      companyName: RandomGenerator.company(),
      businessNumber: "0987654321",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerB);

  // 3. Login as Seller A (ensure token is set)
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerAemail,
      password: sellerApassword,
    } satisfies ISellerAuth.SignIn,
  });

  // 4. Seller A creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerA.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(1),
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 5. Seller A creates product content
  const content = await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      content_type: "gallery_image",
      content_uri: "https://cdn.example.com/images/" + RandomGenerator.alphaNumeric(8),
      content_order: 1,
      content_description: RandomGenerator.paragraph()(1),
      status: "active",
    } satisfies IShoppingMallAiBackendProductContent.ICreate,
  });
  typia.assert(content);

  // 6. Login as Seller B (sets token)
  await api.functional.auth.seller.login.signIn(connection, {
    body: { email: sellerBemail, password: sellerBpassword } satisfies ISellerAuth.SignIn,
  });

  // 7. Seller B attempts to delete Seller A's product content (should FAIL - permission error)
  await TestValidator.error("Seller B cannot delete Seller A's product content")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productContents.erase(connection, {
      productId: product.id,
      productContentId: content.id,
    }),
  );

  // 8. Login again as Seller A to ensure content is present (no GET/list endpoint so attempt DELETE - should succeed)
  await api.functional.auth.seller.login.signIn(connection, {
    body: { email: sellerAemail, password: sellerApassword } satisfies ISellerAuth.SignIn,
  });
  await api.functional.shoppingMallAiBackend.seller.products.productContents.erase(connection, {
    productId: product.id,
    productContentId: content.id,
  });
  // If no error thrown, deletion by owner succeeded; permission logic is enforced.
}

