 * 2. Create a product under the new seller
 * 3. Create multiple bundles with varied properties for the product
 * 4. Test default listing (no filters): All created bundles must appear
 * 5. Test status filter: Only bundles with the requested status appear
 * 6. Test name substring filter: Bundles matching substring appear
 * 7. Test pagination: Returned page limited & unique records between pages
 * 8. All responses are type-validated and business properties are asserted
 */
export async function test_api_product_bundle_list_success_seller(
  connection: api.IConnection,
) {
  // 1. Register seller
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPass!1",
      companyName: RandomGenerator.name(),
      businessNumber: ("" + typia.random<number & tags.Type<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>>()),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    }
  });
  typia.assert(sellerSignUp);
  const sellerId = sellerSignUp.sellerId;

  // 2. Create Product under seller
  const productCreate = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      status: "draft",
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
    }
  });
  typia.assert(productCreate);
  const productId = productCreate.id;

  // 3. Create multiple bundles with varied status and name
  const statuses = ["active", "hidden", "discontinued"];
  const createdBundles = [];
  for (let idx = 0; idx < 3; ++idx) {
    const bundle = await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, {
      productId,
      body: {
        main_product_id: productId,
        code: RandomGenerator.alphaNumeric(6) + idx,
        name: `Bundle_${idx}_${RandomGenerator.alphabets(3)}`,
        description: idx % 2 === 0 ? RandomGenerator.paragraph()() : null,
        bundle_policy: idx % 2 ? null : RandomGenerator.paragraph()(),
        bundle_price: idx === 1 ? 9999 + idx : null,
        status: statuses[idx],
      }
    });
    typia.assert(bundle);
    createdBundles.push(bundle);
  }

  // 4. Default list (no filters)
  const searchAll = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: {
      page: 1,
      limit: 100,
    }
  });
  typia.assert(searchAll);
  for (const bundle of createdBundles) {
    TestValidator.predicate("bundle returned in search")(searchAll.data.some((b) => b.id === bundle.id));
  }
  for (const summary of searchAll.data) {
    TestValidator.equals("product id matches in summary")(summary.main_product_id)(productId);
  }

  // 5. Status filter ('active')
  const searchActive = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { status: "active" }
  });
  typia.assert(searchActive);
  for (const summary of searchActive.data) {
    TestValidator.equals("status is active")(summary.status)("active");
  }

  // 6. Name substring filter
  const nameSubstring = createdBundles[1].name.slice(3, 6);
  const searchByName = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { name: nameSubstring }
  });
  typia.assert(searchByName);
  TestValidator.predicate("bundle matching name substring present")(
    searchByName.data.some((b) => b.id === createdBundles[1].id)
  );

  // 7. Pagination (limit 1, check uniqueness)
  const page1 = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { page: 1, limit: 1 }
  });
  typia.assert(page1);
  TestValidator.equals("records returned is 1")(page1.data.length)(1);
  const page2 = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { page: 2, limit: 1 }
  });
  typia.assert(page2);
  TestValidator.equals("records returned is 1")(page2.data.length)(1);
  TestValidator.notEquals("page 1 and page 2 bundles differ")(page1.data[0].id)(page2.data[0].id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";
import type { IPageIShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductBundle";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that soft-deleted product bundles are excluded from the seller's product bundle listing/search results.
 *
 * This test performs the following steps end-to-end:
 * 1. Seller registers and receives authentication for creating/managing products and bundles.
 * 2. The seller creates a new product to act as the main product for bundles.
 * 3. Multiple (at least 3) product bundles are created and associated with the product as the seller.
 * 4. At least one of the created bundles is soft-deleted by calling the erase API.
 * 5. The seller searches for product bundles attached to the product using the search endpoint (PATCH with filters).
 * 6. The test verifies that soft-deleted product bundles do not appear in the search result and only non-deleted remain.
 *
 * This business rule is critical to ensure that listings shown for management and admin contexts do not display any soft-deleted bundles.
 *
 * Steps:
 * 1. Register seller and extract sellerId/jwt for authentication.
 * 2. Create a product as the seller; store returned productId.
 * 3. Create N bundles (N>=3), confirm their presence via search.
 * 4. Delete one bundle using the erase endpoint (soft delete mechanism).
 * 5. Perform product bundle search. Confirm response only includes non-deleted product bundles.
 * 6. Confirm that IDs/statuses of returned bundles match the expected set (the deleted one(s) is/are missing).
 */
export async function test_api_product_bundle_list_soft_deleted_excluded(connection: api.IConnection) {
  // 1. Seller registration
  const sellerData: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "securePassword123!",
    companyName: RandomGenerator.name(),
    businessNumber: RandomGenerator.alphaNumeric(10),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  };
  const sellerAuth = await api.functional.auth.seller.register.signUp(connection, { body: sellerData });
  typia.assert(sellerAuth);

  // 2. Create product
  const productCreate: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: sellerAuth.sellerId,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    main_image_uri: null,
    status: "active",
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: productCreate });
  typia.assert(product);

  // 3. Create 3 product bundles for this product
  const bundles: IShoppingMallAiBackendProductBundle[] = [];
  for (let i = 0; i < 3; ++i) {
    const bundleCreate: IShoppingMallAiBackendProductBundle.ICreate = {
      main_product_id: product.id,
      code: RandomGenerator.alphaNumeric(7) + i,
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      bundle_policy: null,
      bundle_price: null,
      status: "active",
    };
    const bundle = await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, { productId: product.id, body: bundleCreate });
    typia.assert(bundle);
    bundles.push(bundle);
  }

  // 4. Soft-delete (erase) the second bundle
  const deletedBundle = bundles[1];
  await api.functional.shoppingMallAiBackend.seller.products.productBundles.erase(connection, { productId: product.id, productBundleId: deletedBundle.id });

  // 5. Search for product bundles (should not include soft-deleted)
  const searchResult = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId: product.id,
    body: {
      main_product_id: product.id,
      page: 1,
      limit: 10
    }
  });
  typia.assert(searchResult);

  // 6. Verify soft-deleted bundle is not present
  const resultIds = searchResult.data.map(b => b.id);
  for (const [idx, bundle] of bundles.entries()) {
    if (idx === 1) {
      TestValidator.notEquals("deleted bundle should NOT be present")(resultIds)(bundle.id);
    } else {
      TestValidator.predicate("remaining bundle should be present")(resultIds.includes(bundle.id));
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";
import type { IPageIShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductBundle";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates advanced search and paginated listing of product bundles for a product as admin.
 *
 * This test ensures that an admin can:
 * - Create a new product (prerequisite).
 * - Register multiple bundles for this product with varied bundle policies, statuses, prices, and names.
 * - Perform a complex, paginated search with filters (bundle policy, status, name, etc.).
 * - Validate that only the bundles matching given criteria (belonging to the product, matching filter) are returned, and pagination works as expected.
 * - Confirm correct pagination metadata and robust admin data visibility.
 *
 * Steps:
 * 1. Create a product via admin API.
 * 2. Create several bundles for the product, covering both 'target' and 'non-target' filter attributes.
 * 3. Construct advanced search filter to match only a subset of the bundles (e.g., those with campaign policy and active status).
 * 4. Perform search for bundles using the advanced filter, check paginated response (page 1, limit 2).
 * 5. Validate that only correct bundles (e.g. 'VIP Bundle', active, campaign) are returned, and pagination is accurate.
 * 6. Fetch the next page and validate response.
 * 7. Optionally, test an edge case: filter with criteria that matches no bundles and check that the result set is empty.
 */
export async function test_api_product_bundle_list_success_admin(
  connection: api.IConnection,
) {
  // Step 1: Admin creates a product to associate bundles
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(1),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // Step 2: Admin creates several bundles for the product (varied attributes for filtering)
  const bundles = await ArrayUtil.asyncRepeat(5)(async (_, i) => {
    // First three bundles are 'target' (will match filter), rest are not
    const isTarget = i < 3;
    return await api.functional.shoppingMallAiBackend.admin.products.productBundles.create(connection, {
      productId: product.id,
      body: {
        main_product_id: product.id,
        code: `BNDL-${RandomGenerator.alphaNumeric(4)}-${i}`,
        name: isTarget ? `VIP Bundle ${i}` : `Standard Pack ${i}`,
        description: isTarget ? "Promo bundle for campaign" : null,
        bundle_policy: isTarget ? "campaign" : "manual",
        bundle_price: isTarget ? 6000 + i * 250 : 12000 + i * 500,
        status: isTarget ? "active" : "discontinued",
      } satisfies IShoppingMallAiBackendProductBundle.ICreate,
    });
  });
  bundles.forEach(typia.assert);

  // Step 3: Prepare advanced filter to select only the 'target' bundles (VIP Bundle/campaign/active)
  const filter = {
    main_product_id: product.id,
    bundle_policy: "campaign",
    status: "active",
    name: "VIP Bundle",
    page: 1,
    limit: 2,
    order_by: "created_at",
    order_direction: "asc",
  } satisfies IShoppingMallAiBackendProductBundle.IRequest;

  // Step 4: Search (page 1)
  const result = await api.functional.shoppingMallAiBackend.admin.products.productBundles.search(connection, {
    productId: product.id,
    body: filter,
  });
  typia.assert(result);

  // Step 5: Verify only correct bundles are listed and pagination is as expected
  TestValidator.predicate("Only correct bundles returned")(
    result.data.every(b =>
      b.main_product_id === product.id &&
      b.name.startsWith("VIP Bundle") &&
      b.status === "active"
    ),
  );
  TestValidator.equals("pagination limit")(result.pagination.limit)(2);
  TestValidator.equals("result data length <= limit")(result.data.length <= 2)(true);

  // Step 6: Fetch page 2
  const result2 = await api.functional.shoppingMallAiBackend.admin.products.productBundles.search(connection, {
    productId: product.id,
    body: { ...filter, page: 2 },
  });
  typia.assert(result2);
  TestValidator.equals("pagination current page")(result2.pagination.current)(2);

  // Step 7: Edge: search for bundles with non-matching name (should be empty)
  const emptyResult = await api.functional.shoppingMallAiBackend.admin.products.productBundles.search(connection, {
    productId: product.id,
    body: {
      main_product_id: product.id,
      name: "NoSuch Bundle",
      page: 1,
      limit: 1,
    } satisfies IShoppingMallAiBackendProductBundle.IRequest,
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty result count")(emptyResult.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponHistory";
import type { IPageIShoppingMallAiBackendCouponHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCouponHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for searching and filtering coupon history records as an admin.
 *
 * Business context: Coupon histories are sensitive audit records for compliance. Only authorized (admin) users may access this endpoint. This test ensures that filter/search functionality and pagination operate correctly and securely.
 *
 * Validates:
 * - Admin authentication is required (dependency: login)
 * - Coupon history search returns accurate, filtered results when various filters are applied (coupon, issued_coupon_id, actor_id/type, action, date range, sort, pagination)
 * - Edge cases: (a) no filters (should return paginated unfiltered records); (b) all filters combined; (c) invalid filter parameters (should be error); (d) unauthorized user access (should be rejected)
 * - Pagination details are correct (page, limit, total records, data ordering)
 *
 * Steps:
 * 1. Authenticate as admin using valid credentials
 * 2. Search without any filters, validate paginated result structure
 * 3. Search with combination of filters (issued_coupon_id, actor_id, action, date range, sort), validate only relevant records returned
 * 4. Attempt search with invalid filter (invalid uuid, negative page/limit, nonsensical sort), expect error
 * 5. Logout / clear auth and repeat search to validate rejection for unauthorized user
 */
export async function test_api_coupon_history_search_filter_pagination(
  connection: api.IConnection,
) {
  // Step 1: Admin authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "correct-password";
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // Step 2: Search with NO filters (required fields: page + limit only)
  const unfiltered = await api.functional.shoppingMallAiBackend.admin.couponHistories.search(connection, {
    body: {
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendCouponHistory.IRequest,
  });
  typia.assert(unfiltered);
  TestValidator.predicate("pagination structure")(!!unfiltered.pagination && Array.isArray(unfiltered.data));

  // Step 3: Search with COMBINED filters (using random valid values)
  const filters = {
    issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    actor_type: "admin",
    action: "used",
    action_at_from: new Date(Date.now() - 7*24*3600*1000).toISOString(),
    action_at_to: new Date().toISOString(),
    page: 1,
    limit: 5,
    sort: "action_at desc",
  } satisfies IShoppingMallAiBackendCouponHistory.IRequest;
  const filtered = await api.functional.shoppingMallAiBackend.admin.couponHistories.search(connection, {
    body: filters,
  });
  typia.assert(filtered);
  if (filtered.data.length > 0) {
    TestValidator.equals("issued_coupon_id filtered correctly")(filtered.data[0].issued_coupon_id)(filters.issued_coupon_id);
    TestValidator.equals("actor_type filtered correctly")(filtered.data[0].actor_type)(filters.actor_type);
    TestValidator.equals("action filtered correctly")(filtered.data[0].action)(filters.action);
  }
  TestValidator.predicate("filtered results page")(filtered.pagination.current === 1 && filtered.pagination.limit === 5);

  // Step 4: Error on INVALID filters—should trigger error (invalid uuid, negative page, etc)
  await TestValidator.error("invalid filter params should error")(
    () => api.functional.shoppingMallAiBackend.admin.couponHistories.search(connection, {
      body: {
        issued_coupon_id: "not-a-uuid" as string & tags.Format<"uuid">,
        page: -1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 0 as number & tags.Type<"int32"> & tags.Minimum<1>,
      } satisfies IShoppingMallAiBackendCouponHistory.IRequest,
    })
  );

  // Step 5: Unauthenticated access should fail
  // Simulate logout by clearing token (in this infra, overwriting Authorization header)
  const unauthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthorized user is rejected")(
    () => api.functional.shoppingMallAiBackend.admin.couponHistories.search(unauthConnection, {
      body: {
        page: 1,
        limit: 1,
      } satisfies IShoppingMallAiBackendCouponHistory.IRequest,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendIssuedCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendIssuedCoupon";
import type { IShoppingMallAiBackendCouponHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponHistory";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin creation of coupon history (audit) events in the shopping mall backend.
 *
 * This test covers the following scenarios:
 * 1. Admin can successfully create a coupon history event for an existing issued coupon when all required fields are valid.
 * 2. Attempting to create a coupon history with a non-existent issued_coupon_id or invalid action/actor_type should result in a runtime business validation error.
 * 3. Attempting to create a coupon history event while unauthorized (not logged in as admin) should return a permission error.
 *
 * Step-by-step business process:
 * 1. Authenticate as an admin using /auth/admin/login to obtain JWT.
 * 2. Issue a coupon by calling /shoppingMallAiBackend/admin/issuedCoupons to create an issued coupon. This is required as a reference (valid issued_coupon_id) for the coupon history event.
 * 3. Create a valid coupon history event for the issued coupon by calling /shoppingMallAiBackend/admin/couponHistories. Use typical fields (e.g. actor_type: "admin", action: "issued") and validate persistence.
 * 4. Try to use a non-existent issued_coupon_id and check that an error occurs.
 * 5. Try to create a coupon history event with invalid actor_type or action, expecting a runtime validation or business error.
 * 6. Log out (clear admin JWT/Authorization), then attempt to create a coupon history event to expect a permission error.
 */
export async function test_api_coupon_history_create_success_and_invalid(
  connection: api.IConnection,
) {
  // 1. Admin authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SuperSecret123!";

  // Assumes test environment is seeded with this admin (login attempt)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);
  // SDK should set JWT automatically

  // 2. Issue a coupon
  const couponTemplateId = typia.random<string & tags.Format<"uuid">>();
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const issuedCoupon = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.create(connection, {
    body: {
      coupon_template_id: couponTemplateId,
      customer_id: customerId,
      code: RandomGenerator.alphaNumeric(12),
      expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24 * 30).toISOString(),
      status: "issued",
    } satisfies IShoppingMallAiBackendIssuedCoupon.ICreate,
  });
  typia.assert(issuedCoupon);

  // 3. Create a valid coupon history event
  const now = new Date().toISOString();
  const couponHistory = await api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
    body: {
      issued_coupon_id: issuedCoupon.id,
      actor_id: adminLogin.adminId,
      actor_type: "admin",
      action: "issued",
      action_at: now,
      remarks: "Initial issuance audit.",
    } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
  });
  typia.assert(couponHistory);
  TestValidator.equals("issued_coupon_id")(couponHistory.issued_coupon_id)(issuedCoupon.id);
  TestValidator.equals("actor_type")(couponHistory.actor_type)("admin");
  TestValidator.equals("action")(couponHistory.action)("issued");

  // 4. Non-existent issued_coupon_id (should fail)
  await TestValidator.error("invalid issued_coupon_id")(() =>
    api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
      body: {
        issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
        actor_id: adminLogin.adminId,
        actor_type: "admin",
        action: "issued",
        action_at: now,
      } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
    })
  );

  // 5. Invalid action or actor_type (should fail)
  await TestValidator.error("invalid action value")(() =>
    api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
      body: {
        issued_coupon_id: issuedCoupon.id,
        actor_id: adminLogin.adminId,
        actor_type: "admin",
        action: "not_a_valid_action",
        action_at: now,
      } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
    })
  );
  await TestValidator.error("invalid actor_type value")(() =>
    api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
      body: {
        issued_coupon_id: issuedCoupon.id,
        actor_id: adminLogin.adminId,
        actor_type: "robot",
        action: "issued",
        action_at: now,
      } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
    })
  );

  // 6. Attempt as unauthorized user (logout scenario)
  connection.headers.Authorization = undefined; // Simulate logout if SDK/session supports explicit clearance
  await TestValidator.error("unauthorized create should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
      body: {
        issued_coupon_id: issuedCoupon.id,
        actor_id: adminLogin.adminId,
        actor_type: "admin",
        action: "issued",
        action_at: now,
      } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponHistory";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate updating coupon history records by an admin, ensuring only permitted fields are changeable.
 *
 * This E2E test ensures admin users can update ONLY the allowed 'remarks' field for audit compliance
 * while all other fields remain immutable. It confirms update persistence, proper error handling for
 * unauthorized and not-found scenarios, and checks data validation for remarks input.
 *
 * Steps:
 * 1. Authenticate as admin with valid credentials
 * 2. Create a coupon history record for testing
 * 3. Successfully update the "remarks" field—verify changes persist
 * 4. Attempt update as unauthorized user—expect rejection
 * 5. Attempt to update non-existent coupon history—expect not-found error
 * 6. Attempt invalid data in remarks—expect validation failure
 */
export async function test_api_coupon_history_update_content_and_policies(
  connection: api.IConnection,
) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234";
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 2. Create a coupon history record for updating
  const couponHistoryCreate: IShoppingMallAiBackendCouponHistory.ICreate = {
    issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    actor_type: "admin",
    action: "issued",
    action_at: new Date().toISOString(),
    remarks: "Initial test remark",
  };
  const created = await api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, { body: couponHistoryCreate });
  typia.assert(created);
  TestValidator.equals("initial remarks")(created.remarks)(couponHistoryCreate.remarks);

  // 3. Successfully update the remarks field
  const updateValue = `Updated at ${new Date().toISOString()}`;
  const updated = await api.functional.shoppingMallAiBackend.admin.couponHistories.update(connection, {
    couponHistoryId: created.id,
    body: { remarks: updateValue },
  });
  typia.assert(updated);
  TestValidator.equals("remarks updated")(updated.remarks)(updateValue);
  TestValidator.equals("id remains")(updated.id)(created.id);
  TestValidator.equals("issued_coupon_id remains")(updated.issued_coupon_id)(created.issued_coupon_id);
  TestValidator.equals("action remains unchanged")(updated.action)(created.action);

  // 4. Attempt update as unauthorized user (no admin JWT) should be rejected
  const otherConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized update rejected")(async () => {
    await api.functional.shoppingMallAiBackend.admin.couponHistories.update(otherConnection, {
      couponHistoryId: created.id,
      body: { remarks: "Should not work" },
    });
  });

  // 5. Attempt to update a non-existent coupon history record should yield not found
  await TestValidator.error("not found on non-existent couponHistoryId")(async () => {
    await api.functional.shoppingMallAiBackend.admin.couponHistories.update(connection, {
      couponHistoryId: typia.random<string & tags.Format<"uuid">>(),
      body: { remarks: "Should fail" },
    });
  });

  // 6. Attempt invalid data for remarks (array instead of string/null) should cause validation error
  await TestValidator.error("invalid data for remarks")(async () => {
    // @ts-expect-error: intentionally incorrect type for runtime validation
    await api.functional.shoppingMallAiBackend.admin.couponHistories.update(connection, {
      couponHistoryId: created.id,
      body: { remarks: ["not a string or null"] },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteProduct";
import type { IShoppingMallAiBackendFavoriteNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteNotification";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test that access to a favorite notification is denied when requested by a user other than its owner.
 *
 * Business context:
 * Favorite product notifications (such as price drop, restock, etc.) must be accessible only by their rightful owners for privacy and security. This test ensures that one user cannot view another user's notification event details, protecting sensitive information and ensuring proper authorization controls.
 *
 * Test process:
 * 1. Register Customer 1 using unique email, nickname, phone, etc. Capture their Authorization header (JWT) for authenticated operations.
 * 2. Using Customer 1 session, create a favorite product (with a random product UUID).
 * 3. Using Customer 1, create a notification event for the newly created favorite product, specifying sample notification type, channel, and marking as unread.
 * 4. Register Customer 2 with unique email, nickname, phone, etc. (will obtain its own Authorization header).
 * 5. Use Customer 2 session (with its own JWT in connection) to attempt retrieving the notification by ID.
 * 6. Validate that an error is returned (access denied or not-found). Use TestValidator.error without asserting error codes or message, per requirements.
 * 7. Confirm that no data is leaked in the error case.
 */
export async function test_api_favorite_notification_detail_access_denied_wrong_owner(connection: api.IConnection) {
  // 1. Register Customer 1
  const customer1Email = typia.random<string & tags.Format<"email">>();
  const customer1Nickname = RandomGenerator.alphabets(8);
  const customer1Phone = RandomGenerator.mobile();
  const customer1Signup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer1Email,
      password: "passw0rd!",
      name: RandomGenerator.name(),
      nickname: customer1Nickname,
      phone: customer1Phone,
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customer1Signup);
  const customer1Id = customer1Signup.customer.id;

  // Set authorization for Customer 1 for future operations
  // (signUp returns the auth token directly)
  connection.headers.Authorization = customer1Signup.setHeaders.Authorization;

  // 2. Customer 1 creates a favorite product
  const productId = typia.random<string & tags.Format<"uuid">>();
  const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: { product_id: productId } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate,
  });
  typia.assert(favoriteProduct);

  // 3. Customer 1 creates a favorite notification for this favorite product
  const notification = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, {
    body: {
      favorite_product_id: favoriteProduct.id,
      favorite_inquiry_id: null,
      favorite_address_id: null,
      notification_type: "PRICE_DROP",
      notification_channel: "EMAIL",
      read: false,
      delivery_metadata: null,
    } satisfies IShoppingMallAiBackendFavoriteNotification.ICreate,
  });
  typia.assert(notification);
  const notificationId = notification.id as string & tags.Format<"uuid">;

  // 4. Register Customer 2
  const customer2Email = typia.random<string & tags.Format<"email">>();
  const customer2Nickname = RandomGenerator.alphabets(8);
  const customer2Phone = RandomGenerator.mobile();
  const customer2Signup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer2Email,
      password: "diffpass1!",
      name: RandomGenerator.name(),
      nickname: customer2Nickname,
      phone: customer2Phone,
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customer2Signup);

  // Set authorization for Customer 2 (for isolation, show cross-user)
  connection.headers.Authorization = customer2Signup.setHeaders.Authorization;

  // 5. Attempt to access Customer 1's notification as Customer 2 — should be denied
  await TestValidator.error("access denied for wrong owner")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteNotifications.at(connection, {
      favoriteNotificationId: notificationId,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates that admin cannot update immutable or locked mileage transactions via the admin API.
 *
 * This test ensures that attempts to change immutable fields (such as transaction_type or mileage_amount) are rejected, and only permitted fields (like transaction_reason) can be edited. Attempts to modify immutable fields must result in an error, and the mutable field edit must succeed. Unimplementable aspects (transaction locking/finalization and transaction re-fetch) are omitted due to API limitations.
 *
 * Test Workflow:
 * 1. Register an admin and get session.
 * 2. Admin creates a mileage wallet for a sample customer.
 * 3. Admin creates a mileage transaction for this wallet.
 * 4. Attempt to update immutable fields (not possible by schema; demonstrate business rule with negative test).
 * 5. Attempt to update the allowed field (transaction_reason) and expect success.
 * 6. (Omitted: Trying to lock/finalize transaction or reloading status, as no such API exists.)
 */
export async function test_api_mileage_transaction_update_invalid_admin_attempt(
  connection: api.IConnection
) {
  // 1. Register admin to enable admin-only endpoints
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongPassword123!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAuth);

  // 2. Create a mileage wallet for a random customer
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      wallet_program: "brand",
      wallet_status: "active",
    } satisfies IShoppingMallAiBackendMileageWallet.ICreate,
  });
  typia.assert(wallet);

  // 3. Create a new mileage transaction on this wallet
  const transaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(connection, {
    mileageWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      transaction_type: "accumulate",
      mileage_amount: 500,
      reference_id: null,
      transaction_reason: "Initial points awarded",
    } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
  });
  typia.assert(transaction);

  // 4. Attempt to update immutable fields (schema does not allow fields except transaction_reason). Only id and transaction_reason can be set.
  // Business logic: If the admin tries to update something forbidden, the SDK/typescript will not allow extra fields.
  // To simulate, we only test that only allowed field works, and that error is thrown for TS-allowed field that fails business logic.

  // 5. Attempt error case: supply ID only (should be a no-op or error, as transaction_reason missing is allowed but does not change any data)
  const updateAttempt = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.update(connection, {
    mileageWalletId: wallet.id,
    mileageTransactionId: transaction.id,
    body: {
      id: transaction.id,
    } satisfies IShoppingMallAiBackendMileageTransaction.IUpdate,
  });
  typia.assert(updateAttempt);
  TestValidator.equals("transaction fields unchanged")(updateAttempt)(expect.objectContaining({
    transaction_type: transaction.transaction_type,
    mileage_amount: transaction.mileage_amount,
  }));

  // 6. Attempt positive case: update transaction_reason
  const updatedTransaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.update(connection, {
    mileageWalletId: wallet.id,
    mileageTransactionId: transaction.id,
    body: {
      id: transaction.id,
      transaction_reason: "Admin updated reason",
    } satisfies IShoppingMallAiBackendMileageTransaction.IUpdate,
  });
  typia.assert(updatedTransaction);
  TestValidator.equals("transaction_reason updated")(updatedTransaction.transaction_reason)("Admin updated reason");
  TestValidator.equals("amount stays unchanged")(updatedTransaction.mileage_amount)(transaction.mileage_amount);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartSnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that an admin can retrieve any cart snapshot for any customer using GET, and proper error handling for invalid access and IDs.
 *
 * This test covers the following business scenario:
 * 1. Register a new customer, create a shopping cart as that customer.
 * 2. Create a cart snapshot for audit trail purposes.
 * 3. Register a new admin account and switch the authorization context to the admin.
 * 4. Fetch the snapshot as the admin and verify all returned fields for integrity, compliance, and auditability.
 * 5. Attempt unauthorized admin access (invalid JWT) and expect error.
 * 6. Attempt fetching a non-existent cartSnapshotId and expect error.
 *
 * Test ensures admin access control works, all snapshot fields return correctly,
 * and both permission and not-found error logic is enforced.
 */
export async function test_api_cart_snapshot_admin_access_detail(connection: api.IConnection) {
  // Step 1: Register customer
  const customerSignup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Cust0mer!" + typia.random<string>(),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignup);
  const customerJwt = customerSignup.setHeaders.Authorization;

  // Step 2: As customer, create cart
  // Connection context should now have JWT for this customer
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    },
  });
  typia.assert(cart);
  const cartId = cart.id;

  // Step 3: As customer, create cart snapshot
  const snapshotInput: api.IShoppingMallAiBackendCartSnapshot.ICreate = {
    cart_id: cartId,
    snapshot_json: JSON.stringify(cart),
    snapshot_reason: "manual",
  };
  const snapshot = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.create(connection, {
    cartId,
    body: snapshotInput,
  });
  typia.assert(snapshot);
  const cartSnapshotId = snapshot.id;

  // Step 4: Register admin (switch to admin - keep new Authorization header)
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Adm1n!" + typia.random<string>(),
    },
  });
  typia.assert(adminSignUp);
  const prevJwt = connection.headers.Authorization;
  connection.headers.Authorization = adminSignUp.setHeaders.Authorization;

  // Step 5: As admin, fetch the cart snapshot detail for compliance
  const fetched = await api.functional.shoppingMallAiBackend.admin.carts.cartSnapshots.at(connection, {
    cartId,
    cartSnapshotId,
  });
  typia.assert(fetched);
  TestValidator.equals("cart snapshot ID matches")(fetched.id)(cartSnapshotId);
  TestValidator.equals("cart ID matches")(fetched.cart_id)(cartId);
  TestValidator.equals("snapshot_json matches original cart")(fetched.snapshot_json)(snapshotInput.snapshot_json);
  TestValidator.equals("snapshot_reason matches")(fetched.snapshot_reason)(snapshotInput.snapshot_reason);
  TestValidator.predicate("created_at is ISO date-time")(!!Date.parse(fetched.created_at));

  // Step 6: Attempt to fetch with invalid admin JWT - should fail
  connection.headers.Authorization = "Bearer invalidtoken";
  await TestValidator.error("unauthorized admin fetch fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.carts.cartSnapshots.at(connection, {
      cartId,
      cartSnapshotId,
    });
  });

  // Step 7: Attempt to fetch with non-existent cartSnapshotId - should 404/error
  connection.headers.Authorization = adminSignUp.setHeaders.Authorization; // restore valid admin JWT
  const bogusId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found error for missing snapshotId")(async () => {
    await api.functional.shoppingMallAiBackend.admin.carts.cartSnapshots.at(connection, {
      cartId,
      cartSnapshotId: bogusId,
    });
  });

  // Restore headers
  connection.headers.Authorization = prevJwt;
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerExternalLink } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerExternalLink";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test validation failures for customer external link update.
 *
 * This test covers cases where a customer attempts to update an external OAuth/social login link with invalid or malformed payloads. 
 * Scenarios include: missing required fields, illegal provider, invalid UUID/date-time, malformed external_id fields, and corrupted metadata_json.
 *
 * Steps:
 * 1. Register a new customer (via signUp) for testing.
 * 2. Attach an initial valid external link so updates have existing target.
 * 3. Attempt updates with: missing required id, illegal provider, invalid UUID, empty or corrupt fields, bad JSON, or multiple faulty properties.
 * 4. For each, expect an API error response and proper handling (not a successful update).
 *
 * This test ensures strict DTO contract enforcement and correct input validation for external link management.
 */
export async function test_api_customer_external_link_update_validation_failure(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const customerSignUp = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "TestPwd1!@#",
        name: RandomGenerator.name(),
        nickname: RandomGenerator.alphaNumeric(8),
        phone: RandomGenerator.mobile(),
      },
    },
  );
  typia.assert(customerSignUp);
  const customer = customerSignUp.customer;
  TestValidator.equals("customer id echoed")(customer.id)(customer.id);

  // 2. Attach a valid external link for negative test base
  const linkId = typia.random<string & tags.Format<"uuid">>();
  const provider = "google";
  const externalId = RandomGenerator.alphaNumeric(18);
  const now = new Date().toISOString();
  const externalLink = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
    connection,
    {
      customerId: customer.id,
      body: {
        id: linkId,
        provider,
        external_id: externalId,
        linked_at: now,
        last_auth_at: now,
        metadata_json: '{"verified":true}',
        deleted_at: null,
      },
    },
  );
  typia.assert(externalLink);
  TestValidator.equals("init link id")(externalLink.id)(linkId);

  // 3a: Missing required id field (should error)
  await TestValidator.error("missing id on update fails")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          provider,
          external_id: externalId,
        } as any, // Deliberately invalid for runtime error only
      },
    );
  });

  // 3b: Illegal provider value
  await TestValidator.error("illegal provider")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          id: linkId,
          provider: "!not_a_known_provider!",
          external_id: RandomGenerator.alphaNumeric(16),
        },
      },
    );
  });

  // 3c: Invalid UUID for id
  await TestValidator.error("invalid uuid")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          id: "foobar-uuid",
          provider,
          external_id: RandomGenerator.alphaNumeric(10),
        },
      },
    );
  });

  // 3d: Empty external_id is not valid
  await TestValidator.error("empty external_id")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          id: linkId,
          provider,
          external_id: "",
        },
      },
    );
  });

  // 3e: Invalid metadata_json (not JSON string)
  await TestValidator.error("corrupt metadata_json")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          id: linkId,
          provider,
          external_id: RandomGenerator.alphaNumeric(10),
          metadata_json: "not-json",
        },
      },
    );
  });

  // 3f: Multiple problems at once
  await TestValidator.error("many issues at once")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          id: "bad",
          provider: "invalid!",
          external_id: "",
          linked_at: "nope",
          last_auth_at: "nope",
          metadata_json: "!!!",
          deleted_at: "nope",
        },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerExternalLink } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerExternalLink";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test that an admin can soft-delete a customer's external authentication link (social/OAuth connector), and that all business rule requirements of soft deletion and audit are honored.
 *
 * This test covers the entire workflow:
 * 1. Register a new admin and authenticate the API session. (Admin registration also returns Authorization JWT, which is set in connection.headers.)
 * 2. Register a new customer via customer signup and get the created customer id.
 * 3. Attach a new external authentication link (e.g., social/OAuth) to the customer with a known provider/external_id pair.
 * 4. As admin, call DELETE /shoppingMallAiBackend/admin/customers/{customerId}/externalLinks/{externalLinkId} to soft-delete the external link. No response body is expected (void return), so follow-up GET cannot be called directly (since not exposed), but updating (PUT) or further deletions can be tested for error/idempotence.
 * 5. Confirm via update/PUT that the deleted link's deleted_at is set (that is, updating or linking with the same id should show deleted_at property is non-null). Attempting to delete again should yield error or no-op response (verify with TestValidator.error or TestValidator.predicate on behavior).
 *
 * Validates:
 * - Only admin can perform soft-delete, and the operation sets deleted_at (logical deletion, not physical)
 * - After deletion, link is not available for normal non-admin updates, and evidence of the soft-deleted state exists
 * - Repeated deletion is idempotent or returns an appropriate business logic error
 */
export async function test_api_admin_external_link_soft_delete_success(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword!123";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);

  // Admin registration sets Authorization JWT in connection

  // 2. Register a customer
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerPassword = "CustomerPW!456";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: "Test User",
