/**
 * Validate the end-to-end customer appeal creation process for a moderation event.
 *
 * This test simulates a customer registering, a moderation event being triggered (as would occur if their content was moderated), and then submitting an appeal against that moderation event. The test verifies proper appeal creation, required status, traceability, and demonstrates correct error handling for duplicate and invalid appeals.
 *
 * Steps:
 * 1. Customer registration/sign-up
 * 2. Admin triggers a moderation event (manually, as the e2e test cannot actually block real content)
 * 3. Customer submits an appeal on the moderation event
 * 4. Validate the created appeal's correctness (links, initial status, trace, timestamps)
 * 5. Attempt duplicate appeal (expect error)
 * 6. Attempt appeal on non-existent moderation event (expect error)
 */
export async function test_api_appeal_creation_success_workflow(connection: api.IConnection) {
  // 1. Customer registers and is authenticated
  const customerSignup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password!234",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignup);
  const customer = customerSignup.customer;

  // 2. Admin creates a moderation event (for customer's resource)
  const moderationEvent = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
    body: {
      // For this synthetic case, block a "fake" review by the customer
      actor_id: customer.id,
      event_type: "block",
      reason: "Test e2e trigger - blocking for simulation",
      // Target either an inquiry OR a review; here, synthesize a review UUID
      target_inquiry_id: null,
      target_review_id: typia.random<string & tags.Format<"uuid">>(),
      attached_ai_evidence_id: null,
      referenced_event_id: null,
    },
  });
  typia.assert(moderationEvent);

  // 3. Customer files an appeal for the moderation event
  const appealInput = {
    moderation_event_id: moderationEvent.id,
    appellant_id: customer.id,
    status: "pending",
    decision_comment: null,
  };
  const appeal = await api.functional.shoppingMallAiBackend.customer.appeals.create(connection, {
    body: appealInput,
  });
  typia.assert(appeal);

  // 4. Verify fields: linkage, status, timestamps, audit
  TestValidator.equals("moderation_event_id link")(appeal.moderation_event_id)(moderationEvent.id);
  TestValidator.equals("appellant_id link")(appeal.appellant_id)(customer.id);
  TestValidator.equals("initial status")(appeal.status)("pending");
  TestValidator.equals("decision_comment is null")(appeal.decision_comment)(null);

  // 5. Duplicate appeal (expect error)
  await TestValidator.error("duplicate appeal should fail")(async () => {
    await api.functional.shoppingMallAiBackend.customer.appeals.create(connection, {
      body: appealInput,
    });
  });

  // 6. Appeal to non-existent moderation event (expect error)
  await TestValidator.error("invalid moderation_event_id should fail")(async () => {
    await api.functional.shoppingMallAiBackend.customer.appeals.create(connection, {
      body: {
        moderation_event_id: typia.random<string & tags.Format<"uuid">>(),
        appellant_id: customer.id,
        status: "pending",
        decision_comment: null,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import type { IShoppingMallAiBackendCoinSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinSnapshot";

/**
 * Validate updating metadata and compliance/documentation fields of coin wallet snapshots by admin.
 *
 * This test verifies that an admin can update allowed metadata fields (wallet_label, security_code, snapshot_reason) on a coin wallet snapshot and see changes reflected. It also checks that attempts to update immutable fields are rejected, and that proper errors are returned for non-existent resources.
 *
 * Steps:
 * 1. Provision a coin wallet as admin and obtain the wallet ID.
 * 2. Create a snapshot for this wallet and obtain the snapshot ID.
 * 3. Update only allowed metadata fields (wallet_label, security_code, snapshot_reason) and verify results.
 * 4. Attempt to update immutable/banned fields (wallet_address, snapshot_balance); ensure validation fails (not allowed via DTO; triggers error if attempted by type bypass).
 * 5. Attempt to update a non-existent snapshot or a snapshot of a non-existent wallet, and expect an error.
 * 6. (Unauthorized user scenario skipped: only admin APIs available.)
 */
export async function test_api_coin_wallet_snapshot_update_metadata_and_compliance(connection: api.IConnection) {
  // 1. Create a coin wallet
  const wallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_type: "event",
      wallet_status: "active",
      wallet_address: typia.random<string & tags.Format<"uuid">>(),
      wallet_label: "For event prize",
      security_code: "1234",
      wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>()
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate
  });
  typia.assert(wallet);

  // 2. Create a coin wallet snapshot
  const now = new Date().toISOString();
  const snapshot = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.create(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      wallet_type: wallet.wallet_type,
      wallet_status: wallet.wallet_status,
      wallet_address: wallet.wallet_address,
      owner_admin_id: wallet.wallet_owner_admin_id,
      snapshot_balance: 1000,
      snapshot_reason: "Initial event funds loaded",
      snapshot_at: now,
      created_at: now,
      wallet_label: wallet.wallet_label,
      security_code: wallet.security_code
    } satisfies IShoppingMallAiBackendCoinSnapshot.ICreate
  });
  typia.assert(snapshot);

  // 3. Update allowed metadata: wallet_label, security_code, snapshot_reason
  const newLabel = "Updated by compliance test";
  const newReason = "Annotation for compliance update.";
  const newSecurity = "5678";
  const updated = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.update(connection, {
    coinWalletId: wallet.id,
    coinSnapshotId: snapshot.id,
    body: {
      wallet_label: newLabel,
      snapshot_reason: newReason,
      security_code: newSecurity
    } satisfies IShoppingMallAiBackendCoinSnapshot.IUpdate
  });
  typia.assert(updated);
  TestValidator.equals("wallet_label updated")(updated.wallet_label)(newLabel);
  TestValidator.equals("snapshot_reason updated")(updated.snapshot_reason)(newReason);
  TestValidator.equals("security_code updated")(updated.security_code)(newSecurity);
  // Fields not updated should remain
  TestValidator.equals("wallet_address unchanged")(updated.wallet_address)(snapshot.wallet_address);
  TestValidator.equals("snapshot_balance unchanged")(updated.snapshot_balance)(snapshot.snapshot_balance);

  // 4. Attempt to update immutable fields (not accepted by DTO) via forced bypass (should error)
  await TestValidator.error("immutable field update rejected")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.update(connection, {
      coinWalletId: wallet.id,
      coinSnapshotId: snapshot.id,
      body: {
        // The following fields are not allowed by DTO and will cause an error if forced
        wallet_address: typia.random<string>(),
        snapshot_balance: 9999,
        wallet_label: "should not work"
      } as any
    });
  });

  // 5. Attempt to update a non-existent snapshot
  await TestValidator.error("update non-existent snapshot fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.update(connection, {
      coinWalletId: wallet.id,
      coinSnapshotId: typia.random<string & tags.Format<"uuid">>(),
      body: { wallet_label: "irrelevant" }
    });
  });

  // 5b. Snapshot for a non-existent wallet
  await TestValidator.error("update with non-existent wallet fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.update(connection, {
      coinWalletId: typia.random<string & tags.Format<"uuid">>(),
      coinSnapshotId: snapshot.id,
      body: { wallet_label: "irrelevant" }
    });
  });

  // 6. Skipped: Unauthorized user not testable (only admin API available)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates admin audit access to full product inquiry detail.
 *
 * Ensures that an admin can: (1) register, (2) product and inquiry are created, and (3) the admin retrieves all fields from a product inquiry regardless of ownership for audit and compliance. Checks all main and audit fields (AI scoring, status, public flag, answer reference, timestamps, customer/product IDs).
 *
 * 1. Register an admin to get admin access.
 * 2. Register a seller (used to create a product).
 * 3. Register a customer (who will later submit the inquiry).
 * 4. As the seller, register a product to be inquired about.
 * 5. As the customer, create a product inquiry on that product.
 * 6. Switch to admin context and fetch the inquiry by its ID using admin endpoint.
 * 7. Assert that all fields returned match the created inquiry, and critical audit/AI/status fields are present and populated as expected.
 */
export async function test_api_admin_product_inquiry_detail_audit_access(connection: api.IConnection) {
  // 1. Register admin (for audit access)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin!1234";
  const adminRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminRes);

  // 2. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Seller!1234";
  const sellerRes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: "AutoTest Seller",
      businessNumber: `${typia.random<string>().slice(0,10)}`,
      representativeName: "Test Owner",
      address: "123 AutoTest St, TestCity",
      phone: "01012345678"
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerRes);
  const sellerId = sellerRes.sellerId;

  // 3. Register customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Customer!1234";
  const customerRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: "AutoTest Customer",
      nickname: "auto_cust",
      phone: "01087654321",
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerRes);
  const customerId = customerRes.customer.id;

  // 4. Seller creates product
  // Use the seller's JWT for authentication
  connection.headers["Authorization"] = sellerRes.setHeaders.Authorization;
  const productCode = `SKU-${typia.random<string>().slice(0,8)}`;
  const productRes = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: "Test Product For Inquiry",
      description: "Description for audit test product.",
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productRes);
  const productId = productRes.id;

  // 5. Customer creates inquiry on the product
  // Switch to customer JWT
  connection.headers["Authorization"] = customerRes.setHeaders.Authorization;
  const inquiryTitle = "Test Inquiry For Audit";
  const inquiryBody = "Does this product support audit logging?";
  const inquiryRes = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: productId,
      title: inquiryTitle,
      body: inquiryBody,
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
  });
  typia.assert(inquiryRes);
  const inquiryId = inquiryRes.id;

  // 6. Admin retrieves the inquiry by ID for audit
  // Switch back to admin JWT
  connection.headers["Authorization"] = adminRes.setHeaders.Authorization;
  const got = await api.functional.shoppingMallAiBackend.admin.productInquiries.at(connection, {
    productInquiryId: inquiryId,
  });
  typia.assert(got);

  // 7. Validate all key fields match and audit/Ai/status fields are present
  TestValidator.equals("customer_id")(got.customer_id)(customerId);
  TestValidator.equals("product_id")(got.product_id)(productId);
  TestValidator.equals("title")(got.title)(inquiryTitle);
  TestValidator.equals("body")(got.body)(inquiryBody);
  TestValidator.equals("public")(got.public)(true);
  // Audit/status/AI fields should be present (not necessarily non-null for AI fields)
  TestValidator.equals("status is string")(typeof got.status)("string");
  TestValidator.equals("created_at is ISO date")(!!Date.parse(got.created_at))(true);
  TestValidator.equals("updated_at is ISO date")(!!Date.parse(got.updated_at))(true);
  // AI fields: nullable, but key exists
  TestValidator.predicate("ai_sentiment_score key exists")("ai_sentiment_score" in got);
  TestValidator.predicate("ai_spam_score key exists")("ai_spam_score" in got);
  // answer_id and deleted_at are optional (nullable)
  TestValidator.predicate("answer_id key exists")("answer_id" in got);
  TestValidator.predicate("deleted_at key exists")("deleted_at" in got);
}

