import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates that a seller cannot update a product inquiry for a product they do not own.
 *
 * This test ensures business logic enforcement around seller permissions: specifically,
 * that only the seller who owns the product related to an inquiry can update that inquiry.
 * An unauthorized seller must receive a permission error, and the state of the inquiry
 * must remain unchanged.
 *
 * Steps:
 * 1. Register seller A (the owner of the product).
 * 2. Register seller B (the unauthorized seller).
 * 3. Register a customer.
 * 4. Seller A creates a product.
 * 5. Customer submits an inquiry on the product.
 * 6. Seller B (not the owner) attempts to update the inquiry (status or body).
 * 7. Assert that permission is denied (error is thrown, no update).
 * 8. Verify the inquiry is unchanged (no direct GET for customer/seller, so best-effort: if update failed, state should be unchanged)
 */
export async function test_api_seller_product_inquiry_update_forbidden_not_owner(connection: api.IConnection) {
  // 1. Register seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAPassword = "Test1234!";
  const sellerARes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile()
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(sellerARes);
  const sellerAId = sellerARes.sellerId;

  // 2. Register seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBPassword = "Test1234!";
  const sellerBRes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: sellerBPassword,
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile()
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(sellerBRes);

  // 3. Register a customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Test1234!";
  const customerRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerRes);
  const customerId = customerRes.customer.id;

  // 4. Seller A creates a product
  connection.headers.Authorization = sellerARes.setHeaders.Authorization;
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(3),
      main_image_uri: null,
      status: "published"
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 5. Customer submits inquiry on product
  connection.headers.Authorization = customerRes.setHeaders.Authorization;
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: product.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(2),
      public: true
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate
  });
  typia.assert(inquiry);

  // 6. Seller B attempts to update the inquiry
  connection.headers.Authorization = sellerBRes.setHeaders.Authorization;
  const updateInput: IShoppingMallAiBackendProductInquiry.IUpdate = {
    title: "Malicious Edit By Unauthorized Seller",
    body: "Shouldn't be able to update this inquiry.",
    status: "answered"
  };

  // 7. Expect error due to lack of permission
  await TestValidator.error("forbidden inquiry update by not-owner seller")(async () => {
    await api.functional.shoppingMallAiBackend.seller.productInquiries.update(connection, {
      productInquiryId: inquiry.id,
      body: updateInput
    });
  });

  // 8. Verify the inquiry is unchanged (no direct GET for customer/seller, so best-effort: if update failed, state should be unchanged)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate seller updating their product option information.
 *
 * This test ensures a seller can update one of their own product option entries on the platform, modifying fields such as SKU, option name, values, additional price, and status. This covers the normal product option update workflow for e-commerce product management.
 *
 * Steps:
 * 1. Register a new seller and obtain authentication.
 * 2. Log the seller in to ensure proper credentials and obtain latest JWT.
 * 3. Create a new product as that seller.
 * 4. Add an option to this product.
 * 5. Update the product option: change SKU, option_name, option_values, extra_price, and status. 
 * 6. Assert that the updated option data reflects all the new values. 
 */
export async function test_api_seller_update_product_option_success(connection: api.IConnection) {
  // 1. Register and authenticate seller
  const signUpInput: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "ValidPass123!",
    companyName: RandomGenerator.name(),
    businessNumber:
      "" +
      typia.random<
        number & tags.Format<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>
      >(),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  };
  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: signUpInput,
  });
  typia.assert(signUpResp);

  // 2. Login seller for new auth token
  const signInResp = await api.functional.auth.seller.login.signIn(connection, {
    body: { email: signUpInput.email, password: signUpInput.password },
  });
  typia.assert(signInResp);

  // 3. Create product for this seller
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: signUpResp.sellerId,
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    main_image_uri: null,
    status: "active",
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: productInput,
  });
  typia.assert(product);

  // 4. Create product option under this product
  const optionCreateInput: IShoppingMallAiBackendProductOption.ICreate = {
    product_id: product.id,
    sku: RandomGenerator.alphaNumeric(9),
    option_name: "Size",
    option_values: "S|M|L",
    extra_price: 570,
    main_image_uri: null,
    status: "active",
  };
  const option = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(
    connection,
    { productId: product.id, body: optionCreateInput }
  );
  typia.assert(option);

  // 5. Update the product option (SKU, option_name, values, extra_price, status)
  const updateInput: IShoppingMallAiBackendProductOption.IUpdate = {
    sku: RandomGenerator.alphaNumeric(12),
    option_name: "Color",
    option_values: "Red|Blue|Green",
    extra_price: 820,
    status: "inactive",
  };
  const updated = await api.functional.shoppingMallAiBackend.seller.products.productOptions.update(
    connection,
    { productId: product.id, productOptionId: option.id, body: updateInput }
  );
  typia.assert(updated);

  // 6. Assert all updated values present in the new option data
  TestValidator.equals("updated sku")(updated.sku)(updateInput.sku);
  TestValidator.equals("updated option_name")(updated.option_name)(updateInput.option_name);
  TestValidator.equals("updated option_values")(updated.option_values)(updateInput.option_values);
  TestValidator.equals("updated extra_price")(updated.extra_price)(updateInput.extra_price);
  TestValidator.equals("updated status")(updated.status)(updateInput.status);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Verify that unauthorized sellers cannot update product options belonging to products they do not own.
 *
 * Business context:
 *  - The API must ensure that only the owner (seller) of a product or an authorized admin can update its product options.
 *  - This prevents cross-tenant/multi-seller manipulation and enforces strict RBAC/ownership policy.
 *
 * Test steps and validation:
 * 1. Register seller A, who will own the product and its option.
 * 2. Authenticate as seller A.
 * 3. Seller A creates a product.
 * 4. Seller A registers an option for their own product.
 * 5. Register seller B, who will attempt unauthorized access.
 * 6. Authenticate as seller B (should have no access to seller A's resources).
 * 7. As seller B, attempt to update seller A's product option via PUT.
 * 8. Confirm that the API throws an error (authorization failure), validating that RBAC enforcement works and seller B cannot update resources they do not own.
 *
 * This test verifies backend security and RBAC/ownership enforcement for product option updates.
 */
export async function test_api_seller_update_product_option_unauthorized_access(connection: api.IConnection) {
  // 1. Register seller A (owner of product/option)
  const sellerA_email = typia.random<string & tags.Format<"email">>();
  const sellerA_password = "Password123!";
  const sellerARegistration = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerA_email,
      password: sellerA_password,
      companyName: RandomGenerator.company(),
      businessNumber: RandomGenerator.alphabets(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(15),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerARegistration);

  // 2. Authenticate seller A to obtain their session JWT
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerA_email,
      password: sellerA_password,
    } satisfies ISellerAuth.SignIn,
  });

  // 3. Seller A creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerARegistration.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.content()()() ?? null,
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 4. Seller A creates a product option
  const productOption = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: RandomGenerator.alphaNumeric(8),
      option_name: RandomGenerator.name(),
      option_values: null,
      extra_price: null,
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProductOption.ICreate,
  });
  typia.assert(productOption);

  // 5. Register seller B (not owner)
  const sellerB_email = typia.random<string & tags.Format<"email">>();
  const sellerB_password = "Password123!";
  const sellerBRegistration = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerB_email,
      password: sellerB_password,
      companyName: RandomGenerator.company(),
      businessNumber: RandomGenerator.alphabets(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(15),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerBRegistration);

  // 6. Authenticate seller B for unauthorized update attempt
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerB_email,
      password: sellerB_password,
    } satisfies ISellerAuth.SignIn,
  });

  // 7. Seller B attempts to update seller A's product option: must fail
  await TestValidator.error("seller B cannot update another seller's product option")(
    () =>
      api.functional.shoppingMallAiBackend.seller.products.productOptions.update(connection, {
        productId: product.id,
        productOptionId: productOption.id,
        body: {
          option_name: RandomGenerator.name(),
        } satisfies IShoppingMallAiBackendProductOption.IUpdate,
      }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Verify that unauthorized users (seller or anonymous) cannot update product options via the admin endpoint.
 *
 * This test enforces strong RBAC (role-based access control) and compliance
 * by asserting:
 *   1. A logged-in seller is denied access to the admin product option
 *      update API (PUT /shoppingMallAiBackend/admin/products/{productId}/productOptions/{productOptionId})
 *   2. An anonymous (unauthenticated) user is denied access as well.
 *
 * Steps:
 * 1. Register a new seller account (for negative role enforcement).
 * 2. Log in to obtain seller authentication.
 * 3. Attempt to update a product option with seller credentials; expect an authorization error.
 * 4. Attempt the same request with no authentication (anonymous); expect an authorization error.
 *
 * This test does not attempt successful update as admin or real-product modifications; only negative scenarios are validated.
 */
export async function test_api_admin_update_product_option_unauthorized(
  connection: api.IConnection,
) {
  // 1. Register a new seller for negative access test
  const email = typia.random<string & tags.Format<"email">>();
  const password = "Test1234!";
  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email,
      password,
      companyName: "RBAC Test Seller",
      businessNumber: "1234567890",
      representativeName: "Test Owner",
      address: "1 Test Lane, Seoul",
      phone: "010-1234-5678",
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Authenticate as seller to set JWT context
  const signInResp = await api.functional.auth.seller.login.signIn(connection, {
    body: { email, password } satisfies ISellerAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Attempt to call admin update as seller
  await TestValidator.error("seller forbidden on admin endpoint")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productOptions.update(connection, {
      productId: typia.random<string & tags.Format<"uuid">>(),
      productOptionId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        sku: "NEW-SKU-S1",
        option_name: "XL",
        status: "active",
      } satisfies IShoppingMallAiBackendProductOption.IUpdate,
    });
  });

  // 4. Attempt to call admin update as anonymous (no authentication)
  const anonConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("anonymous forbidden on admin endpoint")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productOptions.update(anonConnection, {
      productId: typia.random<string & tags.Format<"uuid">>(),
      productOptionId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        sku: "NEW-SKU-A1",
        option_name: "Red",
        status: "active",
      } satisfies IShoppingMallAiBackendProductOption.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import type { IPageIShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendMileageTransaction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates admin paginated & filtered search of mileage transactions in a mileage wallet.
 *
 * This test ensures that:
 * - Admin can create a mileage wallet for a test customer.
 * - Admin can add multiple transactions (accrual, redeem, correction, etc) to the wallet successfully.
 * - Admin can view all transactions using PATCH /shoppingMallAiBackend/admin/mileageWallets/{mileageWalletId}/mileageTransactions, unfiltered and with filters (type, amount, date) with proper pagination.
 * - Filters for transaction type, amount range, and date work as expected, returning only matching transactions.
 * - The list returned is paginated and each page contains the expected number of records.
 * - All inserted transaction types are visible and searchable by type.
 *
 * Test Steps:
 * 1. Admin creates a test customer_id (random UUID)
 * 2. Admin creates a mileage wallet for this customer
 * 3. Admin adds multiple transactions of various types ("accumulate", "redeem", "correction") with different amounts and dates
 * 4. Admin searches all transactions (unfiltered), checks that all data is present
 * 5. For each transaction type, filters by type and asserts only type-matching entries are returned
 * 6. Filters by min/max amount and by date to verify results are correct
 * 7. Asserts pagination (first page, page size, total records, total pages, etc.)
 * 8. Verifies that all admin operations succeed and data integrity is preserved
 */
export async function test_api_mileage_transaction_search_admin_scope(connection: api.IConnection) {
  // 1. Create a random customer ID
  const customerId = typia.random<string & tags.Format<"uuid">>();

  // 2. Admin creates the mileage wallet
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: customerId,
      wallet_program: "brand",
      wallet_status: "active",
      wallet_label: "Test Wallet",
      security_code: null,
    },
  });
  typia.assert(wallet);

  // 3. Admin creates multiple transactions of different types and values, with different creation dates
  const types = ["accumulate", "redeem", "correction"];
  const now = new Date();
  const transactions = [] as Array<
    Omit<import("api/structures/IShoppingMallAiBackendMileageTransaction").IShoppingMallAiBackendMileageTransaction, "created_at"> &
      { forced_type: string; forced_amount: number; forced_createdAt: string }
  >;
  for (let i = 0; i < 9; ++i) {
    const type = types[i % types.length];
    const amount = (i + 1) * 100 * (type === "redeem" ? -1 : 1); // redeem is negative
    // Simulate a different creation timestamp for each
    const createdAt = new Date(now.getTime() - i * 24 * 3600 * 1000).toISOString();
    const txn = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(connection, {
      mileageWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        transaction_type: type,
        mileage_amount: amount,
        reference_id: null,
        transaction_reason: `${type} test transaction`,
      },
    });
    typia.assert(txn);
    transactions.push({ ...txn, forced_type: type, forced_amount: amount, forced_createdAt: createdAt });
  }

  // 4. List all transactions with no filters
  let pageSize = 5;
  const unfiltered = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.search(connection, {
    mileageWalletId: wallet.id,
    body: {
      page: 1,
      page_size: pageSize,
    },
  });
  typia.assert(unfiltered);
  TestValidator.predicate("unfiltered data includes all stored txns")(
    unfiltered.pagination.records >= transactions.length
  );

  // 5. Filter by each transaction type; assert only that type returned
  for (const type of types) {
    const filtered = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.search(connection, {
      mileageWalletId: wallet.id,
      body: {
        transaction_type: type,
        page: 1,
        page_size: pageSize,
      },
    });
    typia.assert(filtered);
    TestValidator.predicate(`all txn are type ${type}`)(
      filtered.data.every(t => t.transaction_type === type)
    );
  }

  // 6. Filter by amount range
  const minAmount = 200, maxAmount = 600;
  const filteredByAmount = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.search(connection, {
    mileageWalletId: wallet.id,
    body: {
      min_amount: minAmount,
      max_amount: maxAmount,
      page: 1,
      page_size: pageSize,
    },
  });
  typia.assert(filteredByAmount);
  TestValidator.predicate("all txn amounts in range")(
    filteredByAmount.data.every(t => t.mileage_amount >= minAmount && t.mileage_amount <= maxAmount)
  );

  // 7. Filter by date (created_from, created_to; use one of known txn dates)
  const refDate = new Date(now.getTime() - 2 * 24 * 3600 * 1000).toISOString();
  const filteredByDate = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.search(connection, {
    mileageWalletId: wallet.id,
    body: {
      created_from: refDate,
      page: 1,
      page_size: pageSize,
    },
  });
  typia.assert(filteredByDate);
  TestValidator.predicate("all txn created_at >= refDate")(
    filteredByDate.data.every(t => t.created_at >= refDate)
  );

  // 8. Test pagination by requesting second page if enough records
  if (unfiltered.pagination.pages > 1) {
    const page2 = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.search(connection, {
      mileageWalletId: wallet.id,
      body: {
        page: 2,
        page_size: pageSize,
      },
    });
    typia.assert(page2);
    TestValidator.equals("current page==2")(page2.pagination.current)(2);
  }
}

