import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test validating immutability of order snapshot fields via admin API.
 *
 * This test ensures an admin cannot update immutable fields (such as snapshot_json or order_id) on an existing order snapshot.
 *
 * Business context:
 * - Order snapshots are immutable records that provide a forensic/audit trail for rollback/legal/dispute handling.
 * - Only the snapshot_reason field is allowed to be updated post-creation (as permitted by IUpdate schema), ensuring audit chain integrity.
 * - Server should reject any attempt (even via type-bypass) to mutate immutable fields.
 *
 * Test workflow:
 * 1. Register (and log in as) an admin for authentication
 * 2. Create a new order snapshot for a random order
 * 3. Update only the allowed field (snapshot_reason) and confirm change
 * 4. Attempt to update forbidden/immutable fields (snapshot_json, order_id) using a type bypass; expect a business/validation error
 */
export async function test_api_order_snapshot_update_attempt_on_immutable_fields_raises_error(connection: api.IConnection) {
  // Step 1: Register a new admin (dependency setup)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "test1234!";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);

  // Step 2: Create a new order snapshot for a random order
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const snapshotCreateBody = {
    snapshot_json: JSON.stringify({ item: "shoes", total: 120 } as Record<string, unknown>),
    snapshot_reason: "created", // valid reason
  } satisfies IShoppingMallAiBackendOrderSnapshot.ICreate;
  const snapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.create(connection, {
    orderId,
    body: snapshotCreateBody,
  });
  typia.assert(snapshot);
  TestValidator.equals("order id on snapshot")(snapshot.order_id)(orderId);

  // Step 3: Update only allowed field (snapshot_reason)
  const allowedUpdateReason = "qualified compliance edit";
  const allowedUpdate = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.update(connection, {
    orderId,
    orderSnapshotId: snapshot.id,
    body: { snapshot_reason: allowedUpdateReason } satisfies IShoppingMallAiBackendOrderSnapshot.IUpdate,
  });
  typia.assert(allowedUpdate);
  TestValidator.equals("allowed snapshot_reason update")(allowedUpdate.snapshot_reason)(allowedUpdateReason);
  TestValidator.equals("order id unchanged")(allowedUpdate.order_id)(orderId);
  TestValidator.equals("snapshot_json unchanged")(allowedUpdate.snapshot_json)(snapshot.snapshot_json);

  // Step 4: Attempt to update immutable fields (must fail at business logic layer)
  await TestValidator.error("should fail to mutate immutable fields")(
    async () => {
      // bypass type system intentionally for negative business test
      // @ts-expect-error
      await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.update(connection, {
        orderId,
        orderSnapshotId: snapshot.id,
        body: {
          snapshot_reason: "illegal mutation attempt",
          snapshot_json: "this should not be accepted", // not permitted by schema
          order_id: typia.random<string & tags.Format<"uuid">>(), // not updatable
        } as any,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { IPageIShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendInquirySnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Verify that a seller can retrieve a paginated and filtered list of inquiry snapshots for a product inquiry.
 *
 * This end-to-end test validates:
 * 1. Seller onboarding and product creation
 * 2. Product inquiry creation by a customer
 * 3. Inquiry snapshot creation (simulate history/events)
 * 4. Retrieval of snapshots with pagination, filters (actor, status, time, etc.), sorting
 * 5. Security: Only owner seller may access; others and unauthenticated should fail
 *
 * Step-by-step process:
 * 1. Register a seller and obtain JWT for authentication
 * 2. Register a product as that seller
 * 3. Simulate a customer and submit a product inquiry for that product
 * 4. Create multiple inquiry snapshots as seller, varying some fields/status for realistic test
 * 5. Retrieve snapshot list (PATCH) as seller with different filters/paging/sort
 * 6. Validate filter/sort/pagination logic is correctly reflected in results
 * 7. Validate only authorized (owning) seller can fetch; forbidden for non-owners/unauthenticated access
 */
export async function test_api_inquiry_snapshot_list_happy_path_pagination_filtering(connection: api.IConnection) {
  // 1. Register seller and authenticate
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const sellerReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "StrongPassw0rd!",
      companyName: "Test Company",
      businessNumber: "1000123456",
      representativeName: "Tester Seller",
      address: "123 Test Address, Test City",
      phone: "01012345678"
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerReg);
  const sellerId = sellerReg.sellerId;

  // Ensure connection is authenticated (JWT placed in headers automatically)

  // 2. Seller creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: `PROD-${Date.now()}`,
      name: "Test Product",
      description: "Product for inquiry snapshot testing",
      main_image_uri: null,
      status: "published" // as a simple published state
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);
  const productId = product.id;

  // 3. Simulate a customer inquiry (impersonate via random customer uuid for testing); in real usage this would be a separate auth flow
  const customerId: string = typia.random<string & tags.Format<"uuid">>();
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: productId,
      title: "Test Inquiry",
      body: "Inquiry about the product.",
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate
  });
  typia.assert(inquiry);
  const inquiryId = inquiry.id;

  // 4. Seller creates multiple inquiry snapshots (varying values)
  const snapshots: IShoppingMallAiBackendInquirySnapshot[] = [];
  const statSeq: Array<IShoppingMallAiBackendInquirySnapshot["status"]> = ["waiting", "answered", "blocked"];
  const now = new Date();
  for (let i = 0; i < 6; ++i) {
    const status = statSeq[i % statSeq.length];
    const changed_at = new Date(now.getTime() + i * 1000 * 60).toISOString(); // spaced by 1 minute
    const snap = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.create(connection, {
      productInquiryId: inquiryId,
      body: {
        inquiry_id: inquiryId,
        title: `Inquiry Title v${i + 1}`,
        body: `Edit ${i + 1} to inquiry body`,
        public: Boolean(i % 2),
        status,
        actor_id: sellerId,
        ai_sentiment_score: (i % 3 === 0) ? 0.5 : null,
        ai_spam_score: (i % 2 === 0) ? 0.2 : null,
        changed_at,
      } satisfies IShoppingMallAiBackendInquirySnapshot.ICreate
    });
    typia.assert(snap);
    snapshots.push(snap);
  }

  // 5a. Retrieve: all snapshots (no filter)
  let result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      // no filters here
    } satisfies IShoppingMallAiBackendInquirySnapshot.IRequest
  });
  typia.assert(result);
  TestValidator.equals("all snapshots count")(result.data.length)(snapshots.length);

  // 5b. Filter by actor_id (should match all as seller is creator of all)
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      actor_id: sellerId
    }
  });
  typia.assert(result);
  TestValidator.predicate("actor filtered count")(result.data.every(d => d.actor_id === sellerId));

  // 5c. Filter by status
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      status: "answered"
    }
  });
  typia.assert(result);
  TestValidator.predicate("status=answered")(result.data.every(d => d.status === "answered"));

  // 5d. Pagination: limit and page
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      limit: 2,
      page: 2
    }
  });
  typia.assert(result);
  TestValidator.equals("pagination meta limit")(result.pagination.limit)(2);
  TestValidator.equals("pagination meta page")(result.pagination.current)(2);
  TestValidator.predicate("pagination data max 2")((result.data.length <= 2));

  // 5e. Sort: changed_at desc/asc
  // Asc
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      sort_by: "changed_at",
      sort_direction: "asc"
    }
  });
  typia.assert(result);
  for (let i = 1; i < result.data.length; ++i) {
    TestValidator.predicate(`asc-sort order at ${i}`)(result.data[i].changed_at >= result.data[i - 1].changed_at);
  }
  // Desc
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      sort_by: "changed_at",
      sort_direction: "desc"
    }
  });
  typia.assert(result);
  for (let i = 1; i < result.data.length; ++i) {
    TestValidator.predicate(`desc-sort order at ${i}`)(result.data[i - 1].changed_at >= result.data[i].changed_at);
  }

  // 5f. Filter by date range (changed_at_from/to)
  // Use the time window from snapshot[2] to snapshot[4]
  const changed_at_from = snapshots[2].changed_at;
  const changed_at_to = snapshots[4].changed_at;
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      changed_at_from,
      changed_at_to
    }
  });
  typia.assert(result);
  TestValidator.predicate("date range filter")(
    result.data.every(d => d.changed_at >= changed_at_from && d.changed_at <= changed_at_to)
  );

  // 6. Security: only owning seller can fetch - test negative: no auth/JWT
  const unauthConn = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: undefined } };
  await TestValidator.error("unauthorized - no JWT")(() =>
    api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(unauthConn, {
      productInquiryId: inquiryId,
      body: {
        inquiry_id: inquiryId,
      }
    })
  );

  // 7. Security: seller who does not own the product
  const seller2Email: string = typia.random<string & tags.Format<"email">>();
  const seller2Reg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller2Email,
      password: "StrongPassw0rd!",
      companyName: "Test Company 2",
      businessNumber: "1000123457",
      representativeName: "Other Seller",
      address: "234 Second Address, City",
      phone: "01022334455"
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller2Reg);
  const conn2 = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: seller2Reg.setHeaders.Authorization } };
  await TestValidator.error("not owner seller forbidden")(() =>
    api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(conn2, {
      productInquiryId: inquiryId,
      body: { inquiry_id: inquiryId }
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { IPageIShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendInquirySnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test verifying admin can audit/search all inquiry snapshots: filter, paginate, enumerate events, and enforce security.
 *
 * Business context:
 * - Product inquiry snapshots form a regulatory evidence chain for all changes (content, status, actor)
 * - Admins must be able to view and filter the full change history for any inquiry
 *
 * Process:
 * 1. Admin registers and is authenticated (get adminId, JWT)
 * 2. A product inquiry is created by a customer (simulate IDs as customer reg is unavailable)
 * 3. Inquiry is mutated multiple times to accumulate at least three change events/snapshots
 * 4. Admin creates an additional manual snapshot for broader test coverage
 * 5. Admin searches/filters with PATCH: all, by actor_id, by status, paginates, sorts, date window
 * 6. Results validated for filter effectiveness and record inclusion
 * 7. Negative scenario: search as non-admin (no Authorization) yields error
 * 8. Negative scenario: malformed filter (missing required inquiry_id) yields error
 */
export async function test_api_inquiry_snapshot_admin_search_advanced_audit_evidence(
  connection: api.IConnection,
) {
  // 1. Register admin and get JWT/profile
  const adminInfo = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongP@ss1!",
    },
  });
  typia.assert(adminInfo);

  // 2. Simulate customer & product IDs and create product inquiry
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const productId = typia.random<string & tags.Format<"uuid">>();
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: productId,
      title: "How durable is this backpack?",
      body: "Is the seam waterproof and does it have an inner sleeve?",
      public: true,
    },
  });
  typia.assert(inquiry);

  // 3. Update inquiry multiple times (triggers snapshot creation)
  const updA = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      title: "How durable is this backpack? (edit A)",
      status: "waiting",
    },
  });
  typia.assert(updA);

  const updB = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      body: "Does it come in blue?",
      status: "answered",
    },
  });
  typia.assert(updB);

  const updC = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      public: false,
      status: "blocked",
    },
  });
  typia.assert(updC);

  // 4. As admin, manually snapshot the inquiry
  const nowIso = new Date().toISOString();
  const manualSnap = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.create(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      title: updC.title ?? updB.title ?? updA.title ?? inquiry.title,
      body: updC.body ?? updB.body ?? updA.body ?? inquiry.body,
      public: updC.public ?? updB.public ?? updA.public ?? inquiry.public,
      status: updC.status ?? updB.status ?? updA.status ?? inquiry.status,
      actor_id: adminInfo.adminId,
      changed_at: nowIso,
    },
  });
  typia.assert(manualSnap);

  // 5. As admin, search all snapshots for this inquiry (no filter)
  const allSnaps = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
    },
  });
  typia.assert(allSnaps);
  TestValidator.predicate("should have at least 4 snapshots")(allSnaps.data.length >= 4);
  TestValidator.predicate("should include admin-created snapshot")(
    allSnaps.data.some((s) => s.actor_id === adminInfo.adminId),
  );

  // 5b. Filter by actor_id (customer)
  const byCustomer = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      actor_id: customerId,
    },
  });
  typia.assert(byCustomer);
  TestValidator.predicate("should include only customer-written events")(
    byCustomer.data.every((s) => s.actor_id === customerId),
  );

  // 5c. Filter by status ('answered', which was set by updB)
  const byStatus = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      status: "answered",
    },
  });
  typia.assert(byStatus);
  TestValidator.predicate("should include at least one answered snapshot")(
    byStatus.data.some((s) => s.status === "answered"),
  );

  // 5d. Pagination (limit=2, page=1)
  const paged = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      limit: 2,
      page: 1,
    },
  });
  typia.assert(paged);
  TestValidator.equals("should return only 2 results")(paged.data.length)(2);

  // 5e. Sorted by change time (desc)
  const sorted = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      sort_by: "changed_at",
      sort_direction: "desc",
    },
  });
  typia.assert(sorted);

  // 5f. Date range window: only most recent
  const afterManual = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      changed_at_from: nowIso,
      limit: 1,
    },
  });
  typia.assert(afterManual);
  TestValidator.predicate("at least one snapshot after manual creation")(
    afterManual.data.length >= 1,
  );

  // 6. Negative: Search as non-admin → Auth error expected
  connection.headers.Authorization = undefined;
  await TestValidator.error("non-admin cannot search snapshots")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
      productInquiryId: inquiry.id,
      body: {
        inquiry_id: inquiry.id,
      },
    });
  });

  // 7. Negative: Malformed filter (missing required inquiry_id)
  connection.headers.Authorization = adminInfo.setHeaders.Authorization;
  await TestValidator.error("malformed filter causes server error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
      productInquiryId: inquiry.id,
      body: {} as any,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { IPageIShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendInquirySnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated retrieval of inquiry snapshot history for a customer who owns the inquiry.
 *
 * This test creates a product inquiry, updates it several times (which generates audit/evidence snapshots per update),
 * and then uses the search API to fetch the inquiry snapshot history.
 * It verifies that the returned snapshots match the updates and that pagination/meta data is correct.
 *
 * Steps:
 * 1. Create a new product inquiry as a customer (using random IDs for customer/product).
 * 2. Update the inquiry several times (with different fields) to generate audit snapshots.
 * 3. Search for all snapshots by inquiry ID via the paginated search endpoint (as the owning customer).
 * 4. Validate that the returned data contains at least as many snapshots as updates performed, and that core snapshot data aligns with update history.
 */
export async function test_api_inquiry_snapshot_search_customer_success(connection: api.IConnection) {
  // 1. Create a new inquiry
  const inquiryCreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    title: `Initial inquiry: ${RandomGenerator.paragraph(1)()}`,
    body: RandomGenerator.paragraph(1)(),
    public: true,
  } satisfies IShoppingMallAiBackendProductInquiry.ICreate;
  const created = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, { body: inquiryCreate });
  typia.assert(created);

  // 2. Perform several updates (generating snapshots)
  const updates = [
    { title: `Edit 1: ${RandomGenerator.alphabets(6)}`, status: "waiting" },
    { body: `Body update 2: ${RandomGenerator.alphaNumeric(10)}`, status: "waiting" },
    { public: false, status: "answered" },
    { title: `Edit 4: ${RandomGenerator.alphabets(5)}`, body: `Body final: ${RandomGenerator.alphaNumeric(8)}`, status: "under_review" }
  ];
  for (const upd of updates) {
    await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
      productInquiryId: created.id,
      body: {
        ...upd
      } satisfies IShoppingMallAiBackendProductInquiry.IUpdate,
    });
  }

  // 3. Search all inquiry snapshots (as inquiry owner, using inquiry_id filter)
  const snapshotSearchReq = {
    inquiry_id: created.id,
    // fetch all: set high limit to get all (assuming limit is enough)
    limit: 10,
    page: 1,
    sort_by: "changed_at",
    sort_direction: "asc"
  } satisfies IShoppingMallAiBackendInquirySnapshot.IRequest;
  const pageResult = await api.functional.shoppingMallAiBackend.customer.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: created.id,
    body: snapshotSearchReq,
  });
  typia.assert(pageResult);

  // 4. Validate result: snapshots length >= 1 + updates (original + updates)
  const numUpdatesPerformed = updates.length;
  TestValidator.predicate("# of snapshots >= original + updates")(
    pageResult.data.length >= 1 + numUpdatesPerformed
  );
  // Optionally, check newest snapshot fields match last update
  const latestSnapshot = pageResult.data[pageResult.data.length - 1];
  if (latestSnapshot) {
    if (updates[updates.length - 1].title !== undefined) {
      TestValidator.equals("latest title")(
        latestSnapshot.title
      )(
        updates[updates.length - 1].title!
      );
    }
    if (updates[updates.length - 1].body !== undefined) {
      TestValidator.equals("latest body")(
        latestSnapshot.body
      )(
        updates[updates.length - 1].body!
      );
    }
    if (updates[updates.length - 1].public !== undefined) {
      TestValidator.equals("latest public")(
        latestSnapshot.public
      )(
        updates[updates.length - 1].public!
      );
    }
    TestValidator.equals("latest status")(
      latestSnapshot.status
    )(
      updates[updates.length - 1].status
    );
  }
}

