      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(5),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerSignUp);
  const sellerId = sellerSignUp.sellerId;

  // 2. Register the customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "CustomerSecret321@",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;

  // 3. Seller creates a product
  // The seller is still authenticated
  const productCode = RandomGenerator.alphaNumeric(12);
  const productName = RandomGenerator.paragraph()(2);
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: productName,
      status: "published",
      description: RandomGenerator.content()()(),
      main_image_uri: null,
    },
  });
  typia.assert(product);

  // 4. Customer submits a product inquiry
  // Switch to customer session (use the JWT header)
  connection.headers.Authorization = customerSignUp.setHeaders.Authorization;
  const inquiryTitle = RandomGenerator.paragraph()(1);
  const inquiryBody = RandomGenerator.content()(1)();
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: product.id,
      title: inquiryTitle,
      body: inquiryBody,
      public: true,
    },
  });
  typia.assert(inquiry);

  // 5. Seller creates a snapshot for the inquiry
  // Switch back to seller
  connection.headers.Authorization = sellerSignUp.setHeaders.Authorization;

  const now = new Date().toISOString();
  const snapshot = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.create(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      title: inquiry.title,
      body: inquiry.body,
      public: inquiry.public,
      status: (inquiry.status === "waiting" || inquiry.status === "answered" || inquiry.status === "blocked" || inquiry.status === "under_review" || inquiry.status === "deleted") ? inquiry.status : "waiting",
      actor_id: sellerId,
      ai_sentiment_score: inquiry.ai_sentiment_score ?? null,
      ai_spam_score: inquiry.ai_spam_score ?? null,
      changed_at: now,
    },
  });
  typia.assert(snapshot);

  // 6. Validate that the snapshot matches key fields
  TestValidator.equals("inquiry id matches")(snapshot.inquiry_id)(inquiry.id);
  TestValidator.equals("title matches")(snapshot.title)(inquiry.title);
  TestValidator.equals("body matches")(snapshot.body)(inquiry.body);
  TestValidator.equals("public flag matches")(snapshot.public)(inquiry.public);
  TestValidator.equals("status legal value")(snapshot.status)(snapshot.status); // already validated above
  TestValidator.equals("actor id is seller")(snapshot.actor_id)(sellerId);
  TestValidator.predicate("changed_at recent")(Math.abs(new Date(snapshot.changed_at).getTime() - new Date(now).getTime()) < 10000);
  if (inquiry.ai_sentiment_score !== undefined)
    TestValidator.equals("ai_sentiment_score matches")(snapshot.ai_sentiment_score)(inquiry.ai_sentiment_score);
  if (inquiry.ai_spam_score !== undefined)
    TestValidator.equals("ai_spam_score matches")(snapshot.ai_spam_score)(inquiry.ai_spam_score);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate unauthorized snapshot creation by non-owner seller is prevented.
 *
 * This test ensures that only the seller who owns the product associated
 * with an inquiry can create a snapshot for that inquiry. If a seller
 * who does not own the underlying product attempts to create a snapshot,
 * the API must reject the request and no state should be changed.
 *
 * Workflow:
 * 1. Register Seller A and Seller B.
 * 2. Seller A creates a product.
 * 3. Register a customer.
 * 4. Customer creates an inquiry for Seller A's product.
 * 5. Seller B (not the owner) attempts to create a snapshot for the inquiry.
 * 6. Assert error is thrown for insufficient permission; state is not changed.
 *
 * Note: Final check for unchanged state or audit log cannot be performed,
 * as no API to list snapshots/logs exists in current SDK/materials.
 */
export async function test_api_inquiry_snapshot_creation_seller_unauthorized(
  connection: api.IConnection,
) {
  // 1. Register Seller A
  const sellerAEmail: string = typia.random<string & tags.Format<"email">>();
  const sellerA = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "Password!1234",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerA);

  // 2. Register Seller B
  const sellerBEmail: string = typia.random<string & tags.Format<"email">>();
  const sellerB = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "Password!4321",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerB);

  // Use Seller A's session for product creation
  connection.headers.Authorization = sellerA.setHeaders.Authorization;
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerA.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.content()(1)(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 3. Register Customer
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customer = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "Password!5678",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customer);

  // Use customer session for inquiry creation
  connection.headers.Authorization = customer.setHeaders.Authorization;
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customer.customer.id,
      product_id: product.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
  });
  typia.assert(inquiry);

  // Switch to Seller B session to attempt forbidden snapshot creation
  connection.headers.Authorization = sellerB.setHeaders.Authorization;
  await TestValidator.error("Non-owner seller should not be able to create inquiry snapshot")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.create(connection, {
        productInquiryId: inquiry.id,
        body: {
          inquiry_id: inquiry.id,
          title: inquiry.title,
          body: inquiry.body,
          public: inquiry.public,
          // Map status to a valid value from the allowed enum
          status: inquiry.status === "waiting" ||
                  inquiry.status === "answered" ||
                  inquiry.status === "blocked" ||
                  inquiry.status === "under_review" ||
                  inquiry.status === "deleted"
            ? (inquiry.status as "waiting" | "answered" | "blocked" | "under_review" | "deleted")
            : "waiting",
          actor_id: sellerB.sellerId,
          changed_at: new Date().toISOString(),
        } satisfies IShoppingMallAiBackendInquirySnapshot.ICreate,
      });
    },
  );
  // Note: Cannot verify no snapshot was created or audit log due to API limitations
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IPageIShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrder";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPayment";
import type { IShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPaymentLog";
import type { IPageIShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderPaymentLog";

/**
 * Validate advanced payment log searching for an order payment as an admin.
 *
 * This test verifies that an admin can search, filter, and paginate payment log records for any order payment in the system—regardless of ownership. It applies various filters (log_type, date range, pagination), checks that logs with sensitive or error details are visible to admins as business policy allows, confirms correct response structure, and ensures error handling is proper for invalid access.
 *
 * Steps:
 * 1. Search for an order visible to admin (any order suffices)
 * 2. Create a payment for that order as admin
 * 3. Insert diverse payment logs (types: request, response, error)
 * 4. Search logs
 *    a. Unfiltered (all logs)
 *    b. By log_type
 *    c. By occurred_at date-range
 *    d. By pagination
 * 5. Confirm log content and pagination correctness
 * 6. Validate sensitive/error content is present for admins
 * 7. Test error handling for invalid payment id
 */
export async function test_api_order_payment_log_search_as_admin_with_advanced_filters(
  connection: api.IConnection,
) {
  // 1. Search for any order (admin has global access)
  const orderSearch = await api.functional.shoppingMallAiBackend.admin.orders.search(connection, {
    body: {
      page: 1,
      pageSize: 1,
      sort: '-created_at',
    },
  });
  typia.assert(orderSearch);
  TestValidator.predicate('admin can see at least one order')(orderSearch.data.length > 0);
  const order = orderSearch.data[0];

  // 2. Create payment for the found order
  const payment = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id: typia.random<string & tags.Format<'uuid'>>(),
      payment_method: 'card',
      transaction_id: `TXN-${Date.now()}`,
      amount: 10000,
      currency_code: order.currency_code,
      payment_result: 'completed',
      payment_context: '{"meta":"test"}',
    },
  });
  typia.assert(payment);

  // 3. Insert three logs (types: request, response, error)
  const now = new Date();
  const logs = await Promise.all([
    api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: payment.id,
      body: {
        log_type: 'request',
        log_context: '{"request":"initiated"}',
        occurred_at: new Date(now.getTime() - 1000 * 60 * 10).toISOString(),
      },
    }),
    api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: payment.id,
      body: {
        log_type: 'response',
        log_context: '{"response":"ok"}',
        occurred_at: now.toISOString(),
      },
    }),
    api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: payment.id,
      body: {
        log_type: 'error',
        log_context: '{"error":"card_declined","details":{"stack":"err_stack_here"}}',
        occurred_at: new Date(now.getTime() + 1000 * 60 * 10).toISOString(),
      },
    }),
  ]);
  logs.forEach(typia.assert);

  // 4a. Search all logs (no filter)
  const resultAll = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      order_payment_id: payment.id,
    },
  });
  typia.assert(resultAll);
  TestValidator.equals('should return all logs')(resultAll.data.length)(3);

  // 4b. Search by log type (error)
  const resultErrorType = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      order_payment_id: payment.id,
      log_type: 'error',
    },
  });
  typia.assert(resultErrorType);
  TestValidator.equals('should return only error logs')(resultErrorType.data.length)(1);
  TestValidator.equals('error log type matches')(resultErrorType.data[0].log_type)('error');

  // 4c. Filter by occurred_at range (should catch at least 2 logs)
  const resultRange = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      order_payment_id: payment.id,
      occurred_at_from: new Date(now.getTime() - 1000 * 60 * 5).toISOString(),
      occurred_at_to: new Date(now.getTime() + 1000 * 60 * 15).toISOString(),
    },
  });
  typia.assert(resultRange);
  TestValidator.predicate('time range filter works')(resultRange.data.length >= 2);

  // 4d. Pagination: limit 2, page 1
  const paginated = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      order_payment_id: payment.id,
      page: 1,
      limit: 2,
    },
  });
  typia.assert(paginated);
  TestValidator.equals('pagination limit')(paginated.data.length)(2);
  TestValidator.equals('pagination page')(paginated.pagination.current)(1);
  TestValidator.equals('pagination size')(paginated.pagination.limit)(2);

  // 5. Confirm error log's sensitive details are visible
  const errorLog = resultErrorType.data[0];
  TestValidator.predicate('admin sees error stack in log_context')(
    typeof errorLog.log_context === 'string' && errorLog.log_context.includes('stack'),
  );

  // 6. Test error handling: search with invalid orderPaymentId
  await TestValidator.error('invalid payment id triggers error')(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
        orderId: order.id,
        orderPaymentId: typia.random<string & tags.Format<'uuid'>>(),
        body: {
          order_payment_id: typia.random<string & tags.Format<'uuid'>>(),
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendPoint";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validates admin-level updates to a customer point wallet's balance,
 * enforcing business rules and immutability constraints.
 *
 * **Test Steps:**
 * 1. Register a new customer using the customer registration API.
 * 2. Create a point wallet for the new customer via the admin point creation API (linking with the customer).
 * 3. Update the point wallet's balance as an admin with a new (positive) value, and verify the response reflects the new balance and updated timestamp (audit field).
 * 4. Attempt to update immutable/missing fields (e.g., pass extra body keys), and verify the API rejects these requests.
 * 5. Attempt to update the balance with an invalid value (such as a negative number if negatives are logically disallowed), and expect the API to reject such changes, confirming enforcement of business restrictions.
 */
export async function test_api_point_wallet_update_balance_and_restrictions(connection: api.IConnection) {
  // 1. Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "Abcd1234!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(10),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;

  // 2. Create a point wallet for the new customer
  const initialBalance = 1000;
  const pointWallet = await api.functional.shoppingMallAiBackend.admin.points.create(connection, {
    body: {
      customer_id: customerId,
      balance: initialBalance,
    } satisfies IShoppingMallAiBackendPoint.ICreate,
  });
  typia.assert(pointWallet);

  // 3. Update the point wallet's balance via admin
  const updatedBalance = initialBalance + 500;
  const updatedWallet = await api.functional.shoppingMallAiBackend.admin.points.update(connection, {
    pointId: pointWallet.id,
    body: {
      balance: updatedBalance,
    } satisfies IShoppingMallAiBackendPoint.IUpdate,
  });
  typia.assert(updatedWallet);
  TestValidator.equals("updated balance")(updatedWallet.balance)(updatedBalance);
  TestValidator.notEquals("updated timestamp should change")(pointWallet.updated_at)(updatedWallet.updated_at);

  // 4. Attempt to update immutable/missing fields (should fail)
  await TestValidator.error("cannot update customer_id field")(() =>
    api.functional.shoppingMallAiBackend.admin.points.update(connection, {
      pointId: pointWallet.id,
      // @ts-expect-error: purposely include invalid key for negative test
      body: {
        // the schema only allows 'balance', so adding 'customer_id' should fail on runtime
        customer_id: typia.random<string & tags.Format<"uuid">>(),
        balance: updatedBalance + 100
      } as any,
    })
  );

  // 5. Attempt to set an invalid (negative) balance if negatives forbidden
  await TestValidator.error("cannot set negative balance")(() =>
    api.functional.shoppingMallAiBackend.admin.points.update(connection, {
      pointId: pointWallet.id,
      body: {
        balance: -100,
      } satisfies IShoppingMallAiBackendPoint.IUpdate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
