import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate the paginated, filtered search of mileage wallet records as an admin.
 *
 * This test ensures the admin can retrieve wallets using various filters, pagination, and access controls. It simulates customers and wallets with different data, performs filtered and paginated searches (by program, status, label, and customer), confirms result correctness, and verifies error handling for invalid filters. It also checks access is admin-only.
 *
 * Steps:
 * 1. Register two customers.
 * 2. Create mileage wallets for those customers with varied program types and status.
 * 3. Search for wallets filtered by wallet_program and wallet_status.
 * 4. Search using customer_id to ensure correct customer wallets are returned.
 * 5. Test pagination by setting a low limit.
 * 6. Try malformed or unsupported filters and expect errors.
 * 7. Confirm only admin (test context) can access; (customer access cannot be tested due to lack of endpoint).
 */
export async function test_api_mileage_wallet_search_filters_and_access_control(connection: api.IConnection) {
  // 1. Register two customers
  const cust1Res = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(cust1Res);
  const cust2Res = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(cust2Res);

  // 2. Create wallets for both customers, different program/status/labels
  const walletA = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: cust1Res.customer.id,
      wallet_program: "event",
      wallet_status: "active",
      wallet_label: "Customer1 - Event Points",
      security_code: null,
    },
  });
  typia.assert(walletA);
  const walletB = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: cust2Res.customer.id,
      wallet_program: "campaign",
      wallet_status: "locked",
      wallet_label: "Customer2 - Campaign",
      security_code: "4321",
    },
  });
  typia.assert(walletB);

  // 3. Search by program and status
  const programSearch = await api.functional.shoppingMallAiBackend.admin.mileageWallets.search(connection, {
    body: { wallet_program: "event", wallet_status: "active" },
  });
  typia.assert(programSearch);
  TestValidator.predicate("program search")(programSearch.data.every((w) => w.wallet_program === "event" && w.wallet_status === "active"));

  // 4. Search by customer_id
  const custSearch = await api.functional.shoppingMallAiBackend.admin.mileageWallets.search(connection, {
    body: { customer_id: cust2Res.customer.id },
  });
  typia.assert(custSearch);
  TestValidator.predicate("customer_id search")(custSearch.data.every((w) => w.customer_id === cust2Res.customer.id));

  // 5. Pagination: limit=1
  const paged = await api.functional.shoppingMallAiBackend.admin.mileageWallets.search(connection, {
    body: { limit: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("pagination limit")(paged.data.length)(1);

  // 6. Error handling: malformed search (use an invalid type for limit)
  await TestValidator.error("malformed limit")(async () => {
    await api.functional.shoppingMallAiBackend.admin.mileageWallets.search(connection, {
      body: { limit: "bad" as any },
    });
  });

  // 7. Error: unsupported search filter (field does not exist)
  await TestValidator.error("unsupported filter")(async () => {
    await api.functional.shoppingMallAiBackend.admin.mileageWallets.search(connection, {
      body: { bogusFilter: 999 as any },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
