import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendArticleCategory";
import type { IPageIShoppingMallAiBackendArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendArticleCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for advanced admin search & pagination on article categories.
 *
 * This test validates that the admin article category search endpoint supports multiple filter/search scenarios, including:
 *  - Partial search by code and name
 *  - Parent-child tree filtering (parent_id as root and nested)
 *  - Active/inactive status filter
 *  - Pagination robustness (more than one page, correct limit/page)
 *
 * The test ensures only admin can access, and invalid search input returns error.
 *
 * Steps:
 * 1. Create a root category (no parent)
 * 2. Create 5+ child categories with parent structure
 * 3. Create several more categories (different codes/names, a mix of active/inactive and roots/children)
 * 4. Perform search with:
 *     - Name partial match (should match relevant names only)
 *     - Code partial match (should match only code subset)
 *     - parent_id filter (tree separation, only matching children or roots)
 *     - is_active filter (return only active/inactive accordingly)
 *     - Combined filters (e.g. parent_id + is_active)
 *     - Pagination (limit=2, page=2, etc. check boundaries and total page count)
 * 5. Validate search results each time (correct hits, correct total count, records on correct page)
 * 6. Attempt search as unauthorized user (simulate) and expect error
 * 7. Send invalid search filter (e.g., negative limit or page, impossible filter) and expect error.
 */
export async function test_api_article_category_advanced_search_admin(connection: api.IConnection) {
  // 1. Create root category
  const root = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
    body: {
      parent_id: null,
      name: "RootCat",
      code: "ROOT",
      sort_order: 0,
      is_active: true,
    },
  });
  typia.assert(root);

  // 2. Create 5+ children under root
  const children = await Promise.all(
    ArrayUtil.repeat(5)((i) =>
      api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
        body: {
          parent_id: root.id,
          name: `ChildCat${i + 1}`,
          code: `CHILD${i + 1}`,
          sort_order: i + 1,
          is_active: true,
        },
      })
    )
  );
  children.forEach(typia.assert);

  // 3. Create more categories (varied: roots, children, codes, names, is_active)
  const mixA = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
    body: {
      parent_id: null,
      name: "FAQ",
      code: "FAQA",
      sort_order: 99,
      is_active: false,
    },
  });
  typia.assert(mixA);
  const mixB = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
    body: {
      parent_id: mixA.id,
      name: "InactiveChild",
      code: "INACTIVECHILD",
      sort_order: 100,
      is_active: false,
    },
  });
  typia.assert(mixB);

  // 4a. Search by name (partial)
  let res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { name: "ChildCat" },
  });
  typia.assert(res);
  TestValidator.predicate("all names include keyword")(
    res.data.every((c) => c.name.includes("ChildCat"))
  );
  TestValidator.predicate("contains all children")(
    children.every((child) => res.data.some((c) => c.id === child.id))
  );

  // 4b. Search by code (partial)
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { code: "CHILD" },
  });
  typia.assert(res);
  TestValidator.predicate("all codes include keyword")(
    res.data.every((c) => c.code.includes("CHILD"))
  );

  // 4c. Filter by parent_id (should return only direct children of root)
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { parent_id: root.id },
  });
  typia.assert(res);
  TestValidator.equals("direct child count")(res.data.length)(children.length);
  TestValidator.predicate("all have parent_id=root.id")(
    res.data.every((c) => c.parent_id === root.id)
  );

  // 4d. Filter by is_active = false
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { is_active: false },
  });
  typia.assert(res);
  TestValidator.predicate("all inactive")(
    res.data.every((c) => c.is_active === false)
  );
  TestValidator.predicate("mixA and mixB are found")(
    [mixA.id, mixB.id].every((id) => res.data.some((c) => c.id === id))
  );

  // 4e. Combined filter: parent_id + is_active=false
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { parent_id: mixA.id, is_active: false },
  });
  typia.assert(res);
  TestValidator.predicate("only InactiveChild returned")(
    res.data.length === 1 && res.data[0].id === mixB.id
  );

  // 4f. Pagination test: add extra categories for paging
  const pagecats = await Promise.all(
    ArrayUtil.repeat(4)((i) =>
      api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
        body: {
          parent_id: null,
          name: `PageCat${i + 1}`,
          code: `PAGE${i + 1}`,
          sort_order: 100 + i,
          is_active: true,
        },
      })
    )
  );
  pagecats.forEach(typia.assert);

  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { name: "PageCat", limit: 2, page: 1 },
  });
  typia.assert(res);
  TestValidator.equals("should be limited to 2 results")(res.data.length)(2);
  TestValidator.equals("pagination info, page 1")(res.pagination.current)(1);
  TestValidator.equals("total pages at least 2")(res.pagination.pages >= 2)(true);

  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { name: "PageCat", limit: 2, page: 2 },
  });
  typia.assert(res);
  TestValidator.equals("should be limited to 2 results")(res.data.length)(2);
  TestValidator.equals("pagination info, page 2")(res.pagination.current)(2);

  // 5. Unauthorized access: simulate non-admin, or invalid token if available (expect error)
  if (connection.headers) {
    const fakeConnection = {
      ...connection,
      headers: {
        ...connection.headers,
        Authorization: "Bearer FAKEINVALIDTOKEN",
      },
    };
    await TestValidator.error("unauthorized fails")(
      () =>
        api.functional.shoppingMallAiBackend.admin.articleCategories.search(fakeConnection, {
          body: {},
        })
    );
  }

  // 6. Invalid filter (e.g. negative page/limit) expect error
  await TestValidator.error("invalid limit")(
    () =>
      api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
        body: { limit: -1, page: 1 },
      })
  );
  await TestValidator.error("invalid page")(
    () =>
      api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
        body: { limit: 1, page: -2 },
      })
  );
  await TestValidator.error("impossible parent_id")(
    () =>
      api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
        body: { parent_id: "deadbeef" },
      })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderStatusHistory";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Ensures that a non-owning seller cannot record order status updates for another seller's order.
 *
 * Business context:
 * In a marketplace, only the seller who owns a product (and thus whose shop received the order) should be able to update an order's status history as a "seller" actor for that order. If an unrelated seller attempts such an action, the backend must enforce business isolation and reject the unauthorized request.
 *
 * Why this test is critical:
 * - Prevents privilege escalation and unauthorized workflow transitions.
 * - Ensures that order/audit trails are maintained only by relevant, authorized business actors.
 * - Enforces marketplace contract boundaries, protecting both customer and seller integrity.
 *
 * Process breakdown:
 * 1. Register Seller A (who will own the product and order).
 * 2. Register Seller B (a user with valid seller account, but unrelated to the order).
 * 3. Register a customer (who will make a purchase for Seller A's goods).
 * 4. Seller A creates a product (product is attributed to Seller A).
 * 5. Customer places an order (simplified, as order entity does not natively list product; test assumes system linkage for this context).
 * 6. Switch API context to Seller B by injecting Seller B's JWT into connection.headers.
 * 7. Seller B attempts to record an order status history event for the order from step 5.
 * 8. Assertion: Backend rejects with permission or ownership error; operation must not succeed.
 */
export async function test_api_seller_create_order_status_history_for_non_owned_order(
  connection: api.IConnection,
) {
  // 1. Register Seller A and receive authentication response
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAPassword = "Password123!";
  const sellerAResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
      companyName: RandomGenerator.name(),
      businessNumber: String(
        typia.random<
          number & tags.Format<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>
        >(),
      ),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerAResp);
  const sellerAId = sellerAResp.sellerId;

  // 2. Register Seller B (will attempt the forbidden action)
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBPassword = "Password456!";
  const sellerBResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: sellerBPassword,
      companyName: RandomGenerator.name(),
      businessNumber: String(
        typia.random<
          number & tags.Format<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>
        >(),
      ),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerBResp);
  const sellerBId = sellerBResp.sellerId;

  // 3. Register a Customer C and set API context to customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Customer789!";
  const customerResp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerResp);
  const customerId = customerResp.customer.id;
  // Simulate customer authentication: set JWT from registration response
  connection.headers = { ...(connection.headers ?? {}), Authorization: customerResp.setHeaders.Authorization };

  // 4. Seller A (re-auth) creates a product
  connection.headers = { ...(connection.headers ?? {}), Authorization: sellerAResp.setHeaders.Authorization };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(),
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 5. Customer (set back to customer JWT) places an order (for Seller A's product)
  connection.headers = { ...(connection.headers ?? {}), Authorization: customerResp.setHeaders.Authorization };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 50000,
      currency_code: "KRW",
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(order);

  // 6. Switch context/API headers to Seller B (unrelated seller)
  connection.headers = { ...(connection.headers ?? {}), Authorization: sellerBResp.setHeaders.Authorization };

  // 7. Seller B attempts forbidden creation of order status history
  await TestValidator.error("unrelated seller must be denied updating order status history")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.orders.orderStatusHistories.create(connection, {
        orderId: order.id,
        body: {
          previous_status: "created",
          new_status: "paid",
          actor_type: "seller",
          actor_id: sellerBId,
          occurred_at: new Date().toISOString(),
        } satisfies IShoppingMallAiBackendOrderStatusHistory.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSeller";
import type { IShoppingMallAiBackendSellerBusinessVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSellerBusinessVerification";
import type { IPageIShoppingMallAiBackendSellerBusinessVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSellerBusinessVerification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate business verification search and filtering as admin for a seller
 *
 * This test ensures the admin can retrieve paginated, filtered business verification records for a specific seller.
 *
 * Covered behaviors:
 * 1. Admin authentication (login)
 * 2. Seller lookup (acquire a sellerId fixture)
 * 3. Creation of multiple business verification records for the seller (distinct document types, statuses, reviewers)
 * 4. Execution of various filtered searches (by document_type, status, reviewed_by, date range)
 * 5. Validation that filters and pagination work as expected
 * 6. Soft-delete simulation by setting deleted_at, then verifying records disappear from search results (audit compliance)
 * 7. Permission checks: only admin can search (no non-admin scenario implemented if no endpoint exists)
 */
export async function test_api_seller_business_verification_search_various_filters(connection: api.IConnection) {
  // 1. Admin authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123!";
  // NOTE: In a full system, the admin account should be created, but as only login is available, use randomized credentials.
  // If this fails in your environment, use known credentials or system-provided fixtures.
  let adminJwt: string;
  try {
    const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IAdminAuth.SignIn,
    });
    typia.assert(adminLogin);
    adminJwt = adminLogin.jwt;
    connection.headers = { ...(connection.headers ?? {}), Authorization: `Bearer ${adminJwt}` };
  } catch (err) {
    // If login fails, skip further steps (test infra may require predefined admin)
    throw new Error(`Admin login failed – supply a valid admin account in test context.`);
  }

  // 2. Lookup sellerId (use existing or generate a mock fixture)
  // Here, simulate the existence by generating a uuid and using the admin to fetch details
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  let seller;
  try {
    seller = await api.functional.shoppingMallAiBackend.admin.sellers.at(connection, { sellerId });
    typia.assert(seller);
  } catch (err) {
    // If lookup fails, treat as fixture or setup step.
    // (In a real test, create seller beforehand if API permits.)
    throw new Error(`Seller lookup failed – ensure seller exists or fixture is prepared.`);
  }

  // 3. Create several business verifications with different values
  const testRecords = [
    {
      document_type: "business_license",
      verification_status: "approved",
      reviewed_by: "AdminTester",
      // Generate creation timestamps in increasing order for date range testing
      created_at: new Date(Date.now() - 1000 * 60 * 60 * 24 * 2).toISOString(),
    },
    {
      document_type: "bankbook",
      verification_status: "pending",
      reviewed_by: null,
      created_at: new Date(Date.now() - 1000 * 60 * 60 * 24 * 1).toISOString(),
    },
    {
      document_type: "business_license",
      verification_status: "rejected",
      reviewed_by: "AuditorJim",
      created_at: new Date().toISOString(),
    },
  ];

  const createdVerifications: IShoppingMallAiBackendSellerBusinessVerification[] = [];
  for (const rec of testRecords) {
    const created = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.putBySellerid(connection, {
      sellerId,
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        seller_id: sellerId,
        document_type: rec.document_type,
        document_file_uri: "https://example.com/file.pdf",
        verification_status: rec.verification_status,
        reviewed_by: rec.reviewed_by,
        reviewed_at: rec.reviewed_by ? new Date().toISOString() : null,
        note: "Test note for filtering",
        created_at: rec.created_at,
        updated_at: rec.created_at,
        deleted_at: null,
      } satisfies IShoppingMallAiBackendSellerBusinessVerification,
    });
    typia.assert(created);
    createdVerifications.push(created);
  }

  // 4. Run SEARCH with single-criterion filter: document_type = business_license
  let resp = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.search(connection, {
    sellerId,
    body: {
      document_type: "business_license",
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IRequest,
  });
  typia.assert(resp);
  TestValidator.predicate("Search by document_type: all types are business_license")(
    resp.data.every((r) => r.document_type === "business_license")
  );

  // 5. Filter: verification_status = approved
  resp = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.search(connection, {
    sellerId,
    body: {
      verification_status: "approved",
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IRequest,
  });
  typia.assert(resp);
  TestValidator.predicate("Search by verification_status: all results approved")(
    resp.data.every((r) => r.verification_status === "approved")
  );

  // 6. Filter: reviewed_by = AdminTester
  resp = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.search(connection, {
    sellerId,
    body: {
      reviewed_by: "AdminTester",
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IRequest,
  });
  typia.assert(resp);
  TestValidator.predicate("reviewed_by filter returns expected admin")(
    resp.data.every((r) => r.reviewed_by === "AdminTester")
  );

  // 7. Filter: created_from - only most recent
  const from = new Date(Date.now() - 1000 * 60 * 60 * 24 * 1).toISOString();
  resp = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.search(connection, {
    sellerId,
    body: {
      created_from: from,
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IRequest,
  });
  typia.assert(resp);
  TestValidator.predicate("date range filter")(
    resp.data.every((r) => new Date(r.created_at) >= new Date(from))
  );

  // 8. Pagination: limit to 2, page 1,2
  resp = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.search(connection, {
    sellerId,
    body: {
      page: 1,
      limit: 2,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IRequest,
  });
  typia.assert(resp);
  TestValidator.equals("Pagination: limit 2")(resp.pagination.limit)(2);
  TestValidator.equals("Pagination: page 1")(resp.pagination.current)(1);
  // Now page 2
  const resp2 = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.search(connection, {
    sellerId,
    body: {
      page: 2,
      limit: 2,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IRequest,
  });
  typia.assert(resp2);
  TestValidator.equals("Pagination: page 2")(resp2.pagination.current)(2);

  // 9. Soft-delete simulation: mark one record as deleted
  const softDeleted = createdVerifications[0];
  await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.putBySellerid(connection, {
    sellerId,
    body: {
      ...softDeleted,
      deleted_at: new Date().toISOString(),
    } satisfies IShoppingMallAiBackendSellerBusinessVerification,
  });
  resp = await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.search(connection, {
    sellerId,
    body: {
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IRequest,
  });
  typia.assert(resp);
  TestValidator.predicate("No soft-deleted records in search results")(
    resp.data.every((r) => !r.deleted_at)
  );

  // 10. Permission check edge case (not implementable as non-admin context not available)
  // Attempt as non-admin or unrelated seller is skipped (no API for sign-in as seller)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerAddress";
import type { IPageIShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerAddress";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBackendFavoriteAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteAddress";
import type { IPageIShoppingMallAiBackendFavoriteAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendFavoriteAddress";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * End-to-end test for listing and filtering a customer's favorite addresses, supporting business pagination and filter scenarios.
 *
 * Business goals:
 * - Ensure favorite address listing/filtering works for an authenticated customer only (privacy)
 * - Correctly returns only active favorites, not soft-deleted
 * - Filtering: supports alias, created_at date range, and pagination on PATCH endpoint
 * - Negative test: handles invalid filters, rejects unauthenticated access
 *
 * Workflow:
 * 1. Register a new customer/account (retains connection authorization)
 * 2. Add/associate several addresses to the customer account (imitate address book by using those from test DB)
 * 3. Mark a subset of these addresses as favorites
 * 4. Run PATCH favoriteAddresses with default (no filters): must return all active favorite records for this customer
 * 5. Run PATCH again (with alias, created_at_from/created_at_to, pagination - eg limit=2) and verify only valid/filtered records are returned
 * 6. Negative: try with invalid filter parameters (such as `limit=0`, bad sort_dir), expect errors
 * 7. Negative: logout/remove Authorization, try listing again — must be denied (unauthenticated)
 */
export async function test_api_favorite_addresses_list_pagination_filtering(
  connection: api.IConnection,
) {
  // 1. Register account
  const signup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(signup);

  const customerId = signup.customer.id;

  // 2. Obtain addresses for this customer (admin listing — test DB must have test data)
  const addressesResp = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: {},
  });
  typia.assert(addressesResp);

  const addresses = addressesResp.data;
  if (!addresses.length)
    throw new Error("No addresses for customer found in test DB. Skipping favorite-address scenario.");

  // 3. Mark several as favorites (first up to 2)
  const favoriteTargets = addresses.slice(0, Math.min(2, addresses.length));
  for (let addr of favoriteTargets) {
    const fav = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, {
      body: { customer_id: customerId, address_id: addr.id },
    });
    typia.assert(fav);
    TestValidator.equals("favorite mapped correctly")(fav.customer_id)(customerId);
    TestValidator.equals("favorited address ID matches")(fav.address_id)(addr.id);
  }

  // 4. List all favorites, no filters (should include all favorites just created above)
  const allFavsResp = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
    body: { customer_id: customerId },
  });
  typia.assert(allFavsResp);
  const allFavIds = allFavsResp.data.map((fa) => fa.address_id);
  for (const favTarget of favoriteTargets)
    TestValidator.predicate("favorite present in list")(allFavIds.includes(favTarget.id));

  // 5. Test filters (alias, date ranges, pagination)
  // Assume alias is optional, only filter if present
  if (favoriteTargets[0].alias) {
    const byAlias = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
      body: { customer_id: customerId, alias: favoriteTargets[0].alias },
    });
    typia.assert(byAlias);
    TestValidator.predicate("alias filter result includes address")(
      byAlias.data.some((fa) => fa.address_id === favoriteTargets[0].id),
    );
  }

  // Filter by created_at date range of one favorite
  if (allFavsResp.data.length > 0) {
    const dateFrom = allFavsResp.data[0].created_at;
    const dateTo = allFavsResp.data[0].created_at;
    const byDate = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
      body: { customer_id: customerId, created_at_from: dateFrom, created_at_to: dateTo },
    });
    typia.assert(byDate);
    TestValidator.predicate("date-range filter result nonempty")(
      byDate.data.length > 0
    );
  }

  // Pagination (limit: 1)
  const paged = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
    body: { customer_id: customerId, limit: 1, page: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("pagination (limit=1)")(paged.data.length)(1);

  // 6. Negative: invalid limit (0)
  await TestValidator.error("limit zero triggers error")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
      body: { customer_id: customerId, limit: 0 },
    });
  });
  // Negative: invalid sort_dir
  await TestValidator.error("bad sort_dir triggers error")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
      body: { customer_id: customerId, sort_dir: "bad_dir" as any },
    });
  });

  // 7. Privacy/unauthenticated: clear Authorization and try listing
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("privacy enforced: unauthenticated cannot list favorites")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(
      unauthConn,
      {
        body: { customer_id: customerId },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSellerOnboarding } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSellerOnboarding";
import type { IPageIShoppingMallAiBackendSellerOnboarding } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSellerOnboarding";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate updating of a seller's own onboarding event (onboarding milestone record).
 *
 * This test ensures that a seller, after registration and authentication, can create and update their own onboarding events.
 * It verifies that only allowed fields are mutable, audit log fields behave correctly, and forbidden operations such as updating immutable fields
 * or modifying another seller's onboarding event are properly rejected by the API.
 *
 * 1. Register a new seller (sign-up) and sign in to obtain authentication tokens (JWT stored automatically in connection)
 * 2. Create an onboarding milestone event for the seller (step_code=document_upload, step_status=pending)
 * 3. Update the onboarding event (step_status -> completed, add note) and verify the updates
 * 4. Attempt forbidden updates (e.g., changing immutable step_code, or updating as the wrong seller) to ensure proper errors are thrown
 */
export async function test_api_seller_onboarding_update_by_self(connection: api.IConnection) {
  // 1. Register seller and login
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "ValidPassw0rd!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResp);

  // Login (mainly to initialize connection with JWT, but registration may already do this)
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: "ValidPassw0rd!"
    } satisfies ISellerAuth.SignIn,
  });

  // 2. Create seller onboarding milestone event (step_code=document_upload, pending)
  const onboardingResp = await api.functional.shoppingMallAiBackend.seller.sellers.onboardings.patchBySellerid(connection, {
    sellerId: signUpResp.sellerId,
    body: {
      seller_id: signUpResp.sellerId,
      step_code: "document_upload",
      step_status: "pending",
      approved_by: null,
      note: null,
      occurred_from: null,
      occurred_to: null,
      page: 1,
      limit: 1,
      orderBy: null,
      orderDir: null,
    } satisfies IShoppingMallAiBackendSellerOnboarding.IRequest,
  });
  typia.assert(onboardingResp);
  if (!onboardingResp.data.length) throw new Error("Failed to create onboarding event");
  const createdEvent = onboardingResp.data[0];

  // 3. Update: change step_status and add note
  const updateReq: IShoppingMallAiBackendSellerOnboarding.IUpdate = {
    id: createdEvent.id,
    step_status: "completed",
    note: "document verified",
    approved_by: null
  };
  const updatedEvent = await api.functional.shoppingMallAiBackend.seller.sellers.onboardings.putBySellerid(connection, {
    sellerId: signUpResp.sellerId,
    body: updateReq,
  });
  typia.assert(updatedEvent);
  TestValidator.equals("updated step_status")(updatedEvent.step_status)("completed");
  TestValidator.equals("note updated")(updatedEvent.note)("document verified");
  TestValidator.equals("step_code cannot change")(updatedEvent.step_code)(createdEvent.step_code);
  TestValidator.equals("seller_id cannot change")(updatedEvent.seller_id)(createdEvent.seller_id);

  // 4. Try forbidden update: attempt to update non-mutable field (e.g. step_code)
  await TestValidator.error("cannot change step_code via update")(() =>
    api.functional.shoppingMallAiBackend.seller.sellers.onboardings.putBySellerid(connection, {
      sellerId: signUpResp.sellerId,
      body: {
        ...updateReq,
        // @ts-ignore - purposely sending non-mutable field for error
        step_code: "ai_review"
      } as any, // Only mutable fields allowed by schema
    })
  );

  // 5. Try forbidden update: as another seller
  const otherSellerEmail = typia.random<string & tags.Format<"email">>();
  const otherSignUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: otherSellerEmail,
      password: "AnotherPassw0rd!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(8),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(otherSignUpResp);
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: otherSellerEmail,
      password: "AnotherPassw0rd!"
    } satisfies ISellerAuth.SignIn,
  });

  await TestValidator.error("cannot update another seller's onboarding event")(() =>
    api.functional.shoppingMallAiBackend.seller.sellers.onboardings.putBySellerid(connection, {
      sellerId: signUpResp.sellerId, // Try to update original seller's onboarding as other seller
      body: updateReq
    })
  );
}

