/**
 * Validates admin update of a customer's address, including field, business logic, and error validation flows.
 *
 * This test covers:
 * 1. Admin login to obtain authorization
 * 2. Register a new customer (target)
 * 3. Obtain the customer's addresses (must exist or be auto-generated)
 * 4. Update a chosen address via the admin PUT endpoint
 * 5. Assert update is persisted (by new search)
 * 6. Validate runtime errors: missing required fields, bad phone, non-existent address
 */
export async function test_api_admin_customer_address_update_success_and_validation(
  connection: api.IConnection,
) {
  // 1. Admin login to obtain Authorization header
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = "TestAdmin!234";
  const adminLoginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
