  const addressesPage = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: {
      customer_id: customerId,
      limit: 10,
      page: 1,
    } satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(addressesPage);
  const addresses = addressesPage.data;
  TestValidator.predicate("Should have at least one address")(addresses.length > 0);
