import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerAddress";
import type { IPageIShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerAddress";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate customer address update functionality and permission enforcement.
 *
 * This test ensures that only the rightful customer can update their own address and
 * that the update endpoint enforces validation and security:
 *
 * 1. Registers and authenticates a new customer ("owner").
 * 2. Lists addresses for the owner; selects one to update.
 * 3. Successfully updates the recipient name for that address and confirms the change.
 * 4. Attempts to update with invalid input (blank name, bad phone format) and confirms errors occur.
 * 5. Attempts to update with missing required id and checks error thrown.
 * 6. Registers a second (intruder) customer and confirms they cannot update another customer's address.
 */
export async function test_api_customer_address_update_by_owner_and_permission_enforcement(
  connection: api.IConnection,
) {
  // 1. Register a new customer (owner)
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const customerSignUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: ownerEmail,
      password: "test-password-1234",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignUpResponse);
  const ownerCustomer = customerSignUpResponse.customer;
  const ownerCustomerId = ownerCustomer.id;

  // 2. List addresses for the owner and pick the first one for updating
  const addressListPage = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
    customerId: ownerCustomerId,
    body: {},
  });
  typia.assert(addressListPage);
  TestValidator.predicate("at least one address exists for new customer")(
    addressListPage.data.length > 0
  );
  const addressForUpdate = addressListPage.data[0];

  // 3. Successful update: change receiver_name and verify update
  const newReceiverName = RandomGenerator.name();
  const updatedAddress = await api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
    customerId: ownerCustomerId,
    body: {
      id: addressForUpdate.id,
      receiver_name: newReceiverName,
    },
  });
  typia.assert(updatedAddress);
  TestValidator.equals("receiver_name updated")(updatedAddress.receiver_name)(newReceiverName);
  TestValidator.equals("id unchanged")(updatedAddress.id)(addressForUpdate.id);

  // 4. Validation error: missing required id
  await TestValidator.error("missing required address id fails")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
      customerId: ownerCustomerId,
      // @ts-expect-error: purposely missing id field (runtime test only)
      body: {
        receiver_name: RandomGenerator.name(),
      } as any,
    })
  );

  // 4b. Blank receiver_name: invalid blank name
  await TestValidator.error("blank receiver_name fails")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
      customerId: ownerCustomerId,
      body: {
        id: addressForUpdate.id,
        receiver_name: "",
      },
    })
  );

  // 4c. Invalid receiver_phone
  await TestValidator.error("invalid receiver_phone fails")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
      customerId: ownerCustomerId,
      body: {
        id: addressForUpdate.id,
        receiver_phone: "not-a-phone-number",
      },
    })
  );

  // 5. Second customer attempts to update a different customer's address (should fail)
  const intruderEmail = typia.random<string & tags.Format<"email">>();
  const intruderSignUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: intruderEmail,
      password: "other-password-5678",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(intruderSignUpResponse);
  const intruderCustomerId = intruderSignUpResponse.customer.id;

  await TestValidator.error("cannot update another customer's address")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
      customerId: intruderCustomerId,
      body: {
        id: addressForUpdate.id,
        receiver_name: RandomGenerator.name(),
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerAddress";
import type { IPageIShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerAddress";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test soft-deleting one’s own address as a customer, and forbidden access for others.
 *
 * Business context:
 * - Customers manage multiple addresses for shipping, and should be able to soft-delete (mark deleted_at) their own addresses.
 * - Soft delete means removed from active address lists, but auditable for rollback/history.
 *
 * Test Steps:
 * 1. Register a new customer and authenticate (JWT issued).
 * 2. Create an address for this customer (simulate via listing/patch endpoint).
 * 3. List addresses and select a valid address to delete (get id).
 * 4. Delete the address as the address owner.
 * 5. Assert: address is no longer found in active address listing.
 * 6. Register a second customer, try deleting first customer’s address as the second user (expect permission error).
 * 7. Attempt deleting a random non-existent address id (expect error: not found or similar).
 */
export async function test_api_customer_address_soft_delete_by_owner_and_forbidden_access(connection: api.IConnection) {
  // 1. Register new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const signUpRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpRes);
  const customer = signUpRes.customer;

  // 2. Simulate address creation using the address PATCH endpoint (listing with body = new address fields)
  const newAddressFields = {
    receiver_name: RandomGenerator.name(),
    receiver_phone: RandomGenerator.mobile(),
    postal_code: "12345",
    address_line1: "1 Test St",
    city: "TestCity",
    state: "TestState",
    country: "KR",
    is_primary: true,
  } satisfies IShoppingMallAiBackendCustomerAddress.IRequest;
  await api.functional.shoppingMallAiBackend.customer.customers.addresses.patchByCustomerid(connection, {
    customerId: customer.id,
    body: newAddressFields,
  });

  // 3. List addresses for the customer (should include the new one)
  let listRes = await api.functional.shoppingMallAiBackend.customer.customers.addresses.patchByCustomerid(connection, {
    customerId: customer.id,
    body: {} satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(listRes);
  const [addressToDelete] = listRes.data;
  if (!addressToDelete) throw new Error("Expected at least one address for the customer");

  // 4. Delete the address as owner
  await api.functional.shoppingMallAiBackend.customer.customers.addresses.eraseByCustomeridAndAddressid(connection, {
    customerId: customer.id,
    addressId: addressToDelete.id,
  });

  // 5. Verify soft-deleted address is gone from active address listings
  listRes = await api.functional.shoppingMallAiBackend.customer.customers.addresses.patchByCustomerid(connection, {
    customerId: customer.id,
    body: {} satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(listRes);
  TestValidator.predicate("deleted address no longer listed")(
    listRes.data.every(addr => addr.id !== addressToDelete.id)
  );

  // 6. Register a second customer
  const customer2Email = typia.random<string & tags.Format<"email">>();
  const signUpRes2 = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer2Email,
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpRes2);
  const customer2 = signUpRes2.customer;

  // 7. Attempt forbidden delete (second customer tries to delete first customer’s address)
  TestValidator.error("forbidden to delete another's address")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.addresses.eraseByCustomeridAndAddressid(connection, {
      customerId: customer2.id,
      addressId: addressToDelete.id,
    });
  });

  // 8. Attempt to delete a non-existent address as owner (should return not found)
  TestValidator.error("deleting non-existent address fails")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.addresses.eraseByCustomeridAndAddressid(connection, {
      customerId: customer.id,
      addressId: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendComplianceEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceEvent";

/**
 * Ensure that non-admins cannot delete compliance events (permission denied).
 *
 * This test verifies that deletion of compliance events is strictly restricted to admin users. It follows these steps:
 *
 * 1. Create a compliance event via the admin API (dependency step).
 * 2. Remove admin authorization to simulate a non-admin or unauthenticated client.
 * 3. Attempt to delete the compliance event as a non-admin user.
 * 4. Confirm the API returns a permission error (such as 403 Forbidden).
 *
 * This is essential to enforce audit-log integrity and regulatory controls, ensuring only administrators manage compliance events.
 */
export async function test_api_compliance_event_soft_delete_forbidden_non_admin(
  connection: api.IConnection
) {
  // 1. Create a compliance event as admin
  const complianceEvent = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
    body: {
      event_type: "policy_update",
      actor_id: null,
      actor_type: "admin",
      target_type: "system",
      target_id: null,
      event_payload: null,
    } satisfies IShoppingMallAiBackendComplianceEvent.ICreate,
  });
  typia.assert(complianceEvent);

  // 2. Simulate non-admin context by removing Authorization header
  const nonAdminConnection: api.IConnection = {
    ...connection,
    headers: { ...(connection.headers ?? {}), Authorization: undefined },
  };

  // 3. Attempt to delete as non-admin (should fail with permission error)
  await TestValidator.error("non-admin cannot delete compliance event")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.complianceEvents.erase(nonAdminConnection, {
        complianceEventId: complianceEvent.id,
      });
    },
  );
}

