import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates error handling for the admin soft-delete product endpoint when the target product does not exist.
 *
 * This test checks that the system correctly responds with a 404 Not Found when an admin attempts to soft-delete (erase) a product by a non-existent productId.
 * The test also ensures there are no side effects (e.g., accidental product or audit record modifications).
 *
 * Workflow:
 * 1. Register a new admin using unique credentials
 * 2. Authenticate with the admin account to retrieve a valid JWT, ensuring access to the protected endpoint
 * 3. Attempt to soft-delete a product by passing a random, guaranteed-nonexistent UUID as the productId to the admin products erase endpoint
 * 4. Expect and validate that the API responds with an error (404 Not Found), and verify that no exception other than an HttpError occurs
 */
export async function test_api_admin_product_soft_delete_not_found(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword!123";
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as the admin
  const signInResp = await api.functional.auth.admin.login.post(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Try to soft-delete a product that is guaranteed not to exist
  const nonExistentProductId = typia.random<string & tags.Format<"uuid">>();

  await TestValidator.error("soft-delete non-existent product returns 404")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.eraseByProductid(connection, {
      productId: nonExistentProductId,
    });
  });
}

