import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductSearchKeyword } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSearchKeyword";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates the system's handling of attempts to update a non-existent product search keyword as an authorized seller.
 *
 * This test ensures that when a legitimate seller is authenticated, and then issues a request to update a keyword using non-existent product and keyword IDs, the backend correctly rejects the request with a 'not found' error and does not alter any real data.
 *
 * Step-by-step process:
 * 1. Register a new seller account and ensure authorization context (JWT/session headers) are present for subsequent requests.
 * 2. Attempt to update a product search keyword using random/invalid UUIDs for both productId and productSearchKeywordId.
 * 3. Expect the API to respond with a not found error (e.g., 404), and validate that the operation did not succeed.
 *
 * This test verifies correct error reporting and protects against erroneous data mutation from invalid references.
 */
export async function test_api_product_search_keyword_update_not_found(
  connection: api.IConnection,
) {
  // 1. Register and authenticate seller
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Testpass123$",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.address(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUp);
  // Authorization context (JWT) is now established for this connection

  // 2. Attempt to update a non-existent product search keyword (random UUIDs)
  await TestValidator.error("should return 404 not found - invalid product or keyword")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.updateProductSearchKeyword(connection, {
        productId: typia.random<string & tags.Format<"uuid">>(),
        productSearchKeywordId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          search_keyword: RandomGenerator.alphabets(10),
        } satisfies IShoppingMallAiBackendProductSearchKeyword.IUpdate,
      });
    },
  );
}

