import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that attempting to soft delete a customer profile that has already been soft-deleted triggers the correct error response.
 *
 * This test simulates the following:
 * 1. An admin is registered.
 * 2. The admin logs in and obtains a valid authorization.
 * 3. A new customer is registered (as the entity to be deleted).
 * 4. The admin performs a soft delete (DELETE /shoppingMallAiBackend/admin/customers/{customerId}). This should succeed and set deleted_at.
 * 5. The admin attempts to soft delete the same customer profile again (DELETE /shoppingMallAiBackend/admin/customers/{customerId}).
 *
 * The final step must fail, and the system must return an error indicating the customer no longer exists or is already soft deleted.
 *
 * Steps:
 * 1. Register an admin using api.functional.auth.admin.register.post.
 * 2. Login as that admin using api.functional.auth.admin.login.post.
 * 3. Register a new customer using api.functional.auth.customer.register.post.
 * 4. Soft delete the customer using api.functional.shoppingMallAiBackend.admin.customers.eraseByCustomerid.
 * 5. Retry the soft delete (expect an error). Validate that the deletion failure is correctly handled (do not check error message details).
 */
export async function test_api_customer_admin_erase_already_deleted(
  connection: api.IConnection,
) {
  // 1. Register an admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "Admin123!";
  const adminSignUp = await api.functional.auth.admin.register.post(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as admin
  const adminLogin = await api.functional.auth.admin.login.post(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register a customer
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerSignUp = await api.functional.auth.customer.register.post(connection, {
    body: {
      email: customerEmail,
      password: "customerPass123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;

  // 4. Soft delete customer (should succeed)
  await api.functional.shoppingMallAiBackend.admin.customers.eraseByCustomerid(connection, {
    customerId,
  });

  // 5. Attempt to delete again, expect error
  await TestValidator.error("Deleting already deleted customer must fail")(
    () => api.functional.shoppingMallAiBackend.admin.customers.eraseByCustomerid(connection, { customerId })
  );
}

