import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test soft deletion (erase) of a customer account by an admin, and validate audit/compliance.
 *
 * This test verifies that an admin can successfully perform a soft delete on a customer profile, ensuring:
 * - Proper setup of both admin and customer entities
 * - Execution of the soft delete endpoint as an authorized admin
 * - The customer account is no longer usable afterward
 *
 * Step-by-step:
 * 1. Register a new admin account (receive JWT/setHeaders)
 * 2. Login as the admin (token refresh/verification)
 * 3. Register a new customer account (receive profile & id)
 * 4. Admin soft deletes the customer profile
 * 5. Verify customer actions are blocked after deletion (as far as possible with current APIs)
 *
 * (Note: Due to available API SDK limitations, fetching profile or login as customer after deletion cannot be tested, nor can audit table customer_histories be checked directly. The test covers all possible validations with the provided endpoints.)
 */
export async function test_api_customer_admin_erase_success_and_audit(connection: api.IConnection) {
  // 1. Admin registers
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "S3cr3t!123";
  const adminRegister = await api.functional.auth.admin.register.post(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminRegister);

  // 2. Admin logs in (to ensure fresh session/auth)
  const adminLogin = await api.functional.auth.admin.login.post(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignIn
  });
  typia.assert(adminLogin);

  // 3. Admin creates a customer profile
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Custom3r!123";
  const customerRegister = await api.functional.auth.customer.register.post(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerRegister);
  const customerId = customerRegister.customer.id;

  // 4. Admin soft deletes the customer profile
  await api.functional.shoppingMallAiBackend.admin.customers.eraseByCustomerid(connection, {
    customerId
  });

  // 5. (Limitations) Cannot test customer login/profile fetch or customer_histories due to unavailable APIs
  // The test ends here, validating successful flow up to soft delete execution only.
}

