import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendPoint";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validates admin-level updates to a customer point wallet's balance,
 * enforcing business rules and immutability constraints.
 *
 * **Test Steps:**
 * 1. Register a new customer using the customer registration API.
 * 2. Create a point wallet for the new customer via the admin point creation API (linking with the customer).
 * 3. Update the point wallet's balance as an admin with a new (positive) value, and verify the response reflects the new balance and updated timestamp (audit field).
 * 4. Attempt to update immutable/missing fields (e.g., pass extra body keys), and verify the API rejects these requests.
 * 5. Attempt to update the balance with an invalid value (such as a negative number if negatives are logically disallowed), and expect the API to reject such changes, confirming enforcement of business restrictions.
 */
export async function test_api_point_wallet_update_balance_and_restrictions(connection: api.IConnection) {
  // 1. Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "Abcd1234!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(10),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;

  // 2. Create a point wallet for the new customer
  const initialBalance = 1000;
  const pointWallet = await api.functional.shoppingMallAiBackend.admin.points.create(connection, {
    body: {
      customer_id: customerId,
      balance: initialBalance,
    } satisfies IShoppingMallAiBackendPoint.ICreate,
  });
  typia.assert(pointWallet);

  // 3. Update the point wallet's balance via admin
  const updatedBalance = initialBalance + 500;
  const updatedWallet = await api.functional.shoppingMallAiBackend.admin.points.update(connection, {
    pointId: pointWallet.id,
    body: {
      balance: updatedBalance,
    } satisfies IShoppingMallAiBackendPoint.IUpdate,
  });
  typia.assert(updatedWallet);
  TestValidator.equals("updated balance")(updatedWallet.balance)(updatedBalance);
  TestValidator.notEquals("updated timestamp should change")(pointWallet.updated_at)(updatedWallet.updated_at);

  // 4. Attempt to update immutable/missing fields (should fail)
  await TestValidator.error("cannot update customer_id field")(() =>
    api.functional.shoppingMallAiBackend.admin.points.update(connection, {
      pointId: pointWallet.id,
      // @ts-expect-error: purposely include invalid key for negative test
      body: {
        // the schema only allows 'balance', so adding 'customer_id' should fail on runtime
        customer_id: typia.random<string & tags.Format<"uuid">>(),
        balance: updatedBalance + 100
      } as any,
    })
  );

  // 5. Attempt to set an invalid (negative) balance if negatives forbidden
  await TestValidator.error("cannot set negative balance")(() =>
    api.functional.shoppingMallAiBackend.admin.points.update(connection, {
      pointId: pointWallet.id,
      body: {
        balance: -100,
      } satisfies IShoppingMallAiBackendPoint.IUpdate,
    })
  );
}

