import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate creation of a new shopping cart by an authenticated customer and ensure duplicate prevention per business policy.
 *
 * This test simulates a real customer journey:
 *
 * 1. Register a new customer using unique credentials (email, phone, etc.) via the sign-up API. Confirm the response includes JWT token information and a valid customer profile without sensitive info (e.g., password hash).
 * 2. Using the registered and logged-in session (headers updated with JWT from registration), create a new shopping cart with status 'active'. Verify the created cart record has proper structure (id, status, created/updated timestamps, etc.), status set to 'active', and no missing required fields. Ensure nulls are set explicitly where allowed.
 * 3. Attempt to create a second 'active' cart for the same customer (using the same authenticated session). Expect a business logic error and confirm it is handled by rejecting the API call—using TestValidator to ensure the proper error is thrown (without relying on the exact error message).
 * 4. Verify no superfluous carts are created and customer remains with at most one active cart.
 */
export async function test_api_cart_customer_create_success(connection: api.IConnection) {
  // Step 1: Register a new customer using unique credentials
  const email = typia.random<string & tags.Format<"email">>();
  const password = "ShoppingCart123!";
  const name = RandomGenerator.name();
  const nickname = RandomGenerator.alphaNumeric(8);
  const phone = RandomGenerator.mobile();

  const registration = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name,
      nickname,
      phone
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(registration);
  const { customer } = registration;
  TestValidator.equals("registered customer email")(customer.email)(email);
  TestValidator.equals("registered customer nickname")(customer.nickname)(nickname);
  TestValidator.equals("registered customer status")(customer.status)("active");
  // Confirm auto-login by verifying Authorization header is present in connection.headers
  TestValidator.predicate("Authorization token issued")(
    typeof connection.headers === "object" &&
    typeof connection.headers["Authorization"] === "string" &&
    connection.headers["Authorization"].length > 0
  );

  // Step 2: Create a new active cart as the authenticated customer
  const cartBody: IShoppingMallAiBackendCart.ICreate = {
    status: "active",
    session_token: null, // Must be explicit null if not using guest/anonymous cart
  };

  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: cartBody
  });
  typia.assert(cart);
  TestValidator.equals("cart status is 'active'")(cart.status)("active");
  TestValidator.equals("cart session token null")(cart.session_token)(null);
  TestValidator.predicate("cart id is uuid")(typeof cart.id === "string" && cart.id.match(/^\w{8}-\w{4}-\w{4}-\w{4}-\w{12}$/));
  TestValidator.predicate("cart created_at is ISO8601")(typeof cart.created_at === "string" && !isNaN(Date.parse(cart.created_at)));
  TestValidator.predicate("cart updated_at is ISO8601")(typeof cart.updated_at === "string" && !isNaN(Date.parse(cart.updated_at)));
  if (cart.deleted_at !== undefined && cart.deleted_at !== null) {
    // If soft deletion ever returned, ensure it's ISO format
    TestValidator.predicate("deleted_at ISO8601")(typeof cart.deleted_at === "string" && !isNaN(Date.parse(cart.deleted_at)));
  }

  // Step 3: Attempt to create a second 'active' cart for the same customer
  TestValidator.error("Only one active cart per customer - duplication blocked")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
        body: {
          status: "active",
          session_token: null,
        }
      });
    }
  );
}

