import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test access control for the admin product inquiry detail endpoint.
 *
 * This test ensures that anonymous (unauthenticated) users are NOT able to access product inquiry details through the admin-only API endpoint. The logic simulates a seller registering and creating a product, a customer registering and posting a product inquiry, then attempts to access the admin product inquiry detail endpoint without authentication. The correct behavior is for the API to deny access and raise an authorization error.
 *
 * Steps:
 * 1. Register a seller.
 * 2. As the seller, create a product.
 * 3. Register a customer.
 * 4. As the customer, post a product inquiry for the product.
 * 5. Remove Authorization info from the connection to simulate anonymous access.
 * 6. Attempt to call the admin product inquiry detail API and confirm a permission denial error is raised.
 */
export async function test_api_admin_product_inquiry_detail_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register a seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerRegisterResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "!Test12345",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerRegisterResponse);
  const sellerId = sellerRegisterResponse.sellerId;

  // 2. As seller, create a product
  connection.headers.Authorization = sellerRegisterResponse.setHeaders.Authorization;
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.paragraph()(3),
      status: "published",
      description: RandomGenerator.content()()(),
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);
  const productId = product.id;

  // 3. Register a customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerRegisterResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "!Test54321",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerRegisterResponse);
  const customerId = customerRegisterResponse.customer.id;
  connection.headers.Authorization = customerRegisterResponse.setHeaders.Authorization;

  // 4. As customer, post a product inquiry
  const productInquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: productId,
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.content()()(),
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
  });
  typia.assert(productInquiry);

  // 5. Remove Authorization info (simulate anonymous access)
  delete connection.headers.Authorization;

  // 6. Attempt unauthorized admin endpoint access, expect denial
  await TestValidator.error("anonymous user should be denied admin product inquiry access")(
    () =>
      api.functional.shoppingMallAiBackend.admin.productInquiries.at(connection, {
        productInquiryId: productInquiry.id,
      }),
  );
}

