import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendPoint";
import type { IShoppingMallAiBackendPointHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendPointHistory";

/**
 * Validate admin update of point wallet transaction records for allowed metadata fields, audit logging, and error handling.
 *
 * This test simulates an admin updating a point transaction record. It covers:
 * 1. Creating a point wallet for a synthetic customer.
 * 2. Creating a point wallet history/transaction for that wallet.
 * 3. Performing a valid update to the remarks/audit field.
 * 4. Attempting to update a non-existent record (should error out).
 *
 * Steps:
 * 1. Generate synthetic customer UUID.
 * 2. Admin creates a new point wallet for that customer.
 * 3. Admin creates an initial point history record associated with above wallet.
 * 4. Admin successfully updates the remarks for that point history. Validate that the remarks field changes and other business fields are unchanged after update.
 * 5. Try to update a non-existent pointHistoryId. Assert error is thrown (runtime check only).
 */
export async function test_api_point_history_update_metadata_and_audit_logging(
  connection: api.IConnection,
) {
  // 1. Generate synthetic customer UUID
  const customerId = typia.random<string & tags.Format<"uuid">>();

  // 2. Admin creates a new point wallet for the customer
  const wallet = await api.functional.shoppingMallAiBackend.admin.points.create(connection, {
    body: {
      customer_id: customerId,
      balance: 0,
    } satisfies IShoppingMallAiBackendPoint.ICreate,
  });
  typia.assert(wallet);

  // 3. Admin creates a point history record for the wallet
  const history = await api.functional.shoppingMallAiBackend.admin.pointHistories.create(connection, {
    body: {
      point_wallet_id: wallet.id,
      change_type: "accrual",
      change_amount: 1000,
      balance_after: 1000,
      actor_type: "admin",
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      order_id: null,
      remarks: "Initial accrual",
    } satisfies IShoppingMallAiBackendPointHistory.ICreate,
  });
  typia.assert(history);

  // 4. Admin successfully updates the remarks for that history (allowed field only)
  const updated = await api.functional.shoppingMallAiBackend.admin.pointHistories.update(connection, {
    pointHistoryId: history.id,
    body: {
      remarks: "Updated by admin for audit reasons",
    } satisfies IShoppingMallAiBackendPointHistory.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("remarks updated")(updated.remarks)("Updated by admin for audit reasons");
  // All business fields except mutable remarks/created_at must be unchanged
  TestValidator.equals("immutable business fields remain")(
    {
      ...updated,
      remarks: undefined,
      created_at: undefined,
    },
    {
      ...history,
      remarks: undefined,
      created_at: undefined,
    },
  );

  // 5. Attempt update to non-existent pointHistoryId (should throw error)
  await TestValidator.error("non-existent pointHistoryId should error")(
    () =>
      api.functional.shoppingMallAiBackend.admin.pointHistories.update(
        connection,
        {
          pointHistoryId: typia.random<string & tags.Format<"uuid">>(),
          body: {
            remarks: "Update attempt on non-existent row",
          },
        },
      ),
  );
}

