 * 7. Attempt deleting a random non-existent address id (expect error: not found or similar).
 */
export async function test_api_customer_address_soft_delete_by_owner_and_forbidden_access(connection: api.IConnection) {
  // 1. Register new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const signUpRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpRes);
  const customer = signUpRes.customer;

  // 2. (NOTE: No API for creation; only search/list possible.)
  // For test, we assume there's at least one address already for the user.
  // 3. List addresses for the customer (should include at least one address)
  let listRes = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
    customerId: customer.id,
    body: {} satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(listRes);
  const [addressToDelete] = listRes.data;
  if (!addressToDelete) throw new Error("Expected at least one address for the customer");

  // 4. Delete the address as owner
  await api.functional.shoppingMallAiBackend.customer.customers.addresses.erase(connection, {
    customerId: customer.id,
    addressId: addressToDelete.id,
  });

  // 5. Verify soft-deleted address is gone from active address listings
  listRes = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
    customerId: customer.id,
    body: {} satisfies IShoppingMallAiBackendCustomerAddress.IRequest,
  });
  typia.assert(listRes);
  TestValidator.predicate("deleted address no longer listed")(
    listRes.data.every((addr: IShoppingMallAiBackendCustomerAddress) => addr.id !== addressToDelete.id)
  );

  // 6. Register a second customer
  const customer2Email = typia.random<string & tags.Format<"email">>();
  const signUpRes2 = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer2Email,
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpRes2);
  const customer2 = signUpRes2.customer;

  // 7. Attempt forbidden delete (second customer tries to delete first customer’s address)
  TestValidator.error("forbidden to delete another's address")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.addresses.erase(connection, {
      customerId: customer2.id,
      addressId: addressToDelete.id,
    });
  });

  // 8. Attempt to delete a non-existent address as owner (should return not found)
  TestValidator.error("deleting non-existent address fails")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.addresses.erase(connection, {
      customerId: customer.id,
      addressId: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

