import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerAddress";
import type { IPageIShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerAddress";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate customer address update functionality and permission enforcement.
 *
 * This test ensures that only the rightful customer can update their own address and
 * that the update endpoint enforces validation and security:
 *
 * 1. Registers and authenticates a new customer ("owner").
 * 2. Lists addresses for the owner; selects one to update.
 * 3. Successfully updates the recipient name for that address and confirms the change.
 * 4. Attempts to update with invalid input (blank name, bad phone format) and confirms errors occur.
 * 5. Attempts to update with missing required id and checks error thrown.
 * 6. Registers a second (intruder) customer and confirms they cannot update another customer's address.
 */
export async function test_api_customer_address_update_by_owner_and_permission_enforcement(
  connection: api.IConnection,
) {
  // 1. Register a new customer (owner)
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const customerSignUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: ownerEmail,
      password: "test-password-1234",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignUpResponse);
  const ownerCustomer = customerSignUpResponse.customer;
  const ownerCustomerId = ownerCustomer.id;

  // 2. List addresses for the owner and pick the first one for updating
  const addressListPage = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
    customerId: ownerCustomerId,
    body: {},
  });
  typia.assert(addressListPage);
  TestValidator.predicate("at least one address exists for new customer")(
    addressListPage.data.length > 0
  );
  const addressForUpdate = addressListPage.data[0];

  // 3. Successful update: change receiver_name and verify update
  const newReceiverName = RandomGenerator.name();
  const updatedAddress = await api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
    customerId: ownerCustomerId,
    body: {
      id: addressForUpdate.id,
      receiver_name: newReceiverName,
    },
  });
  typia.assert(updatedAddress);
  TestValidator.equals("receiver_name updated")(updatedAddress.receiver_name)(newReceiverName);
  TestValidator.equals("id unchanged")(updatedAddress.id)(addressForUpdate.id);

  // 4. Validation error: missing required id
  await TestValidator.error("missing required address id fails")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
      customerId: ownerCustomerId,
      // @ts-expect-error: purposely missing id field (runtime test only)
      body: {
        receiver_name: RandomGenerator.name(),
      } as any,
    })
  );

  // 4b. Blank receiver_name: invalid blank name
  await TestValidator.error("blank receiver_name fails")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
      customerId: ownerCustomerId,
      body: {
        id: addressForUpdate.id,
        receiver_name: "",
      },
    })
  );

  // 4c. Invalid receiver_phone
  await TestValidator.error("invalid receiver_phone fails")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
      customerId: ownerCustomerId,
      body: {
        id: addressForUpdate.id,
        receiver_phone: "not-a-phone-number",
      },
    })
  );

  // 5. Second customer attempts to update a different customer's address (should fail)
  const intruderEmail = typia.random<string & tags.Format<"email">>();
  const intruderSignUpResponse = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: intruderEmail,
      password: "other-password-5678",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(intruderSignUpResponse);
  const intruderCustomerId = intruderSignUpResponse.customer.id;

  await TestValidator.error("cannot update another customer's address")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
      customerId: intruderCustomerId,
      body: {
        id: addressForUpdate.id,
        receiver_name: RandomGenerator.name(),
      },
    })
  );
}

