import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IPageIShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrder";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderSnapshot";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate unauthorized access control for order snapshot creation by non-owning seller.
 *
 * Business context:
 * Ensures strict access separation: a seller (A) must not be able to create an order snapshot for an order they do not own (owned by seller B). This is critical for regulatory/audit purposes and business data integrity.
 *
 * Test steps:
 * 1. Register Seller A, obtain their credentials/JWT.
 * 2. Register Seller B, obtain their credentials/JWT.
 * 3. Using Seller B's credentials, ensure an order exists (pick one or random if empty list).
 * 4. Switch to Seller A's session.
 * 5. Attempt to create a snapshot for Seller B's order as Seller A — this should fail.
 * 6. Validate that access is denied (error is thrown).
 *
 * Note: Audit/compliance log check is omitted as there is no endpoint for this in provided APIs.
 */
export async function test_api_order_snapshot_creation_by_seller_unauthorized_non_owner(
  connection: api.IConnection,
) {
  // 1. Register Seller A (will NOT own the test order)
  const sellerAEmail: string = typia.random<string & tags.Format<"email">>();
  const sellerAReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerAReg);

  // 2. Register Seller B (the owner of the test order)
  const sellerBEmail: string = typia.random<string & tags.Format<"email">>();
  const sellerBReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "SellerBpwd!",
      companyName: RandomGenerator.name(),
      businessNumber: "9876543210",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerBReg);

  // 3. Use Seller B session: ensure there is at least one order available to simulate snapshot attempt
  connection.headers.Authorization = sellerBReg.setHeaders.Authorization;
  const ordersSummary = await api.functional.shoppingMallAiBackend.seller.orders.search(connection, {
    body: {} // No filters: list Seller B's orders (patch API matches doc, even if unusual)
  });
  typia.assert(ordersSummary);
  // If no order exists, simulate a random UUID (cannot create order—API not given)
  // In real-world E2E, recommend: create order via corresponding API before this step.
  const orderId: string & tags.Format<"uuid"> =
    ordersSummary.data.length > 0
      ? ordersSummary.data[0].id
      : typia.random<string & tags.Format<"uuid">>();

  // 4. Switch session to Seller A (unauthorized for given order)
  connection.headers.Authorization = sellerAReg.setHeaders.Authorization;

  // 5. Seller A attempts to create an order snapshot for Seller B's order (should fail)
  await TestValidator.error("unauthorized seller cannot create snapshot for other's order")(
    () =>
      api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.create(connection, {
        orderId,
        body: {
          snapshot_json: JSON.stringify({ test: "unauthorized_access_check" }),
          snapshot_reason: "Test Unauthorized Access",
        } satisfies IShoppingMallAiBackendOrderSnapshot.ICreate,
      }),
  );
}

