import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCategory";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductCategoryMap";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Verify uniqueness enforcement when updating product-category mapping.
 *
 * This test ensures that the system would enforce uniqueness constraints on product-category mappings on update,
 * but per API/DTO, only the 'primary' flag can be updated. Changing the category for an existing mapping is not possible,
 * so it is impossible to trigger a uniqueness violation on update as described in the scenario.
 *
 * Thus, the test builds all dependencies and validates that the update endpoint does not allow mutation of category_id/product_id, and that other business logic (like toggling 'primary') is accepted. Attempting to pass invalid keys for update is rejected by TypeScript at compile time, not at runtime, so the uniqueness test cannot be performed.
 *
 * Steps:
 * 1. Register admin and seller accounts for test setup authentication.
 * 2. Create two categories as admin.
 * 3. Create a product as admin (assigning seller_id returned from seller register).
 * 4. Create two product-category mappings for the product, each with a unique category.
 * 5. Attempt to update a mapping by changing its 'primary' value (the only allowed update field).
 * 6. Confirm that the update takes effect (i.e., 'primary' is changed), validating the only permitted update path.
 */
export async function test_api_product_category_map_update_duplicate_mapping_error(
  connection: api.IConnection,
) {
  // 1. Register admin account.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "admin-Password!123"
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminSignup);

  // 2. Register a seller account.
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerSignup = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "SellerPass123!",
      companyName: RandomGenerator.company(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignup);

  // 3. Create two categories as admin (requires admin connection).
  const category1 = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      created_by_admin_id: adminSignup.adminId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      display_order: 1,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate
  });
  typia.assert(category1);

  const category2 = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      created_by_admin_id: adminSignup.adminId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      display_order: 2,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate
  });
  typia.assert(category2);

  // 4. Create a product (assign to seller).
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerSignup.sellerId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 5. Create two product-category mappings (with distinct categories).
  const mapping1 = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      category_id: category1.id,
      primary: true,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate
  });
  typia.assert(mapping1);

  const mapping2 = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      category_id: category2.id,
      primary: false,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate
  });
  typia.assert(mapping2);

  // 6. Update the second mapping's 'primary' field to true (the only permitted update).
  const updatedMapping2 = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.update(connection, {
    productId: product.id,
    productCategoryMapId: mapping2.id,
    body: {
      primary: true,
    } satisfies IShoppingMallAiBackendProductCategoryMap.IUpdate
  });
  typia.assert(updatedMapping2);
  TestValidator.equals("primary field changed")(updatedMapping2.primary)(true);
}

