import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerExternalLink } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerExternalLink";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * E2E test to verify that customers cannot delete other customers' external links.
 *
 * This test checks for correct authorization logic by attempting cross-account deletion of an OAuth/social link. It confirms both the appropriate access-denied error and link persistence.
 *
 * Workflow:
 * 1. Register Customer A (the link owner) and capture their credentials/token
 * 2. Register Customer B (the attacker) and capture their credentials/token
 * 3. As Customer A, create an external link
 * 4. Switch to Customer B's context (using their credentials/token)
 * 5. Attempt to delete Customer A's external link as Customer B (should fail with access error)
 * 6. Verify the external link for Customer A still exists (was NOT deleted)
 */
export async function test_api_customer_external_link_delete_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register Customer A (owner of the external link)
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const ownerPassword = "Password123!";
  const ownerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: ownerEmail,
      password: ownerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(ownerSignUp);
  const ownerId = ownerSignUp.customer.id;

  // 2. Register Customer B (attempting attacker)
  const attackerEmail = typia.random<string & tags.Format<"email">>();
  const attackerPassword = "Password456!";
  const attackerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: attackerEmail,
      password: attackerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(attackerSignUp);

  // 3. As Customer A, create an external link
  const externalLink = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(connection, {
    customerId: ownerId,
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      provider: "github",
      external_id: RandomGenerator.alphaNumeric(16),
      linked_at: new Date().toISOString(),
      last_auth_at: new Date().toISOString(),
      metadata_json: null,
      deleted_at: null,
