import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IPageIShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCart";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test admin cart search endpoint handles invalid or malformed criteria gracefully.
 *
 * Business context: Admins may sometimes send request bodies with unknown or incorrectly typed fields to the PATCH /shoppingMallAiBackend/admin/carts endpoint (e.g., typo in filter name, wrong type (string instead of int for page/limit)). The API should validate incoming requests, return a validation error with proper description/code (e.g., 400 Bad Request), and avoid processing the request. The endpoint must not leak sensitive data or mistakenly accept/broadcast malformed queries. Auditing (error logging) is out of test scope and verified in service logs.
 *
 * Test Steps:
 * 1. Authenticate as admin using /auth/admin/login (dependency).
 * 2. Attempt to search carts with a request body containing an unrecognized field (e.g., {'foo': 'bar'}) and expect a runtime error.
 * 3. Attempt to search carts with a request body where 'page' is an invalid type (e.g., string instead of integer) and expect a runtime error.
 * 4. Verify both attempts raise errors and do NOT return a normal paginated cart result.
 */
export async function test_api_cart_admin_search_invalid_filter_error(connection: api.IConnection) {
  // Step 1: Admin login
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin-Test1!";
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignIn
  });
  typia.assert(adminLogin);

  // Step 2: Send search with unrecognized field
  await TestValidator.error("should reject unknown filter field")(() => {
    return api.functional.shoppingMallAiBackend.admin.carts.search(connection, {
      body: { ("foo" as any): "bar" } as any // throw at runtime only
    });
  });

  // Step 3: Send search with invalid data type for filter
  await TestValidator.error("should reject wrong type for page")(() => {
    return api.functional.shoppingMallAiBackend.admin.carts.search(connection, {
      body: { page: "not_a_number" as any } as any // throw at runtime only
    });
  });
}

