      parent_id: null,
      created_by_admin_id: admin.adminId,
      code: parentCode,
      name: parentName,
      description: "A parent category for hierarchy test.",
      display_order: 1,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(parent);

  // 3. Create child category
  const childCode = "child_" + RandomGenerator.alphaNumeric(8);
