import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that soft-deleted product bundles are excluded from the seller's product bundle listing/search results.
 *
 * This test performs the following steps end-to-end:
 * 1. Seller registers and receives authentication for creating/managing products and bundles.
 * 2. The seller creates a new product to act as the main product for bundles.
 * 3. Multiple (at least 3) product bundles are created and associated with the product as the seller.
 * 4. At least one of the created bundles is soft-deleted by calling the erase API.
 * 5. The seller searches for product bundles attached to the product using the search endpoint (PATCH with filters).
 * 6. The test verifies that soft-deleted product bundles do not appear in the search result and only non-deleted remain.
 *
 * This business rule is critical to ensure that listings shown for management and admin contexts do not display any soft-deleted bundles.
 *
 * Steps:
 * 1. Register seller and extract sellerId/jwt for authentication.
 * 2. Create a product as the seller; store returned productId.
 * 3. Create N bundles (N>=3), confirm their presence via search.
 * 4. Delete one bundle using the erase endpoint (soft delete mechanism).
 * 5. Perform product bundle search. Confirm response only includes non-deleted product bundles.
 * 6. Confirm that IDs/statuses of returned bundles match the expected set (the deleted one(s) is/are missing).
 */
export async function test_api_product_bundle_list_soft_deleted_excluded(connection: api.IConnection) {
  // 1. Seller registration
  const sellerData: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "securePassword123!",
    companyName: RandomGenerator.name(),
    businessNumber: RandomGenerator.alphaNumeric(10),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  };
  const sellerAuth = await api.functional.auth.seller.register.signUp(connection, { body: sellerData });
  typia.assert(sellerAuth);

  // 2. Create product
  const productCreate: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: sellerAuth.sellerId,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    main_image_uri: null,
    status: "active",
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: productCreate });
  typia.assert(product);

  // 3. Create 3 product bundles for this product
  const bundles: IShoppingMallAiBackendProductBundle[] = [];
  for (let i = 0; i < 3; ++i) {
    const bundleCreate: IShoppingMallAiBackendProductBundle.ICreate = {
      main_product_id: product.id,
      code: RandomGenerator.alphaNumeric(7) + i,
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      bundle_policy: null,
      bundle_price: null,
      status: "active",
    };
    const bundle = await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, { productId: product.id, body: bundleCreate });
    typia.assert(bundle);
    bundles.push(bundle);
  }

