import type { IPageIShoppingMallAiBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate the admin channel list search endpoint with authentication, diversified data setup, filter/pagination assertions, and soft delete exclusion.
 *
 * This test ensures admin users can retrieve and filter a paginated list of channels, validating business, RBAC, and search criteria for enterprise compliance.
 *
 * Steps:
 * 1. Admin login (JWT in headers)
 * 2. Create several diverse channels
 * 3. Search with various filters & pagination; verify results match filters and metadata is intact
 * 4. (Soft delete excluded as it's not directly available in this API shape)
 */
export async function test_api_channel_list_search_admin_success(connection: api.IConnection) {
  // 1. Admin login to get credentials and adminId for test - ensure JWT syncs into connection headers
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPW123!";
  // Assumes this admin is present according to test scenario setup/guidance
  const adminJwt = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminJwt);
  connection.headers = { ...connection.headers, Authorization: adminJwt.setHeaders.Authorization };

  // 2. Create several channels (with different names, codes, status)
  const channelA = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: "PARTNER001",
      name: "Blue Part Channel",
      created_by_admin_id: adminJwt.adminId,
      description: "Blue partner's sales channel",
      logo_url: "https://brand.example.com/logo-blue.png",
      active: true,
    },
  });
  typia.assert(channelA);

  const channelB = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: "PARTNER002",
      name: "Red Part Channel",
      created_by_admin_id: adminJwt.adminId,
      description: "Red partner's sales arm",
      logo_url: "https://brand.example.com/logo-red.png",
      active: false,
    },
  });
  typia.assert(channelB);

  const channelC = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: "UNIQUE003",
      name: "Green Vert Channel",
      created_by_admin_id: adminJwt.adminId,
      description: null,
      logo_url: null,
      active: true,
    },
  });
  typia.assert(channelC);

  // 3a. Search by partial name
  const nameRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { name: "Part", page: 1, limit: 10 },
  });
  typia.assert(nameRes);
  for (const s of nameRes.data) TestValidator.predicate("name contains 'Part'")(s.name.includes("Part"));

  // 3b. Filter by code (exact)
  const codeRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { code: "PARTNER002" },
  });
  typia.assert(codeRes);
  TestValidator.equals("one PARTNER002 result")(codeRes.data.length)(1);
  TestValidator.equals("code matches")(codeRes.data[0].code)("PARTNER002");

  // 3c. Filter by activation status (inactive)
  const inactiveRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { active: false },
  });
  typia.assert(inactiveRes);
  for (const s of inactiveRes.data) TestValidator.equals("inactive only")(s.active)(false);

  // 3d. Filter by creator (adminId)
  const creatorRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { created_by_admin_id: adminJwt.adminId },
  });
  typia.assert(creatorRes);
  for (const s of creatorRes.data) TestValidator.equals("created_by_admin_id matches")(s.created_by_admin_id)(adminJwt.adminId);

  // 3e. Combine filters (active + name partial)
  const combineRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { active: true, name: "Vert" },
  });
  typia.assert(combineRes);
  for (const s of combineRes.data) {
    TestValidator.equals("active & Vert")(s.active)(true);
    TestValidator.predicate("name contains 'Vert'")(s.name.includes("Vert"));
  }

  // 3f. Pagination (limit=2)
  const pagedRes = await api.functional.shoppingMallAiBackend.admin.channels.search(connection, {
    body: { limit: 2, page: 1 },
  });
  typia.assert(pagedRes);
  TestValidator.predicate("limit respected")(pagedRes.data.length <= 2);
  TestValidator.predicate("pagination object")(typeof pagedRes.pagination.current === "number");

  // 4. Soft delete exclusion cannot be tested without a delete API
}

