import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderItem";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate the addition of an order item by a customer to their own order.
 *
 * Ensures an authenticated customer can add a new order item to an existing order, referencing a valid product and meeting all business rules.
 *
 * Steps performed:
 * 1. Register and login a seller (for product creation; maintains role separation).
 * 2. Register and login a customer (who will own the order).
 * 3. Seller creates a new product for sale (ensures valid product_id for order item).
 * 4. Customer creates a new order (with no items yet).
 * 5. Customer adds an order item to their order, specifying valid product and order linkage (quantity, price, snapshot, etc.).
 * 6. Assertions verify correct linkage (order_id, product_id, price, currency), presence of snapshot, and correctness of major business fields.
 */
export async function test_api_order_item_add_success_customer(connection: api.IConnection) {
  // 1. Register & login seller (for product creation)
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "s3ll3rP@ssw0rd";
  const companyName = RandomGenerator.name();
  const sellerReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName,
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerReg);
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    },
  });

  // 2. Register & login customer (order owner)
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "cust0m3rP@ss";
  const customerReg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
