import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSearchKeyword } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSearchKeyword";
import type { IPageIShoppingMallAiBackendProductSearchKeyword } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductSearchKeyword";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that a seller cannot search product keywords for a product they do not own.
 *
 * This test covers the business rule that sellers must only be able to search (list/filter)
 * search keywords for products that they own. If a seller attempts to use the API to search
 * for keywords on another seller's product (by specifying a non-owned product ID), the 
 * operation should be forbidden, and the server must deny access (throwing a permission
 * denied or forbidden error).
 *
 * Step-by-step process:
 * 1. Register two distinct sellers (Seller A and Seller B).
 * 2. Seller A creates a product (Product X).
 * 3. Seller B attempts to search keywords on Product X (which is owned by Seller A).
 * 4. Assert the operation is forbidden (permission denied).
 */
export async function test_api_product_search_keyword_search_unauthorized_by_seller(
  connection: api.IConnection,
) {
  // 1. Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "SellerA-Secret1!",
      companyName: RandomGenerator.name(),
      businessNumber: typia.random<string>(),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerAResponse);

  // 2. Register Seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "SellerB-Secret2!",
      companyName: RandomGenerator.name(),
      businessNumber: typia.random<string>(),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerBResponse);

  // 3. As Seller A, create a product (Product X)
  connection.headers.Authorization = sellerAResponse.setHeaders.Authorization;
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAResponse.sellerId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      status: "published",
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 4. Attempt to search keywords for Product X as Seller B (expect forbidden)
  connection.headers.Authorization = sellerBResponse.setHeaders.Authorization;
  await TestValidator.error("Seller B must not be able to search Product X's keywords")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.searchProductSearchKeywords(
        connection,
        {
          productId: product.id,
          body: {
            product_id: product.id,
            page: 1,
            limit: 10,
          } satisfies IShoppingMallAiBackendProductSearchKeyword.IRequest,
        },
      );
    },
  );
}

