import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSellerBusinessVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSellerBusinessVerification";
import type { IPageIShoppingMallAiBackendSellerBusinessVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSellerBusinessVerification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that searching for business verification records as an unauthorized user (without authentication) does not succeed and does not return sensitive data.
 *
 * This test simulates an attempt to fetch a seller's business verification records via the PATCH endpoint as an unauthenticated actor. It first creates a seller account (dependency step) to ensure the seller exists, but then clears authentication context to simulate search from an unauthorized perspective.
 *
 * 1. Register a new seller using the public registration endpoint.
 * 2. Attempt to search business verification records for this seller (using their ID) without authentication.
 * 3. Assert that an authorization error occurs and that no sensitive data is returned in the response.
 *
 * The test ensures that only authorized actors (the seller themselves or a platform admin) can access seller KYC/business compliance submissions, in accordance with platform security and privacy requirements.
 */
export async function test_api_seller_business_verifications_search_unauthorized(connection: api.IConnection) {
  // 1. Register a new seller (with valid business and contact info)
  const signUpResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "A_securePassword123!",
      companyName: RandomGenerator.name(),
      businessNumber: (
        typia.random<number & tags.Pattern<"^[0-9]{10}$">>() as unknown as string
      ),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Simulate unauthorized search by clearing Authorization header
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: { ...connection.headers, Authorization: undefined },
  };

  // 3. Attempt to search business verification records for the registered seller, expect authorization error
  await TestValidator.error("Unauthorized search should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.search(
        unauthConnection,
        {
          sellerId: signUpResponse.sellerId,
          body: {},
        },
      );
    },
  );
}

