import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCategory";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test admin category creation: valid creation, duplicate rejection, parent_id validation, non-admin permission enforcement.
 *
 * This E2E test verifies the business logic and authorization of the shopping mall category creation API for the admin backend. It covers:
 *   1. A valid admin creates a root category and all persisted fields match input.
 *   2. Creating a duplicate code is correctly rejected.
 *   3. Using a nonexistent parent_id fails with error.
 *   4. Non-admin actors cannot create categories.
 *
 * Step-by-step process:
 * 1. Register an admin; capture JWT and adminId from the response.
 * 2. Use this admin to create an initial category (with no parent_id).
 *    - Confirm fields returned (code, name, created_by_admin_id, etc.) match inputs.
 * 3. Attempt to create a category with duplicate code (expect error).
 * 4. Attempt to create a category with an invalid parent_id (expect error).
 * 5. Attempt to create a category using a fresh unauthenticated connection (no admin JWT; expect permission error).
 */
export async function test_api_category_creation_valid_duplicate_and_invalid_parent(connection: api.IConnection) {
  // 1. Register a new admin and retrieve JWT profile
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const signUpResp: IAdminAuth.JwtWithProfile = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(signUpResp);
  const adminId = signUpResp.adminId;

  // 2. Admin creates a new root category (no parent_id)
  // Use a unique code
  const uniqueCode = RandomGenerator.alphaNumeric(8);
  const inputCategory: IShoppingMallAiBackendCategory.ICreate = {
    code: uniqueCode,
    name: RandomGenerator.name(),
    description: RandomGenerator.content()()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    visible: true,
    created_by_admin_id: adminId,
    parent_id: null // root category
  };
  const created: IShoppingMallAiBackendCategory = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: inputCategory
  });
  typia.assert(created);
  // Assert critical fields match
  TestValidator.equals("code matches")(created.code)(inputCategory.code);
  TestValidator.equals("name matches")(created.name)(inputCategory.name);
  TestValidator.equals("created_by_admin_id matches")(created.created_by_admin_id)(adminId);
  TestValidator.equals("parent_id matches")(created.parent_id)(null);
  TestValidator.equals("visible matches")(created.visible)(inputCategory.visible);
  TestValidator.equals("display_order matches")(created.display_order)(inputCategory.display_order);
  if (typeof inputCategory.description === "string")
    TestValidator.equals("description matches")(created.description)(inputCategory.description);

  // 3. Attempt to create category with the same code (should fail)
  const dupInput: IShoppingMallAiBackendCategory.ICreate = {
    code: uniqueCode, // same code
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    visible: true,
    created_by_admin_id: adminId
  };
  await TestValidator.error("duplicate code should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
      body: dupInput
    });
  });

  // 4. Attempt to create with invalid parent_id (should fail)
  const invalidParentId = typia.random<string & tags.Format<"uuid">>();
  const invalidParentInput: IShoppingMallAiBackendCategory.ICreate = {
    code: RandomGenerator.alphaNumeric(9),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    visible: true,
    created_by_admin_id: adminId,
    parent_id: invalidParentId
  };
  await TestValidator.error("invalid parent_id should fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
      body: invalidParentInput
    });
  });

  // 5. Try category creation as non-admin (simulate by using a fresh plain connection)
  const plainInput: IShoppingMallAiBackendCategory.ICreate = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    visible: true,
    created_by_admin_id: adminId // This is technically still the admin's UUID, but the JWT is missing
  };
  // Remove/set empty Authorization header to simulate non-admin (no JWT)
  const plainConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("non-admin should be denied")(async () => {
    await api.functional.shoppingMallAiBackend.admin.categories.createCategory(plainConnection, {
      body: plainInput
    });
  });
}

