 * 2. Create a new order snapshot for a random order
 * 3. Update only the allowed field (snapshot_reason) and confirm change
 * 4. Attempt to update forbidden/immutable fields (snapshot_json, order_id) using an unsafe dynamic object (simulating outside-type request); expect a business/validation error.
 */
export async function test_api_order_snapshot_update_attempt_on_immutable_fields_raises_error(connection: api.IConnection) {
  // Step 1: Register a new admin (dependency setup)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "test1234!";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);

  // Step 2: Create a new order snapshot for a random order
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const snapshotCreateBody = {
    snapshot_json: JSON.stringify({ item: "shoes", total: 120 } as Record<string, unknown>),
    snapshot_reason: "created", // valid reason
  } satisfies IShoppingMallAiBackendOrderSnapshot.ICreate;
  const snapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.create(connection, {
    orderId,
    body: snapshotCreateBody,
  });
  typia.assert(snapshot);
  TestValidator.equals("order id on snapshot")(snapshot.order_id)(orderId);

  // Step 3: Update only allowed field (snapshot_reason)
  const allowedUpdateReason = "qualified compliance edit";
  const allowedUpdate = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.update(connection, {
    orderId,
    orderSnapshotId: snapshot.id,
    body: { snapshot_reason: allowedUpdateReason } satisfies IShoppingMallAiBackendOrderSnapshot.IUpdate,
  });
  typia.assert(allowedUpdate);
  TestValidator.equals("allowed snapshot_reason update")(allowedUpdate.snapshot_reason)(allowedUpdateReason);
  TestValidator.equals("order id unchanged")(allowedUpdate.order_id)(orderId);
  TestValidator.equals("snapshot_json unchanged")(allowedUpdate.snapshot_json)(snapshot.snapshot_json);

  // Step 4: Attempt to update immutable fields (must fail at business logic layer)
  await TestValidator.error("should fail to mutate immutable fields")(
    async () => {
      // Send deliberately extra fields via runtime-constructed object
      const invalidBody = {
        snapshot_reason: "illegal mutation attempt",
        snapshot_json: "this should not be accepted",
        order_id: typia.random<string & tags.Format<"uuid">>(),
      } as unknown as IShoppingMallAiBackendOrderSnapshot.IUpdate;
      await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.update(connection, {
        orderId,
        orderSnapshotId: snapshot.id,
        body: invalidBody,
      });
    }
  );
}

