import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrderGroup } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderGroup";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin order group detail retrieval and access error handling.
 *
 * This test ensures an authenticated admin can successfully fetch all details for an order group by its ID, including admin-only fields. It also covers negative scenarios: fetch with a random/nonexistent UUID (expect not found error), fetch with an invalid UUID format (should result in validation or bad request error), and attempt to fetch without admin privileges (expect forbidden/unauthorized). Business logic should ensure such detail access triggers audit logging (verifiable only if an API/audit field exists). The full admin authentication and resource setup must be performed.
 *
 * Steps:
 * 1. Authenticate as an admin (using API with known/valid credentials).
 * 2. Create an order group (admin-only privilege).
 * 3. Retrieve group details as admin – confirm all fields (including admin/metadata fields).
 * 4. Attempt to retrieve group using a random (nonexistent) UUID – expect not found.
 * 5. Attempt to retrieve group with an invalid UUID format – expect error (bad request/validation).
 * 6. Attempt to retrieve group without admin authentication (simulate insufficient permission) – expect forbidden/unauthorized.
 */
export async function test_api_admin_order_group_detail_retrieval_errors(
  connection: api.IConnection,
) {
  // 1. Admin authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234";
  const adminSignin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminSignin);
  connection.headers = {
    ...connection.headers,
    Authorization: adminSignin.setHeaders.Authorization,
  };

  // 2. Create order group
  const groupCreateInput = {
    group_name: "Test Group",
    external_reference: "integration-" + Math.random().toString(36).substring(2, 8),
    meta_info: '{"test":true}',
  } satisfies IShoppingMallAiBackendOrderGroup.ICreate;
  const orderGroup = await api.functional.shoppingMallAiBackend.admin.orderGroups.create(connection, {
    body: groupCreateInput,
  });
  typia.assert(orderGroup);

  // 3. Retrieve order group details as admin
  const fetchedGroup = await api.functional.shoppingMallAiBackend.admin.orderGroups.at(connection, {
    orderGroupId: orderGroup.id,
  });
  typia.assert(fetchedGroup);
  TestValidator.equals("group equality")(fetchedGroup)(orderGroup);

  // 4. Attempt with random/nonexistent UUID – should return not found error
  await TestValidator.error("Not found error for random UUID")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orderGroups.at(connection, {
        orderGroupId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 5. Attempt with invalid UUID format
  await TestValidator.error("Validation error for invalid UUID format")(
    async () => {
      // @ts-expect-error: intentionally using an invalid format
      await api.functional.shoppingMallAiBackend.admin.orderGroups.at(connection, {
        orderGroupId: "not-a-uuid",
      });
    },
  );

  // 6. Attempt to fetch without admin authentication
  const unauthConn = { ...connection, headers: {} };
  await TestValidator.error("Forbidden/unauthorized without admin auth")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orderGroups.at(unauthConn, {
        orderGroupId: orderGroup.id,
      });
    },
  );
}

