import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendIssuedCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendIssuedCoupon";
import type { IShoppingMallAiBackendCouponHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponHistory";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin creation of coupon history (audit) events in the shopping mall backend.
 *
 * This test covers the following scenarios:
 * 1. Admin can successfully create a coupon history event for an existing issued coupon when all required fields are valid.
 * 2. Attempting to create a coupon history with a non-existent issued_coupon_id or invalid action/actor_type should result in a runtime business validation error.
 * 3. Attempting to create a coupon history event while unauthorized (not logged in as admin) should return a permission error.
 *
 * Step-by-step business process:
 * 1. Authenticate as an admin using /auth/admin/login to obtain JWT.
 * 2. Issue a coupon by calling /shoppingMallAiBackend/admin/issuedCoupons to create an issued coupon. This is required as a reference (valid issued_coupon_id) for the coupon history event.
 * 3. Create a valid coupon history event for the issued coupon by calling /shoppingMallAiBackend/admin/couponHistories. Use typical fields (e.g. actor_type: "admin", action: "issued") and validate persistence.
 * 4. Try to use a non-existent issued_coupon_id and check that an error occurs.
 * 5. Try to create a coupon history event with invalid actor_type or action, expecting a runtime validation or business error.
 * 6. Log out (clear admin JWT/Authorization), then attempt to create a coupon history event to expect a permission error.
 */
export async function test_api_coupon_history_create_success_and_invalid(
  connection: api.IConnection,
) {
  // 1. Admin authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SuperSecret123!";

  // Assumes test environment is seeded with this admin (login attempt)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);
  // SDK should set JWT automatically

  // 2. Issue a coupon
  const couponTemplateId = typia.random<string & tags.Format<"uuid">>();
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const issuedCoupon = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.create(connection, {
    body: {
      coupon_template_id: couponTemplateId,
      customer_id: customerId,
      code: RandomGenerator.alphaNumeric(12),
      expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24 * 30).toISOString(),
      status: "issued",
    } satisfies IShoppingMallAiBackendIssuedCoupon.ICreate,
  });
  typia.assert(issuedCoupon);

  // 3. Create a valid coupon history event
  const now = new Date().toISOString();
  const couponHistory = await api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
    body: {
      issued_coupon_id: issuedCoupon.id,
      actor_id: adminLogin.adminId,
      actor_type: "admin",
      action: "issued",
      action_at: now,
      remarks: "Initial issuance audit.",
    } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
  });
  typia.assert(couponHistory);
  TestValidator.equals("issued_coupon_id")(couponHistory.issued_coupon_id)(issuedCoupon.id);
  TestValidator.equals("actor_type")(couponHistory.actor_type)("admin");
  TestValidator.equals("action")(couponHistory.action)("issued");

  // 4. Non-existent issued_coupon_id (should fail)
  await TestValidator.error("invalid issued_coupon_id")(() =>
    api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
      body: {
        issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
        actor_id: adminLogin.adminId,
        actor_type: "admin",
        action: "issued",
        action_at: now,
      } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
    })
  );

  // 5. Invalid action or actor_type (should fail)
  await TestValidator.error("invalid action value")(() =>
    api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
      body: {
        issued_coupon_id: issuedCoupon.id,
        actor_id: adminLogin.adminId,
        actor_type: "admin",
        action: "not_a_valid_action",
        action_at: now,
      } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
    })
  );
  await TestValidator.error("invalid actor_type value")(() =>
    api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
      body: {
        issued_coupon_id: issuedCoupon.id,
        actor_id: adminLogin.adminId,
        actor_type: "robot",
        action: "issued",
        action_at: now,
      } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
    })
  );

  // 6. Attempt as unauthorized user (logout scenario)
  connection.headers.Authorization = undefined; // Simulate logout if SDK/session supports explicit clearance
  await TestValidator.error("unauthorized create should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.couponHistories.create(connection, {
      body: {
        issued_coupon_id: issuedCoupon.id,
        actor_id: adminLogin.adminId,
        actor_type: "admin",
        action: "issued",
        action_at: now,
      } satisfies IShoppingMallAiBackendCouponHistory.ICreate,
    })
  );
}

