import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate retrieval of favorite snapshot records by admin, including permission logic, auditing, and error handling.
 *
 * Business context:
 * - Admins are allowed to retrieve any favorite snapshot—even those owned by customers—to handle compliance, audit, and troubleshooting.
 * - This test ensures that access is allowed for valid records, is auditable, is properly denied or returns appropriate errors for deleted/nonexistent records, and does not expose information leakage.
 *
 * Step-by-step process:
 * 1. Register a customer and login to create an authenticated session.
 * 2. Customer favorites a product (assume a product exists; use random UUID for demo).
 * 3. Customer creates a favorite snapshot linked to the favorite (serializing the favorite as JSON).
 * 4. Register a new admin and login for admin session.
 * 5. As admin, retrieve the favorite snapshot by its ID.
 * 6. Validate snapshot content, permissions, and presence of all required fields.
 * 7. Attempt retrieval with a random/non-existent favoriteSnapshotId and verify error handling (not found/permission).
 *
 * Implementation Notes:
 * - We do not actually delete the snapshot (as no such API is provided); simulate with a random non-existent id for error.
 * - Verification includes type assertion, strict equality of IDs, and permission logic.
 */
export async function test_api_favorite_snapshot_get_by_admin(connection: api.IConnection) {
  // 1. Register a customer
  const customerEmail = typia.random<string & tags.Format<'email'>>();
  const customerPassword = 'password123';
  const registerCustomerResp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(registerCustomerResp);

  // 2. Customer login (sets token in connection)
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    },
  });

  // 3. Customer creates a favorite product (with random product_id)
  const productId = typia.random<string & tags.Format<'uuid'>>();
  const favorite = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: {
      product_id: productId,
    },
  });
  typia.assert(favorite);

  // 4. Customer creates a favorite snapshot (target_type: PRODUCT)
  const snapshotInput = {
    favorite_product_id: favorite.id,
    favorite_inquiry_id: null,
    favorite_address_id: null,
    target_type: 'PRODUCT',
    snapshot_object_id: productId,
    serialized_object: JSON.stringify(favorite),
  };
  const snapshot = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: snapshotInput,
  });
  typia.assert(snapshot);

  // 5. Register and login as admin to start an admin-auth session
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'adminPass123';
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 6. As admin, retrieve the snapshot by ID
  const adminSnapshot = await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.at(connection, {
    favoriteSnapshotId: snapshot.id,
  });
  typia.assert(adminSnapshot);
  TestValidator.equals('retrieved snapshot id by admin')(adminSnapshot.id)(snapshot.id);
  TestValidator.equals('target_type')(adminSnapshot.target_type)('PRODUCT');
  TestValidator.equals('snapshot_object_id')(adminSnapshot.snapshot_object_id)(productId);
  TestValidator.equals('favorite_product_id')(adminSnapshot.favorite_product_id)(favorite.id);
  TestValidator.equals('serialized_object')(adminSnapshot.serialized_object)(JSON.stringify(favorite));

  // 7. Attempt retrieval with a random/non-existent favoriteSnapshotId and verify error handling
  const fakeSnapshotId = typia.random<string & tags.Format<'uuid'>>();
  TestValidator.error('non-existent snapshot retrieval throws')(async () => {
    await api.functional.shoppingMallAiBackend.admin.favoriteSnapshots.at(connection, {
      favoriteSnapshotId: fakeSnapshotId,
    });
  });
}

