import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerExternalLink } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerExternalLink";
import type { IPageIShoppingMallAiBackendCustomerExternalLink } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerExternalLink";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate customer external link list self-service with permission enforcement
 *
 * This test ensures customer can retrieve a paginated, filtered list of their own external authentication links and cannot access others'.
 *
 * Steps:
 * 1. Register customerA and customerB
 * 2. As customerA, search own external links (no filter):
 *    - Assert response structure and ownership
 *    - Page, limit, data expected per schema
 * 3. As customerA, repeat search with filters (provider, date range, deleted only, pagination, sorting)
 * 4. As customerA, attempt to retrieve links for customerB (permission should be denied or empty)
 * 5. As customerB, repeat self-search to confirm symmetric enforcement
 *
 * Note: Cannot actually create or delete links (no such endpoint provided), so only validate reading/search permission and pagination/filter logic.
 */
export async function test_api_customer_external_link_self_paginated_search_and_permission_enforcement(connection: api.IConnection) {
  // Register customerA
  const emailA = typia.random<string & tags.Format<"email">>();
  const respA = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: emailA,
      password: "Passw0rd!A",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(10),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(respA);
  const customerA = respA.customer;
  // The connection is now authenticated as customerA (via setHeaders)

  // Register customerB
  const emailB = typia.random<string & tags.Format<"email">>();
  // Use a new connection instance or manually swap header for test isolation
  const respB = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: emailB,
      password: "Passw0rd!B",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(10),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(respB);
  const customerB = respB.customer;

  // Helper to swap connection's Authorization to customerA
  async function switchToA() {
    // Re-authorize as customerA if needed (simulate login if such endpoint exists)
    connection.headers.Authorization = respA.setHeaders.Authorization;
  }
  // Helper to swap to customerB
  async function switchToB() {
    connection.headers.Authorization = respB.setHeaders.Authorization;
  }

  // --- As customerA, list own external links, no filter ---
  await switchToA();
  const pageA1 = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.search(connection, {
    customerId: customerA.id,
    body: {},
  });
  typia.assert(pageA1);
  // Each returned link must belong to customerA only
  for (const link of pageA1.data) {
    TestValidator.equals("customer_id == A")(link.customer_id)(customerA.id);
    TestValidator.equals("deleted is null")(link.deleted_at)(null);
  }

  // --- As customerA, filter by provider (random text, likely to yield empty set) ---
  await switchToA();
  const byProvider = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.search(connection, {
    customerId: customerA.id,
    body: {
      provider: RandomGenerator.alphabets(8),
    },
  });
  typia.assert(byProvider);
  for (const link of byProvider.data) {
    TestValidator.equals("customer_id == A")(link.customer_id)(customerA.id);
    TestValidator.equals("provider matches")(link.provider)(byProvider.body.provider);
  }

  // --- As customerA, filter by non-existing date range (far future, expect empty set) ---
  await switchToA();
  const byDate = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.search(connection, {
    customerId: customerA.id,
    body: {
      linked_at_from: "2099-01-01T00:00:00.000Z",
      linked_at_to: "2099-12-31T23:59:59.999Z",
    },
  });
  typia.assert(byDate);
  TestValidator.equals("future date yields no links")(byDate.data.length)(0);

  // --- As customerA, filter deleted=true (should be empty/none if none exist) ---
  await switchToA();
  const deletedOnly = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.search(connection, {
    customerId: customerA.id,
    body: { deleted: true },
  });
  typia.assert(deletedOnly);
  for (const link of deletedOnly.data) {
    TestValidator.predicate("deleted_at is not null")(!!link.deleted_at);
  }

  // --- As customerA, paginate (limit=1) ---
  await switchToA();
  const paged = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.search(connection, {
    customerId: customerA.id,
    body: { limit: 1, page: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("pagination current page")(paged.pagination.current)(1);
  TestValidator.equals("pagination limit")(paged.pagination.limit)(1);
  // At most 1 item in data
  TestValidator.predicate("max one item")(paged.data.length <= 1);

  // --- As customerA, sort ascending (if present, order by linked_at) ---
  await switchToA();
  const sortedAsc = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.search(connection, {
    customerId: customerA.id,
    body: { sort: "linked_at", direction: "asc" },
  });
  typia.assert(sortedAsc);
  // Ascending order check
  for (let i = 1; i < sortedAsc.data.length; ++i) {
    TestValidator.predicate("ascending order")(sortedAsc.data[i].linked_at >= sortedAsc.data[i - 1].linked_at);
  }

  // --- As customerA, attempt to view customerB's links (permission denied or empty set) ---
  await switchToA();
  await TestValidator.error("should deny access to other's links")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.search(connection, {
      customerId: customerB.id,
      body: {},
    });
  });

  // --- As customerB, self-search (should succeed, and owner is customerB) ---
  await switchToB();
  const pageB1 = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.search(connection, {
    customerId: customerB.id,
    body: {},
  });
  typia.assert(pageB1);
  for (const link of pageB1.data) {
    TestValidator.equals("customer_id == B")(link.customer_id)(customerB.id);
  }
}

