import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductCategoryMap";
import type { IPageIShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductCategoryMap";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test searching and paginating product-category mappings for a seller's own product.
 *
 * This scenario confirms that a seller can only see category mappings for products they own and that pagination and result filters work as intended. It also checks that access is denied for non-owners and no results are returned if no mappings exist for a product.
 *
 * 1. Register Seller A and log in (obtain credentials).
 * 2. Use Seller A's credentials to create a product.
 * 3. Seller A maps the product to multiple (at least 3) categories using the productCategoryMap creation API (with at least one marked primary, the others secondary).
 * 4. Search with product's ID and confirm all mappings appear (full list).
 * 5. Use pagination (limit = 2, page = 1, page = 2) and verify paging meta and correct splits.
 * 6. Search with category_id and/or primary=true filtering – verify accuracy.
 * 7. Register Seller B and log in as B.
 * 8. Seller B attempts to search mappings for A's product (should yield access denied or empty list).
 * 9. Create a second product for Seller B (but no category mappings). Seller B queries its mappings (should get empty list).
 */
export async function test_api_product_category_map_search_by_seller_success(connection: api.IConnection) {
  // 1. Register Seller A
  const signUpA = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpA);
  const sellerAId = signUpA.sellerId;

  // 2. Create a product for Seller A
  connection.headers.Authorization = signUpA.setHeaders.Authorization;
  const productA = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productA);

  // Generate dummy unique category UUIDs
  const categoryA1 = typia.random<string & tags.Format<"uuid">>();
  const categoryA2 = typia.random<string & tags.Format<"uuid">>();
  const categoryA3 = typia.random<string & tags.Format<"uuid">>();

  // 3. Seller A maps product to 3 categories (1 primary, 2 secondary)
  const map1 = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      category_id: categoryA1,
      primary: true,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
  });
  typia.assert(map1);
  const map2 = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      category_id: categoryA2,
      primary: false,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
  });
  typia.assert(map2);
  const map3 = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      category_id: categoryA3,
      primary: false,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
  });
  typia.assert(map3);

  // 4. Search (list all mappings for productA)
  const pageAll = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connection, {
    productId: productA.id,
    body: {
      product_id: productA.id,
    },
  });
  typia.assert(pageAll);
  TestValidator.equals("all mappings for productA")(pageAll.data.length)(3);
  TestValidator.predicate("all categories present")(pageAll.data.every(x => [categoryA1, categoryA2, categoryA3].includes(x.category_id)));

  // 5. Pagination: limit 2, page 1 & 2
  const page1 = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connection, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      limit: 2,
      page: 1,
    },
  });
  typia.assert(page1);
  TestValidator.equals("page 1 data length")(page1.data.length)(2);
  TestValidator.equals("pagination current page")(page1.pagination.current)(1);

  const page2 = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connection, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      limit: 2,
      page: 2,
    },
  });
  typia.assert(page2);
  TestValidator.equals("page 2 data length")(page2.data.length)(1);
  TestValidator.equals("pagination current page")(page2.pagination.current)(2);

  // 6. Search filter: category_id and primary=true
  const filterCategory = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connection, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      category_id: categoryA2,
    },
  });
  typia.assert(filterCategory);
  TestValidator.equals("category_id filter count")(filterCategory.data.length)(1);
  TestValidator.equals("filtered is map2")(filterCategory.data[0].id)(map2.id);

  const filterPrimary = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connection, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      primary: true,
    },
  });
  typia.assert(filterPrimary);
  TestValidator.equals("primary filter count")(filterPrimary.data.length)(1);
  TestValidator.equals("filtered is primary")(filterPrimary.data[0].category_id)(categoryA1);

  // 7. Register Seller B
  const signUpB = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpB);
  const sellerBId = signUpB.sellerId;

  // 8. Seller B tries to access A's product mappings (should be denied or empty)
  connection.headers.Authorization = signUpB.setHeaders.Authorization;
  const nonOwnerSearch = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connection, {
    productId: productA.id,
    body: {
      product_id: productA.id,
    },
  });
  typia.assert(nonOwnerSearch);
  TestValidator.equals("non-owner has no mappings")(nonOwnerSearch.data.length)(0);

  // 9. Seller B's own product, no mappings
  const productB = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerBId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productB);
  const noMappings = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connection, {
    productId: productB.id,
    body: {
      product_id: productB.id,
    },
  });
  typia.assert(noMappings);
  TestValidator.equals("no mappings for sellerB")(noMappings.data.length)(0);
}

