import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachment";
import type { IShoppingMallAiBackendAttachmentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachmentLog";
import type { IPageIShoppingMallAiBackendAttachmentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAttachmentLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test: Validate log search for attachment (admin only) with pagination/filtering
 *
 * Business context:
 * Attachment audit log search is security-critical. Admins must be able to search event logs
 * for a given attachment file, filtering by business event, date, operator, and paging. Result
 * must always be for the correct attachment, only include valid logs (exclude soft-deleted ones),
 * and supply correct pagination meta.
 *
 * Steps:
 * 1. Create a new attachment as admin
 * 2. Create multiple log entries (upload, download, access) for that attachment with different event_types, contexts, and timestamps
 * 3. Search logs for the attachment:
 *    a. Without filter (should see all logs)
 *    b. Filtering by event_type
 *    c. Pagination (pageSize)
 *    d. Date/time range filter
 *    e. Edge: filter with no matches
 * 4. Validate every result has the correct attachment_id and no soft-deletion
 * 5. Validate all pagination metadata on response
 * 6. Error case: invalid attachmentId
 * 7. Error case: malformed filter (bad date)
 */
export async function test_api_attachment_log_search_basic_pagination_filtering(connection: api.IConnection) {
  // 1. Create a new attachment as admin
  const attachment = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, {
    body: {
      owner_id: typia.random<string & tags.Format<'uuid'>>(),
      owner_type: 'admin',
      file_name: RandomGenerator.alphaNumeric(14),
      file_size: typia.random<number & tags.Type<'int32'>>(),
      mime_type: 'application/pdf',
      storage_uri: `s3://e2e-test-bucket/file-${Date.now()}.pdf`,
      hash_sha256: RandomGenerator.alphaNumeric(64),
      uploaded_at: new Date(Date.now() - 86400000).toISOString(),
      expire_at: null,
      description: 'E2E: attachment for log search test',
    } satisfies IShoppingMallAiBackendAttachment.ICreate
  });
  typia.assert(attachment);

  // 2. Create multiple log entries (simulate upload, download, access)
  const event_types = ['upload', 'download', 'access'];
  const logs = [];
  const adminId = typia.random<string & tags.Format<'uuid'>>();
  const baseTimestamp = Date.now() - 100000;
  for (let i = 0; i < event_types.length; ++i) {
    const created = await api.functional.shoppingMallAiBackend.admin.attachments.logs.create(connection, {
      attachmentId: attachment.id,
      body: {
        event_type: event_types[i],
        ip_address: `192.168.1.${i+1}`,
        operated_by_admin_id: adminId,
        event_context: `Automated log ${i+1}`,
        event_at: new Date(baseTimestamp + i * 1000).toISOString(),
      } satisfies IShoppingMallAiBackendAttachmentLog.ICreate
    });
    typia.assert(created);
    logs.push(created);
  }

  // 3a. Search logs for the attachment with no filter (all logs)
  {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: {}
    });
    typia.assert(found);
    TestValidator.equals('returns all logs')(found.data.length)(logs.length);
    found.data.forEach(x => {
      TestValidator.equals('correct attachment_id')(x.attachment_id)(attachment.id);
      TestValidator.equals('no soft delete')(x.deleted_at)(undefined);
    });
    TestValidator.equals('pagination current')(found.pagination.current)(1);
    TestValidator.equals('pagination limit')(found.pagination.limit)(25);
    TestValidator.equals('pagination records')(found.pagination.records)(logs.length);
    // Should be only one page (<=25)
    TestValidator.equals('pagination pages')(found.pagination.pages)(1);
  }

  // 3b. Filter by event_type
  for (let i = 0; i < event_types.length; ++i) {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_type: event_types[i] }
    });
    typia.assert(found);
    TestValidator.equals(`1 log for event_type ${event_types[i]}`)(found.data.length)(1);
    found.data.forEach(x => {
      TestValidator.equals('event_type')(x.event_type)(event_types[i]);
      TestValidator.equals('correct attachment_id')(x.attachment_id)(attachment.id);
      TestValidator.equals('no soft delete')(x.deleted_at)(undefined);
    });
    // Pagination meta (should still be one page, but records=1)
    TestValidator.equals('pagination records')(found.pagination.records)(1);
    TestValidator.equals('pagination pages')(found.pagination.pages)(1);
  }

  // 3c. Pagination: pageSize=2
  {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { page: 1, pageSize: 2 }
    });
    typia.assert(found);
    TestValidator.equals('pageSize')(found.pagination.limit)(2);
    TestValidator.equals('first page')(found.pagination.current)(1);
    TestValidator.predicate('at most 2 logs')(found.data.length <= 2);
    found.data.forEach(x => {
      TestValidator.equals('no soft delete')(x.deleted_at)(undefined);
    });
  }

  // 3d. Date/time range filter: should find logs in selected range
  {
    const from = logs[1].event_at;
    const to = logs[2].event_at;
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_at_from: from, event_at_to: to }
    });
    typia.assert(found);
    found.data.forEach(l => {
      TestValidator.predicate('event_at after from')(l.event_at >= from);
      TestValidator.predicate('event_at before to')(l.event_at <= to);
    });
    found.data.forEach(x => {
      TestValidator.equals('correct attachment_id')(x.attachment_id)(attachment.id);
      TestValidator.equals('no soft delete')(x.deleted_at)(undefined);
    });
  }

  // 3e. Empty result when event_type does not exist
  {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_type: 'nonexistent_event' }
    });
    typia.assert(found);
    TestValidator.equals('empty for nonexistent type')(found.data.length)(0);
    TestValidator.equals('records 0')(found.pagination.records)(0);
    TestValidator.equals('pages 0')(found.pagination.pages)(0);
  }

  // 4. Error: invalid attachment id
  await TestValidator.error('attachment id does not exist')(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: typia.random<string & tags.Format<'uuid'>>(),
      body: {}
    })
  );

  // 5. Error: malformed filter (bad date)
  await TestValidator.error('malformed filter')(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_at_from: 'not-a-date' as any }
    })
  );
}

