  // 6. Filter by city
  const byCity = await api.functional.shoppingMallAiBackend.admin.customers.addresses.patchByCustomerid(connection, {
    customerId,
    body: { city: cityA },
  });
  typia.assert(byCity);
  TestValidator.predicate(`all city == ${cityA}`)(byCity.data.every(a => a.city === cityA));

  // 7. Filter by state
  const byState = await api.functional.shoppingMallAiBackend.admin.customers.addresses.patchByCustomerid(connection, {
    customerId,
    body: { state: stateB },
  });
  typia.assert(byState);
  TestValidator.predicate(`all state == ${stateB}`)(byState.data.every(a => a.state === stateB));

  // 8. Filter by is_primary true
  const primaries = await api.functional.shoppingMallAiBackend.admin.customers.addresses.patchByCustomerid(connection, {
    customerId,
    body: { is_primary: true },
  });
  typia.assert(primaries);
  TestValidator.predicate("all primary")(primaries.data.every(a => a.is_primary));
  TestValidator.equals("single primary")(primaries.data.length)(1);

  // 9. Pagination: limit=2, page=2
  const paged = await api.functional.shoppingMallAiBackend.admin.customers.addresses.patchByCustomerid(connection, {
    customerId,
    body: { limit: 2, page: 2 },
  });
  typia.assert(paged);
  TestValidator.equals("page size")(paged.pagination.limit)(2);
  TestValidator.equals("page 2")(paged.pagination.current)(2);
  TestValidator.equals("pagination total records")(paged.pagination.records)(addresses.length);
  TestValidator.equals("pagination total pages")(paged.pagination.pages)(Math.ceil(addresses.length / 2));

  // 10. Query with non-existent customerId (expect error)
  const badCustomerId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent customerId fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.addresses.patchByCustomerid(connection, {
      customerId: badCustomerId,
      body: {},
    });
  });
}

