import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAdmin";
import type { IPageIShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

typia, { tags } from "typia";







/**
 * Validate soft-deletion and idempotency for admin accounts (set deleted_at field).
 *
 * This test covers the admin deletion workflow and all error/idempotency cases:
 *
 * 1. Log in as admin with sufficient privileges
 * 2. List current admins and select a non-self, active admin as the target
 * 3. Soft delete the selected admin by adminId
 * 4. Search for the same admin and ensure it no longer appears in unfiltered result
 * 5. Repeat the delete—should return error (not found/idempotent)
 * 6. Attempt to delete a random, non-existent adminId and expect error
 * 7. Remove JWT from connection and attempt deletion—should fail for insufficient permissions
 * 8. (Note: Audit/history endpoint is not present for programmatic test)
 *
 * Prerequisites: The E2E infrastructure must contain at least two valid admin accounts: one to act as operator (test runner), and one to be the deletion target. If the infra creates/cleans up its own admin(s), this test must adapt accordingly.
 */
export async function test_api_admin_soft_delete_and_idempotency(
  connection: api.IConnection,
) {
  // 1. Login as a privileged admin user
  // NOTE: The test requires a valid admin for login; actual E2E infra should provide secrets/config or guarantee setup.
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin_password_123";
  const auth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(auth);

  // 2. Fetch admins, pick another active (non-self, not deleted) admin for deletion
  const page = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: { status: "active", page: 1, limit: 10 },
  });
  typia.assert(page);
  const candidates = page.data.filter(
    (a) => a.email !== adminEmail && !a.deleted_at,
  );
  if (!candidates.length) throw new Error("No other active admin available for deletion test.");
  const target = candidates[0];

  // 3. Soft delete the selected admin
  await api.functional.shoppingMallAiBackend.admin.admins.erase(connection, {
    adminId: target.id,
  });

  // 4. Search; deleted admin should not be found among active accounts
  const after = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: { status: "active", email: target.email, page: 1, limit: 10 },
  });
  typia.assert(after);
  TestValidator.equals("deleted admin not returned")(
    after.data.findIndex((a) => a.id === target.id),
  )(-1);

  // 5. Repeat delete: should throw (idempotent or not found)
  await TestValidator.error("repeat delete fails")(
    async () =>
      await api.functional.shoppingMallAiBackend.admin.admins.erase(connection, {
        adminId: target.id,
      }),
  );

  // 6. Delete non-existent adminId: expect error
  await TestValidator.error("random adminId delete fails")(
    async () =>
      await api.functional.shoppingMallAiBackend.admin.admins.erase(connection, {
        adminId: typia.random<string & tags.Format<"uuid">>(),
      }),
  );

  // 7. Remove JWT/Authorization; expect forbidden error on erase
  const noAuth: api.IConnection = {
    ...connection,
    headers: { ...(connection.headers ?? {}) },
  };
  delete noAuth.headers["Authorization"];
  await TestValidator.error("forbidden without admin JWT")(
    async () =>
      await api.functional.shoppingMallAiBackend.admin.admins.erase(noAuth, {
        adminId: target.id,
      }),
  );

  // 8. Audit/history confirmation (manual)
  // NOTE: No endpoint or event inspection for audit/history available in current SDK
}

