 * 1. Register admin account (for delete privileges)
 * 2. Log in as the admin (acquire authorization)
 * 3. Register a seller (for product creation)
 * 4. Log in as the seller
 * 5. Seller creates a product with valid fields
 * 6. Switch back to admin (login again)
 * 7. Admin soft-deletes the product (should succeed)
 * 8. Admin attempts a second soft-delete on the same product (should return 404)
 * 9. (Optional) If API/audit logs are accessible, further compliance validations could be performed
 */
export async function test_api_admin_product_soft_delete_already_deleted(
  connection: api.IConnection,
) {
