  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongP@ssw0rd!";
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminReg);

  // 2. Log in as admin (to get Authorization)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "AnotherP@ssw0rd!";
  const sellerReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.alphaNumeric(10),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(1),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerReg);

  // 4. Log in as seller to acquire seller privileges
  const sellerLogin = await api.functional.auth.seller.login.signIn(connection, {
    body: { email: sellerEmail, password: sellerPassword } satisfies ISellerAuth.SignIn,
  });
  typia.assert(sellerLogin);

  // 5. Seller creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerReg.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(2),
      main_image_uri: RandomGenerator.url(),
      status: "draft",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 6. Switch (back) to admin account
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignIn,
  });

  // 7. Admin soft-deletes the product (first attempt - should succeed)
  await api.functional.shoppingMallAiBackend.admin.products.erase(connection, {
    productId: product.id,
  });

  // 8. Admin attempts second soft-delete on the same product (should throw error)
  await TestValidator.error("Re-soft-deleting already deleted product returns 404")(
    () => api.functional.shoppingMallAiBackend.admin.products.erase(connection, {
      productId: product.id,
    }),
  );
  // 9. Further compliance or audit trail checks could be inserted here if the API exposed such endpoints
}

