import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderItem";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test that a seller cannot access another seller's order item detail.
 *
 * This test verifies that the platform enforces strict data privacy by ensuring a seller cannot fetch details of an order item not associated with their own products. The workflow covers complete real-world business logic, including seller onboarding, product registration, customer shopping, order/item creation, and unauthorized access attempts by a non-associated seller.
 *
 * **Steps:**
 * 1. Register Seller 1, and save credentials/ID.
 * 2. Register Seller 2 (the one who will attempt unauthorized access), and save credentials/ID as well.
 * 3. Log in as Seller 1 to establish their Authorization (creates their product and is owner in DB).
 * 4. Seller 1 registers a product for sale.
 * 5. Register a customer account with random info for test-shopping.
 * 6. Log in the customer to get a session.
 * 7. Customer creates a new order, referencing Seller 1's product and including valid product IDs/amounts/currency.
 * 8. Customer adds an order item to the order representing the purchase of Seller 1's product.
 * 9. Log in as Seller 2 (who does NOT own the product/order/item).
 * 10. Seller 2 attempts to fetch the order item detail for the order placed by the customer for Seller 1's product. This should fail.
 * 11. Assert that the system throws a forbidden/access-denied error to Seller 2, with no sensitive data leaked.
 */
export async function test_api_order_item_detail_forbidden_other_seller(connection: api.IConnection) {
  // 1. Register Seller 1
  const seller1Email = typia.random<string & tags.Format<"email">>();
  const seller1Password = "1234!Seller1";
  const seller1SignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller1Email,
      password: seller1Password,
      companyName: RandomGenerator.company(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(seller1SignUp);
  const seller1Id = seller1SignUp.sellerId;

  // 2. Register Seller 2
  const seller2Email = typia.random<string & tags.Format<"email">>();
  const seller2Password = "1234!Seller2";
  const seller2SignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller2Email,
      password: seller2Password,
      companyName: RandomGenerator.company(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(seller2SignUp);

  // 3. Log in as Seller 1
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: seller1Email,
      password: seller1Password,
    },
  });

  // 4. Seller 1 registers a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: seller1Id,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    },
  });
  typia.assert(product);

  // 5. Customer registration
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "1234!Custom";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;

  // 6. Customer login
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    },
  });

  // 7. Customer creates an order
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 10000,
      currency_code: "KRW",
      current_status: "created",
      note: null,
      order_group_id: null,
    },
  });
  typia.assert(order);

  // 8. Customer creates an order item for Seller 1's product
  const orderItem = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      product_id: product.id,
      product_snapshot_id: typia.random<string & tags.Format<"uuid">>(),
      quantity: 1,
      unit_price: 10000,
      currency_code: "KRW",
      note: null,
    },
  });
  typia.assert(orderItem);

  // 9. Log in as Seller 2 (should NOT be authorized for this order item)
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: seller2Email,
      password: seller2Password,
    },
  });

  // 10. Seller 2 attempts to fetch Seller 1's order item (must be forbidden)
  await TestValidator.error("forbidden for other seller")(() =>
    api.functional.shoppingMallAiBackend.seller.orders.orderItems.at(connection, {
      orderId: order.id,
      orderItemId: orderItem.id,
    })
  );
}

