  const validChannelInput = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(2),
    created_by_admin_id: adminLogin.adminId,
    active: true,
    description: null,
    logo_url: null,
  } satisfies IShoppingMallAiBackendChannel.ICreate;

