  await TestValidator.error("missing name should fail")(async () => {
    const input = { ...validChannelInput };
    // @ts-expect-error
    delete input.name;
    await api.functional.shoppingMallAiBackend.admin.channels.create(connection, { body: input as any });
  });

  // 3. Empty name field — should fail
  await TestValidator.error("empty name should fail")(async () => {
    const input = { ...validChannelInput, name: "" };
    await api.functional.shoppingMallAiBackend.admin.channels.create(connection, { body: input });
  });

  // 4. Create valid channel, then test duplicate code
  const createdChannel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: validChannelInput,
  });
  typia.assert(createdChannel);

