import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test that a seller cannot delete a tag from another seller's product.
 *
 * This test ensures business security: a seller can only manage tags on products they own. It verifies that the backend properly refuses unauthorized deletion requests, protecting cross-tenant data integrity.
 *
 * Steps:
 * 1. Register Seller A and obtain their credentials.
 * 2. Register Seller B (the unauthorized seller).
 * 3. Seller A creates a product owned by themselves.
 * 4. (Simulate a tag existing on the product using a random UUID, as no tag-creation API is provided.)
 * 5. Switch to Seller B.
 * 6. Attempt to delete the tag from Seller A's product.
 * 7. Assert that the operation fails due to insufficient permissions.
 */
export async function test_api_product_tag_delete_unauthorized_by_seller(
  connection: api.IConnection,
) {
  // 1. Register Seller A (product owner)
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "SellerA$1234",
      companyName: "Seller A Ltd.",
      businessNumber: typia.random<string>(),
      representativeName: "Alice A",
      address: "123 Main Road, City A",
      phone: "010-1000-0001",
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerAResponse);
  const sellerAId = sellerAResponse.sellerId;

  // 2. Register Seller B (other seller)
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "SellerB$1234",
      companyName: "Seller B Inc.",
      businessNumber: typia.random<string>(),
      representativeName: "Bob B",
      address: "456 Side Lane, City B",
      phone: "010-2000-0002",
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerBResponse);

  // 3. Impersonate Seller A to create a product
  connection.headers.Authorization = sellerAResponse.setHeaders.Authorization;
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: typia.random<string>(),
      name: "Product of Seller A",
      description: "A test product for permission checks.",
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 4. Simulate existence of a tag UUID (no create/list tag API available)
  const fakeProductTagId = typia.random<string & tags.Format<"uuid">>();

  // 5. Switch to Seller B
  connection.headers.Authorization = sellerBResponse.setHeaders.Authorization;

  // 6/7. Attempt deletion as Seller B and assert permission denied
  await TestValidator.error("Seller B should not delete another seller's product tag")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productTags.eraseProductTag(connection, {
        productId: product.id,
        productTagId: fakeProductTagId,
      });
    },
  );
}

