import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that a seller can view the complete details of a product bundle they own.
 *
 * Business context:
 * Sellers may create bundles of products for marketing and sales efficiency. Such bundles are essential for campaigns and inventory operations. Only the owning seller (or platform admin) should be able to fetch the full bundle detail. Correct operation means sellers see all configured information—business codes, name, rich description, pricing/discount, and timestamps. This also tests security: non-owners must not access.
 *
 * Steps:
 * 1. Register a new seller via the seller sign-up endpoint (simulate onboarding for a unique business).
 * 2. Create a new product using the registered seller’s identity.
 * 3. Create a product bundle for this product, providing full fields (name, description, bundle_policy if relevant, bundle_price, status, code).
 * 4. Fetch the bundle detail using the GET endpoint, providing both the productId and the created productBundleId.
 * 5. Validate the returned bundle matches all fields given at creation—name, code, description, bundle policy, price, status, reference IDs, audit fields (created/updated_at), and is linked to the correct product.
 * 6. (Optionally, attempt unauthorized access logic: test that another seller or non-owner cannot fetch the bundle - omitted if endpoints not provided.)
 */
export async function test_api_product_bundle_detail_view_as_seller(connection: api.IConnection) {
  // 1. Seller registration
  const signUpInput: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "testPassword1234!@#",
    companyName: RandomGenerator.name(),
    businessNumber: String(typia.random<number & tags.Format<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>>()),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  };
  const sellerAuth = await api.functional.auth.seller.register.signUp(connection, { body: signUpInput });
  typia.assert(sellerAuth);

  // 2. Product creation for the seller
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: sellerAuth.sellerId,
    code: "PROD-" + RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    main_image_uri: null,
    status: "published",
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: productInput });
  typia.assert(product);

  // 3. Product bundle creation
  const bundleInput: IShoppingMallAiBackendProductBundle.ICreate = {
    main_product_id: product.id,
    code: "BUNDLE-" + RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
