import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test unauthorized and forbidden access to the admin article search endpoint.
 *
 * This test verifies that non-admin users and unauthenticated sessions are denied access to the admin-level article search API via PATCH /shoppingMallAiBackend/admin/articles.
 *
 * Steps:
 * 1. Register a new customer (non-admin account) and obtain the JWT token.
 * 2. Attempt to access the admin article search endpoint with the customer session.
 *    - Expect an authorization error (access denied/forbidden – no articles data returned, error is thrown)
 * 3. Attempt to access the admin article search endpoint with NO authentication (logged out/anonymous).
 *    - Expect an authorization error (access denied/forbidden – error is thrown)
 */
export async function test_api_admin_article_search_no_access_non_admin(
  connection: api.IConnection,
) {
  // 1. Register a new customer (non-admin)
  const email = typia.random<string & tags.Format<"email">>();
  const password = "1234!@#Testing";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: `${RandomGenerator.name()}_${RandomGenerator.alphaNumeric(6)}`,
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);

  // Ensure Authorization header is set to customer JWT token
  connection.headers.Authorization = customerSignUp.setHeaders.Authorization;

  // 2. Attempt admin article search as non-admin (customer)
  await TestValidator.error("non-admin user should not access admin article search")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.articles.search(connection, {
        body: {}, // minimal valid request
      });
    },
  );

  // 3. Attempt admin article search with NO authentication
  delete connection.headers.Authorization;
  await TestValidator.error("anonymous user should not access admin article search")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.articles.search(connection, {
        body: {}, // minimal valid request
      });
    },
  );
}

