import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendIssuedCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendIssuedCoupon";
import type { IShoppingMallAiBackendCouponUsage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponUsage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test creation and duplicate-protection of coupon usage association by admin.
 *
 * This test simulates the workflow for an admin to create a coupon usage record:
 * 1. Admin logs in to obtain JWT authentication.
 * 2. A valid order is created for a (dummy) customer to associate with coupon usage.
 * 3. An issued coupon is created and assigned to the same customer, with a valid template and future expiry.
 * 4. As admin, create a coupon usage record linking the issued coupon, the order, and the customer, providing a used_at timestamp.
 * 5. Validate coupon usage is created successfully, verifying all IDs and the used_at timestamp are correct.
 * 6. Attempt creating a duplicate coupon usage record with the same coupon/order/customer and expect failure (no duplicate allowed).
 * 7. (Business audit: although not directly observable, ensure the test action is done as admin for compliance tracking.)
 */
export async function test_api_coupon_usage_create_valid_association(
  connection: api.IConnection,
) {
  // 1. Admin login
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminTestPw2025";
  // IMPORTANT: This assumes such an admin exists or is provisioned for tests
  const jwt = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(jwt);
  connection.headers.Authorization = jwt.setHeaders.Authorization;

  // 2. Create order for a test customer
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const orderDto = {
    customer_id: customerId,
    order_group_id: null,
    order_number: "ORD-" + typia.random<string>(),
    total_amount: typia.random<number & tags.Type<"uint32">>(),
    currency_code: "USD",
    note: null,
    current_status: "created",
  } satisfies IShoppingMallAiBackendOrder.ICreate;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: orderDto,
  });
  typia.assert(order);

  // 3. Issue coupon to this customer
  const couponTemplateId = typia.random<string & tags.Format<"uuid">>();
  const issuedCoupon = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.create(connection, {
    body: {
      coupon_template_id: couponTemplateId,
      customer_id: customerId,
      code: "CPN-" + typia.random<string>(),
      expires_at: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(), // 2 weeks from now
      status: "issued",
    } satisfies IShoppingMallAiBackendIssuedCoupon.ICreate,
  });
  typia.assert(issuedCoupon);

  // 4. Create coupon usage record
  const usedAt = new Date().toISOString();
  const couponUsage = await api.functional.shoppingMallAiBackend.admin.couponUsages.create(connection, {
    body: {
      issued_coupon_id: issuedCoupon.id,
      order_id: order.id,
      customer_id: customerId,
      used_at: usedAt,
    } satisfies IShoppingMallAiBackendCouponUsage.ICreate,
  });
  typia.assert(couponUsage);
  TestValidator.equals("issued_coupon_id echo")(couponUsage.issued_coupon_id)(issuedCoupon.id);
  TestValidator.equals("order_id echo")(couponUsage.order_id)(order.id);
  TestValidator.equals("customer_id echo")(couponUsage.customer_id)(customerId);
  TestValidator.equals("used_at echo")(couponUsage.used_at)(usedAt);

  // 5. Creating duplicate coupon usage should fail
  await TestValidator.error("Duplicate coupon usage not allowed")(() =>
    api.functional.shoppingMallAiBackend.admin.couponUsages.create(connection, {
      body: {
        issued_coupon_id: issuedCoupon.id,
        order_id: order.id,
        customer_id: customerId,
        used_at: new Date().toISOString(),
      } satisfies IShoppingMallAiBackendCouponUsage.ICreate,
    })
  );
}

