import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";
import type { IPageIShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductBundle";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates advanced search and paginated listing of product bundles for a product as admin.
 *
 * This test ensures that an admin can:
 * - Create a new product (prerequisite).
 * - Register multiple bundles for this product with varied bundle policies, statuses, prices, and names.
 * - Perform a complex, paginated search with filters (bundle policy, status, name, etc.).
 * - Validate that only the bundles matching given criteria (belonging to the product, matching filter) are returned, and pagination works as expected.
 * - Confirm correct pagination metadata and robust admin data visibility.
 *
 * Steps:
 * 1. Create a product via admin API.
 * 2. Create several bundles for the product, covering both 'target' and 'non-target' filter attributes.
 * 3. Construct advanced search filter to match only a subset of the bundles (e.g., those with campaign policy and active status).
 * 4. Perform search for bundles using the advanced filter, check paginated response (page 1, limit 2).
 * 5. Validate that only correct bundles (e.g. 'VIP Bundle', active, campaign) are returned, and pagination is accurate.
 * 6. Fetch the next page and validate response.
 * 7. Optionally, test an edge case: filter with criteria that matches no bundles and check that the result set is empty.
 */
export async function test_api_product_bundle_list_success_admin(
  connection: api.IConnection,
) {
  // Step 1: Admin creates a product to associate bundles
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(1),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // Step 2: Admin creates several bundles for the product (varied attributes for filtering)
  const bundles = await ArrayUtil.asyncRepeat(5)(async (_, i) => {
    // First three bundles are 'target' (will match filter), rest are not
    const isTarget = i < 3;
    return await api.functional.shoppingMallAiBackend.admin.products.productBundles.create(connection, {
      productId: product.id,
      body: {
        main_product_id: product.id,
        code: `BNDL-${RandomGenerator.alphaNumeric(4)}-${i}`,
        name: isTarget ? `VIP Bundle ${i}` : `Standard Pack ${i}`,
        description: isTarget ? "Promo bundle for campaign" : null,
        bundle_policy: isTarget ? "campaign" : "manual",
        bundle_price: isTarget ? 6000 + i * 250 : 12000 + i * 500,
        status: isTarget ? "active" : "discontinued",
      } satisfies IShoppingMallAiBackendProductBundle.ICreate,
    });
  });
  bundles.forEach(typia.assert);

  // Step 3: Prepare advanced filter to select only the 'target' bundles (VIP Bundle/campaign/active)
  const filter = {
    main_product_id: product.id,
    bundle_policy: "campaign",
    status: "active",
    name: "VIP Bundle",
    page: 1,
    limit: 2,
    order_by: "created_at",
    order_direction: "asc",
  } satisfies IShoppingMallAiBackendProductBundle.IRequest;

