import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderStatusHistory";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Ensures that a non-owning seller cannot record order status updates for another seller's order.
 *
 * Business context:
 * In a marketplace, only the seller who owns a product (and thus whose shop received the order) should be able to update an order's status history as a "seller" actor for that order. If an unrelated seller attempts such an action, the backend must enforce business isolation and reject the unauthorized request.
 *
 * Why this test is critical:
 * - Prevents privilege escalation and unauthorized workflow transitions.
 * - Ensures that order/audit trails are maintained only by relevant, authorized business actors.
 * - Enforces marketplace contract boundaries, protecting both customer and seller integrity.
 *
 * Process breakdown:
 * 1. Register Seller A (who will own the product and order).
 * 2. Register Seller B (a user with valid seller account, but unrelated to the order).
 * 3. Register a customer (who will make a purchase for Seller A's goods).
 * 4. Seller A creates a product (product is attributed to Seller A).
 * 5. Customer places an order (simplified, as order entity does not natively list product; test assumes system linkage for this context).
 * 6. Switch API context to Seller B by injecting Seller B's JWT into connection.headers.
 * 7. Seller B attempts to record an order status history event for the order from step 5.
 * 8. Assertion: Backend rejects with permission or ownership error; operation must not succeed.
 */
export async function test_api_seller_create_order_status_history_for_non_owned_order(
  connection: api.IConnection,
) {
  // 1. Register Seller A and receive authentication response
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAPassword = "Password123!";
  const sellerAResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
      companyName: RandomGenerator.name(),
      businessNumber: String(
        typia.random<
          number & tags.Format<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>
        >(),
      ),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerAResp);
  const sellerAId = sellerAResp.sellerId;

  // 2. Register Seller B (will attempt the forbidden action)
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBPassword = "Password456!";
  const sellerBResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: sellerBPassword,
      companyName: RandomGenerator.name(),
      businessNumber: String(
        typia.random<
          number & tags.Format<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>
        >(),
      ),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerBResp);
  const sellerBId = sellerBResp.sellerId;

  // 3. Register a Customer C and set API context to customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Customer789!";
  const customerResp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerResp);
  const customerId = customerResp.customer.id;
  // Simulate customer authentication: set JWT from registration response
  connection.headers = { ...(connection.headers ?? {}), Authorization: customerResp.setHeaders.Authorization };

  // 4. Seller A (re-auth) creates a product
  connection.headers = { ...(connection.headers ?? {}), Authorization: sellerAResp.setHeaders.Authorization };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(),
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 5. Customer (set back to customer JWT) places an order (for Seller A's product)
  connection.headers = { ...(connection.headers ?? {}), Authorization: customerResp.setHeaders.Authorization };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 50000,
      currency_code: "KRW",
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(order);

  // 6. Switch context/API headers to Seller B (unrelated seller)
  connection.headers = { ...(connection.headers ?? {}), Authorization: sellerBResp.setHeaders.Authorization };

  // 7. Seller B attempts forbidden creation of order status history
  await TestValidator.error("unrelated seller must be denied updating order status history")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.orders.orderStatusHistories.create(connection, {
        orderId: order.id,
        body: {
          previous_status: "created",
          new_status: "paid",
          actor_type: "seller",
          actor_id: sellerBId,
          occurred_at: new Date().toISOString(),
        } satisfies IShoppingMallAiBackendOrderStatusHistory.ICreate,
      });
    },
  );
}

