import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSeller";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates admin access to seller details endpoint and access control logic.
 *
 * This test ensures that an authenticated admin can retrieve the complete profile
 * of any seller by sellerId via the /admin/sellers/{sellerId} API. It checks that:
 *   - All business and certification fields are visible to admins (no field hiding)
 *   - The returned profile matches seller registration info for core fields
 *   - Access is denied for non-existent, deleted, or unauthorized sessions
 *   - No field over-exposure/under-exposure based on admin privilege
 *
 * Test Steps:
 * 1. Register and authenticate a new admin, capturing JWT for admin session
 * 2. Register a new seller entity; retain sellerId and profile fields for validation
 * 3. Admin gets seller profile by sellerId: all fields present, info matches registration
 * 4. Try random/non-existent sellerId as admin: must throw 'not found' error
 * 5. Attempt seller profile fetch as a seller (non-admin) session: must throw authorization error
 * 6. Try deleted/withdrawn seller: simulate by using a random UUID, expect not found
 * 7. Try invalid sellerId format: should throw input validation error
 */
export async function test_api_admin_access_seller_details(connection: api.IConnection) {
  // 1. Admin registration and authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin1234";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);

  // 2. Register new seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerData = {
    email: sellerEmail,
    password: "seller1234",
    companyName: "Test Merchant LLC",
    businessNumber: RandomGenerator.alphabets(10),
    representativeName: RandomGenerator.name(),
    address: "1 Main Street",
    phone: RandomGenerator.mobile(),
  } satisfies ISellerAuth.SignUp;
  const seller = await api.functional.auth.seller.register.signUp(connection, {
    body: sellerData,
  });
  typia.assert(seller);

  // 3. Admin retrieves seller profile
  connection.headers = { ...connection.headers, Authorization: admin.setHeaders.Authorization };
  const profile = await api.functional.shoppingMallAiBackend.admin.sellers.at(connection, {
    sellerId: seller.sellerId,
  });
  typia.assert(profile);
  // Check presence and correctness of all main fields
  ["id", "email", "company_name", "business_number", "representative_name", "address", "phone", "status", "email_verified", "joined_at", "created_at", "updated_at"].forEach(field => {
    TestValidator.predicate(`admin sees ${field}`)(profile[field] !== undefined && profile[field] !== null);
  });
  TestValidator.equals("email matches")(profile.email)(seller.email);
  TestValidator.equals("company_name matches")(profile.company_name)(seller.companyName);
  TestValidator.equals("business_number matches")(profile.business_number)(seller.businessNumber);

  // 4. Admin requests with random/non-existent sellerId
  const randomSellerId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("non-existent sellerId fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.at(connection, {
        sellerId: randomSellerId,
      });
    }
  );

  // 5. Seller tries to access admin endpoint (not allowed)
  connection.headers = { ...connection.headers, Authorization: seller.setHeaders.Authorization };
  TestValidator.error("seller cannot see admin-only profile")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.at(connection, {
        sellerId: seller.sellerId,
      });
    }
  );
  // Restore admin session
  connection.headers = { ...connection.headers, Authorization: admin.setHeaders.Authorization };

  // 6. Use likely-nonexistent (deleted/withdrawn) sellerId
  const deletedSellerId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("deleted/withdrawn sellerId fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.at(connection, {
        sellerId: deletedSellerId,
      });
    }
  );

  // 7. Input validation (malformed sellerId)
  TestValidator.error("invalid sellerId format fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.at(connection, {
        sellerId: "not-a-uuid" as any,
      });
    }
  );
}

