import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerAddress";
import type { IPageIShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerAddress";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validate customer self-address search, advanced filtering, pagination, and privacy enforcement.
 *
 * Simulates a real-world workflow in a shopping mall backend: a customer registers and logs in,
 * adds multiple delivery addresses, and then tests the self-address listing endpoint with diverse
 * filters and paginations—also verifying privacy boundaries so addresses remain accessible only
 * to their owner.
 *
 * Test flow:
 * 1. Register a customer (random email/phone).
 * 2. Log in to activate session and JWT.
 * 3. Add several addresses—mixing alias, city, and is_primary.
 * 4. List all addresses for the customer (plain, no filter, page 1/limit 10), checking all addresses returned belong to the customer.
 * 5. List by alias partial and verify result contains only the expected subset.
 * 6. List by city, verify only city-matching addresses are in result.
 * 7. Filter by is_primary and ensure only the primary address appears.
 * 8. Paginate with limit and second page; verify correct subset and pagination metadata.
 * 9. Attempt to fetch with other customer session and confirm privacy enforcement (error thrown or forbidden).
 * 10. Try with a non-existent/fake customerId and confirm error is raised.
 */
export async function test_api_customer_self_search_addresses_and_privacy(
  connection: api.IConnection,
) {
  // 1. Register a new customer account
  const email = typia.random<string & tags.Format<"email">>();
  const password = "Abc123!@#";
  const signUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUp);
  const customer = signUp.customer;
  const customerId = customer.id;

  // 2. Login as that customer to activate JWT in connection
  const signIn = await api.functional.auth.customer.login.signIn(connection, {
    body: { email, password } satisfies ICustomerSignIn.Request,
  });
  typia.assert(signIn);

  // 3. Add several (4) customer addresses
  const addressInputs = [
    { alias: "Home", city: "Seoul", is_primary: true },
    { alias: "Office", city: "Busan", is_primary: false },
    { alias: "Parents", city: "Incheon", is_primary: false },
    { alias: null, city: "Daegu", is_primary: false },
  ];
  const created: IShoppingMallAiBackendCustomerAddress[] = [];
  for (let i = 0; i < addressInputs.length; ++i) {
    const input = addressInputs[i];
    const addr = await api.functional.shoppingMallAiBackend.customer.customers.addresses.putByCustomerid(
      connection,
      {
        customerId,
        body: {
          id: typia.random<string & tags.Format<"uuid">>(),
          receiver_name: RandomGenerator.name(),
          receiver_phone: RandomGenerator.mobile(),
          postal_code: String(53000 + i),
          address_line1: RandomGenerator.paragraph()(6),
          address_line2: i % 2 === 0 ? null : RandomGenerator.alphaNumeric(4),
          city: input.city,
