      limit: 2,
      page: 2
    }
  });
  typia.assert(result);
  TestValidator.equals("pagination meta limit")(result.pagination.limit)(2);
  TestValidator.equals("pagination meta page")(result.pagination.current)(2);
  TestValidator.predicate("pagination data max 2")((result.data.length <= 2));

  // 5e. Sort: changed_at desc/asc
  // Asc
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      sort_by: "changed_at",
      sort_direction: "asc"
    }
  });
  typia.assert(result);
  for (let i = 1; i < result.data.length; ++i) {
    TestValidator.predicate(`asc-sort order at ${i}`)(result.data[i].changed_at >= result.data[i - 1].changed_at);
  }
  // Desc
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      sort_by: "changed_at",
      sort_direction: "desc"
    }
  });
  typia.assert(result);
  for (let i = 1; i < result.data.length; ++i) {
    TestValidator.predicate(`desc-sort order at ${i}`)(result.data[i - 1].changed_at >= result.data[i].changed_at);
  }

  // 5f. Filter by date range (changed_at_from/to)
  // Use the time window from snapshot[2] to snapshot[4]
  const changed_at_from = snapshots[2].changed_at;
  const changed_at_to = snapshots[4].changed_at;
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
