  typia.assert(result);
  TestValidator.predicate("date range filter")(
    result.data.every(d => d.changed_at >= changed_at_from && d.changed_at <= changed_at_to)
  );

  // 6. Security: only owning seller can fetch - test negative: no auth/JWT
  const { Authorization, ...restHeaders } = connection.headers ?? {};
  const unauthConn = {
    ...connection,
    headers: restHeaders
  };
  await TestValidator.error("unauthorized - no JWT")(() =>
    api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(unauthConn, {
      productInquiryId: inquiryId,
      body: {
        inquiry_id: inquiryId,
      }
    })
  );

  // 7. Security: seller who does not own the product
  const seller2Email: string = typia.random<string & tags.Format<"email">>();
  const seller2Reg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller2Email,
      password: "StrongPassw0rd!",
      companyName: "Test Company 2",
      businessNumber: "1000123457",
