 * 1. Register and login seller A (owner); create a product and tag as A.
 * 2. Successfully retrieve the tag detail as seller A.
 * 3. Try to fetch a random/nonexistent tag on the product (expect error).
 * 4. Register and login seller B. Attempt to access A's product tag (expect forbidden error).
 * 5. Tag deletion step is omitted as no API for deletion exists.
 */
export async function test_api_product_tag_detail_access_control_and_existence(connection: api.IConnection) {
  // 1. Register seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerARegister = await api.functional.auth.seller.register.signUp(connection, {
