  });
  typia.assert(tag);
  // 5. Retrieve tag detail as owner
  const tagRead = await api.functional.shoppingMallAiBackend.seller.products.productTags.atProductTag(connection, {
    productId: product.id,
    productTagId: tag.id,
  });
  typia.assert(tagRead);
  TestValidator.equals("tag detail - id")(tagRead.id)(tag.id);
  TestValidator.equals("tag detail - product_id")(tagRead.product_id)(product.id);
  // 6. Attempt to fetch non-existent tag (random ID)
  await TestValidator.error("not found for non-existent tag")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productTags.atProductTag(connection, {
        productId: product.id,
        productTagId: typia.random<string & tags.Format<"uuid">>(),
      });
    }
  );
  // 7. Register and login seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBRegister = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "securePass2!",
      companyName: RandomGenerator.name(),
      businessNumber: String(typia.random<number & tags.Format<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>>()),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(1),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerBRegister);
  // 8. Login seller B
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerBEmail,
      password: "securePass2!",
    } satisfies ISellerAuth.SignIn,
  });
  // 9. Seller B tries to access seller A's tag (expect forbidden)
  await TestValidator.error("forbidden - non-owner cannot access")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productTags.atProductTag(connection, {
        productId: product.id,
        productTagId: tag.id,
      });
    }
  );
  // 10. (Tag deletion not available in API, so cannot run deleted tag error)
}

