import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSellerOnboarding } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSellerOnboarding";
import type { IPageIShoppingMallAiBackendSellerOnboarding } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSellerOnboarding";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate hard deletion of a seller onboarding record by admin.
 *
 * This test ensures an admin can permanently (hard) delete a specific seller onboarding record. It verifies correct authorization, deletion, audit-trailing, error handling, and that the deleted record is not retrievable afterwards. Also tests edge and negative scenarios to enforce correct system error responses.
 *
 * Step-by-step process:
 * 1. Register an admin account.
 * 2. Log in as admin and ensure Authorization header is set.
 * 3. Register a new seller (provides a sellerId for onboarding).
 * 4. As admin, create an onboarding record for the seller.
 * 5. As admin, delete the onboarding record with correct sellerId and onboardingId.
 * 6. As admin, attempt to retrieve the deleted onboarding via search (should not appear).
 * 7. As admin, attempt a second deletion of the same onboardingId (should return not found or appropriate error).
 * 8. As admin, attempt to delete a completely non-existent onboardingId (should return not found or error).
 * 9. (Optional) Attempt deletion with an unauthorized connection (skipped: only admin endpoints provided).
 * 10. Throughout, ensure each operation could be audited (covered by API contract; not tested here but left as an assertion note).
 */
export async function test_api_admin_delete_seller_onboarding_record(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPW!2345";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);
  TestValidator.equals("admin email matches")(adminSignUp.email)(adminEmail);

  // 2. Log in as admin
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);
  TestValidator.equals("admin login email matches")(adminSignIn.email)(adminEmail);

  // 3. Register a seller
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "SellerPW@4321",
      companyName: "Shop Company " + RandomGenerator.alphaNumeric(7),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(1),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUp);
  const sellerId = sellerSignUp.sellerId;

  // 4. As admin, create onboarding record for seller
  const onboardingStepCode = "application";
  const onboardingStepStatus = "pending";
  const onboardingSearchResp = await api.functional.shoppingMallAiBackend.admin.sellers.onboardings.patchBySellerid(connection, {
    sellerId,
    body: {
      seller_id: sellerId,
      step_code: onboardingStepCode,
      step_status: onboardingStepStatus,
      approved_by: adminSignIn.adminId,
      occurred_from: null,
      occurred_to: null,
      page: null,
      limit: null,
      orderBy: null,
      orderDir: null,
    } satisfies IShoppingMallAiBackendSellerOnboarding.IRequest,
  });
  typia.assert(onboardingSearchResp);
  // Ensure onboarding record exists
  TestValidator.predicate("at least one onboarding returned for seller")(
    onboardingSearchResp.data.length > 0,
  );
  const onboarding = onboardingSearchResp.data[0];
  typia.assert(onboarding);

  // 5. As admin, delete the onboarding record
  const eraseResult = await api.functional.shoppingMallAiBackend.admin.sellers.onboardings.eraseBySelleridAndOnboardingid(connection, {
    sellerId,
    onboardingId: onboarding.id,
  });
  TestValidator.equals("erase result is void")(eraseResult)(undefined);

  // 6. As admin, try to search for deleted onboarding (should not appear)
  const afterDeleteSearch = await api.functional.shoppingMallAiBackend.admin.sellers.onboardings.patchBySellerid(connection, {
    sellerId,
    body: {
      seller_id: sellerId,
      step_code: onboardingStepCode,
      step_status: onboardingStepStatus,
      approved_by: adminSignIn.adminId,
      occurred_from: null,
      occurred_to: null,
      page: null,
      limit: null,
      orderBy: null,
      orderDir: null,
    } satisfies IShoppingMallAiBackendSellerOnboarding.IRequest,
  });
  typia.assert(afterDeleteSearch);
  TestValidator.predicate("deleted onboardingId does not appear")(
    !afterDeleteSearch.data.some((o) => o.id === onboarding.id),
  );

  // 7. Attempt to delete same onboarding again (should error)
  await TestValidator.error("already deleted onboarding removes with error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.onboardings.eraseBySelleridAndOnboardingid(connection, {
        sellerId,
        onboardingId: onboarding.id,
      });
    },
  );

  // 8. Attempt to delete a non-existent onboarding id (should error)
  await TestValidator.error("deleting non-existent onboarding id errors")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.sellers.onboardings.eraseBySelleridAndOnboardingid(connection, {
        sellerId,
        onboardingId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 9. (Skipped) Unauthenticated/unauthorized deletion attempts (no endpoint for unauthorized, since all require admin login)
  // 10. Audit-trail is handled by API backend (note in documentation)
}

