import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IPageIShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrder";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPayment";
import type { IShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPaymentLog";
import type { IPageIShoppingMallAiBackendOrderPaymentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderPaymentLog";

/**
 * Validate advanced payment log searching for an order payment as an admin.
 *
 * This test verifies that an admin can search, filter, and paginate payment log records for any order payment in the system—regardless of ownership. It applies various filters (log_type, date range, pagination), checks that logs with sensitive or error details are visible to admins as business policy allows, confirms correct response structure, and ensures error handling is proper for invalid access.
 *
 * Steps:
 * 1. Search for an order visible to admin (any order suffices)
 * 2. Create a payment for that order as admin
 * 3. Insert diverse payment logs (types: request, response, error)
 * 4. Search logs
 *    a. Unfiltered (all logs)
 *    b. By log_type
 *    c. By occurred_at date-range
 *    d. By pagination
 * 5. Confirm log content and pagination correctness
 * 6. Validate sensitive/error content is present for admins
 * 7. Test error handling for invalid payment id
 */
export async function test_api_order_payment_log_search_as_admin_with_advanced_filters(
  connection: api.IConnection,
) {
  // 1. Search for any order (admin has global access)
  const orderSearch = await api.functional.shoppingMallAiBackend.admin.orders.search(connection, {
    body: {
      page: 1,
      pageSize: 1,
      sort: '-created_at',
    },
  });
  typia.assert(orderSearch);
  TestValidator.predicate('admin can see at least one order')(orderSearch.data.length > 0);
  const order = orderSearch.data[0];

  // 2. Create payment for the found order
  const payment = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      payment_provider_id: typia.random<string & tags.Format<'uuid'>>(),
      payment_method: 'card',
      transaction_id: `TXN-${Date.now()}`,
      amount: 10000,
      currency_code: order.currency_code,
      payment_result: 'completed',
      payment_context: '{"meta":"test"}',
    },
  });
  typia.assert(payment);

  // 3. Insert three logs (types: request, response, error)
  const now = new Date();
  const logs = await Promise.all([
    api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: payment.id,
      body: {
        log_type: 'request',
        log_context: '{"request":"initiated"}',
        occurred_at: new Date(now.getTime() - 1000 * 60 * 10).toISOString(),
      },
    }),
    api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: payment.id,
      body: {
        log_type: 'response',
        log_context: '{"response":"ok"}',
        occurred_at: now.toISOString(),
      },
    }),
    api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.create(connection, {
      orderId: order.id,
      orderPaymentId: payment.id,
      body: {
        log_type: 'error',
        log_context: '{"error":"card_declined","details":{"stack":"err_stack_here"}}',
        occurred_at: new Date(now.getTime() + 1000 * 60 * 10).toISOString(),
      },
    }),
  ]);
  logs.forEach(typia.assert);

  // 4a. Search all logs (no filter)
  const resultAll = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      order_payment_id: payment.id,
    },
  });
  typia.assert(resultAll);
  TestValidator.equals('should return all logs')(resultAll.data.length)(3);

  // 4b. Search by log type (error)
  const resultErrorType = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.search(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
    body: {
      order_payment_id: payment.id,
      log_type: 'error',
    },
  });
  typia.assert(resultErrorType);
