import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponHistory";
import type { IPageIShoppingMallAiBackendCouponHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCouponHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for searching and filtering coupon history records as an admin.
 *
 * Business context: Coupon histories are sensitive audit records for compliance. Only authorized (admin) users may access this endpoint. This test ensures that filter/search functionality and pagination operate correctly and securely.
 *
 * Validates:
 * - Admin authentication is required (dependency: login)
 * - Coupon history search returns accurate, filtered results when various filters are applied (coupon, issued_coupon_id, actor_id/type, action, date range, sort, pagination)
 * - Edge cases: (a) no filters (should return paginated unfiltered records); (b) all filters combined; (c) invalid filter parameters (should be error); (d) unauthorized user access (should be rejected)
 * - Pagination details are correct (page, limit, total records, data ordering)
 *
 * Steps:
 * 1. Authenticate as admin using valid credentials
 * 2. Search without any filters, validate paginated result structure
 * 3. Search with combination of filters (issued_coupon_id, actor_id, action, date range, sort), validate only relevant records returned
 * 4. Attempt search with invalid filter (invalid uuid, negative page/limit, nonsensical sort), expect error
 * 5. Logout / clear auth and repeat search to validate rejection for unauthorized user
 */
export async function test_api_coupon_history_search_filter_pagination(
  connection: api.IConnection,
) {
  // Step 1: Admin authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "correct-password";
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // Step 2: Search with NO filters (required fields: page + limit only)
  const unfiltered = await api.functional.shoppingMallAiBackend.admin.couponHistories.search(connection, {
    body: {
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendCouponHistory.IRequest,
  });
  typia.assert(unfiltered);
  TestValidator.predicate("pagination structure")(!!unfiltered.pagination && Array.isArray(unfiltered.data));

  // Step 3: Search with COMBINED filters (using random valid values)
  const filters = {
    issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    actor_type: "admin",
    action: "used",
    action_at_from: new Date(Date.now() - 7*24*3600*1000).toISOString(),
    action_at_to: new Date().toISOString(),
    page: 1,
    limit: 5,
    sort: "action_at desc",
  } satisfies IShoppingMallAiBackendCouponHistory.IRequest;
  const filtered = await api.functional.shoppingMallAiBackend.admin.couponHistories.search(connection, {
    body: filters,
  });
  typia.assert(filtered);
  if (filtered.data.length > 0) {
    TestValidator.equals("issued_coupon_id filtered correctly")(filtered.data[0].issued_coupon_id)(filters.issued_coupon_id);
    TestValidator.equals("actor_type filtered correctly")(filtered.data[0].actor_type)(filters.actor_type);
    TestValidator.equals("action filtered correctly")(filtered.data[0].action)(filters.action);
  }
  TestValidator.predicate("filtered results page")(filtered.pagination.current === 1 && filtered.pagination.limit === 5);

  // Step 4: Error on INVALID filters—should trigger error (invalid uuid, negative page, etc)
  await TestValidator.error("invalid filter params should error")(
    () => api.functional.shoppingMallAiBackend.admin.couponHistories.search(connection, {
      body: {
        issued_coupon_id: "not-a-uuid" as string & tags.Format<"uuid">,
        page: -1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 0 as number & tags.Type<"int32"> & tags.Minimum<1>,
      } satisfies IShoppingMallAiBackendCouponHistory.IRequest,
    })
  );

  // Step 5: Unauthenticated access should fail
  // Simulate logout by clearing token (in this infra, overwriting Authorization header)
  const unauthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthorized user is rejected")(
    () => api.functional.shoppingMallAiBackend.admin.couponHistories.search(unauthConnection, {
      body: {
        page: 1,
        limit: 1,
      } satisfies IShoppingMallAiBackendCouponHistory.IRequest,
    })
  );
}

