import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSearchKeyword } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSearchKeyword";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test the successful workflow for a seller to create a product search keyword.
 *
 * This test simulates the full seller flow:
 * 1. Register a seller using valid KYC/business info
 * 2. Create a product owned by that seller
 * 3. Add a search keyword to the product
 * 4. Validate persistence and relationship of the created keyword
 * 5. Attempt to add the same keyword again (should fail due to uniqueness constraints)
 */
export async function test_api_product_search_keyword_creation_successful(
  connection: api.IConnection,
) {
  // 1. Register a seller (KYC/business data provided per API requirements)
  const email: string = typia.random<string & tags.Format<"email">>();
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email,
      password: "$Test123!test",
      companyName: RandomGenerator.name(),
      businessNumber: `${typia.random<number & tags.Type<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>>()}`,
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(2),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUp);
  TestValidator.equals("returned email matches input")(sellerSignUp.email)(email);
  const sellerId = sellerSignUp.sellerId;

  // 2. Create a product for the seller
  const productCode = `${RandomGenerator.alphaNumeric(8)}-${typia.random<number & tags.Type<"uint32">>()}`;
  const productName = RandomGenerator.name();
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: productName,
      status: "draft",
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);
  TestValidator.equals("seller_id matches registered seller")(product.seller_id)(sellerId);
  const productId = product.id;

  // 3. Add a search keyword to the product
  const searchKeyword = RandomGenerator.lexical(10);
  const keyword = await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.createProductSearchKeyword(connection, {
    productId,
    body: {
      product_id: productId,
      search_keyword: searchKeyword,
    } satisfies IShoppingMallAiBackendProductSearchKeyword.ICreate,
  });
  typia.assert(keyword);
  TestValidator.equals("keyword product_id matches")(keyword.product_id)(productId);
  TestValidator.equals("stored keyword matches input")(keyword.search_keyword)(searchKeyword);

  // 4. Try adding a duplicate search keyword (should error for uniqueness constraint)
  await TestValidator.error("duplicate keyword should be rejected")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.createProductSearchKeyword(connection, {
        productId,
        body: {
          product_id: productId,
          search_keyword: searchKeyword,
        } satisfies IShoppingMallAiBackendProductSearchKeyword.ICreate,
      });
    }
  );
}

