import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { IPageIShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendInquirySnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test verifying admin can audit/search all inquiry snapshots: filter, paginate, enumerate events, and enforce security.
 *
 * Business context:
 * - Product inquiry snapshots form a regulatory evidence chain for all changes (content, status, actor)
 * - Admins must be able to view and filter the full change history for any inquiry
 *
 * Process:
 * 1. Admin registers and is authenticated (get adminId, JWT)
 * 2. A product inquiry is created by a customer (simulate IDs as customer reg is unavailable)
 * 3. Inquiry is mutated multiple times to accumulate at least three change events/snapshots
 * 4. Admin creates an additional manual snapshot for broader test coverage
 * 5. Admin searches/filters with PATCH: all, by actor_id, by status, paginates, sorts, date window
 * 6. Results validated for filter effectiveness and record inclusion
 * 7. Negative scenario: search as non-admin (no Authorization) yields error
 * 8. Negative scenario: malformed filter (missing required inquiry_id) yields error
 */
export async function test_api_inquiry_snapshot_admin_search_advanced_audit_evidence(
  connection: api.IConnection,
) {
  // 1. Register admin and get JWT/profile
  const adminInfo = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongP@ss1!",
    },
  });
  typia.assert(adminInfo);

  // 2. Simulate customer & product IDs and create product inquiry
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const productId = typia.random<string & tags.Format<"uuid">>();
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: productId,
      title: "How durable is this backpack?",
      body: "Is the seam waterproof and does it have an inner sleeve?",
      public: true,
    },
  });
  typia.assert(inquiry);

  // 3. Update inquiry multiple times (triggers snapshot creation)
  const updA = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      title: "How durable is this backpack? (edit A)",
      status: "waiting",
    },
  });
  typia.assert(updA);

  const updB = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      body: "Does it come in blue?",
      status: "answered",
    },
  });
  typia.assert(updB);

  const updC = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      public: false,
      status: "blocked",
    },
  });
