import type { IPageIShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendInquirySnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test verifying admin can audit/search all inquiry snapshots: filter, paginate, enumerate events, and enforce security.
 *
 * Business context:
 * - Product inquiry snapshots form a regulatory evidence chain for all changes (content, status, actor)
 * - Admins must be able to view and filter the full change history for any inquiry
 *
 * Process:
 * 1. Admin registers and is authenticated (get adminId, JWT)
 * 2. A product inquiry is created by a customer (simulate IDs as customer reg is unavailable)
 * 3. Inquiry is mutated multiple times to accumulate at least three change events/snapshots
 * 4. Admin creates an additional manual snapshot for broader test coverage
 * 5. Admin searches/filters with PATCH: all, by actor_id, by status, paginates, sorts, date window
 * 6. Results validated for filter effectiveness and record inclusion
 * 7. Negative scenario: search as non-admin (no Authorization) yields error
 * 8. Negative scenario: malformed filter (missing required inquiry_id) yields error
 */
export async function test_api_inquiry_snapshot_admin_search_advanced_audit_evidence(
  connection: api.IConnection,
) {
  // 1. Register admin and get JWT/profile
  const adminInfo = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongP@ss1!",
    },
  });
  typia.assert(adminInfo);

  // 2. Simulate customer & product IDs and create product inquiry
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const productId = typia.random<string & tags.Format<"uuid">>();
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: productId,
      title: "How durable is this backpack?",
      body: "Is the seam waterproof and does it have an inner sleeve?",
      public: true,
    },
  });
  typia.assert(inquiry);

  // 3. Update inquiry multiple times (triggers snapshot creation)
  const updA = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      title: "How durable is this backpack? (edit A)",
      status: "waiting",
    },
  });
  typia.assert(updA);

  const updB = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      body: "Does it come in blue?",
      status: "answered",
    },
  });
  typia.assert(updB);

  const updC = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      public: false,
      status: "blocked",
    },
  });
  typia.assert(updC);

  // 4. As admin, manually snapshot the inquiry
  const nowIso = new Date().toISOString();
  // Status must be one of enum, so choose a valid value (e.g., use updC.status, if not then updB or updA, else "waiting")
  const allowedStatuses = ["waiting", "answered", "blocked", "under_review", "deleted"] as const;
  const resolveManualSnapStatus = () =>
    ([updC, updB, updA, inquiry]
      .map((o) => o.status)
      .find((s) => allowedStatuses.includes(s as any)) as typeof allowedStatuses[number]) || "waiting";
  const manualSnap = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.create(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      title: updC.title ?? updB.title ?? updA.title ?? inquiry.title,
      body: updC.body ?? updB.body ?? updA.body ?? inquiry.body,
      public: updC.public ?? updB.public ?? updA.public ?? inquiry.public,
      status: resolveManualSnapStatus(),
      actor_id: adminInfo.adminId,
      changed_at: nowIso,
    },
  });
  typia.assert(manualSnap);

  // 5. As admin, search all snapshots for this inquiry (no filter)
  const allSnaps = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
    },
  });
  typia.assert(allSnaps);
  TestValidator.predicate("should have at least 4 snapshots")(allSnaps.data.length >= 4);
  TestValidator.predicate("should include admin-created snapshot")(
    allSnaps.data.some((s) => s.actor_id === adminInfo.adminId),
  );

  // 5b. Filter by actor_id (customer)
  const byCustomer = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      actor_id: customerId,
    },
  });
  typia.assert(byCustomer);
  TestValidator.predicate("should include only customer-written events")(
    byCustomer.data.every((s) => s.actor_id === customerId),
  );

  // 5c. Filter by status ('answered', which was set by updB)
  const byStatus = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      status: "answered",
    },
  });
  typia.assert(byStatus);
  TestValidator.predicate("should include at least one answered snapshot")(
    byStatus.data.some((s) => s.status === "answered"),
  );

  // 5d. Pagination (limit=2, page=1)
  const paged = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      limit: 2,
      page: 1,
    },
  });
  typia.assert(paged);
  TestValidator.equals("should return only 2 results")(paged.data.length)(2);

  // 5e. Sorted by change time (desc)
  const sorted = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      sort_by: "changed_at",
      sort_direction: "desc",
    },
  });
  typia.assert(sorted);

  // 5f. Date range window: only most recent
  const afterManual = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      changed_at_from: nowIso,
      limit: 1,
    },
  });
  typia.assert(afterManual);
  TestValidator.predicate("at least one snapshot after manual creation")(
    afterManual.data.length >= 1,
  );

  // 6. Negative: Search as non-admin → Auth error expected
  if (!connection.headers) connection.headers = {};
  delete connection.headers.Authorization;
  await TestValidator.error("non-admin cannot search snapshots")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
      productInquiryId: inquiry.id,
      body: {
        inquiry_id: inquiry.id,
      },
    });
  });

  // 7. Negative: Malformed filter (missing required inquiry_id)
  connection.headers.Authorization = adminInfo.setHeaders.Authorization;
  await TestValidator.error("malformed filter causes server error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
      productInquiryId: inquiry.id,
      body: {} as any,
    });
  });
}

