import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSellerOnboarding } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSellerOnboarding";
import type { IPageIShoppingMallAiBackendSellerOnboarding } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSellerOnboarding";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate updating of a seller's own onboarding event (onboarding milestone record).
 *
 * This test ensures that a seller, after registration and authentication, can create and update their own onboarding events.
 * It verifies that only allowed fields are mutable, audit log fields behave correctly, and forbidden operations such as updating immutable fields
 * or modifying another seller's onboarding event are properly rejected by the API.
 *
 * 1. Register a new seller (sign-up) and sign in to obtain authentication tokens (JWT stored automatically in connection)
 * 2. Create an onboarding milestone event for the seller (step_code=document_upload, step_status=pending)
 * 3. Update the onboarding event (step_status -> completed, add note) and verify the updates
 * 4. Attempt forbidden updates (e.g., changing immutable step_code, or updating as the wrong seller) to ensure proper errors are thrown
 */
export async function test_api_seller_onboarding_update_by_self(connection: api.IConnection) {
  // 1. Register seller and login
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "ValidPassw0rd!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResp);

  // Login (mainly to initialize connection with JWT, but registration may already do this)
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: "ValidPassw0rd!"
    } satisfies ISellerAuth.SignIn,
  });

  // 2. Create seller onboarding milestone event (step_code=document_upload, pending)
  const onboardingResp = await api.functional.shoppingMallAiBackend.seller.sellers.onboardings.patchBySellerid(connection, {
    sellerId: signUpResp.sellerId,
    body: {
      seller_id: signUpResp.sellerId,
      step_code: "document_upload",
      step_status: "pending",
      approved_by: null,
      note: null,
      occurred_from: null,
      occurred_to: null,
      page: 1,
      limit: 1,
      orderBy: null,
      orderDir: null,
    } satisfies IShoppingMallAiBackendSellerOnboarding.IRequest,
  });
  typia.assert(onboardingResp);
  if (!onboardingResp.data.length) throw new Error("Failed to create onboarding event");
  const createdEvent = onboardingResp.data[0];

  // 3. Update: change step_status and add note
  const updateReq: IShoppingMallAiBackendSellerOnboarding.IUpdate = {
    id: createdEvent.id,
    step_status: "completed",
    note: "document verified",
    approved_by: null
  };
  const updatedEvent = await api.functional.shoppingMallAiBackend.seller.sellers.onboardings.putBySellerid(connection, {
    sellerId: signUpResp.sellerId,
    body: updateReq,
  });
  typia.assert(updatedEvent);
  TestValidator.equals("updated step_status")(updatedEvent.step_status)("completed");
  TestValidator.equals("note updated")(updatedEvent.note)("document verified");
  TestValidator.equals("step_code cannot change")(updatedEvent.step_code)(createdEvent.step_code);
  TestValidator.equals("seller_id cannot change")(updatedEvent.seller_id)(createdEvent.seller_id);

  // 4. Try forbidden update: attempt to update non-mutable field (e.g. step_code)
  await TestValidator.error("cannot change step_code via update")(() =>
    api.functional.shoppingMallAiBackend.seller.sellers.onboardings.putBySellerid(connection, {
      sellerId: signUpResp.sellerId,
      body: {
        ...updateReq,
        // @ts-ignore - purposely sending non-mutable field for error
        step_code: "ai_review"
      } as any, // Only mutable fields allowed by schema
    })
  );

  // 5. Try forbidden update: as another seller
  const otherSellerEmail = typia.random<string & tags.Format<"email">>();
  const otherSignUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: otherSellerEmail,
      password: "AnotherPassw0rd!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(8),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(otherSignUpResp);
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: otherSellerEmail,
      password: "AnotherPassw0rd!"
    } satisfies ISellerAuth.SignIn,
  });

  await TestValidator.error("cannot update another seller's onboarding event")(() =>
    api.functional.shoppingMallAiBackend.seller.sellers.onboardings.putBySellerid(connection, {
      sellerId: signUpResp.sellerId, // Try to update original seller's onboarding as other seller
      body: updateReq
    })
  );
}

