import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCategory";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for updating categories via admin API, covering valid update, duplicate code, permission denied, not found, and invalid parent checks.
 *
 * This test validates all critical aspects of updating category entities in the AI shopping mall backend admin API, including:
 * - successful update with valid admin
 * - uniqueness constraint for `code`
 * - permission enforcement (admin switching)
 * - not-found and referential/parent integrity
 * - cyclic and invalid parent relationship handling
 *
 * Steps:
 * 1. Register two admin users (admin1 for create/update, admin2 for permission testing)
 * 2. Create two categories (catA, catB) as admin1
 * 3. Update catA's name as admin1 and verify the response persists
 * 4. Attempt to set catA's code to duplicate (catB's code) and assert business error
 * 5. Update with random (non-existent) categoryId and check for not found error
 * 6. Attempt to update as different admin (simulate permission denied)
 * 7. Set category's parent_id to a non-existent value (invalid parent)
 * 8. Set parent/child relationship between catB and catA and validate integrity
 */
export async function test_api_category_update_valid_invalid_permission_and_conflict(connection: api.IConnection) {
  // 1. Register admin1
  const adminEmail1 = typia.random<string & tags.Format<"email">>();
  const admin1 = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail1,
      password: "1234",
    },
  });
  typia.assert(admin1);

  // Register admin2
  const adminEmail2 = typia.random<string & tags.Format<"email">>();
  const admin2 = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail2,
      password: "1234",
    },
  });
  typia.assert(admin2);

  // 2. Create two categories as admin1
  // Attach Authorization header for admin1
  connection.headers = { ...connection.headers, Authorization: admin1.setHeaders.Authorization };
  // Create catA
  const catAInput = {
    code: "code-catA",
    name: "Category A",
    created_by_admin_id: admin1.adminId,
    parent_id: null,
    display_order: 1,
    visible: true,
  } satisfies IShoppingMallAiBackendCategory.ICreate;
  const catA = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, { body: catAInput });
  typia.assert(catA);

  // Create catB
  const catBInput = {
    code: "code-catB",
    name: "Category B",
    created_by_admin_id: admin1.adminId,
    parent_id: null,
    display_order: 2,
    visible: true,
  } satisfies IShoppingMallAiBackendCategory.ICreate;
  const catB = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, { body: catBInput });
  typia.assert(catB);

  // 3. Update catA's name as admin1
  const updatedName = "Category A Updated";
  const updateA = await api.functional.shoppingMallAiBackend.admin.categories.updateCategory(connection, {
    categoryId: catA.id,
    body: { name: updatedName },
  });
  typia.assert(updateA);
  TestValidator.equals("update name")(updateA.name)(updatedName);

  // 4. Attempt duplicate code update (catA to catB's code)
  await TestValidator.error("duplicate code should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.categories.updateCategory(connection, {
      categoryId: catA.id,
      body: { code: catB.code },
    })
  );

  // 5. Update using nonexistent categoryId (random uuid)
  await TestValidator.error("not found should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.categories.updateCategory(connection, {
      categoryId: typia.random<string & tags.Format<"uuid">>(),
      body: { name: "NonExistent" },
    })
  );

  // 6. Attempt update as admin2 (should error: permission denied or not found)
  connection.headers = { ...connection.headers, Authorization: admin2.setHeaders.Authorization };
  await TestValidator.error("permission denied should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.categories.updateCategory(connection, {
      categoryId: catA.id,
      body: { name: "ShouldFail" },
    })
  );
  // Switch back to admin1
  connection.headers = { ...connection.headers, Authorization: admin1.setHeaders.Authorization };

  // 7. Set invalid parent_id (random uuid not matching any category)
  await TestValidator.error("invalid parent should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.categories.updateCategory(connection, {
      categoryId: catA.id,
      body: { parent_id: typia.random<string & tags.Format<"uuid">>() },
    })
  );

  // 8. Cyclic/parenting: set catB's parent_id to catA (should succeed if tree allows)
  const reparent = await api.functional.shoppingMallAiBackend.admin.categories.updateCategory(connection, {
    categoryId: catB.id,
    body: { parent_id: catA.id },
  });
  typia.assert(reparent);
  TestValidator.equals("reparent catB to catA")(reparent.parent_id)(catA.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCategory";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate soft-deleting (logical delete) of a category entity as an admin, and permission enforcement.
 *
 * This test confirms:
 * 1. Admin can create a root category, soft-delete it, and the operation completes with no error (deleted_at cannot be fetched directly as there is no list/search API).
 * 2. Deleting a non-existent or already-deleted category returns a runtime business error.
 * 3. If a parent category has an active child, deleting the parent fails (blocked or cascades with error, depending on backend logic).
 * 4. Permission is properly enforced: Non-admin users (or missing Authorization) cannot soft-delete categories.
 *
 * Test Steps:
 * 1. Register a new admin and extract adminId for creation privilege.
 * 2. Create a root category as admin, and then soft-delete it by UUID.
 * 3. Soft-delete using random (non-existent) UUID is denied (error).
 * 4. Create a parent & child category, attempt to delete the parent (expect error if active child exists).
 * 5. Attempt deletion as non-admin (remove Authorization header); must be denied.
 */
export async function test_api_category_soft_delete_success_dependency_and_not_found(connection: api.IConnection) {
  // 1. Register admin and obtain adminId, privilege
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPwd123!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAuth);
  const adminId = adminAuth.adminId;

  // 2. Create a root category as admin
  const categoryCode = RandomGenerator.alphaNumeric(9);
  const category = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: null,
      created_by_admin_id: adminId,
      code: categoryCode,
      name: RandomGenerator.name(),
      description: "Root category for soft-delete E2E test.",
      display_order: 1,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(category);

  // 3. Soft-delete the category as admin (should succeed)
  await api.functional.shoppingMallAiBackend.admin.categories.eraseCategory(connection, {
    categoryId: category.id,
  });

  // 4. Try to delete a non-existent or already deleted category — expect error
  await TestValidator.error("delete of non-existent category fails")(() =>
    api.functional.shoppingMallAiBackend.admin.categories.eraseCategory(connection, {
      categoryId: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 5. Parent-child delete: create parent and child, attempt parent deletion
  const parentCode = RandomGenerator.alphaNumeric(7);
  const parent = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: null,
      created_by_admin_id: adminId,
      code: parentCode,
      name: RandomGenerator.name(),
      description: "Parent category (for child block test).",
      display_order: 2,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(parent);
  const childCode = RandomGenerator.alphaNumeric(7);
  const child = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: parent.id,
      created_by_admin_id: adminId,
      code: childCode,
      name: RandomGenerator.name(),
      description: "Child category of parent (active)",
      display_order: 3,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(child);
  await TestValidator.error("cannot delete parent with active child — expect block or cascade failure")(() =>
    api.functional.shoppingMallAiBackend.admin.categories.eraseCategory(connection, {
      categoryId: parent.id,
    })
  );

  // 6. Permission enforcement: try as non-admin (remove Authorization header)
  const headers = { ...connection.headers };
  delete headers.Authorization;
  const noAuthConnection = { ...connection, headers };
  await TestValidator.error("permission denied for non-admin")(() =>
    api.functional.shoppingMallAiBackend.admin.categories.eraseCategory(noAuthConnection, {
      categoryId: child.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
