import type { IShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductCategoryMap";

/**
 * Validate that sellers can only retrieve the detail of product-category mappings they own, and that forbidden/not-found access is enforced for unauthorized or non-existing mappings.
 *
 * Business context:
 * - When a seller creates a product and maps it to a category, the seller should be able to fetch the mapping detail.
 * - Another seller should be forbidden from accessing this mapping (to check for permission enforcement).
 * - Attempting to fetch a non-existent mapping should result in an error.
 * - The scenario asks for an admin access check, but no admin authentication endpoint is provided, so admin-related tests are omitted.
 *
 * Test workflow:
 * 1. Seller A creates a product.
 * 2. Seller A creates a product-category mapping for their product.
 * 3. Seller A fetches mapping detail (should succeed).
 * 4. Seller B attempts to fetch Seller A's mapping (should fail with forbidden or not found error).
 * 5. Attempt to fetch a random/non-existing mapping (should return not found).
 */
export async function test_api_product_category_mapping_detail_accessible_by_seller_or_admin(
  connection: api.IConnection,
) {
  // 1. Seller A creates a product
  const sellerAId: string = typia.random<string & tags.Format<"uuid">>();
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);
  // 2. Seller A creates a product-category mapping for their product
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const mapping = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      category_id: categoryId,
      primary: true,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
  });
  typia.assert(mapping);
  // 3. Seller A fetches mapping detail (should succeed)
  const detail = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.at(connection, {
    productId: product.id,
    productCategoryMapId: mapping.id,
  });
  typia.assert(detail);
  TestValidator.equals("mapping.product_id matches product")(detail.product_id)(product.id);
  TestValidator.equals("mapping.category_id matches")(detail.category_id)(categoryId);
  TestValidator.equals("mapping.primary flag")(detail.primary)(true);
  // 4. Seller B attempts to fetch Seller A's mapping (should fail with forbidden or not found error)
  const sellerBId: string = typia.random<string & tags.Format<"uuid">>();
  // In a real E2E system, seller login/switching would be performed here, but no authentication API is provided, so we simulate role by passing in sellerBId to product creation only
  const productBySellerB = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerBId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productBySellerB);
  await TestValidator.error("Seller B forbidden/not found when fetching Seller A's mapping")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.at(connection, {
        productId: product.id,
        productCategoryMapId: mapping.id,
      });
    }
  );
  // 5. Attempt to fetch a random/non-existing mapping (should return not found)
  const nonExistingCategoryMapId: string = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Not found for non-existing mapping")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.at(connection, {
        productId: product.id,
        productCategoryMapId: nonExistingCategoryMapId,
      });
    }
  );
}

