import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductCategoryMap";

/**
 * Validate that an admin can retrieve the details of any product-category mapping using productId and productCategoryMapId.
 *
 * This test covers several scenarios:
 *   1. Admin retrieves mapping details successfully (happy path).
 *   2. Attempt to access a non-existent mapping (should error).
 *
 * Skipped scenarios (due to lack of API exposure):
 *   - Soft-delete: No API available to soft-delete products.
 *   - Non-admin/role-based permission checks: No authentication APIs provided.
 *   - Audit log verification: Not possible without log API.
 *
 * Steps:
 *   1. Create a new product as admin.
 *   2. Create a product-category mapping for that product.
 *   3. Retrieve the mapping using productId and mappingId, validate response fields.
 *   4. Attempt to retrieve with a non-existent mappingId (expect error).
 */
export async function test_api_admin_can_retrieve_any_product_category_mapping_detail(
  connection: api.IConnection,
) {
  // 1. Create a product as admin
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const productCode = RandomGenerator.alphaNumeric(8);
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(
    connection,
    {
      body: {
        seller_id: sellerId,
        code: productCode,
        name: "Test E2E Product",
        description: "Test product for product-category mapping E2E.",
        main_image_uri: null,
        status: "draft",
      } satisfies IShoppingMallAiBackendProduct.ICreate,
    },
  );
  typia.assert(product);

  // 2. Create a product-category mapping
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const mapping = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.create(
    connection,
    {
      productId: product.id,
      body: {
        product_id: product.id,
        category_id: categoryId,
        primary: true,
      } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
    },
  );
  typia.assert(mapping);

  // 3. Happy path: Retrieve the mapping as admin
  const read = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.at(
    connection,
    {
      productId: product.id,
      productCategoryMapId: mapping.id,
    },
  );
  typia.assert(read);
  TestValidator.equals("product id matches")(read.product_id)(product.id);
  TestValidator.equals("category id matches")(read.category_id)(categoryId);
  TestValidator.equals("primary flag matches")(read.primary)(true);

  // 4. Error path: Attempt with non-existent mapping id
  await TestValidator.error("non-existent mapping yields error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.at(
      connection,
      {
        productId: product.id,
        productCategoryMapId: typia.random<string & tags.Format<"uuid">>(),
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCategory";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductCategoryMap";

/**
 * Test creating a new product-category mapping for a seller's product.
 *
 * This test covers successful mapping creation, duplicate/illegal mapping error validation,
 * error handling for non-existent products or categories, and forbidden/ownership scenarios.
 *
 * Steps:
 * 1. Create a product as a seller
 * 2. Create a category as admin
 * 3. Successfully map product to category
 * 4. Attempt duplicate mapping (should fail)
 * 5. Attempt illegal mapping with category hierarchy (should fail if business logic enforced)
 * 6. Try mapping with non-existent product (should fail)
 * 7. Try mapping with non-existent category (should fail)
 * 8. Attempt as wrong seller (should be forbidden)
 * 9. Soft-deleted product scenario skipped due to lack of delete API
 */
export async function test_api_product_category_mapping_creation_success_and_duplicate_handling(
  connection: api.IConnection,
) {
  // 1. Seller creates a product
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.paragraph()(),
      status: "published",
      description: RandomGenerator.content()()(),
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 2. Admin creates a category
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const category = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      created_by_admin_id: adminId,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.paragraph()(1),
      display_order: 1,
      visible: true,
      description: RandomGenerator.content()()(),
      parent_id: null,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(category);

  // 3. Map product to category (success)
  const mapping = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      category_id: category.id,
      primary: true,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
  });
  typia.assert(mapping);
  TestValidator.equals("product_id matches")(mapping.product_id)(product.id);
  TestValidator.equals("category_id matches")(mapping.category_id)(category.id);
  TestValidator.equals("primary flag")(mapping.primary)(true);

  // 4. Attempt duplicate mapping (should error)
  await TestValidator.error("duplicate mapping should fail")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        category_id: category.id,
        primary: true,
      } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
    })
  );

  // 5. Attempt illegal hierarchy mapping
  const childCategory = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      created_by_admin_id: adminId,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.paragraph()(1),
      display_order: 2,
      visible: true,
      description: RandomGenerator.content()()(),
      parent_id: category.id,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(childCategory);
  await TestValidator.error("illegal parent-child mapping should fail")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        category_id: childCategory.id,
        primary: false,
      } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
    })
  );

  // 6. Use non-existent product id
  await TestValidator.error("non-existent product should 404")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
      productId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        product_id: typia.random<string & tags.Format<"uuid">>(),
        category_id: category.id,
        primary: true,
      } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
    })
  );

  // 7. Use non-existent category id
  await TestValidator.error("non-existent category should 404")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        category_id: typia.random<string & tags.Format<"uuid">>(),
        primary: true,
      } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
    })
  );

  // 8. Attempt as wrong seller (forbidden scenario)
  const otherSellerId = typia.random<string & tags.Format<"uuid">>();
  const otherProduct = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: otherSellerId,
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.paragraph()(),
      status: "published",
      description: RandomGenerator.content()()(),
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(otherProduct);
  await TestValidator.error("forbidden for wrong seller")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
      productId: otherProduct.id,
      body: {
        product_id: otherProduct.id,
        category_id: category.id,
        primary: true,
      } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
    })
  );

  // 9. Soft-deleted product scenario skipped (no delete API available)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCategory";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductCategoryMap";

/**
 * Validate the creation of product-category mappings and error states for admin operations.
 *
 * This test confirms that the admin can successfully create a valid product-category mapping provided both product and category exist and are active (not soft-deleted). It checks that duplicate mappings are disallowed, and that attempts to map to non-existent products or categories result in validation errors. It also implies that audit logging takes place with each mapping operation for compliance (though direct log verification is out-of-scope unless logs are an API output).
 *
 * Steps:
 * 1. Establish a valid category by admin action.
 * 2. Establish a valid product by admin action.
 * 3. Create a valid mapping between the product and category.
 * 4. Try to create the same mapping again (expect conflict error).
 * 5. Attempt to map to a non-existent product (expect validation error).
 * 6. Attempt to map to a non-existent category (expect validation error).
 * 7. (Note: Audit log presence is assumed as out-of-scope unless auditable via API; soft-deleted scenarios are omitted as deletion is not API-exposed.)
 */
export async function test_api_admin_product_category_mapping_creation_and_error_states(
  connection: api.IConnection,
) {
  // 1. Create a valid category
  const adminId: string = typia.random<string & tags.Format<"uuid">>();
  const category = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      parent_id: null,
      created_by_admin_id: adminId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
      visible: true,
    },
  });
  typia.assert(category);

  // 2. Create a valid product (assume admin creates the product with a seller UUID, which is random for the test)
  const sellerId: string = typia.random<string & tags.Format<"uuid">>();
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    },
  });
  typia.assert(product);

  // 3. Create a valid product-category mapping
  const mapping = await api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      category_id: category.id,
      primary: true,
    },
  });
  typia.assert(mapping);

  // 4. Attempt duplicate mapping (should error)
  await TestValidator.error("duplicate mapping error")(() =>
    api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.create(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        category_id: category.id,
        primary: true,
      },
    })
  );

  // 5. Attempt to map to a non-existent product (should error)
  await TestValidator.error("non-existent product error")(() =>
    api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.create(connection, {
      productId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        product_id: typia.random<string & tags.Format<"uuid">>(),
        category_id: category.id,
        primary: true,
      },
    })
  );

  // 6. Attempt to map to a non-existent category (should error)
  await TestValidator.error("non-existent category error")(() =>
    api.functional.shoppingMallAiBackend.admin.products.productCategoryMap.create(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        category_id: typia.random<string & tags.Format<"uuid">>(),
        primary: true,
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductCategoryMap";

/**
 * E2E test for updating a product-category mapping by a seller.
 *
 * Validates that only allowed fields ('primary') can be updated for a product-category mapping,
 * permissions are enforced (only the owning seller can update), 404s are handled for missing mappings,
 * and out-of-schema DTO submissions fail at type level. Audit/log entries are assumed but cannot be directly verified.
 *
 * Business scenario:
 * 1. Seller creates a product
 * 2. Seller creates a product-category mapping
 * 3. Seller successfully updates mapping's 'primary' status
 * 4. Attempt to update with extra/invalid fields fails (TS-level only)
 * 5. Update attempt on non-existent mapping fails
 * 6. Update attempt by a different seller fails (permission enforced)
 */
export async function test_api_product_category_mapping_update_by_seller(
  connection: api.IConnection,
) {
  // 1. Seller creates a product
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const productCode = RandomGenerator.alphaNumeric(12);
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: RandomGenerator.paragraph()(),
      status: "draft",
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);
  TestValidator.equals("seller_id matches")(product.seller_id)(sellerId);

  // 2. Seller creates a product-category mapping
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const mapping = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      category_id: categoryId,
      primary: false,
    } satisfies IShoppingMallAiBackendProductCategoryMap.ICreate,
  });
  typia.assert(mapping);
  TestValidator.equals("product_id matches")(mapping.product_id)(product.id);
  TestValidator.equals("category_id matches")(mapping.category_id)(categoryId);
  TestValidator.equals("primary default")(mapping.primary)(false);

  // 3. Seller updates mapping to set 'primary' to true
  const updated = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.update(connection, {
    productId: product.id,
    productCategoryMapId: mapping.id,
    body: {
      primary: true,
    } satisfies IShoppingMallAiBackendProductCategoryMap.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("mapping id unchanged")(updated.id)(mapping.id);
  TestValidator.equals("primary is set")(updated.primary)(true);

  // 4. Attempt update with out-of-scope/invalid field (should fail at TS level)
  // (Unimplementable as runtime since SDK/typia blocks, kept for test intent)
  // 5. Attempt to update a non-existent mapping (should yield error/404)
  await TestValidator.error("not found on update of non-existent mapping")(async () => {
    return api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.update(connection, {
      productId: product.id,
      productCategoryMapId: typia.random<string & tags.Format<"uuid">>(),
      body: { primary: false } satisfies IShoppingMallAiBackendProductCategoryMap.IUpdate,
    });
  });

  // 6. Attempt as a different seller (simulate different account context if possible)
  // (If authentication switching API were present, it would be invoked here. For now, connection reuse/different seller_id is used for simulation.)
  const anotherConnection = { ...connection };
  await TestValidator.error("unauthorized update by another seller")(async () => {
    return api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.update(
      anotherConnection,
      {
        productId: product.id,
        productCategoryMapId: mapping.id,
        body: { primary: false } satisfies IShoppingMallAiBackendProductCategoryMap.IUpdate,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendChannel";
import type { IShoppingMallAiBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCategory";
import type { IShoppingMallAiBackendChannelCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendChannelCategoryMap";
import type { IPageIShoppingMallAiBackendChannelCategoryMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendChannelCategoryMap";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin search/filter/pagination for channel-category mappings
 *
 * This test ensures the admin can search and paginate channel-category mappings using different filters and verifies the returned records match the requested filter criteria, are paginated, and carry correct metadata.
 *
 * Steps:
 * 1. Prepare one admin ID to use as creator for all resources.
 * 2. Create 2 channels (A, B) using admin create channel API with different codes/names.
 * 3. Create 2 categories (X, Y) using admin create category API with different codes/names.
 * 4. Create 3 channel-category maps:
 *    (A,X) → active,
 *    (A,Y) → active,
 *    (B,X) → active.
 * 5. Use search (PATCH) with the following cases:
 *    a. Filter by channel_id = A: expect (A,X) and (A,Y) to be returned, (B,X) excluded.
 *    b. Filter by category_id = X: expect (A,X), (B,X) only. (A,Y) excluded.
 *    c. Filter by active=true: expect only active (A,X), (A,Y), (B,X).
 *    d. Filter by active=false: expect empty result (since no mapping is deleted via API).
 *    e. Filter with channel_id=A, active=true: expect only (A,X), (A,Y).
 *    f. Pagination - set pageSize=1, page=2 on active=true: expect to get second record of active group.
 * 6. For each, check that only appropriate set of mappings returned and that pagination metadata is correct.
 * 7. Confirm all returned entities have corresponding relationship fields (channel_id, category_id), proper activity/deletion status, and audit timestamps.
 * 8. Audit logging of search event is assumed but cannot be verified via API in this contract.
 */
export async function test_api_channel_category_map_search_success_and_filter_by_channel(connection: api.IConnection) {
  // 1. Prepare admin ID (simulate as random UUID)
  const adminId = typia.random<string & tags.Format<"uuid">>();

  // 2. Create channels A and B
  const channelA = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      name: "ChannelA-" + RandomGenerator.alphabets(4),
      created_by_admin_id: adminId,
      description: "Test channel A",
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channelA);

  const channelB = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      name: "ChannelB-" + RandomGenerator.alphabets(4),
      created_by_admin_id: adminId,
      description: "Test channel B",
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channelB);

  // 3. Create categories X and Y
  const categoryX = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(7),
      name: "CategoryX-" + RandomGenerator.alphabets(4),
      created_by_admin_id: adminId,
      description: "Test category X",
      parent_id: null,
      display_order: 1,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(categoryX);

  const categoryY = await api.functional.shoppingMallAiBackend.admin.categories.createCategory(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(7),
      name: "CategoryY-" + RandomGenerator.alphabets(4),
      created_by_admin_id: adminId,
      description: "Test category Y",
      parent_id: null,
      display_order: 2,
      visible: true,
    } satisfies IShoppingMallAiBackendCategory.ICreate,
  });
  typia.assert(categoryY);

  // 4. Create channel-category-map records: (A,X)-active, (A,Y)-active, (B,X)-active
  const mappingAX = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.createChannelCategoryMap(connection, {
    body: {
      channel_id: channelA.id,
      category_id: categoryX.id,
    } satisfies IShoppingMallAiBackendChannelCategoryMap.ICreate,
  });
  typia.assert(mappingAX);

  const mappingAY = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.createChannelCategoryMap(connection, {
    body: {
      channel_id: channelA.id,
      category_id: categoryY.id,
    } satisfies IShoppingMallAiBackendChannelCategoryMap.ICreate,
  });
  typia.assert(mappingAY);

  const mappingBX = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.createChannelCategoryMap(connection, {
    body: {
      channel_id: channelB.id,
      category_id: categoryX.id,
    } satisfies IShoppingMallAiBackendChannelCategoryMap.ICreate,
  });
  typia.assert(mappingBX);

  // 5a. Filter by channel_id = channelA.id
  let search = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.searchChannelCategoryMap(connection, {
    body: { channel_id: channelA.id } satisfies IShoppingMallAiBackendChannelCategoryMap.IRequest,
  });
  typia.assert(search);
  TestValidator.predicate("all mappings are for channel A")(search.data.every(m => m.channel_id === channelA.id));

  // 5b. Filter by category_id = categoryX.id
  search = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.searchChannelCategoryMap(connection, {
    body: { category_id: categoryX.id } satisfies IShoppingMallAiBackendChannelCategoryMap.IRequest,
  });
  typia.assert(search);
  TestValidator.predicate("all mappings are for category X")(search.data.every(m => m.category_id === categoryX.id));

  // 5c. active=true
  search = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.searchChannelCategoryMap(connection, {
    body: { active: true } satisfies IShoppingMallAiBackendChannelCategoryMap.IRequest,
  });
  typia.assert(search);
  TestValidator.predicate("all mappings are active")(search.data.every(m => !m.deleted_at));

  // 5d. active=false (should be none unless a mapping got deleted)
  search = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.searchChannelCategoryMap(connection, {
    body: { active: false } satisfies IShoppingMallAiBackendChannelCategoryMap.IRequest,
  });
  typia.assert(search);
  TestValidator.predicate("no mapping is active")(search.data.length === 0);

  // 5e. channel_id=A, active=true
  search = await api.functional.shoppingMallAiBackend.admin.channelCategoryMap.searchChannelCategoryMap(connection, {
    body: { channel_id: channelA.id, active: true } satisfies IShoppingMallAiBackendChannelCategoryMap.IRequest,
  });
