import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IPageIShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomer";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate the admin panel's customer search API with advanced filters and pagination, ensuring correct response structure and error handling.
 *
 * This test simulates a realistic admin interaction with the customer search panel. Key business points:
 * - Admin login is required for all operations (authenticated scenario).
 * - All available search/filter options (email, nickname, verified status, joined date, pagination) are tested.
 * - Response structure (pagination meta and summary record array) is validated.
 * - Scenario covers positive flows (varied filter use, pagination) and negative ones (unauthorized request).
 * - Coverage includes privacy guarantees (actual masking is backend's duty; schema shape is enforced), and forbidden soft-deleted users (by filter logic).
 *
 * Steps:
 * 1. Authenticate as admin and verify the access token.
 * 2. Search customers with no filter, confirm list shape/contents.
 * 3. Search by partial email.
 * 4. Search by partial nickname.
 * 5. Search by phone-verified status.
 * 6. Search by join date window.
 * 7. Paginate with custom limit/page.
 * 8. Confirm soft-deleted/withdrawn accounts do not surface when excluded by status.
 * 9. Check unauthorized access error is handled as expected.
 */
export async function test_api_customer_search_admin_filter_pagination(connection: api.IConnection) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPass123!";
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);
  TestValidator.equals("setHeaders.Authorization is Bearer token")(true)(
    typeof adminSignIn.setHeaders.Authorization === "string" && adminSignIn.setHeaders.Authorization.startsWith("Bearer ")
  );

  // 2. All customer search: no filter (should produce some records)
  const respAll = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
    body: {},
  });
  typia.assert(respAll);
  TestValidator.predicate("pagination fields ok")(
    typeof respAll.pagination.current === "number" &&
    typeof respAll.pagination.limit === "number" &&
    typeof respAll.pagination.records === "number" &&
    typeof respAll.pagination.pages === "number"
  );
  TestValidator.predicate("summary records array present")(
    Array.isArray(respAll.data)
  );
  if (respAll.data.length > 0) {
    for (const customer of respAll.data) {
      typia.assert(customer);
    }
  }

  // 3. Filter by partial email
  const filterEmail = respAll.data.length > 0 ? respAll.data[0].email.slice(0, 4) : "a";
  const respByEmail = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
    body: { email: filterEmail },
  });
  typia.assert(respByEmail);
  for (const customer of respByEmail.data) {
    TestValidator.predicate("email partial match")(
      customer.email.includes(filterEmail)
    );
  }

  // 4. Filter by partial nickname
  if (respAll.data.length > 0) {
    const filterNickname = respAll.data[0].nickname.slice(0, 2);
    const respByNick = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
      body: { nickname: filterNickname },
    });
    typia.assert(respByNick);
    for (const customer of respByNick.data) {
      TestValidator.predicate("nickname partial match")(
        customer.nickname.includes(filterNickname)
      );
    }
  }

  // 5. Filter by phone_verified true
  const respByPhoneVerified = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
    body: { phone_verified: true },
  });
  typia.assert(respByPhoneVerified);
  for (const customer of respByPhoneVerified.data) {
    TestValidator.predicate("phone string format")(
      typeof customer.phone === "string"
    );
  }

  // 6. Registration date window: pick customer date and filter by that
  if (respAll.data.length > 0) {
    const anyCustomer = respAll.data[0];
    const joined_at = anyCustomer.joined_at;
    const respByDate = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
      body: { joined_from: joined_at, joined_to: joined_at },
    });
    typia.assert(respByDate);
    for (const customer of respByDate.data) {
      TestValidator.equals("joined_at matches filter")(customer.joined_at)(joined_at);
    }
  }

  // 7. Pagination: set page and limit
  const respPaging = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
    body: { page: 1, pageSize: 2 },
  });
  typia.assert(respPaging);
  TestValidator.equals("limit matches pageSize")(respPaging.pagination.limit)(2);
  TestValidator.equals("current page is 1")(respPaging.pagination.current)(1);
  TestValidator.predicate("max 2 records on page")(respPaging.data.length <= 2);

  // 8. Check status filter for 'withdrawn' exclusion
  if (respAll.data.find((c) => c.status === "withdrawn")) {
    const respNoWithdrawn = await api.functional.shoppingMallAiBackend.admin.customers.search(connection, {
      body: { status: "active" },
    });
    typia.assert(respNoWithdrawn);
    for (const customer of respNoWithdrawn.data) {
      TestValidator.notEquals("No withdrawn/soft-deleted in active filter")(customer.status)("withdrawn");
    }
  }

  // 9. Unauthorized access rejection
  const anonymousConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized access rejected")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.customers.search(anonymousConnection, {
        body: {},
      });
    }
  );
}

