import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IPageIShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProduct";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates that admin can perform advanced product searches using various filter combinations
 * and pagination, as well as handling empty and edge case scenarios.
 *
 * Business context:
 * - Only admin role can access this endpoint
 * - Results should exactly match filter and pagination input
 * - Edge cases like non-existent values, out-of-bounds pagination, and missing authentication should be handled gracefully
 *
 * Step-by-step process:
 * 1. Register and log in as a new admin to obtain credentials
 * 2. Search with no filters (retrieve all, baseline pagination)
 * 3. Search by random non-existent name (get empty result)
 * 4. Search by a real status value (sampled from results if any exist)
 * 5. Search with multi-level sort and basic paging
 * 6. Search using pageSize exceeding server-side max (cap or error)
 * 7. Request negative page (should error)
 * 8. Remove Authorization, verify forbidden error for unauthenticated call
 */
export async function test_api_admin_product_search_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Admin registration and login
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "P@ssw0rd!";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });

  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });

  // 2. Search with no filters or paging - should list products with pagination structure
  const allResult = await api.functional.shoppingMallAiBackend.admin.products.search(connection, {
    body: {} satisfies IShoppingMallAiBackendProduct.IRequest,
  });
  typia.assert(allResult);
  TestValidator.predicate("pagination present in all-result")(
    !!allResult.pagination && Array.isArray(allResult.data)
  );

  // 3. Search with a random, almost impossible-to-match name to trigger empty results
  const randomNoMatchName = typia.random<string & tags.Format<"uuid">>();
  const emptyResult = await api.functional.shoppingMallAiBackend.admin.products.search(connection, {
    body: {
      filter: { name: randomNoMatchName },
    } satisfies IShoppingMallAiBackendProduct.IRequest,
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty search for random name")(
    emptyResult.data.length
  )(0);

  // 4. If available, grab one real status and search for it specifically
  let sampleStatus: string | undefined = undefined;
  if (allResult.data.length > 0) sampleStatus = allResult.data[0].status;
  if (sampleStatus) {
    const statusResult = await api.functional.shoppingMallAiBackend.admin.products.search(connection, {
      body: {
        filter: { status: sampleStatus },
      } satisfies IShoppingMallAiBackendProduct.IRequest,
    });
    typia.assert(statusResult);
    for (const prod of statusResult.data) {
      TestValidator.equals("status matches filter")(prod.status)(sampleStatus);
    }
  }

  // 5. Search with multi-level sort (name ascending, created_at descending) and paging
  const sortResult = await api.functional.shoppingMallAiBackend.admin.products.search(connection, {
    body: {
      sort: [
        { field: "name", direction: "asc" },
        { field: "created_at", direction: "desc" },
      ],
      page: 1,
      pageSize: 5,
    } satisfies IShoppingMallAiBackendProduct.IRequest,
  });
  typia.assert(sortResult);
  if (sortResult.data.length > 1) {
    for (let i = 1; i < sortResult.data.length; i++) {
      TestValidator.predicate("sorted by name ascending")(
        sortResult.data[i - 1].name <= sortResult.data[i].name,
      );
    }
  }

  // 6. Edge: Excessively large pageSize should either cap or throw error
  try {
    const hugePageReq = await api.functional.shoppingMallAiBackend.admin.products.search(connection, {
      body: {
        pageSize: 100000,
      } satisfies IShoppingMallAiBackendProduct.IRequest,
    });
    typia.assert(hugePageReq);
    TestValidator.predicate("large pageSize is capped")(
      hugePageReq.data.length <= 1000,
    );
  } catch {
    // Acceptable: system may throw instead of cap
  }

  // 7. Edge: Negative page number (should error)
  await TestValidator.error("negative page triggers error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.search(connection, {
        body: {
          page: -1,
        } satisfies IShoppingMallAiBackendProduct.IRequest,
      });
    },
  );

  // 8. Unauthenticated: remove token and confirm forbidden
  const prevAuth = connection.headers?.Authorization;
  if (connection.headers) delete connection.headers.Authorization;
  await TestValidator.error("forbidden when token removed")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.search(connection, {
        body: {} satisfies IShoppingMallAiBackendProduct.IRequest,
      });
    },
  );
  if (connection.headers && prevAuth)
    connection.headers.Authorization = prevAuth;
}

