 *
 * This test performs the following steps:
 * 1. Register two separate sellers (Seller A and Seller B)
 * 2. Authenticate as Seller A
 * 3. Search for all products and verify only Seller A's products are returned
 * 4. Search using a non-existent filter and confirm result is empty
 * 5. Attempt to search with another seller's ID as filter and confirm RBAC enforcement
 * 6. Simulate unauthorized access and confirm denial or empty data
 */
export async function test_api_seller_product_search_role_and_scope_enforcement(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerARegister = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerARegister);
  const sellerAId = sellerARegister.sellerId;

  // 2. Register Seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBRegister = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerBRegister);
  const sellerBId = sellerBRegister.sellerId;

  // 3. Authenticate as Seller A
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerAEmail,
      password: "Password123!",
    },
  });

  // 4. Search for all products as Seller A (expect only Seller A's products)
  const allAResult = await api.functional.shoppingMallAiBackend.seller.products.search(connection, {
    body: {},
  });
  typia.assert(allAResult);
  TestValidator.predicate("all returned products are Seller A's")(
    allAResult.data.every((p) => p.seller_id === sellerAId)
  );

  // 5. Search using a non-existent code filter (expect empty result)
  const nonExist = await api.functional.shoppingMallAiBackend.seller.products.search(connection, {
    body: { filter: { code: "__nonexistent_test_code__" } },
  });
