  TestValidator.equals("empty result for filtered nonexist code")(nonExist.data.length)(0);

  // 6. Attempt to filter by sellerId = sellerBId as Seller A (expect no data/cross-RBAC leakage)
  const byOtherSeller = await api.functional.shoppingMallAiBackend.seller.products.search(connection, {
    body: { filter: { sellerId: sellerBId } },
  });
