  });
  typia.assert(none);
  TestValidator.equals("empty data")(none.data.length)(0);
  TestValidator.predicate("valid pagination")(!!none.pagination);

  // 6. Access denied for non-admin token (simulate missing Authorization)
  const noAuthConnection: api.IConnection = {
    ...connection,
    headers: connection.headers
      ? Object.fromEntries(
          Object.entries(connection.headers).filter(([key]) => key !== "Authorization")
        )
      : undefined,
  };
  await TestValidator.error("access denied for non-admin")(() =>
    api.functional.shoppingMallAiBackend.admin.admins.search(noAuthConnection, { body: {} })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAdmin";
import type { IPageIShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate update process of admin account profile fields (excluding password) as another admin user.
 *
 * This test covers several critical cases:
 *
 * 1. Successfully update permissible fields of an existing admin (role/status/name) as another admin, then verify updates via a subsequent search.
 * 2. Attempt update with missing or invalid fields (e.g., name=null, invalid role/status)—expect a validation failure.
 * 3. Attempt update with an ID that does not exist—expect not found error.
 * 4. Confirm that attempting to update password field is blocked for this endpoint.
 * 5. Attempt update with a non-admin (unauthorized) role/token—expect forbidden error.
 *
 * Steps:
 * 1. Login as an admin (to get privileges)
 * 2. Obtain an existing admin's id via admins search endpoint (for valid update)
 * 3. Update allowed fields (name, role, status) for that id (PUT /shoppingMallAiBackend/admin/admins) and verify changes via search
 * 4. Attempt update with body missing all allowed fields (should fail validation)
 * 5. Attempt update with invalid role/status values (should fail validation)
 * 6. Attempt update for a random UUID not corresponding to any admin (should fail not found)
 * 7. Attempt to supply a password change (should have no effect)
 * 8. Simulate update attempt when not authenticated as admin (e.g., remove Authorization header) and confirm forbidden
 */
export async function test_api_admin_update_profile_fields_and_error_handling(connection: api.IConnection) {
  // 1. Login as an admin to obtain privilege
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "test-Password123!";
  // Assume admin already exists. Otherwise, sign-up logic would be required.
  // For test, login as this admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignIn,
  });
  // 2. Obtain an existing admin's id (excluding the logged-in admin if possible)
  const adminList = await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: { limit: 10 } satisfies IShoppingMallAiBackendAdmin.IRequest,
  });
  typia.assert(adminList);
  const targetAdmin = adminList.data.find(a => a.email !== adminEmail) ?? adminList.data[0];
  let baseAdmin = targetAdmin ?? adminList.data[0];
  typia.assert(baseAdmin);
  // 3. Update permissible fields (name, role, status)
  const updatedName = baseAdmin.name + "_updated";
  const updatedRole = baseAdmin.role === "operator" ? "auditor" : "operator";
  const updatedStatus = baseAdmin.status === "active" ? "suspended" : "active";
  const updateResult = await api.functional.shoppingMallAiBackend.admin.admins.update(connection, {
    body: { id: baseAdmin.id, name: updatedName, role: updatedRole, status: updatedStatus } satisfies IShoppingMallAiBackendAdmin.IUpdate,
  });
  typia.assert(updateResult);
  TestValidator.equals("admin name updated")(updateResult.name)(updatedName);
  TestValidator.equals("admin role updated")(updateResult.role)(updatedRole);
  TestValidator.equals("admin status updated")(updateResult.status)(updatedStatus);
  // 4. Fetch updated admin from list to confirm
  const adminAfter = (await api.functional.shoppingMallAiBackend.admin.admins.search(connection, {
    body: { email: baseAdmin.email } satisfies IShoppingMallAiBackendAdmin.IRequest,
  })).data.find(a => a.id === baseAdmin.id);
  TestValidator.equals("name reflected")(adminAfter?.name)(updatedName);
  TestValidator.equals("role reflected")(adminAfter?.role)(updatedRole);
  TestValidator.equals("status reflected")(adminAfter?.status)(updatedStatus);
  // 5. Attempt update with missing all permitted fields (should fail)
  await TestValidator.error("update with missing fields fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.admins.update(connection, {
      body: { id: baseAdmin.id } satisfies IShoppingMallAiBackendAdmin.IUpdate,
    });
  });
  // 6. Attempt update with invalid role/status (should fail)
  await TestValidator.error("update with invalid role fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.admins.update(connection, {
      body: { id: baseAdmin.id, name: "Invalid", role: "banana", status: "apple" } satisfies IShoppingMallAiBackendAdmin.IUpdate,
    });
  });
  // 7. Attempt update for a non-existent admin id
  await TestValidator.error("update non-existent id fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.admins.update(connection, {
      body: { id: typia.random<string & tags.Format<"uuid">>(), name: "NotExist" } satisfies IShoppingMallAiBackendAdmin.IUpdate,
    });
  });
  // 8. Simulate update with password field—ensure it is ignored (IUpdate type does not contain password, so cannot send it; type violation, test is skipped)
  // 9. Simulate unauthorized role (remove Authorization header)
  const noAuthConnection = { ...connection, headers: { ...connection.headers } };
  delete noAuthConnection.headers["Authorization"];
  await TestValidator.error("update with no auth is forbidden")(async () => {
    await api.functional.shoppingMallAiBackend.admin.admins.update(noAuthConnection, {
      body: { id: baseAdmin.id, name: "UnauthorizedAttempt" } satisfies IShoppingMallAiBackendAdmin.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachment";
import type { IShoppingMallAiBackendAttachmentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachmentLog";
import type { IPageIShoppingMallAiBackendAttachmentLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAttachmentLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test: Validate log search for attachment (admin only) with pagination/filtering
 *
 * Business context:
 * Attachment audit log search is security-critical. Admins must be able to search event logs
 * for a given attachment file, filtering by business event, date, operator, and paging. Result
 * must always be for the correct attachment, only include valid logs, and supply correct pagination meta.
 *
 * Steps:
 * 1. Create a new attachment as admin
 * 2. Create multiple log entries (upload, download, access) for that attachment with different event_types, contexts, and timestamps
 * 3. Search logs for the attachment:
 *    a. Without filter (should see all logs)
 *    b. Filtering by event_type
 *    c. Pagination (pageSize)
 *    d. Date/time range filter
 *    e. Edge: filter with no matches
 * 4. Validate every result has the correct attachment_id
 * 5. Validate all pagination metadata on response
 * 6. Error case: invalid attachmentId
 * 7. Error case: malformed filter (bad date)
 */
export async function test_api_attachment_log_search_basic_pagination_filtering(connection: api.IConnection) {
  // 1. Create a new attachment as admin
  const attachment = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, {
    body: {
      owner_id: typia.random<string & tags.Format<'uuid'>>(),
      owner_type: 'admin',
      file_name: RandomGenerator.alphaNumeric(14),
      file_size: typia.random<number & tags.Type<'int32'>>(),
      mime_type: 'application/pdf',
      storage_uri: `s3://e2e-test-bucket/file-${Date.now()}.pdf`,
      hash_sha256: RandomGenerator.alphaNumeric(64),
      uploaded_at: new Date(Date.now() - 86400000).toISOString(),
      expire_at: null,
      description: 'E2E: attachment for log search test',
    } satisfies IShoppingMallAiBackendAttachment.ICreate
  });
  typia.assert(attachment);

  // 2. Create multiple log entries (simulate upload, download, access)
  const event_types = ['upload', 'download', 'access'];
  const logs = [];
  const adminId = typia.random<string & tags.Format<'uuid'>>();
  const baseTimestamp = Date.now() - 100000;
  for (let i = 0; i < event_types.length; ++i) {
    const created = await api.functional.shoppingMallAiBackend.admin.attachments.logs.create(connection, {
      attachmentId: attachment.id,
      body: {
        event_type: event_types[i],
        ip_address: `192.168.1.${i+1}`,
        operated_by_admin_id: adminId,
        event_context: `Automated log ${i+1}`,
        event_at: new Date(baseTimestamp + i * 1000).toISOString(),
      } satisfies IShoppingMallAiBackendAttachmentLog.ICreate
    });
    typia.assert(created);
    logs.push(created);
  }

  // 3a. Search logs for the attachment with no filter (all logs)
  {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: {}
    });
    typia.assert(found);
    TestValidator.equals('returns all logs')(found.data.length)(logs.length);
    found.data.forEach(x => {
      TestValidator.equals('correct attachment_id')(x.attachment_id)(attachment.id);
    });
    TestValidator.equals('pagination current')(found.pagination.current)(1);
    TestValidator.equals('pagination limit')(found.pagination.limit)(25);
    TestValidator.equals('pagination records')(found.pagination.records)(logs.length);
    // Should be only one page (<=25)
    TestValidator.equals('pagination pages')(found.pagination.pages)(1);
  }

  // 3b. Filter by event_type
  for (let i = 0; i < event_types.length; ++i) {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_type: event_types[i] }
    });
    typia.assert(found);
    TestValidator.equals(`1 log for event_type ${event_types[i]}`)(found.data.length)(1);
    found.data.forEach(x => {
      TestValidator.equals('event_type')(x.event_type)(event_types[i]);
      TestValidator.equals('correct attachment_id')(x.attachment_id)(attachment.id);
    });
    // Pagination meta (should still be one page, but records=1)
    TestValidator.equals('pagination records')(found.pagination.records)(1);
    TestValidator.equals('pagination pages')(found.pagination.pages)(1);
  }

  // 3c. Pagination: pageSize=2
  {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { page: 1, pageSize: 2 }
    });
    typia.assert(found);
    TestValidator.equals('pageSize')(found.pagination.limit)(2);
    TestValidator.equals('first page')(found.pagination.current)(1);
    TestValidator.predicate('at most 2 logs')(found.data.length <= 2);
  }

  // 3d. Date/time range filter: should find logs in selected range
  {
    const from = logs[1].event_at;
    const to = logs[2].event_at;
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_at_from: from, event_at_to: to }
    });
    typia.assert(found);
    found.data.forEach(l => {
      TestValidator.predicate('event_at after from')(l.event_at >= from);
      TestValidator.predicate('event_at before to')(l.event_at <= to);
    });
    found.data.forEach(x => {
      TestValidator.equals('correct attachment_id')(x.attachment_id)(attachment.id);
    });
  }

  // 3e. Empty result when event_type does not exist
  {
    const found = await api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_type: 'nonexistent_event' }
    });
    typia.assert(found);
    TestValidator.equals('empty for nonexistent type')(found.data.length)(0);
    TestValidator.equals('records 0')(found.pagination.records)(0);
    TestValidator.equals('pages 0')(found.pagination.pages)(0);
  }

  // 4. Error: invalid attachment id
  await TestValidator.error('attachment id does not exist')(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: typia.random<string & tags.Format<'uuid'>>() ,
      body: {}
    })
  );

  // 5. Error: malformed filter (bad date)
  await TestValidator.error('malformed filter')(() =>
    api.functional.shoppingMallAiBackend.admin.attachments.logs.search(connection, {
      attachmentId: attachment.id,
      body: { event_at_from: 'not-a-date' as any }
    })
  );
}

