  const { customer } = registration;
  TestValidator.equals("registered customer email")(customer.email)(email);
  TestValidator.equals("registered customer nickname")(customer.nickname)(nickname);
  TestValidator.equals("registered customer status")(customer.status)("active");
  // Confirm auto-login by verifying Authorization header is present in connection.headers
  TestValidator.predicate("Authorization token issued")(
    typeof connection.headers === "object" &&
    typeof connection.headers["Authorization"] === "string" &&
    connection.headers["Authorization"].length > 0
  );

  // Step 2: Create a new active cart as the authenticated customer
  const cartBody: IShoppingMallAiBackendCart.ICreate = {
    status: "active",
    session_token: null, // Must be explicit null if not using guest/anonymous cart
  };

  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: cartBody
  });
  typia.assert(cart);
  TestValidator.equals("cart status is 'active'")(cart.status)("active");
  TestValidator.equals("cart session token null")(cart.session_token)(null);
  // Validate UUID format using regex .test() (boolean result)
  TestValidator.predicate("cart id is uuid")(
    typeof cart.id === "string" && /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(cart.id)
  );
  TestValidator.predicate("cart created_at is ISO8601")(
    typeof cart.created_at === "string" && !isNaN(Date.parse(cart.created_at))
  );
  TestValidator.predicate("cart updated_at is ISO8601")(
    typeof cart.updated_at === "string" && !isNaN(Date.parse(cart.updated_at))
  );
  if (cart.deleted_at !== undefined && cart.deleted_at !== null) {
    TestValidator.predicate("deleted_at ISO8601")(
      typeof cart.deleted_at === "string" && !isNaN(Date.parse(cart.deleted_at))
    );
  }

  // Step 3: Attempt to create a second 'active' cart for the same customer
  TestValidator.error("Only one active cart per customer - duplication blocked")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
        body: {
          status: "active",
          session_token: null,
        }
      });
    }
  );
}

