import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that an admin can retrieve the details of any product tag, regardless of product ownership, and receives correct errors for not found tags.
 *
 * Business context:
 * - Admin users should have permission to view any product tag detail using the admin endpoint, regardless of who created it.
 *
 * Scenario steps:
 * 1. Register a new admin account and log in to obtain admin privileges.
 * 2. Register and log in as a new seller (seller must exist to create products/tags).
 * 3. As seller, create a new product.
 * 4. As seller, create a product tag for the product and retain its id and details.
 * 5. Switch back to admin context (admin login).
 * 6. As admin, retrieve the tag detail by product id and tag id; check the tag's id, product_id, and tag string match creation.
 * 7. Attempt to retrieve a non-existent tag (random UUID); verify that a not found error is thrown.
 * 8. Skip deleted-tag lookup since no delete endpoint exists for tags.
 *
 * This test covers both the successful detail access and not-found error handling.
 */
export async function test_api_admin_product_tag_detail_access_and_not_found(connection: api.IConnection) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Test1234!";
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminReg);

  // 2. Admin login for Authorization header
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminLogin);

  // 3. Seller registration
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "SellerTest1!";
  const sellerCompany = `TestCompany-${Date.now()}`;
  const sellerReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: sellerCompany,
      businessNumber: "1012345678",
      representativeName: "Alice Example",
      address: "123 Test Rd, City, Country",
      phone: "0212345678",
    },
  });
  typia.assert(sellerReg);

  // Seller login to create product/tag
  const sellerLogin = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    },
  });
  typia.assert(sellerLogin);

  // 4. Seller creates a new product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerLogin.sellerId,
      code: `PROD-${Date.now()}`,
      name: "Sample E2E Product",
      description: "Test product for admin tag detail test.",
      main_image_uri: null,
      status: "published",
    },
  });
  typia.assert(product);

  // 5. Seller creates a product tag
  const tagString = `special-tag-${Math.floor(Math.random()*100000)}`;
  const productTag = await api.functional.shoppingMallAiBackend.seller.products.productTags.createProductTag(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      tag: tagString,
    },
  });
  typia.assert(productTag);

  // 6. Switch to admin context (admin login)
  const adminLoginAgain = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminLoginAgain);

  // 7. Admin fetches tag detail (success)
  const tagDetail = await api.functional.shoppingMallAiBackend.admin.products.productTags.atProductTag(connection, {
    productId: product.id,
    productTagId: productTag.id,
  });
  typia.assert(tagDetail);
  TestValidator.equals("tag id matches")(tagDetail.id)(productTag.id);
  TestValidator.equals("product id matches")(tagDetail.product_id)(product.id);
  TestValidator.equals("tag string matches")(tagDetail.tag)(tagString);

  // 8. Try fetching non-existent tag (error)
  const bogusTagId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not found on invalid tag")(() =>
    api.functional.shoppingMallAiBackend.admin.products.productTags.atProductTag(connection, {
      productId: product.id,
      productTagId: bogusTagId,
    })
  );
  // 9. No deletion test — no delete endpoint is provided for tags.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductTag";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * E2E test for creating product tags as a seller, covering:
 *   - Successful tag creation for a product the seller owns
 *   - Prevention of duplicate tags for the same product
 *   - Validation error when missing or invalid tag fields
 *   - Forbidden behavior when creating a tag on products not owned by the seller
 *
 * Steps:
 * 1. Register Seller A and login, obtaining a JWT
 * 2. Create a product as Seller A
 * 3. Successfully add a unique tag to that product (should succeed)
 * 4. Attempt to add the same tag string again for the same product (should fail due to tag uniqueness)
 * 5. Try to add a tag with missing/empty tag string (should fail validation)
 * 6. Register Seller B, login
 * 7. As Seller B, attempt to add a tag to Seller A's product (should be forbidden)
 * 8. Confirm result integrity
 *
 * Note: Connection header Authorization is updated inline for each seller;
 * in a parallelized E2E setup, use fresh connection instances per test for safety.
 */
export async function test_api_seller_create_product_tag_success_and_duplicate(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAPassword = "PasswordA1";
  const signUpAResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpAResponse);

  // 2. Login as Seller A
  const signInAResponse = await api.functional.auth.seller.login.signIn(connection, {
    body: { email: sellerAEmail, password: sellerAPassword } satisfies ISellerAuth.SignIn,
  });
  typia.assert(signInAResponse);
  connection.headers = { ...(connection.headers ?? {}), Authorization: `Bearer ${signInAResponse.token}` };

  // 3. Create a product as Seller A
  const productCreate = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: signInAResponse.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(),
      status: "published",
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productCreate);

  // 4. Successfully add a unique tag
  const tagValue = RandomGenerator.alphaNumeric(5);
  const tag1 = await api.functional.shoppingMallAiBackend.seller.products.productTags.createProductTag(connection, {
    productId: productCreate.id,
    body: { product_id: productCreate.id, tag: tagValue } satisfies IShoppingMallAiBackendProductTag.ICreate,
  });
  typia.assert(tag1);
  TestValidator.equals("tag matches input")(tag1.tag)(tagValue);

  // 5. Attempt to add the same tag again (should fail)
  await TestValidator.error("duplicate tag should fail")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productTags.createProductTag(connection, {
      productId: productCreate.id,
      body: { product_id: productCreate.id, tag: tagValue } satisfies IShoppingMallAiBackendProductTag.ICreate,
    });
  });

  // 6. Add tag with missing/empty tag (should fail)
  await TestValidator.error("empty tag fails")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productTags.createProductTag(connection, {
      productId: productCreate.id,
      body: { product_id: productCreate.id, tag: "" } satisfies IShoppingMallAiBackendProductTag.ICreate,
    });
  });

  // 7. Register Seller B and login
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBPassword = "PasswordB1";
  await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: sellerBPassword,
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  const signInBResponse = await api.functional.auth.seller.login.signIn(connection, {
    body: { email: sellerBEmail, password: sellerBPassword } satisfies ISellerAuth.SignIn,
  });
  typia.assert(signInBResponse);
  connection.headers = { ...(connection.headers ?? {}), Authorization: `Bearer ${signInBResponse.token}` };

  // 8. Attempt as Seller B to add a tag to Seller A's product (should be forbidden)
  await TestValidator.error("Seller B access forbidden")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productTags.createProductTag(connection, {
      productId: productCreate.id,
      body: { product_id: productCreate.id, tag: RandomGenerator.alphaNumeric(5) } satisfies IShoppingMallAiBackendProductTag.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
