import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductTag";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate admin ability to create product tags and related error handling.
 *
 * This function verifies the admin workflow for product tag management, ensuring both positive and negative cases. It tests:
 * 1. Proper admin authentication and seller/product creation prerequisite flow
 * 2. A successful creation of a product tag for an existing seller's product
 * 3. Rejection of duplicate tag creation for the same product (business validation)
 * 4. Prevention of tag creation for non-existent product (not found error)
 *
 * Detailed steps:
 * 1. Register and login as admin to acquire authorization
 * 2. Register and login as a seller to create a product (so it's not owned by admin)
 * 3. Seller creates a new product (collect id for tagging)
 * 4. Switch to admin authentication
 * 5. Admin creates a new tag on the seller's product, verify response
 * 6. Attempt to add the same tag string again for the same product (should fail)
 * 7. Attempt to tag a non-existent productId (should fail with not found)
 */
export async function test_api_admin_create_product_tag_and_validation(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Test1234!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, { body: { email: adminEmail, password: adminPassword } });
  typia.assert(adminSignUp);

  // 2. Login as admin (to store the token)
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, { body: { email: adminEmail, password: adminPassword } });
  typia.assert(adminSignIn);

  // 3. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Seller#123";
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, { body: {
    email: sellerEmail,
    password: sellerPassword,
    companyName: RandomGenerator.alphaNumeric(8),
    businessNumber: RandomGenerator.alphaNumeric(10),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.alphaNumeric(16),
    phone: RandomGenerator.mobile(),
  }});
  typia.assert(sellerSignUp);

  // 4. Seller login
  await api.functional.auth.seller.login.signIn(connection, { body: { email: sellerEmail, password: sellerPassword } });

  // 5. Seller creates a product
  const productInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: sellerSignUp.sellerId,
    code: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.paragraph()(1),
    status: "draft",
    description: RandomGenerator.content()()(),
    main_image_uri: null
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: productInput });
  typia.assert(product);

  // 6. Switch back to admin (re-login)
  await api.functional.auth.admin.login.signIn(connection, { body: { email: adminEmail, password: adminPassword } });

  // 7. Admin creates a product tag for the seller's product
  const tagString = RandomGenerator.alphabets(6);
  const tagInput = { product_id: product.id, tag: tagString } satisfies IShoppingMallAiBackendProductTag.ICreate;
  const productTag = await api.functional.shoppingMallAiBackend.admin.products.productTags.createProductTag(connection, { productId: product.id, body: tagInput });
  typia.assert(productTag);
  TestValidator.equals("tag string matches")(productTag.tag)(tagString);
  TestValidator.equals("product_id matches")(productTag.product_id)(product.id);

  // 8. Attempt to create the same tag again (duplicate error test)
  await TestValidator.error("duplicate tag creation rejected")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productTags.createProductTag(connection, { productId: product.id, body: tagInput });
  });

  // 9. Attempt to tag a non-existent product
  const fakeProductId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("tag on nonexistent product rejected")(async () => {
    await api.functional.shoppingMallAiBackend.admin.products.productTags.createProductTag(connection, { productId: fakeProductId, body: { product_id: fakeProductId, tag: RandomGenerator.alphabets(5) } });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductTag";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates seller-owned product tag updating and access control enforcement.
 *
 * Tests all critical workflows for updating a product tag:
 * - Positive: seller updates their own product tag successfully
 * - Negative: update with duplicate tag (per product), with invalid tag value, unauthorized seller
 *   attempts, and updates on non-existent product/tag
 *
 * This ensures that business rules (tag uniqueness, non-empty values) and RBAC constraints
 * (seller can only update their own resources) are enforced.
 *
 * Steps:
 * 1. Seller A registers and logs in
 * 2. Seller A creates a product
 * 3. Seller A creates two tags (tagA, tagDup)
 * 4. Seller A updates tagA to a new value (should succeed)
 * 5. Seller A updates tagA to duplicate value from tagDup (should fail)
 * 6. Seller A updates tagA to invalid value (empty string, should fail)
 * 7. Seller B registers and logs in, attempts to update Seller A's tag (should be forbidden)
 * 8. Seller A tries to update using a non-existent productTagId
 * 9. Seller A tries to update with a non-existent productId
 */
export async function test_api_seller_update_product_tag_title_and_access_control(connection: api.IConnection) {
  // 1. Seller A registers and logs in
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAPassword = "StrongPw1!";
  const sellerARegistration = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
      companyName: "AlphaBiz",
      businessNumber: "1234567890",
      representativeName: "Alice Alpha",
      address: "101 Alpha Street, City",
      phone: "010-1111-2222",
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(sellerARegistration);

  const sellerALogin = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
    } satisfies ISellerAuth.SignIn
  });
  typia.assert(sellerALogin);
  const sellerAId = sellerARegistration.sellerId;

  // 2. Seller A creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: "ABC1234-UNIQ",
      name: "Gadget of the Year",
      description: "Best trending gadget.",
      main_image_uri: null,
      status: "published"
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 3. Seller A creates two tags (tagA and tagDup)
  const tagA = await api.functional.shoppingMallAiBackend.seller.products.productTags.createProductTag(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      tag: "Best Seller"
    } satisfies IShoppingMallAiBackendProductTag.ICreate
  });
  typia.assert(tagA);
  const tagDup = await api.functional.shoppingMallAiBackend.seller.products.productTags.createProductTag(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      tag: "Limited Edition"
    } satisfies IShoppingMallAiBackendProductTag.ICreate
  });
  typia.assert(tagDup);

  // 4. Seller A updates tagA to a new value (success)
  const updatedTag = await api.functional.shoppingMallAiBackend.seller.products.productTags.updateProductTag(connection, {
    productId: product.id,
    productTagId: tagA.id,
    body: {
      tag: "Hot Item"
    } satisfies IShoppingMallAiBackendProductTag.IUpdate
  });
  typia.assert(updatedTag);
  TestValidator.equals("tag value updated")(updatedTag.tag)("Hot Item");

  // 5. Seller A updates tagA to duplicate value from tagDup (should fail validation)
  await TestValidator.error("duplicate tag should fail")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productTags.updateProductTag(connection, {
      productId: product.id,
      productTagId: tagA.id,
      body: { tag: tagDup.tag } satisfies IShoppingMallAiBackendProductTag.IUpdate
    })
  );

  // 6. Seller A updates tagA to invalid value (empty, should fail validation)
  await TestValidator.error("invalid tag (empty) should fail")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productTags.updateProductTag(connection, {
      productId: product.id,
      productTagId: tagA.id,
      body: { tag: "" } satisfies IShoppingMallAiBackendProductTag.IUpdate
    })
  );

  // 7. Seller B registers and logs in, attempts to update Seller A's tag (should be forbidden)
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBPassword = "StrongPw2!";
  const sellerBRegistration = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBEmail,
      password: sellerBPassword,
      companyName: "BetaBiz",
      businessNumber: "9876543210",
      representativeName: "Bob Beta",
      address: "101 Beta Street, City",
      phone: "010-3333-4444",
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(sellerBRegistration);
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerBEmail,
      password: sellerBPassword,
    } satisfies ISellerAuth.SignIn
  });

  await TestValidator.error("update by non-owner seller fails")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productTags.updateProductTag(connection, {
      productId: product.id,
      productTagId: tagA.id,
      body: { tag: "NonOwnerUpdate" } satisfies IShoppingMallAiBackendProductTag.IUpdate
    })
  );

  // 8. Seller A tries to update non-existent tagId
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
    } satisfies ISellerAuth.SignIn
  });
  const fakeTagId = typia.random<string & tags.Format<"uuid">>();
