/**
 * Test customer JWT logout, session invalidation and audit trace
 *
 * Validates the logout process for a customer:
 * 1. Registers a new customer (obtains customer profile and initial JWT)
 * 2. Logs in with the same credentials (gets a fresh JWT for session testing)
 * 3. Calls the logout endpoint as the authenticated customer
 * 4. Verifies logout response is successful ({ success: true })
 * 5. Ensures subsequent API calls with the (now invalid) JWT are rejected (token invalidation enforced)
 */
export async function test_api_customer_logout_success(connection: api.IConnection) {
  // 1. Register a new customer and get JWT
  const email = typia.random<string & tags.Format<"email">>();
  const password = "P@ssw0rd123!";
  const nickname = RandomGenerator.name();

  const signUpRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname,
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpRes);
  const registeredJwt = signUpRes.setHeaders.Authorization;

  // 2. Login as the registered customer to get a new JWT for this session
  const signInRes = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies ICustomerSignIn.Request,
  });
  typia.assert(signInRes);
  const loginJwt = signInRes.setHeaders.Authorization;

  // 3. Log out using the JWT from the login session
  const authedConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: loginJwt,
    },
  };
  const logoutRes = await api.functional.auth.customer.logout.signOut(authedConnection);
  typia.assert(logoutRes);
  TestValidator.equals("logout returns success")(logoutRes.success)(true);

  // 4. Attempt to log out again with the same (invalidated) JWT: must fail (401/403)
  await TestValidator.error("second logout attempt fails")(async () => {
    await api.functional.auth.customer.logout.signOut(authedConnection);
  });

  // 5. Any further authenticated call with the same JWT must also fail
  await TestValidator.error("logout JWT cannot be reused for auth")(async () => {
    await api.functional.auth.customer.logout.signOut(authedConnection);
  });
}

