  typia.assert(sellerLogin);
  // JWT is now stored in connection.headers automatically by SDK

  // 3. Create a business verification record for this seller
  const verificationReq: IShoppingMallAiBackendSellerBusinessVerification.IUpdate = {
    id: typia.random<string & tags.Format<"uuid">>(),
    verification_status: "pending",
    document_file_uri: "https://testdomain.com/document/" + RandomGenerator.alphaNumeric(8),
    reviewed_by: null,
    reviewed_at: null,
    note: null,
  };
  const createdVerification =
    await api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.update(
      connection,
      {
        sellerId: sellerSignUp.sellerId,
        body: verificationReq,
      },
    );
  typia.assert(createdVerification);

  // 4. Delete the business verification
  await api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.erase(
    connection,
    {
      sellerId: sellerSignUp.sellerId,
      businessVerificationId: createdVerification.id,
    },
  );

  // 5. Not implementable: No fetch endpoint for individual business verification, so cannot confirm resource is gone or audit logs. This is in line with current exposed APIs.
}

