  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "S3cureP@ssw0rd!",
      companyName: RandomGenerator.alphaNumeric(8),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.alphaNumeric(15),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUp);
  const sellerId = sellerSignUp.sellerId;
  const sellerEmail = sellerSignUp.email;

  // 2. Seller logs in
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: "S3cureP@ssw0rd!",
    } satisfies ISellerAuth.SignIn,
  });

  // 3. Seller creates a business verification record
  const verification = await api.functional.shoppingMallAiBackend.seller.sellers.businessVerifications.update(connection, {
    sellerId,
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      verification_status: "pending",
      reviewed_by: null,
      reviewed_at: null,
      note: null,
      document_file_uri: "https://example.com/document.pdf",
    } satisfies IShoppingMallAiBackendSellerBusinessVerification.IUpdate,
  });
  typia.assert(verification);
  const businessVerificationId = verification.id;

  // 4. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Adm1n$pAssw0rd";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 5. Admin logs in
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });

  // 6. Admin deletes the business verification record
  await api.functional.shoppingMallAiBackend.admin.sellers.businessVerifications.erase(connection, {
    sellerId,
    businessVerificationId,
  });

  // 7. Attempt to access the deleted business verification record
