import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate fetching the details of a seller's specific onboarding event.
 *
 * Business Context:
 * This test ensures that a seller can retrieve details of a specific onboarding step or milestone they've completed or are progressing through, verifying secure access control and traceability. It further validates that unauthorized sellers cannot fetch other sellers' onboarding records, and that invalid onboarding IDs are handled.
 *
 * Step-by-step process:
 * 1. Register a new seller.
 * 2. Login as the newly registered seller for authentication tokens.
 * 3. Create an onboarding event for that seller.
 * 4. Retrieve the onboarding event via GET /shoppingMallAiBackend/seller/sellers/{sellerId}/onboardings/{onboardingId}.
 * 5. Assert the onboarding event matches the originally created data.
 * 6. Negative case: Attempt to access this onboarding event from another (unauthorized) seller and assert failure (expected error).
 * 7. Negative case: Attempt to fetch onboarding event with a non-existent onboardingId (random UUID) and assert not found error.
 */
export async function test_api_seller_onboarding_detail_access(connection: api.IConnection) {
  // 1. Register new seller
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPassword1!";
  const companyName = RandomGenerator.alphabets(8) + "Inc.";
  const businessNumber = RandomGenerator.alphaNumeric(10);
  const representativeName = RandomGenerator.name();
  const address = RandomGenerator.paragraph()(1);
  const phone = RandomGenerator.mobile();

  const signup = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email,
      password,
      companyName,
      businessNumber,
      representativeName,
      address,
      phone,
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signup);

  const sellerId = signup.sellerId;

  // 2. Login as seller (token auto-set in connection)
  const signin = await api.functional.auth.seller.login.signIn(connection, {
    body: { email, password } satisfies ISellerAuth.SignIn,
  });
  typia.assert(signin);

  // 3. Create onboarding event for this seller
  const onboardingInput = {
    id: typia.random<string & tags.Format<"uuid">>(),
    step_status: "pending",
    approved_by: null,
    note: "Initial onboarding for compliance review.",
  } satisfies IShoppingMallAiBackendSellerOnboarding.IUpdate;
  const onboarding = await api.functional.shoppingMallAiBackend.seller.sellers.onboardings.update(connection, {
    sellerId,
    body: onboardingInput
  });
  typia.assert(onboarding);

  // 4. Retrieve onboarding event by ID (success case)
  const detail = await api.functional.shoppingMallAiBackend.seller.sellers.onboardings.at(connection, {
    sellerId,
    onboardingId: onboarding.id,
  });
  typia.assert(detail);
  // Assert retrieved details match the onboarding event
  TestValidator.equals("onboarding.id matches")(detail.id)(onboarding.id);
  TestValidator.equals("sellerId matches")(detail.seller_id)(sellerId);
  TestValidator.equals("step_status matches")(detail.step_status)(onboardingInput.step_status);
  TestValidator.equals("note matches")(detail.note)(onboardingInput.note);

  // 5. Attempt to access onboarding using another seller (forbidden)
  const otherEmail = typia.random<string & tags.Format<"email">>();
  const otherPassword = "OtherTestPassword2!";
  const signup2 = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: otherEmail,
      password: otherPassword,
      companyName: RandomGenerator.alphabets(8) + "Inc.",
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(1),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signup2);

  // Switch to other seller account
  await api.functional.auth.seller.login.signIn(connection, {
    body: { email: otherEmail, password: otherPassword } satisfies ISellerAuth.SignIn,
  });
  // Should receive error when accessing another seller's onboarding
  await TestValidator.error("forbidden for other sellers")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.onboardings.at(connection, {
        sellerId,
        onboardingId: onboarding.id,
      });
    }
  );

  // 6. Attempt to get a non-existent onboardingId (not found)
  await api.functional.auth.seller.login.signIn(connection, {
    body: { email, password } satisfies ISellerAuth.SignIn,
  });
  const randomOnboardingId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found for invalid onboardingId")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.onboardings.at(connection, {
        sellerId,
        onboardingId: randomOnboardingId,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAttachment";
import type { IPageIShoppingMallAiBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test for searching attachments with advanced filters as an admin.
 *
 * Validates comprehensive search and filter functionality for attachments
 * via the admin endpoint, ensuring business rules and edge cases are respected.
 *
 * Steps:
 * 1. Register a new admin to obtain authentication and permissions.
 * 2. Create multiple attachments (with diverse file names, mime types, owners, sizes, and expiry combinations).
 * 3. Perform paginated search queries with various filter combinations:
 *      a) Filter by exact file_name match.
 *      b) Filter by partial file_name.
 *      c) Filter by mime_type.
 *      d) Filter by owner_type.
 *      e) Test pagination fields (pageSize, page) and validate result splitting.
 *      f) Confirm attachments with expired 'expire_at' fields are not returned unless appropriate.
 *      g) Confirm soft-deleted attachments are not returned by default.
 *      h) Combine multiple filters for intersection search.
 * 4. Verify performing a search with no filters returns all permitted (non-expired, non-deleted) attachments.
 * 5. Verify that passing invalid values for filters (malformed UUID in owner_id, negative page size, etc.) results in a descriptive validation error (use TestValidator.error).
 * 6. Search for filter combinations that produce empty result sets and verify the data array is empty but query is successful.
 * 7. Confirm that results delivered to admin contain all attributes specified in ISummary and that no unauthorized files are present.
 * 8. (Audit log creation is mentioned, but if no direct audit log API is visible, this is not directly testable and will be omitted except for ensuring no error occurs.)
 *
 * Edge cases are included in the workflow. This suite validates both business and security rules.
 */
export async function test_api_attachment_search_with_advanced_filters(connection: api.IConnection) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: 'Password123!'
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminRes);
  // Connection now has Authorization header automatically

  // 2. Create diverse attachments for testing
  const attachmentPayloads: IShoppingMallAiBackendAttachment.ICreate[] = [
    // Regular active attachment, text file
    {
      owner_id: adminRes.adminId,
      owner_type: 'admin',
      file_name: 'report.txt',
      file_size: 1024,
      mime_type: 'text/plain',
      storage_uri: '/files/report.txt',
      hash_sha256: RandomGenerator.alphaNumeric(64),
      uploaded_at: new Date().toISOString(),
      expire_at: null,
      description: 'Annual report'
    },
    // PNG image owned by admin
    {
      owner_id: adminRes.adminId,
      owner_type: 'admin',
      file_name: 'diagram.png',
      file_size: 444444,
      mime_type: 'image/png',
      storage_uri: '/files/diagram.png',
      hash_sha256: RandomGenerator.alphaNumeric(64),
      uploaded_at: new Date().toISOString(),
      expire_at: null,
      description: 'Technical diagram'
    },
    // Docx file, expired
    {
      owner_id: adminRes.adminId,
      owner_type: 'admin',
      file_name: 'draft.docx',
      file_size: 204800,
      mime_type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      storage_uri: '/files/draft.docx',
      hash_sha256: RandomGenerator.alphaNumeric(64),
      uploaded_at: new Date().toISOString(),
      expire_at: new Date(Date.now() - 1000*60*60*24).toISOString(), // Yesterday
      description: 'Old draft (expired)'
    },
    // PDF file for different owner_type
    {
      owner_id: typia.random<string & tags.Format<'uuid'>>(),
      owner_type: 'product',
      file_name: 'spec.pdf',
      file_size: 555555,
      mime_type: 'application/pdf',
      storage_uri: '/files/spec.pdf',
      hash_sha256: RandomGenerator.alphaNumeric(64),
      uploaded_at: new Date().toISOString(),
      expire_at: null,
      description: 'Product spec sheet'
    }
  ];

  const attachmentEntities = [] as IShoppingMallAiBackendAttachment[];
  for (const createBody of attachmentPayloads) {
    const att = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, { body: createBody });
    typia.assert(att);
    attachmentEntities.push(att);
  }

  // 3. Paginated search with various filters and validation

  // a) Exact file_name match
  let output = await api.functional.shoppingMallAiBackend.admin.attachments.search(connection, {
    body: { file_name: 'report.txt' }
  });
  typia.assert(output);
  TestValidator.predicate('finds report.txt')(output.data.some(x => x.file_name === 'report.txt'));

  // b) Partial file_name search (e.g., 'repor')
  output = await api.functional.shoppingMallAiBackend.admin.attachments.search(connection, {
    body: { file_name: 'repor' }
  });
  typia.assert(output);
  TestValidator.predicate('partial match')(output.data.some(x => x.file_name.includes('repor')));

  // c) MIME type (image/png)
  output = await api.functional.shoppingMallAiBackend.admin.attachments.search(connection, {
    body: { mime_type: 'image/png' }
  });
  typia.assert(output);
  TestValidator.predicate('png filtered')(output.data.every(x => x.mime_type === 'image/png'));

  // d) Owner type filter
  output = await api.functional.shoppingMallAiBackend.admin.attachments.search(connection, {
    body: { owner_type: 'product' }
  });
  typia.assert(output);
  TestValidator.predicate('product owner_type')(output.data.every(x => x.owner_type === 'product'));
  TestValidator.predicate('at least one record (spec.pdf)')(output.data.length >= 1);

  // e) Pagination: pageSize 2, page 1
  output = await api.functional.shoppingMallAiBackend.admin.attachments.search(connection, {
    body: { page: 1, pageSize: 2 }
  });
  typia.assert(output);
  TestValidator.equals('pagination.limit')(output.pagination.limit)(2);
  TestValidator.equals('page 1')(output.pagination.current)(1);

  // f) Pagination: page 2 (should see correct splitting)
  output = await api.functional.shoppingMallAiBackend.admin.attachments.search(connection, {
    body: { page: 2, pageSize: 2 }
  });
  typia.assert(output);
  TestValidator.equals('pagination.limit')(output.pagination.limit)(2);
  TestValidator.equals('page 2')(output.pagination.current)(2);

  // g) Attachment with expired expire_at does not show up by default
  output = await api.functional.shoppingMallAiBackend.admin.attachments.search(connection, {
    body: { file_name: 'draft.docx' }
  });
  typia.assert(output);
  TestValidator.predicate('expired file hidden')(output.data.length === 0 || output.data.every(x => typeof x.expire_at !== 'string' || Date.parse(x.expire_at) > Date.now()));

  // h) No filters (returns all permitted attachments, all non-expired and non-deleted)
  output = await api.functional.shoppingMallAiBackend.admin.attachments.search(connection, { body: {} });
  typia.assert(output);
  TestValidator.predicate('returns at least one attachment')(output.data.length > 0);

  // i) Invalid owner_id (malformed UUID)
  await TestValidator.error('malformed UUID in owner_id')(async () => {
    await api.functional.shoppingMallAiBackend.admin.attachments.search(connection, {
      body: { owner_id: 'INVALID-UUID' as any }
    });
  });

  // j) Negative pageSize triggers error
  await TestValidator.error('negative pageSize error')(async () => {
    await api.functional.shoppingMallAiBackend.admin.attachments.search(connection, {
      body: { pageSize: -5 as any }
    });
  });

  // k) Filter with no match (e.g., random file name)
  const notFoundName = 'zzzz-nonexistent-file';
  output = await api.functional.shoppingMallAiBackend.admin.attachments.search(connection, {
    body: { file_name: notFoundName }
  });
  typia.assert(output);
  TestValidator.equals('empty result')(output.data.length)(0);

  // l) All found summaries contain required ISummary fields
  const sampleSummary = output.data[0] ?? attachmentEntities[0];
  for (const key of ['id', 'owner_id', 'owner_type', 'file_name', 'file_size', 'mime_type', 'storage_uri', 'uploaded_at']) {
    TestValidator.predicate('ISummary property: ' + key)(typeof (sampleSummary as any)[key] !== 'undefined');
  }
  // Authorizations, audit log checks: Only admin can access, and no error occurs (direct audit log checking is not feasible without API).
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
