/**
 * Validate proper retrieval of attachment metadata and detail as admin, including permission and error boundaries.
 *
 * This test simulates the admin workflow and edge/error cases:
 * 1. Register an admin account and store its credentials.
 * 2. Create a new attachment (as admin) and fetch full detail using its id, verifying all business and metadata fields are populated.
 * 3. Attempt to fetch metadata for a non-existent/invalid UUID and assert error handling.
 * 4. Simulate a soft deleted file (cannot directly create deleted_at in API, but can validate presence if surface).
 *    a) Verify admin can still fetch it successfully and all fields (especially deleted_at) are present or null.
 *    b) Simulate a regular user (lacking admin privileges) accessing the same attachment and assert access denied/error.
 * 5. Assert required business/metadata fields on returned objects (storage URI, mime type, hash, etc.).
 */
export async function test_api_attachment_detail_success_and_permissions(connection: api.IConnection) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "adminPass!1234",
    },
  });
  typia.assert(adminReg);

  // 2. Create an attachment as admin
  const createInput: IShoppingMallAiBackendAttachment.ICreate = {
    owner_id: typia.random<string & tags.Format<"uuid">>(),
    owner_type: "admin",
    file_name: "invoice.pdf",
    file_size: 1024,
    mime_type: "application/pdf",
    storage_uri: `s3://bucket/${typia.random<string & tags.Format<"uuid">>()}/invoice.pdf`,
    hash_sha256: "9d3622ecf3fceff465c2c5e01563a7e387dac3590eee861e2be16cba8e64ed92",
    uploaded_at: new Date().toISOString(),
    expire_at: null,
    description: "Test admin file metadata",
  };
  const attachment = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, { body: createInput });
  typia.assert(attachment);

  // 2b. Fetch the detail as admin and check all expected fields
  const detail = await api.functional.shoppingMallAiBackend.admin.attachments.at(connection, { attachmentId: attachment.id });
  typia.assert(detail);
  TestValidator.equals("id matches")(detail.id)(attachment.id);
  TestValidator.equals("storage_uri matches")(detail.storage_uri)(attachment.storage_uri);
  TestValidator.equals("mime_type matches")(detail.mime_type)(attachment.mime_type);
  TestValidator.equals("hash matches")(detail.hash_sha256)(attachment.hash_sha256);
  TestValidator.equals("owner_id matches")(detail.owner_id)(attachment.owner_id);
  TestValidator.equals("owner_type matches")(detail.owner_type)(attachment.owner_type);

  // Confirm mandatory business metadata fields are present
  TestValidator.predicate("file_name exists and is non-empty")(typeof detail.file_name === "string" && detail.file_name.length > 0);
  TestValidator.predicate("file_size positive")(typeof detail.file_size === "number" && detail.file_size > 0);
  TestValidator.predicate("uploaded_at is ISO string")(typeof detail.uploaded_at === "string");

  // 3. Attempt access for random invalid attachmentId
  await TestValidator.error("lookup for non-existent attachment fails")(
    () => api.functional.shoppingMallAiBackend.admin.attachments.at(connection, {
      attachmentId: typia.random<string & tags.Format<"uuid">>()
    })
  );

  // 4. Simulate soft deleted: the only way is to validate deleted_at when present
  // Create file as normal
  const retiredInput: IShoppingMallAiBackendAttachment.ICreate = {
    ...createInput,
    file_name: "retired.docx",
    mime_type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    storage_uri: `s3://bucket/${typia.random<string & tags.Format<"uuid">>()}/retired.docx`,
    hash_sha256: "5bbfae961eafaaac94e2e7ca3a1889e1fe31efb29060aa1a0b0f5d8c7aeafc20",
    uploaded_at: new Date().toISOString(),
    expire_at: new Date(Date.now() + 1000 * 60 * 60 * 24 * 7).toISOString(), // expires in 1 week
    description: "File for deletion/retire test",
  };
  const retiredAttach = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, { body: retiredInput });
  typia.assert(retiredAttach);

  // Since API has no update/delete, we just check that deleted_at field is surfaced (null or string)
  const retired = await api.functional.shoppingMallAiBackend.admin.attachments.at(connection, { attachmentId: retiredAttach.id });
  typia.assert(retired);
  TestValidator.predicate("deleted_at is null or string")(retired.deleted_at === null || typeof retired.deleted_at === "string");

  // 4b. Simulate regular user by clearing admin credentials
  const noAuthConn = { ...connection, headers: { ...connection.headers, Authorization: "" } };
  await TestValidator.error("non-admin cannot fetch attachment detail")(
    () => api.functional.shoppingMallAiBackend.admin.attachments.at(noAuthConn, { attachmentId: retiredAttach.id })
  );
}

