 *
 * This test covers:
 * 1. Admin sign-up and authentication
 * 2. Creating a new attachment record with all required and optional metadata fields
 * 3. Echoed-back metadata and field validation
 * 4. Error cases: missing required field, invalid owner_type, duplicate hash, and unauthorized request
 *
 * Steps:
 * 1. Register a new admin (prerequisite authentication)
 * 2. As this admin, create an attachment using all metadata fields (owner_id, owner_type, file_name, file_size, mime_type, storage_uri, hash_sha256, uploaded_at, expire_at, description)
 * 3. Validate creation and business logic—for example, correct echoing of data and valid ISO timestamps
 * 4. Test failure cases: missing file_name, invalid owner_type, duplicate hash_sha256, and missing authentication
 */
export async function test_api_attachment_creation_with_metadata_validation(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword123!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAuth);

  // System sets Authorization header after signUp
  const adminId = adminAuth.adminId;
  // Prepare test metadata for business file upload
  const fileMetadata: IShoppingMallAiBackendAttachment.ICreate = {
    owner_id: adminId,
    owner_type: "admin",
    file_name: "attachment_test_document.pdf",
    file_size: 4096,
    mime_type: "application/pdf",
    storage_uri: `s3://test-bucket/${adminId}/attachment_test_document.pdf`,
    hash_sha256: typia.random<string>(),
    uploaded_at: new Date().toISOString(),
    expire_at: new Date(Date.now() + 10 * 24 * 60 * 60 * 1000).toISOString(), // 10 days from now
    description: "Test admin attachment with PDF metadata.",
  };

  // 2. Create attachment and assert business logic
  const attachment = await api.functional.shoppingMallAiBackend.admin.attachments.create(connection, {
    body: fileMetadata,
  });
  typia.assert(attachment);
  TestValidator.equals("owner_id echoed")(attachment.owner_id)(fileMetadata.owner_id);
  TestValidator.equals("owner_type echoed")(attachment.owner_type)(fileMetadata.owner_type);
  TestValidator.equals("file_name echoed")(attachment.file_name)(fileMetadata.file_name);
  TestValidator.equals("mime_type echoed")(attachment.mime_type)(fileMetadata.mime_type);
  TestValidator.equals("hash_sha256 echoed")(attachment.hash_sha256)(fileMetadata.hash_sha256);
  TestValidator.equals("expire_at echoed")(attachment.expire_at)(fileMetadata.expire_at);
  TestValidator.equals("description echoed")(attachment.description)(fileMetadata.description);
  TestValidator.predicate("uploaded_at ISO format")(typeof attachment.uploaded_at === "string" && !isNaN(Date.parse(attachment.uploaded_at)));
