/**
 * Validate admin access for retrieving customer history event details via GET /shoppingMallAiBackend/admin/customers/{customerId}/histories/{historyId}.
 *
 * This test ensures:
 *  - Admins can fetch full event details (event type, values, timestamps, actor) for a real, existing event.
 *  - Non-admin (regular customer) requests are denied with proper error response.
 *  - Non-existent history records result in correct error codes (not found/forbidden).
 *
 * Scenario covers:
 * 1. Register admin, obtain admin token.
 * 2. Register customer, obtain customerId.
 * 3. As admin, list customer's histories, pick a valid event; save a valid historyId.
 * 4. As admin, fetch event detail for chosen (customerId, historyId) and validate all major fields.
 * 5. As customer (non-admin), attempt the same request—expect access denied error.
 * 6. As admin, attempt to fetch with a non-existent historyId—expect not found error.
 *
 * Steps 2-4 ensure the normal positive path. Steps 5-6 validate error handling and RBAC access control.
 */
export async function test_api_admin_access_customer_history_event(connection: api.IConnection) {
  // 1. Register admin; obtain admin JWT and set in connection.headers
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "TestAdminPw123!"
    }
  });
  typia.assert(adminSignUp);
  // 2. Register customer, extract customerId
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: "TestCustomerPw123!",
      name: "Test Customer",
      nickname: "customer_" + Math.random().toString(36).substring(2, 8),
      phone: "010-" + Math.floor(1000 + Math.random()*9000) + "-" + Math.floor(1000 + Math.random()*9000)
    }
  });
  typia.assert(customerSignUp);
  const customerId = customerSignUp.customer.id;
  // 3. As admin: list customer histories
  if (!connection.headers) connection.headers = {};
  connection.headers.Authorization = adminSignUp.setHeaders.Authorization;
  const histories = await api.functional.shoppingMallAiBackend.admin.customers.histories.search(connection, {
