import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSeller";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * E2E Test: Seller profile self-service and access control for /shoppingMallAiBackend/seller/sellers/{sellerId}.
 *
 * This test verifies that a seller, once registered and authenticated, can view their own complete profile using the GET endpoint, with all fields populated and matching the registration payload. It checks strict access control so that only the seller can view their own details: a different seller's JWT must NOT allow access (authorization error), and a random/non-existent sellerId must trigger a not-found error. If the system supports unauthenticated access, it also checks that protected details are unavailable or masked. The test ensures robust business logic, privacy, and security enforcement.
 *
 * Steps:
 * 1. Register Seller A -> retain sellerId, registration info, and auth headers.
 * 2. Fetch Seller A's profile (authenticated as self) using the endpoint. Assert complete and correct details.
 * 3. Register Seller B separately.
 * 4. Fetch Seller A's profile as Seller B. Assert authorization error.
 * 5. Attempt to fetch a profile with random (nonexistent) sellerId. Assert not-found error.
 */
export async function test_api_seller_profile_self_service_access(connection: api.IConnection) {
  // 1. Register Seller A, capture details & JWT.
  const signUpPayloadA = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPwd1!",
    companyName: "A Test Company",
    businessNumber: typia.random<string>(),
    representativeName: "Alice Alpha",
    address: "11-1, Some Street, Test City",
    phone: "010-1111-1111"
  } satisfies ISellerAuth.SignUp;

  const sellerAAuth = await api.functional.auth.seller.register.signUp(connection, { body: signUpPayloadA });
  typia.assert(sellerAAuth);
  const sellerAId = sellerAAuth.sellerId;
  const sellerAJwtHeader = sellerAAuth.setHeaders.Authorization;

  // 2. With Seller A's JWT, fetch Seller A's profile and validate all data matches registration info
  const sellerAConn = { ...connection, headers: { ...connection.headers, Authorization: sellerAJwtHeader } };
  const sellerAProfile = await api.functional.shoppingMallAiBackend.seller.sellers.at(sellerAConn, { sellerId: sellerAId });
  typia.assert(sellerAProfile);

  // Validate that all business/identity fields match the registration payload
  TestValidator.equals("seller.email")(sellerAProfile.email)(signUpPayloadA.email);
  TestValidator.equals("company name")(sellerAProfile.company_name)(signUpPayloadA.companyName);
  TestValidator.equals("business number")(sellerAProfile.business_number)(signUpPayloadA.businessNumber);
  TestValidator.equals("representative name")(sellerAProfile.representative_name)(signUpPayloadA.representativeName);
  TestValidator.equals("address")(sellerAProfile.address)(signUpPayloadA.address);
  TestValidator.equals("phone")(sellerAProfile.phone)(signUpPayloadA.phone);
  // We can't check status/email_verified/joined_at/created_at/updated_at for exact value, but can check correct types/fields
  TestValidator.predicate("status present and string")(typeof sellerAProfile.status === "string");
  TestValidator.predicate("email verified is boolean")(typeof sellerAProfile.email_verified === "boolean");
  TestValidator.predicate("joined_at present")(typeof sellerAProfile.joined_at === "string");
  TestValidator.predicate("created_at present")(typeof sellerAProfile.created_at === "string");
  TestValidator.predicate("updated_at present")(typeof sellerAProfile.updated_at === "string");
  // deleted_at field optional/null
  TestValidator.predicate("deleted_at nullable")(sellerAProfile.deleted_at === null || typeof sellerAProfile.deleted_at === "string" || typeof sellerAProfile.deleted_at === "undefined");

  // 3. Register Seller B
  const signUpPayloadB = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPwd2!",
    companyName: "B Company Corp",
    businessNumber: typia.random<string>(),
    representativeName: "Bob Beta",
    address: "99 Market Ave, Beta City",
    phone: "010-2222-2222"
  } satisfies ISellerAuth.SignUp;
  const sellerBAuth = await api.functional.auth.seller.register.signUp(connection, { body: signUpPayloadB });
  typia.assert(sellerBAuth);
  const sellerBJwtHeader = sellerBAuth.setHeaders.Authorization;

  // 4. As Seller B, attempt to fetch Seller A's profile -- ensure error (authorization expected)
  const sellerBConn = { ...connection, headers: { ...connection.headers, Authorization: sellerBJwtHeader } };
  await TestValidator.error("Seller B cannot access Seller A's profile")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.at(sellerBConn, { sellerId: sellerAId });
    }
  );

  // 5. Access with random/non-existent sellerId (should receive a not-found error)
  const randomSellerId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not-found on missing sellerId")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.sellers.at(sellerAConn, { sellerId: randomSellerId });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
