/**
 * Validate idempotency and proper error handling when deleting an already (soft-)deleted product-channel mapping.
 *
 * In this workflow, a seller logs in, creates a product, and a new business channel (as admin). Then, the product is mapped to this channel. After the mapping is created, it is deleted (soft-delete expected by business logic), and an immediate second deletion attempt is made on the same mapping. The endpoint must return idempotent/no-op or a not-found error, confirming robust, idempotent resource deletion. Only runtime HTTP errors are validated—TypeScript compile-time/type safety violation scenarios are skipped by rule.
 *
 * Steps:
 * 1. Register and login a new seller
 * 2. Create a new product with the seller's identity
 * 3. (Admin) Create a new business channel
 * 4. Map the product to the channel (create product-channel map)
 * 5. Delete (soft-delete) the mapping for the first time (expected: success)
 * 6. Attempt to delete the mapping a second time (expected: no-op/idempotent or HTTP error)
 * 7. Validate the API response for the second attempt: passes if no error (idempotent success), or appropriate HTTP not-found / business error is thrown and caught.
 * 8. All API responses are type/assert-validated. No type system error scenarios are implemented. No resource cleanup is required after test.
 */
export async function test_api_product_channel_map_delete_already_deleted(connection: api.IConnection) {
  // 1. Register a seller account
  const email = typia.random<string & tags.Format<"email">>();
  const password = "P@ssw0rd!";
  const registerRes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email,
      password,
      companyName: RandomGenerator.name(),
      businessNumber: ArrayUtil.repeat(10)(() => RandomGenerator.alphaNumeric(1)).join(""),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
