  TestValidator.equals("pagination limit")(page1.pagination.limit)(pageSize);
  TestValidator.predicate("pagination result subset")(page1.data.every(x => returnedKeywords.includes(x.search_keyword)));

  // 5b. Filtering test: filter search_keyword contains 'findme'
  const filterKw = "findme";
  const filterRes = await api.functional.shoppingMallAiBackend.seller.products.productSearchKeywords.searchProductSearchKeywords(connection, {
