import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSearchKeyword } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSearchKeyword";
import type { IPageIShoppingMallAiBackendProductSearchKeyword } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductSearchKeyword";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated and filtered search of product keywords as admin
 *
 * This E2E test performs the following steps to ensure the proper functioning of the product keyword search with pagination and filtering by an admin:
 *
 * 1. Create a new product (with valid fields, including a seller_id).
 * 2. Attach multiple distinct search keywords to the product.
 * 3. Exercise the keyword search API to:
 *    - Retrieve paginated lists of keywords (with limit, page).
 *    - Filter results by keyword substring (partial match).
 *    - Confirm that all assigned keywords can be retrieved.
 *    - Validate correct pagination metadata (limit, current, records, pages).
 *
 * **Business Rationale:**
 * - Validates admin capability for keyword management and search
 * - Validates business rules for assigning and querying keywords
 */
export async function test_api_product_search_keyword_search_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a product to associate keywords with
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    },
  });
  typia.assert(product);

  // 2. Attach multiple keywords to the product
  const keywords = [
    "ultrabook",
    "gaming laptop",
    "touchscreen laptop",
    "notebook",
    "laptop",
  ];
  const createdKeywords: string[] = [];
  for (const keyword of keywords) {
    const out = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.createProductSearchKeyword(
      connection,
      {
        productId: product.id,
        body: {
          product_id: product.id,
          search_keyword: keyword,
        },
      },
    );
    typia.assert(out);
    createdKeywords.push(out.search_keyword);
  }

  // 3. Keyword search with pagination (limit 2, page 1)
  const page1 = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.searchProductSearchKeywords(
    connection,
    {
      productId: product.id,
      body: {
        product_id: product.id,
        page: 1,
        limit: 2,
      },
    },
  );
  typia.assert(page1);
  TestValidator.equals("Page 1 size 2 limit")(page1.pagination.limit)(2);
  TestValidator.equals("Page 1 current")(page1.pagination.current)(1);
  TestValidator.predicate("Should return <=2 keywords")(page1.data.length <= 2);
  TestValidator.predicate("Should return at least 1 keyword")(page1.data.length > 0);

  // 4. Filter by substring for each keyword (partial match)
  for (const k of keywords) {
    const partial = k.slice(0, 5);
    const filtered = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.searchProductSearchKeywords(
      connection,
      {
        productId: product.id,
        body: {
          product_id: product.id,
          search_keyword: partial,
        },
      },
    );
    typia.assert(filtered);
    TestValidator.predicate(
      `Partial keyword search should match at least one: ${partial}`,
    )(filtered.data.some(d => d.search_keyword.includes(partial)));
  }

  // 5. Confirm all assigned keywords are discoverable in a full, unfiltered paged result
  const all = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.searchProductSearchKeywords(
    connection,
    {
      productId: product.id,
      body: {
        product_id: product.id,
        limit: 20,
        page: 1,
      },
    },
  );
  typia.assert(all);
  for (const k of keywords)
    TestValidator.predicate(
      `Unfiltered result contains ${k}`,
    )(all.data.some(d => d.search_keyword === k));

  // 6. Check empty result on high page number
  const emptyPage = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.searchProductSearchKeywords(
    connection,
    {
      productId: product.id,
      body: {
        product_id: product.id,
        page: 99,
        limit: 5,
      },
    },
  );
  typia.assert(emptyPage);
  TestValidator.equals("Empty page should have no data")(emptyPage.data.length)(0);
}

