  TestValidator.equals("receiver_phone matches")(fetched.receiver_phone)(updateBody.receiver_phone);
  TestValidator.equals("postal_code matches")(fetched.postal_code)(updateBody.postal_code);
  TestValidator.equals("address_line1 matches")(fetched.address_line1)(updateBody.address_line1);
  TestValidator.equals("address_line2 matches")(fetched.address_line2)(null);
  TestValidator.equals("city matches")(fetched.city)(updateBody.city);
  TestValidator.equals("state matches")(fetched.state)(updateBody.state);
  TestValidator.equals("country matches")(fetched.country)(updateBody.country);

