import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates admin product option creation input validation error handling.
 *
 * This test ensures that when an admin attempts to create a product option for an existing product, but provides either missing required fields or invalid data according to the DTO schema, the API rejects the request and returns a validation error instead of creating the option.
 *
 * Process:
 * 1. Register and login as a new admin, so subsequent calls are made with admin privileges/session.
 * 2. As admin, create a valid product that can own options (to get a valid productId) — all required fields valid.
 * 3. Attempt to create a product option using the admin API with the following types of invalid input for IShoppingMallAiBackendProductOption.ICreate:
 *    a. Missing required field(s) such as 'sku' or 'option_name'.
 *    b. Invalid format for product_id (not a UUID), or empty string for required fields (e.g., '')
 *    c. Invalid types or out-of-spec values (e.g., negative price for extra_price)
 *
 * Each of these attempts should be rejected by the API, throwing an error.
 */
export async function test_api_product_option_creation_invalid_input_admin(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongTestPassword123!";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });

  // 2. Login as that admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignIn
  });

  // 3. Create a valid product, for association with options
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: "PROD-" + RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphaNumeric(10),
      status: "draft"
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 4. Test input: missing required field 'sku'
  TestValidator.error("missing sku should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.products.productOptions.create(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        // intentionally omitted: sku
        option_name: "Size",
        status: "active"
      } as any
    })
  );

  // 5. Test input: missing required field 'option_name'
  TestValidator.error("missing option_name should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.products.productOptions.create(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        sku: "MISSING-NAME-SKU",
        // intentionally omitted: option_name
        status: "active"
      } as any
    })
  );

  // 6. Test input: invalid product_id format
  TestValidator.error("invalid product_id format should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.products.productOptions.create(connection, {
      productId: "not-a-uuid-value" as any,
      body: {
        product_id: "not-a-uuid-value" as any,
        sku: "INV-FMT-SKU",
        option_name: "Color",
        status: "active"
      }
    })
  );

  // 7. Test input: negative price for extra_price
  TestValidator.error("negative extra_price should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.products.productOptions.create(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        sku: "NEG-PRICE-SKU",
        option_name: "Upgrade",
        extra_price: -1.0,
        status: "active"
      } as any
    })
  );

  // 8. Test input: empty-string for required fields
  TestValidator.error("empty sku should fail")(() =>
    api.functional.shoppingMallAiBackend.admin.products.productOptions.create(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        sku: "",
        option_name: "Color",
        status: "active"
      }
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import type { IShoppingMallAiBackendProductOptionStock } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOptionStock";
import type { IPageIShoppingMallAiBackendProductOptionStock } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductOptionStock";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test that a seller can search, filter, and paginate the list of stock records for their product option.
 *
 * This test goes through a complete business flow:
 * 1. Register a seller with unique credentials.
 * 2. Login as that seller to obtain an authenticated session.
 * 3. Create a product as the seller.
 * 4. Add an option to that product.
 * 5. Add multiple stock records (with different fields for diversity).
 * 6. Perform a PATCH search to filter, sort, and paginate those stocks.
 * 7. Verify the returned data matches input and is properly structured.
 */
export async function test_api_product_option_stock_search_success_seller(connection: api.IConnection) {
  // 1. Seller registration
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const password = "Password!123";
  const signUpRes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password,
      companyName: RandomGenerator.name(),
      businessNumber: ArrayUtil.repeat(10)(() => String(Math.floor(Math.random()*10))).join(""),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(15),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(signUpRes);

  // 2. Seller login (should set Authorization header in connection automatically)
  const loginRes = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password,
    } satisfies ISellerAuth.SignIn
  });
  typia.assert(loginRes);

  // 3. Create a product
  const productRes = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: signUpRes.sellerId,
      code: `P-${Date.now()}`,
      name: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: "active"
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(productRes);

  // 4. Create a product option
  const optionRes = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: productRes.id,
    body: {
      product_id: productRes.id,
      sku: `SKU-${Date.now()}`,
      option_name: "Color",
      option_values: "Red,Blue,Green",
      extra_price: 2000,
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProductOption.ICreate
  });
  typia.assert(optionRes);

  // 5. Create multiple product option stock records (different warehouse, status, etc.)
  const stockInputs = [
    {
      product_option_id: optionRes.id,
      stock_count: 50,
      safety_stock: 10,
      inbound_count: 0,
      warehouse_location: "A1-Red",
      status: "active"
    },
    {
      product_option_id: optionRes.id,
      stock_count: 20,
      safety_stock: 5,
      inbound_count: 10,
      warehouse_location: "B2-Blue",
      status: "reserved"
    },
    {
      product_option_id: optionRes.id,
      stock_count: 100,
      safety_stock: 20,
      inbound_count: 15,
      warehouse_location: "C3-Green",
      status: "locked"
    }
  ];
  const stocks = [];
  for (const input of stockInputs) {
    const stock = await api.functional.shoppingMallAiBackend.seller.productOptions.productOptionStocks.create(connection, {
      productOptionId: optionRes.id,
      body: input
    });
    typia.assert(stock);
    stocks.push(stock);
  }

  // 6. PATCH search: filter by status, sort, and paginate
  const searchRes = await api.functional.shoppingMallAiBackend.seller.productOptions.productOptionStocks.search(connection, {
    productOptionId: optionRes.id,
    body: {
      filter: {
        productOptionId: optionRes.id,
        status: "active"
      },
      sort: [{ field: "created_at", direction: "desc" }],
      page: 1,
      pageSize: 2
    }
  });
  typia.assert(searchRes);
  // 7. Validate structure: confirm pagination structure and at least first record contains the correct filter result
  const stockActive = stocks.find(s => s.status === "active");
  TestValidator.equals("pagination.page")(searchRes.pagination.current)(1);
  TestValidator.equals("pagination.limit")(searchRes.pagination.limit)(2);
  TestValidator.predicate("at least one active record found")(
    searchRes.data.some(s => s.status === "active" && s.id === stockActive?.id)
  );
}

