import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test fully deleting a seller profile (hard delete) from the system.
 *
 * Business context: Only the seller (or admin, but we simulate seller self) can delete their profile. This removes their presence and access entirely.
 *
 * Steps:
 * 1. Register a new seller account with unique email and valid KYC details.
 * 2. Log in as the newly created seller to ensure authentication works and obtain token (the SDK auto-injects Authorization).
 * 3. Use the authenticated connection to call DELETE /shoppingMallAiBackend/seller/sellers/{sellerId} for their own sellerId.
 * 4. Confirm the response (void) is successful (no error thrown = 200/204), meaning the account is deleted.
 * 5. Attempt to log in again with the same credentials - this must now fail (as the seller has been hard deleted).
 *
 * Note: Actual audit log/cascade validation would require side-channel DB/API access—here we check what can be inferred via the available APIs, e.g., login inaccessibility post-delete, and the fact that the operation itself completes without residual access.
 */
export async function test_api_seller_profile_delete_success(connection: api.IConnection) {
  // 1. Register seller
  const email = typia.random<string & tags.Format<"email">>();
  const password = "ValidTestPassword1!";
  const signUpBody: ISellerAuth.SignUp = {
    email,
    password,
    companyName: RandomGenerator.alphabets(10),
    businessNumber: RandomGenerator.alphaNumeric(10),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  };
  const signUpRes = await api.functional.auth.seller.register.signUp(connection, { body: signUpBody });
  typia.assert(signUpRes);
  // 2. Log in (to simulate what a real seller does)
  const loginRes = await api.functional.auth.seller.login.signIn(connection, { body: { email, password } satisfies ISellerAuth.SignIn });
  typia.assert(loginRes);
  // 3. Hard delete self
  await api.functional.shoppingMallAiBackend.seller.sellers.erase(connection, { sellerId: signUpRes.sellerId });
  // 4. Try to log in again (should fail/error)
  await TestValidator.error("Seller cannot log in after deletion")(() => api.functional.auth.seller.login.signIn(connection, { body: { email, password } satisfies ISellerAuth.SignIn }));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test that deleting a seller profile without ownership or valid authentication returns access denied errors and preserves the seller profile.
 *
 * This test ensures the following:
 *  - A seller's profile (created seller) cannot be deleted by another authenticated seller (attacker seller)
 *  - The seller's profile cannot be deleted by an unauthenticated user (no auth header)
 *  - The target seller's profile remains intact after failed deletion attempts (duplicate registration fails due to unique email)
 *
 * Business context: Seller hard-delete is only permitted by the profile owner or platform admin. This simulates malicious or unauthorized deletion attempts, and checks the correctness of backend security policy and business logic enforcement. Expected result is access denied errors and data still present.
 *
 * Step-by-step:
 * 1. Register a target seller account to serve as the deletion candidate
 * 2. Register a second seller account (attacker)
 * 3. Using the authenticated session for the attacker seller, attempt to delete the target seller profile (must fail with error)
 * 4. Attempt deletion without JWT authentication by stripping headers (must fail with error)
 * 5. Attempt to re-register with the target seller's email to confirm it was not deleted (must fail due to uniqueness constraint)
 */
export async function test_api_seller_profile_delete_unauthorized(
  connection: api.IConnection,
) {
  // 1. Register the first (target) seller account
  const targetSellerInput: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "targetP4ssword!!",
    companyName: "Target Co., Ltd.",
    businessNumber: "1234567890",
    representativeName: "Target CEO",
    address: "123 Target Street, City",
    phone: "0212345678",
  };
  const targetSignUp: ISellerAuth.AuthResponseWithHeaders =
    await api.functional.auth.seller.register.signUp(connection, {
      body: targetSellerInput,
    });
  typia.assert(targetSignUp);

  // 2. Register the attacker seller account
  const attackerSellerInput: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "attackerP4ss!!",
    companyName: "Attacker Co., Ltd.",
    businessNumber: "1098765432",
    representativeName: "Attacker CEO",
    address: "555 Attacker Ave, City",
    phone: "0298765432",
  };
