 * 1. Register a new seller.
 * 2. Login as the seller, ensuring authentication.
 * 3. Create a business verification record for this seller with allowed random data.
 * 4. Search for business verifications of this seller, filtering by seller_id, verification_status, and pagination.
 * 5. Assert at least one record matches with the correct seller_id and verification_status, and that pagination is respected.
 */
export async function test_api_seller_business_verifications_search_success(connection: api.IConnection) {
  // 1. Register a new seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Test1234!";
  const companyName = RandomGenerator.name();
  const businessNumber = ArrayUtil.repeat(10)(() => Math.floor(Math.random()*10)).join("");
  const representativeName = RandomGenerator.name();
  const address = RandomGenerator.paragraph()(1);
  const phone = RandomGenerator.mobile();

  const signUpResponse = await api.functional.auth.seller.register.signUp(connection, {
