import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendChannel";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductChannelMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductChannelMap";
import type { IPageIShoppingMallAiBackendProductChannelMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductChannelMap";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test seller's ability to search and filter product-channel mappings for their own products.
 *
 * This test covers:
 * 1. Register a seller (with meaningful business fields).
 * 2. Create a product for the seller under admin privileges.
 * 3. Create multiple channels (for realism and filter tests).
 * 4. Map the product to several channels, using varying statuses (e.g., 'active', 'inactive').
 * 5. Seller searches (PATCH) product-channel map endpoint:
 *    - Without filters: expects all mappings for their product returned.
 *    - With specific filters (channel_id, status): verifies filtering.
 *    - With pagination (page/limit): verifies pagination works as expected.
 * 6. Negative test: Register another seller, repeat a search for the first seller's product—expect 403 Forbidden or no results (depending on RBAC).
 *
 * Coverage:
 * - Main happy path + error/forbidden path for access control.
 * - Data creation/relationships are fully set up.
 * - All API interactions use correct types and are validated with typia.assert(), TestValidator, etc.
 */
export async function test_api_product_channel_map_search_by_seller(
  connection: api.IConnection,
) {
  // 1. Register seller
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "passW0rd!",
      companyName: RandomGenerator.name(),
      businessNumber: Math.floor(Math.random() * 1e10)
        .toString()
        .padStart(10, "0"),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResp);
  // Set connection token for this seller
  connection.headers = {
    ...(connection.headers || {}),
    Authorization: signUpResp.setHeaders.Authorization,
  };

  // 2. Create product for seller (as admin)
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(
    connection,
    {
      body: {
        seller_id: signUpResp.sellerId,
        code: `SKU-${RandomGenerator.alphaNumeric(8)}`,
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph()(),
        main_image_uri: null,
        status: "published",
      } satisfies IShoppingMallAiBackendProduct.ICreate,
    }
  );
  typia.assert(product);

  // 3. Create multiple channels (as admin)
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const channelInputs = ArrayUtil.repeat(3)(() =>
    ({
      code: RandomGenerator.alphaNumeric(6),
      name: RandomGenerator.name(),
      created_by_admin_id: adminId,
      description: RandomGenerator.paragraph()(),
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate)
  );
  const channels = [];
  for (const input of channelInputs) {
    const chan = await api.functional.shoppingMallAiBackend.admin.channels.create(
      connection,
      { body: input }
    );
    typia.assert(chan);
    channels.push(chan);
  }

  // 4. Map product to channels, with various statuses
  const mapStatuses = ["active", "inactive", "hidden"];
  const mappings = [];
  for (let i = 0; i < channels.length; ++i) {
    const map = await api.functional.shoppingMallAiBackend.admin.products.productChannelMap.createProductChannelMap(
      connection,
      {
        productId: product.id,
        body: {
          product_id: product.id,
          channel_id: channels[i].id,
          status: mapStatuses[i % mapStatuses.length],
        } satisfies IShoppingMallAiBackendProductChannelMap.ICreate,
      }
    );
    typia.assert(map);
    mappings.push(map);
  }

  // 5a. Seller search: no filter—all mappings should return
  const resAll =
    await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.search(
      connection,
      {
        productId: product.id,
        body: {},
      }
    );
  typia.assert(resAll);
  // Check we get all created mappings
  TestValidator.equals("mapping result count/full fetch")(resAll.data.length)(mappings.length);
  for (const m of mappings) {
    TestValidator.predicate("result mapping contains all created mappings")(
      resAll.data.some((x) => x.id === m.id)
    );
  }

  // 5b. Seller search with channel_id filter
  const filterIdx = 1;
  const resByChannel =
    await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.search(
      connection,
      {
        productId: product.id,
        body: {
          channel_id: channels[filterIdx].id,
        },
      }
    );
  typia.assert(resByChannel);
  TestValidator.equals("filtered by channel_id")(
    resByChannel.data.length
  )(1);
  TestValidator.equals("filtered element matches channel_id")(
    resByChannel.data[0].channel_id
  )(channels[filterIdx].id);

  // 5c. Seller search with status filter
  const statusIdx = 2;
  const resByStatus =
    await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.search(
      connection,
      {
        productId: product.id,
        body: { status: mapStatuses[statusIdx] },
      }
    );
  typia.assert(resByStatus);
  TestValidator.equals("filtered by status length")(
    resByStatus.data.length
  )(1);
  TestValidator.equals("filtered by status value")(
    resByStatus.data[0].status
  )(mapStatuses[statusIdx]);

  // 5d. Seller search paginated (limit=2)
  const resPaginated =
    await api.functional.shoppingMallAiBackend.seller.products.productChannelMap.search(
      connection,
      {
        productId: product.id,
        body: { page: 1, limit: 2 },
      }
    );
  typia.assert(resPaginated);
  TestValidator.equals("pagination limit")(resPaginated.data.length)(2);
  TestValidator.equals("pagination current page")(
    resPaginated.pagination.current
  )(1);
  TestValidator.equals("pagination limit val")(
    resPaginated.pagination.limit
  )(2);

  // 6. Unauthorized seller cannot view mappings for another seller's product
  // Register a different seller and set connection to them
  const otherEmail: string = typia.random<string & tags.Format<"email">>();
  const otherSeller = await api.functional.auth.seller.register.signUp(
    connection,
    {
      body: {
        email: otherEmail,
        password: "OtherPass1!",
        companyName: RandomGenerator.name(),
        businessNumber: Math.floor(Math.random() * 1e10)
          .toString()
          .padStart(10, "0"),
        representativeName: RandomGenerator.name(),
        address: RandomGenerator.paragraph()(),
        phone: RandomGenerator.mobile(),
      } satisfies ISellerAuth.SignUp,
    }
  );
  typia.assert(otherSeller);
  connection.headers = {
    ...(connection.headers || {}),
    Authorization: otherSeller.setHeaders.Authorization,
  };

  await TestValidator.error("forbidden for another seller")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productChannelMap.search(
      connection,
      {
        productId: product.id,
        body: {},
      }
    )
  );
}

