/**
 * Validate searching and filtering of product-channel mappings by admin.
 *
 * This test ensures that an admin can search for channel mappings of any product with all supported filters (status, channel_id, pagination, etc.), and results correctly reflect all mappings regardless of seller, as per RBAC.
 * It also confirms that audit controls (API-inherent) are applied, and relevant mappings are returned regardless of product ownership.
 *
 * Step-by-step:
 * 1. Register an admin.
 * 2. Register a seller (regular business user).
 * 3. Create a product (tied to the seller).
 * 4. The admin creates two distinct channels.
 * 5. Create two product-channel mappings on the same product, each with a different channel and different status.
 * 6. As admin, search for product-channel mappings for this product:
 *    - No filter (all mappings returned)
 *    - By status (only mappings matching the given status)
 *    - By channel_id (only mapping for the given channel)
 *    - With pagination (limit=1, page=2)
 * 7. For each search, confirm:
 *    - Pagination fields accurate (limit, current/page, records, etc.)
 *    - Data array contains expected mapping(s)
 *    - All fields match expectations and RBAC access is permitted.
 */
export async function test_api_product_channel_map_search_by_admin(connection: api.IConnection) {
  // 1. Register an admin and obtain ID
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin#1234";
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
