  const adminId = adminReg.adminId;

  // 2. Register a seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Seller#1234";
  const sellerReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: ("" + typia.random<number & tags.Type<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>>()),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerReg);
  const sellerId = sellerReg.sellerId;

  // 3. Create a product under this seller
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);
  const productId = product.id;

  // 4. Admin creates 2 channels
  const channel1 = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      name: RandomGenerator.name(),
      created_by_admin_id: adminId,
      description: RandomGenerator.paragraph()(),
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channel1);
  const channel2 = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      name: RandomGenerator.name(),
      created_by_admin_id: adminId,
      description: RandomGenerator.paragraph()(),
      logo_url: null,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channel2);

  // 5. Create two mappings for the product, one for each channel, differing in status
  const mapping1 = await api.functional.shoppingMallAiBackend.admin.products.productChannelMap.createProductChannelMap(connection, {
    productId: productId,
    body: {
      product_id: productId,
      channel_id: channel1.id,
      status: "active",
    } satisfies IShoppingMallAiBackendProductChannelMap.ICreate,
  });
  typia.assert(mapping1);
  const mapping2 = await api.functional.shoppingMallAiBackend.admin.products.productChannelMap.createProductChannelMap(connection, {
    productId: productId,
    body: {
      product_id: productId,
      channel_id: channel2.id,
      status: "hidden",
    } satisfies IShoppingMallAiBackendProductChannelMap.ICreate,
  });
  typia.assert(mapping2);

