  const resAll = await api.functional.shoppingMallAiBackend.admin.products.productChannelMap.search(connection, {
    productId: productId,
    body: {},
  });
  typia.assert(resAll);
  TestValidator.equals("all mappings return")(resAll.data.length)(2);
  const mappingIds = [mapping1.id, mapping2.id];
  for (const m of resAll.data) {
    TestValidator.predicate("is expected mapping")(mappingIds.includes(m.id));
  }

  // 6.B: By status = "hidden"
  const resStatus = await api.functional.shoppingMallAiBackend.admin.products.productChannelMap.search(connection, {
    productId: productId,
    body: { status: "hidden" },
  });
  typia.assert(resStatus);
  TestValidator.equals("one hidden mapping")(resStatus.data.length)(1);
  TestValidator.equals("hidden mapping status")(resStatus.data[0].status)("hidden");
  TestValidator.equals("hidden mapping id")(resStatus.data[0].id)(mapping2.id);

  // 6.C: By channel_id = channel1
  const resChannel = await api.functional.shoppingMallAiBackend.admin.products.productChannelMap.search(connection, {
    productId: productId,
    body: { channel_id: channel1.id },
  });
  typia.assert(resChannel);
  TestValidator.equals("one for channel1")(resChannel.data.length)(1);
  TestValidator.equals("channel1 mapping id")(resChannel.data[0].id)(mapping1.id);

  // 6.D: Pagination (limit=1, page=2: get 2nd mapping)
  const resPage2 = await api.functional.shoppingMallAiBackend.admin.products.productChannelMap.search(connection, {
    productId: productId,
    body: { limit: 1, page: 2 },
