  TestValidator.equals("page 2 limit")(resPage2.pagination.limit)(1);
  TestValidator.equals("page 2 current")(resPage2.pagination.current)(2);
  TestValidator.equals("should be 1 record")(resPage2.data.length)(1);

  // 7: RBAC - admin can access all mappings for any product, so both present, and audit/logging is assumed as part of endpoint.
}

