 *
 * 1. Register Seller A and log in (obtain credentials).
 * 2. Use Seller A's credentials to create a product.
 * 3. Seller A maps the product to multiple (at least 3) categories using the productCategoryMap creation API (with at least one marked primary, the others secondary).
 * 4. Search with product's ID and confirm all mappings appear (full list).
 * 5. Use pagination (limit = 2, page = 1, page = 2) and verify paging meta and correct splits.
 * 6. Search with category_id and/or primary=true filtering – verify accuracy.
 * 7. Register Seller B and log in as B.
 * 8. Seller B attempts to search mappings for A's product (should yield access denied or empty list).
 * 9. Create a second product for Seller B (but no category mappings). Seller B queries its mappings (should get empty list).
 */
export async function test_api_product_category_map_search_by_seller_success(connection: api.IConnection) {
  // 1. Register Seller A
  const signUpA = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
