  typia.assert(pageAll);
  TestValidator.equals("all mappings for productA")(pageAll.data.length)(3);
  TestValidator.predicate("all categories present")(pageAll.data.every(x => [categoryA1, categoryA2, categoryA3].includes(x.category_id)));

  // 5. Pagination: limit 2, page 1 & 2
  const page1 = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connectionA, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      limit: 2,
      page: 1,
    },
  });
  typia.assert(page1);
  TestValidator.equals("page 1 data length")(page1.data.length)(2);
  TestValidator.equals("pagination current page")(page1.pagination.current)(1);

  const page2 = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connectionA, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      limit: 2,
      page: 2,
    },
  });
  typia.assert(page2);
  TestValidator.equals("page 2 data length")(page2.data.length)(1);
  TestValidator.equals("pagination current page")(page2.pagination.current)(2);

  // 6. Search filter: category_id and primary=true
  const filterCategory = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connectionA, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      category_id: categoryA2,
    },
  });
  typia.assert(filterCategory);
  TestValidator.equals("category_id filter count")(filterCategory.data.length)(1);
  TestValidator.equals("filtered is map2")(filterCategory.data[0].id)(map2.id);

  const filterPrimary = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connectionA, {
    productId: productA.id,
    body: {
      product_id: productA.id,
      primary: true,
    },
  });
  typia.assert(filterPrimary);
  TestValidator.equals("primary filter count")(filterPrimary.data.length)(1);
  TestValidator.equals("filtered is primary")(filterPrimary.data[0].category_id)(categoryA1);

  // 7. Register Seller B
  const signUpB = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpB);
  const sellerBId = signUpB.sellerId;

  // 8. Seller B tries to access A's product mappings (should be denied or empty)
  const connectionB: api.IConnection = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: signUpB.setHeaders.Authorization } };
  const nonOwnerSearch = await api.functional.shoppingMallAiBackend.seller.products.productCategoryMap.search(connectionB, {
    productId: productA.id,
    body: {
      product_id: productA.id,
    },
  });
  typia.assert(nonOwnerSearch);
  TestValidator.equals("non-owner has no mappings")(nonOwnerSearch.data.length)(0);

  // 9. Seller B's own product, no mappings
  const productB = await api.functional.shoppingMallAiBackend.seller.products.create(connectionB, {
    body: {
      seller_id: sellerBId,
      code: RandomGenerator.alphaNumeric(8),
