import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSnapshot";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Verify seller's ability to create an immutable product snapshot for a product they own (evidence/audit scenario).
 *
 * Business Context:
 * - Product snapshots are immutable records for compliance, rollback, auditing, and evidence.
 * - Only owners (sellers) can create snapshots for their products.
 *
 * This test ensures:
 * - Seller sign-up and authentication propagates session/token correctly for subsequent requests.
 * - Seller can create a product with valid business fields.
 * - Seller can create a new product snapshot for their product, reflecting the correct product state.
 * - All snapshot fields are correctly set and associated with the originating product.
 *
 * Limitations:
 * - Product snapshot listing endpoint is not provided in given API SDK, so list verification is omitted.
 *
 * Steps:
 * 1. Register a new seller via sign-up and obtain authentication.
 * 2. Create a product as the seller; capture IDs and business fields.
 * 3. Submit a valid product snapshot creation request, using real product data.
 * 4. Verify all fields in the returned snapshot to ensure correct association and immutability.
 */
export async function test_api_product_snapshot_creation_success_by_owner_seller(
  connection: api.IConnection,
) {
  // 1. Register a seller and authenticate
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerCompany = RandomGenerator.name();
  const sellerBno = "1101234567";
  const sellerRep = RandomGenerator.name();
  const sellerAddr = RandomGenerator.paragraph()(10);
  const sellerPhone = RandomGenerator.mobile();
  const sellerPassword = "test1234AB!";
  const signUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: sellerCompany,
      businessNumber: sellerBno,
      representativeName: sellerRep,
      address: sellerAddr,
      phone: sellerPhone,
    },
  });
  typia.assert(signUp);
  TestValidator.equals("seller email")(signUp.email)(sellerEmail);
  TestValidator.equals("company name")(signUp.companyName)(sellerCompany);
  const sellerId = signUp.sellerId;

  // 2. Seller creates a product
  const productCode = RandomGenerator.alphaNumeric(8);
  const productName = RandomGenerator.name();
  const productDesc = RandomGenerator.paragraph()(3);
  const productStatus = "draft"; // Typical initial business status
  const mainImageUri = null;     // Testing optional null for no image
  const createdProduct = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: productName,
      description: productDesc,
      main_image_uri: mainImageUri,
      status: productStatus,
    },
  });
  typia.assert(createdProduct);
  TestValidator.equals("product seller id")(createdProduct.seller_id)(sellerId);
  TestValidator.equals("product code")(createdProduct.code)(productCode);
  TestValidator.equals("product name")(createdProduct.name)(productName);

  // 3. Seller creates a product snapshot
  const snapshotCode = RandomGenerator.alphaNumeric(12);
  const snapshotType = "created";
  const createdSnapshot = await api.functional.shoppingMallAiBackend.seller.products.productSnapshots.create(connection, {
    productId: createdProduct.id,
    body: {
      product_id: createdProduct.id,
      snapshot_code: snapshotCode,
      snapshot_type: snapshotType,
      name: productName,
      description: productDesc,
      main_image_uri: mainImageUri,
      status: productStatus,
    },
  });
  typia.assert(createdSnapshot);
  TestValidator.equals("snapshot.product_id")(createdSnapshot.product_id)(createdProduct.id);
  TestValidator.equals("snapshot code")(createdSnapshot.snapshot_code)(snapshotCode);
  TestValidator.equals("snapshot type")(createdSnapshot.snapshot_type)(snapshotType);
  TestValidator.equals("snapshot name")(createdSnapshot.name)(productName);
  TestValidator.equals("snapshot description")(createdSnapshot.description)(productDesc);
  TestValidator.equals("snapshot status")(createdSnapshot.status)(productStatus);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSnapshot";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test that creating a product snapshot is forbidden for a non-owner seller.
 *
 * This API must enforce that only a product's owner (seller) can create product snapshots for that product. This test workflow verifies:
 * 1. Seller A (the owner) and Seller B (non-owner) both register accounts.
 * 2. Seller A creates a product.
 * 3. Seller B (not owner) attempts to create a snapshot for Seller A's product.
 * 4. API must return an error (403 forbidden), and no snapshot should be created.
 *
 * This business rule prevents tampering or evidence manipulation by unrelated parties, critical for audit trails.
 *
 * Steps:
 * 1. Register Seller A and obtain their sellerId and authentication (JWT).
 * 2. Switch connection to Seller A and create a product (capture productId and all required fields).
 * 3. Register Seller B and obtain their sellerId and authentication (JWT).
 * 4. Switch to Seller B's authenticated context.
 * 5. Attempt to create a product snapshot for the product owned by Seller A (prepare ICreate payload with valid fields, use productId from step 2).
 * 6. Expect API to return 403 forbidden error. Validate no data returned.
 */
export async function test_api_product_snapshot_creation_forbidden_on_non_owned_product(connection: api.IConnection) {
  // 1. Register Seller A (owner of the product)
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAPassword = "Password1!@#$";
  const sellerAProfile = {
    email: sellerAEmail,
    password: sellerAPassword,
    companyName: RandomGenerator.name(),
    businessNumber: "1234567890",
    representativeName: RandomGenerator.name(),
    address: "Seoul, South Korea",
    phone: RandomGenerator.mobile(),
  } satisfies ISellerAuth.SignUp;
  const sellerAAuthResp = await api.functional.auth.seller.register.signUp(connection, { body: sellerAProfile });
  typia.assert(sellerAAuthResp);
  // Set Seller A's Authorization
  connection.headers = { ...connection.headers, Authorization: sellerAAuthResp.setHeaders.Authorization };

  // 2. Seller A creates a product
  const productCreate = {
    seller_id: sellerAAuthResp.sellerId,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(2),
    status: "published",
  } satisfies IShoppingMallAiBackendProduct.ICreate;
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: productCreate });
  typia.assert(product);

  // 3. Register Seller B (non-owner)
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBPassword = "Password1!@#$";
  const sellerBProfile = {
    email: sellerBEmail,
    password: sellerBPassword,
    companyName: RandomGenerator.name(),
    businessNumber: "1987654321",
    representativeName: RandomGenerator.name(),
    address: "Busan, South Korea",
    phone: RandomGenerator.mobile(),
  } satisfies ISellerAuth.SignUp;
  const sellerBAuthResp = await api.functional.auth.seller.register.signUp(connection, { body: sellerBProfile });
  typia.assert(sellerBAuthResp);
  // Set Seller B's Authorization
  connection.headers = { ...connection.headers, Authorization: sellerBAuthResp.setHeaders.Authorization };

  // 4. Seller B attempts to create a snapshot for Seller A's product
  const snapshotCreate = {
    product_id: product.id,
    snapshot_code: RandomGenerator.alphaNumeric(10),
    snapshot_type: "published",
    name: product.name,
    status: product.status,
  } satisfies IShoppingMallAiBackendProductSnapshot.ICreate;

  await TestValidator.error("forbidden for non-owner seller")(
    () => api.functional.shoppingMallAiBackend.seller.products.productSnapshots.create(connection, {
      productId: product.id,
      body: snapshotCreate,
    })
  );
}

