/**
 * Validate failure to login with inactive or suspended seller account.
 *
 * This test verifies that a seller whose account status is not "active" (e.g., "suspended") cannot login. It performs:
 *
 * 1. Registers a new seller (signUp) with random but valid credentials.
 * 2. Changes the seller status to "suspended" using the admin sellers.update.
 * 3. Attempts to login as that seller - expects authentication to fail.
 * 4. Confirms error occurs (login fails), and no token/JWT is returned.
 * 5. Optionally, re-enables status and confirms login now succeeds.
 *
 * The test ensures proper enforcement of status-based login restrictions.
 */
export async function test_api_seller_login_failure_inactive_account(
  connection: api.IConnection,
) {
  // 1. Register new seller
  const email = typia.random<string & tags.Format<"email">>();
  const password = "Test1234$";
  const registration = {
    email,
    password,
    companyName: RandomGenerator.name(),
    businessNumber: `${typia.random<number & tags.Type<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>>()}`,
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(1),
    phone: RandomGenerator.mobile(),
  } satisfies ISellerAuth.SignUp;
  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: registration,
  });
  typia.assert(signUpResp);
  const sellerId = signUpResp.sellerId;

  // 2. Suspend the seller account via admin update
  const adminUpdate = {
    id: sellerId,
    status: "suspended",
  } satisfies IShoppingMallAiBackendSeller.IUpdate;
  const updateResp = await api.functional.shoppingMallAiBackend.admin.sellers.update(
    connection,
    { body: adminUpdate }
  );
  typia.assert(updateResp);
  TestValidator.equals("sellerId after update")(updateResp.id)(sellerId);
  TestValidator.equals("status suspended")(updateResp.status)("suspended");

  // 3. Attempt login and expect authentication failure
  TestValidator.error("login fails for suspended seller")(
    async () => {
      await api.functional.auth.seller.login.signIn(connection, {
        body: {
          email,
          password,
        } satisfies ISellerAuth.SignIn,
      });
    },
  );

  // 4. Control: reactivate and confirm it now succeeds
  const adminReactivate = {
    id: sellerId,
    status: "active",
  } satisfies IShoppingMallAiBackendSeller.IUpdate;
  const reactivateResp = await api.functional.shoppingMallAiBackend.admin.sellers.update(
    connection,
    { body: adminReactivate }
  );
  typia.assert(reactivateResp);
  TestValidator.equals("sellerId reactivated")(reactivateResp.id)(sellerId);
  TestValidator.equals("status active")(reactivateResp.status)("active");

  // Should now be able to login
  const signInResp = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(signInResp);
  TestValidator.equals("sellerId after login")(signInResp.sellerId)(sellerId);
  TestValidator.equals("status after login")(signInResp.status)("active");
}

