import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that the authentication system properly rejects expired or invalid JWT tokens for sellers.
 *
 * Business context:
 * This test is crucial to guarantee that the seller token validation endpoint robustly enforces authentication expiry and safeguards compliance. It ensures that sellers cannot use old/expired tokens to access protected endpoints, and that the API provides no seller context for such requests. This test also supports auditability for regulatory purposes, as improper handling of invalid tokens could introduce both security and compliance risks.
 *
 * Test workflow:
 * 1. Register a new seller account (to ensure a unique and fresh environment)
 * 2. Log in as that seller to acquire a valid JWT (and record it)
 * 3. Manually tamper with the JWT to simulate expiry (e.g., edit payload or truncate token to invalidate signature)
 * 4. Set the tampered JWT as the Authorization header in the connection
 * 5. Call the validateToken endpoint using the tampered JWT
 * 6. Assert that the response indicates the token is invalid, and that no seller details (sellerId/email/status) are returned (all should be null)
 * 7. Assert that 'valid' is false and that 'expiresAt' is null or missing
 * 8. Optionally: Check with the original valid token (should pass)
 */
export async function test_api_seller_token_validation_failure_expired_token(connection: api.IConnection) {
  // 1. Register a new seller (prerequisite for JWT issuance)
  const uniqueEmail = typia.random<string & tags.Format<"email">>();
  const signUpResult: ISellerAuth.AuthResponseWithHeaders = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: uniqueEmail,
      password: "1ValidPassw0rd!",
      companyName: "Compliance & Test Sellers, Inc.",
      businessNumber: "2210994433",
      representativeName: "Reginald Testerson",
      address: "123 Token St, Testville",
      phone: "010-2210-9944"
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(signUpResult);

  // 2. Log in using the registered account
  const loginResult: ISellerAuth.AuthResponse = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: uniqueEmail,
      password: "1ValidPassw0rd!"
    } satisfies ISellerAuth.SignIn
  });
  typia.assert(loginResult);

  // 3. Tamper with the JWT (simulate expiry/invalidity by truncating or corrupting it)
  const badJwt = loginResult.token.slice(0, loginResult.token.length - 10) + "zXCInvalid";
  const connectionWithBadJwt: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: `Bearer ${badJwt}`
    }
  };

  // 4&5. Call validate with invalid JWT
  const resultInvalid: ISellerAuth.ValidateTokenResponse = await api.functional.auth.seller.validate.validateToken(connectionWithBadJwt);
  typia.assert(resultInvalid);

  // 6&7. Assert invalid result, no identity, null expiry
  TestValidator.equals("token validity should be false")(resultInvalid.valid)(false);
  TestValidator.equals("sellerId should be null when invalid")(resultInvalid.sellerId)(null);
  TestValidator.equals("seller email should be null")(resultInvalid.email)(null);
  TestValidator.equals("seller status should be null")(resultInvalid.status)(null);
  TestValidator.equals("expiresAt should be null")(resultInvalid.expiresAt)(null);

  // 8. Check with original valid token to ensure token is valid
  const connectionWithGoodJwt: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: `Bearer ${loginResult.token}`
    }
  };

  const resultValid: ISellerAuth.ValidateTokenResponse = await api.functional.auth.seller.validate.validateToken(connectionWithGoodJwt);
  typia.assert(resultValid);
  TestValidator.equals("token validity should be true")(resultValid.valid)(true);
  TestValidator.equals("sellerId matches")(resultValid.sellerId)(loginResult.sellerId);
  TestValidator.equals("seller email matches")(resultValid.email)(loginResult.email);
  TestValidator.equals("seller status matches")(resultValid.status)(loginResult.status);
  TestValidator.predicate("expiresAt should be a non-null ISO string")(
    typeof resultValid.expiresAt === "string" && !!Date.parse(resultValid.expiresAt)
  );
}

