import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that changing a seller's password to an invalid value is not permitted and correct business rules are enforced.
 *
 * This test ensures that the seller password change API enforces password policy (e.g., minimum length, prevents past/reused passwords, checks for weak or dictionary passwords).
 *
 * Step-by-step process:
 * 1. Register a new seller with a valid, strong password (meets policy).
 * 2. Authenticate as this seller, obtain a session.
 * 3. Attempt to change the password to invalid values:
 *    - Too short (e.g., 'short')
 *    - Too simple/numeric (e.g., '12345678')
 *    - Common dictionary word (e.g., 'password')
 *    - Re-use of current password
 *    For each, expect error and no change.
 * 4. Verify the original password is still accepted for login.
 * 5. Confirm each rejected password cannot be used to login.
 *
 * This confirms proper enforcement of password policy, no state/session changes on rejected attempts, and robust security/business rule compliance for seller password management.
 */
export async function test_api_seller_change_password_failure_policy_violation(connection: api.IConnection) {
  // 1. Register seller with a strong password
  const signUpInput: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Valid1Password!", // meets strong, policy-compliant password
    companyName: RandomGenerator.alphabets(8) + " Inc.",
    businessNumber: RandomGenerator.alphaNumeric(10),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(10),
    phone: RandomGenerator.mobile(),
  };
  const registration = await api.functional.auth.seller.register.signUp(connection, {
    body: signUpInput satisfies ISellerAuth.SignUp
  });
  typia.assert(registration);

  // 2. Authenticate seller and obtain JWT/session
  const authResult = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: signUpInput.email,
      password: signUpInput.password
    } satisfies ISellerAuth.SignIn
  });
  typia.assert(authResult);
  TestValidator.equals("login email matches registration")(authResult.email)(signUpInput.email);

  // List of invalid password policy test-cases
  const invalidPasswords = [
    // Too short
    "short",
    // Common dictionary word
    "password",
    // Current (re-used) password
    signUpInput.password,
    // Only numeric, lacks complexity
    "12345678",
  ];

  for (const newPassword of invalidPasswords) {
    // Attempt to change password to an invalid one, expect policy error
    await TestValidator.error(`password policy violation: '${newPassword}' should be rejected`)(async () => {
      await api.functional.auth.seller.password.changePassword(connection, {
        body: {
          currentPassword: signUpInput.password,
          newPassword
        } satisfies ISellerAuth.ChangePassword
      });
    });
  }

  // 4. Original password should still work: login again
  const relogin = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: signUpInput.email,
      password: signUpInput.password
    } satisfies ISellerAuth.SignIn
  });
  typia.assert(relogin);
  TestValidator.equals("login after invalid changes still works")(relogin.email)(signUpInput.email);

  // 5. Verify that rejected/invalid passwords still cannot be used to login
  for (const trialPassword of invalidPasswords) {
    await TestValidator.error(`cannot login with rejected password '${trialPassword}'`)(async () => {
      await api.functional.auth.seller.login.signIn(connection, {
        body: {
          email: signUpInput.email,
          password: trialPassword,
        } satisfies ISellerAuth.SignIn
      });
    });
  }
}

