import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import type { IPageIShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductOption";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates seller product option search and pagination.
 *
 * This test ensures that a seller can list, search, and paginate their own product options using various filter criteria via the PATCH API. The seller account is created and authenticated, a product is created, and at least two options with unique distinguishing fields are registered. Search filters (option_name, SKU, status) and pagination controls are tested to guarantee correctness of returned records and pagination meta.
 *
 * Steps:
 * 1. Register seller
 * 2. Login as seller
 * 3. Create product (owned by seller)
 * 4. Add at least two product options with unique fields
 * 5. Search options by partial option_name, partial SKU, and status, validating filter correctness
 * 6. Paginate (pageSize=1), verify pagination fields and page overflow handling
 * 7. Confirm all found options are owned by test product's seller
 */
export async function test_api_seller_search_product_options_success(connection: api.IConnection) {
  // 1. Register seller (unique email, companyName, businessNumber, all required fields)
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123!",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(1),
      phone: RandomGenerator.mobile(),
    }
  });
  typia.assert(sellerSignUp);
  const sellerId = sellerSignUp.sellerId;
  const sellerEmail = sellerSignUp.email;

  // 2. Authenticate as seller (token auto-managed in connection)
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: "Password123!",
    },
  });

  // 3. Create product under seller
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(1),
      main_image_uri: null,
      status: "published",
    },
  });
  typia.assert(product);

  // 4. Create two options with different values
  const option1Name = "OptionAlpha" + RandomGenerator.alphaNumeric(2);
  const option2Name = "OptionBeta" + RandomGenerator.alphaNumeric(2);
  const status1 = "active";
  const status2 = "inactive";
  const sku1 = "SKU-" + RandomGenerator.alphaNumeric(5);
  const sku2 = "SKU-" + RandomGenerator.alphaNumeric(5);

  const option1 = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: sku1,
      option_name: option1Name,
      option_values: null,
      extra_price: null,
      main_image_uri: null,
      status: status1,
    },
  });
  typia.assert(option1);
  const option2 = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: sku2,
      option_name: option2Name,
      option_values: null,
      extra_price: null,
      main_image_uri: null,
      status: status2,
    },
  });
  typia.assert(option2);

  // 5a. Search by partial option_name (should return correct record, page size 1)
  const pageSearchName = await api.functional.shoppingMallAiBackend.seller.products.productOptions.search(connection, {
    productId: product.id,
    body: {
      filter: { option_name: option1Name.slice(0, 7), productId: product.id },
      page: 1,
      pageSize: 1,
    },
  });
  typia.assert(pageSearchName);
  TestValidator.equals("pagination - page 1")(pageSearchName.pagination.current)(1);
  TestValidator.equals("pagination limit = 1")(pageSearchName.pagination.limit)(1);
  TestValidator.predicate("filtered by option_name partial")(
    pageSearchName.data.length === 1 && pageSearchName.data[0].option_name.includes(option1Name.slice(0, 7))
  );
  TestValidator.equals("ownership")(pageSearchName.data[0].product_id)(product.id);

  // 5b. Search by partial SKU (should return correct option)
  const pageSearchSku = await api.functional.shoppingMallAiBackend.seller.products.productOptions.search(connection, {
    productId: product.id,
    body: {
      filter: { sku: sku2.substring(0, 5), productId: product.id },
      page: 1,
      pageSize: 1,
    },
  });
  typia.assert(pageSearchSku);
  TestValidator.predicate("filtered by sku partial")(
    pageSearchSku.data.length === 1 && pageSearchSku.data[0].sku.startsWith(sku2.substring(0, 5))
  );
  TestValidator.equals("option name matches")(pageSearchSku.data[0].option_name)(option2Name);
  TestValidator.equals("ownership")(pageSearchSku.data[0].product_id)(product.id);

  // 5c. Search/filter by status (page all, pageSize 2)
  const pageSearchStatus = await api.functional.shoppingMallAiBackend.seller.products.productOptions.search(connection, {
    productId: product.id,
    body: {
      filter: { status: status1, productId: product.id },
      page: 1,
      pageSize: 2,
    },
  });
  typia.assert(pageSearchStatus);
  const expectedOptions = [option1].filter(opt => opt.status === status1);
  TestValidator.equals("status-fltr count")(pageSearchStatus.data.length)(expectedOptions.length);
  TestValidator.equals("status match")(pageSearchStatus.data[0].status)(status1);
  TestValidator.equals("ownership")(pageSearchStatus.data[0].product_id)(product.id);

  // 5d. Page 2 for above filter (should be empty input - only 1 record)
  const exhaustedPage = await api.functional.shoppingMallAiBackend.seller.products.productOptions.search(connection, {
    productId: product.id,
    body: {
      filter: { status: status1, productId: product.id },
      page: 2,
      pageSize: 1,
    },
  });
  typia.assert(exhaustedPage);
  TestValidator.equals("empty page on pagination overflow")(exhaustedPage.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import type { IPageIShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductOption";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that seller cannot search (PATCH) product options of a product owned by another seller (permission denial).
 *
 * This test covers cross-seller access control (information leakage prevention) for the product options search endpoint.
 *
 * Scenario:
 * 1. Register Seller A (intended product owner) and Seller B (non-owner adversary)
 * 2. Seller A logs in and creates a new product
 * 3. Seller A adds an option to that product
 * 4. Seller B logs in (switches authentication context)
 * 5. Seller B attempts to PATCH /shoppingMallAiBackend/seller/products/{productId}/productOptions
 *    for the product owned by Seller A (passing valid filter/search request or empty object)
 * 6. Assert that the API call fails with 403 Forbidden error (permission denied)
 * 7. Assert that no sensitive product or option information is leaked in the error response body
 * 8. (Note: Validation of audit trail for denied action is not feasible from API, assumed tested at system level)
 *
 * Steps:
 * - Seller registration and authentication
 * - Product and option creation for Seller A
 * - Authentication switching to Seller B
 * - Unauthorized PATCH product options operation and assertion of outcome
 */
export async function test_api_seller_search_product_options_invalid_product_permissions(connection: api.IConnection) {
  // Step 1: Register Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerAPassword = "Password@1";
  const sellerAProfile = {
    email: sellerAEmail,
    password: sellerAPassword,
    companyName: RandomGenerator.name(),
    businessNumber: "1234567890",
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  } satisfies ISellerAuth.SignUp;
  const sellerAReg = await api.functional.auth.seller.register.signUp(connection, { body: sellerAProfile });
  typia.assert(sellerAReg);
  const sellerAId = sellerAReg.sellerId;

  // Step 2: Register Seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBPassword = "Password@2";
  const sellerBProfile = {
    email: sellerBEmail,
    password: sellerBPassword,
    companyName: RandomGenerator.name(),
    businessNumber: "0987654321",
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  } satisfies ISellerAuth.SignUp;
  const sellerBReg = await api.functional.auth.seller.register.signUp(connection, { body: sellerBProfile });
  typia.assert(sellerBReg);
  const sellerBId = sellerBReg.sellerId;

  // Step 3: Seller A logs in
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerAEmail,
      password: sellerAPassword,
    } satisfies ISellerAuth.SignIn,
  });

  // Step 4: Seller A creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerAId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: "Product owned by sellerA for permissions test.",
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // Step 5: Seller A adds a product option
  const option = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: "SKU-001",
      option_name: "Size",
      option_values: "Small,Medium,Large",
      extra_price: 500,
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProductOption.ICreate,
  });
  typia.assert(option);

  // Step 6: Switch to Seller B (adversary)
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerBEmail,
      password: sellerBPassword,
    } satisfies ISellerAuth.SignIn,
  });

  // Step 7: Seller B attempts PATCH product option search for Seller A's product
  // Expect 403 error and no sensitive data in response
  await TestValidator.error("PATCH search forbidden for non-owner")(
    async () => {
      await api.functional.shoppingMallAiBackend.seller.products.productOptions.search(connection, {
        productId: product.id,
        body: {}, // valid, minimal request allowed
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import type { IPageIShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductOption";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that an admin can search and paginate product options for any product across the catalog, not just their own. 
 *
 * This test ensures that:
 * - Role permissions are enforced: only an admin can perform the global option search.
 * - Seller can successfully create a product and attach multiple options to it.
 * - The admin can search for product options with filters (SKU, status) and pagination across all products (not scoped only to their own).
 * - Query logic works: The response contains only the expected options and respects pagination and filter constraints.
 *
 * 1. Register a new admin account and login to get an admin connection.
 * 2. Register a seller account and login to get a seller-authenticated connection.
 * 3. Seller creates a new product with a unique SKU.
 * 4. Seller creates two options for their product: e.g., distinct SKU and status.
 * 5. Switch to the admin connection (admin should have global visibility).
 * 6. Admin searches options for the seller's product by filtering for one option's SKU (should get only that option).
 * 7. Admin searches with a status filter and page size 1 (should get a single-page result with pageSize respected).
 * 8. Admin searches with no filters but pageSize 1, then fetch page 2 (should get the other option in the second page).
 * 9. For each search, validate the returned option(s) match expected data, and pagination info is correct.
 */
export async function test_api_admin_search_product_options_all_products(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPass123!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as admin to populate Authorization
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });

  // 3. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "sellerpass1!";
  const sellerCompany = RandomGenerator.alphabets(8) + " Inc.";
  const seller = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: sellerCompany,
      businessNumber: RandomGenerator.sample(["1234567890","2345678901","3456789012"])(1)[0],
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller);

  // 4. Login as seller
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuth.SignIn,
  });

  // 5. Seller creates product
  const productCode = RandomGenerator.alphaNumeric(7);
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: seller.sellerId,
      code: productCode,
      name: "test-e2e product " + RandomGenerator.alphabets(5),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 6. Seller creates two options for the product
  const optionA: IShoppingMallAiBackendProductOption = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: productCode + "-RED",
      option_name: "Color",
      option_values: "Red",
      extra_price: 1000.0,
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProductOption.ICreate,
  });
  typia.assert(optionA);

  const optionB: IShoppingMallAiBackendProductOption = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      sku: productCode + "-BLUE",
      option_name: "Color",
      option_values: "Blue",
      extra_price: 2000.0,
      main_image_uri: null,
      status: "inactive",
    } satisfies IShoppingMallAiBackendProductOption.ICreate,
  });
  typia.assert(optionB);

  // 7. Switch back to admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });

  // 8. Admin searches for only optionA with SKU filter
  {
    const result = await api.functional.shoppingMallAiBackend.admin.products.productOptions.search(connection, {
      productId: product.id,
      body: {
        filter: {
          sku: optionA.sku,
        },
        page: 1,
        pageSize: 10,
      } satisfies IShoppingMallAiBackendProductOption.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("optionA sku search count")(result.data.length)(1);
    TestValidator.equals("optionA sku search item")(result.data[0].sku)(optionA.sku);
  }

  // 9. Admin searches for inactive status, pageSize 1, should get only optionB
  {
    const result = await api.functional.shoppingMallAiBackend.admin.products.productOptions.search(connection, {
      productId: product.id,
      body: {
        filter: {
          status: "inactive",
        },
        page: 1,
        pageSize: 1,
      } satisfies IShoppingMallAiBackendProductOption.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("inactive status")(result.data.length)(1);
    TestValidator.equals("status value")(result.data[0].status)("inactive");
    TestValidator.equals("sku value")(result.data[0].sku)(optionB.sku);
  }

  // 10. Admin searches with no filter, pageSize 1, fetch page 2 (should get the second option). Order by SKU for deterministic paging.
  {
    const resultPage1 = await api.functional.shoppingMallAiBackend.admin.products.productOptions.search(connection, {
      productId: product.id,
      body: {
        page: 1,
        pageSize: 1,
        sort: [{ field: "sku", direction: "asc" }],
      } satisfies IShoppingMallAiBackendProductOption.IRequest,
    });
    typia.assert(resultPage1);
    TestValidator.equals("page 1 count")(resultPage1.data.length)(1);
    const resultPage2 = await api.functional.shoppingMallAiBackend.admin.products.productOptions.search(connection, {
      productId: product.id,
      body: {
        page: 2,
        pageSize: 1,
        sort: [{ field: "sku", direction: "asc" }],
      } satisfies IShoppingMallAiBackendProductOption.IRequest,
    });
    typia.assert(resultPage2);
    TestValidator.equals("page 2 count")(resultPage2.data.length)(1);
    TestValidator.notEquals("different SKU in pages")(resultPage1.data[0].sku)(resultPage2.data[0].sku);
    // Optionally confirm that the returned options are the expected ones
    const skus = [resultPage1.data[0].sku, resultPage2.data[0].sku].sort();
    const expectedSkus = [optionA.sku, optionB.sku].sort();
    TestValidator.equals("all returned skus between both pages")(skus)(expectedSkus);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that a seller can retrieve all details for a specific product option they own via GET /shoppingMallAiBackend/seller/products/{productId}/productOptions/{productOptionId}.
 *
 * Business purpose:
 *  - Ensures sellers can access product option details for management and auditing.
 *  - Confirms owner-only access and correct field-level integrity.
 *
 * Steps:
 * 1. Register a new seller with unique business credentials.
 * 2. Authenticate the seller to receive valid session/JWT for protected API access.
 * 3. As seller, create a product using API, saving its product id for parent linkage.
 * 4. As seller, create a new product option for the above product via products/{productId}/productOptions, saving option id for retrieval.
 * 5. Retrieve option details using /shoppingMallAiBackend/seller/products/{productId}/productOptions/{productOptionId}.
 * 6. Verify that every field matches the data in DB (should be identical to the create result), covering referential and field-level integrity.
 * 7. Optionally, try accessing with a non-owner (should fail - omitted here, implement only as feasible). 
 */
export async function test_api_seller_get_own_product_option_success(connection: api.IConnection) {
  // 1. Register a new seller
  const signUpInput: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password123!",
    companyName: RandomGenerator.name(),
    businessNumber: (1000000000 + Math.floor(Math.random() * 9000000000)).toString(),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  };
  const registerResult = await api.functional.auth.seller.register.signUp(connection, { body: signUpInput });
  typia.assert(registerResult);
  const sellerId = registerResult.sellerId;
  // 2. Authenticate as this seller
  const loginResult = await api.functional.auth.seller.login.signIn(connection, { body: { email: signUpInput.email, password: signUpInput.password } });
  typia.assert(loginResult);
  // 3. Create a product as seller
  const createProductInput: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: sellerId,
    code: "SKU-" + Math.floor(Math.random() * 1000000),
    name: RandomGenerator.name(),
    description: RandomGenerator.content()()(),
    status: "published",
    main_image_uri: null,
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: createProductInput });
  typia.assert(product);
  // 4. Create a product option under this product
  const createOptionInput: IShoppingMallAiBackendProductOption.ICreate = {
    product_id: product.id,
    sku: "OPT-" + Math.floor(Math.random() * 1000000),
    option_name: "Color",
    option_values: "Red,Blue,Green",
    extra_price: 1500.50,
    status: "active",
    main_image_uri: null,
  };
  const option = await api.functional.shoppingMallAiBackend.seller.products.productOptions.create(connection, { productId: product.id, body: createOptionInput });
  typia.assert(option);
  // 5. Retrieve the option by ID
  const fetched = await api.functional.shoppingMallAiBackend.seller.products.productOptions.at(connection, { productId: product.id, productOptionId: option.id });
  typia.assert(fetched);
  // 6. Deep compare database state and input entity
  TestValidator.equals("product option id matches")(fetched.id)(option.id);
  TestValidator.equals("parent product id matches")(fetched.product_id)(product.id);
  TestValidator.equals("sku matches")(fetched.sku)(createOptionInput.sku);
  TestValidator.equals("option name matches")(fetched.option_name)(createOptionInput.option_name);
  TestValidator.equals("option values matches")(fetched.option_values)(createOptionInput.option_values);
  TestValidator.equals("extra price matches")(fetched.extra_price)(createOptionInput.extra_price);
  TestValidator.equals("main image uri matches")(fetched.main_image_uri)(createOptionInput.main_image_uri);
  TestValidator.equals("status matches")(fetched.status)(createOptionInput.status);
  // Timestamps created_at and updated_at must be valid date-times
  TestValidator.predicate("created_at valid datetime")(!!Date.parse(fetched.created_at));
  TestValidator.predicate("updated_at valid datetime")(!!Date.parse(fetched.updated_at));
  // deleted_at is null at create
  TestValidator.equals("deleted_at is null at create")(fetched.deleted_at)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates that a seller cannot access another seller's product option details and gets a 403 Forbidden error.
 *
 * This test covers a key authorization safeguard: only the owner of a product (Seller A) can access its options, while other sellers (Seller B) are forbidden, ensuring sensitive product configuration data is not leaked and unauthorized access is detected/audited. Audit trail requirements are out-of-band for E2E validation but could be checked via backend logs.
 *
 * Step-by-step scenario:
 * 1. Register Seller A (the product/option owner) with unique credentials
 * 2. Register Seller B (the outsider)
 * 3. Seller A logs in
 * 4. Seller A creates a product
 * 5. Seller A creates a product option under that product
 * 6. Seller B logs in (switches authentication)
 * 7. Seller B sends a GET request to retrieve Seller A's product option details (by product and option ID)
 * 8. Expects a 403 Forbidden error, confirming no sensitive data is returned to Seller B
 * 9. Confirms type-safety: forbidden error is handled, result is not a successful data record
 */
export async function test_api_seller_get_product_option_forbidden(connection: api.IConnection) {
