}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderStatusHistory";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate customer order status history creation—including both success and illegal transition paths.
 *
 * Business context:
 * Ensures customer order status transitions are correctly audited through status history.
 * This includes both a valid change (e.g., 'pending' > 'paid') and several illegal transitions that should be rejected.
 *
 * Scenario steps:
 * 1. Register a new customer (random info for uniqueness).
 * 2. Create a new order for this customer in 'pending' status.
 * 3. Perform a valid order status transition (e.g., 'pending' > 'paid') and validate results.
 * 4. Attempt illegal status transitions and ensure they are rejected.
 *    a) 'created' > 'delivered' (typically invalid)
 *    b) Any transition from a 'cancelled' state
 */
export async function test_api_order_status_history_create_success_and_illegal_transition(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const email = typia.random<string & tags.Format<'email'>>();
  const password = 'Abcd!1234';
  const nickname = RandomGenerator.name();
  const name = RandomGenerator.name();
  const phone = RandomGenerator.mobile();
  const signUpRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name,
      nickname,
      phone,
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signUpRes);
  const customer = signUpRes.customer;

  // 2. Create a new order with 'pending' status
  const orderNumber = `ORD-${typia.random<number & tags.Type<'uint32'>>()}`;
  const totalAmount = typia.random<number & tags.Type<'uint32'> & tags.Minimum<1000> & tags.Maximum<50000>>();
  const currency = 'USD';
  const createOrderBody = {
    customer_id: customer.id,
    order_number: orderNumber,
    total_amount: totalAmount,
    currency_code: currency,
    current_status: 'pending',
  } satisfies IShoppingMallAiBackendOrder.ICreate;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: createOrderBody,
  });
  typia.assert(order);
  TestValidator.equals('order.customer_id')(order.customer_id)(customer.id);
  TestValidator.equals('order.current_status')(order.current_status)('pending');

  // 3. Perform a valid order status transition: pending -> paid
  const transitionTime = new Date().toISOString();
  const historyBody: IShoppingMallAiBackendOrderStatusHistory.ICreate = {
    previous_status: 'pending',
    new_status: 'paid',
    actor_type: 'customer',
    actor_id: customer.id,
    event_context: 'Customer completed payment',
    occurred_at: transitionTime,
  };
  const statusHistory = await api.functional.shoppingMallAiBackend.customer.orders.orderStatusHistories.create(connection, {
    orderId: order.id,
    body: historyBody,
  });
  typia.assert(statusHistory);
  TestValidator.equals('order id')(statusHistory.order_id)(order.id);
  TestValidator.equals('statuses')(statusHistory.previous_status)('pending');
  TestValidator.equals('statuses')(statusHistory.new_status)('paid');
  TestValidator.equals('actor_id')(statusHistory.actor_id)(customer.id);
  TestValidator.equals('actor_type')(statusHistory.actor_type)('customer');
  TestValidator.equals('event_context')(statusHistory.event_context)('Customer completed payment');
  // occurred_at should be same as sent
  TestValidator.equals('occurred_at')(statusHistory.occurred_at)(transitionTime);

  // 4. Attempt illegal status transitions
  // a) created -> delivered (should fail)
  const badHistoryA: IShoppingMallAiBackendOrderStatusHistory.ICreate = {
    previous_status: 'created',
    new_status: 'delivered',
    actor_type: 'customer',
    actor_id: customer.id,
    event_context: 'Attempted illegal direct delivery',
    occurred_at: new Date().toISOString(),
  };
  await TestValidator.error('illegal transition: created->delivered')(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderStatusHistories.create(connection, {
        orderId: order.id,
        body: badHistoryA,
      });
    },
  );

  // b) transition from cancelled (should fail)
  // First, transition order to cancelled.
  const cancelHistory: IShoppingMallAiBackendOrderStatusHistory.ICreate = {
    previous_status: 'paid',
    new_status: 'cancelled',
    actor_type: 'customer',
    actor_id: customer.id,
    event_context: 'Customer cancelled',
    occurred_at: new Date().toISOString(),
  };
  const cancelledStatus = await api.functional.shoppingMallAiBackend.customer.orders.orderStatusHistories.create(connection, {
    orderId: order.id,
    body: cancelHistory,
  });
  typia.assert(cancelledStatus);
  TestValidator.equals('cancelled')(cancelledStatus.new_status)('cancelled');

  // Try to update status after cancelled (should fail)
  const afterCancelHistory: IShoppingMallAiBackendOrderStatusHistory.ICreate = {
    previous_status: 'cancelled',
    new_status: 'paid',
    actor_type: 'customer',
    actor_id: customer.id,
    event_context: 'Re-paying after cancellation',
    occurred_at: new Date().toISOString(),
  };
  await TestValidator.error('illegal transition: cancelled->paid')(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderStatusHistories.create(connection, {
        orderId: order.id,
        body: afterCancelHistory,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
