  // 11. Non-existent orderId → empty or error
  const fakeOrderId = typia.random<string & tags.Format<"uuid">>();
  const noSnapshotsResults = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.search(connection, {
    orderId: fakeOrderId,
    body: {},
