import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates that an admin can update any shopping cart by its cartId.
 *
 * Ensures correct privilege boundaries between customer and admin:
 * 1. Registers and authenticates both an admin and a customer.
 * 2. Customer creates a cart (default status 'active').
 * 3. Admin logs in and updates the cart (status change, clears session_token).
 * 4. Verifies that updates are successful and reflected in the cart, including audit fields and nullability.
 * 5. Confirms unauthorized (customer) update attempt fails as expected (error handling covered generically per guideline).
 */
export async function test_api_cart_update_by_admin(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // Login as admin (again, in case signUp doesn't fully authenticate or to refresh session)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
