/**
 * Validates the soft-delete operation (erase by owner) for shopping cart.
 *
 * This test verifies that an authenticated customer can soft-delete (mark as deleted, not hard delete) their own cart. The test covers:
 * 
 * 1. Register and login as a customer, obtaining valid authentication.
 * 2. Create a new cart (business status 'active') for the customer.
 * 3. Perform a DELETE on that cartId via the soft-delete endpoint.
 * 4. (If list/fetch endpoints existed: Confirm the deleted cart is marked as deleted and excluded from results.)
 * 5. Attempt to re-delete the same cart to ensure the API prevents double-delete (or returns correct error).
 *
 * Note: Only features available via provided SDK functions are implemented. Cart exclusion from further queries/inaccessibility after delete is only partially testable here due to absence of fetch/list/update APIs.
 */
export async function test_api_cart_erase_by_owner(connection: api.IConnection) {
  // Step 1: Register a new customer and set the issued token for the session
  const email = typia.random<string & tags.Format<"email">>();
  const password = "Abcd!@#123";
  const nickname = RandomGenerator.name();
  const phone = RandomGenerator.mobile();
  const name = RandomGenerator.name();
  const register = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name,
      nickname,
      phone,
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(register);
  // Use the returned Authorization from registration response
  connection.headers = { ...connection.headers, Authorization: register.setHeaders.Authorization };

  // Explicit login (after registration) to confirm credentials and refresh token
  const login = await api.functional.auth.customer.login.signIn(connection, {
    body: { email, password } satisfies ICustomerSignIn.Request,
  });
  typia.assert(login);
  connection.headers = { ...connection.headers, Authorization: login.setHeaders.Authorization };

  // Step 2: Create a cart owned by this customer
  const createCart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    } satisfies IShoppingMallAiBackendCart.ICreate,
  });
  typia.assert(createCart);
  TestValidator.equals("Cart initial status")(createCart.status)("active");
  TestValidator.equals("Cart must not be soft-deleted at creation")(createCart.deleted_at)(null);

  // Step 3: Soft-delete the cart (erase by owner)
  await api.functional.shoppingMallAiBackend.customer.carts.erase(connection, {
    cartId: createCart.id,
  });

  // Step 4: Negative test — attempt to re-delete the already-deleted cart; should fail
  let failedDelete = false;
  try {
    await api.functional.shoppingMallAiBackend.customer.carts.erase(connection, {
      cartId: createCart.id,
    });
  } catch {
    failedDelete = true;
  }
  TestValidator.predicate("Re-deleting deleted cart should fail")(failedDelete);

  // (If fetch/list API existed: would test exclusion and deleted_at field here)
}

