  const couponUsage2 = await api.functional.shoppingMallAiBackend.admin.couponUsages.create(connection, {
    body: {
      issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
      order_id: typia.random<string & tags.Format<"uuid">>(),
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      used_at: new Date(Date.now() - 86400000).toISOString(), // 1 day ago
    } satisfies IShoppingMallAiBackendCouponUsage.ICreate,
  });
  typia.assert(couponUsage2);

  // 3. Search with no filters—should see both records & valid pagination summary structure
  let searchResult = await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
    body: { page: 1, limit: 10 } satisfies IShoppingMallAiBackendCouponUsage.IRequest,
  });
  typia.assert(searchResult);
  TestValidator.predicate("found at least two records")(searchResult.data.length >= 2);

  // 4. Filter by issued_coupon_id
  searchResult = await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
    body: {
      issued_coupon_id: couponUsage1.issued_coupon_id,
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendCouponUsage.IRequest,
  });
  typia.assert(searchResult);
  TestValidator.equals("filtered records are correct")(searchResult.data[0].issued_coupon_id)(couponUsage1.issued_coupon_id);
  TestValidator.predicate("only one result")(
    searchResult.data.length === 1 && searchResult.data[0].id === couponUsage1.id
  );

  // 5. Non-existent issued_coupon_id
  searchResult = await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
    body: {
      issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendCouponUsage.IRequest,
  });
  typia.assert(searchResult);
  TestValidator.equals("empty on unmatched filter")(searchResult.data.length)(0);

  // 6. Filter by used_at date window (only couponUsage2 matches)
  searchResult = await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
    body: {
      used_at_from: couponUsage2.used_at,
      used_at_to: couponUsage2.used_at,
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendCouponUsage.IRequest,
  });
  typia.assert(searchResult);
  TestValidator.equals("correct record filtered by date")(searchResult.data.length)(1);
  TestValidator.equals("correct id by date")(searchResult.data[0].id)(couponUsage2.id);

  // 7. Filter by customer_id and order_id
  searchResult = await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
    body: {
      customer_id: couponUsage1.customer_id,
      order_id: couponUsage1.order_id,
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendCouponUsage.IRequest,
  });
  typia.assert(searchResult);
  TestValidator.equals("customer_id matches")(searchResult.data[0].customer_id)(couponUsage1.customer_id);
  TestValidator.equals("order_id matches")(searchResult.data[0].order_id)(couponUsage1.order_id);

  // 8. Sort by used_at desc then asc
  searchResult = await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
    body: {
      page: 1,
      limit: 10,
      sort: "used_at desc",
    } satisfies IShoppingMallAiBackendCouponUsage.IRequest,
  });
  typia.assert(searchResult);
  if (searchResult.data.length >= 2) {
    TestValidator.predicate("sorted desc")(
      new Date(searchResult.data[0].used_at) >= new Date(searchResult.data[1].used_at)
    );
  }
  searchResult = await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
    body: {
      page: 1,
      limit: 10,
      sort: "used_at asc",
    } satisfies IShoppingMallAiBackendCouponUsage.IRequest,
  });
  typia.assert(searchResult);
  if (searchResult.data.length >= 2) {
    TestValidator.predicate("sorted asc")(
      new Date(searchResult.data[0].used_at) <= new Date(searchResult.data[1].used_at)
    );
  }

  // 9. Error: page=0, negative limit, malformed uuid, all should throw
  await TestValidator.error("page=0 should error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
        body: { page: 0, limit: 5 } as any,
      });
    },
  );
  await TestValidator.error("negative limit should error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
        body: { page: 1, limit: -1 } as any,
      });
    },
  );
  await TestValidator.error("malformed uuid for issued_coupon_id should error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
        body: { page: 1, limit: 5, issued_coupon_id: "not-a-uuid" as any } as any,
      });
    },
  );

  // 10. Output structure
  TestValidator.predicate("paginated structure present")(!!searchResult.pagination && Array.isArray(searchResult.data));
  // 11. Audit log event: side effect (not surfaced or testable directly via API)
}

