/**
 * Validate that non-admin users cannot search coupon usage (permission denied).
 *
 * This test ensures that the coupon usage search endpoint, intended for admin use, enforces proper role/permission restrictions.
 * Any attempt from a non-admin context (expired admin JWT or customer/seller JWT, even if structure/format is correct) must fail with a permission error.
 *
 * Workflow:
 * 1. Authenticate as admin to obtain a valid JWT and verify that searching coupon usages succeeds (reference case).
 * 2. Attempt the same coupon usage search with an explicitly expired admin JWT, expecting permission denied or unauthorized error.
 * 3. Attempt the coupon usage search without any Authorization header (fully unauthenticated), expecting permission denied error.
 * 4. Validate that for all non-admin/expired/invalid contexts, the API call fails and returns an error (TestValidator.error) with suitable error code/status (e.g., 401/403).
 */
export async function test_api_coupon_usage_search_no_permission(
  connection: api.IConnection,
) {
  // 1. Obtain admin JWT
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "ValidPassword123!";
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);

  // Set Authorization header for connection (Bearer token)
  connection.headers = {
    ...connection.headers,
    Authorization: adminSignIn.setHeaders.Authorization,
  };

  // 2. Valid admin: perform coupon usage search (reference success case)
  const requestBody: IShoppingMallAiBackendCouponUsage.IRequest = {
    page: 1,
    limit: 5,
  };
  const result = await api.functional.shoppingMallAiBackend.admin.couponUsages.search(connection, {
    body: requestBody,
  });
  typia.assert(result);

  // 3. Attempt search with expired/invalid JWT (simulate by giving bogus token)
  const invalidTokenConnection = {
    ...connection,
    headers: { ...connection.headers, Authorization: "Bearer expired.invalid.token" },
  };
  TestValidator.error("expired/invalid admin JWT fails")(() =>
    api.functional.shoppingMallAiBackend.admin.couponUsages.search(invalidTokenConnection, {
      body: requestBody,
    })
  );

  // 4. Attempt search with no Authorization header
  const noAuthConnection = {
    ...connection,
    headers: Object.fromEntries(
      Object.entries(connection.headers ?? {}).filter(([k]) => k.toLowerCase() !== "authorization"),
    ),
  };
  TestValidator.error("no Authorization header fails")(() =>
    api.functional.shoppingMallAiBackend.admin.couponUsages.search(noAuthConnection, {
      body: requestBody,
    })
  );
}

