import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponTemplate";
import type { IPageIShoppingMallAiBackendCouponTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCouponTemplate";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates advanced search, filtering, and pagination of coupon templates for admin users.
 *
 * This comprehensive scenario verifies that the coupon template search endpoint
 * (PATCH /shoppingMallAiBackend/admin/couponTemplates) correctly implements
 * multi-field filtering, paginates accurately, and enforces admin-only access.
 * Both positive (matches present) and negative (zero results) filter cases
 * are tested, including edge cases for date/time and permission enforcement.
 *
 * Steps:
 * 1. Register a new admin and authenticate to get a valid JWT.
 * 2. As admin, create five coupon templates with diverse attributes (code,
 *    name, type, valid windows, and is_active status).
 * 3. Execute filter/search queries:
 *    - Partial match by code
 *    - By coupon type and enabled status
 *    - Pagination (limit/page mechanics)
 *    - Full use of validity window/date filters
 *    - Combined field filters
 *    - Edge: unmatched name, date window with no match
 * 4. Confirm results strictly match input filter and returned pagination is accurate.
 * 5. Simulate unauthorized search (remove auth header) to validate admin-only access.
 */
export async function test_api_coupon_template_advanced_search_filtering_pagination(connection: api.IConnection) {
  // Step 1: Register and authenticate an admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword1!";
  const signUp = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignUp,
  });
  typia.assert(signUp);

  const signIn = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignIn,
  });
  typia.assert(signIn);

  // Step 2: As admin, create a diverse set of coupon templates for search testing
  // Mix codes, types, windows, and activation for robust coverage
  const now = new Date();
  const templates: IShoppingMallAiBackendCouponTemplate[] = [];
  for (let i = 0; i < 5; ++i) {
    // Even indices: type=discount, odd: type=gift; is_active toggled
    // validity windows staggered across now/soon for date filter testing
    const template: IShoppingMallAiBackendCouponTemplate = await api.functional.shoppingMallAiBackend.admin.couponTemplates.create(connection, {
      body: {
        code: `SPEC${i}` + RandomGenerator.alphaNumeric(5),
        name: i % 2 === 0 ? `Promo Discount ${i}` : `Gift Bonus ${i}`,
        description: i % 2 === 0 ? `Discount for type discount (${i})` : null,
        type: i % 2 === 0 ? "discount" : "gift",
        discount_amount: i % 2 === 0 ? 15 * (i + 1) : null,
        discount_percent: i % 2 === 1 ? 8 * (i + 1) : null,
        min_purchase_amount: i % 2 === 0 ? 90 * (i + 1) : null,
        valid_from: new Date(now.getTime() + i * 86400000).toISOString(), // Today + i days
        valid_until: new Date(now.getTime() + (i + 2) * 86400000).toISOString(), // +2 days window
        max_issue_count: i % 3 === 0 ? 50 + i * 10 : null,
        is_active: i % 2 === 0,
      } satisfies IShoppingMallAiBackendCouponTemplate.ICreate,
    });
    typia.assert(template);
    templates.push(template);
  }

  // Step 3.1: Search by code partial (should match all, as codes share SPEC prefix)
  const byCode = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: { code: "SPEC", limit: 10 } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(byCode);
  TestValidator.predicate("all codes start with 'SPEC'")(byCode.data.every((t) => t.code.includes("SPEC")));

  // Step 3.2: Filter by type and is_active (find only 'discount' and enabled)
  const activeDiscount = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: { type: "discount", is_active: true, limit: 10 } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(activeDiscount);
  for (const t of activeDiscount.data) {
    TestValidator.equals("type=discount")(t.type)("discount");
    TestValidator.equals("is_active=true")(t.is_active)(true);
  }

  // Step 3.3: Pagination test (limit=2 should return at most 2 records, with meta)
  const paged = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: { limit: 2, page: 2 } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("pagination limit 2")(paged.pagination.limit)(2);
  TestValidator.equals("page = 2")(paged.pagination.current)(2);
  TestValidator.predicate("at most 2 records shown")(paged.data.length <= 2);

  // Step 3.4: Valid_from window filter (should return only future templates)
  const minWindow = templates[1].valid_from;
  const maxWindow = templates[3].valid_until;
  const byValidWindow = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: { valid_from_min: minWindow, valid_until_max: maxWindow } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(byValidWindow);
  TestValidator.predicate("all valid_from >= minWindow")(
    byValidWindow.data.every((t) => t.valid_from >= minWindow)
  );
  TestValidator.predicate("all valid_until <= maxWindow")(
    byValidWindow.data.every((t) => t.valid_until <= maxWindow)
  );

  // Step 3.5: Combined filters (by name + type + is_active, unique match)
  const lastTemplate = templates[4];
  const combinedSearch = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: {
      name: lastTemplate.name,
      type: lastTemplate.type,
      is_active: lastTemplate.is_active,
      code: lastTemplate.code.substring(0, 6),
      valid_from_min: lastTemplate.valid_from,
      valid_until_max: lastTemplate.valid_until,
    } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(combinedSearch);
  // Should match at most 1 record with those combined criteria
  TestValidator.predicate("combined search at most 1 result")(combinedSearch.data.length <= 1);
  if (combinedSearch.data.length === 1) {
    TestValidator.equals("id matches")(combinedSearch.data[0].id)(lastTemplate.id);
  }

  // Step 3.6: Edge case - unmatched name
  const neverExist = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: { name: "NonExistentName123" } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(neverExist);
  TestValidator.equals("no records for unmatched name")(neverExist.pagination.records)(0);
  TestValidator.equals("no data for unmatched name")(neverExist.data.length)(0);

  // Step 3.7: Edge case - date window excludes all
  const farPast = new Date(now.getTime() - 3600 * 1000 * 48).toISOString();
  const farFuture = new Date(now.getTime() - 3600 * 1000 * 36).toISOString();
  const noDateMatch = await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(connection, {
    body: { valid_from_min: farPast, valid_from_max: farFuture } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
  });
  typia.assert(noDateMatch);
  TestValidator.equals("records = 0 when out of date window")(noDateMatch.pagination.records)(0);

  // Step 4: Simulate unauthorized search (clear auth)
  const anonymousConn = { ...connection, headers: { ...connection.headers } };
  delete anonymousConn.headers["Authorization"];
  await TestValidator.error("must reject missing/invalid admin")(async () => {
    await api.functional.shoppingMallAiBackend.admin.couponTemplates.search(anonymousConn, {
      body: { limit: 1 } satisfies IShoppingMallAiBackendCouponTemplate.IRequest,
    });
  });
}

