import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendComplianceEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendComplianceEvent";

/**
 * Validates the admin soft-delete (erase) workflow for a compliance event.
 *
 * This test simulates an admin creating a compliance event (such as a policy update or regulatory change),
 * followed by a soft-delete through the dedicated erase endpoint. It confirms:
 * 1. A compliance event can be created as admin
 * 2. The event can be soft-deleted using its unique id
 * 3. Repetitive soft-deletion attempts return an error or act as idempotent no-op
 *
 * Note: Since there is no available query/list/read endpoint for compliance events, validation is limited to the
 * available primitives (creation and deletion). We cannot programmatically verify exclusion from queries or
 * presence in an audit log beyond type-level and procedural assertions in this workflow.
 *
 * Steps:
 * 1. Create a compliance event and check that required fields are correctly registered
 * 2. Soft-delete the compliance event by id (should succeed)
 * 3. Attempt to delete the event again (should fail or no-op)
 */
export async function test_api_compliance_event_soft_delete_successful(connection: api.IConnection) {
  // 1. Create a compliance event as admin (prerequisite for deletion test)
  const createBody: IShoppingMallAiBackendComplianceEvent.ICreate = {
    event_type: "policy_update", // Simulate a typical event
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    actor_type: "admin",
    target_type: "user",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    event_payload: JSON.stringify({ change: "Update privacy policy", reason: "regulatory update" }),
  };
  const event = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
    body: createBody,
  });
  typia.assert(event);
  // Check that the event fields are registered properly
  TestValidator.equals("event_type matches")(event.event_type)(createBody.event_type);
  TestValidator.equals("actor_id matches")(event.actor_id)(createBody.actor_id);
  TestValidator.equals("actor_type matches")(event.actor_type)(createBody.actor_type);
  TestValidator.equals("target_type matches")(event.target_type)(createBody.target_type);
  TestValidator.equals("target_id matches")(event.target_id)(createBody.target_id);
  // Validate that event.id is properly formatted
  TestValidator.predicate("event.id is uuid")(!!event.id && /^([0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$/i.test(event.id));

  // 2. Soft delete the event using its id
  await api.functional.shoppingMallAiBackend.admin.complianceEvents.erase(connection, {
    complianceEventId: event.id,
  });

  // 3. Attempt to soft-delete again; should throw error or be a no-op depending on backend approach
  await TestValidator.error("soft-deleting a deleted compliance event should fail (or be a no-op)")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.complianceEvents.erase(connection, {
        complianceEventId: event.id,
      });
    }
  );
  // Note: No search/list/read endpoint exists--cannot programmatically validate exclusion from future queries
  // or presence/absence in audit logs. Limit validation to available API.
}

