/**
 * Ensure that non-admins cannot delete compliance events (permission denied).
 *
 * This test verifies that deletion of compliance events is strictly restricted to admin users. It follows these steps:
 *
 * 1. Create a compliance event via the admin API (dependency step).
 * 2. Remove admin authorization to simulate a non-admin or unauthenticated client.
 * 3. Attempt to delete the compliance event as a non-admin user.
 * 4. Confirm the API returns a permission error (such as 403 Forbidden).
 *
 * This is essential to enforce audit-log integrity and regulatory controls, ensuring only administrators manage compliance events.
 */
export async function test_api_compliance_event_soft_delete_forbidden_non_admin(
