/**
 * Validate that a seller can retrieve all review snapshots for a product review on their own product.
 *
 * This test covers the scenario where a seller wants to access the historical snapshots of a customer review left on one of their products. The process assumes the following workflow:
 *
 * 1. Register a new seller account via the registration endpoint. This acts as our seller principal and ensures isolated, fresh data.
 * 2. (SKIPPED - Product creation is NOT supported in provided DTOs/APIs)
 * 3. Simulate a customer review creation for the seller's product by calling the customer product review creation endpoint, passing valid product and order item IDs (randomly-generated for this test, since product/order creation is not exposed).
 * 4. Update the customer review to generate at least one historical snapshot by invoking the update endpoint for the product review (simulate at least one edit/change).
 * 5. As the (logged-in) seller, call the endpoint to fetch all review snapshots for the product review. Provide the product review ID and appropriate filter (review_id).
 * 6. Validate that the snapshot listing:
 *    - Is not empty (since at least one update has occurred)
 *    - Contains expected review_id matching the created review
 *    - The most recent snapshot reflects the updated content
 *
 * Notes:
 * - Actual product and order creation are omitted because their APIs/DTOs are not present; necessary foreign keys are supplied using valid UUIDs.
 * - The role/account switch for endpoints requiring seller/correct access is assumed via registration (no explicit login needed since the registration returns JWT/auth context for the connection).
 */
export async function test_api_seller_review_snapshots_for_owned_product_review(connection: api.IConnection) {
  // 1. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "TestPassword123!",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUp);

  // 2. Prepare fake product & order_item UUIDs (real creation not supported)
  const productId = typia.random<string & tags.Format<"uuid">>();
  const orderItemId = typia.random<string & tags.Format<"uuid">>();

  // 3. Simulate customer review creation for the seller's product
  const initialReview = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: productId,
      order_item_id: orderItemId,
      title: "Initial Title",
      body: "Review body for the first version.",
      rating: 4,
      status: "normal",
      ai_sentiment_score: 0.5,
      ai_spam_score: 0.1,
    } satisfies IShoppingMallAiBackendProductReview.ICreate,
  });
  typia.assert(initialReview);

  // 4. Update the review to generate a snapshot
  const updatedReview = await api.functional.shoppingMallAiBackend.customer.productReviews.update(connection, {
    productReviewId: initialReview.id,
    body: {
      title: "Updated Title",
      body: "Edited review body for audit.",
      rating: 5,
      status: "normal",
      ai_sentiment_score: 0.9,
      ai_spam_score: 0.0,
    } satisfies IShoppingMallAiBackendProductReview.IUpdate,
  });
  typia.assert(updatedReview);

  // 5. As the seller, fetch review snapshots
  const snapshotsPage = await api.functional.shoppingMallAiBackend.seller.productReviews.reviewSnapshots.search(connection, {
    productReviewId: initialReview.id,
    body: {
      review_id: initialReview.id,
    },
