 *
 * Steps:
 * 1. Log in as an admin via /auth/admin/login (obtain JWT for authorization)
 * 2. Create a new channel via /shoppingMallAiBackend/admin/channels (admin-only; extract created channelId)
 * 3. Immediately fetch details for the created channel via /shoppingMallAiBackend/admin/channels/{channelId}
 * 4. Assert all major fields are correct (code, name, status, logo_url, created_by_admin_id, created_at, etc.)
 */
export async function test_api_channel_detail_admin_success(connection: api.IConnection) {
  // 1. Log in as admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = "TestPassword!123";
  // This test expects a valid admin already exists with the given credentials, or that test DB/fixtures provisioning is in place.
  const auth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
