  // Apply Authorization: Bearer <token> for subsequent admin operations
  if (auth.setHeaders?.Authorization)
    connection.headers = { ...connection.headers, Authorization: auth.setHeaders.Authorization };
  else if (auth.jwt)
    connection.headers = { ...connection.headers, Authorization: `Bearer ${auth.jwt}` };

  // 2. Create a new channel
  const channelCode = RandomGenerator.alphaNumeric(10);
  const channelName = RandomGenerator.name();
  const channelLogo = `https://logo.example.com/${channelCode}.png`;
  const channelDescription = RandomGenerator.paragraph()();
  const createChannelInput = {
    code: channelCode,
    name: channelName,
    created_by_admin_id: auth.adminId,
    description: channelDescription,
    logo_url: channelLogo,
    active: true,
  } satisfies IShoppingMallAiBackendChannel.ICreate;
