  // 4. Assert all fields are correct
  TestValidator.equals("id matches")(detail.id)(createdChannel.id);
  TestValidator.equals("created_by_admin_id")(detail.created_by_admin_id)(auth.adminId);
  TestValidator.equals("name matches")(detail.name)(channelName);
  TestValidator.equals("code matches")(detail.code)(channelCode);
  TestValidator.equals("description matches")(detail.description)(channelDescription);
  TestValidator.equals("logo_url matches")(detail.logo_url)(channelLogo);
  TestValidator.equals("active matches")(detail.active)(true);
