/**
 * Validate error response for fetching details of a non-existent or soft-deleted channel as an admin.
 *
 * Business context:
 * In the admin interface of the shopping mall AI backend, it is critical that accessing the detail API for channels that do not exist or have been soft-deleted (not permanently removed) yields a compliant error (404 Not Found) and never exposes sensitive or residual business data. Admins need to ensure the system's audit log, data compliance, and privacy are preserved for such error cases.
 *
 * Step-by-step process:
 * 1. Log in as an admin using a known credential to ensure authorization for subsequent API calls.
 * 2. Attempt to get the details of a channel with a random UUID (which is guaranteed to not exist). Confirm that a 404 Not Found error is thrown, ensuring no channel data nor sensitive information is leaked in the response.
 * 3. Create a new channel using the admin ID obtained, and verify its creation.
 * 4. Soft-delete this channel (set deleted_at) via the provided admin API.
 * 5. After soft deletion, attempt to get channel details again (using its UUID). Assert that a 404 Not Found error is again thrown and that error compliance is maintained.
 * 6. Conclude that the system behavior in both non-existent and logically deleted channel cases is correct, and no sensitive data is revealed on error.
 */
export async function test_api_channel_detail_not_found_or_deleted(connection: api.IConnection) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "testPassword123!";
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);

  // 2. Try to get channel details for a random (non-existent) channelId
  const nonExistentChannelId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent channel yields 404 not found")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.channels.at(connection, {
        channelId: nonExistentChannelId,
      });
    }
  );

  // 3. Create a new channel (will be soft-deleted soon)
  const channel = await api.functional.shoppingMallAiBackend.admin.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      created_by_admin_id: adminAuth.adminId,
      active: true,
    } satisfies IShoppingMallAiBackendChannel.ICreate,
  });
  typia.assert(channel);

  // 4. Soft-delete the channel
  await api.functional.shoppingMallAiBackend.admin.channels.erase(connection, {
    channelId: channel.id,
  });

  // 5. Try to get the details for this now soft-deleted channel
  await TestValidator.error("soft-deleted channel yields 404 not found")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.channels.at(connection, {
        channelId: channel.id,
      });
    }
  );
}

