import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendFavoriteProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteProduct";
import type { IPageIShoppingMallAiBackendFavoriteProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendFavoriteProduct";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";

/**
 * Validate paginated, filtered retrieval, and security boundaries of a customer's favorite products.
 *
 * This scenario simulates all business and security flows for the /shoppingMallAiBackend/customer/favoriteProducts (PATCH) endpoint:
 * 1. Customer A registration and automatic authentication
 * 2. Admin creates three catalog products with random sellers
 * 3. Customer A favorites two of those products
 * 4. Retrieve favorites list with pagination, limiting to 1 per page; validate page boundaries and correctness
 * 5. Test product_id and date range filters to validate filtering
 * 6. Register and login as Customer B; confirm empty favorites for isolation
 * 7. Switch back and forth between customers; verify segregation of favorites
 * 8. Attempt list access without login; confirm proper denial (error thrown)
 *
 * All API responses are strictly type-asserted; random UUIDs and business data are used where required. The test checks data, pagination, and security correctness for both happy-path and security edge cases.
 */
export async function test_api_favorite_products_pagination_filtering_security(connection: api.IConnection) {
  // 1. Customer A registration (auto-authenticated, JWT in headers)
  const customerA_email: string = typia.random<string & tags.Format<"email">>();
  const customerA_password: string = RandomGenerator.alphaNumeric(10);
  const customerA_nickname: string = RandomGenerator.alphaNumeric(8);
  const customerA_phone: string = RandomGenerator.mobile();
  const customerA_register = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerA_email,
      password: customerA_password,
      name: RandomGenerator.name(),
      nickname: customerA_nickname,
      phone: customerA_phone
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerA_register);
  const customerA = customerA_register.customer;

  // 2. Admin creates 3 products assigned to synthetic (random) sellers
  const syntheticSellerIds = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const createdProducts = await ArrayUtil.asyncMap(syntheticSellerIds)(async (sellerId, idx) =>
    await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
      body: {
        seller_id: sellerId,
        code: RandomGenerator.alphaNumeric(12) + idx,
        name: RandomGenerator.paragraph()(1),
        description: RandomGenerator.content()()(1),
        main_image_uri: null,
        status: "published"
      } satisfies IShoppingMallAiBackendProduct.ICreate
    })
  );
  typia.assert(createdProducts);

  // 3. Customer A favorites first and last product
  for (const productIdx of [0, 2]) {
    const favoriteOut = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
      body: {
        product_id: createdProducts[productIdx].id
      } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate
    });
    typia.assert(favoriteOut);
  }

  // 4. Retrieve favorites paginated (page=1, limit=1), expect only 1 on first page, correct pagination metadata
  let favoritesPage1 = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: {
      page: 1,
      limit: 1
    }
  });
  typia.assert(favoritesPage1);
  TestValidator.equals("favorites pagination page 1")(favoritesPage1.pagination.current)(1);
  TestValidator.equals("limit")(favoritesPage1.pagination.limit)(1);
  TestValidator.predicate("should have at least 1 favorite")(favoritesPage1.data.length >= 1);

  // Validate product_id of favorite matches first or last product
  TestValidator.predicate("product id matches favorited item")(
    createdProducts
      .map(p => p.id)
      .includes(favoritesPage1.data[0].product_id)
  );

  // 5. Retrieve page 2, verify record count
  let favoritesPage2 = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: {
      page: 2,
      limit: 1
    }
  });
  typia.assert(favoritesPage2);
  TestValidator.equals("favorites pagination page 2")(favoritesPage2.pagination.current)(2);
  TestValidator.equals("limit")(favoritesPage2.pagination.limit)(1);
  TestValidator.predicate("should have at least 1 favorite")(favoritesPage2.data.length >= 1);

  TestValidator.equals("pagination record count")(favoritesPage1.pagination.records + favoritesPage2.pagination.records)(favoritesPage2.pagination.records * 2);

  // 6. Filter by specific product_id
  for (const selected of [0, 2]) {
    let filtered = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
      body: {
        product_id: createdProducts[selected].id
      }
    });
    typia.assert(filtered);
    TestValidator.predicate("filtered data has correct product")(
      filtered.data.every(fav => fav.product_id === createdProducts[selected].id)
    );
  }

  // 7. Filter by favorited date (from_date = now -10m, to_date = now)
  const fromDate = new Date(Date.now() - 10 * 60 * 1000).toISOString();
  const toDate = new Date().toISOString();
  const filteredByDate = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: {
      from_date: fromDate,
      to_date: toDate
    }
  });
  typia.assert(filteredByDate);
  TestValidator.predicate("all favorites within date range")(
    filteredByDate.data.every(fav => fav.created_at >= fromDate && fav.created_at <= toDate)
  );

  // 8. Register and authenticate Customer B
  const customerB_email: string = typia.random<string & tags.Format<"email">>();
  const customerB_password: string = RandomGenerator.alphaNumeric(10);
  const customerB_nickname: string = RandomGenerator.alphaNumeric(8);
  const customerB_phone: string = RandomGenerator.mobile();
  const customerB_register = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerB_email,
      password: customerB_password,
      name: RandomGenerator.name(),
      nickname: customerB_nickname,
      phone: customerB_phone
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerB_register);

  // 9. Authenticate as Customer B
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerB_email,
      password: customerB_password
    } satisfies ICustomerSignIn.Request
  });

  // 10. Customer B - retrieve favorites (should be empty)
  const customerB_favorites = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: {}
  });
  typia.assert(customerB_favorites);
  TestValidator.equals("customer B has no favorites")(customerB_favorites.data.length)(0);

  // 11. Switch back to Customer A via login
  await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerA_email,
      password: customerA_password
    } satisfies ICustomerSignIn.Request
  });

  // 12. Retrieve A's favorites - ensure visible again
  const revisitA_favorites = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(connection, {
    body: {}
  });
  typia.assert(revisitA_favorites);
  TestValidator.predicate("customer A sees their favorites again")(revisitA_favorites.data.length >= 2);

  // 13. Clear Authorization and verify request fails (security - unauthorized)
  const headers = connection.headers ?? {};
  const { Authorization, ...headersWithoutAuth } = headers;
  const unauthConn = { ...connection, headers: headersWithoutAuth };
  await TestValidator.error("unauthorized fails")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteProducts.search(unauthConn, {
      body: {}
    })
  );
}

