import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Product inquiry detail view by the customer owner (happy & negative path).
 *
 * Validates that a customer who owns a product inquiry can fetch its complete detail via the dedicated GET endpoint.
 * Also tests error paths: retrieving with a non-existent productInquiryId and attempting access to an inquiry belonging to another customer.
 * Covers privacy, field-level access, and expected audit trail triggers for compliance.
 *
 * 1. Register a new customer and authenticate (obtain token).
 * 2. Create a product inquiry for this customer (the one that will be fetched).
 * 3. Use the GET-by-id endpoint with correct productInquiryId as the owner customer.
 *    - Assert all fields present, expected field privacy, and compliance with IShoppingMallAiBackendProductInquiry definition.
 * 4. Try GET with a random/non-existent productInquiryId – expect 404 or similar error.
 * 5. Register a second customer and attempt to access the first customer's inquiry – expect 403/404 as per privacy rules.
 */
export async function test_api_product_inquiry_detail_view_by_owner(
  connection: api.IConnection,
) {
  // 1. Register and authenticate the first customer (inquiry owner)
  const customerReg1Email: string = typia.random<string & tags.Format<"email">>();
  const customerReg1Request: ICustomerSignUp.Request = {
    email: customerReg1Email,
    password: "1234!qwer",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const register1 = await api.functional.auth.customer.register.signUp(connection, {
    body: customerReg1Request,
  });
  typia.assert(register1);
  const customer1 = register1.customer;
  // By contract, token is already in connection

  // 2. Create a product inquiry for the first customer
  const productId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const inquiryCreate: IShoppingMallAiBackendProductInquiry.ICreate = {
    customer_id: customer1.id,
    product_id: productId,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(),
    public: true,
  };
  const createdInquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: inquiryCreate,
  });
  typia.assert(createdInquiry);
  TestValidator.equals("created inquiry belongs to customer1")(createdInquiry.customer_id)(customer1.id);
  TestValidator.equals("product id matches")(createdInquiry.product_id)(productId);
  TestValidator.equals("inquiry title matches")(createdInquiry.title)(inquiryCreate.title);
  TestValidator.equals("inquiry body matches")(createdInquiry.body)(inquiryCreate.body);
  TestValidator.equals("public flag matches")(createdInquiry.public)(inquiryCreate.public);
  TestValidator.equals("status initialized")(createdInquiry.status)("waiting"); // Status may default to 'waiting'
  TestValidator.predicate("created_at set")(!!createdInquiry.created_at && typeof createdInquiry.created_at === "string");
  TestValidator.predicate("updated_at set")(!!createdInquiry.updated_at && typeof createdInquiry.updated_at === "string");
  typia.assert<IShoppingMallAiBackendProductInquiry>(createdInquiry);

  // 3. Fetch inquiry by id as owner
  const fetchedInquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.at(connection, {
    productInquiryId: createdInquiry.id,
  });
  typia.assert(fetchedInquiry);
  TestValidator.equals("fetched inquiry same as created")(fetchedInquiry)(createdInquiry);
  // Spot field privacy: as owner, all fields should be present and match spec
  TestValidator.equals("owner sees customer_id")(fetchedInquiry.customer_id)(customer1.id);
  TestValidator.equals("owner sees product_id")(fetchedInquiry.product_id)(productId);
  TestValidator.equals("title matches")(fetchedInquiry.title)(inquiryCreate.title);
  TestValidator.equals("body matches")(fetchedInquiry.body)(inquiryCreate.body);
  TestValidator.equals("public matches")(fetchedInquiry.public)(true);
  TestValidator.equals("status matches")(fetchedInquiry.status)("waiting");
  // AI/optional fields: may be null/undefined at this stage
  TestValidator.predicate("AI fields type")(
    typeof fetchedInquiry.ai_sentiment_score === "number" || fetchedInquiry.ai_sentiment_score == null
  );
  TestValidator.predicate("AI spam score type")(
    typeof fetchedInquiry.ai_spam_score === "number" || fetchedInquiry.ai_spam_score == null
  );

  // 4. Try to fetch a non-existent inquiry ID
  await TestValidator.error("non-existent inquiry should error")(async () => {
    await api.functional.shoppingMallAiBackend.customer.productInquiries.at(connection, {
      productInquiryId: typia.random<string & tags.Format<"uuid">>()
    });
  });

  // 5. Register a second customer and verify privacy enforcement
  const customerReg2Email: string = typia.random<string & tags.Format<"email">>();
  const customerReg2Request: ICustomerSignUp.Request = {
    email: customerReg2Email,
    password: "1234!asdf",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const register2 = await api.functional.auth.customer.register.signUp(connection, {
    body: customerReg2Request,
  });
  typia.assert(register2);
  // Token auto-switched in connection

  // Attempt by customer2 to access inquiry owned by customer1
  await TestValidator.error("other customer forbidden from fetching")(async () => {
    await api.functional.shoppingMallAiBackend.customer.productInquiries.at(connection, {
      productInquiryId: createdInquiry.id,
    });
  });
}

