import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate successful admin password change with end-to-end workflow.
 *
 * This test ensures the password change endpoint for admins works end-to-end—the workflow includes registering a new admin, authenticating, changing password using the valid current password and a strong new password, then validating that authentication with the new password works and the old password is invalidated.
 *
 * Steps:
 * 1. Register a new admin using /auth/admin/register.
 * 2. Log in as the newly registered admin (establish session) using /auth/admin/login.
 * 3. Change the password via /auth/admin/password using the correct (current) password and a new secure password.
 * 4. Validate successful response (success: true, informative message).
 * 5. Assert that authentication using the OLD password fails (login should error).
 * 6. Assert that authentication with the NEW password now succeeds (new valid JWT/profile returned).
 *
 * The test ensures security best-practices: old sessions and passwords cannot be re-used, and password change is properly processed and enforced.
 */
export async function test_api_admin_auth_change_password_success(connection: api.IConnection) {
  // 1. Register a new admin
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = "Admin@1234!" + RandomGenerator.alphaNumeric(4);
  const newPassword: string = "NewAdmin@5678!" + RandomGenerator.alphaNumeric(4);

  // Register admin
  const registration = await api.functional.auth.admin.register.signUp(connection, {
    body: { email, password } satisfies IAdminAuth.SignUp
  });
  typia.assert(registration);
  TestValidator.equals("registered email matches")(registration.email)(email);

  // 2. Log in as the registered admin (OBTAIN JWT, set headers)
  const login = await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IAdminAuth.SignIn
  });
  typia.assert(login);
  TestValidator.equals("login email matches")(login.email)(email);

  // 3. Change password with correct current password
  const changeResult = await api.functional.auth.admin.password.changePassword(connection, {
    body: {
      currentPassword: password,
      newPassword,
    } satisfies IAdminAuth.ChangePassword
  });
  typia.assert(changeResult);
  TestValidator.equals("password change success")(changeResult.success)(true);

  // 4. OLD password authentication should now fail
  await TestValidator.error("old password login should fail")(async () => {
    await api.functional.auth.admin.login.signIn(connection, {
      body: { email, password } satisfies IAdminAuth.SignIn
    });
  });

