}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteInquiry";
import type { IPageIShoppingMallAiBackendFavoriteInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendFavoriteInquiry";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate search and pagination of favorite inquiries for a customer.
 *
 * This test covers:
 *   - Default and filtered search results for a customer's favorite inquiries
 *   - Pagination (page/limit) and multi-page handling
 *   - Authorization: ensures only favorites of authenticated customer are found
 *   - Soft-delete edge: verified only indirectly as SDK lacks explicit unfavorite
 *   - Limits/edges: empty sets and invalid filter/pagination
 *
 * Steps:
 * 1. Favorite three random inquiries for this user.
 * 2. Search all favorites, verify all are present and not deleted.
 * 3. Search with specific filters (inquiry_id, from/to date, query)
 * 4. Test pagination: page=1/2 and limit
 * 5. Test edge: out-of-bounds pagination and nonsense filter
 * 6. Note: true soft-delete or user switching not implementable with SDK.
 */
export async function test_api_favorite_inquiry_search_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create three favorite inquiries for this customer
  const favorite1 = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.create(connection, {
    body: { inquiry_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(favorite1);

  const favorite2 = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.create(connection, {
    body: { inquiry_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(favorite2);

  const favorite3 = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.create(connection, {
    body: { inquiry_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(favorite3);

  // Step 2: Basic search with no filters: all favorites for user
  const allPage = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.search(connection, {
    body: {} satisfies IShoppingMallAiBackendFavoriteInquiry.IRequest,
  });
  typia.assert(allPage);
  const ids = [favorite1.id, favorite2.id, favorite3.id];
  ids.forEach(id =>
    TestValidator.predicate(`favorite id ${id} is present and not deleted`)(
      allPage.data.some(x => x.id === id && !x.deleted_at),
    ),
  );

  // Step 3: Filtered search
  // (a) By inquiry_id
  {
    const byId = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.search(connection, {
      body: { inquiry_id: favorite2.inquiry_id },
    });
    typia.assert(byId);
    TestValidator.equals("single match by inquiry_id")(byId.data.length)(1);
    TestValidator.equals("correct favorite returned")(byId.data[0].id)(favorite2.id);
  }
  // (b) By date range (from and to date)
  {
    const fromDate = favorite1.created_at;
    const toDate = favorite3.created_at;
    const byDate = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.search(connection, {
      body: { from_date: fromDate, to_date: toDate },
    });
    typia.assert(byDate);
    ids.forEach(id =>
      TestValidator.predicate(`favorite id ${id} within date range`)(
        byDate.data.some(x => x.id === id),
      ),
    );
  }
  // (c) By query
  {
    const byQuery = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.search(connection, {
      body: { query: "irrelevant-test-query" },
    });
    typia.assert(byQuery);
    // No assertion: no way to correlate result with query content
  }

  // Step 4: Pagination
  {
    const page1 = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.search(connection, {
      body: { page: 1, limit: 2 },
    });
    typia.assert(page1);
    TestValidator.equals("2 records on page 1")(page1.data.length)(2);

    const page2 = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.search(connection, {
      body: { page: 2, limit: 2 },
    });
    typia.assert(page2);
    TestValidator.predicate("at most 1 record on page 2")(page2.data.length <= 1);
  }

  // Step 5: Invalid filters/edge: out-of-bounds pagination and nonsense inquiry_id
  {
    // Out-of-bounds: page too high
    const emptyPage = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.search(connection, {
      body: { page: 1000, limit: 1 },
    });
    typia.assert(emptyPage);
    TestValidator.equals("empty result for invalid page")(emptyPage.data.length)(0);
  }
  {
    // Nonsense inquiry_id
    const missing = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.search(connection, {
      body: { inquiry_id: typia.random<string & tags.Format<"uuid">>() },
    });
    typia.assert(missing);
    TestValidator.equals("no match for bogus inquiry_id")(missing.data.length)(0);
  }
  // Note: explicit unfavorite and user switching cannot be tested due to lack of appropriate API support.
}

