  TestValidator.equals("item product id")(orderItem.product_id)(
    itemCreate.product_id,
  );
  TestValidator.equals("item quantity")(orderItem.quantity)(itemCreate.quantity);
  TestValidator.equals("item unit price")(orderItem.unit_price)(
    itemCreate.unit_price,
  );
  TestValidator.equals("item currency code")(orderItem.currency_code)(
    itemCreate.currency_code,
  );

  // 5. Retrieve the item details as the customer
  const detail =
    await api.functional.shoppingMallAiBackend.customer.orders.orderItems.at(
      connection,
      {
        orderId: order.id,
        orderItemId: orderItem.id,
      },
    );
