  TestValidator.equals("retrieved order item id")(detail.id)(orderItem.id);
  TestValidator.equals("retrieved order id")(detail.order_id)(order.id);
  TestValidator.equals("retrieved product id")(detail.product_id)(
    itemCreate.product_id,
  );
  TestValidator.equals("retrieved quantity")(detail.quantity)(itemCreate.quantity);
  TestValidator.equals("retrieved unit price")(detail.unit_price)(itemCreate.unit_price);
  TestValidator.equals("retrieved currency code")(detail.currency_code)(
    itemCreate.currency_code,
  );
}

