import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderItem";

/**
 * Test that adding an order item as an unauthenticated customer is forbidden.
 *
 * Business context:
 * Order item creation must be protected so only properly authenticated customers can add items to their orders. This verifies backend security by ensuring unauthenticated requests cannot mutate order data, preventing privilege escalation and data leakage.
 *
 * Step-by-step process:
 * 1. Create a valid customer order as an authenticated user (to obtain a real orderId for the test, using connection with auth).
 * 2. Remove authentication from the connection (simulate no JWT or customer token).
 * 3. Attempt to create an order item for the above orderId using valid item data but the unauthenticated connection.
 * 4. Assert that the server denies the operation, throwing an authentication or authorization error – confirming proper security.
 */
export async function test_api_order_item_add_unauthorized_customer(connection: api.IConnection) {
  // 1. Create a customer order while authenticated (to get a valid orderId for the test)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const orderCreate = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
      order_number: RandomGenerator.alphaNumeric(12),
      total_amount: 10000,
      currency_code: "USD",
      current_status: "created",
      // note and order_group_id are optional and may be omitted
    } satisfies IShoppingMallAiBackendOrder.ICreate
  });
  typia.assert(orderCreate);

  // 2. Remove authentication: Make a copy of the connection with an empty headers object
  const unauthenticatedConnection = { ...connection, headers: {} };

  // 3. Attempt to add an order item as an unauthenticated customer (should fail)
  await TestValidator.error("Adding order item unauthorized")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderItems.create(
        unauthenticatedConnection,
        {
          orderId: orderCreate.id,
          body: {
            order_id: orderCreate.id,
            product_id: typia.random<string & tags.Format<"uuid">>(),
            product_snapshot_id: typia.random<string & tags.Format<"uuid">>(),
            quantity: 1,
            unit_price: 1000,
            currency_code: "USD"
            // note is optional
          } satisfies IShoppingMallAiBackendOrderItem.ICreate
        }
      );
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderItem";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that an administrator can directly add an order item to another customer's order via the privileged endpoint.
 *
 * Business context:
 * In many e-commerce or order management systems, administrators sometimes need the capability to modify customer orders on behalf of users. This includes the ability to add order items to an existing customer order, regardless of ownership. This test ensures that the endpoint for admin item insertion is functional, honors authentication, and preserves data relationships.
 *
 * Steps:
 * 1. Register a new admin. Capture credentials for later login.
 * 2. Login as the admin to obtain a JWT for privileged actions.
 * 3. Register a customer who will own the target order.
 * 4. Login as the customer and create a new order on their behalf.
 * 5. Login again as the admin (updates the Authorization header) in order to execute admin-level POST to add order item to the customer order.
 * 6. Use the admin order item API to insert a new item for the customer's order with random product/snapshot IDs, realistic quantity/price/currency.
 * 7. Validate that the returned order item is type-correct and that its order_id matches the customer's order.
 */
export async function test_api_order_item_add_by_admin_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "Adm1n!Passw0rd";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as the admin (ensures connection uses admin JWT for subsequent requests)
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);

  // 3. Register a new customer
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerPassword: string = "Custom3r!Pa55";
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUp);
  const customerId: string & tags.Format<"uuid"> = customerSignUp.customer.id;

  // 4. Login as the customer
  const customerSignIn = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    } satisfies ICustomerSignIn.Request,
  });
  typia.assert(customerSignIn);

  // 5. Customer creates a new order
  const orderNumber = `ORD-${new Date().getTime()}`;
  const currency = "USD";
  const orderCreate = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
      order_number: orderNumber,
      total_amount: typia.random<number>(),
      currency_code: currency,
      note: null,
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(orderCreate);
  const orderId: string & tags.Format<"uuid"> = orderCreate.id;

  // 6. Login back as admin to get admin JWT (overwrites session)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  // (No need to assert - JWT will be in connection for next request)

  // 7. Admin adds an order item to the customer's order
  const newProductId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const newProductSnapshotId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const orderItemCreate = await api.functional.shoppingMallAiBackend.admin.orders.orderItems.create(connection, {
    orderId: orderId,
    body: {
      order_id: orderId,
      product_id: newProductId,
      product_snapshot_id: newProductSnapshotId,
      quantity: typia.random<number & tags.Type<"int32">>(),
      unit_price: typia.random<number>(),
      currency_code: currency,
      note: null,
    } satisfies IShoppingMallAiBackendOrderItem.ICreate,
  });
  typia.assert(orderItemCreate);
  // Validate that the created order item is bound to the intended customer's order
  TestValidator.equals("order_id properly set")(orderItemCreate.order_id)(orderId);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderItem";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that adding an order item with invalid references fails as expected (admin endpoint).
 *
 * This test ensures system integrity by confirming that an admin cannot attach an order item with references to a nonexistent product or product_snapshot, which would break relational and audit integrity.
 * The business workflow being tested is full RBAC admin interaction: registration, authentication, and use of protected CRUD endpoints.
 *
 * Step-by-step process:
 * 1. Register a new admin, then login to obtain JWT/Authorization for privileged endpoints
 * 2. Register a new customer, then login as the customer and create an order (orderId is thus real & valid)
 * 3. Switch back to admin account (login)
 * 4. Attempt to add a new order item to the existing order using a fake/nonexistent product_id and product_snapshot_id value (random UUIDs)
 * 5. Confirm this operation fails (should throw error: validation error or not found)
 */
export async function test_api_order_item_add_by_admin_invalid_references(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin123!";
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword }
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword }
  });

  // 3. Register customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Customer123!";
  const customerSignUpRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile()
    }
  });
  typia.assert(customerSignUpRes);

  // 4. Login as customer
  await api.functional.auth.customer.login.signIn(connection, {
    body: { email: customerEmail, password: customerPassword }
  });

  // 5. Create a customer order
  const orderReq: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customerSignUpRes.customer.id,
    order_number: RandomGenerator.alphaNumeric(12),
    total_amount: 10000,
    currency_code: "USD",
    current_status: "created"
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderReq });
  typia.assert(order);

  // 6. Switch back to admin account
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword }
  });

  // 7. Attempt to add an invalid order item with fake product_id and snapshot_id (should fail)
  const invalidOrderItem: IShoppingMallAiBackendOrderItem.ICreate = {
    order_id: order.id,
    product_id: typia.random<string & tags.Format<"uuid">>(),
    product_snapshot_id: typia.random<string & tags.Format<"uuid">>(),
    quantity: 1,
    unit_price: 1000,
    currency_code: "USD"
  };
  await TestValidator.error("should fail for invalid product references")(
    () => api.functional.shoppingMallAiBackend.admin.orders.orderItems.create(connection, {
      orderId: order.id,
      body: invalidOrderItem
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponSnapshot";
import type { IPageIShoppingMallAiBackendCouponSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCouponSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test retrieval of coupon snapshots with advanced filtering and pagination as an admin.
 *
 * Business context:
 * Admins must audit and review coupon lifecycle operations through filtered lists of coupon snapshot records.
 * Critical queries include filtering by coupon template code, date range, status, and paginating through potentially large audit logs.
 * Only admin-role users should be allowed access; unauthorized or malformed requests must be rejected appropriately.
 *
 * Test Steps:
 * 1. Authenticate as a valid admin user via /auth/admin/login to obtain the JWT and set Authorization headers.
 * 2. Request coupon snapshots with a variety of valid advanced filters and pagination parameters:
 *    - Filter by coupon_template_code (expect records with matching code)
 *    - Filter by status (expect records with matching status)
 *    - Filter by created_at_from and created_at_to range (date window)
 *    - Use pagination: test first page, last page, and page sizes
 *    - Combine multiple filters for intersectional subsets
 * 3. Validate for each successful query that returned rows strictly match the filter criteria and paging info is correct.
 * 4. Send a query that would return an empty result (e.g., nonexistent coupon_template_code), check that data is an empty array and pagination is still correct.
 * 5. Simulate a large set by requesting a small 'limit' and page through results (if possible—skip if not enough sample data).
 * 6. Submit a purposely malformed query (e.g., non-uuid value for issued_coupon_id, negative page/limit) and confirm error is thrown.
 * 7. Attempt coupon snapshot search with a non-admin connection or missing/invalid token and confirm access is denied.
 */
export async function test_api_coupon_snapshot_admin_list_success_with_advanced_filters(connection: api.IConnection) {
  // 1. Authenticate as admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "Password!234";
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // Automatically store Authorization header in connection.headers

  // 2. Valid filter: by coupon_template_code
  const filterCode = "TEST-TEMPLATE";
  const resByTemplate = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.search(connection, {
    body: {
      coupon_template_code: filterCode,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(resByTemplate);
  resByTemplate.data.forEach(r => {
    TestValidator.equals("template code matches")(r.coupon_template_code)(filterCode);
  });

  // Valid filter: by status
  const statusFilter = "issued";
  const resByStatus = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.search(connection, {
    body: {
      status: statusFilter,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(resByStatus);
  resByStatus.data.forEach(r => {
    TestValidator.equals("status matches")(r.status)(statusFilter);
  });

  // Valid filter: by created_at_from/to
  const from = new Date(Date.now() - 1000 * 60 * 60 * 24 * 7).toISOString();
  const to = new Date().toISOString();
  const resByDate = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.search(connection, {
    body: {
      created_at_from: from,
      created_at_to: to,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(resByDate);
  resByDate.data.forEach(r => {
    TestValidator.predicate("created_at in range")(r.created_at >= from && r.created_at <= to);
  });

  // Pagination/large result set (assume sample data returned)
  const pagingSmall = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.search(connection, {
    body: {
      page: 1,
      limit: 2,
    },
  });
  typia.assert(pagingSmall);
  TestValidator.equals("page number")(pagingSmall.pagination.current)(1);
  TestValidator.equals("page limit")(pagingSmall.pagination.limit)(2);
  // If there are more pages, fetch next page
  if (pagingSmall.pagination.pages > 1) {
    const pagingNext = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.search(connection, {
      body: {
        page: 2,
        limit: 2,
      },
    });
    typia.assert(pagingNext);
    TestValidator.equals("next page")(pagingNext.pagination.current)(2);
  }

  // 4. Query for empty results
  const noneRes = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.search(connection, {
    body: {
      coupon_template_code: "NO_SUCH_TEMPLATE_CODE",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(noneRes);
  TestValidator.equals("empty array for missing template code")(noneRes.data.length)(0);

  // 5. Error: malformed issued_coupon_id (not uuid)
  await TestValidator.error("malformed issued_coupon_id")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.couponSnapshots.search(connection, {
        body: {
          issued_coupon_id: "not-a-uuid",
          page: 1,
          limit: 10,
        },
      });
    },
  );
  // Error: negative limit
  await TestValidator.error("negative limit is error")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.couponSnapshots.search(connection, {
        body: {
          page: 1,
          limit: -5,
        },
      });
    },
  );

  // 6. Unauthorized access (non-admin/missing token)
  // Temporarily drop Authorization header (simulate unauthenticated)
  const withoutAuth = { ...connection, headers: { ...connection.headers } };
  delete withoutAuth.headers["Authorization"];
  await TestValidator.error("unauthorized without admin token")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.couponSnapshots.search(withoutAuth, {
        body: {
          page: 1,
          limit: 5,
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCouponSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponSnapshot";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin-only access for fetching coupon snapshot details.
 *
 * This test checks the following scenarios:
 * 1. Admin user can successfully fetch an existing coupon snapshot by UUID and receives full details (where available).
 * 2. Fetching with a random/non-existent (or deleted) UUID should result in a not-found error.
 * 3. Only authenticated admin users may access this endpoint; unauthenticated requests (missing Authorization) must be denied.
 *
 * Steps:
 * 1. Authenticate as admin via POST /auth/admin/login and obtain JWT/session.
 * 2. Attempt to fetch a non-existent coupon snapshot (random UUID) — expect not found error.
 * 3. (Optional/integrated) Attempt to fetch a snapshot by a known ID — result may vary if no snapshot exists; validate response if returned.
 * 4. Simulate access without admin authorization header; endpoint access should be rejected.
 */
export async function test_api_coupon_snapshot_admin_detail_access_and_not_found(connection: api.IConnection) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "test_password";
  const login = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(login);

  // 2. Attempt to fetch non-existent coupon snapshot by random UUID
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existing coupon snapshot should result in error")(() =>
    api.functional.shoppingMallAiBackend.admin.couponSnapshots.at(connection, {
      couponSnapshotId: randomId,
    })
  );

  // 3. Attempt to fetch with a (simulated) known/valid coupon snapshot ID
  // Since snapshot creation API is unavailable here, simulate with random DTO instance
  const sampleSnapshot = typia.random<IShoppingMallAiBackendCouponSnapshot>();
  try {
    const output = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.at(connection, {
      couponSnapshotId: sampleSnapshot.id,
    });
    typia.assert(output);
  } catch {
    // Acceptable: snapshot may not exist
  }

  // 4. Attempt endpoint access with missing Authorization header (unauthenticated)
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers.Authorization;
  await TestValidator.error("accessing as unauthenticated user must fail")(() =>
    api.functional.shoppingMallAiBackend.admin.couponSnapshots.at(unauthConnection, {
      couponSnapshotId: randomId,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendIssuedCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendIssuedCoupon";
import type { IShoppingMallAiBackendCouponSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCouponSnapshot";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate creation of a new coupon snapshot as an admin—success, duplicate, and input error cases.
 *
 * Business context:
 * Coupon snapshots serve auditing, rollback, and compliance tracking in the system. Only admins can create snapshots, which must reference real, issued coupons and reflect coupon state history at the time of key events.
 *
 * Steps:
 * 1. Admin login—obtain JWT to enable admin-only coupon snapshot actions.
 * 2. Issue a coupon (creates valid reference data).
 * 3. Create a valid coupon snapshot (expect success).
 * 4. Attempt to create a duplicate snapshot (expect validation/conflict error).
 * 5. Attempt to create a snapshot for a fake/non-existent issued coupon (expect error).
 * 6. Edge: Attempt to create a snapshot with a purposely invalid required field (expect business validation error, but always provide all required fields).
 */
export async function test_api_coupon_snapshot_creation_success_and_duplicate(
  connection: api.IConnection,
) {
  // 1. Admin login (credentials assumed to exist in test env)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestSecure!P@ss1";
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);
  // JWT/Authorization is managed in the connection by SDK

  // 2. Issue a new coupon (get a valid coupon to snapshot)
  const issuedCoupon = await api.functional.shoppingMallAiBackend.admin.issuedCoupons.create(connection, {
    body: {
      coupon_template_id: typia.random<string & tags.Format<"uuid">>(),
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      code: "CPN-" + typia.random<string>(),
      expires_at: new Date(Date.now() + 7 * 86400 * 1000).toISOString(),
      status: "issued",
    } satisfies IShoppingMallAiBackendIssuedCoupon.ICreate,
  });
  typia.assert(issuedCoupon);

  // 3. Create a valid coupon snapshot
  const snapshotInput: IShoppingMallAiBackendCouponSnapshot.ICreate = {
    issued_coupon_id: issuedCoupon.id,
    coupon_template_code: "TEMPLATE-" + typia.random<string>(),
    issued_coupon_code: issuedCoupon.code,
    customer_id: issuedCoupon.customer_id,
    status: issuedCoupon.status,
    valid_from: issuedCoupon.issued_at,
    valid_until: issuedCoupon.expires_at,
    action: "issued",
  };

  const createdSnapshot = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, {
    body: snapshotInput,
  });
  typia.assert(createdSnapshot);
  TestValidator.equals("issued_coupon_id matches")(createdSnapshot.issued_coupon_id)(snapshotInput.issued_coupon_id);
  TestValidator.equals("coupon_template_code")(createdSnapshot.coupon_template_code)(snapshotInput.coupon_template_code);
  TestValidator.equals("issued_coupon_code")(createdSnapshot.issued_coupon_code)(snapshotInput.issued_coupon_code);
  TestValidator.equals("customer_id")(createdSnapshot.customer_id)(snapshotInput.customer_id);
  TestValidator.equals("status")(createdSnapshot.status)(snapshotInput.status);
  TestValidator.equals("valid_from")(createdSnapshot.valid_from)(snapshotInput.valid_from);
  TestValidator.equals("valid_until")(createdSnapshot.valid_until)(snapshotInput.valid_until);
  TestValidator.equals("action")(createdSnapshot.action)(snapshotInput.action);

  // 4. Duplicate snapshot (same reference data)
