 *
 * This test checks the admin update functionality for coupon snapshot records. It performs the following:
 *
 * 1. Admin authentication: Signs in as an admin to obtain JWT authorization for subsequent requests.
 * 2. Coupon snapshot creation: Creates a valid coupon snapshot that will serve as the target for update tests.
 * 3. Successful update: Updates mutable field(s) of the snapshot (only 'action' is updatable) and asserts success and field change.
 * 4. Non-existent snapshot: Tries updating a random UUID (non-existent) and expects error.
 * 5. Forbidden mutation by schema: Only 'action' can be updated (enforced by DTO/schema), so forbidden mutation of immutable/evidence fields cannot be tested at runtime. This is enforced at the type level.
 * 6. Audit logging not testable (no audit log API or feedback in SDK/type).
 */
export async function test_api_coupon_snapshot_update_fields_as_admin(
  connection: api.IConnection,
) {
  // 1. Admin authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongP@ssw0rd"; // strong password for test purpose
  const login = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(login);

  // 2. Coupon snapshot creation
  const couponSnapshotInput: IShoppingMallAiBackendCouponSnapshot.ICreate = {
    issued_coupon_id: typia.random<string & tags.Format<"uuid">>(),
    coupon_template_code: RandomGenerator.alphabets(10),
    issued_coupon_code: RandomGenerator.alphaNumeric(12),
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    status: "active",
    valid_from: new Date().toISOString(),
    valid_until: new Date(Date.now() + 1000 * 60 * 60 * 24 * 30).toISOString(),
    action: "issued",
  };
  const createdSnapshot = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.create(connection, {
    body: couponSnapshotInput,
  });
  typia.assert(createdSnapshot);
  TestValidator.equals("action before update")(createdSnapshot.action)("issued");

  // 3. Successful update: update allowed field (action)
  const updateBody: IShoppingMallAiBackendCouponSnapshot.IUpdate = {
    action: "updated-by-admin",
  };
  const updated = await api.functional.shoppingMallAiBackend.admin.couponSnapshots.update(connection, {
    couponSnapshotId: createdSnapshot.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("action updated")(updated.action)("updated-by-admin");
  // Confirm all immutable fields remain unchanged
  TestValidator.equals("immutable: issued_coupon_id")(updated.issued_coupon_id)(createdSnapshot.issued_coupon_id);
  TestValidator.equals("immutable: coupon_template_code")(updated.coupon_template_code)(createdSnapshot.coupon_template_code);
  TestValidator.equals("immutable: issued_coupon_code")(updated.issued_coupon_code)(createdSnapshot.issued_coupon_code);
  TestValidator.equals("immutable: customer_id")(updated.customer_id)(createdSnapshot.customer_id);
  TestValidator.equals("immutable: status")(updated.status)(createdSnapshot.status);
  TestValidator.equals("immutable: valid_from")(updated.valid_from)(createdSnapshot.valid_from);
  TestValidator.equals("immutable: valid_until")(updated.valid_until)(createdSnapshot.valid_until);
  TestValidator.equals("immutable: created_at")(typeof updated.created_at === "string")(true);

  // 4. Non-existent snapshot update should fail (random UUID)
  await TestValidator.error("update non-existent snapshot fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.couponSnapshots.update(connection, {
        couponSnapshotId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          action: "should-fail",
        },
      });
    },
  );

  // 5. Forbidden mutation of immutable fields: The schema only allows 'action' in update body.
  // Attempting to set any other field will cause compile error—test omitted as it's statically prevented.
  // 6. Audit log verification not possible (no API feedback or log endpoint).
}

