      status: "normal",
      ai_sentiment_score: 0.7,
      ai_spam_score: 0.1,
    } satisfies IShoppingMallAiBackendProductReview.ICreate,
  });
  typia.assert(review);

  // 5. Switch back to admin JWT
  connection.headers = { ...connection.headers, Authorization: adminRes.setHeaders.Authorization };

  // Admin creates a snapshot for the review
  const snapshot = await api.functional.shoppingMallAiBackend.admin.productReviews.reviewSnapshots.create(connection, {
    productReviewId: review.id,
    body: {
      review_id: review.id,
      body: review.body,
      rating: review.rating,
      status: review.status,
      actor_id: adminRes.adminId,
