import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrderGroup } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderGroup";
import type { IPageIShoppingMallAiBackendOrderGroup } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderGroup";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate advanced search, pagination, and admin-only access for order group listing.
 *
 * This test ensures that an admin can retrieve a paginated and filtered list of order groups using various criteria. It covers:
 *  - Happy path: filtering by group_name, external_reference, and created_at date ranges, using valid values that match created test data
 *  - Empty result: using filters that shouldn’t match any data (to ensure no false positives and valid empty pagination)
 *  - Pagination and sorting: using page and pageSize for chunked retrieval and sort for order, verifying data and pagination match expectations
 *  - Security: confirming that only an authenticated admin (JWT) can access the list; if unauthenticated (JWT not provided) the API must reject access (error expected).
 *
 * Steps:
 * 1. Authenticate as an admin
 * 2. Create one (or more) order groups for the search to match (unique group_name, external_reference)
 * 3. Filter with group_name and external_reference—expect result contains those groups
 * 4. Filter with a non-matching group_name—expect result is empty
 * 5. Filter with created_at_gte/lte surrounding existing group’s created_at—expect a match
 * 6. Filter with created_at before oldest data—expect empty data
 * 7. Use pageSize = 1 and page = 1/2 to validate correct pagination
 * 8. Try access without being authenticated as admin—API should deny access (error expected)
 */
export async function test_api_admin_order_group_search_success_and_filtering(connection: api.IConnection) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admintest123!";
  const loginRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(loginRes);

  // 2. Create a test order group
  const groupName = `QA-Group-${RandomGenerator.alphabets(6)}`;
  const extRef = `EXT-${RandomGenerator.alphaNumeric(8)}`;
  const createRes = await api.functional.shoppingMallAiBackend.admin.orderGroups.create(connection, {
    body: {
      group_name: groupName,
      external_reference: extRef,
      meta_info: JSON.stringify({ run: "search-e2e" }),
    },
  });
  typia.assert(createRes);

  // 3. Filter with group_name and external_reference—should match
  const filterRes = await api.functional.shoppingMallAiBackend.admin.orderGroups.index(connection, {
    body: {
      group_name: groupName,
      external_reference: extRef,
      page: 1,
      pageSize: 10,
    },
  });
  typia.assert(filterRes);
  TestValidator.predicate("found matching row")(filterRes.data.some(o => o.id === createRes.id));

  // 4. Search with a non-existent group name—should be empty
  const noMatchRes = await api.functional.shoppingMallAiBackend.admin.orderGroups.index(connection, {
    body: {
      group_name: "DefinitelyNonMatchingName123",
      page: 1,
      pageSize: 10,
    },
  });
  typia.assert(noMatchRes);
  TestValidator.equals("empty search")(noMatchRes.data.length)(0);
  TestValidator.predicate("valid pagination even if empty")(typeof noMatchRes.pagination.current === "number");

  // 5. Date range: created_at_gte/lte bounding the actual row
  const createdAt = createRes.created_at;
  const dateRangeRes = await api.functional.shoppingMallAiBackend.admin.orderGroups.index(connection, {
    body: {
      created_at_gte: createdAt,
      created_at_lte: createdAt,
      page: 1,
      pageSize: 10,
    },
  });
  typia.assert(dateRangeRes);
  TestValidator.predicate("date match")(dateRangeRes.data.some(o => o.id === createRes.id));

  // 6. Created_at before all known data—empty result
  const ancientRes = await api.functional.shoppingMallAiBackend.admin.orderGroups.index(connection, {
    body: {
      created_at_lte: "2000-01-01T00:00:00.000Z",
      page: 1,
      pageSize: 10,
    },
  });
  typia.assert(ancientRes);
  TestValidator.equals("ancient date yields empty")(ancientRes.data.length)(0);

  // 7. Pagination and sorting: create a second group for paging
  const extraGroupName = `QA-Extra-${RandomGenerator.alphabets(6)}`;
  const extraRes = await api.functional.shoppingMallAiBackend.admin.orderGroups.create(connection, {
    body: {
      group_name: extraGroupName,
      meta_info: JSON.stringify({ run: "search-e2e-paging" }),
    },
  });
  typia.assert(extraRes);
  // Asc/desc tests
  const pagedResAsc = await api.functional.shoppingMallAiBackend.admin.orderGroups.index(connection, {
    body: {
      sort: "created_at",
      page: 1,
      pageSize: 1,
    },
  });
  typia.assert(pagedResAsc);
  TestValidator.equals("page limit")(pagedResAsc.data.length)(1);
  const pagedResAsc2 = await api.functional.shoppingMallAiBackend.admin.orderGroups.index(connection, {
    body: {
      sort: "created_at",
      page: 2,
      pageSize: 1,
    },
  });
  typia.assert(pagedResAsc2);
  TestValidator.equals("page2 limit")(pagedResAsc2.data.length)(1);
  TestValidator.notEquals("paging distinct")(pagedResAsc.data[0].id)(pagedResAsc2.data[0]?.id);

  // 8. Security: Try access without admin login (clear header)
  const nonAdminConnection = { ...connection, headers: { ...connection.headers, Authorization: "" } };
  await TestValidator.error("must not allow unauthenticated access")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orderGroups.index(nonAdminConnection, {
        body: { page: 1, pageSize: 1 },
      });
    },
  );
}

