 *
 * This test ensures that an admin user can successfully authenticate and request a filtered, paged list of security logs, such as failed_login events, with filtering by event_type, actor type, alert level, and time window. The scenario verifies that the results are correct and limited to what an authenticated admin should see, and no unauthorized information is present.
 *
 * Steps:
 * 1. Authenticate as admin using provided credentials and obtain admin JWT (via API).
 * 2. Fetch a real security log to extract real filterable field values.
 * 3. Perform a paginated/filter search using those values as criteria (event_type, actor_id, actor_type, alert_level, and a tight time window).
 * 4. Assert the API returns a paginated response matching the filter criteria, containing only records that fulfill the criteria (no unauthorized data), and with accurate pagination metadata.
 * 5. Edge case: time window which cannot match should return zero results.
 */
export async function test_api_security_log_search_with_advanced_filtering(
  connection: api.IConnection,
) {
  // 1. Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234@Password";
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);
  // Set the token for subsequent admin calls
  connection.headers = {
    ...connection.headers,
    Authorization: adminAuth.setHeaders.Authorization,
  };

  // 2. Fetch a sample security log to use real values for filterable fields
  const log = await api.functional.shoppingMallAiBackend.admin.securityLogs.at(
    connection,
    {
      securityLogId: typia.random<string & tags.Format<"uuid">>(),
    },
  );
  typia.assert(log);

  // 3. Perform filtered & paginated search for logs with those field values
  const filters = {
    event_type: log.event_type,
    actor_id: log.actor_id ?? null,
    actor_type: log.actor_type,
    alert_level: log.alert_level,
    occurred_at_from: log.occurred_at,
    occurred_at_to: log.occurred_at,
    sort_by: "occurred_at",
    order: "desc",
    page: 0,
    limit: 5,
  } satisfies IShoppingMallAiBackendSecurityLog.IRequest;
  const page = await api.functional.shoppingMallAiBackend.admin.securityLogs.search(
    connection,
    {
      body: filters,
    },
  );
  typia.assert(page);
  // 4. Validate all results match the criteria
  for (const rec of page.data) {
    TestValidator.equals("event_type")(rec.event_type)(log.event_type);
    TestValidator.equals("actor_type")(rec.actor_type)(log.actor_type);
    TestValidator.equals("alert_level")(rec.alert_level)(log.alert_level);
    if (log.actor_id !== null && log.actor_id !== undefined)
      TestValidator.equals("actor_id")(rec.actor_id)(log.actor_id);
    TestValidator.predicate("occurred_at matches filter")(
      rec.occurred_at === log.occurred_at,
    );
  }
  // Pagination info
  TestValidator.predicate("limit respected")(page.data.length <= 5);
  TestValidator.equals("pagination page")(page.pagination.current)(1);

  // 5. Edge: out-of-range window yields empty results
  const emptyPage = await api.functional.shoppingMallAiBackend.admin.securityLogs.search(
    connection,
    {
      body: {
        event_type: log.event_type,
        occurred_at_from: "2000-01-01T00:00:00.000Z",
        occurred_at_to: "2000-01-01T01:00:00.000Z",
