 *
 * Business context: Admins need the ability to search, browse, and review infrastructure/system events (e.g., deployments, incidents, maintenance), using a variety of operational filters, supporting root cause and operations analysis. This test ensures search respects filters, produces paginated results, each event contains only allowed fields (no over/underfetch). Only authenticated admins can access, so proper login is part of the workflow.
 *
 * Step-by-step process:
 * 1. Authenticate as an admin using email & password.
 * 2. Search: Send a filtered, paginated search request for system events with a selected event type (e.g., deployment), time range, and severity.
 * 3. Validate: Confirm the API returns paginated summary: correct page/limit, and each returned event matches the filters (event type, time, severity), with no extra fields.
 * 4. Data completeness: Each event must include all required fields (no over/underfetch) per schema.
 * 5. Edge case: Execute a filter combination guaranteed to return zero events and validate an empty result/page.
 *
 * Assumptions:
 * - A valid admin account for login is available. If admin accounts are provisioned dynamically in your environment, you may need to create one separately; this test expects a functional credential.
 */
export async function test_api_system_event_search_with_filters(
  connection: api.IConnection,
) {
  // 1. Authenticate as an admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "1234!Aa";
  // (This test assumes the admin test account already exists; modify as needed)
  const loginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(loginResponse);

  // 2. Search with specific filters
  const filterBody: IShoppingMallAiBackendSystemEvent.IRequest = {
    system_event_type: "deployment",
    severity_level: "info",
    occurred_at_from: new Date(Date.now() - 1000 * 60 * 60 * 24 * 30).toISOString(), // 30 days ago
    occurred_at_to: new Date().toISOString(),
    sort_by: "occurred_at",
    order: "desc",
    page: 1,
    limit: 10,
  };
  const summary = await api.functional.shoppingMallAiBackend.admin.systemEvents.search(connection, {
    body: filterBody,
  });
  typia.assert(summary);

  // 3. Validate pagination and event matching
  TestValidator.equals("page number matches request")(summary.pagination.current)(1);
  TestValidator.equals("result page size matches limit")(summary.pagination.limit)(10);
  for (const event of summary.data) {
    if (filterBody.system_event_type)
      TestValidator.equals("event type matches")(event.system_event_type)(filterBody.system_event_type);
    if (filterBody.severity_level)
      TestValidator.equals("severity level matches")(event.severity_level)(filterBody.severity_level);
    if (filterBody.occurred_at_from)
      TestValidator.predicate("event after or equal to from filter")(
        event.occurred_at >= filterBody.occurred_at_from,
      );
    if (filterBody.occurred_at_to)
      TestValidator.predicate("event before or equal to to filter")(
        event.occurred_at <= filterBody.occurred_at_to,
      );
    // Ensure event is fully schema-compliant (no excess/missing fields)
    typia.assert(event);
  }

  // 4. Edge case: search with filter that returns 0 events
  const emptySummary = await api.functional.shoppingMallAiBackend.admin.systemEvents.search(connection, {
    body: {
      system_event_type: "__nonexistent_type__",
      severity_level: "critical",
      occurred_at_from: filterBody.occurred_at_from,
      occurred_at_to: filterBody.occurred_at_to,
      page: 1,
      limit: 5,
    },
  });
  typia.assert(emptySummary);
  TestValidator.equals("should return empty event list")(emptySummary.data.length)(0);
}

