import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Ensure admin-only access enforcement for system event record retrieval.
 *
 * This test checks that the API endpoint for retrieving a system event detail (`GET /shoppingMallAiBackend/admin/systemEvents/{systemEventId}`)
 * strictly rejects both:
 *  - Non-admin authenticated requests (using a valid JWT from a registered seller)
 *  - Unauthenticated (no Authorization header) requests
 * In both cases, permission should be denied and *no* event content nor metadata must be disclosed in API responses.
 *
 * Steps:
 * 1. Register a new seller (non-admin role) and retrieve authentication headers.
 * 2. Attempt to access a (random) system event as the seller, expecting a permission-denied error.
 * 3. Remove authentication header (simulate unauthenticated request), reattempt access, expect same denial.
 * 4. For both denials, verify that no system event data is present in the error outcome (strict access control enforcement).
 */
export async function test_api_system_event_retrieve_unauthorized(
  connection: api.IConnection,
) {
  // 1. Register a new seller to obtain valid non-admin JWT
  const seller = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller);

  // Prepare system event id to test
  const systemEventId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt access as this (non-admin) seller - must fail with permission denied
  connection.headers = { ...(connection.headers ?? {}), Authorization: seller.setHeaders.Authorization };
  await TestValidator.error("non-admin forbidden from viewing system event")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.systemEvents.at(
        connection,
        { systemEventId },
      );
    },
  );

  // 3. Remove authentication for unauthenticated (public) attempt - must also fail
  connection.headers = Object.fromEntries(
    Object.entries(connection.headers ?? {}).filter(([k]) => k.toLowerCase() !== "authorization"),
  );
  await TestValidator.error("unauthenticated forbidden from viewing system event")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.systemEvents.at(
        connection,
        { systemEventId },
      );
    },
  );
}

