import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartSnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test deleting a shopping cart snapshot as the authorized customer.
 *
 * This test covers the workflow and error conditions related to deleting a cart snapshot:
 *
 * 1. Register and authenticate a new customer.
 * 2. Create a cart for the customer.
 * 3. Create a cart snapshot for that cart.
 * 4. Successfully delete the snapshot as the cart owner.
 * 5. Verify the snapshot is logically deleted (soft-deleted).
 * 6. Attempt to delete a snapshot that does not exist.
 * 7. Attempt to delete a snapshot with a different customer (non-owner).
 * 8. Attempt to delete an already deleted snapshot.
 *
 * The test validates correct logical deletion behavior, appropriate authorization, and error handling for invalid or repeated deletions.
 */
export async function test_api_customer_cart_snapshot_delete_success_and_error(connection: api.IConnection) {
  // 1. Register and authenticate a new customer.
  const email = typia.random<string & tags.Format<"email">>();
  const password = "P@ssw0rd";
  const nickname = RandomGenerator.alphaNumeric(8);
  const customerSignUpReq: ICustomerSignUp.Request = {
    email,
    password,
    name: RandomGenerator.name(),
    nickname,
    phone: RandomGenerator.mobile(),
  };
  const signUpResp = await api.functional.auth.customer.register.signUp(connection, { body: customerSignUpReq });
  typia.assert(signUpResp);
  TestValidator.equals("registered email")(signUpResp.customer.email)(email);

  // 2. Create a cart for the customer.
  const newCartReq: IShoppingMallAiBackendCart.ICreate = { status: "active" };
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, { body: newCartReq });
  typia.assert(cart);

  // 3. Create a cart snapshot for that cart.
  const snapshotJson = JSON.stringify(cart);
  const snapshotReason = "manual";
  const snapshotReq: IShoppingMallAiBackendCartSnapshot.ICreate = {
    cart_id: cart.id,
    snapshot_json: snapshotJson,
    snapshot_reason: snapshotReason
  };
  const snapshot = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.create(connection, {
    cartId: cart.id,
    body: snapshotReq
  });
  typia.assert(snapshot);
  TestValidator.equals("snapshot cart id")(snapshot.cart_id)(cart.id);

  // 4. Successfully delete the snapshot as the cart owner.
  await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.erase(connection, {
    cartId: cart.id,
    cartSnapshotId: snapshot.id,
  });

  // 5. Try deleting again (should error: already deleted or not found)
  await TestValidator.error("cannot delete an already deleted snapshot")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.erase(connection, {
        cartId: cart.id,
        cartSnapshotId: snapshot.id,
      });
    }
  );

  // 6. Attempt to delete a snapshot that does not exist.
  const fakeSnapshotId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("cannot delete nonexistent snapshot")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.erase(connection, {
        cartId: cart.id,
        cartSnapshotId: fakeSnapshotId,
      });
    }
  );

  // 7. Register a second customer and try to delete the first customer's snapshot from their cart (should error)
  const email2 = typia.random<string & tags.Format<"email">>();
  const nickname2 = RandomGenerator.alphaNumeric(8);
  const customerSignUpReq2: ICustomerSignUp.Request = {
    email: email2,
    password,
    name: RandomGenerator.name(),
    nickname: nickname2,
    phone: RandomGenerator.mobile(),
  };
  await api.functional.auth.customer.register.signUp(connection, { body: customerSignUpReq2 });

  await TestValidator.error("cannot delete snapshot as non-owner")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.erase(connection, {
        cartId: cart.id,
        cartSnapshotId: snapshot.id,
      });
    }
  );
}

