import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test retrieving the details of an order payment as an admin, including edge cases and error handling.
 *
 * This E2E test covers:
 * 1. Admin authenticates and receives a JWT.
 * 2. A customer order is created as a fixture (simulating a pre-existing customer in the DB).
 * 3. An order payment is created for this order via the admin API.
 * 4. The payment is retrieved by ID as admin, validating all audit and business fields.
 * 5. Fetching a payment with a nonexistent payment ID returns an error.
 * 6. Fetching a payment with a nonexistent order ID returns an error.
 * 7. Attempting access with insufficient privilege (no admin credentials) returns an error.
 *
 * This test ensures both business and security rules for order payment detail access operate as intended.
 */
export async function test_api_admin_order_payment_detail_access_and_error(
  connection: api.IConnection,
) {
  // 1. Admin logs in and gets JWT.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin123!";
  // NOTE: The email/password must correspond to a pre-registered admin for E2E test infra to work.
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminAuth);
  TestValidator.equals("admin JWT is present")(typeof adminAuth.jwt)("string");

  // 2. Create a customer order as test fixture
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(
    connection,
    {
      body: {
        customer_id: typia.random<string & tags.Format<"uuid">>(),
        order_group_id: null,
        order_number: RandomGenerator.alphaNumeric(12),
        total_amount: 10000,
        currency_code: "KRW",
        note: "E2E order note",
        current_status: "created",
      } satisfies IShoppingMallAiBackendOrder.ICreate,
    },
  );
  typia.assert(order);

  // 3. Admin creates an order payment record for the order
  const payment = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.create(
    connection,
    {
      orderId: order.id,
      body: {
        order_id: order.id,
        payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
        payment_method: "card",
        transaction_id: RandomGenerator.alphaNumeric(16),
        amount: 10000,
        currency_code: "KRW",
        payment_result: "completed",
        payment_context: JSON.stringify({ e2e: true }),
      } satisfies IShoppingMallAiBackendOrderPayment.ICreate,
    },
  );
  typia.assert(payment);
  TestValidator.equals("payment references correct order")(payment.order_id)(order.id);
  TestValidator.equals("payment currency matches")(payment.currency_code)(order.currency_code);
  TestValidator.equals("payment created_at is present")(typeof payment.created_at)("string");
  TestValidator.equals("payment updated_at is present")(typeof payment.updated_at)("string");

  // 4. Admin fetches the payment by its ID
  const found = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.at(
    connection,
    {
      orderId: order.id,
      orderPaymentId: payment.id,
    },
  );
  typia.assert(found);
  TestValidator.equals("fetched payment ID matches")(found.id)(payment.id);
  TestValidator.equals("fetched payment matches created payment")(found)(payment);

  // 5. Non-existent payment ID error
  await TestValidator.error("fetch with non-existent payment ID fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.at(
      connection,
      {
        orderId: order.id,
        orderPaymentId: typia.random<string & tags.Format<"uuid">>(),
      },
    );
  });

  // 6. Non-existent order ID error
  await TestValidator.error("fetch with non-existent order ID fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.at(
      connection,
      {
        orderId: typia.random<string & tags.Format<"uuid">>(),
        orderPaymentId: payment.id,
      },
    );
  });

  // 7. Insufficient privilege error: remove admin Authorization and attempt access
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  if (unauthConn.headers) delete unauthConn.headers.Authorization;
  await TestValidator.error("access without admin privilege fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.at(
      unauthConn,
      {
        orderId: order.id,
        orderPaymentId: payment.id,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartItem";
import type { IPageIShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCartItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin search, filter, and pagination for cart items in a given cart.
 *
 * Business purpose:
 * Ensure that an admin can successfully paginate and search for cart items belonging to a specific cart using allowed search filters: product_id, product_option_id, created_at(date range), and with pagination (page/limit).  
 * This test covers the business scenario that an admin should see all items in a given cart and can filter down as required for support/audit/business operations.
 *
 * Step-by-step process:
 * 1. Register a customer (owner of the cart)
 * 2. Register an admin (will perform the search as admin)
 * 3. As customer, create a cart
 * 4. As customer, add multiple cart items into this cart (distinct product_ids, quantities, and optionally product_option_id)
 * 5. As admin, search for cart items in that cart:
 *    a. No filters, page/limit specified — validate ALL items visible, correct page & total
 *    b. Filter by product_id of one created item, validate only that item (or those items if same id used multiple times) are returned
 *    c. Filter by created_at_from/created_at_to covering specific range, validate correct items are returned by timestamp
 * 6. For all cases: assert that the items returned satisfy the filter, and pagination metadata is accurate.
 */
export async function test_api_cart_item_search_filter_pagination_success_admin(connection: api.IConnection) {
  // 1. Register a customer and receive JWT for customer actions
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Cpw123!" + typia.random<string>();
  const customerReg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name() + typia.random<string>(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerReg);

  // Authenticate as this customer for following steps
  connection.headers = { ...(connection.headers ?? {}), Authorization: customerReg.setHeaders.Authorization };

  // 2. Register an admin and store the Authorization header (for later)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Apw123!" + typia.random<string>();
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminReg);
  const adminJwt = adminReg.setHeaders.Authorization;

  // 3. Customer creates a cart
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      status: "active",
      session_token: null,
    },
  });
  typia.assert(cart);

  // 4. Customer adds several cart items (distinct product_id, qty, option)
  const products = ArrayUtil.repeat(5)(() => ({ product_id: typia.random<string & tags.Format<"uuid">>(), product_option_id: typia.random<string & tags.Format<"uuid">>(), quantity: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(), unit_price: 10000 + typia.random<number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<1000>>(), currency_code: "KRW", note: RandomGenerator.paragraph()(10) }));
  const now = new Date();

  // Use precise timestamp for each insertion (for deterministic date filter tests)
  const insertedItems: { item: IShoppingMallAiBackendCartItem; inserted_at: Date }[] = [];
  for (const prod of products) {
    // Wait one ms to ensure unique timestamps
    await new Promise((resolve) => setTimeout(resolve, 2));
    const created = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
      cartId: cart.id,
      body: {
        ...prod,
      },
    });
    typia.assert(created);
    insertedItems.push({ item: created, inserted_at: new Date(created.created_at) });
  }

  // 5. Switch to admin account (set Authorization header)
  connection.headers = { ...(connection.headers ?? {}), Authorization: adminJwt };

  // ----
  // 5a. Search for all items in the cart (no filters)
  const pageLimit = 2;
  const noFilterPage1 = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: { page: 1, limit: pageLimit },
  });
  typia.assert(noFilterPage1);
  TestValidator.equals("pagination.records count matches items")(
    noFilterPage1.pagination.records,
  )(insertedItems.length);
  TestValidator.equals("pagination.current page is correct")(noFilterPage1.pagination.current)(1);
  TestValidator.equals("pagination.limit is correct")(noFilterPage1.pagination.limit)(pageLimit);
  // Data matches expected items
  TestValidator.equals("first page data matches")(
    noFilterPage1.data.map((it) => it.id),
  )(insertedItems.map((x) => x.item.id).slice(0, pageLimit));

  // ----
  // 5a-2. Page 2 - should have remaining items
  const noFilterPage2 = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: { page: 2, limit: pageLimit },
  });
  typia.assert(noFilterPage2);
  TestValidator.equals("pagination.current page is 2")(noFilterPage2.pagination.current)(2);
  // Data matches expected items
  TestValidator.equals("page 2 data matches")(
    noFilterPage2.data.map((it) => it.id),
  )(insertedItems.map((x) => x.item.id).slice(pageLimit, pageLimit * 2));

  // ----
  // 5b. Filter by product_id of first inserted item
  const filterProductId = insertedItems[0].item.product_id;
  const filteredByProductId = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: { product_id: filterProductId },
  });
  typia.assert(filteredByProductId);
  // Should only find items with this product_id
  TestValidator.predicate("all items have correct product_id")(
    filteredByProductId.data.every((it) => it.product_id === filterProductId),
  );

  // ----
  // 5c. Date range filter: items inserted strictly after first (should yield 4)
  const createdDates = insertedItems.map((x) => x.inserted_at).sort((a, b) => a.getTime() - b.getTime());
  const afterFirst = createdDates[1].toISOString();
  const filteredByDateFrom = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: { created_at_from: afterFirst },
  });
  typia.assert(filteredByDateFrom);
  // Should contain all except the first item
  TestValidator.equals("date-from filter matches correct items")(
    filteredByDateFrom.data.length,
  )(insertedItems.length - 1);
  filteredByDateFrom.data.forEach((item) => {
    TestValidator.predicate("created_at >= from")(
      new Date(item.created_at).getTime() >= new Date(afterFirst).getTime(),
    );
  });

  // 5d. Date range filter: between 2nd and 4th item inclusively
  const from = createdDates[1].toISOString();
  const to = createdDates[3].toISOString();
  const range = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.search(connection, {
    cartId: cart.id,
    body: { created_at_from: from, created_at_to: to },
  });
  typia.assert(range);
  // The items between 2nd and 4th inclusively
  const expectedInRange = insertedItems.filter((x) => x.inserted_at >= new Date(from) && x.inserted_at <= new Date(to));
  TestValidator.equals("date range matches")(range.data.map((it) => it.id))(expectedInRange.map((x) => x.item.id));
}

