      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerBRegistration);
  const customerBId = customerBRegistration.customer.id;
  // Customer B's JWT will now be set on the connection

