/**
 * Validate duplicate cart item error handling in shopping cart workflow.
 *
 * This test ensures the system enforces item uniqueness in carts:
 * - Register a new customer
 * - Create a cart for that customer
 * - Add a cart item (with productId and optionally productOptionId) to the cart
 * - Attempt to add the identical item again (same productId & productOptionId)
 * - Assert that the system rejects the second addition (business rule: uniqueness constraint per cart on item-product/option combination)
 *
 * Steps:
 * 1. Register a customer account (get authentication)
 * 2. Create a cart as the customer
 * 3. Define a cart item payload (random productId, potentially optionId, always fixed for duplicate simulation)
 * 4. Add the cart item to the cart successfully
 * 5. Attempt to add the same cart item again
 * 6. Verify the system throws an error (TestValidator.error), confirming duplicate item rejection
 */
export async function test_api_cart_item_create_duplicate_error(connection: api.IConnection) {
  // 1. Register a new customer and get their JWT (auto-set in connection)
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Password123$",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
