    body: {
      status: "active",
    } satisfies IShoppingMallAiBackendCart.ICreate,
  });
  typia.assert(cart);

  // 3. Prepare a cart item payload (fixed product, optionally with optionId)
  const productId = typia.random<string & tags.Format<"uuid">>();
  // Randomly decide to include an optionId for variant coverage
  const includeOption = Math.random() > 0.5;
  const productOptionId = includeOption ? typia.random<string & tags.Format<"uuid">>() : undefined;
  const itemPayload: IShoppingMallAiBackendCartItem.ICreate = {
    product_id: productId,
    ...(productOptionId !== undefined ? { product_option_id: productOptionId } : {}),
    quantity: 1,
    unit_price: 10000,
    currency_code: "KRW",
  };

  // 4. Add the initial cart item - succeeds
