 * 2. Search orders with: total_amount_gte: very large value (e.g., 1e12), created_at_gte: a far-future datetime, and/or other impossible combinations
 * 3. Assert: data array is empty
 * 4. Assert: pagination meta is valid (page >= 1, limit >= 1, records = 0, pages = 0 or 1)
 * 5. Assert: no error status or unintended error thrown
 */
export async function test_api_order_search_no_results(
  connection: api.IConnection,
) {
