/**
 * E2E test for advanced admin order search with full filters and pagination.
 *
 * This test validates:
 * 1. Admin can register and log in.
 * 2. Multiple orders exist across at least 2 customers, enough for multiple pages, with a variety of statuses, order groups, amounts, currencies, and created_at values.
 * 3. Admin can search orders with advanced filters (customer, status, group, date, amount, pagination, sort).
 * 4. Search works with correct result structure per API/DTO, and paged results match applied filter logic.
 * 5. Pagination and sorting are robust and multi-page is supported.
 * 6. Cross-customer querying (admin seeing all orders from different customers) works.
 */
export async function test_api_order_search_with_admin_access_and_full_filters(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongP@ssword123";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);
  const adminProfile = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignIn,
  });
  typia.assert(adminProfile);

  // 2. Create orders (at least 2 customers, diverse fields, multi-page)
  const customer1 = typia.random<string & tags.Format<"uuid">>();
  const customer2 = typia.random<string & tags.Format<"uuid">>();
  const orderGroupId = typia.random<string & tags.Format<"uuid">>();
  const orderDatas: IShoppingMallAiBackendOrder.ICreate[] = [
    // Customer 1
    {
      customer_id: customer1,
      order_group_id: orderGroupId,
      order_number: `ORD-${RandomGenerator.alphaNumeric(6)}`,
      total_amount: 150000,
      currency_code: "KRW",
      note: "bulk test 1",
      current_status: "created",
    },
    {
      customer_id: customer1,
      order_group_id: null,
      order_number: `ORD-${RandomGenerator.alphaNumeric(6)}`,
      total_amount: 34000,
      currency_code: "KRW",
      note: "older order",
      current_status: "paid",
    },
    // Customer 2
    {
      customer_id: customer2,
      order_group_id: orderGroupId,
      order_number: `ORD-${RandomGenerator.alphaNumeric(6)}`,
      total_amount: 55000,
      currency_code: "USD",
      note: "usd order",
      current_status: "pending",
    },
    {
      customer_id: customer2,
      order_group_id: null,
      order_number: `ORD-${RandomGenerator.alphaNumeric(6)}`,
      total_amount: 103000,
      currency_code: "KRW",
      note: null,
      current_status: "cancelled",
    },
    // Multi-page data
    ...ArrayUtil.repeat(8)(i => ({
      customer_id: RandomGenerator.pick([customer1, customer2]),
      order_group_id: RandomGenerator.pick([orderGroupId, null]),
      order_number: `ORD-${RandomGenerator.alphaNumeric(6)}`,
      total_amount: 50000 + 10000 * i,
      currency_code: RandomGenerator.pick(["KRW", "USD"]),
      note: i % 2 === 0 ? `test note ${i}` : null,
      current_status: RandomGenerator.pick(["created", "paid", "pending", "cancelled"]),
    })),
  ];
  const allOrders: IShoppingMallAiBackendOrder[] = [];
  for (const orderData of orderDatas) {
    const newOrder = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
      body: orderData,
    });
    typia.assert(newOrder);
    allOrders.push(newOrder);
  }

  // 3. Admin search with advanced filters & pagination
  const searchBody: IShoppingMallAiBackendOrder.IRequest = {
    page: 1,
    pageSize: 5,
    order_number: undefined,
    customer_id: customer1,
    current_status: "created",
    status_in: ["created", "paid"],
    total_amount_gte: 30000,
    total_amount_lte: 200000,
    currency_code: "KRW",
    created_at_gte: allOrders[0].created_at,
    created_at_lte: allOrders[allOrders.length - 1].created_at,
    sort: "-created_at",
  };
  const pagedResult = await api.functional.shoppingMallAiBackend.admin.orders.search(connection, {
    body: searchBody,
  });
  typia.assert(pagedResult);

  // 4. Validate structure and business logic for filtered result
  TestValidator.predicate("pagination metadata exists")(!!pagedResult.pagination);
  TestValidator.predicate("paged data present")(pagedResult.data.length > 0);
  TestValidator.equals("page size limit")(pagedResult.pagination.limit)(5);
  TestValidator.predicate("all orders in page match filters")(
    pagedResult.data.every(o =>
      o.customer_id === customer1 &&
      ["created", "paid"].includes(o.current_status) &&
      o.total_amount >= 30000 &&
      o.total_amount <= 200000 &&
      o.currency_code === "KRW"
    )
  );

  // 5. Advance to second page; check correct pagination info
  const pagedResult2 = await api.functional.shoppingMallAiBackend.admin.orders.search(connection, {
    body: {
      ...searchBody,
      page: 2,
    },
  });
  typia.assert(pagedResult2);
  TestValidator.equals("pagination current is 2")(pagedResult2.pagination.current)(2);

  // 6. Remove most filters, see that admin can list and access orders from both/all customers.
  const allOrdersResult = await api.functional.shoppingMallAiBackend.admin.orders.search(connection, {
    body: {
      page: 1,
      pageSize: 20,
      sort: "created_at",
    },
  });
  typia.assert(allOrdersResult);
  TestValidator.predicate("admin sees all customers across orders")(
    allOrdersResult.data.some(o => o.customer_id === customer1) &&
    allOrdersResult.data.some(o => o.customer_id === customer2)
  );
}

