import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test the end-to-end flow of a seller deleting a product content entry for their own product.
 *
 * This test covers the following workflow:
 * 1. Seller registration and authentication (sign up, then sign in to get JWT session).
 * 2. Seller creates a product to which content will be attached.
 * 3. Seller creates a product content (e.g., image, video, document) for the created product.
 * 4. Seller deletes the specific product content they own via the DELETE endpoint.
 * 5. Validate that deletion is successful: the content is no longer available via business APIs for standard fetch, and subsequent attempts to view it throw not found errors (or soft-deleted if system uses soft-deletes and exposes them).
 *
 * Business context:
 * - Ensures correct authentication propagation (token set), resource ownership enforcement, and that a seller can only delete content from their own product.
 * - Does NOT validate physical content deletion from storage, only API-level business visibility.
 * - For compliance, soft-deleted content should retain a deleted_at timestamp in the backend but must not be exposed via business UI flows.
 *
 * Implementation limitations:
 * - Because the provided SDK does NOT expose a "get by id"/read function for product content, there is no way to implement API-level get/not found or soft-deleted status assertions after deletion. Only the erase (delete) operation and its success (no error thrown) is validated. This is a known technical limitation.
 */
export async function test_api_product_content_delete_by_seller_success(connection: api.IConnection) {
  // 1. Seller registration (sign up)
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234abcd",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUp);

  // 2. Seller logs in (sign in for new JWT, emulating separate browser session)
  const sellerSignIn = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerSignUp.email,
      password: "1234abcd",
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(sellerSignIn);

  // 3. Seller creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerSignIn.sellerId,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      description: RandomGenerator.content()()(),
      main_image_uri: `https://cdn.example.com/product/${RandomGenerator.alphaNumeric(8)}`,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);
  TestValidator.equals("product status is published")(product.status)("published");
  TestValidator.equals("product seller id matches")(product.seller_id)(sellerSignIn.sellerId);

  // 4. Seller creates a product content for that product
  const content = await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      content_type: "gallery_image",
      content_uri: `https://cdn.example.com/content/${RandomGenerator.alphaNumeric(6)}`,
      content_order: 1,
      content_description: RandomGenerator.paragraph()(),
      status: "active",
    } satisfies IShoppingMallAiBackendProductContent.ICreate,
  });
  typia.assert(content);
  TestValidator.equals("content product id matches")(content.product_id)(product.id);
  TestValidator.equals("content status is active")(content.status)("active");

  // 5. Seller deletes the created product content (the target action for this test)
  await api.functional.shoppingMallAiBackend.seller.products.productContents.erase(connection, {
    productId: product.id,
    productContentId: content.id,
  });

  // 6. Post-delete validation (Not Implemented: No API available)
  // No provided SDK API function allows fetching product content by id post-deletion,
  // so we cannot test soft/hard delete exposure or 404 not found behavior directly.
  // This is a platform limitation and is documented for audit, but not code-validated here.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * E2E test: ensure that a seller cannot delete product content owned by another seller.
 *
 * Business context:
 * Only the owner seller of a product (and its product content) should be able to delete their own product content. If another seller attempts to delete this content, the API must return a permission error and the content should remain intact in the system.
 *
 * Steps:
 * 1. Register Seller A.
 * 2. Register Seller B.
 * 3. Login as Seller A and create a new product.
 * 4. As Seller A, add a product content to the product.
 * 5. Logout (if necessary) and login as Seller B.
 * 6. As Seller B (who does not own the product), attempt to delete Seller A's product content. This should fail with a permission error.
 * 7. Login back as Seller A and verify that the product content still exists by (optionally) attempting deletion (should succeed for the owner), or by verifying via API if there is a content listing/read function.
 *
 * Validations:
 * - The cross-owner deletion attempt by Seller B must fail with a permission-related error.
 * - The product content must still exist after the failed deletion attempt, as verified by the owner.
 */
export async function test_api_product_content_delete_not_owned_by_seller(connection: api.IConnection) {
  // 1. Register Seller A
  const sellerAemail = typia.random<string & tags.Format<"email">>();
  const sellerApassword = "Password123!"; // static for login simplicity
  const sellerA = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerAemail,
      password: sellerApassword,
      companyName: RandomGenerator.alphabets(10),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerA);

  // 2. Register Seller B
  const sellerBemail = typia.random<string & tags.Format<"email">>();
  const sellerBpassword = "Password123!";
  const sellerB = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerBemail,
      password: sellerBpassword,
      companyName: RandomGenerator.alphabets(10),
      businessNumber: "0987654321",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerB);

  // 3. Login as Seller A (ensure token is set)
  await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerAemail,
      password: sellerApassword,
    } satisfies ISellerAuth.SignIn,
  });

  // 4. Seller A creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerA.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(1),
      main_image_uri: null,
      status: "active",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 5. Seller A creates product content
  const content = await api.functional.shoppingMallAiBackend.seller.products.productContents.create(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      content_type: "gallery_image",
      content_uri: "https://cdn.example.com/images/" + RandomGenerator.alphaNumeric(8),
      content_order: 1,
      content_description: RandomGenerator.paragraph()(1),
      status: "active",
    } satisfies IShoppingMallAiBackendProductContent.ICreate,
  });
  typia.assert(content);

  // 6. Login as Seller B (sets token)
  await api.functional.auth.seller.login.signIn(connection, {
    body: { email: sellerBemail, password: sellerBpassword } satisfies ISellerAuth.SignIn,
  });

  // 7. Seller B attempts to delete Seller A's product content (should FAIL - permission error)
  await TestValidator.error("Seller B cannot delete Seller A's product content")(() =>
    api.functional.shoppingMallAiBackend.seller.products.productContents.erase(connection, {
      productId: product.id,
      productContentId: content.id,
    }),
  );

  // 8. Login again as Seller A to ensure content is present (no GET/list endpoint so attempt DELETE - should succeed)
  await api.functional.auth.seller.login.signIn(connection, {
    body: { email: sellerAemail, password: sellerApassword } satisfies ISellerAuth.SignIn,
  });
  await api.functional.shoppingMallAiBackend.seller.products.productContents.erase(connection, {
    productId: product.id,
    productContentId: content.id,
  });
  // If no error thrown, deletion by owner succeeded; permission logic is enforced.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that deleting a nonexistent product content does not affect system state and returns proper error.
 *
 * This test ensures that when a DELETE request is made to the product content deletion endpoint with a random (invalid) productContentId for an existing product, the following is validated:
 * 1. The system returns a not found error.
 * 2. The API call is idempotent (repeated calls with invalid ID do not cause further side effects).
 * 3. No product content is actually deleted from the system.
 *
 * Test scenario:
 * 1. Register a new seller account.
 * 2. Login as the seller to obtain authentication and session.
 * 3. The seller creates a new product, building a valid productId.
 * 4. Without ever creating a productContent for this product, generate a random UUID to use as an invalid productContentId.
 * 5. Call the DELETE endpoint with the valid productId and invalid productContentId.
 * 6. Confirm that the API returns a not found error, indicating the content does not exist.
 * 7. Repeat the DELETE call with the same ID to check idempotency (system should still return not found with no state changes).
 * 8. Optionally, re-fetch or check the product (if an endpoint existed for contents list, but it is not in SDK) to ensure product is unaffected (cannot be checked further due to limited API in SDK).
 */
export async function test_api_product_content_delete_nonexistent(
  connection: api.IConnection,
) {
  // 1. Register seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Password1!";
  const signUpResp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: `${typia.random<string>().substring(0, 10)}`,
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: "010-5555-1234",
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as seller
  const signInResp = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Seller creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: signUpResp.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "draft",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 4. Use random (non-existent) productContentId for deletion
  const invalidProductContentId = typia.random<string & tags.Format<"uuid">>();
  const productId = product.id;

  // 5. Attempt to delete nonexistent content; expect error
  await TestValidator.error("delete nonexistent product content should fail")(
    () =>
      api.functional.shoppingMallAiBackend.seller.products.productContents.erase(
        connection,
        {
          productId: productId,
          productContentId: invalidProductContentId,
        },
      ),
  );

  // 6. Attempt deletion again for idempotency; should remain not found
  await TestValidator.error(
    "repeat delete nonexistent product content should still fail",
  )(() =>
    api.functional.shoppingMallAiBackend.seller.products.productContents.erase(
      connection,
      {
        productId: productId,
        productContentId: invalidProductContentId,
      },
    ),
  );
}

