import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSearchKeyword } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSearchKeyword";

/**
 * Validate that an admin can successfully update a product search keyword.
 *
 * Business workflow and validation:
 * 1. Create a product as admin with realistic test data
 * 2. Register a search keyword for the product
 * 3. Update only the allowed (mutable) field of the keyword ('search_keyword')
 * 4. Ensure the update succeeds and verifies:
 *    - The keyword string is updated
 *    - Immutable properties (id, product_id) are unchanged
 */
export async function test_api_product_search_keyword_update_success_admin(
  connection: api.IConnection,
) {
  // 1. Create a product as admin
  const sellerId: string = typia.random<string & tags.Format<"uuid">>();
  const productCode: string = RandomGenerator.alphaNumeric(12);
  const productName: string = RandomGenerator.paragraph()(1);
  const createdProduct = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: productCode,
      name: productName,
      description: RandomGenerator.paragraph()(2),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(createdProduct);

  // 2. Register a search keyword for the product
  const baseKeyword = RandomGenerator.alphaNumeric(8);
  const createdKeyword = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.createProductSearchKeyword(
    connection,
    {
      productId: createdProduct.id,
      body: {
        product_id: createdProduct.id,
        search_keyword: baseKeyword,
      } satisfies IShoppingMallAiBackendProductSearchKeyword.ICreate,
    },
  );
  typia.assert(createdKeyword);
  TestValidator.equals("created keyword's product_id matches product")(createdKeyword.product_id)(createdProduct.id);
  TestValidator.equals("created keyword string matches baseKeyword")(createdKeyword.search_keyword)(baseKeyword);

  // 3. Update the search keyword - only the mutable field
  const updatedKeyword = baseKeyword + "_edited";
  const updated = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.updateProductSearchKeyword(
    connection,
    {
      productId: createdProduct.id,
      productSearchKeywordId: createdKeyword.id,
      body: {
        search_keyword: updatedKeyword,
      } satisfies IShoppingMallAiBackendProductSearchKeyword.IUpdate,
    },
  );
  typia.assert(updated);

  // 4. Validate update: only keyword string is changed, ids remain unchanged
  TestValidator.equals("keyword id unchanged")(updated.id)(createdKeyword.id);
  TestValidator.equals("product id unchanged")(updated.product_id)(createdKeyword.product_id);
  TestValidator.equals("keyword string updated")(updated.search_keyword)(updatedKeyword);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductSearchKeyword } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSearchKeyword";

/**
 * Validate update failure due to resource not found when updating a product search keyword.
 *
 * This test verifies that the API correctly returns an error when attempting to update a product search keyword
 * using non-existent product or productSearchKeywordId values. It ensures resource integrity and that updates
 * are never allowed for missing or already-deleted records.
 *
 * Steps:
 * 1. Prepare random UUIDs not associated with any product or product search keyword (simulate missing records).
 * 2. Attempt to update a product search keyword using made-up IDs.
 * 3. Assert that the API throws an error indicating not found.
 * 4. Repeat with another set of random IDs to confirm error behavior.
 */
export async function test_api_product_search_keyword_update_not_found(
  connection: api.IConnection,
) {
  // 1. Prepare random UUIDs for productId and productSearchKeywordId (guaranteed non-existent)
  const nonExistentProductId: string = typia.random<string & tags.Format<"uuid">>();
  const nonExistentProductSearchKeywordId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Prepare update body with random search keyword
  const updateBody: IShoppingMallAiBackendProductSearchKeyword.IUpdate = {
    search_keyword: RandomGenerator.alphaNumeric(12),
  };

  // 3. Attempt to update using non-existent IDs, expecting a not found error
  await TestValidator.error("should throw not found error on update with invalid IDs")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.updateProductSearchKeyword(
        connection,
        {
          productId: nonExistentProductId,
          productSearchKeywordId: nonExistentProductSearchKeywordId,
          body: updateBody,
        },
      );
    },
  );

  // 4. Repeat with a second set of random non-existent IDs to reaffirm error behavior
  const anotherFakeProductId: string = typia.random<string & tags.Format<"uuid">>();
  const anotherFakeProductSearchKeywordId: string = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("should throw not found for another random ID combination")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.updateProductSearchKeyword(
        connection,
        {
          productId: anotherFakeProductId,
          productSearchKeywordId: anotherFakeProductSearchKeywordId,
          body: updateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSearchKeyword } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSearchKeyword";

/**
 * Validate that non-admin users (such as customers) are denied permission when attempting to update a product search keyword.
 *
 * Business Context:
 * Enforces that only admin users may update a product search keyword via the backend API. The endpoint must reject requests from unauthorized users.
 *
 * Step-by-step process:
 * 1. As admin, create a product with only essential fields.
 * 2. Still as admin, add a product search keyword to the new product.
 * 3. Simulate switched context to a non-admin (such as a customer). In a real-world test suite, this requires switching authentication tokens, but here we use the available connection context to illustrate expected permission denial.
 * 4. Attempt to update the product search keyword as an unauthorized user.
 * 5. Confirm that a permission/authorization error is thrown by the API.
 */
export async function test_api_product_search_keyword_update_permission_denied(
  connection: api.IConnection
) {
  // 1. As admin, create a product
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 2. Create a search keyword for this product
  const searchKeyword = await api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.createProductSearchKeyword(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      search_keyword: RandomGenerator.alphaNumeric(10),
    } satisfies IShoppingMallAiBackendProductSearchKeyword.ICreate,
  });
  typia.assert(searchKeyword);

  // 3. Attempt to update search keyword as an unauthorized user. In practice, this would use a customer or non-admin connection.
  await TestValidator.error("permission denied: non-admin cannot update product search keyword")(
    () =>
      api.functional.shoppingMallAiBackend.admin.products.productSearchKeywords.updateProductSearchKeyword(connection, {
        productId: product.id,
        productSearchKeywordId: searchKeyword.id,
        body: {
          search_keyword: RandomGenerator.alphaNumeric(12),
        } satisfies IShoppingMallAiBackendProductSearchKeyword.IUpdate,
      })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";
import type { IPageIShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductBundle";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate seller-side listing and searching of product bundles.
 *
 * This test covers the business journey: registering a seller, creating a product, creating multiple product bundles, and verifying paginated and filtered search as the seller.
 *
 * Steps:
 * 1. Register a new seller account for isolated testing
 * 2. Create a product under the new seller
 * 3. Create multiple bundles with varied properties for the product
 * 4. Test default listing (no filters): All created bundles must appear
 * 5. Test status filter: Only bundles with the requested status appear
 * 6. Test name substring filter: Bundles matching substring appear
 * 7. Test pagination: Returned page limited & unique records between pages
 * 8. All responses are type-validated and business properties are asserted
 */
export async function test_api_product_bundle_list_success_seller(
  connection: api.IConnection,
) {
  // 1. Register seller
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPass!1",
      companyName: RandomGenerator.name(),
      businessNumber: ("" + typia.random<number & tags.Type<"uint32"> & tags.Minimum<1000000000> & tags.Maximum<9999999999>>()),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    }
  });
  typia.assert(sellerSignUp);
  const sellerId = sellerSignUp.sellerId;

  // 2. Create Product under seller
  const productCreate = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      status: "draft",
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
    }
  });
  typia.assert(productCreate);
  const productId = productCreate.id;

  // 3. Create multiple bundles with varied status and name
  const statuses = ["active", "hidden", "discontinued"];
  const createdBundles: IShoppingMallAiBackendProductBundle[] = [];
  for (let idx = 0; idx < 3; ++idx) {
    const bundle = await api.functional.shoppingMallAiBackend.seller.products.productBundles.create(connection, {
      productId,
      body: {
        main_product_id: productId,
        code: RandomGenerator.alphaNumeric(6) + idx,
        name: `Bundle_${idx}_${RandomGenerator.alphabets(3)}`,
        description: idx % 2 === 0 ? RandomGenerator.paragraph()() : null,
        bundle_policy: idx % 2 ? null : RandomGenerator.paragraph()(),
        bundle_price: idx === 1 ? 9999 + idx : null,
        status: statuses[idx],
      }
    });
    typia.assert(bundle);
    createdBundles.push(bundle);
  }

  // 4. Default list (no filters)
  const searchAll = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: {
      page: 1,
      limit: 100,
    }
  });
  typia.assert(searchAll);
  for (const bundle of createdBundles) {
    TestValidator.predicate("bundle returned in search")(searchAll.data.some((b) => b.id === bundle.id));
  }
  for (const summary of searchAll.data) {
    TestValidator.equals("product id matches in summary")(summary.main_product_id)(productId);
  }

  // 5. Status filter ('active')
  const searchActive = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { status: "active" }
  });
  typia.assert(searchActive);
  for (const summary of searchActive.data) {
    TestValidator.equals("status is active")(summary.status)("active");
  }

  // 6. Name substring filter
  const nameSubstring = createdBundles[1].name.slice(3, 6);
  const searchByName = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { name: nameSubstring }
  });
  typia.assert(searchByName);
  TestValidator.predicate("bundle matching name substring present")(
    searchByName.data.some((b) => b.id === createdBundles[1].id)
  );

  // 7. Pagination (limit 1, check uniqueness)
  const page1 = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { page: 1, limit: 1 }
  });
  typia.assert(page1);
  TestValidator.equals("records returned is 1")(page1.data.length)(1);
  const page2 = await api.functional.shoppingMallAiBackend.seller.products.productBundles.search(connection, {
    productId,
    body: { page: 2, limit: 1 }
  });
  typia.assert(page2);
  TestValidator.equals("records returned is 1")(page2.data.length)(1);
  TestValidator.notEquals("page 1 and page 2 bundles differ")(page1.data[0].id)(page2.data[0].id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";
import type { IPageIShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductBundle";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates admin paginated search and filtering of product bundles linked to a product.
 *
 * Business goal: Ensure admin can create a product, register several bundles (with a mix of attributes), and perform
 * advanced paginated search (by name and status) that returns only the proper bundles with accurate pagination. Also ensure
 * an empty result is returned for unmatched filter.
 *
 * 1. Admin creates a product
 * 2. Admin creates 5 bundles (3 named 'VIP Bundle N', status=active, 2 named 'Standard Pack N', status=discontinued)
 * 3. Admin performs paginated search for name='VIP Bundle', status='active', limit=2, page=1 (expect bundles 0,1)
 * 4. Admin fetches next paginated page (expect bundle 2)
 * 5. Admin performs filter search for name='NoSuch Bundle' to confirm empty result
 */
export async function test_api_product_bundle_list_success_admin(connection: api.IConnection) {
  // 1. Create product
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(1),
      main_image_uri: null,
      status: "published"
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 2. Create bundles (3 that match filter, 2 that don't)
  const bundles = await ArrayUtil.asyncRepeat(5)(async (i: number) =>
    await api.functional.shoppingMallAiBackend.admin.products.productBundles.create(connection, {
      productId: product.id,
      body: {
        main_product_id: product.id,
        code: `BNDL-${RandomGenerator.alphaNumeric(4)}-${i}`,
        name: i < 3 ? `VIP Bundle ${i}` : `Standard Pack ${i}`,
        description: i < 3 ? "Promo bundle for campaign" : null,
        bundle_policy: i < 3 ? "campaign" : "manual",
        bundle_price: i < 3 ? 6000 + i * 250 : 12000 + i * 500,
        status: i < 3 ? "active" : "discontinued"
      } satisfies IShoppingMallAiBackendProductBundle.ICreate
    })
  );
  bundles.forEach(bundle => typia.assert(bundle));

  // 3. Paginated search for VIP Bundles (page 1, limit 2)
  const filter = {
    main_product_id: product.id,
    name: "VIP Bundle",
    status: "active",
    page: 1,
    limit: 2,
    order_by: "created_at",
    order_direction: "asc"
  } satisfies IShoppingMallAiBackendProductBundle.IRequest;
  const result = await api.functional.shoppingMallAiBackend.admin.products.productBundles.search(connection, {
    productId: product.id,
    body: filter
  });
  typia.assert(result);
  TestValidator.predicate("Bundles match VIP Bundle/active")(
    result.data.every(b =>
      b.main_product_id === product.id &&
      b.name.startsWith("VIP Bundle") &&
      b.status === "active"
    )
  );
  TestValidator.equals("pagination limit")(result.pagination.limit)(2);
  TestValidator.predicate("result length ≤ limit")(result.data.length <= 2);

  // 4. Page 2
  const result2 = await api.functional.shoppingMallAiBackend.admin.products.productBundles.search(connection, {
    productId: product.id,
    body: { ...filter, page: 2 }
  });
  typia.assert(result2);
  TestValidator.equals("pagination current page")(result2.pagination.current)(2);

  // 5. Edge case: filter for no-match bundles
  const emptyResult = await api.functional.shoppingMallAiBackend.admin.products.productBundles.search(connection, {
    productId: product.id,
    body: {
      main_product_id: product.id,
      name: "NoSuch Bundle",
      page: 1,
      limit: 1
    } satisfies IShoppingMallAiBackendProductBundle.IRequest
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty result count")(emptyResult.data.length)(0);
}

