/**
 * Validates that a customer can mark their own favorite notification as read,
 * and verifies both that the state changes correctly and that non-owners cannot update it.
 *
 * Business scenario:
 * 1. A customer signs up and authenticates.
 * 2. The customer favorites a product (which may later generate notifications).
 * 3. A notification is created for this favorite product, unread by default.
 * 4. The customer marks the notification as read using the update endpoint.
 * 5. Assert the notification's 'read' property is now true, and linkage fields (favorite_product_id) remain unchanged.
 * 6. Assert non-owners cannot update another customer's notification: a new customer signs up, and attempts to mark the same notification as unread (should error).
 *
 * This test ensures adherence to security/ownership, audit integrity, and correct endpoint operation as described.
 */
export async function test_api_favorite_notification_update_mark_read(connection: api.IConnection) {
  // 1. Sign up and authenticate as the first customer (auto-applies session/JWT)
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(10);
  const customerResp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: email,
      password: password,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerResp);
  const customer = customerResp.customer;

  // 2. Customer favorites a product (create favorite product record)
  const favoriteProduct = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: {
      product_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IShoppingMallAiBackendFavoriteProduct.ICreate,
  });
  typia.assert(favoriteProduct);

  // 3. Create an unread favorite notification tied to that favorite product
  const notification = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, {
    body: {
      favorite_product_id: favoriteProduct.id,
      notification_type: "PRICE_DROP",
      notification_channel: "PUSH",
      read: false,
      delivery_metadata: null,
    } satisfies IShoppingMallAiBackendFavoriteNotification.ICreate,
  });
  typia.assert(notification);
  TestValidator.equals("notification unread on creation")(notification.read)(false);

  // 4. Mark the notification as read
  const updatedNotification = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.update(connection, {
    favoriteNotificationId: notification.id as string & tags.Format<"uuid">,
    body: {
      read: true,
    } satisfies IShoppingMallAiBackendFavoriteNotification.IUpdate,
  });
  typia.assert(updatedNotification);
  TestValidator.equals("notification read state changed")(updatedNotification.read)(true);
  TestValidator.equals("favorite product linkage unchanged")(updatedNotification.favorite_product_id)(notification.favorite_product_id);
  TestValidator.equals("notification id unchanged")(updatedNotification.id)(notification.id);

  // 5. Attempt unauthorized update by a different (non-owner) customer
  const email2 = typia.random<string & tags.Format<"email">>();
  const password2 = RandomGenerator.alphaNumeric(10);
  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: email2,
      password: password2,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  // JWT/session is now second user
  await TestValidator.error("non-owner forbidden to update notification")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.update(connection, {
        favoriteNotificationId: notification.id as string & tags.Format<"uuid">,
        body: { read: false },
      });
    },
  );
}

