 * 4. Attempt to create a duplicate coin balance for the same wallet using the same balance_at timestamp. Expect an error due to unique constraint.
 * 5. Attempt to create a coin balance for a non-existent wallet_id. Expect failure and error response.
 */
export async function test_api_coin_wallet_balance_creation_and_duplicate_error(
  connection: api.IConnection,
) {
