  // Assert immutable fields are unchanged
  TestValidator.equals("wallet_id unchanged")(updatedBalance.wallet_id)(wallet.id);
  TestValidator.equals("id unchanged")(updatedBalance.id)(balance.id);
  TestValidator.equals("created_at unchanged")(updatedBalance.created_at)(balance.created_at);

