import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test a successful update of a mileage transaction's allowed mutable fields by the mileage wallet owner (customer).
 *
 * Business context: Ensures a customer can successfully update mutable fields (e.g., reason/comment) of their own mileage transaction.
 * Verifies only the allowed fields are modified, the change is persisted, and unmodifiable fields remain intact.
 *
 * Steps:
 * 1. Register a new customer and obtain JWT authentication automatically
 * 2. As admin, create a mileage wallet for the new customer
 * 3. As the authenticated customer, create a mileage transaction for their own wallet
 * 4. As the same customer, update the transaction (only allowed field: transaction_reason)
 * 5. Validate that only the mutable field has changed; all other properties remain unchanged
 */
export async function test_api_mileage_transaction_update_success_customer(
  connection: api.IConnection,
) {
  // 1. Register a new customer and obtain JWT
  const signUpBody: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "T3stPassword$123",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const signUp = await api.functional.auth.customer.register.signUp(connection, {
    body: signUpBody,
  });
  typia.assert(signUp);
  // JWT automatically set for this connection
  const customer = signUp.customer;

  // 2. As admin, create a mileage wallet for the customer
  const walletCreate: IShoppingMallAiBackendMileageWallet.ICreate = {
    customer_id: customer.id,
    wallet_program: "event",
    wallet_status: "active",
    wallet_label: "Test Wallet",
    security_code: null,
  };
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: walletCreate,
  });
  typia.assert(wallet);

  // 3. As authenticated customer, create a mileage transaction on their wallet
  const transactionCreate: IShoppingMallAiBackendMileageTransaction.ICreate = {
    wallet_id: wallet.id,
    transaction_type: "accumulate",
    mileage_amount: 1000,
    reference_id: null,
    transaction_reason: "Test E2E transaction",
  };
  const transaction = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.create(connection, {
    mileageWalletId: wallet.id,
    body: transactionCreate,
  });
  typia.assert(transaction);

  // 4. Update the transaction_reason with a new value
  const updatedReason = "Changed by customer for E2E test";
  const updatePayload: IShoppingMallAiBackendMileageTransaction.IUpdate = {
    id: transaction.id,
    transaction_reason: updatedReason,
  };
  const updated = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.update(connection, {
    mileageWalletId: wallet.id,
    mileageTransactionId: transaction.id,
    body: updatePayload,
  });
  typia.assert(updated);

  // 5. Validate that only transaction_reason is changed, other fields are unchanged
  TestValidator.equals("ID unchanged")(updated.id)(transaction.id);
  TestValidator.equals("wallet unchanged")(updated.wallet_id)(transaction.wallet_id);
  TestValidator.equals("type unchanged")(updated.transaction_type)(transaction.transaction_type);
  TestValidator.equals("mileage amount unchanged")(updated.mileage_amount)(transaction.mileage_amount);
  TestValidator.equals("reason updated")(updated.transaction_reason)(updatedReason);
  TestValidator.equals("created_at unchanged")(updated.created_at)(transaction.created_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test updating immutable or restricted fields of a mileage transaction as a customer.
 *
 * This test ensures that when a customer attempts to update immutable or restricted fields of a mileage transaction (such as 'mileage_amount', 'transaction_type', or trying to move the transaction to a different wallet), the API rejects such changes with appropriate validation or business errors and preserves the original transaction data.
 *
 * **Test Steps:**
 * 1. Register a customer account and save the session token.
 * 2. Using admin privileges, create a mileage wallet for the registered customer.
 * 3. As the customer, create a valid mileage transaction (type 'accumulate', positive amount).
 * 4. For each immutable/restricted field, attempt to update it via the customer update API and verify each attempt fails (returns an error):
 *    - Attempt to change 'mileage_amount'.
 *    - Attempt to change 'transaction_type'.
 *    - Attempt to indirectly move the transaction to another wallet (should be blocked by backend if implemented, via the transaction 'id').
 * 5. Confirm original transaction is unchanged after failed updates (by local invariants, since transaction fetch API is not available).
 */
export async function test_api_mileage_transaction_update_invalid_or_immutable_fields(connection: api.IConnection) {
  // 1. Register customer and obtain session
  const signUpReq: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword123!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const signUpRes = await api.functional.auth.customer.register.signUp(connection, { body: signUpReq });
  typia.assert(signUpRes);
  const customer = signUpRes.customer;

  // 2. Create mileage wallet for customer (admin privilege)
  const walletReq: IShoppingMallAiBackendMileageWallet.ICreate = {
    customer_id: customer.id,
    wallet_program: RandomGenerator.alphaNumeric(6),
    wallet_status: "active",
    wallet_label: "Test Wallet",
    security_code: null,
  };
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, { body: walletReq });
  typia.assert(wallet);

  // 3. Create valid mileage transaction as the customer
  const txnCreate: IShoppingMallAiBackendMileageTransaction.ICreate = {
    wallet_id: wallet.id,
    transaction_type: "accumulate",
    mileage_amount: 100,
    reference_id: RandomGenerator.alphaNumeric(8),
    transaction_reason: "Initial test accrual.",
  };
  const txn = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.create(connection, { mileageWalletId: wallet.id, body: txnCreate });
  typia.assert(txn);

  // 4a. Attempt to update 'mileage_amount' (should fail)
  await TestValidator.error("Updating mileage_amount must be rejected")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.update(connection, {
        mileageWalletId: wallet.id,
        mileageTransactionId: txn.id,
        body: {
          id: txn.id,
          // This field is not updatable: attempt by supplying in IUpdate object, should fail
          // (If DTO does not allow, expect type error; here used to force business or validation error)
          transaction_reason: txn.transaction_reason,
          // illegal field placement for test (simulate via business logic, not type omission)
          mileage_amount: 9999 as any,
        } as any,
      });
    },
  );

  // 4b. Attempt to update 'transaction_type' (should fail)
  await TestValidator.error("Updating transaction_type must be rejected")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.update(connection, {
        mileageWalletId: wallet.id,
        mileageTransactionId: txn.id,
        body: {
          id: txn.id,
          transaction_reason: txn.transaction_reason,
          transaction_type: "redeem" as any,
        } as any,
      });
    },
  );

  // 4c. Attempt to update 'wallet_id' to move transaction (should fail)
  // For the sake of completeness, create a second wallet and try to "move"
  const wallet2Req: IShoppingMallAiBackendMileageWallet.ICreate = {
    customer_id: customer.id,
    wallet_program: RandomGenerator.alphaNumeric(6),
    wallet_status: "active",
    wallet_label: "Alt Wallet",
    security_code: null,
  };
  const wallet2 = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, { body: wallet2Req });
  typia.assert(wallet2);

  await TestValidator.error("Moving transaction to another wallet must be rejected")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.update(connection, {
        mileageWalletId: wallet2.id,
        mileageTransactionId: txn.id,
        body: {
          id: txn.id,
          transaction_reason: txn.transaction_reason,
          // Attempt placement of wallet_id, although schema would not allow; simulate by path param
        } as any,
      });
    },
  );

  // 5. Confirm transaction values remain unchanged (invariant: no fetch endpoint is available; local invariants only)
  // The test expects no mutation for immutable fields and assumes backend will log attempts for compliance.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates that an admin can update mutable fields (such as transaction_reason) of a mileage transaction,
 * but is prevented from changing immutable/financial fields (like mileage_amount or transaction_type). The test also ensures
 * the transaction is correctly updated in the system. Audit log validation is outside the allowed API surface.
 *
 * Business context:
 * Mileage transactions record loyalty operations (accrual, redemption, adjustment) tied to a wallet. Update is allowed for certain non-financial metadata fields,
 * but core finance details (amount/type) are locked for integrity. Only admins may update.
 *
 * Step-by-step flow:
 * 1. Register a new admin and authenticate to get JWT/session
 * 2. Create a mileage wallet for a random customer (simulate with random UUID)
 * 3. Create a new mileage transaction on that wallet as admin
 * 4. Attempt to update allowed field (transaction_reason) -> expect a successful update
 * 5. Validate the field was updated, and immutable fields remain unchanged
 * 6. (Error test omitted – as only legal fields are allowed by DTO structure, type safety blocks amount/type mutation)
 */
export async function test_api_mileage_transaction_update_success_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin (simulate with random credentials)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAuth);

  // (JWT is set in connection via setHeaders)

  // 2. Create a mileage wallet for testing (simulate random customer)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const walletProgram = "test_program_" + typia.random<string>();
  const walletStatus = "active";
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(
    connection,
    {
      body: {
        customer_id: customerId,
        wallet_program: walletProgram,
        wallet_status: walletStatus,
        wallet_label: "Test Wallet",
        security_code: null,
      } satisfies IShoppingMallAiBackendMileageWallet.ICreate,
    },
  );
  typia.assert(wallet);

  // 3. Create a mileage transaction
  const transactionType = "accumulate";
  const mileageAmount = 100;
  const transactionReason = "Initial grant";
  const referenceId = typia.random<string & tags.Format<"uuid">>();
  const transaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(
    connection,
    {
      mileageWalletId: wallet.id,
      body: {
        wallet_id: wallet.id,
        transaction_type: transactionType,
        mileage_amount: mileageAmount,
        reference_id: referenceId,
        transaction_reason: transactionReason,
      } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
    },
  );
  typia.assert(transaction);

  // 4. Update transaction_reason (the only mutable field)
  const newReason = "Admin post-correction note";
  const updatedTransaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.update(
    connection,
    {
      mileageWalletId: wallet.id,
      mileageTransactionId: transaction.id,
      body: {
        id: transaction.id,
        transaction_reason: newReason,
      } satisfies IShoppingMallAiBackendMileageTransaction.IUpdate,
    },
  );
  typia.assert(updatedTransaction);

  // 5. Validate only the mutable field was changed.
  TestValidator.equals("transaction_reason updated")(
    updatedTransaction.transaction_reason,
  )(newReason);
  TestValidator.equals("amount remains the same")(
    updatedTransaction.mileage_amount,
  )(mileageAmount);
  TestValidator.equals("type remains the same")(
    updatedTransaction.transaction_type,
  )(transactionType);
  TestValidator.equals("reference remains the same")(
    updatedTransaction.reference_id,
  )(referenceId);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import type { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validates that admin cannot update immutable or locked mileage transactions via the admin API.
 *
 * This test ensures that attempts to change immutable fields (such as transaction_type or mileage_amount) via the update endpoint are rejected/not allowed, and only permitted fields (like transaction_reason) can be edited. Attempts to modify immutable fields must have no effect. Attempts to edit transaction_reason must succeed. Unimplementable aspects (transaction locking/finalization and full re-read) are omitted due to API limitations.
 *
 * Test Workflow:
 * 1. Register an admin and get session.
 * 2. Admin creates a mileage wallet for a random customer.
 * 3. Admin creates a mileage transaction for this wallet.
 * 4. Attempt to update with just id (should be a no-op; immutable fields must not change).
 * 5. Assert immutable fields (transaction_type, mileage_amount) remain the same.
 * 6. Attempt to update transaction_reason and expect this to succeed.
 * 7. Assert transaction_reason field updated, but immutable fields still unchanged.
 */
export async function test_api_mileage_transaction_update_invalid_admin_attempt(
  connection: api.IConnection
) {
  // 1. Register admin to enable admin-only endpoints
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongPassword123!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminAuth);

  // 2. Create a mileage wallet for a random customer
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      wallet_program: "brand",
      wallet_status: "active",
    } satisfies IShoppingMallAiBackendMileageWallet.ICreate,
  });
  typia.assert(wallet);

  // 3. Create a new mileage transaction on this wallet
  const transaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.create(connection, {
    mileageWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      transaction_type: "accumulate",
      mileage_amount: 500,
      reference_id: null,
      transaction_reason: "Initial points awarded",
    } satisfies IShoppingMallAiBackendMileageTransaction.ICreate,
  });
  typia.assert(transaction);

  // 4. Attempt to update with just id (should be a no-op)
  const updateAttempt = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.update(connection, {
    mileageWalletId: wallet.id,
    mileageTransactionId: transaction.id,
    body: {
      id: transaction.id,
    } satisfies IShoppingMallAiBackendMileageTransaction.IUpdate,
  });
  typia.assert(updateAttempt);

  // 5. Assert immutable fields remain unchanged
  TestValidator.equals("transaction_type unchanged")(updateAttempt.transaction_type)(transaction.transaction_type);
  TestValidator.equals("mileage_amount unchanged")(updateAttempt.mileage_amount)(transaction.mileage_amount);

  // 6. Attempt positive case: update transaction_reason
  const updatedTransaction = await api.functional.shoppingMallAiBackend.admin.mileageWallets.mileageTransactions.update(connection, {
    mileageWalletId: wallet.id,
    mileageTransactionId: transaction.id,
    body: {
      id: transaction.id,
      transaction_reason: "Admin updated reason",
    } satisfies IShoppingMallAiBackendMileageTransaction.IUpdate,
  });
  typia.assert(updatedTransaction);

  // 7. Assert updated field, and immutables still unchanged
  TestValidator.equals("transaction_reason updated")(updatedTransaction.transaction_reason)("Admin updated reason");
  TestValidator.equals("transaction_type unchanged")(updatedTransaction.transaction_type)(transaction.transaction_type);
  TestValidator.equals("mileage_amount unchanged")(updatedTransaction.mileage_amount)(transaction.mileage_amount);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
