import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validates customer-initiated soft deletion (logical deletion via deleted_at) of a mileage transaction they own via DELETE operation.
 *
 * This E2E scenario is crucial for ensuring compliance and auditability in financial/mileage operations involving point redemptions and accruals by customers.
 *
 * Workflow Steps:
 * 1. Register a customer via /auth/customer/register, which also authenticates and sets JWT in session.
 * 2. Create a new mileage wallet for this customer via /shoppingMallAiBackend/admin/mileageWallets (acting as setup, allowed precondition for customer integration test).
 * 3. As the authenticated customer, create a mileage transaction for that wallet (e.g., sign-up bonus or test accrual) using /shoppingMallAiBackend/customer/mileageWallets/{mileageWalletId}/mileageTransactions.
 * 4. Issue a DELETE request to /shoppingMallAiBackend/customer/mileageWallets/{mileageWalletId}/mileageTransactions/{mileageTransactionId} to perform logical/soft deletion (deleted_at field should be set, not physical deletion).
 * 5. (As there are no SDK endpoints provided to read single transactions or their deleted status, direct fetch/validation of deleted_at is not possible in this E2E test.)
 *
 * Note:
 * - Test validates the process up to DELETE.
 * - In a real audit, logical deletion (deleted_at) and compliance logs should be checked in system backend or by adding read/list endpoints in the SDK in future development.
 * - All SDK and DTO usage is strictly from provided materials.
 */
export async function test_api_mileage_transaction_delete_success_customer(connection: api.IConnection) {
  // Step 1: Customer registration and authentication
  const signUpInput: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Abc!12345#",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(10),
    phone: RandomGenerator.mobile()
  };
  const signUpResult = await api.functional.auth.customer.register.signUp(connection, { body: signUpInput });
  typia.assert(signUpResult);
  const customer = signUpResult.customer;

  // Step 2: Admin creates a mileage wallet for this customer
  const walletInput: IShoppingMallAiBackendMileageWallet.ICreate = {
    customer_id: customer.id,
    wallet_program: "brand",
    wallet_status: "active",
    wallet_label: RandomGenerator.alphabets(15),
    security_code: null
  };
  const wallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, { body: walletInput });
  typia.assert(wallet);

  // Step 3: Customer creates a mileage transaction in this wallet
  const transactionInput: IShoppingMallAiBackendMileageTransaction.ICreate = {
    wallet_id: wallet.id,
    transaction_type: "accumulate",
    mileage_amount: 500,
    reference_id: null,
    transaction_reason: "test bonus"
  };
  const transaction = await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.create(connection, {
    mileageWalletId: wallet.id,
    body: transactionInput,
  });
  typia.assert(transaction);

  // Step 4: Customer issues DELETE to soft-delete the transaction (logical deletion)
  await api.functional.shoppingMallAiBackend.customer.mileageWallets.mileageTransactions.erase(connection, {
    mileageWalletId: wallet.id,
    mileageTransactionId: transaction.id,
  });

  // Note: There is no SDK endpoint provided to re-read or verify the deleted_at status of this transaction directly.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
