  TestValidator.equals("metadata_json updated")(updatedExternalLink.metadata_json)(updatedFields.metadata_json);

  // 4. Negative test: attempt update as non-owner (should fail)
  await TestValidator.error("non-owner update should fail")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: typia.random<string & tags.Format<"uuid">>(),
        body: updatedFields,
