/**
 * Test validation failures for customer external link update.
 *
 * This test covers cases where a customer attempts to update an external OAuth/social login link with invalid or malformed payloads. 
 * Scenarios include: missing required fields, illegal provider, invalid UUID/date-time, malformed external_id fields, and corrupted metadata_json.
 *
 * Steps:
 * 1. Register a new customer (via signUp) for testing.
 * 2. Attach an initial valid external link so updates have existing target.
 * 3. Attempt updates with: missing required id, illegal provider, invalid UUID, empty or corrupt fields, bad JSON, or multiple faulty properties.
 * 4. For each, expect an API error response and proper handling (not a successful update).
 *
 * This test ensures strict DTO contract enforcement and correct input validation for external link management.
 */
export async function test_api_customer_external_link_update_validation_failure(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const customerSignUp = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "TestPwd1!@#",
        name: RandomGenerator.name(),
        nickname: RandomGenerator.alphaNumeric(8),
        phone: RandomGenerator.mobile(),
      },
    },
  );
  typia.assert(customerSignUp);
  const customer = customerSignUp.customer;
  TestValidator.equals("customer id echoed")(customer.id)(customer.id);

  // 2. Attach a valid external link for negative test base
  const linkId = typia.random<string & tags.Format<"uuid">>();
  const provider = "google";
  const externalId = RandomGenerator.alphaNumeric(18);
  const now = new Date().toISOString();
  const externalLink = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
    connection,
    {
      customerId: customer.id,
      body: {
        id: linkId,
        provider,
        external_id: externalId,
        linked_at: now,
        last_auth_at: now,
        metadata_json: '{"verified":true}',
        // deleted_at: null, // Removed because property only allows string | undefined
      },
    },
  );
  typia.assert(externalLink);
  TestValidator.equals("init link id")(externalLink.id)(linkId);

  // 3a: Missing required id field (should error)
  await TestValidator.error("missing id on update fails")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          provider,
          external_id: externalId,
        } as any, // Deliberately invalid for runtime error only
      },
    );
  });

  // 3b: Illegal provider value
  await TestValidator.error("illegal provider")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          id: linkId,
          provider: "!not_a_known_provider!",
          external_id: RandomGenerator.alphaNumeric(16),
        },
      },
    );
  });

  // 3c: Invalid UUID for id
  await TestValidator.error("invalid uuid")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          id: "foobar-uuid",
          provider,
          external_id: RandomGenerator.alphaNumeric(10),
        },
      },
    );
  });

  // 3d: Empty external_id is not valid
  await TestValidator.error("empty external_id")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          id: linkId,
          provider,
          external_id: "",
        },
      },
    );
  });

  // 3e: Invalid metadata_json (not JSON string)
  await TestValidator.error("corrupt metadata_json")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          id: linkId,
          provider,
          external_id: RandomGenerator.alphaNumeric(10),
          metadata_json: "not-json",
        },
      },
    );
  });

  // 3f: Multiple problems at once
  await TestValidator.error("many issues at once")(async () => {
    await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(
      connection,
      {
        customerId: customer.id,
        body: {
          id: "bad",
          provider: "invalid!",
          external_id: "",
          linked_at: "nope",
          last_auth_at: "nope",
          metadata_json: "!!!",
          deleted_at: "nope",
        },
      },
    );
  });
}

