  // Use the JWT token provided for the customer
  connection.headers = {
    ...connection.headers,
    Authorization: customerSignUp.setHeaders.Authorization
  };

  // 3. Attach an external link to the customer
  const provider = "test-provider";
  const externalId = RandomGenerator.alphaNumeric(12);
