import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin-side deletion behavior for non-existent or already-deleted external customer links.
 *
 * This scenario ensures that, as an admin, attempting to soft-delete an external login/social/OAuth link by ID on behalf of a customer (via the admin endpoint) returns the correct not-found/idempotent response. The deletion attempt must not affect other records, and such attempts should be auditable for compliance.
 *
 * Process:
 * 1. Register and authenticate a new admin, as required by system policy.
 * 2. As admin, attempt to delete an external link using random UUIDs for both customer and externalLink (ensuring the link does not actually exist).
 * 3. Validate the API properly handles the case: expecting an error or silent idempotent success, with no side effects on other data.
 * 4. (Optional edge case): Repeat with the same UUIDs to simulate "already deleted" state. Confirm same idempotent or error handling applies.
 */
export async function test_api_admin_external_link_delete_nonexistent_or_already_deleted(connection: api.IConnection) {
  // 1. Admin registration & authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminRegistration = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "strongTestPassword!1"
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminRegistration);

  // 2. Attempt to delete an external link that does not exist
  const randomCustomerId = typia.random<string & tags.Format<"uuid">>();
  const randomExternalLinkId = typia.random<string & tags.Format<"uuid">>();

  // 3. Expect either an error (not found) or a silent idempotent no-op success. Either is acceptable for idempotent deletion.
  await TestValidator.error("Should reject non-existent external link deletion")(
    () => api.functional.shoppingMallAiBackend.admin.customers.externalLinks.erase(
      connection,
      {
        customerId: randomCustomerId,
        externalLinkId: randomExternalLinkId
      }
    )
  );

  // 4. (Optional) Try deleting again to simulate already-deleted state – should again be error or idempotent ok.
  await TestValidator.error("Should still reject repeated/\"already deleted\" external link deletion")(
    () => api.functional.shoppingMallAiBackend.admin.customers.externalLinks.erase(
      connection,
      {
        customerId: randomCustomerId,
        externalLinkId: randomExternalLinkId
      }
    )
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerExternalLink } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerExternalLink";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test that a customer can soft delete (unlink) their own external authentication/social login.
 *
 * Business context:
 * Customers may link external OAuth/social accounts to their profile for login convenience. When they choose to unlink (soft-delete) an externalId, it should not be usable for login but the record must remain for audit purposes (with deleted_at set). Users must not see deleted links by default. Deletion should be idempotent.
 *
 * Steps:
 * 1. Register a customer account (and obtain their customerId, verify authentication is set)
 * 2. Attach an external link to this customer using PUT /shoppingMallAiBackend/customer/customers/{customerId}/externalLinks
 * 3. Delete (soft-delete) the link using DELETE /shoppingMallAiBackend/customer/customers/{customerId}/externalLinks/{externalLinkId}
 * 4. Verify the external link object has deleted_at set
 * 5. Attempt to delete again and confirm either idempotent pass or correct error (e.g., not-found or already-deleted)
 */
export async function test_api_customer_external_link_soft_delete_by_owner(
  connection: api.IConnection,
) {
  // 1. Register a customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "StrongP@ssw0rd";
  const nickname = RandomGenerator.name();
  const customerRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname,
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerRes);
  const customer = customerRes.customer;
  const customerId = customer.id;

  // 2. Attach external link (simulate a real provider link)
  const provider = "google";
  const externalId = RandomGenerator.alphaNumeric(20);
  const externalLink = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(connection, {
    customerId,
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      provider,
      external_id: externalId,
      linked_at: new Date().toISOString(),
    } satisfies IShoppingMallAiBackendCustomerExternalLink.IUpdate
  });
  typia.assert(externalLink);

  // 3. Soft-delete the external link
  await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.erase(connection, {
    customerId,
    externalLinkId: externalLink.id,
  });

  // 4. Attempt to fetch the link again (no GET API, so update acts as a read substitute)
  const deletedLink = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(connection, {
    customerId,
    body: {
      id: externalLink.id
    }
  });
  typia.assert(deletedLink);
  TestValidator.predicate("deleted_at should be set")(typeof deletedLink.deleted_at === "string" && deletedLink.deleted_at.length > 0);

  // 5. Repeat delete should be idempotent/handled gracefully
  await TestValidator.error("repeat delete does not throw critical error")(
    () => api.functional.shoppingMallAiBackend.customer.customers.externalLinks.erase(connection, {
      customerId,
      externalLinkId: externalLink.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerExternalLink } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerExternalLink";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * E2E test to verify that customers cannot delete other customers' external links.
 *
 * This test checks for correct authorization logic by attempting cross-account deletion of an OAuth/social link. It confirms both the appropriate access-denied error and link persistence.
 *
 * Workflow:
 * 1. Register Customer A (the link owner) and capture their credentials/token
 * 2. Register Customer B (the attacker) and capture their credentials/token
 * 3. As Customer A, create an external link
 * 4. Switch to Customer B's context (using their credentials/token)
 * 5. Attempt to delete Customer A's external link as Customer B (should fail with access error)
 * 6. Verify the external link for Customer A still exists (was NOT deleted)
 */
export async function test_api_customer_external_link_delete_permission_denied(connection: api.IConnection) {
  // 1. Register Customer A (owner of the external link)
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const ownerPassword = "Password123!";
  const ownerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: ownerEmail,
      password: ownerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(ownerSignUp);
  const ownerId = ownerSignUp.customer.id;

  // 2. Register Customer B (attempting attacker)
  const attackerEmail = typia.random<string & tags.Format<"email">>();
  const attackerPassword = "Password456!";
  const attackerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: attackerEmail,
      password: attackerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(attackerSignUp);

  // 3. As Customer A, create an external link (without nulls for fields not allowed to be null)
  const externalLink = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(connection, {
    customerId: ownerId,
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      provider: "github",
      external_id: RandomGenerator.alphaNumeric(16),
      linked_at: new Date().toISOString(),
      last_auth_at: new Date().toISOString(),
      // metadata_json, deleted_at omitted
    },
  });
  typia.assert(externalLink);
  const externalLinkId = externalLink.id;

  // 4. Switch to Customer B's context (simulate by setting Authorization header)
  connection.headers = {
    ...connection.headers,
    Authorization: attackerSignUp.setHeaders.Authorization,
  };

  // 5. Attempt cross-user deletion (should fail with permission error)
  await TestValidator.error("permission denied for external link delete")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.erase(connection, {
        customerId: ownerId,
        externalLinkId: externalLinkId,
      });
    },
  );

  // 6. Verify the external link was NOT deleted (should still exist and not soft-deleted)
  connection.headers = {
    ...connection.headers,
    Authorization: ownerSignUp.setHeaders.Authorization,
  };
  const after = await api.functional.shoppingMallAiBackend.customer.customers.externalLinks.update(connection, {
    customerId: ownerId,
    body: {
      id: externalLinkId,
    },
  });
  typia.assert(after);
  TestValidator.equals("external link not deleted")(after.deleted_at)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerHistory";
import type { IPageIShoppingMallAiBackendCustomerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate admin retrieval of paginated and filtered customer audit/history events.
 *
 * This test ensures that after registering both an admin and a customer (and thereby generating some history events), the admin can:
 * 1. Query all audit/history events for the target customer via the admin endpoint (search/paginate).
 * 2. Use filtering by event_type (e.g., 'created') and a time window (occurred_from/to), confirming that results:
 *    - Only show events for the correct customer
 *    - Include correct event type (if filtered)
 *    - Occurred within the specified time window (if filtered)
 *    - Include all required audit metadata fields (id, occurred_at, triggered_by, etc)
 *    - Pagination metadata (page, limit, etc.) matches the request
 * 3. Attempt to access the endpoint as a non-admin (customer) and confirm access is denied (error thrown).
 *
 * Steps:
 * 1. Register an admin (capture Authorization header so all following requests are as ADMIN).
 * 2. Register a customer (capture the customer ID and know that 'created' event(s) are generated).
 * 3. As ADMIN, fetch history events for the customer, paginated (e.g., limit=5 on page 1).
 * 4. Validate all events belong to the customer and pagination is correct.
 * 5. Filter for event_type='created'. Validate only 'created' events are returned.
 * 6. Filter by a time window that should include only registration (joined_at .. joined_at+10min).
 * 7. As CUSTOMER, attempt the same call and verify that access is denied (error is thrown).
 */
export async function test_api_admin_customer_history_search_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'adminP@ss1!';
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Register a customer
  const customerEmail = typia.random<string & tags.Format<'email'>>();
  const customerPassword = 'customerP@ss01!';
  const signUpReq = {
    email: customerEmail,
    password: customerPassword,
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphaNumeric(8),
    phone: RandomGenerator.mobile(),
  } satisfies ICustomerSignUp.Request;
  const customerSignUpRes = await api.functional.auth.customer.register.signUp(connection, { body: signUpReq });
  typia.assert(customerSignUpRes);
  const customerId = customerSignUpRes.customer.id;

  // 3. As ADMIN, get full history events for this customer, with pagination
  // Switch Authorization to admin
  connection.headers = { ...connection.headers, Authorization: adminSignUp.setHeaders.Authorization };
  const pageLimit = 5;
  const page1Histories = await api.functional.shoppingMallAiBackend.admin.customers.histories.search(connection, {
    customerId,
    body: {
      customer_id: customerId,
      limit: pageLimit,
      page: 1,
    },
  });
  typia.assert(page1Histories);
  // Check: Pagination size matches
  TestValidator.equals('limit')(page1Histories.pagination.limit)(pageLimit);
  // All events must be for this customer
  for (const hist of page1Histories.data) {
    TestValidator.equals('customer id')(hist.customer_id)(customerId);
  }

  // 4. Filter by event_type = 'created'—registration always generates at least a 'created' event
  const byCreated = await api.functional.shoppingMallAiBackend.admin.customers.histories.search(connection, {
    customerId,
    body: {
      customer_id: customerId,
      event_type: 'created',
    },
  });
  typia.assert(byCreated);
  for (const hist of byCreated.data) {
    TestValidator.equals('only created')(hist.event_type)('created');
    TestValidator.equals('customer id')(hist.customer_id)(customerId);
  }

  // 5. Filter by a tight time window around registration (joined_at±10min)
  const joinedAt = customerSignUpRes.customer.joined_at;
  const occurredFrom = joinedAt;
  const occurredTo = new Date(new Date(joinedAt).getTime() + 10 * 60 * 1000).toISOString(); // joined_at + 10min
  const byTime = await api.functional.shoppingMallAiBackend.admin.customers.histories.search(connection, {
    customerId,
    body: {
      customer_id: customerId,
      occurred_from: occurredFrom,
      occurred_to: occurredTo,
    },
  });
  typia.assert(byTime);
  for (const hist of byTime.data) {
    TestValidator.predicate('within window')(
      new Date(hist.occurred_at) >= new Date(occurredFrom) && new Date(hist.occurred_at) <= new Date(occurredTo)
    );
    TestValidator.equals('customer id')(hist.customer_id)(customerId);
  }

  // 6. As CUSTOMER, attempt to call the admin history endpoint (should be forbidden)
  connection.headers = { ...connection.headers, Authorization: customerSignUpRes.setHeaders.Authorization };
  await TestValidator.error('customer forbidden')(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.histories.search(connection, {
      customerId,
      body: {
        customer_id: customerId,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerHistory";
import type { IPageIShoppingMallAiBackendCustomerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate RBAC and privacy enforcement for customer audit history search (admin endpoint).
 *
 * This test ensures that:
 * - Admin users can successfully retrieve a customer's full lifecycle/audit history via the admin endpoint.
 * - Unprivileged customers cannot access the same endpoint or see other customers' audit history (permission denied).
 *
 * Steps:
 * 1. Register a new admin user (to act as privileged actor).
 * 2. Register a new customer user (target of audit fetch).
 * 3. As admin, fetch customer audit history using the correct endpoint. Expect data and correct structure.
 * 4. As customer, attempt to fetch own audit history via the admin endpoint. Expect a permission/RBAC authorization failure, confirming RBAC/privacy protection.
 */
export async function test_api_admin_customer_history_search_permission_enforcement(
  connection: api.IConnection,
) {
  // 1. Register an admin as allowed actor
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "1234!Admin";
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminSignup);

  // 2. Register a customer as target
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerPassword = "cUst0merpw!";
  const customerSignup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignup);

  // 3. As admin, fetch customer history (should succeed)
  connection.headers = { Authorization: adminSignup.setHeaders.Authorization };
  const adminHistory = await api.functional.shoppingMallAiBackend.admin.customers.histories.search(connection, {
    customerId: customerSignup.customer.id,
    body: {
      customer_id: customerSignup.customer.id,
      limit: 10,
      page: 1,
    },
  });
  typia.assert(adminHistory);
  TestValidator.predicate("admin can fetch history")(Array.isArray(adminHistory.data));

  // 4. As customer, attempt to access admin endpoint (should fail with RBAC/permission error)
  connection.headers = { Authorization: customerSignup.setHeaders.Authorization };
  await TestValidator.error("permission denied for customer")(async () => {
    await api.functional.shoppingMallAiBackend.admin.customers.histories.search(connection, {
      customerId: customerSignup.customer.id,
      body: {
        customer_id: customerSignup.customer.id,
        limit: 1,
        page: 1,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerHistory";
import type { IPageIShoppingMallAiBackendCustomerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that a customer can search and paginate their own account history (audit/compliance/profile events).
 *
 * Ensures:
 * - Registration creates at least one history (creation event).
 * - The customer can fetch their own full or filtered, paginated audit history.
 * - Filtering by event_type yields consistent results.
 * - Pagination returns unique, non-overlapping history event subsets.
 * - Attempting to access another customer's history is strictly forbidden.
 *
 * Steps:
 * 1. Register a customer (receiving JWT and customerId automatically)
 * 2. List their own full audit history with default filter (pagination, all events)
 * 3. If history available, filter by event_type and validate filter behavior
 * 4. If multiple pages, confirm no event overlaps between pages
 * 5. Attempt to search for history of a random other customer, and verify this is denied
 */
export async function test_api_customer_self_history_search_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register a customer to obtain JWT and customerId
  const signupInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword!1",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphaNumeric(10),
    phone: RandomGenerator.mobile(),
  } satisfies ICustomerSignUp.Request;
  const signupResponse = await api.functional.auth.customer.register.signUp(connection, { body: signupInput });
  typia.assert(signupResponse);
  const customer = signupResponse.customer;
  const customerId = customer.id;

  // 2. Query for full paginated history list for self
  const searchBody = {
    customer_id: customerId,
    limit: 10 as number & tags.Type<"int32">,
    page: 1 as number & tags.Type<"int32">,
  } satisfies IShoppingMallAiBackendCustomerHistory.IRequest;
  const page1 = await api.functional.shoppingMallAiBackend.customer.customers.histories.search(connection, {
    customerId,
    body: searchBody,
  });
  typia.assert(page1);
  // All events must belong to this customer
  for (const evt of page1.data) {
    TestValidator.equals("event.customer_id matches query")(evt.customer_id)(customerId);
  }

  // 3. If any history present, filter by event_type and check consistency
  if (page1.data.length > 0) {
    const filteredEventType = page1.data[0].event_type;
    const filtered = await api.functional.shoppingMallAiBackend.customer.customers.histories.search(connection, {
      customerId,
      body: {
        customer_id: customerId,
        event_type: filteredEventType,
        limit: 10 as number & tags.Type<"int32">,
        page: 1 as number & tags.Type<"int32">,
      },
    });
    typia.assert(filtered);
    for (const evt of filtered.data) {
      TestValidator.equals("filtered event_type matches")(evt.event_type)(filteredEventType);
    }
  }

  // 4. If enough events for pagination, fetch a second page and check for overlap
  if (page1.pagination.records > page1.data.length) {
    const page2 = await api.functional.shoppingMallAiBackend.customer.customers.histories.search(connection, {
      customerId,
      body: {
        customer_id: customerId,
        limit: 10 as number & tags.Type<"int32">,
        page: 2 as number & tags.Type<"int32">,
      },
    });
    typia.assert(page2);
    // Page 1 and Page 2 should not overlap
    const ids1 = new Set(page1.data.map((x) => x.id));
    for (const evt of page2.data) {
      if (ids1.has(evt.id)) {
        throw new Error("Pagination failed: overlapping history events between pages");
      }
    }
  }

  // 5. Try searching for another (random) customer's history, expect error
  const otherId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("should not permit querying history of another customer")(
    () => api.functional.shoppingMallAiBackend.customer.customers.histories.search(connection, {
      customerId: otherId,
      body: {
        customer_id: otherId,
        limit: 5 as number & tags.Type<"int32">,
        page: 1 as number & tags.Type<"int32">,
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerHistory";
import type { IPageIShoppingMallAiBackendCustomerHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that a customer cannot access another customer's account history via the customer endpoint, enforcing strict permission.
 *
 * This test simulates two distinct customers using the customer API:
 * 1. Register two separate customer accounts (customerA and customerB).
 * 2. With customerA (active session), attempt to view the account history for customerB.
 * 3. The system must deny permission—history data for customerB must not be accessible to customerA under any scenario. No sensitive data should be returned.
 *
 * Steps:
 * 1. Register customerA. (JWT authorization for customerA is set)
 * 2. Register customerB. (JWT for customerB, but session remains as customerB after registration!)
