/**
 * Validate that an admin can update any customer cart item, enforcing permission and business rules.
 *
 * **Purpose:**
 * Ensure that the admin can successfully update a cart item in any customer's cart, including fields such as quantity, product_option_id, and note. Changes must be visible to both admin and customer, and only allowed fields should be mutable.
 *
 * **Steps:**
 * 1. Register a new customer (gathers customerId/JWT for cart ownership).
 * 2. Customer creates a new cart (get cartId).
 * 3. Customer adds a cart item (get cartItemId, and associated product/product_option context).
 * 4. Register a new admin (obtain admin JWT and session context).
 * 5. Admin updates the cart item (modify quantity or product_option_id, and optionally note).
 * 6. Assert the update succeeded:
 *    a. All updated fields (quantity, note, product_option_id as applicable) reflect the new values.
 *    b. The updated_at field is newer than prior value; created_at remains unchanged.
 *    c. No immutable fields (cartId, product_id, unit_price, etc.) have changed.
 *    d. The updated cart item can be loaded via both admin context and (optionally) via the customer context to confirm visibility and integrity.
 */
export async function test_api_cart_item_update_by_admin_success_and_permission_control(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = RandomGenerator.alphaNumeric(12);
  const customerSignup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerSignup);
  const customerId = customerSignup.customer.id;

  // Switch connection to use customer JWT for customer actions
  connection.headers = {
    ...connection.headers,
    Authorization: customerSignup.setHeaders.Authorization
  };

  // 2. Customer creates new cart
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
    body: {
      // Typically, status is 'active', session_token is null for regular accounts
      status: "active",
      session_token: null
    } satisfies IShoppingMallAiBackendCart.ICreate
  });
  typia.assert(cart);
  const cartId = cart.id;

  // 3. Customer adds a cart item
  const productId = typia.random<string & tags.Format<"uuid">>();
  // Optionally, possibly use a product_option_id, or null if not applicable
  const productOptionId = Math.random() < 0.5 ? typia.random<string & tags.Format<"uuid">>() : null;
  const cartItemInput: IShoppingMallAiBackendCartItem.ICreate = {
    product_id: productId,
    product_option_id: productOptionId,
    quantity: 2,
    unit_price: 19900,
    currency_code: "KRW",
    note: "initial insert by customer"
  };
  const cartItem = await api.functional.shoppingMallAiBackend.customer.carts.cartItems.create(connection, {
    cartId,
    body: cartItemInput
  });
  typia.assert(cartItem);

  // Capture state before update
  const prevUpdatedAt = cartItem.updated_at;
  const prevCreatedAt = cartItem.created_at;
  const prevProductId = cartItem.product_id;
  const prevUnitPrice = cartItem.unit_price;
  const prevCurrencyCode = cartItem.currency_code;

  // 4. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(14);
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminSignup);

  // Switch connection to use admin JWT for admin actions
  connection.headers = {
    ...connection.headers,
    Authorization: adminSignup.setHeaders.Authorization
  };

  // 5. Prepare new values for cart item update
  const newQuantity = cartItem.quantity + 1;
  // Change option (inverts assignment to cover field) or toggles null if previously non-null for edge case
  const newProductOptionId = cartItem.product_option_id
    ? null
    : typia.random<string & tags.Format<"uuid">>();
  const newNote = "updated by admin for validation";

  // 6. Admin updates the cart item
  const updatedCartItem = await api.functional.shoppingMallAiBackend.admin.carts.cartItems.update(connection, {
    cartId,
    cartItemId: cartItem.id,
    body: {
      quantity: newQuantity,
      product_option_id: newProductOptionId,
      note: newNote
    } satisfies IShoppingMallAiBackendCartItem.IUpdate
  });
  typia.assert(updatedCartItem);

  // Assert allowed fields are updated and correct
  TestValidator.equals("quantity updated")(updatedCartItem.quantity)(newQuantity);
  TestValidator.equals("note updated")(updatedCartItem.note)(newNote);
  TestValidator.equals("option updated")(updatedCartItem.product_option_id)(newProductOptionId);

  // Assert immutable fields are unchanged
  TestValidator.equals("product_id immutable")(updatedCartItem.product_id)(prevProductId);
  TestValidator.equals("unit_price immutable")(updatedCartItem.unit_price)(prevUnitPrice);
  TestValidator.equals("currency_code immutable")(updatedCartItem.currency_code)(prevCurrencyCode);
  TestValidator.equals("created_at unchanged")(updatedCartItem.created_at)(prevCreatedAt);

  // updated_at must be newer than previous value
  TestValidator.predicate("updated_at is after prior")(new Date(updatedCartItem.updated_at).getTime() > new Date(prevUpdatedAt).getTime());

  // Check visibility/integrity for both roles: Switch back to customer
  connection.headers = {
    ...connection.headers,
    Authorization: customerSignup.setHeaders.Authorization
  };

  // (If a 'get cart item' exists for customer context, could re-fetch and check; here, we simply check JWT switch and test could be expanded)
}

