import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IShoppingMallAiBackendCartSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartSnapshot";
import type { IPageIShoppingMallAiBackendCartSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCartSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validates pagination and filtering for a customer's cart snapshot search endpoint.
 *
 * Business context: Cart snapshots serve as crucial audit and rollback entities, allowing support and compliance for a customer's shopping history. This E2E test ensures a customer can retrieve only their own cart's snapshot records, and that the API's filtering and pagination features work as intended.
 *
 * Test Steps:
 * 1. Register a customer (for authentication and access control).
 * 2. Create a cart associated with that customer.
 * 3. Generate several snapshots for that cart, each with distinct snapshot reasons and creation timestamps.
 * 4. Test the search endpoint with:
 *    a. No filters (get all snapshots, verify completeness, audit integrity).
 *    b. Reason substring filter (e.g., substring match on snapshot_reason).
 *    c. Date range filters (created_at_from/to - test boundaries and subsets).
 *    d. Pagination (page & limit) - verify correct segments and paging details.
 * 5. For each response, assert:
 *    - Only the target cart's records are returned
 *    - Filtering reduces the set as expected
 *    - Pagination gives correct window & meta info
 *    - Records have correct audit fields populated (id, cart_id, created_at)
 *    - No snapshots for other carts are included (ownership respected)
 */
export async function test_api_cart_snapshots_paginated_search_success_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register a customer for authentication/ownership
  const email: string = typia.random<string & tags.Format<"email">>();
  const password = "Test1234!";
  const nickname = RandomGenerator.name();
  const customerSignUp = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email,
        password,
        name: RandomGenerator.name(),
        nickname,
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );
  typia.assert(customerSignUp);
  TestValidator.equals("customer email matches")(customerSignUp.customer.email)(email);

  // 2. Create a cart for the customer
  const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(
    connection,
    {
      body: {
        status: "active",
        session_token: null,
      } satisfies IShoppingMallAiBackendCart.ICreate,
    },
  );
  typia.assert(cart);

  // 3. Generate several snapshots for the cart, with varied reasons/times
  // We'll create 5+ snapshots with distinguishable snapshot_reasons and spaced-out created_at
  const reasons = [
    "init",
    "add_item",
    "remove_item",
    "checkout",
    "manual_save",
  ];
  const baseCartState = JSON.stringify(cart);
  const now = new Date();
  const snapshots = [] as IShoppingMallAiBackendCartSnapshot[];
  for (let i = 0; i < reasons.length; ++i) {
    // Fake snapshot timestamp increasing by 1 minute per entry
    const snapshot = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.create(
      connection,
      {
        cartId: cart.id,
        body: {
          cart_id: cart.id,
          snapshot_json: baseCartState,
          snapshot_reason: reasons[i],
        } satisfies IShoppingMallAiBackendCartSnapshot.ICreate,
      },
    );
    typia.assert(snapshot);
    // Patch audit field for simulation's sake...
    snapshot.created_at = new Date(now.getTime() + i * 60_000).toISOString() as string & tags.Format<"date-time">;
    snapshots.push(snapshot);
  }

  // Sort snapshots by created_at ascending for search expectations
  const snapByTime = [...snapshots].sort((a, b) => (a.created_at > b.created_at ? 1 : -1));

  // 4a. Search snapshots for this cartId (no filter): get all
  const allResult = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.search(
    connection,
    {
      cartId: cart.id,
      body: {
        cart_id: cart.id,
      } satisfies IShoppingMallAiBackendCartSnapshot.IRequest,
    },
  );
  typia.assert(allResult);
  // Validate audit fields & record count
  TestValidator.equals("record count matches full list")(allResult.data.length)(snapshots.length);
  allResult.data.forEach((snap) => {
    TestValidator.equals("cart id matches")(snap.cart_id)(cart.id);
    TestValidator.predicate("has id")(typeof snap.id === "string" && snap.id.length > 0);
    TestValidator.predicate("has created_at")(!!snap.created_at);
  });

  // 4b. Search with substring filter on snapshot_reason
  const reasonQuery = "add"; // Should match "add_item"
  const byReason = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.search(
    connection,
    {
      cartId: cart.id,
      body: {
        cart_id: cart.id,
        snapshot_reason: reasonQuery,
      } satisfies IShoppingMallAiBackendCartSnapshot.IRequest,
    },
  );
  typia.assert(byReason);
  byReason.data.forEach((snap) => {
    TestValidator.predicate("reason substring match")(snap.snapshot_reason.includes(reasonQuery));
  });
  TestValidator.predicate("filtered subset is smaller or equal")(
    byReason.data.length <= snapshots.length,
  );

  // 4c. Search within date range - only 2nd, 3rd snapshot (by created_at)
  const rangeStart = snapByTime[1].created_at; // 2nd snapshot's time
  const rangeEnd = snapByTime[2].created_at; // 3rd snapshot's time
  const byDate = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.search(
    connection,
    {
      cartId: cart.id,
      body: {
        cart_id: cart.id,
        created_at_from: rangeStart,
        created_at_to: rangeEnd,
      } satisfies IShoppingMallAiBackendCartSnapshot.IRequest,
    },
  );
  typia.assert(byDate);
  byDate.data.forEach((snap) => {
    TestValidator.predicate("in range - from")(
      snap.created_at >= rangeStart,
    );
    TestValidator.predicate("in range - to")(
      snap.created_at <= rangeEnd,
    );
  });

  // 4d. Pagination: page 2, limit 2
  const pageSize = 2;
  const pageNum = 2;
  const pagedResult = await api.functional.shoppingMallAiBackend.customer.carts.cartSnapshots.search(
    connection,
    {
      cartId: cart.id,
      body: {
        cart_id: cart.id,
        page: pageNum,
        limit: pageSize,
      } satisfies IShoppingMallAiBackendCartSnapshot.IRequest,
    },
  );
  typia.assert(pagedResult);
  TestValidator.equals("page number")(pagedResult.pagination.current)(pageNum);
  TestValidator.equals("page limit")(pagedResult.pagination.limit)(pageSize);
  // Slice local and compare results
  const localSlice = snapByTime.slice((pageNum - 1) * pageSize, pageNum * pageSize);
  TestValidator.equals("page data matches slice")(pagedResult.data.length)(localSlice.length);
  for (let i = 0; i < localSlice.length; ++i) {
    TestValidator.equals("snapshot matches")(pagedResult.data[i].id)(localSlice[i].id);
  }

  // 5. Security: Snapshots only from customer's own cart; not cross-user tested (single user in scenario)
}

