import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendModerationEvent";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test the immutability enforcement of moderation event fields via the admin backend API.
 *
 * This test verifies that attempts to update immutable/modifiable-restricted fields (such as event_type and created_at)
 * in a moderation event are properly blocked at the API or business logic layer. The workflow simulates real-world admin
 * moderation actions, and robustly checks both error handling and immutability guarantee for audit-trace and compliance integrity.
 *
 * Test Workflow:
 * 1. Register and authenticate a new admin. Save adminId for audit linkage.
 * 2. As that admin, create a moderation event for a synthetic review/inquiry (randomly generate required IDs for a valid request).
 * 3. Attempt to update the moderation event, but include forbidden fields (event_type, created_at) in the update body (via direct fetch workaround, since the SDK/DTO only allow modifiable keys). Expect the API or server to block the update.
 * 4. Confirm via error assertion (TestValidator.error) that the API rejects the update, and that the moderation event record’s original
 *    immutable fields remain unchanged after reloading.
 *
 * This test is critical for legal/audit compliance and defensible trace of moderation actions, ensuring no admin can illicitly
 * rewrite the type or origin of a moderation action after its creation.
 */
export async function test_api_moderation_event_update_immutable_field_failure(connection: api.IConnection) {
  // 1. Register and authenticate a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Passw0rd!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminSignUp);
  const adminId = adminSignUp.adminId;

  // 2. Create a moderation event as the authenticated admin
  const eventType = "block"; // Example event_type
  const createBody = {
    actor_id: adminId,
    event_type: eventType,
    reason: "Initial moderation action.",
    target_inquiry_id: Math.random() > 0.5
      ? typia.random<string & tags.Format<"uuid">>()
      : null,
    target_review_id: Math.random() > 0.5
      ? typia.random<string & tags.Format<"uuid">>()
      : null,
    attached_ai_evidence_id: null,
    referenced_event_id: null,
  } satisfies IShoppingMallAiBackendModerationEvent.ICreate;
  // Ensure at least one of target_inquiry_id or target_review_id is not null
  if (createBody.target_inquiry_id == null && createBody.target_review_id == null) {
    createBody.target_review_id = typia.random<string & tags.Format<"uuid">>()
  }
  const moderationEvent = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, { body: createBody });
  typia.assert(moderationEvent);

  // 3. Attempt to update forbidden/immutable fields by manual fetch (workaround the DTO/type safety) and expect error
  const forbiddenUpdate = {
    reason: "Illicit field update.",
    event_type: "unblock", // Forbidden change
    created_at: new Date(Date.now() + 123456).toISOString(), // Forbidden change
  };
  await TestValidator.error("modification of immutable fields must fail")(async () => {
    await fetch(
      `${connection.host}/shoppingMallAiBackend/admin/moderationEvents/${moderationEvent.id}`,
      {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          ...(connection.headers ?? {}),
        },
        body: JSON.stringify(forbiddenUpdate),
      },
    ).then(async r => {
      if (r.ok) {
        throw new Error("API allowed forbidden field update!");
      }
    });
  });

  // 4. Confirm the moderation event’s immutable fields remain unchanged
  const refreshedEvent = await api.functional.shoppingMallAiBackend.admin.moderationEvents.update(connection, {
    moderationEventId: moderationEvent.id,
    body: {},
  });
  typia.assert(refreshedEvent);
  TestValidator.equals("event_type remains unchanged")(refreshedEvent.event_type)(eventType);
  TestValidator.equals("created_at remains unchanged")(refreshedEvent.created_at)(moderationEvent.created_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendModerationEvent";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate soft-deletion (erase) of a moderation event by an authorized admin.
 *
 * This function ensures compliance/audit trace of moderation event lifecycle—creation to soft-deletion—by an admin account. It guarantees only admins can erase events, that soft-deletion triggers necessary compliance states, and validates idempotency business rules.
 *
 * Steps:
 * 1. Register a new admin via /auth/admin/register. Use valid unique email/password for SignUp (IAdminAuth.SignUp). Assert successful registration and extract admin ID.
 * 2. Using the authenticated session (Authorization provided by signUp setHeaders or jwt), create a valid moderation event using /shoppingMallAiBackend/admin/moderationEvents (ICreate body).
 *    - Use the admin's ID as actor_id. At least one of target_inquiry_id or target_review_id must be set (choose target_inquiry_id randomly and set target_review_id null for this test).
 *    - Provide a realistic event_type (e.g. "block"), and reason/description per ICreate requirements.
 *    - Assert creation success, capture the moderation event id.
 * 3. Call the erase (DELETE) API on /shoppingMallAiBackend/admin/moderationEvents/{moderationEventId} using the id from above.
 *    - Assert no content is returned and request does not throw.
 * 4. Repeat deletion: validate that a repeated DELETE on the same moderationEventId is idempotent or yields not-found (per API design).
 */
export async function test_api_moderation_event_erase_success(
  connection: api.IConnection,
) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPwd!234";
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminReg);
  const adminId = adminReg.adminId;

  // 2. Create moderation event as admin
  const moderationEventCreateInput = {
    actor_id: adminId,
    target_inquiry_id: typia.random<string & tags.Format<"uuid">>(),
    target_review_id: null,
    event_type: "block",
    reason: "prohibited content",
    attached_ai_evidence_id: null,
    referenced_event_id: null,
  } satisfies IShoppingMallAiBackendModerationEvent.ICreate;

  const createdEvent = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
    body: moderationEventCreateInput,
  });
  typia.assert(createdEvent);

  // 3. Erase (soft-delete) the moderation event
  await api.functional.shoppingMallAiBackend.admin.moderationEvents.erase(connection, {
    moderationEventId: createdEvent.id,
  });

  // 4. Repeat deletion (should be idempotent or return not-found)
  await TestValidator.error("second erase is idempotent or returns not-found")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.moderationEvents.erase(connection, {
        moderationEventId: createdEvent.id,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendModerationEvent";
import type { IShoppingMallAiBackendAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAppeal";
import type { IPageIShoppingMallAiBackendAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAppeal";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate paginated, filtered retrieval of appeal records by an admin.
 *
 * This test verifies that an admin can search for moderation appeals using multiple advanced filters
 * —such as status, appellant ID, decision comment, and a precise date range—while ensuring correct
 * pagination and compliant result sets. Key workflow steps:
 *
 * 1. Register and authenticate as an admin (for audit and permission scope)
 * 2. Create multiple moderation events (using admin endpoint), each with unique/traceable data
 * 3. Submit several appeals referencing those moderation events (imitating customer submissions)
 * 4. As admin, perform a variety of PATCH /shoppingMallAiBackend/admin/appeals invocations:
 *    - Filter by status (pending, approved, rejected)
 *    - Filter by appellant_id
 *    - Filter by part of decision_comment
 *    - Filter by creation date bounds (from_date, to_date as ISO8601)
 *    - Paginate and check per-page logic
 * 5. For each search, verify correct filter application and paging, and, where possible,
 *    check that appeals returned match filter criteria.
 *    Test will provide strong evidence of business and legal compliance audit behaviors.
 */
export async function test_api_appeal_search_filtered_pagination(connection: api.IConnection) {
  // 1. Admin registration (for full appeal search scope)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "P@ssw0rd123";
  const adminProfile = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminProfile);
  // (connection's Authorization token is implicitly set)

  // 2. Create several moderation events as the new admin
  const actorId = typia.random<string & tags.Format<"uuid">>();
  const inquiryIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const events: IShoppingMallAiBackendModerationEvent[] = [];
  for (let i = 0; i < 3; ++i) {
    const event = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
      body: {
        actor_id: actorId,
        event_type: i === 0 ? "block" : i === 1 ? "warn" : "edit",
        target_inquiry_id: i < 2 ? inquiryIds[i] : null,
        target_review_id: i === 2 ? typia.random<string & tags.Format<"uuid">>() : null,
        reason: i === 1 ? "Not in line with guidelines" : i === 2 ? "Incorrectly flagged review" : null,
        attached_ai_evidence_id: null,
        referenced_event_id: null,
      } satisfies IShoppingMallAiBackendModerationEvent.ICreate,
    });
    typia.assert(event);
    events.push(event);
  }

  // 3. Create unique appeals for each event as a customer (stand-in: same appellantId)
  const appellantId = typia.random<string & tags.Format<"uuid">>();
  const appeals: IShoppingMallAiBackendAppeal[] = [];
  for (const [idx, modEvent] of events.entries()) {
    const status = (["pending", "approved", "rejected"] as const)[idx % 3];
    const decision_comment =
      idx === 1
        ? "Admin rejected previous block."
        : idx === 2
        ? "Final decision: inappropriate wording."
        : null;
    const appeal = await api.functional.shoppingMallAiBackend.customer.appeals.create(connection, {
      body: {
        moderation_event_id: modEvent.id,
        appellant_id: appellantId,
        status,
        decision_comment,
      } satisfies IShoppingMallAiBackendAppeal.ICreate,
    });
    typia.assert(appeal);
    appeals.push(appeal);
  }

  // 4. Admin search: various filters/pagination

  // (a) Filter by status (pending, approved, rejected): check each appeal returned
  for (const status of ["pending", "approved", "rejected"] as const) {
    const res = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, {
      body: { status },
    });
    typia.assert(res);
    TestValidator.predicate(`Each appeal is status = ${status}`)(res.data.every((a) => a.status === status));
  }

  // (b) Filter by appellant_id
  const resByAppellant = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, {
    body: { appellant_id: appellantId },
  });
  typia.assert(resByAppellant);
  TestValidator.predicate("Each appeal belongs to appellantId")(
    resByAppellant.data.every((a) => a.appellant_id === appellantId)
  );

  // (c) Filter by decision_comment substring
  for (const query of ["rejected", "Final decision"]) {
    const resByComment = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, {
      body: { decision_comment: query },
    });
    typia.assert(resByComment);
    TestValidator.predicate(`decision_comment contains '${query}'`)(
      resByComment.data.every((a) => a.decision_comment && a.decision_comment.includes(query))
    );
  }

  // (d) Filter by date window (all appeals, assuming just created)
  const fromDate = new Date(Date.now() - 86400000).toISOString();
  const toDate = new Date(Date.now() + 86400000).toISOString();
  const resByDate = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, {
    body: { from_date: fromDate, to_date: toDate },
  });
  typia.assert(resByDate);
  TestValidator.predicate("appeals created within date range")(
    resByDate.data.every((a) => a.created_at >= fromDate && a.created_at <= toDate)
  );

  // (e) Pagination test: limit/page combos
  const paged1 = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(paged1);
  TestValidator.equals("limit == 2")(paged1.pagination.limit)(2);
  TestValidator.equals("page == 1")(paged1.pagination.current)(1);

  if (paged1.pagination.pages > 1) {
    const paged2 = await api.functional.shoppingMallAiBackend.admin.appeals.search(connection, {
      body: { page: 2, limit: 2 },
    });
    typia.assert(paged2);
    TestValidator.equals("limit == 2")(paged2.pagination.limit)(2);
    TestValidator.equals("page == 2")(paged2.pagination.current)(2);
  }

  // 5. Audit/compliance confirmation (implicit: all auth actions/audited by design)
}

