import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendModerationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendModerationEvent";
import type { IShoppingMallAiBackendAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAppeal";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that an admin can retrieve the full details of a specific appeal record.
 *
 * This test simulates the complete compliance workflow for appeal detail access:
 * 1. Register an admin account to obtain privileges for creating moderation events and accessing all appeal details.
 * 2. The admin creates a moderation event (e.g., block, edit, etc.).
 * 3. An appeal is then registered by a user (here simulated by the admin, since only admin registration is exposed).
 * 4. Retrieve the appeal by its ID as the admin.
 * 5. Validate that all fields in the returned appeal record are present and not masked (status, moderation event linkage, appellant, decision_comment, audit timestamps, etc.).
 * 6. Optionally, confirm audit-eligibility by checking timestamps and presence of all business/trace fields.
 */
export async function test_api_appeal_detail_admin_access(connection: api.IConnection) {
  // 1. Register as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminT3stP@ss";
  const adminSignUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignUpRes);
  // the connection will have Authorization updated automatically
  const adminId = adminSignUpRes.adminId;

  // 2. Create a moderation event
  const moderationEvent = await api.functional.shoppingMallAiBackend.admin.moderationEvents.create(connection, {
    body: {
      actor_id: adminId,
      event_type: "block",
      target_inquiry_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IShoppingMallAiBackendModerationEvent.ICreate,
  });
  typia.assert(moderationEvent);
  TestValidator.equals("moderation actor matches admin")(moderationEvent.actor_id)(adminId);

  // 3. Register an appeal for the moderation event
  const appeal = await api.functional.shoppingMallAiBackend.customer.appeals.create(connection, {
    body: {
      moderation_event_id: moderationEvent.id,
      appellant_id: adminId,
      status: "pending",
    } satisfies IShoppingMallAiBackendAppeal.ICreate,
  });
  typia.assert(appeal);
  TestValidator.equals("appeal links moderation event")(appeal.moderation_event_id)(moderationEvent.id);
  TestValidator.equals("appellant matches admin")(appeal.appellant_id)(adminId);

  // 4. Retrieve the appeal details as admin
  const fetched = await api.functional.shoppingMallAiBackend.admin.appeals.at(connection, {
    appealId: appeal.id,
  });
  typia.assert(fetched);
  TestValidator.equals("appeal detail matches")(fetched.id)(appeal.id);

  // 5. Validate all major fields are present and not masked
  TestValidator.equals("status is preserved")(fetched.status)(appeal.status);
  TestValidator.equals("moderation event link")(fetched.moderation_event_id)(moderationEvent.id);
  TestValidator.equals("appellant")(fetched.appellant_id)(adminId);
  TestValidator.equals("decision_comment null initially")(fetched.decision_comment)(null);
  TestValidator.predicate("audit timestamps valid")(!!fetched.created_at && !!fetched.updated_at);
}

