 * 2. Create a customer order
 * 3. Create a payment for that order
 * 4. Create a payment log entry (POST)
 * 5. Update the payment log's allowed fields (PUT)
 * 6. Validate that only allowed fields change, and all identifiers are preserved
 */
export async function test_api_order_payment_log_update_success(connection: api.IConnection) {
