 *
 * Business context:
 * This test ensures that only permitted fields (log_context) of an order payment log can be updated by an admin, and attempts to update immutable fields (log_type, occurred_at) are blocked.
 * Audit and compliance correctness of payment log annotation is essential in financial workflows.
 *
 * Step-by-step process:
 * 1. Register and authenticate as an admin (to get Authorization for admin endpoints).
 * 2. Create a customer order with valid values.
 * 3. Create a payment for the order.
 * 4. Create a payment log for the payment via admin endpoint.
 * 5. Update the allowed log_context field (remark/annotation) of the log entry and verify change.
 * 6. Attempt to update forbidden (immutable) fields and verify such changes are not permitted by the API contract (typesystem), and thus test business error handling by structure only.
 */
export async function test_api_admin_order_payment_log_update_annote_success(connection: api.IConnection) {
  // 1. Register a new admin
