      occurred_at: new Date().toISOString(),
    } satisfies IShoppingMallAiBackendOrderPaymentLog.ICreate,
  });
  typia.assert(log);

  // 5. Update only the allowed field: log_context
  const newLogContext = `Admin annotation at ${new Date().toISOString()}`;
  const updatedLog = await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.orderPaymentLogs.update(connection, {
    orderId: order.id,
