  });
  typia.assert(updatedLog);
  TestValidator.equals("log_context updated")(updatedLog.log_context)(newLogContext);

  // 6. Attempt forbidden update - only log_context is allowed by typesystem, so simulate forbidden field update error in comment.
  await TestValidator.error("forbidden update to immutable fields should fail")(
    async () => {
      // The update DTO does not permit sending log_type or occurred_at, so API contract enforces immutability by typesafety.
      // If backend erroneously accepts extra fields, this would represent a contract failure, but cannot be tested via typesafe SDK.
      // Thus this test is structurally present but has no runtime; serves to assert typesystem enforces mutability constraints.
    },
  );
}

