/**
 * Validate successful retrieval of a compliance event detail by its unique identifier.
 *
 * This test verifies that an authorized admin can fetch all metadata for a created compliance event and that the returned data matches the originally created values. It also ensures authorization is required for access.
 *
 * Steps:
 * 1. Register a new admin for required authorization and use the returned Authorization header for all subsequent requests.
 * 2. Create a new compliance event as the authenticated admin, specifying unique values for event_type, actor_type, target_type, and optional payload fields. Retain all input values for later validation, and record the returned compliance event id.
 * 3. Fetch the compliance event with the newly created id using the /shoppingMallAiBackend/admin/complianceEvents/{complianceEventId} endpoint.
 * 4. Assert that all fields in the fetched response exactly match those in the created record, including id, event_type, actor_id (if present), actor_type, target_type, target_id (if present), event_payload, and created_at (to be ISO 8601 valid and within a reasonable offset of now).
 * 5. (Negative case) Attempt to fetch a compliance event without proper Authorization and ensure access is denied (error thrown).
 */
export async function test_api_compliance_event_get_successful(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecureP@ssw0rd!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(adminAuth);

  // 2. Create compliance event
  const eventCreate = {
    event_type: RandomGenerator.alphabets(12),
    actor_id: adminAuth.adminId,
    actor_type: "admin",
    target_type: RandomGenerator.alphabets(8),
    target_id: typia.random<string & tags.Format<"uuid">>(),
    event_payload: JSON.stringify({ info: RandomGenerator.paragraph()() }),
  } satisfies IShoppingMallAiBackendComplianceEvent.ICreate;
  const createdEvent = await api.functional.shoppingMallAiBackend.admin.complianceEvents.create(connection, {
    body: eventCreate
  });
  typia.assert(createdEvent);

  // 3. Fetch event by id
  const fetchedEvent = await api.functional.shoppingMallAiBackend.admin.complianceEvents.at(connection, {
    complianceEventId: createdEvent.id
  });
