  const snapshotInputs = ArrayUtil.repeat(5)((i) => {
    const reason = i % 2 === 0 ? "audit" : "incident";
    const snapshot_at = new Date(now.getTime() - i * 7 * 24 * 60 * 60 * 1000).toISOString();
    return {
      wallet_id: coinWallet.id,
      owner_admin_id: coinWallet.wallet_owner_admin_id!,
      wallet_type: coinWallet.wallet_type,
      wallet_status: coinWallet.wallet_status,
      wallet_address: coinWallet.wallet_address,
      wallet_label: coinWallet.wallet_label,
      security_code: coinWallet.security_code,
      snapshot_balance: 5000 + i * 1000,
      snapshot_reason: reason,
      snapshot_at,
    } satisfies IShoppingMallAiBackendCoinSnapshot.ICreate;
  });
  const snapshots = await ArrayUtil.asyncMap(snapshotInputs)(async (input) => {
    const snap = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.create(connection, {
      coinWalletId: coinWallet.id,
      body: input,
    });
    typia.assert(snap);
    return snap;
  });

  // 3. Search snapshots by reason 'audit', expect only those results
  const auditResult = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.search(connection, {
    coinWalletId: coinWallet.id,
    body: {
      wallet_id: coinWallet.id,
      snapshot_reason: "audit",
      page: 1,
      limit: 10,
      sort: "snapshot_at desc",
    },
  });
  typia.assert(auditResult);
  auditResult.data.forEach((snap) => {
    TestValidator.equals("reason is audit")(snap.snapshot_reason)("audit");
    TestValidator.equals("wallet matches")(snap.wallet_id)(coinWallet.id);
  });
  TestValidator.predicate("all audit results use reason=\"audit\"")(auditResult.data.every((s) => s.snapshot_reason === "audit"));
  // 4. Filter by snapshot_at (range for 3rd and 4th inserted)
  const from = snapshots[2].snapshot_at;
  const to = snapshots[3].snapshot_at;
  const rangeResult = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.search(connection, {
    coinWalletId: coinWallet.id,
    body: {
      wallet_id: coinWallet.id,
      snapshot_at_from: from,
      snapshot_at_to: to,
      limit: 10,
      page: 1,
      sort: "snapshot_at asc",
    },
  });
  typia.assert(rangeResult);
  TestValidator.predicate("all results in date range")(rangeResult.data.every((snap) => snap.snapshot_at >= from && snap.snapshot_at <= to));

  // 5. Pagination: page 1 and page 2 with limit=2
  const page1 = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.search(connection, {
    coinWalletId: coinWallet.id,
    body: {
      wallet_id: coinWallet.id,
      limit: 2,
      page: 1,
      sort: "snapshot_at desc",
    },
  });
  const page2 = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.search(connection, {
    coinWalletId: coinWallet.id,
    body: {
      wallet_id: coinWallet.id,
      limit: 2,
      page: 2,
      sort: "snapshot_at desc",
    },
  });
  typia.assert(page1);
  typia.assert(page2);
  TestValidator.equals("page1 2 elements")(page1.data.length)(2);
  TestValidator.equals("page2 2 elements")(page2.data.length)(2);
  TestValidator.equals("pagination limit")(page1.pagination.limit)(2);

  // 6. Schema compliance: check all mandatory snapshot fields in result
  page1.data.concat(page2.data).forEach((snap) => {
    TestValidator.predicate("has id")(!!snap.id);
    TestValidator.equals("wallet_id matches")(snap.wallet_id)(coinWallet.id);
    TestValidator.predicate("snapshot_reason populated")(typeof snap.snapshot_reason === "string" && snap.snapshot_reason.length > 0);
    TestValidator.predicate("snapshot_balance type")(typeof snap.snapshot_balance === "number");
    TestValidator.predicate("created_at present")(!!snap.created_at);
  });

  // 7. Unauthorized search attempt: no Authorization header
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers.Authorization;
  await TestValidator.error("unauthorized search must fail")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.coinSnapshots.search(unauthConnection, {
      coinWalletId: coinWallet.id,
      body: {
        wallet_id: coinWallet.id,
        limit: 1,
        page: 1,
      },
    });
  });
}

