  TestValidator.equals("wallet_status")(found.wallet_status)(wallet.wallet_status);
  TestValidator.equals("wallet_type")(found.wallet_type)(wallet.wallet_type);
  TestValidator.equals("wallet_address")(found.wallet_address)(wallet.wallet_address);
  // Audit fields
  TestValidator.equals("created_at present")(
    typeof found.created_at === "string" && found.created_at.length > 0
  )(true);
  TestValidator.equals("snapshot_at exact")(found.snapshot_at)(snapshotInput.snapshot_at);

  // 5. Attempt access as a non-admin (simulate by removing admin fields)
  const nonAdminConnection = { ...connection, headers: { ...connection.headers } };
