 * 3. Only the associated customer can access their notifications (searching as another should yield empty).
 * 4. Pagination works properly.
 *
 * Steps:
 * 1. Register new customer and get their JWT token for authenticated actions.
 * 2. Favorite a new random product as that customer.
 * 3. Create several favorite notifications attached to that favorite, varying type/channel/read.
 * 4. Run search with no filters (should yield all notifications for favorite product).
 * 5. Search with type/read/channel filters and check filtered output.
 * 6. Search with pagination (limit=2) and verify result page/paging.
 * 7. Attempt to search as another customer (or with other customer_id filter) and assert zero/no access.
 */
export async function test_api_favorite_notifications_search_for_customer(connection: api.IConnection) {
  // 1. Register a new customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "1234";
  const registerResp = await api.functional.auth.customer.register.signUp(connection, { body: {
    email,
    password,
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphaNumeric(8),
    phone: RandomGenerator.mobile(),
  }});
  typia.assert(registerResp);
  const customer = registerResp.customer;
  TestValidator.equals("email matches")(customer.email)(email);

  // Set Authorization header in connection for session authentication
  connection.headers = { ...connection.headers, Authorization: registerResp.setHeaders.Authorization };

  // 2. Create a favorite product for this customer
  const product_id = typia.random<string & tags.Format<"uuid">>();
  const favorite = await api.functional.shoppingMallAiBackend.customer.favoriteProducts.create(connection, {
    body: { product_id }
  });
  typia.assert(favorite);
  TestValidator.equals("favorite.owner matches customer")(favorite.customer_id)(customer.id);

  // 3. Create several favorite notifications linked to this favorite
  const notif1 = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, {
    body: {
      favorite_product_id: favorite.id,
      notification_type: "PRICE_DROP",
      notification_channel: "PUSH",
      read: false,
      delivery_metadata: null
    },
  });
  typia.assert(notif1);
  const notif2 = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, {
    body: {
      favorite_product_id: favorite.id,
      notification_type: "RESTOCK",
      notification_channel: "EMAIL",
      read: true,
      delivery_metadata: "Sent with tracking code"
    },
  });
  typia.assert(notif2);
  const notif3 = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.create(connection, {
    body: {
      favorite_product_id: favorite.id,
      notification_type: "PRICE_DROP",
      notification_channel: "PUSH",
      read: true,
      delivery_metadata: null
    },
  });
  typia.assert(notif3);

  // 4. Search for all notifications (no filter except product)
  const searchAll = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.search(connection, {
    body: { favorite_product_id: favorite.id }
  });
  typia.assert(searchAll);
  TestValidator.predicate("pagination: at least 3 records")(searchAll.pagination.records >= 3);
  TestValidator.equals("returned notifications >= 3")(searchAll.data.length >= 3)(true);

  // 5. Search filtered by notification_type only
  const priceDropOnly = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.search(connection, {
    body: {
      favorite_product_id: favorite.id,
      notification_type: "PRICE_DROP",
    }
  });
  typia.assert(priceDropOnly);
  for (const n of priceDropOnly.data)
    TestValidator.equals("notification_type filter")(n.notification_type)("PRICE_DROP");

  // 6. Search filtered by unread (read: false)
  const unreadOnly = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.search(connection, {
    body: {
      favorite_product_id: favorite.id,
      read: false,
    }
  });
  typia.assert(unreadOnly);
  for (const n of unreadOnly.data)
    TestValidator.equals("read should be false")(n.read)(false);

  // 7. Paginate with limit = 2
  const paged = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.search(connection, {
    body: {
      favorite_product_id: favorite.id,
      limit: 2,
    }
  });
  typia.assert(paged);
  TestValidator.equals("pagination.limit")(paged.pagination.limit)(2);
  TestValidator.predicate("pagination.pages >= 2")(paged.pagination.pages >= 2);

  // 8. Try searching notifications for a different customer
  const fakeCustomerId = typia.random<string & tags.Format<"uuid">>();
  const otherCustomerRes = await api.functional.shoppingMallAiBackend.customer.favoriteNotifications.search(connection, {
    body: { customer_id: fakeCustomerId }
  });
  typia.assert(otherCustomerRes);
  TestValidator.equals("no notifications for other customers")(otherCustomerRes.data.length)(0);
}

