import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validates the successful update of an order item by its owning customer.
 *
 * This test ensures that an authenticated customer can:
 *   1. Register and log in as a new customer (obtaining JWT).
 *   2. Create a new order referencing their customer ID.
 *   3. Add a new order item to that order, linking a random product/product_snapshot (using random UUIDs in absence of product API).
 *   4. Update permissible fields (quantity, note) for the order item.
 *   5. Confirm that the changes persist, and the response includes proper audit trail fields (created_at, updated_at change on update).
 *
 * Workflow:
 * 1. Sign up a new customer using the auth endpoint, capturing customer_id and JWT Authorization (connection mutation is automatic).
 * 2. Create an order for the customer (requires customer_id).
 * 3. Create an order item for that order using arbitrary product/product_snapshot UUIDs.
 * 4. Update the order item (change quantity and add a note).
 * 5. Assert that returned order item reflects changes,
 *    - That keys like "updated_at" are different from "created_at"
 *    - And "id", "order_id", etc., remain the same
 * 6. Confirm types as expected (typia.assert), and verify business logic via TestValidator.
 */
export async function test_api_customer_update_order_item_success(connection: api.IConnection) {
  // 1. Register new customer
  const signup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(signup);
  const customerId = signup.customer.id;

  // 2. Create new order for this customer
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerId,
      order_number: `ORD-${RandomGenerator.alphaNumeric(7)}`,
      total_amount: 12345,
      currency_code: "USD",
      current_status: "created"
    } satisfies IShoppingMallAiBackendOrder.ICreate
  });
  typia.assert(order);

  // 3. Add order item with random product/product_snapshot
  const productId = typia.random<string & tags.Format<"uuid">>();
  const productSnapshotId = typia.random<string & tags.Format<"uuid">>();
  const orderItem = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.create(connection, {
    orderId: order.id,
    body: {
      order_id: order.id,
      product_id: productId,
      product_snapshot_id: productSnapshotId,
      quantity: 2,
      unit_price: 1111,
      currency_code: "USD"
    } satisfies IShoppingMallAiBackendOrderItem.ICreate
  });
  typia.assert(orderItem);

  // 4. Update order item (change quantity and add note)
  const updatedQuantity = orderItem.quantity + 1;
  const updateNote = "Increase quantity for test.";
  const updated = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.update(connection, {
    orderId: order.id,
    orderItemId: orderItem.id,
    body: {
      quantity: updatedQuantity,
      note: updateNote
    } satisfies IShoppingMallAiBackendOrderItem.IUpdate
  });
  typia.assert(updated);

  // 5. Confirm persistent update and audit trail
  TestValidator.equals("id unchanged")(updated.id)(orderItem.id);
  TestValidator.equals("order_id unchanged")(updated.order_id)(orderItem.order_id);
  TestValidator.notEquals("quantity updated")(updated.quantity)(orderItem.quantity);
  TestValidator.equals("note applied")(updated.note)(updateNote);
  TestValidator.notEquals("updated_at is changed")(updated.updated_at)(orderItem.updated_at);
  TestValidator.equals("created_at stays")(updated.created_at)(orderItem.created_at);
}

