 *
 * Test necessity:
 * This E2E test ensures, at runtime, that only modifiable fields may be updated via the public API contract (TypeScript DTO).
 * Negative test cases involving forbidden fields are unimplementable at TypeScript level; attempting to include them results in compile-time errors—not runtime validation failures.
 *
 * Test workflow:
 * 1. Register an admin to obtain an admin session
 * 2. Create a new customer order
 * 3. Add an order item under this order
 * 4. Update the order item's allowed fields (e.g., quantity); assert update succeeds
 */
export async function test_api_admin_update_order_item_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Register admin and obtain session
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPass!123";
