      quantity: 2,
      unit_price: 5000,
      currency_code: "USD",
    } satisfies IShoppingMallAiBackendOrderItem.ICreate,
  });
  typia.assert(orderItem);

  // 4. Attempting to update forbidden fields (product_id, order_id, etc.) is impossible at the TypeScript type level.
  // Only allowed fields (quantity, note) exist on IUpdate. So only a positive update is tested here.

  // 5. Positive case: valid update succeeds
  const updated = await api.functional.shoppingMallAiBackend.admin.orders.orderItems.update(connection, {
