import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test: Admin can successfully soft-delete (erase) an order item from an order
 *
 * Business rationale:
 * Order items may need to be removed from a customer's order for various reasons (e.g. inventory issues, admin correction, customer changes, etc.), but should not be hard deleted for audit and compliance. Instead, a soft delete is performed: flagged by a 'deleted_at' timestamp, the item remains in storage for traceability but is excluded from normal retrieval/search endpoints. Only privileged admin operations should be able to perform this action.
 *
 * Test steps:
 * 1. Register a new admin via the admin registration endpoint
 * 2. Admin creates a customer order using the 'customer order create' endpoint
 * 3. Admin (or the customer) adds a new order item to that order
 * 4. Admin erases (soft deletes) the order item via the '/admin/orders/{orderId}/orderItems/{orderItemId}' DELETE endpoint
 * 5. Confirm the operation succeeds (no error)
 * 6. (If possible) retrieve the order item directly by ID or via a privileged API and verify:
 *    - The 'deleted_at' field is now set (not null)
 * 7. (If list/search endpoints were available): Verify the erased item is no longer present in normal listings (not possible with provided APIs)
 *
 * Constraints:
 * - All involved data (admin, order, order item) are freshly created and only exist within scope of this test
 * - The test focuses on the erase action and its business effects on data integrity
 * - Only use available SDK/API functions and DTOs supplied
 */
export async function test_api_admin_erase_order_item_success(connection: api.IConnection) {
  // 1. Register a new admin and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminP@ssw0rd";
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminReg); // Auth JWT/token is automatically managed in connection

  // 2. Create a customer order using valid random data (create as admin)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const orderCreate: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customerId,
    order_group_id: null,
    order_number: "ORD-" + Date.now().toString(),
    total_amount: 150.00,
    currency_code: "USD",
    note: "Test order for e2e soft delete",
    current_status: "created",
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderCreate });
  typia.assert(order);

  // 3. Add an order item to the order
  const orderItemCreate: IShoppingMallAiBackendOrderItem.ICreate = {
    order_id: order.id,
    product_id: typia.random<string & tags.Format<"uuid">>(),
    product_snapshot_id: typia.random<string & tags.Format<"uuid">>(),
    quantity: 2,
    unit_price: 75.00,
    currency_code: "USD",
    note: "Test order item for soft delete",
  };
  const orderItem = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.create(connection, { orderId: order.id, body: orderItemCreate });
