import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate customer order group search and pagination by filters.
 *
 * This test ensures that a customer can only retrieve and paginate their own order groups using available filters such as group_name and date range, and does not see other users' order groups. The test walks through full data setup and business isolation.
 *
 * Steps:
 * 1. Register a new customer, asserting successful sign-up and authentication.
 * 2. As admin, create multiple order groups, ensuring realistic variation in group_name and creation time.
 * 3. (Assumed: Each order group is only visible to a specific assigned customer -- but assignment logic not exposed; test logically restricts expectation to groups created in this isolated instance.)
 * 4. Switch connection back to the registered customer.
 * 5. Search using PATCH /shoppingMallAiBackend/customer/orderGroups with no filter, then with group_name partial, then date range.
 * 6. Validate that all retrieved order groups (in pagination) match the criteria and, where possible, that they belong to the correct authenticated user.
 * 7. Edge cases: Ensure that searching for non-existent group_name or date range yields empty results.
 *
 * Limitations:
 * - If API implementation allows customer to see only his/her own groups by design, only those will be visible.
 * - If group-to-customer mapping cannot be set in setup (as no such DTO or API exists for assignment), test only covers logical isolation by using unique naming/creation and verifying output matches setup.
 */
export async function test_api_customer_search_order_groups_basic(connection: api.IConnection) {
  // 1. Register a new customer
  const email = typia.random<string & tags.Format<"email">>();
  const nickname = RandomGenerator.name();
  const password = RandomGenerator.alphaNumeric(10);
  const customerSignUp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email,
      password,
      name: RandomGenerator.name(),
      nickname,
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerSignUp);
  TestValidator.equals("auth header set")(typeof customerSignUp.setHeaders.Authorization)("string");

  // 2. Create multiple order groups as admin (simulate different group_names and dates)
  const now = new Date();
  const groupNames = [RandomGenerator.alphabets(8), RandomGenerator.alphabets(8), RandomGenerator.alphabets(8)];
  const createdGroups = [];
  for (let i = 0; i < groupNames.length; ++i) {
    const created = await api.functional.shoppingMallAiBackend.admin.orderGroups.create(connection, {
      body: {
        group_name: groupNames[i],
        external_reference: `ref${i}_${RandomGenerator.alphaNumeric(5)}`,
        meta_info: null,
      } satisfies IShoppingMallAiBackendOrderGroup.ICreate
    });
    typia.assert(created);
    createdGroups.push(created);
    // Space out created_at for testing date range later
    await new Promise(r => setTimeout(r, 100));
  }

  // 3. As the registered customer, search for order groups using PATCH /shoppingMallAiBackend/customer/orderGroups
  // If session switch required, re-authenticate with customer JWT (assumed automatic via setHeaders.Authorization)
  // 3a. Search with no filters (should see all 3 just created in this clean test instance)
  const allGroupsRes = await api.functional.shoppingMallAiBackend.customer.orderGroups.index(connection, {
    body: {} satisfies IShoppingMallAiBackendOrderGroup.IRequest
  });
  typia.assert(allGroupsRes);
  TestValidator.predicate("all created groups visible")(allGroupsRes.data.length >= groupNames.length);
  const foundAllGroups = groupNames.every(nm => allGroupsRes.data.some(g => g.group_name === nm));
  TestValidator.predicate("all group names returned")(foundAllGroups);

  // 3b. Filter with group_name partial matching (choose one substring)
  const groupPartial = groupNames[0].substring(0, 4);
  const filterPartial = await api.functional.shoppingMallAiBackend.customer.orderGroups.index(connection, {
    body: { group_name: groupPartial } satisfies IShoppingMallAiBackendOrderGroup.IRequest
  });
  typia.assert(filterPartial);
  TestValidator.predicate("partial group_name filter matches at least 1")(filterPartial.data.length > 0);
  TestValidator.predicate("all returned group_names contain partial filter")(filterPartial.data.every(g => g.group_name.includes(groupPartial)));

  // 3c. Filter by date range covering only the latter 2 groups
  const fromDate = createdGroups[1].created_at;
  const toDate = createdGroups[2].created_at;
  const filterDate = await api.functional.shoppingMallAiBackend.customer.orderGroups.index(connection, {
    body: {
      created_at_gte: fromDate,
      created_at_lte: toDate,
    } satisfies IShoppingMallAiBackendOrderGroup.IRequest
  });
  typia.assert(filterDate);
  const validDateMatch = filterDate.data.every(grp => (grp.created_at >= fromDate && grp.created_at <= toDate));
  TestValidator.predicate("date range filter returns correct subset")(validDateMatch);

  // 4. Edge: Search for non-existent group_name
  const filterEmpty = await api.functional.shoppingMallAiBackend.customer.orderGroups.index(connection, {
    body: { group_name: "NoSuchGroupNameXYZ1234" } satisfies IShoppingMallAiBackendOrderGroup.IRequest
  });
  typia.assert(filterEmpty);
  TestValidator.equals("no results for nonexistent group_name")(filterEmpty.data.length)(0);

  // 5. Edge: Search with impossible date range
  const impossibleFrom = new Date(now.getTime() + 1000 * 60 * 60).toISOString();
  const impossibleTo = new Date(now.getTime() + 1000 * 60 * 120).toISOString();
  const impossibleRes = await api.functional.shoppingMallAiBackend.customer.orderGroups.index(connection, {
    body: { created_at_gte: impossibleFrom, created_at_lte: impossibleTo } satisfies IShoppingMallAiBackendOrderGroup.IRequest
  });
  typia.assert(impossibleRes);
  TestValidator.equals("no results for impossible date range")(impossibleRes.data.length)(0);
}

