  // 2. As mainSeller, register product
  connection.headers = { ...connection.headers, Authorization: mainSeller.setHeaders.Authorization };
  const productData: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: mainSeller.sellerId,
    code: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.paragraph()(3),
    description: RandomGenerator.paragraph()(10),
    status: "published",
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, { body: productData });
