  const inquiryData: IShoppingMallAiBackendProductInquiry.ICreate = {
    customer_id: customer.customer.id,
    product_id: product.id,
    title: RandomGenerator.paragraph()(2),
    body: RandomGenerator.paragraph()(8),
    public: true,
  };
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, { body: inquiryData });
  typia.assert(inquiry);
  // 5. As intruderSeller, attempt to access inquiry detail
  connection.headers = { ...connection.headers, Authorization: intruderSeller.setHeaders.Authorization };
  await TestValidator.error("Unauthorized seller cannot access other's product inquiry")(async () => {
    await api.functional.shoppingMallAiBackend.seller.productInquiries.at(connection, {
      productInquiryId: inquiry.id,
    });
  });
