import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that product inquiry creation fails for invalid or prohibited input scenarios.
 *
 * This test ensures that the customer cannot create a product inquiry in the following invalid situations:
 *   - Title is empty (violates required constraints)
 *   - Title contains prohibited/profane language
 *   - Title exceeds maximum length (over 200 bytes)
 *   - Body contains prohibited/profane language
 *   - Body exceeds plausible content size limits (simulate >10K chars)
 *
 * It checks that the API returns error responses in these cases and does not create a resource.
 * Scenarios relying on omitting required properties are skipped due to TypeScript type system constraints.
 *
 * Steps:
 * 1. Register a seller
 * 2. Register a product tied to that seller
 * 3. Register a customer (connection JWT will use this customer)
 * 4. Try to create a product inquiry with: empty title, profane title, profane body, too-long title, too-long body
 *    - Each should produce an error
 *    - No inquiry resource should be created in these cases
 */
export async function test_api_customer_product_inquiry_create_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Register a seller
  const sellerReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234abcd",
      companyName: RandomGenerator.name(),
      businessNumber: RandomGenerator.alphaNumeric(10),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(sellerReg);

  // 2. Register a product for the seller
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerReg.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    },
  });
  typia.assert(product);

  // 3. Register a customer (connection accepts new JWT after signup)
  const customerReg = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "customerPwd09!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerReg);

  // 4. Invalid inquiry: Title is empty string
  await TestValidator.error("should fail when title is empty")(() =>
    api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
      body: {
        customer_id: customerReg.customer.id,
        product_id: product.id,
        title: "",
        body: "Test body is fine.",
        public: true,
      },
    })
  );

  // 5. Invalid inquiry: Profane word in title
  await TestValidator.error("should fail for profane title")(() =>
    api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
      body: {
        customer_id: customerReg.customer.id,
        product_id: product.id,
        title: "fuck this product?",
        body: "Is this product available?",
        public: true,
      },
    })
  );

  // 6. Invalid inquiry: Profane word in body
  await TestValidator.error("should fail for profane body")(() =>
    api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
      body: {
        customer_id: customerReg.customer.id,
        product_id: product.id,
        title: "Inquiry about price",
        body: "Why is this shit so expensive?",
        public: true,
      },
    })
  );

  // 7. Invalid inquiry: Title exceeds 200 bytes (simulate by 201+ chars)
  await TestValidator.error("should fail when title exceeds 200 bytes")(() =>
    api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
      body: {
        customer_id: customerReg.customer.id,
        product_id: product.id,
        title: "A".repeat(201),
        body: "Test body.",
        public: true,
      },
    })
  );

  // 8. Invalid inquiry: Body content is excessively large (simulate >10,000 chars)
  await TestValidator.error("should fail when body exceeds plausible limit")(() =>
    api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
      body: {
        customer_id: customerReg.customer.id,
        product_id: product.id,
        title: "Normal Title",
        body: "B".repeat(10001),
        public: true,
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates prevention of duplicate product inquiries by the same customer.
 *
 * This test ensures the system does not allow a customer to submit
 * duplicate inquiries with the same content and product within the defined interval.
 * The test covers business workflow from account and product creation to duplicate
 * inquiry attempt and error validation.
 *
 * Step-by-step:
 * 1. Register a new seller to obtain a sellerId
 * 2. Create a product as the seller and get its productId
 * 3. Register a new customer (customerId is required for the inquiry payload)
 * 4. As the authenticated customer, submit a new inquiry for the product
 * 5. Immediately try to submit a second inquiry with identical content and for the same product
 * 6. Confirm the second attempt is rejected (either as duplicate or with rate limit error)
 * 7. Assert responses: success for first, error for second
 */
export async function test_api_customer_product_inquiry_create_duplicate_prevention(connection: api.IConnection) {
  // 1. Register Seller
  const sellerSignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "SellerPass1234#",
    companyName: RandomGenerator.name(),
    businessNumber: `${typia.random<number>()}`.padStart(10, "0"),
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(),
    phone: RandomGenerator.mobile(),
  } satisfies ISellerAuth.SignUp;
  const sellerAuthResp = await api.functional.auth.seller.register.signUp(connection, {
    body: sellerSignUp
  });
  typia.assert(sellerAuthResp);
  const sellerId = sellerAuthResp.sellerId;

  // 2. Register Product
  const productCreate = {
    seller_id: sellerId,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(),
    description: RandomGenerator.content()()(),
    main_image_uri: null,
    status: "published"
  } satisfies IShoppingMallAiBackendProduct.ICreate;
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: productCreate
  });
  typia.assert(product);
  const productId = product.id;

  // 3. Register Customer
  const customerSignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "CustomerPass4321#",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  } satisfies ICustomerSignUp.Request;
  const customerResp = await api.functional.auth.customer.register.signUp(connection, {
    body: customerSignUp,
  });
  typia.assert(customerResp);
  const customerId = customerResp.customer.id;

  // 4. Create inquiry (first try)
  const inquiryPayload = {
    customer_id: customerId,
    product_id: productId,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    public: true,
  } satisfies IShoppingMallAiBackendProductInquiry.ICreate;
  const inquiry1 = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: inquiryPayload,
  });
  typia.assert(inquiry1);
  TestValidator.equals("inquiry customer id is correct")(inquiry1.customer_id)(customerId);
  TestValidator.equals("inquiry product id is correct")(inquiry1.product_id)(productId);

  // 5. Try duplicate inquiry immediately
  await TestValidator.error("Duplicate inquiry for same product and customer should fail")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
        body: inquiryPayload,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates that the customer who created a product inquiry can update its mutable fields before the inquiry is answered or closed.
 *
 * Business context:
 * Customers can submit inquiries about products, which can later be edited by the inquiry author as long as the inquiry has not been answered or closed. Only allowable business fields (title, body, status, public) are mutable. All changes should be reflected in the inquiry and tracked by the workflow.
 *
 * Steps:
 * 1. Register a seller (to associate a product with)
 * 2. Seller creates a new product
 * 3. Register a customer
 * 4. Customer creates a product inquiry for the product
 * 5. Customer updates the inquiry with new values for title, body, public, and status
 * 6. Validate the updated fields are correctly changed in the returned inquiry object
 */
export async function test_api_customer_product_inquiry_update_owner_allowed(
  connection: api.IConnection,
) {
  // 1. Register seller for product association
  const seller_email = typia.random<string & tags.Format<"email">>();
  const seller_signup = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller_email,
      password: "Seller12345!",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller_signup);

  // 2. Seller creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: seller_signup.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 3. Customer registers
  const customer_email = typia.random<string & tags.Format<"email">>();
  const customer_signup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customer_email,
      password: "Customer12345!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customer_signup);
  // Switch to customer's Authorization
  connection.headers = { ...(connection.headers ?? {}), Authorization: customer_signup.setHeaders.Authorization };

  // 4. Customer creates a product inquiry
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customer_signup.customer.id,
      product_id: product.id,
      title: "Original Title",
      body: "Original inquiry content.",
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
  });
  typia.assert(inquiry);

  // 5. Update inquiry's allowed fields as author
  const updated_fields: IShoppingMallAiBackendProductInquiry.IUpdate = {
    title: "Updated Title",
    body: "Updated inquiry body.",
    public: false,
    status: "waiting",
  };
  const updated_inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: updated_fields,
  });
  typia.assert(updated_inquiry);

  // 6. Validate updated fields and immutables remain unchanged
  TestValidator.equals("updated title")(updated_inquiry.title)(updated_fields.title);
  TestValidator.equals("updated body")(updated_inquiry.body)(updated_fields.body);
  TestValidator.equals("public updated")(updated_inquiry.public)(updated_fields.public);
  TestValidator.equals("status updated")(updated_inquiry.status)(updated_fields.status);
  TestValidator.equals("customer invariant")(updated_inquiry.customer_id)(inquiry.customer_id);
  TestValidator.equals("product invariant")(updated_inquiry.product_id)(inquiry.product_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
