import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validate that product inquiry editing is forbidden to non-owners.
 *
 * This test ensures that only the customer who originally created a product inquiry can update it. If a different customer (non-owner) attempts to modify the inquiry, the system must deny the operation and return an error.
 *
 * **Business context:**
 * - Product inquiries are part of the shopping mall's compliance audit, and editing must be strictly controlled.
 * - Unauthorized editing could allow abuse or circumvention of audit/evidence.
 *
 * **Test workflow:**
 * 1. Register a new seller.
 * 2. Seller creates a product.
 * 3. Register Customer A (the owner of the inquiry).
 * 4. Customer A creates an inquiry on the product.
 * 5. Register Customer B (a different customer).
 * 6. Customer B attempts to update the inquiry created by Customer A — must fail.
 */
export async function test_api_customer_product_inquiry_update_forbidden_non_owner(connection: api.IConnection) {
  // 1. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "pw" + typia.random<string & tags.Pattern<"^[a-zA-Z0-9]{6,}">>();
  const sellerSignUp = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: RandomGenerator.name(),
      businessNumber: "" + (1000000000 + Math.floor(Math.random() * 8999999999)),
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(1),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUp);

  // 2. Seller creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerSignUp.sellerId,
      code: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.content()()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 3. Register Customer A (inquiry owner)
  const customerAEmail = typia.random<string & tags.Format<"email">>();
  const customerAPassword = "pw" + typia.random<string & tags.Pattern<"^[a-zA-Z0-9]{6,}">>();
  const customerA = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerAEmail,
      password: customerAPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerA);

  // 4. Customer A creates a product inquiry
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerA.customer.id,
      product_id: product.id,
      title: "Test Inquiry " + RandomGenerator.alphabets(4),
      body: RandomGenerator.content()()(),
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
  });
  typia.assert(inquiry);

  // 5. Register Customer B (not the inquiry owner)
  const customerBEmail = typia.random<string & tags.Format<"email">>();
  const customerBPassword = "pw" + typia.random<string & tags.Pattern<"^[a-zA-Z0-9]{6,}">>();
  const customerB = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerBEmail,
      password: customerBPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerB);

  // 6. Customer B attempts to update the inquiry made by Customer A (must be denied)
  await TestValidator.error("non-owner cannot update inquiry")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
        productInquiryId: inquiry.id,
        body: {
          title: "Attempted Illegal Update",
          body: "This should not succeed.",
          public: false,
          status: "waiting",
        } satisfies IShoppingMallAiBackendProductInquiry.IUpdate,
      });
    }
  );
}

