/**
 * Test seller order snapshot creation functionality with complete business flow and evidence validation.
 *
 * Business context: Verifies that a seller can create an immutable snapshot of an order for compliance and audit purposes. The test also checks that audit/evidence fields are stored and the order remains unmodified beyond the snapshot.
 *
 * Steps:
 * 1. Register and authenticate a new seller: Required for authorization and parent order ownership.
 * 2. Create (find) an order belonging to this seller using the seller orders search API (PATCH).
 * 3. Seller prepares snapshot creation request with serialized JSON and business reason.
 * 4. Seller calls the orderSnapshots.create API for the selected order.
 * 5. Validate that the response contains a new IShoppingMallAiBackendOrderSnapshot object:
 *    - order_id links to the correct order
 *    - snapshot_json and snapshot_reason reflect the request
 *    - created_at is an ISO 8601 timestamp
 *    - The snapshot contains the actual order data at the point-in-time
 * 6. Order remains unchanged except for the snapshot's existence; verify by searching with the unique order_number.
 */
export async function test_api_order_snapshot_creation_by_seller_success_with_audit_and_compliance_evidence(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new seller
  const sellerSignUpInput: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPassword1$",
    companyName: "Test AI Shop Co.",
    businessNumber: "1234567890",
    representativeName: "Alice Test",
    address: "321 Innovation Rd, Seoul",
    phone: "0212345678",
  };
  const seller: ISellerAuth.AuthResponseWithHeaders = await api.functional.auth.seller.register.signUp(connection, {
    body: sellerSignUpInput,
  });
  typia.assert(seller);

  // 2. Obtain a test order for this seller (using search)
  const orderResult = await api.functional.shoppingMallAiBackend.seller.orders.search(connection, {
    body: {
      page: 1,
      pageSize: 1,
    } satisfies IShoppingMallAiBackendOrder.IRequest,
  });
  typia.assert(orderResult);
  const orderList = orderResult.data;
  if (!orderList?.length) throw new Error("No available order for snapshot testing");
  const order = orderList[0];

  // 3. Prepare snapshot creation body
  const snapshotBody = {
    snapshot_json: JSON.stringify(order),
    snapshot_reason: "compliance-audit-test",
  } satisfies IShoppingMallAiBackendOrderSnapshot.ICreate;

  // 4. Seller creates the snapshot
  const snapshot = await api.functional.shoppingMallAiBackend.seller.orders.orderSnapshots.create(connection, {
    orderId: order.id,
    body: snapshotBody,
  });
  typia.assert(snapshot);

  // 5. Validate correctness and evidence fields
  TestValidator.equals("order_id links to order")(snapshot.order_id)(order.id);
  TestValidator.equals("snapshot_reason")(snapshot.snapshot_reason)(snapshotBody.snapshot_reason);
  TestValidator.predicate("created_at is ISO8601")(!!Date.parse(snapshot.created_at));
  const parsedSnapshot = JSON.parse(snapshot.snapshot_json);
  TestValidator.equals("Order in snapshot matches original order number")(parsedSnapshot.order_number)(order.order_number);

  // 6. Verify the order remains unchanged except snapshot presence
  const reCheck = await api.functional.shoppingMallAiBackend.seller.orders.search(connection, {
    body: {
      order_number: order.order_number,
    } satisfies IShoppingMallAiBackendOrder.IRequest,
  });
  typia.assert(reCheck);
  if (!reCheck.data.length || reCheck.data[0].id !== order.id)
    throw new Error("Original order missing or modified after snapshot!");
}

