import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IPageIShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrder";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderSnapshot";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that an admin can successfully update allowed metadata fields on a specific order snapshot, without changing immutable snapshot evidence fields.
 *
 * This test simulates a legal/compliance officer updating the justification or annotation on an archived order snapshot for regulatory purposes. It ensures only permitted metadata changes (like snapshot_reason) are allowed and immutable fields (order_id, snapshot_json) remain unchanged. It also checks that compliance logging is triggered.
 *
 * Test Steps:
 * 1. Register a new admin account (simulate compliance officer).
 * 2. Authenticate as the admin — this sets the connection as admin session.
 * 3. Use admin search to locate or create a suitable test order and get an order id.
 * 4. Create a snapshot for that order with an original snapshot_reason and snapshot_json.
 * 5. Capture the immutable fields (order_id, snapshot_json, created_at) before update.
 * 6. Update the snapshot by modifying snapshot_reason only (business policy allows this).
 * 7. Confirm API response:   - snapshot_reason is updated as requested   - snapshot_json, order_id, created_at remain unchanged   - The returned object has correctly updated reason and preserved evidence fields.
 * 8. Optionally: (if environment supports) — verify that audit/compliance log entry exists for the change.
 */
export async function test_api_order_snapshot_metadata_update_by_admin_success_change_compliance_justification(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongTestPassword123!";
  const signUpResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IAdminAuth.SignUp
  });
  typia.assert(signUpResult);

  // (Connection headers auto-updated with JWT for admin)

  // 2. Find or create a test order (use admin patch/search API to get one)
  const searchResult = await api.functional.shoppingMallAiBackend.admin.orders.search(connection, {
    body: {
      page: 1,
      pageSize: 1
    } satisfies IShoppingMallAiBackendOrder.IRequest
  });
  typia.assert(searchResult);
  let orderSummary = searchResult.data[0];

  // If no order exists, fail the test (in real e2e, creation logic could be added if API provided)
  if (!orderSummary) throw new Error("No test order found in system.");

  // 3. Create a new snapshot for the found order
  const snapshotCreateInput: IShoppingMallAiBackendOrderSnapshot.ICreate = {
    snapshot_json: JSON.stringify({ test_order_id: orderSummary.id, random: Math.random() }),
    snapshot_reason: "initial evidence record"
  };
  const snapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.create(connection, {
    orderId: orderSummary.id,
    body: snapshotCreateInput
  });
  typia.assert(snapshot);

  // 4. Save immutable fields before update
  const preUpdate = {
    order_id: snapshot.order_id,
    snapshot_json: snapshot.snapshot_json,
    created_at: snapshot.created_at
  };

  // 5. Prepare update: change snapshot_reason only (business policy allows this)
  const newReason = "Compliance note updated by admin at " + new Date().toISOString();
  const updateInput: IShoppingMallAiBackendOrderSnapshot.IUpdate = {
    snapshot_reason: newReason
  };
  const updatedSnapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.update(connection, {
    orderId: snapshot.order_id,
    orderSnapshotId: snapshot.id,
    body: updateInput
  });
  typia.assert(updatedSnapshot);

  // 6. Verify only snapshot_reason changed, others remain identical
  TestValidator.equals("order_id unchanged")(updatedSnapshot.order_id)(preUpdate.order_id);
  TestValidator.equals("snapshot_json unchanged")(updatedSnapshot.snapshot_json)(preUpdate.snapshot_json);
  TestValidator.equals("created_at unchanged")(updatedSnapshot.created_at)(preUpdate.created_at);
  TestValidator.equals("snapshot_reason updated")(updatedSnapshot.snapshot_reason)(newReason);

  // 7. (Optional, if environment supports) — Audit/compliance log check (not implemented here due to lack of API)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderSnapshot";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test validating immutability of order snapshot fields via admin API.
 *
 * This test ensures an admin cannot update immutable fields (such as snapshot_json or order_id) on an existing order snapshot.
 *
 * Business context:
 * - Order snapshots are immutable records that provide a forensic/audit trail for rollback/legal/dispute handling.
 * - Only the snapshot_reason field is allowed to be updated post-creation (as permitted by IUpdate schema), ensuring audit chain integrity.
 * - Server should reject any attempt (even via type-bypass) to mutate immutable fields.
 *
 * Test workflow:
 * 1. Register (and log in as) an admin for authentication
 * 2. Create a new order snapshot for a random order
 * 3. Update only the allowed field (snapshot_reason) and confirm change
 * 4. Attempt to update forbidden/immutable fields (snapshot_json, order_id) using an unsafe dynamic object (simulating outside-type request); expect a business/validation error.
 */
export async function test_api_order_snapshot_update_attempt_on_immutable_fields_raises_error(connection: api.IConnection) {
  // Step 1: Register a new admin (dependency setup)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "test1234!";
  const admin = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IAdminAuth.SignUp,
  });
  typia.assert(admin);

  // Step 2: Create a new order snapshot for a random order
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const snapshotCreateBody = {
    snapshot_json: JSON.stringify({ item: "shoes", total: 120 } as Record<string, unknown>),
    snapshot_reason: "created", // valid reason
  } satisfies IShoppingMallAiBackendOrderSnapshot.ICreate;
  const snapshot = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.create(connection, {
    orderId,
    body: snapshotCreateBody,
  });
  typia.assert(snapshot);
  TestValidator.equals("order id on snapshot")(snapshot.order_id)(orderId);

  // Step 3: Update only allowed field (snapshot_reason)
  const allowedUpdateReason = "qualified compliance edit";
  const allowedUpdate = await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.update(connection, {
    orderId,
    orderSnapshotId: snapshot.id,
    body: { snapshot_reason: allowedUpdateReason } satisfies IShoppingMallAiBackendOrderSnapshot.IUpdate,
  });
  typia.assert(allowedUpdate);
  TestValidator.equals("allowed snapshot_reason update")(allowedUpdate.snapshot_reason)(allowedUpdateReason);
  TestValidator.equals("order id unchanged")(allowedUpdate.order_id)(orderId);
  TestValidator.equals("snapshot_json unchanged")(allowedUpdate.snapshot_json)(snapshot.snapshot_json);

  // Step 4: Attempt to update immutable fields (must fail at business logic layer)
  await TestValidator.error("should fail to mutate immutable fields")(
    async () => {
      // Send deliberately extra fields via runtime-constructed object
      const invalidBody = {
        snapshot_reason: "illegal mutation attempt",
        snapshot_json: "this should not be accepted",
        order_id: typia.random<string & tags.Format<"uuid">>(),
      } as unknown as IShoppingMallAiBackendOrderSnapshot.IUpdate;
      await api.functional.shoppingMallAiBackend.admin.orders.orderSnapshots.update(connection, {
        orderId,
        orderSnapshotId: snapshot.id,
        body: invalidBody,
      });
    }
  );
}

