import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCart";
import type { IPageIShoppingMallAiBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCart";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test that a customer can retrieve a paginated and filtered list of their own shopping carts.
 *
 * This test validates that an authenticated customer can view ONLY their own shopping carts, filtered by status and date, using the pagination/sorting controls. It also ensures there is no data leakage (carts from other users cannot be retrieved), guaranteeing user privacy in e-commerce workflows.
 *
 * Steps:
 * 1. Register customer A (primary test user) and store their JWT.
 * 2. Create multiple carts for customer A with varying statuses ('active', 'checked_out', 'abandoned') and timestamps.
 * 3. Filter by status (e.g., 'active') and ensure only 'active', customer A's carts are returned.
 * 4. Filter by a created_at date range (between two cart creation times) and validate results are in range and only belong to customer A.
 * 5. Use pagination (page, limit) to check result set size and pagination meta.
 * 6. Register customer B, create carts for B, then as customer A, ensure B's carts do not appear in A's filtered search (privacy check).
 */
export async function test_api_cart_search_returns_customer_carts_filtered_and_paginated(connection: api.IConnection) {
  // 1. Register customer A
  const emailA: string = typia.random<string & tags.Format<"email">>();
  const passwordA = "Password!234";
  const signUpA = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: emailA,
      password: passwordA,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphaNumeric(8),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(signUpA);
  // set Authorization header in connection for customer A
  connection.headers = {
    ...connection.headers,
    Authorization: signUpA.setHeaders.Authorization,
  };

  // 2. Create carts for customer A: statuses and creation spread
  const statusList = ["active", "checked_out", "abandoned"];
  const cartsA: IShoppingMallAiBackendCart[] = [];
  for (let i = 0; i < 7; ++i) {
    // Spread creation timestamps: oldest to newest by 5 minutes each
    const now = new Date();
    now.setMinutes(now.getMinutes() - (35 - i * 5));
    const status = statusList[i % statusList.length];
    const cart = await api.functional.shoppingMallAiBackend.customer.carts.create(connection, {
      body: {
        status: status,
        session_token: null
      } satisfies IShoppingMallAiBackendCart.ICreate
    });
    typia.assert(cart);
    // Overwrite created_at via hypothetical DB or after retrieval (skip, as cannot be set by API)
    cartsA.push(cart);
  }

  // 3a. Filter by status ('active')
  const searchActive = await api.functional.shoppingMallAiBackend.customer.carts.search(connection, {
    body: {
      status: "active"
    } satisfies IShoppingMallAiBackendCart.IRequest
  });
  typia.assert(searchActive);
  for (const cart of searchActive.data) {
    TestValidator.equals("status=active")(cart.status)("active");
    TestValidator.predicate("belongs to customer A")(cartsA.some(a => a.id === cart.id));
  }

  // 3b. Filter by creation date: use min/max cart times from customer A carts
  const allCreatedA = cartsA.map(c => c.created_at).sort();
  const createdFrom = allCreatedA[1];
  const createdTo = allCreatedA[5];
  const searchDate = await api.functional.shoppingMallAiBackend.customer.carts.search(connection, {
    body: {
      created_at_from: createdFrom,
      created_at_to: createdTo
    } satisfies IShoppingMallAiBackendCart.IRequest
  });
  typia.assert(searchDate);
  for (const cart of searchDate.data) {
    TestValidator.predicate("belongs to customer A")(cartsA.some(a => a.id === cart.id));
    TestValidator.predicate("created_at in range")(cart.created_at >= createdFrom && cart.created_at <= createdTo);
  }

  // 3c. Pagination: page 2, limit 3
  const searchPaginated = await api.functional.shoppingMallAiBackend.customer.carts.search(connection, {
    body: {
      page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
