  TestValidator.equals("amount")(tx1.transaction_amount)(depositAmount);
  TestValidator.equals("reference id")(tx1.reference_id)(referenceId);
  TestValidator.equals("type")(tx1.transaction_type)("deposit");
  TestValidator.equals("balance after")(tx1.balance_after_transaction)(depositAmount);

