 * - Validate result reflects the update, others unchanged
 * - Attempt to update an immutable field (simulated, should fail)
 * - Attempt to update a non-existent transaction (should fail)
 */
export async function test_api_coin_transaction_update_with_field_restrictions(connection: api.IConnection) {
  // 1. Create a coin wallet as admin
  const wallet = await api.functional.shoppingMallAiBackend.admin.coinWallets.create(connection, {
    body: {
      wallet_owner_admin_id: typia.random<string & tags.Format<"uuid">>(),
      wallet_type: "reward",
      wallet_status: "active",
      wallet_address: typia.random<string>(),
    } satisfies IShoppingMallAiBackendCoinWallet.ICreate
  });
  typia.assert(wallet);

  // 2. Create a coin transaction for that wallet
  const tx = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.create(connection, {
    coinWalletId: wallet.id,
    body: {
      wallet_id: wallet.id,
      transaction_type: "deposit",
      transaction_amount: 1000,
      balance_after_transaction: 1000,
      reference_id: null,
      transaction_reason: "Initial deposit"
    } satisfies IShoppingMallAiBackendCoinTransaction.ICreate
  });
  typia.assert(tx);

  // 3. Update transaction_reason field successfully
  const updatedReason = "Audit adjustment reason: test update";
  const updatedTx = await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.update(connection, {
    coinWalletId: wallet.id,
    coinTransactionId: tx.id,
    body: { transaction_reason: updatedReason } satisfies IShoppingMallAiBackendCoinTransaction.IUpdate
  });
  typia.assert(updatedTx);
  TestValidator.equals("updated reason")(updatedTx.transaction_reason)(updatedReason);
  // Ensure other fields unchanged
  TestValidator.equals("id unchanged")(updatedTx.id)(tx.id);
  TestValidator.equals("wallet_id unchanged")(updatedTx.wallet_id)(tx.wallet_id);
  TestValidator.equals("transaction_amount unchanged")(updatedTx.transaction_amount)(tx.transaction_amount);
  TestValidator.equals("transaction_type unchanged")(updatedTx.transaction_type)(tx.transaction_type);
  TestValidator.equals("balance_after_transaction unchanged")(updatedTx.balance_after_transaction)(tx.balance_after_transaction);

  // 4. Attempt to update immutable field (transaction_amount) - should fail
  await TestValidator.error("immutable field mutation forbidden")(async () => {
    // TypeScript enforces DTO schema so we cannot send forbidden field in IUpdate; skip direct immutable mutation attempt
    // Instead, simulate by casting (for negative test demonstration only)
    await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.update(
      connection,
      {
        coinWalletId: wallet.id,
        coinTransactionId: tx.id,
        body: { transaction_amount: 9999 } as any
      }
    );
  });

  // 5. Attempt to update a non-existent transaction
  await TestValidator.error("non-existent transaction update fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.coinWallets.coinTransactions.update(connection, {
      coinWalletId: wallet.id,
      coinTransactionId: typia.random<string & tags.Format<"uuid">>(),
      body: { transaction_reason: "Should not succeed" }
    });
  });
}

