import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { IPageIShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendInquirySnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Verify that a seller can retrieve a paginated and filtered list of inquiry snapshots for a product inquiry.
 *
 * This end-to-end test validates:
 * 1. Seller onboarding and product creation
 * 2. Product inquiry creation by a customer
 * 3. Inquiry snapshot creation (simulate history/events)
 * 4. Retrieval of snapshots with pagination, filters (actor, status, time, etc.), sorting
 * 5. Security: Only owner seller may access; others and unauthenticated should fail
 *
 * Step-by-step process:
 * 1. Register a seller and obtain JWT for authentication
 * 2. Register a product as that seller
 * 3. Simulate a customer and submit a product inquiry for that product
 * 4. Create multiple inquiry snapshots as seller, varying some fields/status for realistic test
 * 5. Retrieve snapshot list (PATCH) as seller with different filters/paging/sort
 * 6. Validate filter/sort/pagination logic is correctly reflected in results
 * 7. Validate only authorized (owning) seller can fetch; forbidden for non-owners/unauthenticated access
 */
export async function test_api_inquiry_snapshot_list_happy_path_pagination_filtering(connection: api.IConnection) {
  // 1. Register seller and authenticate
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const sellerReg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: "StrongPassw0rd!",
      companyName: "Test Company",
      businessNumber: "1000123456",
      representativeName: "Tester Seller",
      address: "123 Test Address, Test City",
      phone: "01012345678"
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerReg);
  const sellerId = sellerReg.sellerId;

  // 2. Seller creates a product
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: `PROD-${Date.now()}`,
      name: "Test Product",
      description: "Product for inquiry snapshot testing",
      main_image_uri: null,
      status: "published"
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);
  const productId = product.id;

  // 3. Simulate a customer inquiry (impersonate via random customer uuid for testing)
  const customerId: string = typia.random<string & tags.Format<"uuid">>();
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: productId,
      title: "Test Inquiry",
      body: "Inquiry about the product.",
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate
  });
  typia.assert(inquiry);
  const inquiryId = inquiry.id;

  // 4. Seller creates multiple inquiry snapshots (varying values)
  const snapshots: IShoppingMallAiBackendInquirySnapshot[] = [];
  const statSeq: Array<IShoppingMallAiBackendInquirySnapshot["status"]> = ["waiting", "answered", "blocked"];
  const now = new Date();
  for (let i = 0; i < 6; ++i) {
    const status = statSeq[i % statSeq.length];
    const changed_at = new Date(now.getTime() + i * 1000 * 60).toISOString(); // spaced by 1 minute
    const snap = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.create(connection, {
      productInquiryId: inquiryId,
      body: {
        inquiry_id: inquiryId,
        title: `Inquiry Title v${i + 1}`,
        body: `Edit ${i + 1} to inquiry body`,
        public: Boolean(i % 2),
        status,
        actor_id: sellerId,
        ai_sentiment_score: (i % 3 === 0) ? 0.5 : null,
        ai_spam_score: (i % 2 === 0) ? 0.2 : null,
        changed_at,
      } satisfies IShoppingMallAiBackendInquirySnapshot.ICreate
    });
    typia.assert(snap);
    snapshots.push(snap);
  }

  // 5a. Retrieve: all snapshots (no filter)
  let result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      // no filters here
    } satisfies IShoppingMallAiBackendInquirySnapshot.IRequest
  });
  typia.assert(result);
  TestValidator.equals("all snapshots count")(result.data.length)(snapshots.length);

  // 5b. Filter by actor_id
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      actor_id: sellerId
    }
  });
  typia.assert(result);
  TestValidator.predicate("actor filtered count")(result.data.every(d => d.actor_id === sellerId));

  // 5c. Filter by status
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      status: "answered"
    }
  });
  typia.assert(result);
  TestValidator.predicate("status=answered")(result.data.every(d => d.status === "answered"));

  // 5d. Pagination: limit and page
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      limit: 2,
      page: 2
    }
  });
  typia.assert(result);
  TestValidator.equals("pagination meta limit")(result.pagination.limit)(2);
  TestValidator.equals("pagination meta page")(result.pagination.current)(2);
  TestValidator.predicate("pagination data max 2")((result.data.length <= 2));

  // 5e. Sort: changed_at desc/asc
  // Asc
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      sort_by: "changed_at",
      sort_direction: "asc"
    }
  });
  typia.assert(result);
  for (let i = 1; i < result.data.length; ++i) {
    TestValidator.predicate(`asc-sort order at ${i}`)(result.data[i].changed_at >= result.data[i - 1].changed_at);
  }
  // Desc
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      sort_by: "changed_at",
      sort_direction: "desc"
    }
  });
  typia.assert(result);
  for (let i = 1; i < result.data.length; ++i) {
    TestValidator.predicate(`desc-sort order at ${i}`)(result.data[i - 1].changed_at >= result.data[i].changed_at);
  }

  // 5f. Filter by date range (changed_at_from/to)
  // Use the time window from snapshot[2] to snapshot[4]
  const changed_at_from = snapshots[2].changed_at;
  const changed_at_to = snapshots[4].changed_at;
  result = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiryId,
    body: {
      inquiry_id: inquiryId,
      changed_at_from,
      changed_at_to
    }
  });
  typia.assert(result);
  TestValidator.predicate("date range filter")(
    result.data.every(d => d.changed_at >= changed_at_from && d.changed_at <= changed_at_to)
  );

  // 6. Security: only owning seller can fetch - test negative: no auth/JWT
  const { Authorization, ...restHeaders } = connection.headers ?? {};
  const unauthConn = {
    ...connection,
    headers: restHeaders
  };
  await TestValidator.error("unauthorized - no JWT")(() =>
    api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(unauthConn, {
      productInquiryId: inquiryId,
      body: {
        inquiry_id: inquiryId,
      }
    })
  );

  // 7. Security: seller who does not own the product
  const seller2Email: string = typia.random<string & tags.Format<"email">>();
  const seller2Reg = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: seller2Email,
      password: "StrongPassw0rd!",
      companyName: "Test Company 2",
      businessNumber: "1000123457",
      representativeName: "Other Seller",
      address: "234 Second Address, City",
      phone: "01022334455"
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(seller2Reg);
  const conn2 = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: seller2Reg.setHeaders.Authorization } };
  await TestValidator.error("not owner seller forbidden")(() =>
    api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.search(conn2, {
      productInquiryId: inquiryId,
      body: { inquiry_id: inquiryId }
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { IPageIShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendInquirySnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * E2E test verifying admin can audit/search all inquiry snapshots: filter, paginate, enumerate events, and enforce security.
 *
 * Business context:
 * - Product inquiry snapshots form a regulatory evidence chain for all changes (content, status, actor)
 * - Admins must be able to view and filter the full change history for any inquiry
 *
 * Process:
 * 1. Admin registers and is authenticated (get adminId, JWT)
 * 2. A product inquiry is created by a customer (simulate IDs as customer reg is unavailable)
 * 3. Inquiry is mutated multiple times to accumulate at least three change events/snapshots
 * 4. Admin creates an additional manual snapshot for broader test coverage
 * 5. Admin searches/filters with PATCH: all, by actor_id, by status, paginates, sorts, date window
 * 6. Results validated for filter effectiveness and record inclusion
 * 7. Negative scenario: search as non-admin (no Authorization) yields error
 * 8. Negative scenario: malformed filter (missing required inquiry_id) yields error
 */
export async function test_api_inquiry_snapshot_admin_search_advanced_audit_evidence(
  connection: api.IConnection,
) {
  // 1. Register admin and get JWT/profile
  const adminInfo = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongP@ss1!",
    },
  });
  typia.assert(adminInfo);

  // 2. Simulate customer & product IDs and create product inquiry
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const productId = typia.random<string & tags.Format<"uuid">>();
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customerId,
      product_id: productId,
      title: "How durable is this backpack?",
      body: "Is the seam waterproof and does it have an inner sleeve?",
      public: true,
    },
  });
  typia.assert(inquiry);

  // 3. Update inquiry multiple times (triggers snapshot creation)
  const updA = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      title: "How durable is this backpack? (edit A)",
      status: "waiting",
    },
  });
  typia.assert(updA);

  const updB = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      body: "Does it come in blue?",
      status: "answered",
    },
  });
  typia.assert(updB);

  const updC = await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
    productInquiryId: inquiry.id,
    body: {
      public: false,
      status: "blocked",
    },
  });
  typia.assert(updC);

  // 4. As admin, manually snapshot the inquiry
  const nowIso = new Date().toISOString();
  // Only the IShoppingMallAiBackendInquirySnapshot.ICreate allows status as:
  //   "waiting" | "answered" | "blocked" | "under_review" | "deleted"
  const allowedStatuses = ["waiting", "answered", "blocked", "under_review", "deleted"] as const;
  const resolveManualSnapStatus = () =>
    ([updC, updB, updA, inquiry]
      .map((o) => o.status)
      .find((s): s is typeof allowedStatuses[number] => allowedStatuses.includes(s as typeof allowedStatuses[number])) || "waiting");
  const manualSnap = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.create(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      title: updC.title ?? updB.title ?? updA.title ?? inquiry.title,
      body: updC.body ?? updB.body ?? updA.body ?? inquiry.body,
      public: updC.public ?? updB.public ?? updA.public ?? inquiry.public,
      status: resolveManualSnapStatus(),
      actor_id: adminInfo.adminId,
      changed_at: nowIso,
    },
  });
  typia.assert(manualSnap);

  // 5. As admin, search all snapshots for this inquiry (no filter)
  const allSnaps = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
    },
  });
  typia.assert(allSnaps);
  TestValidator.predicate("should have at least 4 snapshots")(allSnaps.data.length >= 4);
  TestValidator.predicate("should include admin-created snapshot")(
    allSnaps.data.some((s) => s.actor_id === adminInfo.adminId),
  );

  // 5b. Filter by actor_id (customer)
  const byCustomer = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      actor_id: customerId,
    },
  });
  typia.assert(byCustomer);
  TestValidator.predicate("should include only customer-written events")(
    byCustomer.data.every((s) => s.actor_id === customerId),
  );

  // 5c. Filter by status ('answered', which was set by updB)
  const byStatus = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      status: "answered",
    },
  });
  typia.assert(byStatus);
  TestValidator.predicate("should include at least one answered snapshot")(
    byStatus.data.some((s) => s.status === "answered"),
  );

  // 5d. Pagination (limit=2, page=1)
  const paged = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      limit: 2,
      page: 1,
    },
  });
  typia.assert(paged);
  TestValidator.equals("should return only 2 results")(paged.data.length)(2);

  // 5e. Sorted by change time (desc)
  const sorted = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      sort_by: "changed_at",
      sort_direction: "desc",
    },
  });
  typia.assert(sorted);

  // 5f. Date range window: only most recent
  const afterManual = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      changed_at_from: nowIso,
      limit: 1,
    },
  });
  typia.assert(afterManual);
  TestValidator.predicate("at least one snapshot after manual creation")(
    afterManual.data.length >= 1,
  );

  // 6. Negative: Search as non-admin → Auth error expected
  if (!connection.headers) connection.headers = {};
  delete connection.headers.Authorization;
  await TestValidator.error("non-admin cannot search snapshots")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
      productInquiryId: inquiry.id,
      body: {
        inquiry_id: inquiry.id,
      },
    });
  });

  // 7. Negative: Malformed filter (missing required inquiry_id)
  connection.headers.Authorization = adminInfo.setHeaders.Authorization;
  await TestValidator.error("malformed filter causes server error")(async () => {
    await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.search(connection, {
      productInquiryId: inquiry.id,
      body: {} as any,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate correct customer access and permission control for product inquiry snapshot detail retrieval (positive and negative cases)
 *
 * Business context:
 * This test ensures that the customer who owns a product inquiry can fully retrieve all historical snapshot details for their inquiry, including all tracked fields (title, body, public status, workflow status, actor, AI scores, timestamps, etc). It also ensures that any customer who does NOT own the inquiry is forbidden from accessing the snapshot, enforcing proper auditability and data privacy.
 *
 * Process outline:
 * 1. Register and authenticate a customer (as inquiry owner)
 * 2. Create a product inquiry as that customer
 * 3. Update the inquiry to a new state (edit title, body, etc)
 * 4. Explicitly create a new inquiry snapshot to capture the audit state
 * 5. As the owner customer, retrieve that snapshot and confirm all fields match the audit record, including id, timestamp, status, etc
 * 6. Register a second (non-owner) customer, and confirm that access to the snapshot using their context is forbidden/denied
 */
export async function test_api_inquiry_snapshot_detail_customer_access(
  connection: api.IConnection,
) {
  // 1. Register and authenticate the owning customer
  const email = typia.random<string & tags.Format<"email">>();
  const signUpRes = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email,
        password: "test-password",
        name: RandomGenerator.name(),
        nickname: RandomGenerator.alphabets(6),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );
  typia.assert(signUpRes);
  const customer = signUpRes.customer;

  // 2. Create a product inquiry as this customer
  const productId = typia.random<string & tags.Format<"uuid">>();
  const inquiryCreateInput = {
    customer_id: customer.id,
    product_id: productId,
    title: "Test Inquiry Title",
    body: "Initial inquiry content for audit.",
    public: true,
  } satisfies IShoppingMallAiBackendProductInquiry.ICreate;
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(
    connection,
    { body: inquiryCreateInput },
  );
  typia.assert(inquiry);

  // 3. Update the inquiry to generate a changed state
  const updateInput = {
    title: "Audit Title for Snapshot E2E",
    body: "Edited body content for snapshot record.",
    public: false,
    status: "waiting" as const,
    answer_id: null,
  } satisfies IShoppingMallAiBackendProductInquiry.IUpdate;
  const inquiryAfterUpdate =
    await api.functional.shoppingMallAiBackend.customer.productInquiries.update(
      connection,
      {
        productInquiryId: inquiry.id,
        body: updateInput,
      },
    );
  typia.assert(inquiryAfterUpdate);

  // 4. Create an explicit snapshot record for audit
  const now = new Date().toISOString();
  const snapshotCreateInput = {
    inquiry_id: inquiry.id,
    title: updateInput.title!,
    body: updateInput.body!,
    public: updateInput.public!,
    status: updateInput.status,
    actor_id: customer.id,
    ai_sentiment_score: null,
    ai_spam_score: null,
    changed_at: now,
  } satisfies IShoppingMallAiBackendInquirySnapshot.ICreate;
  const snapshot = await api.functional.shoppingMallAiBackend.customer.productInquiries.inquirySnapshots.create(
    connection,
    {
      productInquiryId: inquiry.id,
      body: snapshotCreateInput,
    },
  );
  typia.assert(snapshot);

  // 5. As the owning customer: Retrieve and validate all fields from the historical snapshot
  const fetched =
    await api.functional.shoppingMallAiBackend.customer.productInquiries.inquirySnapshots.at(
      connection,
      {
        productInquiryId: inquiry.id,
        inquirySnapshotId: snapshot.id,
      },
    );
  typia.assert(fetched);
  // Validate all fields (use ground-truth from actual snapshot entity to avoid timestamp/nullable issues)
  TestValidator.equals("snapshot id")(fetched.id)(snapshot.id);
  TestValidator.equals("inquiry_id")(fetched.inquiry_id)(snapshot.inquiry_id);
  TestValidator.equals("title")(fetched.title)(snapshot.title);
  TestValidator.equals("body")(fetched.body)(snapshot.body);
  TestValidator.equals("public flag")(fetched.public)(snapshot.public);
  TestValidator.equals("status")(fetched.status)(snapshot.status);
  TestValidator.equals("actor_id")(fetched.actor_id)(snapshot.actor_id);
  TestValidator.equals("ai_sentiment_score")(fetched.ai_sentiment_score)(snapshot.ai_sentiment_score);
  TestValidator.equals("ai_spam_score")(fetched.ai_spam_score)(snapshot.ai_spam_score);
  TestValidator.equals("changed_at")(fetched.changed_at)(snapshot.changed_at);

  // 6. Register a second customer; attempt forbidden access as non-owner
  const email2 = typia.random<string & tags.Format<"email">>();
  const signUpRes2 = await api.functional.auth.customer.register.signUp(
    connection,
    {
      body: {
        email: email2,
        password: "test-password-2",
        name: RandomGenerator.name(),
        nickname: RandomGenerator.alphabets(8),
        phone: RandomGenerator.mobile(),
      } satisfies ICustomerSignUp.Request,
    },
  );
  typia.assert(signUpRes2);
  // When this customer context is active, attempt access to snapshot (should fail)
  await TestValidator.error("should fail for non-owner snapshot get")(
    async () =>
      await api.functional.shoppingMallAiBackend.customer.productInquiries.inquirySnapshots.at(
        connection,
        {
          productInquiryId: inquiry.id,
          inquirySnapshotId: snapshot.id,
        },
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test authorized seller snapshot access and edge cases for product inquiries.
 *
 * Verifies a seller can access inquiry snapshot details of their own product inquiries through:
 *   1. Seller registration (acquire JWT and sellerId)
 *   2. Product creation (owned by seller)
 *   3. Inquiry created for product (simulate as customer by direct assignment)
 *   4. Multiple snapshots created for inquiry
 *   5. Seller accesses an arbitrary snapshot for their inquiry (should succeed)
 *   6. Seller attempts to access inquiry snapshot for inquiry not owned (should fail with forbidden error)
 *   7. Seller attempts to access with invalid/nonexistent snapshot ID (should fail with not-found error)
 *
 * Steps:
 * - Register seller (to get sellerId and JWT)
 * - Register 2nd seller (used for resource separation)
 * - Create product (assign to seller)
 * - Create product for 2nd seller as negative test
 * - Create inquiry for main product (simulate customer by assigning random UUID)
 * - Create inquiry for secondary product (for permission denial test)
 * - Create multiple snapshots for both inquiries
 * - Seller tries get-by-id for their snapshot (should succeed and values match)
 * - Seller tries get-by-id for non-owned inquiry snapshot (should fail forbidden)
 * - Seller tries get-by-id for invalid/nonexistent snapshotId (should fail not found)
 */
export async function test_api_inquiry_snapshot_detail_seller_access_and_edge_cases(
  connection: api.IConnection
) {
  // 1. Register main seller
  const sellerSignUp: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPass1234",
    companyName: RandomGenerator.name(),
    businessNumber: "1234567890",
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(20),
    phone: RandomGenerator.mobile(),
  };
  const sellerResp = await api.functional.auth.seller.register.signUp(connection, {
    body: sellerSignUp,
  });
  typia.assert(sellerResp);
  const sellerId = sellerResp.sellerId;

  // 2. Register another seller for negative edge case
  const sellerSignUp2: ISellerAuth.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "AnotherStrongPass1234",
    companyName: RandomGenerator.name(),
    businessNumber: "9876543210",
    representativeName: RandomGenerator.name(),
    address: RandomGenerator.paragraph()(20),
    phone: RandomGenerator.mobile(),
  };
  const sellerResp2 = await api.functional.auth.seller.register.signUp(connection, {
    body: sellerSignUp2,
  });
  typia.assert(sellerResp2);
  const sellerId2 = sellerResp2.sellerId;

  // 3. Create product for main seller
  const productCreate: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: sellerId,
    code: "SKU-" + RandomGenerator.alphaNumeric(8),
    name: "Main Product " + RandomGenerator.alphaNumeric(5),
    description: RandomGenerator.content()(1)(),
    main_image_uri: null,
    status: "published",
  };
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: productCreate,
  });
  typia.assert(product);

  // 4. Create another product for 2nd seller
  const productCreate2: IShoppingMallAiBackendProduct.ICreate = {
    seller_id: sellerId2,
    code: "SKU-" + RandomGenerator.alphaNumeric(8),
    name: "Other Product " + RandomGenerator.alphaNumeric(5),
    status: "published",
  };
  const product2 = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: productCreate2,
  });
  typia.assert(product2);

  // 5. Simulate a customer (fake customer_id)
  const fakeCustomerId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const fakeCustomerId2: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 6. Create inquiry for main product
  const inquiryBody: IShoppingMallAiBackendProductInquiry.ICreate = {
    customer_id: fakeCustomerId,
    product_id: product.id,
    title: "Main product inquiry",
    body: "What is the material?",
    public: true,
  };
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: inquiryBody,
  });
  typia.assert(inquiry);

  // 7. Create inquiry for other product (negative edge)
  const inquiryBody2: IShoppingMallAiBackendProductInquiry.ICreate = {
    customer_id: fakeCustomerId2,
    product_id: product2.id,
    title: "Other product inquiry",
    body: "Is there a warranty?",
    public: true,
  };
  const inquiry2 = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: inquiryBody2,
  });
  typia.assert(inquiry2);

  // 8. Create multiple snapshots for first inquiry
  const snapshotBodyA: IShoppingMallAiBackendInquirySnapshot.ICreate = {
    inquiry_id: inquiry.id,
    title: inquiry.title,
    body: inquiry.body,
    public: inquiry.public,
    status: "waiting",
    actor_id: sellerId,
    changed_at: new Date().toISOString(),
  };
  const snapshotA = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.create(
    connection,
    {
      productInquiryId: inquiry.id,
      body: snapshotBodyA,
    }
  );
  typia.assert(snapshotA);

  // create second snapshot (simulate edit or answer)
  const snapshotBodyB: IShoppingMallAiBackendInquirySnapshot.ICreate = {
    inquiry_id: inquiry.id,
    title: inquiry.title + " (edited)",
    body: inquiry.body + " Now contains more info.",
    public: false,
    status: "answered",
    actor_id: sellerId,
    ai_sentiment_score: 0.75,
    ai_spam_score: 0.1,
    changed_at: new Date(Date.now() + 1000).toISOString(),
  };
  const snapshotB = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.create(
    connection,
    {
      productInquiryId: inquiry.id,
      body: snapshotBodyB,
    }
  );
  typia.assert(snapshotB);

  // 9. Create a snapshot for other product's inquiry
  const snapshotBodyC: IShoppingMallAiBackendInquirySnapshot.ICreate = {
    inquiry_id: inquiry2.id,
    title: inquiry2.title,
    body: inquiry2.body,
    public: true,
    status: "waiting",
    actor_id: sellerId2,
    ai_sentiment_score: -0.4,
    ai_spam_score: 0.2,
    changed_at: new Date().toISOString(),
  };
  const snapshotC = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.create(
    connection,
    {
      productInquiryId: inquiry2.id,
      body: snapshotBodyC,
    }
  );
  typia.assert(snapshotC);

  // 10. Seller accesses their own snapshot (should succeed)
  const output = await api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.at(connection, {
    productInquiryId: inquiry.id,
    inquirySnapshotId: snapshotB.id,
  });
  typia.assert(output);
  TestValidator.equals("Snapshot id matches")(output.id)(snapshotB.id);
  TestValidator.equals("Snapshot fields match")(output.title)(snapshotB.title);
  TestValidator.equals("Public flag")(output.public)(snapshotB.public);

  // 11. Seller access forbidden: snapshot for other seller's inquiry
  await TestValidator.error("Forbidden (not owner) access to snapshot")(() =>
    api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.at(connection, {
      productInquiryId: inquiry2.id,
      inquirySnapshotId: snapshotC.id,
    })
  );

  // 12. Seller access with invalid snapshot ID
  const nonExistentSnapshotId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Not found (invalid snapshotId)")(() =>
    api.functional.shoppingMallAiBackend.seller.productInquiries.inquirySnapshots.at(connection, {
      productInquiryId: inquiry.id,
      inquirySnapshotId: nonExistentSnapshotId,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendInquirySnapshot";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test that an admin has full access to inquiry snapshots, including historical record retrieval and error cases for missing or soft-deleted entries.
 *
 * Business Context: Admins must be able to retrieve any inquiry snapshot—for legal audits, compliance, and historical state review—regardless of product or inquiry ownership. Snapshots record the complete state of an inquiry at each major event and may be soft-deleted to hide them from normal flows while preserving evidence.
 *
 * Steps:
 * 1. Register a new admin account with full permissions.
 * 2. Create a new product inquiry as a customer (simulated, using valid random data).
 * 3. As admin, create at least two snapshots for that inquiry, simulating distinct inquiry events (title/status changes).
 * 4. Retrieve one snapshot by ID as admin, and verify all details match exactly.
 * 5. NEGATIVE: Attempt to retrieve a non-existent snapshot (random UUID) and verify that an error is thrown.
 * 6. NEGATIVE: Soft-delete a real snapshot, then attempt to retrieve it, and verify that an error is thrown as expected.
 */
export async function test_api_inquiry_snapshot_detail_admin_full_access_and_nonexistent_error(connection: api.IConnection) {
  // 1. Register a new admin with maximum access
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "Admin!234";
  const adminProfile = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminProfile);
  // JWT is now set in connection for admin actions

  // 2. Create a new product inquiry (acting as a stand-in customer)
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: typia.random<string & tags.Format<"uuid">>(),
      product_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(20),
      body: RandomGenerator.paragraph()(100),
      public: true,
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate,
  });
  typia.assert(inquiry);

  // 3. Create at least two distinct inquiry snapshots as admin
  const adminId = adminProfile.adminId;
  // Snapshot 1 – initial, "waiting" state
  const snapshot1 = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.create(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      title: inquiry.title,
      body: inquiry.body,
      public: inquiry.public,
      status: "waiting",
      actor_id: adminId,
      ai_sentiment_score: 0.3,
      ai_spam_score: 0.1,
      changed_at: new Date().toISOString(),
    } satisfies IShoppingMallAiBackendInquirySnapshot.ICreate,
  });
  typia.assert(snapshot1);

  // Snapshot 2 – simulate change (e.g., "under_review")
  const snapshot2 = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.create(connection, {
    productInquiryId: inquiry.id,
    body: {
      inquiry_id: inquiry.id,
      title: "Changed title - compliance review",
      body: inquiry.body,
      public: inquiry.public,
      status: "under_review",
      actor_id: adminId,
      ai_sentiment_score: -0.3,
      ai_spam_score: 0.2,
      changed_at: new Date().toISOString(),
    } satisfies IShoppingMallAiBackendInquirySnapshot.ICreate,
  });
  typia.assert(snapshot2);

  // 4. Retrieve a valid inquiry snapshot by ID and verify fields
  const fetched = await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.at(connection, {
    productInquiryId: inquiry.id,
    inquirySnapshotId: snapshot2.id,
  });
  typia.assert(fetched);
  TestValidator.equals("fetched snapshot matches snapshot2")(fetched)(snapshot2);

  // 5. NEGATIVE: Attempt to retrieve a non-existent snapshot (random UUID)
  const fakeSnapshotId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("error: non-existent snapshot")(() =>
    api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.at(connection, {
      productInquiryId: inquiry.id,
      inquirySnapshotId: fakeSnapshotId,
    })
  );

  // 6. NEGATIVE: Soft-delete an actual snapshot, then try to fetch it
  await api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.erase(connection, {
    productInquiryId: inquiry.id,
    inquirySnapshotId: snapshot1.id,
  });
  TestValidator.error("error: fetch soft-deleted snapshot")(() =>
    api.functional.shoppingMallAiBackend.admin.productInquiries.inquirySnapshots.at(connection, {
      productInquiryId: inquiry.id,
      inquirySnapshotId: snapshot1.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPayment";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate that an authenticated customer can successfully create a payment record for their own order.
 *
 * This test ensures the payment creation logic for customer-owned orders functions properly
 * under standard business rules. It covers all main positive and negative business flows:
 * 1. Customer registration with unique credentials/identity
 * 2. Authenticated customer creates a new order with valid info
 * 3. Customer submits a payment creation request against their order
 * 4. The payment record is returned and validated for accuracy and audit fields
 * 5. Negative: Creating payment for an order not owned by the customer must error
 *
 * Test Steps:
 * 1. Register a new customer and authenticate the session (retrieve JWT)
 * 2. Create a new order for that customer (explicit customer_id, basic business values)
 * 3. Create a payment with valid provider, method, amount, status, etc.
 * 4. Validate that:
 *    - All key fields in the payment match input/order (order_id, provider, method, status, audit fields, deleted_at)
 *    - Payment record includes proper order reference and field echo
 *    - Audit fields (created_at, updated_at) are present and ISO 8601 formatted
 * 5. Try creating a payment for a non-owned/random order and confirm error is thrown
 */
export async function test_api_order_payment_create_customer_success(
  connection: api.IConnection,
) {
  // 1. Register a new customer and authenticate session
  const customerInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  } satisfies ICustomerSignUp.Request;
  const register = await api.functional.auth.customer.register.signUp(connection, { body: customerInput });
  typia.assert(register);
  connection.headers = {
    ...connection.headers,
    Authorization: register.setHeaders.Authorization,
  };
  const customer = register.customer;

  // 2. Create a new order for this customer
  const orderInput = {
    customer_id: customer.id,
    order_number: RandomGenerator.alphaNumeric(16),
    total_amount: 99900,
    currency_code: "KRW",
    current_status: "created"
  } satisfies IShoppingMallAiBackendOrder.ICreate;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderInput });
  typia.assert(order);

  // 3. Create a payment record for the order
  const paymentInput = {
    order_id: order.id,
    payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
    payment_method: "card",
    transaction_id: RandomGenerator.alphaNumeric(20),
    amount: order.total_amount,
    currency_code: order.currency_code,
    payment_result: "completed"
  } satisfies IShoppingMallAiBackendOrderPayment.ICreate;
  const payment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, { orderId: order.id, body: paymentInput });
  typia.assert(payment);
  // Key business and audit field validations
  TestValidator.equals("order_id matches")(payment.order_id)(order.id);
  TestValidator.equals("amount matches")(payment.amount)(order.total_amount);
  TestValidator.equals("currency_code matches")(payment.currency_code)(order.currency_code);
  TestValidator.equals("method matches")(payment.payment_method)(paymentInput.payment_method);
  TestValidator.equals("provider matches")(payment.payment_provider_id)(paymentInput.payment_provider_id);
  TestValidator.equals("transaction_id matches")(payment.transaction_id)(paymentInput.transaction_id);
  TestValidator.equals("result matches")(payment.payment_result)(paymentInput.payment_result);
  TestValidator.predicate("created_at is ISO")(typeof payment.created_at === "string" && /^\d{4}-\d{2}-\d{2}T/.test(payment.created_at));
  TestValidator.predicate("updated_at is ISO")(typeof payment.updated_at === "string" && /^\d{4}-\d{2}-\d{2}T/.test(payment.updated_at));
  TestValidator.equals("deleted_at is null or undefined")(payment.deleted_at ?? null)(null);

  // 4. Negative scenario: Attempt payment for random non-owned order
  await TestValidator.error("Payment for non-owned/random order should fail")(async () => {
    await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
      orderId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        ...paymentInput,
