/**
 * Validate that creating a payment for an order in an invalid status (such as 'paid' or 'cancelled') is correctly rejected.
 *
 * Business context: In an e-commerce system, payments may only be added to orders that are in "created" or "pending" states. Once an order is marked as "paid" or "cancelled", additional payments should not be allowed for data integrity and business rule enforcement. Attempting to create a payment on such orders must produce an error, block the creation, and return a business-specific error response (such as HTTP 4xx and an error object as per contract).
 *
 * Steps:
 * 1. Register a new customer—obtain auth and customer id.
 * 2. Create an order for the customer. The order starts in a valid state (e.g., "created").
 * 3. Update the order to an invalid state for payment (e.g., status: "paid").
 * 4. Attempt to create a payment record for this order by POSTing to the payment endpoint with valid (randomized) payment details.
 * 5. Confirm that the API rejects the request—validate that an error is thrown and no payment is created.
 * 6. Optionally repeat with another invalid state (e.g., "cancelled").
 */
export async function test_api_order_payment_create_customer_invalid_status(
  connection: api.IConnection,
) {
  // 1. Register a customer
  const signup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Test@1234!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(signup);
  const customer = signup.customer;
  // token automatically applied to connection

  // 2. Create an order (status: 'created')
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customer.id,
      order_number: RandomGenerator.alphaNumeric(10),
      total_amount: typia.random<number>(),
      currency_code: "KRW",
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate
  });
  typia.assert(order);

  // 3. Update order to 'paid'
  const updatedOrder = await api.functional.shoppingMallAiBackend.customer.orders.update(connection, {
    orderId: order.id,
    body: {
      current_status: "paid"
    } satisfies IShoppingMallAiBackendOrder.IUpdate
  });
  typia.assert(updatedOrder);
  TestValidator.equals("order updated to paid")(updatedOrder.current_status)("paid");

  // 4. Attempt payment creation on paid order
  await TestValidator.error("cannot create payment for paid order")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
        orderId: order.id,
        body: {
          order_id: order.id,
          payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
          payment_method: "card",
          transaction_id: RandomGenerator.alphaNumeric(12),
          amount: order.total_amount,
          currency_code: order.currency_code,
          payment_result: "pending"
        } satisfies IShoppingMallAiBackendOrderPayment.ICreate
      });
    }
  );

  // 5. Update order to 'cancelled'
  const cancelledOrder = await api.functional.shoppingMallAiBackend.customer.orders.update(connection, {
    orderId: order.id,
    body: {
      current_status: "cancelled"
    } satisfies IShoppingMallAiBackendOrder.IUpdate
  });
  typia.assert(cancelledOrder);
  TestValidator.equals("order updated to cancelled")(cancelledOrder.current_status)("cancelled");

  // 6. Attempt payment creation on cancelled order
  await TestValidator.error("cannot create payment for cancelled order")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, {
        orderId: order.id,
        body: {
          order_id: order.id,
          payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
          payment_method: "bank_transfer",
          transaction_id: RandomGenerator.alphaNumeric(12),
          amount: order.total_amount,
          currency_code: order.currency_code,
          payment_result: "pending"
        } satisfies IShoppingMallAiBackendOrderPayment.ICreate
      });
    }
  );
}

