 * 2. Register a customer user (capture their UUID for order creation).
 * 3. Create a new order as the customer, providing valid info and amount (capture order ID and details).
 * 4. Switch connection context to admin authentication (using Authorization header from signUp response).
 * 5. Create a new payment as admin for the order.
 * 6. Validate that the returned payment correctly references the input (order and payment data), and has all required fields properly set.
 */
export async function test_api_order_payment_create_admin_success(
  connection: api.IConnection,
) {
  // 1. Register admin
