      total_amount: 10000,
      currency_code: "KRW",
      current_status: "created",
    } satisfies IShoppingMallAiBackendOrder.ICreate,
  });
  typia.assert(customerOrder);

  // 4. Switch to admin (set Authorization header)
  connection.headers = {
    ...connection.headers,
    Authorization: adminSignUp.setHeaders?.Authorization ?? adminSignUp.jwt,
  };

  // 5. Create payment for order as admin
  const paymentPayload = {
    order_id: customerOrder.id,
    payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
    payment_method: "card",
    transaction_id: "TXN-" + RandomGenerator.alphaNumeric(10),
