import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Validate that admin users cannot update order payment records that are either non-existent or reference immutable fields, enforcing business restrictions and error handling.
 *
 * Business context:
 * Admin APIs allow updating of certain payment record fields (status and payment_context), but must prohibit updates to non-existent records and must not allow attempts to mutate immutable fields (e.g., amount, transaction_id, etc. which are not in the update DTO).
 * This ensures integrity and correct permission enforcement, which are compliance/audit requirements for payment systems.
 *
 * Step-by-step test process:
 * 1. Register a new admin account and obtain Authorization.
 * 2. Register a new customer and obtain Authorization.
 * 3. Customer creates a valid order for context.
 * 4. Switch back to the admin account to attempt forbidden and negative update cases:
 *    a. Attempt to update a non-existent payment for a valid order (should fail).
 *    b. Attempt to update a random payment record on a random order (should also fail).
 *
 * Notes:
 * - It is impossible (by type design) to update immutable fields like 'amount' or 'transaction_id', as the DTO does not permit those fields. The type system already enforces the business rules, so this cannot be coerced or tested at runtime.
 * - Error cases are caught and asserted via TestValidator.error; specific error payloads/codes should be validated at the system level (not in E2E script).
 */
export async function test_api_order_payment_update_admin_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin!1234";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminAuth);
  connection.headers = { ...connection.headers, Authorization: adminAuth.setHeaders.Authorization };

  // 2. Register customer (needed to create an order)
  const custEmail = typia.random<string & tags.Format<"email">>();
  const custPassword = "Customer!1234";
  const customerAuth = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: custEmail,
      password: custPassword,
      name: "John Customer",
      nickname: "cust" + Math.floor(Math.random() * 100000),
      phone: "010" + Math.floor(Math.random() * 100000000).toString().padStart(8, "0"),
    },
  });
  typia.assert(customerAuth);
  connection.headers = { ...connection.headers, Authorization: customerAuth.setHeaders.Authorization };

  // 3. Customer creates a valid order for context
  const orderNumber = `ORD-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: {
      customer_id: customerAuth.customer.id,
      order_number: orderNumber,
      total_amount: 10000,
      currency_code: "USD",
      current_status: "created",
    },
  });
  typia.assert(order);

  // Switch back to admin to attempt forbidden/invalid update
  connection.headers = { ...connection.headers, Authorization: adminAuth.setHeaders.Authorization };

  // 4a. Attempt to update non-existent payment for the order (should fail)
  await TestValidator.error("update with non-existent orderPaymentId fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.update(connection, {
        orderId: order.id,
        orderPaymentId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          payment_result: "completed",
        },
      });
    },
  );

  // 4b. Attempt to update with totally random IDs (non-existent order and payment IDs)
  await TestValidator.error("update with random IDs fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.orders.orderPayments.update(connection, {
        orderId: typia.random<string & tags.Format<"uuid">>(),
        orderPaymentId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          payment_result: "completed",
          payment_context: "manual negative path test",
        },
      });
    },
  );

  // NOTE: Attempting to update immutable fields like 'amount', 'transaction_id' etc. is impossible via IUpdate DTO so type system already enforces business rules; no need to test further.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderPayment";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate deletion (soft/hard) of an order payment by an authenticated customer.
 * 
 * This test ensures that a customer can successfully delete a payment record belonging to their own order while adhering to business logic and schema. The workflow verifies:
 * - Registration/login as a customer
 * - Order creation (linked to the customer)
 * - Payment creation for that order
 * - Deletion (by the customer) of that payment record
 * - Validation that the payment is either (a) soft deleted (i.e., marked with deleted_at and not returned in normal queries) or (b) hard deleted (removed from all records)
 * - Ensures audit and referential integrity on deletion
 *
 * Steps:
 * 1. Register new customer (capture credentials & JWT)
 * 2. Place a new order for customer (record orderId)
 * 3. Create a payment for the order (capture orderPaymentId)
 * 4. Delete the payment as the authenticated customer
 * 5. Confirm the payment is deleted:
 *      - If soft delete: payment's deleted_at is set and payment cannot be found by default searches
 *      - If hard delete: payment record no longer exists (API returns not found or error)
 *      - Data integrity checks (order's accuracy/audit state, consistency)
 */
export async function test_api_order_payment_delete_customer_success(connection: api.IConnection) {
  // 1. Register a new customer and gain JWT auth context
  const registerBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPass123!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  } satisfies ICustomerSignUp.Request;
  const registerRes = await api.functional.auth.customer.register.signUp(connection, { body: registerBody });
  typia.assert(registerRes);
  const customer = registerRes.customer;

  // 2. Place a new order as this customer
  const orderCreateBody = {
    customer_id: customer.id,
    order_group_id: null,
    order_number: RandomGenerator.alphaNumeric(12),
    total_amount: 10000, // simple amount
    currency_code: "KRW",
    note: "E2E payment test order",
    current_status: "created",
  } satisfies IShoppingMallAiBackendOrder.ICreate;
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderCreateBody });
  typia.assert(order);

  // 3. Create payment for the order
  const paymentCreateBody = {
    order_id: order.id,
    payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
    payment_method: "card",
    transaction_id: RandomGenerator.alphaNumeric(16),
    amount: 10000,
    currency_code: "KRW",
    payment_result: "completed",
    payment_context: null,
  } satisfies IShoppingMallAiBackendOrderPayment.ICreate;
  const payment = await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, { orderId: order.id, body: paymentCreateBody });
  typia.assert(payment);

  // 4. Delete payment as this customer
  await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.erase(connection, {
    orderId: order.id,
    orderPaymentId: payment.id,
  });

  // 5. Confirm deletion: expect that attempting to pay again with same transaction_id now fails
  await TestValidator.error("Deleted payment transaction_id should not allow duplicate re-use")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.orders.orderPayments.create(connection, { orderId: order.id, body: paymentCreateBody });
    }
  );
}

