import type { IPageIShoppingMallAiBackendInquirySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendInquirySnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated retrieval of inquiry snapshot history for a customer who owns the inquiry.
 *
 * This test creates a product inquiry, updates it several times (which generates audit/evidence snapshots per update),
 * and then uses the search API to fetch the inquiry snapshot history.
 * It verifies that the returned snapshots match the updates and that pagination/meta data is correct.
 *
 * Steps:
 * 1. Create a new product inquiry as a customer (using random IDs for customer/product).
 * 2. Update the inquiry several times (with different fields) to generate audit snapshots.
 * 3. Search for all snapshots by inquiry ID via the paginated search endpoint (as the owning customer).
 * 4. Validate that the returned data contains at least as many snapshots as updates performed, and that core snapshot data aligns with update history.
 */
export async function test_api_inquiry_snapshot_search_customer_success(connection: api.IConnection) {
  // 1. Create a new inquiry
  const inquiryCreate = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    title: `Initial inquiry: ${RandomGenerator.paragraph(1)()}`,
    body: RandomGenerator.paragraph(1)(),
    public: true,
  } satisfies IShoppingMallAiBackendProductInquiry.ICreate;
  const created = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, { body: inquiryCreate });
  typia.assert(created);

  // 2. Perform several updates (generating snapshots)
  const updates: IShoppingMallAiBackendProductInquiry.IUpdate[] = [
    { title: `Edit 1: ${RandomGenerator.alphabets(6)}`, status: "waiting" },
    { body: `Body update 2: ${RandomGenerator.alphaNumeric(10)}`, status: "waiting" },
    { public: false, status: "answered" },
    { title: `Edit 4: ${RandomGenerator.alphabets(5)}`, body: `Body final: ${RandomGenerator.alphaNumeric(8)}`, status: "under_review" }
  ];
  for (const upd of updates) {
    await api.functional.shoppingMallAiBackend.customer.productInquiries.update(connection, {
      productInquiryId: created.id,
      body: upd,
    });
  }

  // 3. Search all inquiry snapshots (as inquiry owner, using inquiry_id filter)
  const snapshotSearchReq = {
    inquiry_id: created.id,
    // fetch all: set high limit to get all (assuming limit is enough)
    limit: 10,
    page: 1,
    sort_by: "changed_at",
    sort_direction: "asc"
  } satisfies IShoppingMallAiBackendInquirySnapshot.IRequest;
  const pageResult = await api.functional.shoppingMallAiBackend.customer.productInquiries.inquirySnapshots.search(connection, {
    productInquiryId: created.id,
    body: snapshotSearchReq,
  });
  typia.assert(pageResult);

  // 4. Validate result: snapshots length >= 1 + updates (original + updates)
  const numUpdatesPerformed = updates.length;
  TestValidator.predicate("# of snapshots >= original + updates")(
    pageResult.data.length >= 1 + numUpdatesPerformed
  );
  // Optionally, check newest snapshot fields match last update
  const latestSnapshot = pageResult.data[pageResult.data.length - 1];
  if (latestSnapshot) {
    const lastUpdate = updates[updates.length - 1];
    if (lastUpdate.title !== undefined) {
      TestValidator.equals("latest title")(latestSnapshot.title)(lastUpdate.title);
    }
    if (lastUpdate.body !== undefined) {
      TestValidator.equals("latest body")(latestSnapshot.body)(lastUpdate.body);
    }
    if (lastUpdate.public !== undefined) {
      TestValidator.equals("latest public")(latestSnapshot.public)(lastUpdate.public);
    }
    TestValidator.equals("latest status")(latestSnapshot.status)(lastUpdate.status);
  }
}

