  await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerBEmail,
      password: "1234!@#Abc",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  // 6. Attempt to create an inquiry snapshot for A's inquiry as B: permission expected to be denied
  await TestValidator.error("permission denied: customer B cannot create snapshot for A's inquiry")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.productInquiries.inquirySnapshots.create(connection, {
        productInquiryId: inquiryId,
        body: {
