  });
  typia.assert(sellerB);

  // Use Seller A's session for product creation
  const sellerAConnection = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: sellerA.setHeaders.Authorization } };
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(sellerAConnection, {
    body: {
      seller_id: sellerA.sellerId,
