import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderItem";
import type { IPageIShoppingMallAiBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderItem";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Validate customer order item listing, paging, filtering, and access control.
 *
 * This scenario tests the ability for a customer to:
 * 1. Log in and acquire a session (auth).
 * 2. Create an order as their own customer entity.
 * 3. Add multiple (3+) items to that order (distinct products, product snapshots, and prices).
 * 4. Retrieve the list of all items for that order using PATCH
 *    a. Confirm all created items are listed when pagination covers them
 *    b. Confirm page-limited responses respect "page" and "pageSize"
 *    c. Filter by product_id and confirm correct item(s) returned
 *    d. Validate access control (cannot access unrelated orders)
 * 5. Type and business rule validations on all responses.
 */
export async function test_api_order_item_list_by_customer(connection: api.IConnection) {
  // 1. Log in as customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "1qaz2wsx!";
  const signIn = await api.functional.auth.customer.login.signIn(connection, {
    body: { email, password } satisfies ICustomerSignIn.Request,
  });
  typia.assert(signIn);
  // Set Authorization token to connection
  connection.headers = { ...connection.headers, Authorization: signIn.setHeaders.Authorization };

  // 2. Create an order for this customer
  const orderCreate: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: signIn.customer.id,
    order_group_id: null,
    order_number: RandomGenerator.alphaNumeric(10),
    total_amount: 0,
    currency_code: 'KRW',
    note: null,
    current_status: "created",
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderCreate });
  typia.assert(order);

  // 3. Add multiple items to this order
  const createdItems: IShoppingMallAiBackendOrderItem[] = [];
  for (let i = 0; i < 5; ++i) {
    const product_id = typia.random<string & tags.Format<"uuid">>();
    const itemCreate: IShoppingMallAiBackendOrderItem.ICreate = {
      order_id: order.id,
      product_id,
      product_snapshot_id: typia.random<string & tags.Format<"uuid">>(),
      quantity: 1,
      unit_price: 10000 + i * 1000,
      currency_code: 'KRW',
      note: i % 2 ? RandomGenerator.paragraph()(1) : null,
    };
    const item = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.create(connection, { orderId: order.id, body: itemCreate });
    typia.assert(item);
    createdItems.push(item);
  }

  // 4a. Retrieve all items without filtering (page large enough)
  const allItems = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.index(connection, {
    orderId: order.id,
    body: { order_id: order.id, page: 1, pageSize: 10 } satisfies IShoppingMallAiBackendOrderItem.IRequest,
  });
  typia.assert(allItems);
  TestValidator.equals("all items count")(allItems.data.length)(createdItems.length);
  // Confirm all created items are present
  for (const item of createdItems) {
    const match = allItems.data.find(i => i.id === item.id);
    TestValidator.predicate("item returned")(!!match);
    if (match) TestValidator.equals("item fields")(match.product_id)(item.product_id);
  }

  // 4b. Pagination - page 2 with pageSize 2
  const page2 = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.index(connection, {
    orderId: order.id,
    body: { order_id: order.id, page: 2, pageSize: 2 } satisfies IShoppingMallAiBackendOrderItem.IRequest,
  });
  typia.assert(page2);
  // Page 2 should contain next 2 items, unless fewer remain
  const expectedPage2Length = createdItems.length - 2 * 1 >= 2 ? 2 : Math.max(0, createdItems.length - 2);
  TestValidator.equals("page 2 length")(page2.data.length)(expectedPage2Length);
  // Confirm different items across pages
  const firstPageIds = allItems.data.slice(0, 2).map(i => i.id);
  for (const item of page2.data) TestValidator.predicate("item not in page 1")(!firstPageIds.includes(item.id));

  // 4c. Filtering by product_id
  const filterByProduct = createdItems[2];
  const filterRes = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.index(connection, {
    orderId: order.id,
    body: { order_id: order.id, product_id: filterByProduct.product_id, page: 1, pageSize: 10 } satisfies IShoppingMallAiBackendOrderItem.IRequest,
  });
  typia.assert(filterRes);
  TestValidator.equals("filtered by product_id")(filterRes.data.length)(1);
  TestValidator.equals("filtered product matches")(filterRes.data[0].id)(filterByProduct.id);

  // 4d. Access Control: cannot view items for unrelated orders
  const order2 = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, {
    body: { ...orderCreate, order_number: RandomGenerator.alphaNumeric(10) }
  });
  typia.assert(order2);
  const emptyRes = await api.functional.shoppingMallAiBackend.customer.orders.orderItems.index(connection, {
    orderId: order2.id,
    body: { order_id: order2.id, page: 1, pageSize: 10 } satisfies IShoppingMallAiBackendOrderItem.IRequest,
  });
  typia.assert(emptyRes);
  TestValidator.equals("no items in unrelated order")(emptyRes.data.length)(0);
}

