import type { IShoppingMallAiBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductBundle";

/**
 * Validates that an admin can update a product bundle's name, description, and price for a product successfully.
 *
 * Business context:
 * - Product bundles are managed by the admin interface.
 * - Each bundle is associated with a product.
 * - Updating the bundle should apply changes and reflect them in both the API response and audit records.
 * - The operation must obey business validation rules.
 *
 * Step-by-step process:
 * 1. Create a new product as a prerequisite (admin, required for bundle association).
 * 2. Create an initial product bundle for that product with valid initial data.
 * 3. Update the product bundle with new name, description, and price as admin using the update API.
 * 4. Verify the response reflects the changes (name, description, bundle_price).
 * 5. Ensure that the update timestamp advances and bundle_id, productId remain unchanged.
 * 6. (Business assertion) Business validation: name non-empty, price non-negative.
 */
export async function test_api_product_bundle_update_success_admin(
  connection: api.IConnection,
) {
  // 1. Create a new product
  const product = await api.functional.shoppingMallAiBackend.admin.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: `sku-${typia.random<string>()}`,
      name: "Original product for bundle test",
      status: "draft",
      description: "This is a product used for product bundle update admin flow.",
      main_image_uri: null,
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 2. Create a product bundle for that product
  const bundle = await api.functional.shoppingMallAiBackend.admin.products.productBundles.create(connection, {
    productId: product.id,
    body: {
      main_product_id: product.id,
      code: `bundle-${typia.random<string>()}`,
      name: "Initial Test Bundle",
      status: "active",
      description: "Initial description for bundle.",
      bundle_policy: null,
      bundle_price: 10000,
    } satisfies IShoppingMallAiBackendProductBundle.ICreate,
  });
  typia.assert(bundle);

  // Save original updated_at for later comparison
  const previousUpdatedAt = bundle.updated_at;

  // 3. Perform an update with new name, description, price
  const updateInput = {
    name: "Updated Bundle Name",
    description: "Updated bundle description (admin test)",
    bundle_price: 18999,
  } satisfies IShoppingMallAiBackendProductBundle.IUpdate;
  const updatedBundle = await api.functional.shoppingMallAiBackend.admin.products.productBundles.update(connection, {
    productId: product.id,
    productBundleId: bundle.id,
    body: updateInput,
  });
  typia.assert(updatedBundle);

  // 4. Verify response reflects changes
  TestValidator.equals("bundle name is updated")(updatedBundle.name)(updateInput.name);
  TestValidator.equals("bundle description is updated")(updatedBundle.description)(updateInput.description);
  TestValidator.equals("bundle price is updated")(updatedBundle.bundle_price)(updateInput.bundle_price);
  TestValidator.equals("bundle id consistent")(updatedBundle.id)(bundle.id);
  TestValidator.equals("main_product_id consistent")(updatedBundle.main_product_id)(bundle.main_product_id);
  TestValidator.predicate("updated_at changed after update")(updatedBundle.updated_at > previousUpdatedAt);

  // 5. Business validations
  TestValidator.predicate("name is not empty after update")(!!updatedBundle.name && updatedBundle.name.length > 0);
  TestValidator.predicate("price non-negative after update")(typeof updatedBundle.bundle_price === "number" ? updatedBundle.bundle_price >= 0 : true);
}

