/**
 * Validates the deletion (logical/physical) of an order payment by an admin.
 *
 * Test covers:
 * 1. Creating a payment record for a specific order as a privileged admin
 * 2. Deleting that payment by its ID
 * 3. Ensuring double-deletion is handled by the API (not found or idempotent)
 *
 * Notes:
 * - Listing payments or validating financial calculation exclusion is not implemented as SDK for these ops is not provided.
 * - Ensures proper logical deletion as per schema by confirming deleted_at on creation is null
 * - No business logic or audit log validation possible here due to SDK limitations
 */
export async function test_api_order_payment_delete_success_as_admin(
  connection: api.IConnection,
) {
  // 1. Create a payment entry (dependency: to have a deletable payment)
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const paymentPayload: IShoppingMallAiBackendOrderPayment.ICreate = {
    order_id: orderId,
    payment_provider_id: typia.random<string & tags.Format<"uuid">>(),
    payment_method: "card",
    transaction_id: typia.random<string>(),
    amount: 10000.5,
    currency_code: "USD",
