 *
 * 1. Register a new customer to serve as the wallet owner
 * 2. Create a point wallet for this customer as an admin
 * 3. Delete the wallet using the admin soft-delete endpoint
 * 4. Attempt to delete the same wallet again to verify idempotency (should not error, or should return a documented error)
 *
 * Edge cases:
 * - Ensures a point wallet can be deleted only if policy allows; in-use constraints cannot be tested because there is no transaction API
 * - Cannot directly verify deleted_at field or post-delete absence since there is no query or list API
 * - If no error occurs on repeated deletion, that is considered proof of idempotency for this E2E
 */
export async function test_api_point_wallet_soft_delete_and_idempotency(connection: api.IConnection) {
  // 1. Register a new customer to serve as the wallet owner
  const signUpRequest = {
