  } satisfies IShoppingMallAiBackendPoint.ICreate;
  const pointWallet = await api.functional.shoppingMallAiBackend.admin.points.create(connection, { body: createPointBody });
  typia.assert(pointWallet);

  // 3. Delete the wallet using the admin endpoint
  await api.functional.shoppingMallAiBackend.admin.points.erase(connection, { pointId: pointWallet.id });

  // 4. Attempt to delete the same wallet again (should no-op or return meaningful error)
  await api.functional.shoppingMallAiBackend.admin.points.erase(connection, { pointId: pointWallet.id });

  // Business logic: While deletion idempotency is confirmed by repeat success, there is no way to further check deleted_at or list post-delete records with the present API.
}

