import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteAddress";

/**
 * Validate soft deletion (unfavorite) of a customer's favorite address by its owner.
 *
 * This test verifies that when a customer requests to unfavorite (soft delete) one of their saved addresses, the system appropriately marks the favorite as deleted (by setting `deleted_at` on the favorite-address record) rather than removing it physically, and all reference/integrity is maintained.
 *
 * Test process:
 * 1. Prepare test UUIDs for customer and address (simulating customer context -- assumes authentication handled by test environment)
 * 2. Create a favorite address record for this customer/address pair via API.
 * 3. Assert the favoriteAddress is created and not soft-deleted (deleted_at === null)
 * 4. Soft delete (unfavorite) by favoriteAddressId via DELETE endpoint.
 * 5. Attempt to re-create the same favorite to observe business logic: if API allows recovery/re-creation, new favoriteAddress is returned; else, error may indicate soft-deletion retention. Final result allows us to infer that soft-deletion logic and physical integrity are preserved.
 * 6. Confirm that the related address_id remains logically referenced after favorite is unfavorited, with available data.
 */
export async function test_api_favorite_address_soft_delete_by_owner(connection: api.IConnection) {
  // 1. Prepare random UUIDs simulating a customer and an address
  const customer_id = typia.random<string & tags.Format<"uuid">>();
  const address_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a favoriteAddress record linking the customer and address
  const favorite = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, {
    body: { customer_id, address_id },
  });
  typia.assert(favorite);
  TestValidator.equals("favoriteAddress ownership")(favorite.customer_id)(customer_id);
  TestValidator.equals("favoriteAddress for address")(favorite.address_id)(address_id);
  TestValidator.equals("Not deleted initially")(favorite.deleted_at)(null);

  // 3. Soft delete (unfavorite) the favorite address by its id
  await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.erase(connection, {
    favoriteAddressId: favorite.id,
  });

  // 4. Attempt to re-create the favorite for the same customer/address. If API permits, a new favorite will be returned.
  const favorite2 = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, {
    body: { customer_id, address_id },
  });
  typia.assert(favorite2);
  TestValidator.equals("Re-created favorite for same customer & address")(favorite2.customer_id)(customer_id);
  TestValidator.equals("Address unchanged after unfavorite")(favorite2.address_id)(address_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteAddress";

/**
 * Validate error handling and access control for soft deleting a favorite address record (unfavoriting).
 *
 * This test covers two primary negative scenarios:
 * 1. A customer (CustomerB) attempts to unfavorite (soft delete) a favorite address record belonging to another customer (CustomerA). This should result in a forbidden/access denied error, ensuring only the owner can unfavorite their own address.
 * 2. The original owner (CustomerA) tries to unfavorite the same address a second time (after already soft deleting it). This should result in an error (not found or similar), confirming the operation is idempotent and that no redundant database changes occur.
 *
 * Notes:
 * - This test uses random UUIDs to simulate different user identities and favorite address records. In production, true authentication context would be enforced; here we rely on the API's permission logic to enforce access control.
 * - Actual validation of audit logs or database effects is out of scope since no read or log endpoint is exposed.
 *
 * Steps:
 * 1. Simulate CustomerA and CustomerB as separate unique UUIDs.
 * 2. CustomerA creates a favorite address record.
 * 3. CustomerB attempts to DELETE (unfavorite) CustomerA's favorite address (should fail).
 * 4. CustomerA unfavorites (soft deletes) their address normally (should succeed).
 * 5. CustomerA attempts to unfavorite the same address again (should fail or yield no-op error from API).
 */
export async function test_api_favorite_address_delete_not_owned_or_already_deleted(
  connection: api.IConnection,
) {
  // 1. Simulate two customers with unique random UUIDs
  const customerAId = typia.random<string & tags.Format<"uuid">>();
  const addressId = typia.random<string & tags.Format<"uuid">>();
  const customerBId = typia.random<string & tags.Format<"uuid">>();

  // 2. CustomerA creates a favorite address
  const favorite = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(
    connection,
    {
      body: {
        customer_id: customerAId,
        address_id: addressId,
      } satisfies IShoppingMallAiBackendFavoriteAddress.ICreate,
    },
  );
  typia.assert(favorite);

  // 3. CustomerB tries to unfavorite CustomerA's record (should error)
  //    (This presumes the API enforces ownership based on customer_id or session.)
  await TestValidator.error("Non-owner cannot unfavorite address")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.erase(
        connection,
        {
          favoriteAddressId: favorite.id,
        },
      );
    },
  );

  // 4. CustomerA unfavorites (soft deletes) the address (should succeed)
  await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.erase(
    connection,
    {
      favoriteAddressId: favorite.id,
    },
  );

  // 5. CustomerA tries to unfavorite again (should error or no-op)
  await TestValidator.error("Cannot unfavorite already unfavorited address")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.erase(
        connection,
        {
          favoriteAddressId: favorite.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteSnapshot";
import type { IPageIShoppingMallAiBackendFavoriteSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendFavoriteSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated and filtered retrieval of customer favorite snapshot records.
 *
 * This test ensures that a customer can retrieve their favorite snapshot records using advanced filtering and pagination options.
 * At least three favorite snapshot records of different types (PRODUCT, INQUIRY, ADDRESS) are created for the logged-in user.
 * The test validates filtering by type (PRODUCT/ADDRESS), date ranges, correct pagination metadata, and edge cases like empty results.
 * Steps:
 * 1. Create favorite snapshot records of PRODUCT, INQUIRY, and ADDRESS types for the same customer.
 * 2. Retrieve all records with no filters, validating all created records are present and pagination metadata is accurate.
 * 3. Filter by type (PRODUCT) and ensure only product records are returned.
 * 4. Filter by type (ADDRESS) and ensure only address records are returned.
 * 5. Filter by date range to verify records match the expected snapshot created_at bounds.
 * 6. Use limit=1 to check pagination metadata reflects the full set of records.
 * 7. Apply a filter using a never-used favorite_product_id, expecting an empty result and correct pagination.
 */
export async function test_api_favorite_snapshot_paginated_filtered_search(
  connection: api.IConnection,
) {
  // 1. Create favorite snapshots of all three supported types
  const createdProduct = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: {
      favorite_product_id: typia.random<string & tags.Format<"uuid">>(),
      favorite_inquiry_id: null,
      favorite_address_id: null,
      target_type: "PRODUCT",
      snapshot_object_id: typia.random<string & tags.Format<"uuid">>(),
      serialized_object: JSON.stringify({ foo: RandomGenerator.alphaNumeric(10) }),
    },
  });
  typia.assert(createdProduct);
  const createdInquiry = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: {
      favorite_product_id: null,
      favorite_inquiry_id: typia.random<string & tags.Format<"uuid">>(),
      favorite_address_id: null,
      target_type: "INQUIRY",
      snapshot_object_id: typia.random<string & tags.Format<"uuid">>(),
      serialized_object: JSON.stringify({ bar: RandomGenerator.alphaNumeric(10) }),
    },
  });
  typia.assert(createdInquiry);
  const createdAddress = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: {
      favorite_product_id: null,
      favorite_inquiry_id: null,
      favorite_address_id: typia.random<string & tags.Format<"uuid">>(),
      target_type: "ADDRESS",
      snapshot_object_id: typia.random<string & tags.Format<"uuid">>(),
      serialized_object: JSON.stringify({ baz: RandomGenerator.alphaNumeric(10) }),
    },
  });
  typia.assert(createdAddress);

  // 2. Search with no filters - expect all created records are present
  const unfiltered = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.search(connection, {
    body: {},
  });
  typia.assert(unfiltered);
  // Assert that all created IDs are present in the result
  TestValidator.predicate("all created present")([
    createdProduct.id,
    createdInquiry.id,
    createdAddress.id,
  ].every((id) => unfiltered.data.map((r) => r.id).includes(id)));
  // Check pagination metadata reflects at least our new records
  TestValidator.predicate("pagination valid total")(
    unfiltered.pagination.records >= 3 &&
      unfiltered.data.length <= unfiltered.pagination.limit &&
      unfiltered.pagination.pages >= 1,
  );

  // 3. Filter by type=PRODUCT
  const filteredProduct = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.search(connection, {
    body: { target_type: "PRODUCT" },
  });
  typia.assert(filteredProduct);
  TestValidator.predicate("only product type")(
    filteredProduct.data.every((rec) => rec.target_type === "PRODUCT"),
  );

  // 4. Filter by type=ADDRESS
  const filteredAddress = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.search(connection, {
    body: { target_type: "ADDRESS" },
  });
  typia.assert(filteredAddress);
  TestValidator.predicate("only address type")(
    filteredAddress.data.every((rec) => rec.target_type === "ADDRESS"),
  );

  // 5. Date range filtering (using ISO string comparison which is valid for date-time strings)
  const from = createdProduct.created_at;
  const to = createdInquiry.created_at >= from ? createdInquiry.created_at : createdProduct.created_at;
  const byDateRange = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.search(connection, {
    body: { created_at_from: from, created_at_to: to },
  });
  typia.assert(byDateRange);
  // Only those whose created_at is within [from, to]
  const expectedDateIds = [createdProduct, createdInquiry]
    .filter((rec) => rec.created_at >= from && rec.created_at <= to)
    .map((rec) => rec.id);
  TestValidator.predicate("ids in date range")(
    expectedDateIds.every((id) => byDateRange.data.map((r) => r.id).includes(id)),
  );

  // 6. Pagination: use limit=1 to test correct metadata
  const paged = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.search(connection, {
    body: { limit: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("limit 1")(paged.pagination.limit)(1);
  TestValidator.predicate("at most 1 record")(
    paged.data.length <= 1,
  );
  TestValidator.predicate("pages covers total records")(
    paged.pagination.pages >= Math.ceil(unfiltered.pagination.records / 1),
  );

  // 7. Edge case: use a never-used favorite_product_id to expect empty result
  let unusedUuid: string & tags.Format<"uuid">;
  do {
    unusedUuid = typia.random<string & tags.Format<"uuid">>();
  } while ([createdProduct.favorite_product_id].includes(unusedUuid));

  const empty = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.search(connection, {
    body: { favorite_product_id: unusedUuid },
  });
  typia.assert(empty);
  TestValidator.equals("empty data")(empty.data.length)(0);
  TestValidator.equals("empty records")(empty.pagination.records)(0);
  TestValidator.equals("empty pages")(empty.pagination.pages)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendFavoriteSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteSnapshot";
import type { IPageIShoppingMallAiBackendFavoriteSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendFavoriteSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate error scenarios and edge cases for favorite snapshot searching by customer.
 *
 * This test covers three business-critical negative or edge scenarios for the favorite snapshot search endpoint:
 *
 * 1. A user attempts to search (PATCH /shoppingMallAiBackend/customer/favoriteSnapshots) the favorite snapshots of another customer (by specifying customer_id filter for a different user). This should yield a permission error and the user should not be allowed to view snapshots that do not belong to them.
 * 2. The search endpoint is called with an invalid combination of filter parameters, such as a malformed UUID or logically impossible range. The system should return a validation/business error for invalid input.
 * 3. The endpoint is used with filters that are valid but will not match any data (e.g., wrong type, impossible date range, unknown favorite object ID). This should succeed with a result containing an empty data set and correct pagination fields.
 *
 * Prerequisite: At least one snapshot must exist for the initial user, so a favorite snapshot will be created for the primary test user before scenario steps begin.
 *
 * Test Plan:
 * 1. Test setup: Register two test users (customer A and customer B).
 * 2. As customer A, create one valid favorite snapshot for at least one object.
 * 3. As customer B, attempt to search customer A's snapshots by passing customer_id=A. Expect permission denied error.
 * 4. As customer A, call search with deliberately invalid filter values (malformed UUID or invalid date range, e.g., created_at_from > created_at_to). Expect validation/business error.
 * 5. As customer A, call search with valid filters that produce no results (e.g., random non-existent favorite_product_id and valid type). Expect success with empty result data array and proper pagination fields.
 */
export async function test_api_favorite_snapshot_search_no_permission_or_nonexistent(connection: api.IConnection) {
  // 1. Register customer A
  const customerAId = typia.random<string & tags.Format<"uuid">>();
  // Assume customer registration/login API exists; if not, skip actual registration and use random UUID as identity.

  // 2. Register customer B
  const customerBId = typia.random<string & tags.Format<"uuid">>();
  // Again, assume authentication; if not, just use customerBId for filtering.

  // 3. As customer A, create a favorite snapshot
  const favoriteProductId = typia.random<string & tags.Format<"uuid">>();
  const snapshotObjectId = typia.random<string & tags.Format<"uuid">>();
  const createdSnapshot = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.create(connection, {
    body: {
      favorite_product_id: favoriteProductId,
      favorite_inquiry_id: null,
      favorite_address_id: null,
      target_type: "PRODUCT",
      snapshot_object_id: snapshotObjectId,
      serialized_object: JSON.stringify({ id: snapshotObjectId, name: "TestProduct" })
    } satisfies IShoppingMallAiBackendFavoriteSnapshot.ICreate
  });
  typia.assert(createdSnapshot);

  // 4. As customer B, attempt to search for customer A's snapshots (expect permission error)
  TestValidator.error("permission denied searching other customer's snapshots")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.search(connection, {
      body: { customer_id: customerAId } satisfies IShoppingMallAiBackendFavoriteSnapshot.IRequest
    })
  );

  // 5. As customer A, search with invalid filters (malformed UUID, invalid date range)
  TestValidator.error("malformed UUID in favorite_product_id should fail")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.search(connection, {
      body: { favorite_product_id: "not-a-uuid" as any } // purposely invalid
    })
  );
  TestValidator.error("created_at_from > created_at_to fails")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.search(connection, {
      body: { created_at_from: "2025-12-31T00:00:00Z", created_at_to: "2023-01-01T00:00:00Z" }
    })
  );

  // 6. As customer A, search with valid but non-matching filters (empty returns)
  const emptyQueryResult = await api.functional.shoppingMallAiBackend.customer.favoriteSnapshots.search(connection, {
    body: { favorite_product_id: typia.random<string & tags.Format<"uuid">>(), target_type: "PRODUCT" } satisfies IShoppingMallAiBackendFavoriteSnapshot.IRequest
  });
  typia.assert(emptyQueryResult);
  TestValidator.equals("no data for unknown filter")(emptyQueryResult.data.length)(0);
  TestValidator.equals("pagination current page is 1")(emptyQueryResult.pagination.current)(1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendArticleCategory";
import type { IPageIShoppingMallAiBackendArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendArticleCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for advanced admin search & pagination on article categories.
 *
 * This test validates that the admin article category search endpoint supports multiple filter/search scenarios, including:
 *   - Partial search by code and name
 *   - Parent-child tree filtering (parent_id as root and nested)
 *   - Active/inactive status filter
 *   - Pagination robustness (more than one page, correct limit/page)
 *
 * The test ensures only admin can access, and invalid search input returns error.
 *
 * Steps:
 * 1. Create a root category (no parent)
 * 2. Create 5+ child categories with parent structure
 * 3. Create several more categories (different codes/names, a mix of active/inactive and roots/children)
 * 4. Perform search with:
 *     - Name partial match (should match relevant names only)
 *     - Code partial match (should match only code subset)
 *     - parent_id filter (tree separation, only matching children or roots)
 *     - is_active filter (return only active/inactive accordingly)
 *     - Combined filters (e.g. parent_id + is_active)
 *     - Pagination (limit=2, page=2, etc. check boundaries and total page count)
 * 5. Validate search results each time (correct hits, correct total count, records on correct page)
 * 6. Attempt search as unauthorized user (simulate) and expect error
 * 7. Send invalid search filter (e.g., negative limit or page, impossible filter) and expect error.
 */
export async function test_api_article_category_advanced_search_admin(connection: api.IConnection) {
  // 1. Create root category
  const root = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
    body: {
      parent_id: null,
      name: "RootCat",
      code: "ROOT",
      sort_order: 0,
      is_active: true,
    },
  });
  typia.assert(root);

  // 2. Create 5+ children under root
  const children = await Promise.all(
    ArrayUtil.repeat(5)((i) =>
      api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
        body: {
          parent_id: root.id,
          name: `ChildCat${i + 1}`,
          code: `CHILD${i + 1}`,
          sort_order: i + 1,
          is_active: true,
        },
      })
    )
  );
  for (const child of children) typia.assert(child);

  // 3. Create more categories (varied: roots, children, codes, names, is_active)
  const mixA = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
    body: {
      parent_id: null,
      name: "FAQ",
      code: "FAQA",
      sort_order: 99,
      is_active: false,
    },
  });
  typia.assert(mixA);
  const mixB = await api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
    body: {
      parent_id: mixA.id,
      name: "InactiveChild",
      code: "INACTIVECHILD",
      sort_order: 100,
      is_active: false,
    },
  });
  typia.assert(mixB);

  // 4a. Search by name (partial)
  let res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { name: "ChildCat" },
  });
  typia.assert(res);
  TestValidator.predicate("all names include keyword")(
    res.data.every((c) => c.name.includes("ChildCat"))
  );
  TestValidator.predicate("contains all children")(
    children.every((child) => res.data.some((c) => c.id === child.id))
  );

  // 4b. Search by code (partial)
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { code: "CHILD" },
  });
  typia.assert(res);
  TestValidator.predicate("all codes include keyword")(
    res.data.every((c) => c.code.includes("CHILD"))
  );

  // 4c. Filter by parent_id (should return only direct children of root)
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { parent_id: root.id },
  });
  typia.assert(res);
  TestValidator.equals("direct child count")(res.data.length)(children.length);
  TestValidator.predicate("all have parent_id=root.id")(
    res.data.every((c) => c.parent_id === root.id)
  );

  // 4d. Filter by is_active = false
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { is_active: false },
  });
  typia.assert(res);
  TestValidator.predicate("all inactive")(
    res.data.every((c) => c.is_active === false)
  );
  TestValidator.predicate("mixA and mixB are found")(
    [mixA.id, mixB.id].every((id) => res.data.some((c) => c.id === id))
  );

  // 4e. Combined filter: parent_id + is_active=false
  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { parent_id: mixA.id, is_active: false },
  });
  typia.assert(res);
  TestValidator.predicate("only InactiveChild returned")(
    res.data.length === 1 && res.data[0].id === mixB.id
  );

  // 4f. Pagination test: add extra categories for paging
  const pagecats = await Promise.all(
    ArrayUtil.repeat(4)((i) =>
      api.functional.shoppingMallAiBackend.admin.articleCategories.create(connection, {
        body: {
          parent_id: null,
          name: `PageCat${i + 1}`,
          code: `PAGE${i + 1}`,
          sort_order: 100 + i,
          is_active: true,
        },
      })
    )
  );
  for (const pagecat of pagecats) typia.assert(pagecat);

  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { name: "PageCat", limit: 2, page: 1 },
  });
  typia.assert(res);
  TestValidator.equals("should be limited to 2 results")(res.data.length)(2);
  TestValidator.equals("pagination info, page 1")(res.pagination.current)(1);
  TestValidator.equals("total pages at least 2")(res.pagination.pages >= 2)(true);

  res = await api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
    body: { name: "PageCat", limit: 2, page: 2 },
  });
  typia.assert(res);
  TestValidator.equals("should be limited to 2 results")(res.data.length)(2);
  TestValidator.equals("pagination info, page 2")(res.pagination.current)(2);

  // 5. Unauthorized access: simulate non-admin, or invalid token if available (expect error)
  if (connection.headers) {
    const fakeConnection = {
      ...connection,
      headers: {
        ...connection.headers,
        Authorization: "Bearer FAKEINVALIDTOKEN",
      },
    };
    await TestValidator.error("unauthorized fails")(
      () =>
        api.functional.shoppingMallAiBackend.admin.articleCategories.search(fakeConnection, {
          body: {},
        })
    );
  }

  // 6. Invalid filter (e.g. negative page/limit) expect error
  await TestValidator.error("invalid limit")(
    () =>
      api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
        body: { limit: -1, page: 1 },
      })
  );
  await TestValidator.error("invalid page")(
    () =>
      api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
        body: { limit: 1, page: -2 },
      })
  );
  await TestValidator.error("impossible parent_id")(
    () =>
      api.functional.shoppingMallAiBackend.admin.articleCategories.search(connection, {
        body: { parent_id: "deadbeef" },
      })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
