import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test updating allowed attributes (status and label) of an existing mileage wallet by ID in the admin interface.
 *
 * This test ensures proper update and validation handling for mileage wallet records. To cover realistic business scenarios and permissions, it follows:
 *
 * 1. Register a new customer (for wallet ownership context).
 * 2. Create a mileage wallet for the customer via the admin endpoint, setting program type and initial status/label.
 * 3. Update the wallet's status and/or label fields using the update endpoint.
 * 4. Confirm the response immediately reflects the changes. (Persistence and audit logging can't be checked, as no such endpoint is provided.)
 * 5. Confirm only allowed fields (status, label, security_code) are updatable and that attempts to change disallowed fields are rejected by the API.
 * 6. Confirm an update attempt for a non-existent mileage wallet ID returns a suitable error.
 *
 * Note: Deletion and audit log validation cannot be tested, since delete and audit APIs are not available.
 */
export async function test_api_admin_mileage_wallet_update_attributes(connection: api.IConnection) {
  // 1. Register a new customer
  const signupReq: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "1234",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const signupResult = await api.functional.auth.customer.register.signUp(connection, { body: signupReq });
  typia.assert(signupResult);
  const customer = signupResult.customer;

  // 2. Admin creates mileage wallet for the customer
  const walletCreate: IShoppingMallAiBackendMileageWallet.ICreate = {
    customer_id: customer.id,
    wallet_program: RandomGenerator.alphabets(10),
    wallet_status: "active",
    wallet_label: "Initial Wallet",
    security_code: null,
  };
  const createdWallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.create(connection, { body: walletCreate });
  typia.assert(createdWallet);

  // 3a. Update wallet's status and label
  const updateReq1: IShoppingMallAiBackendMileageWallet.IUpdate = {
    id: createdWallet.id,
    wallet_status: "locked",
    wallet_label: "Wallet Locked",
  };
  const updatedWallet = await api.functional.shoppingMallAiBackend.admin.mileageWallets.update(connection, {
    mileageWalletId: createdWallet.id,
    body: updateReq1,
  });
  typia.assert(updatedWallet);
  TestValidator.equals("wallet_status should update")(updatedWallet.wallet_status)("locked");
  TestValidator.equals("wallet_label should update")(updatedWallet.wallet_label)("Wallet Locked");

  // 3b. Update security_code to set and then to null
  const updateReq2: IShoppingMallAiBackendMileageWallet.IUpdate = {
    id: createdWallet.id,
    security_code: RandomGenerator.alphabets(6),
  };
  const updatedWithPin = await api.functional.shoppingMallAiBackend.admin.mileageWallets.update(connection, {
    mileageWalletId: createdWallet.id,
    body: updateReq2,
  });
  typia.assert(updatedWithPin);
  TestValidator.equals("security_code set")(updatedWithPin.security_code !== null)(true);

  const updateReq3: IShoppingMallAiBackendMileageWallet.IUpdate = {
    id: createdWallet.id,
    security_code: null,
  };
  const clearedCode = await api.functional.shoppingMallAiBackend.admin.mileageWallets.update(connection, {
    mileageWalletId: createdWallet.id,
    body: updateReq3,
  });
  typia.assert(clearedCode);
  TestValidator.equals("security_code cleared")(clearedCode.security_code)(null);

  // 4. Negative test: Attempt to update disallowed field (customer_id) should be rejected
  const updateBad: any = {
    id: createdWallet.id,
    customer_id: typia.random<string & tags.Format<"uuid">>(), // not allowed to update
  };
  await TestValidator.error("disallowed field is rejected")(async () => {
    await api.functional.shoppingMallAiBackend.admin.mileageWallets.update(connection, {
      mileageWalletId: createdWallet.id,
      body: updateBad,
    });
  });

  // 5. Negative: Update non-existent wallet
  const nonExistId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent wallet id fails")(async () => {
    await api.functional.shoppingMallAiBackend.admin.mileageWallets.update(connection, {
      mileageWalletId: nonExistId,
      body: {
        id: nonExistId,
        wallet_label: "Ghost Wallet"
      },
    });
  });

  // 6. Negative: Update logically deleted wallet -- skipped; no delete API or support in SDK.
}

