/**
 * Validate seller access and authorization to specific product review snapshots.
 *
 * This test ensures that sellers can view detailed review snapshot records ONLY for reviews tied
 * to their own products, and that audit information is complete and correct.
 * Review snapshot detail is crucial for evidence, dispute, rollback, and business compliance use-cases.
 *
 * Steps:
 * 1. Register seller (as owner of a product)
 * 2. Seller creates a new product (owned by this seller)
 * 3. Register a test customer
 * 4. Customer creates a product review for this product
 * 5. Customer creates a review snapshot for the review
 * 6. Seller fetches the review snapshot (positive test)
 * 7. A different seller attempts to fetch it (negative: forbidden)
 * 8. Original seller fetches with random/nonexistent snapshotId (negative: not-found)
 */
export async function test_api_seller_review_snapshot_detail_access_and_authorization(
  connection: api.IConnection
) {
  // 1. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "SellerPass123!";
  const sellerSignUpRes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      companyName: "SellerBiz " + RandomGenerator.alphabets(8),
      businessNumber: "123-45-67890",
      representativeName: RandomGenerator.name(),
      address: "100 TestAve",
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(sellerSignUpRes);
  const sellerId = sellerSignUpRes.sellerId;

  // 2. Seller creates a product
  const productCreate = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: sellerId,
      code: "SKU-" + RandomGenerator.alphaNumeric(6),
      name: "AI Widget " + RandomGenerator.alphabets(4),
      description: "Great gadget for sellers.",
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(productCreate);
  const productId = productCreate.id;

  // 3. Register a customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "Customer321!";
  const customerSignUpRes = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(7),
      phone: RandomGenerator.mobile(),
    } satisfies ICustomerSignUp.Request,
  });
  typia.assert(customerSignUpRes);
  const customerId = customerSignUpRes.customer.id;

  // 4. Customer creates a product review for this product (simulate order_item_id)
  const orderItemId = typia.random<string & tags.Format<"uuid">>(); // Order flow not available, so simulate
  const productReview = await api.functional.shoppingMallAiBackend.customer.productReviews.create(connection, {
    body: {
      product_id: productId,
      order_item_id: orderItemId,
      title: "Initial Review",
      body: "Nice product!!",
      rating: 5,
      status: "normal",
      ai_sentiment_score: 0.88,
      ai_spam_score: 0.03,
    } satisfies IShoppingMallAiBackendProductReview.ICreate,
  });
  typia.assert(productReview);
  const productReviewId = productReview.id;

  // 5. Customer creates review snapshot
  const now = new Date().toISOString();
  const reviewSnapshot = await api.functional.shoppingMallAiBackend.customer.productReviews.reviewSnapshots.create(connection, {
    productReviewId,
    body: {
      review_id: productReviewId,
      body: productReview.body,
      rating: productReview.rating,
      status: productReview.status,
      actor_id: customerId,
      ai_sentiment_score: productReview.ai_sentiment_score ?? null,
      ai_spam_score: productReview.ai_spam_score ?? null,
      changed_at: now,
    } satisfies IShoppingMallAiBackendReviewSnapshot.ICreate,
  });
  typia.assert(reviewSnapshot);
  const reviewSnapshotId = reviewSnapshot.id;

  // 6. Seller fetches the review snapshot (should succeed, all fields/integrity)
  const sellerViewSnapshot = await api.functional.shoppingMallAiBackend.seller.productReviews.reviewSnapshots.at(connection, {
    productReviewId,
    reviewSnapshotId,
  });
  typia.assert(sellerViewSnapshot);
  TestValidator.equals("snapshot id matches")(sellerViewSnapshot.id)(reviewSnapshotId);
  TestValidator.equals("review id matches")(sellerViewSnapshot.review_id)(productReviewId);
  TestValidator.equals("body matches")(sellerViewSnapshot.body)(productReview.body);
  TestValidator.equals("rating matches")(sellerViewSnapshot.rating)(productReview.rating);
  TestValidator.equals("status matches")(sellerViewSnapshot.status)(productReview.status);
  TestValidator.equals("actor id matches")(sellerViewSnapshot.actor_id)(customerId);
  TestValidator.equals("changed_at timestamp matches")(sellerViewSnapshot.changed_at)(now);

  // 7. Another seller (not the owner) tries to fetch snapshot (should be forbidden)
  const otherSellerEmail = typia.random<string & tags.Format<"email">>();
  const otherSellerSignUpRes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: otherSellerEmail,
      password: "OtherSeller123!",
      companyName: "OtherBiz " + RandomGenerator.alphabets(6),
      businessNumber: "223-55-99877",
      representativeName: RandomGenerator.name(),
      address: "200 OtherRoad",
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp,
  });
  typia.assert(otherSellerSignUpRes);
  // Use other seller's JWT for authorization
  connection.headers = {
    ...connection.headers,
    Authorization: otherSellerSignUpRes.setHeaders.Authorization,
  };
  await TestValidator.error("forbidden for non-owner")(() =>
    api.functional.shoppingMallAiBackend.seller.productReviews.reviewSnapshots.at(connection, {
      productReviewId,
      reviewSnapshotId,
    })
  );

  // 8. Original seller tries random snapshotId (should be not-found)
  connection.headers = {
    ...connection.headers,
    Authorization: sellerSignUpRes.setHeaders.Authorization,
  };
  await TestValidator.error("not found for random snapshot id")(() =>
    api.functional.shoppingMallAiBackend.seller.productReviews.reviewSnapshots.at(connection, {
      productReviewId,
      reviewSnapshotId: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

