import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Test retrieval of paginated, filtered, and sorted product tags for a seller's product.
 *
 * This E2E function verifies the product tag search endpoint allows an authenticated seller to:
 * - Retrieve all tags attached to their product (pagination)
 * - Filter/search by tag string and supported fields
 * - Return sorted results (by tag, created_at, etc.)
 * - Correctly shows multiple tags, no tags, and paginates as expected
 * - Prevents unauthorized access (without auth token)
 * - Forbids access if the seller does not own the product
 * - Excludes soft-deleted tags from standard queries
 * - Rejects invalid filters and page parameters (validation error)
 *
 * Steps:
 * 1. Register a seller (s1) and create a product (owned by s1)
 * 2. Add multiple distinct tags
 * 3. List tags with no filter: should get all tags with total, pages, correct paginated content
 * 4. List tags with tag string filter (match one tag): should get only matching tag
 * 5. List tags with tag string filter (no match): should get empty result
 * 6. List (pagination): set small limit, get page 1/2 and verify correct records and order
 * 7. Sort by tag (desc/asc)
 * 8. Register another seller (s2). Confirm s2 cannot access s1's tags (403/forbidden)
 * 9. Attempt to search without auth (no token): should return 401
 * 10. (If soft-delete logic is visible to API) Ensure soft-deleted tags are excluded from query results (skip if not supported by API)
 * 11. Provide invalid page and/or filter input, confirm validation error
 */
export async function test_api_product_tag_admin_seller_list_filter_pagination(connection: api.IConnection) {
  // 1. Register first seller (s1)
  const email1 = typia.random<string & tags.Format<'email'>>();
  const s1 = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: email1,
      password: "Abcdef1234!",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(s1);

  // 2. Create product (owned by s1)
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: s1.sellerId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      status: "published",
      main_image_uri: null
    } satisfies IShoppingMallAiBackendProduct.ICreate
  });
  typia.assert(product);

  // 3. Add multiple tags
  const tagStrings = ["ai", "ml", "electronics", "smart-device", "gadget"];
  const createdTags = [] as IShoppingMallAiBackendProductTag[];
  for (const t of tagStrings) {
    const tag = await api.functional.shoppingMallAiBackend.seller.products.productTags.createProductTag(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        tag: t
      } satisfies IShoppingMallAiBackendProductTag.ICreate
    });
    typia.assert(tag);
    createdTags.push(tag);
  }

  // 4. List all tags (no filter)
  const listAll = await api.functional.shoppingMallAiBackend.seller.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: { product_id: product.id } satisfies IShoppingMallAiBackendProductTag.IRequest
  });
  typia.assert(listAll);
  TestValidator.equals("all tags present")(listAll.data.length)(tagStrings.length);

  // 5. Tag string filter matches one
  const filterSingle = await api.functional.shoppingMallAiBackend.seller.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: { product_id: product.id, tag: tagStrings[0] } satisfies IShoppingMallAiBackendProductTag.IRequest
  });
  typia.assert(filterSingle);
  TestValidator.equals("single tag filter")(filterSingle.data.length)(1);
  TestValidator.equals("single tag string")(filterSingle.data[0].tag)(tagStrings[0]);

  // 6. Tag string filter, no match
  const filterNone = await api.functional.shoppingMallAiBackend.seller.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: { product_id: product.id, tag: "not-exist-tag" } satisfies IShoppingMallAiBackendProductTag.IRequest
  });
  typia.assert(filterNone);
  TestValidator.equals("no tags")(filterNone.data.length)(0);

  // 7. Pagination (limit 2, page 1, 2, 3)
  const paginationPage1 = await api.functional.shoppingMallAiBackend.seller.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: { product_id: product.id, page: 1, limit: 2 } satisfies IShoppingMallAiBackendProductTag.IRequest
  });
  typia.assert(paginationPage1);
  TestValidator.equals("pagination 1 length")(paginationPage1.data.length)(2);
  TestValidator.equals("pagination 1 position")(paginationPage1.data[0].tag)(createdTags[0].tag);
  TestValidator.equals("pagination 1 position")(paginationPage1.data[1].tag)(createdTags[1].tag);
  const paginationPage2 = await api.functional.shoppingMallAiBackend.seller.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: { product_id: product.id, page: 2, limit: 2 } satisfies IShoppingMallAiBackendProductTag.IRequest
  });
  typia.assert(paginationPage2);
  TestValidator.equals("pagination 2 length")(paginationPage2.data.length)(2);
  const paginationPage3 = await api.functional.shoppingMallAiBackend.seller.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: { product_id: product.id, page: 3, limit: 2 } satisfies IShoppingMallAiBackendProductTag.IRequest
  });
  typia.assert(paginationPage3);
  TestValidator.equals("pagination 3 length")(paginationPage3.data.length)(1);

  // 8. Sort by tag asc/desc
  const sortedAsc = await api.functional.shoppingMallAiBackend.seller.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: { product_id: product.id, sort: "tag", direction: "asc" } satisfies IShoppingMallAiBackendProductTag.IRequest
  });
  typia.assert(sortedAsc);
  const sortedAscTags = [...tagStrings].sort();
  for (let i = 0; i < sortedAsc.data.length; ++i)
    TestValidator.equals(`asc sorting at ${i}`)(sortedAsc.data[i].tag)(sortedAscTags[i]);
  const sortedDesc = await api.functional.shoppingMallAiBackend.seller.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: { product_id: product.id, sort: "tag", direction: "desc" } satisfies IShoppingMallAiBackendProductTag.IRequest
  });
  typia.assert(sortedDesc);
  const sortedDescTags = [...tagStrings].sort().reverse();
  for (let i = 0; i < sortedDesc.data.length; ++i)
    TestValidator.equals(`desc sorting at ${i}`)(sortedDesc.data[i].tag)(sortedDescTags[i]);

  // 9. Register second seller (s2), cannot access s1's product tags
  const email2 = typia.random<string & tags.Format<'email'>>();
  const s2 = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: email2,
      password: "Zxcvbn4567!",
      companyName: RandomGenerator.name(),
      businessNumber: "0987654321",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(10),
      phone: RandomGenerator.mobile(),
    } satisfies ISellerAuth.SignUp
  });
  typia.assert(s2);

  // 10. Attempt forbidden access as s2
  TestValidator.error("forbidden: not product owner")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productTags.searchProductTags(connection, {
      productId: product.id,
      body: { product_id: product.id } satisfies IShoppingMallAiBackendProductTag.IRequest
    });
  });

  // 11. Attempt access without authentication (simulate unauthenticated connection)
  const unauthConn = { ...connection, headers: {} };
  TestValidator.error("unauthorized: no auth token")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productTags.searchProductTags(unauthConn, {
      productId: product.id,
      body: { product_id: product.id } satisfies IShoppingMallAiBackendProductTag.IRequest
    });
  });

  // 12. Invalid filter/page input: negative page
  TestValidator.error("invalid page param")(async () => {
    await api.functional.shoppingMallAiBackend.seller.products.productTags.searchProductTags(connection, {
      productId: product.id,
      body: { product_id: product.id, page: 0 } satisfies IShoppingMallAiBackendProductTag.IRequest
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductTag";
import type { IPageIShoppingMallAiBackendProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAuth";

/**
 * Test admin ability to search, filter, and page through all product tags on a given product.
 *
 * This test validates the following:
 *   - Only admins can access the product tag search endpoint for auditing and tag management.
 *   - Filtering by tag value, searching using partial string, and pagination all work as intended.
 *   - Response structure and pagination meta are present and correct.
 *   - Handles cases where no results are found.
 *   - Invalid search requests (e.g., invalid page/limit, unauthorized roles) return appropriate errors.
 *
 * Steps:
 * 1. Register an admin user to have access to the admin API endpoints.
 * 2. Create a product through the seller flow for tags to be assigned to.
 * 3. Add multiple tags to the product to have data to search and filter.
 * 4. As an admin, perform list and search operations with various filter criteria:
 *     - List all tags (should include all created, and verify that response data matches created tags)
 *     - Search by full and partial tag string
 *     - Paginate (provide limit & page)
 *     - Filter by nonexistent tag (should yield no results)
 *     - Use invalid pagination parameters (page=0, limit=0)
 *     - Attempt access as non-admin, expect authorization error
 */
export async function test_api_product_tag_admin_search_filter_audit_pagination(connection: api.IConnection) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestPassword123!";
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IAdminAuth.SignUp,
  });
  typia.assert(adminSignup);

  // 2. Create a product (simulate seller behavior)
  const product = await api.functional.shoppingMallAiBackend.seller.products.create(connection, {
    body: {
      seller_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      main_image_uri: null,
      status: "published",
    } satisfies IShoppingMallAiBackendProduct.ICreate,
  });
  typia.assert(product);

  // 3. Add multiple tags to the product (simulate seller tag additions)
  const tagsToCreate = [
    "eco-friendly",
    "limited-edition",
    "new-arrival",
    "sale",
    "archived",
  ];
  const createdTags = [] as IShoppingMallAiBackendProductTag[];
  for (const tag of tagsToCreate) {
    const prodTag = await api.functional.shoppingMallAiBackend.seller.products.productTags.createProductTag(connection, {
      productId: product.id,
      body: {
        product_id: product.id,
        tag,
      } satisfies IShoppingMallAiBackendProductTag.ICreate,
    });
    typia.assert(prodTag);
    createdTags.push(prodTag);
  }

  // 4. List all tags as admin and verify all created tags are present
  const allTags = await api.functional.shoppingMallAiBackend.admin.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendProductTag.IRequest,
  });
  typia.assert(allTags);
  const allTagStrings = allTags.data.map((t) => t.tag).sort();
  const createdTagStrings = tagsToCreate.slice().sort();
  TestValidator.equals("all tag values present")(allTagStrings)(createdTagStrings);
  TestValidator.equals("total count matches")(allTags.data.length)(tagsToCreate.length);

  // 5. Search by exact tag value
  const searchTag = tagsToCreate[1];
  const filteredTags = await api.functional.shoppingMallAiBackend.admin.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      tag: searchTag,
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendProductTag.IRequest,
  });
  typia.assert(filteredTags);
  TestValidator.predicate("only exact tag found")(filteredTags.data.length === 1 && filteredTags.data[0].tag === searchTag);

  // 6. Search by partial tag string using 'search'
  const partialString = "eco";
  const partialMatch = await api.functional.shoppingMallAiBackend.admin.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      search: partialString,
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendProductTag.IRequest,
  });
  typia.assert(partialMatch);
  TestValidator.predicate("partial matches returned")(partialMatch.data.some(tag => tag.tag.includes(partialString)));

  // 7. Pagination - only first 2 tags per page
  const paged = await api.functional.shoppingMallAiBackend.admin.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      page: 1,
      limit: 2,
    } satisfies IShoppingMallAiBackendProductTag.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("records per page")(paged.data.length)(2);
  TestValidator.equals("pagination present")(paged.pagination.limit)(2);

  // 8. No results case
  const noResults = await api.functional.shoppingMallAiBackend.admin.products.productTags.searchProductTags(connection, {
    productId: product.id,
    body: {
      product_id: product.id,
      tag: "nonexistent-tag-value",
      page: 1,
      limit: 10,
    } satisfies IShoppingMallAiBackendProductTag.IRequest,
  });
  typia.assert(noResults);
  TestValidator.equals("no data on not found")(noResults.data.length)(0);

  // 9. Invalid pagination params (page=0 should fail)
  await TestValidator.error("invalid page fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productTags.searchProductTags(connection, {
        productId: product.id,
        body: {
          product_id: product.id,
          page: 0,
          limit: 2,
        } satisfies IShoppingMallAiBackendProductTag.IRequest,
      });
    },
  );
  // 10. Invalid pagination params (limit=0 should fail)
  await TestValidator.error("invalid limit fails")(
    async () => {
      await api.functional.shoppingMallAiBackend.admin.products.productTags.searchProductTags(connection, {
        productId: product.id,
        body: {
          product_id: product.id,
          page: 1,
          limit: 0,
        } satisfies IShoppingMallAiBackendProductTag.IRequest,
      });
    },
  );

  // 11. Access from non-admin (simulate logout: new connection with no admin JWT)
  await TestValidator.error("non-admin gets denied")(
    async () => {
      // Simulate connection without admin authentication
      const normalConnection = Object.assign({}, connection, { headers: { ...connection.headers } });
      delete normalConnection.headers.Authorization;
      await api.functional.shoppingMallAiBackend.admin.products.productTags.searchProductTags(normalConnection, {
        productId: product.id,
        body: {
          product_id: product.id,
          page: 1,
          limit: 2,
        } satisfies IShoppingMallAiBackendProductTag.IRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import type { IShoppingMallAiBackendProductSearchKeyword } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductSearchKeyword";
import type { ISellerAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuth";

/**
 * Validates deletion of product search keywords by a seller, including permissions and existence constraints.
 *
 * Business context: Sellers enrich their product searchability by assigning keywords. They need the ability to remove obsolete or mistyped keywords securely. The action must be limited to the owning seller and ensure referential integrity; error handling and audit recording are critical for compliance and troubleshooting.
 *
 * Test steps:
 * 1. Register a new seller (for authentication and seller context).
 * 2. Create a product with that seller as owner.
