import type { IShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderStatusHistory";
import type { IPageIShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderStatusHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin search of order status history filtering by orderId and with pagination.
 *
 * This test ensures that:
 * - An order is created as a test subject.
 * - The admin creates multiple order status history entries for that order.
 * - The status history search endpoint returns only the relevant histories for the specified orderId.
 * - Filtering and pagination work as specified, and the response data matches schema expectations.
 *
 * Steps:
 * 1. Create a customer order via customer API (to have a legitimate orderId).
 * 2. As admin, create two status history records for that order (different statuses and actor types if possible).
 * 3. Search status histories for that orderId, first with limit=1 (page 1), then with limit=2 (should get both entries).
 * 4. Validate that entries returned are correct, orderId matches, fields are valid, and pagination meta is accurate.
 * 5. Try filtering by previous_status and actor_type for at least one value—it should return only matching record(s).
 */
export async function test_api_order_status_history_search_admin_success(connection: api.IConnection) {
  // 1. Create a new order as a customer (to get a valid orderId)
  const customerId = typia.random<string & tags.Format<'uuid'>>();
  const orderInput: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customerId,
    order_number: `ORD-${typia.random<string & tags.Format<'uuid'>>()}`,
    total_amount: 5000,
    currency_code: "USD",
    current_status: "created",
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderInput });
  typia.assert(order);

  // 2. As admin, create two status history entries for the order
  const adminId = typia.random<string & tags.Format<'uuid'>>();
  const nowA = new Date().toISOString();
  const histAInput: IShoppingMallAiBackendOrderStatusHistory.ICreate = {
    previous_status: "created",
    new_status: "paid",
    actor_type: "admin",
    actor_id: adminId,
    event_context: "Order payment confirmed by admin.",
    occurred_at: nowA,
  };
  const historyA = await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.create(connection, {
    orderId: order.id,
    body: histAInput,
  });
  typia.assert(historyA);

  // Add a second entry with slightly later timestamp and new actor
  const adminIdB = typia.random<string & tags.Format<'uuid'>>();
  const nowB = new Date(Date.now() + 60 * 1000).toISOString();
  const histBInput: IShoppingMallAiBackendOrderStatusHistory.ICreate = {
    previous_status: "paid",
    new_status: "shipped",
    actor_type: "system",
    actor_id: adminIdB,
    event_context: "Order picked up by courier (automated system entry).",
    occurred_at: nowB,
  };
  const historyB = await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.create(connection, {
    orderId: order.id,
    body: histBInput,
  });
  typia.assert(historyB);

  // 3. Now, search the status histories for the orderId with pagination: limit 1 (first page)
  const paged1 = await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.search(connection, {
    orderId: order.id,
    body: { page: 1, limit: 1 },
  });
  typia.assert(paged1);
  TestValidator.equals("pagination.current is 1")(paged1.pagination.current)(1);
  TestValidator.equals("pagination.limit is 1")(paged1.pagination.limit)(1);
  TestValidator.predicate("at least one result in paged1")(paged1.data.length > 0);
  paged1.data.forEach((h) => {
    typia.assert(h);
    TestValidator.equals("order_id matches")(h.order_id)(order.id);
  });

  // With pagination limit=2 (should get both entries)
  const paged2 = await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.search(connection, {
    orderId: order.id,
    body: { page: 1, limit: 2 },
  });
  typia.assert(paged2);
  TestValidator.equals("pagination.current is 1")(paged2.pagination.current)(1);
  TestValidator.equals("pagination.limit is 2")(paged2.pagination.limit)(2);
  TestValidator.predicate("has two results in paged2")(paged2.data.length === 2);
  paged2.data.forEach((h) => {
    typia.assert(h);
    TestValidator.equals("order_id matches")(h.order_id)(order.id);
  });

  // 4. Filter by previous_status 'created' (should match only histA)
  const filteredA = await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.search(connection, {
    orderId: order.id,
    body: { previous_status: "created", limit: 10 },
  });
  typia.assert(filteredA);
  TestValidator.predicate("filteredA returns one result")(filteredA.data.length === 1);
  TestValidator.equals("previous_status matches")(filteredA.data[0].previous_status)("created");

  // 5. Filter by actor_type 'system' (should match only histB)
  const filteredB = await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.search(connection, {
    orderId: order.id,
    body: { actor_type: "system", limit: 10 },
  });
  typia.assert(filteredB);
  TestValidator.predicate("filteredB returns one result")(filteredB.data.length === 1);
  TestValidator.equals("actor_type matches")(filteredB.data[0].actor_type)("system");
}

