import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderStatusHistory";
import type { IPageIShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendOrderStatusHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that a seller can search order status histories for an order they are assigned.
 *
 * This test covers end-to-end flow for seller status history visibility and enforcement. It ensures all history entries returned belong to the correct order, with proper fields and pagination summary.
 *
 * Business scenario:
 * 1. Create a customer order (use the customer order creation endpoint)
 * 2. Create 3 status histories for this order (using seller 'create status history' endpoint)
 * 3. Search for status histories as the seller (patch/search endpoint)
 * 4. Validate that all returned data has order_id matching the order, correct actor_type, and all required fields
 * 5. Check that pagination fields are consistent with the count/data length
 * 6. Test filtering by previous_status and new_status, and pagination limit
 */
export async function test_api_order_status_history_search_seller_success(connection: api.IConnection) {
  // 1. Create a customer order with dummy data (required fields only)
  const customerId: string = typia.random<string & tags.Format<"uuid">>();
  const orderCreateInput: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customerId,
    order_number: RandomGenerator.alphaNumeric(12),
    total_amount: 100000,
    currency_code: "KRW",
    current_status: "created",
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(connection, { body: orderCreateInput });
  typia.assert(order);

  // 2. Create 3 status histories using the seller API
  const statusTransitions = [
    { previous: "created", next: "paid" },
    { previous: "paid", next: "shipped" },
    { previous: "shipped", next: "delivered" },
  ];

  const sellerId: string = typia.random<string & tags.Format<"uuid">>();
  const createdHistories: IShoppingMallAiBackendOrderStatusHistory[] = [];
  for (const transition of statusTransitions) {
    const historyInput: IShoppingMallAiBackendOrderStatusHistory.ICreate = {
      previous_status: transition.previous,
      new_status: transition.next,
      actor_type: "seller",
      actor_id: sellerId,
      occurred_at: new Date().toISOString(),
    };
    const statusHistory = await api.functional.shoppingMallAiBackend.seller.orders.orderStatusHistories.create(connection, {
      orderId: order.id,
      body: historyInput,
    });
    typia.assert(statusHistory);
    createdHistories.push(statusHistory);
  }

  // 3. Search without filter; should get all 3 histories (full page)
  const searchResult = await api.functional.shoppingMallAiBackend.seller.orders.orderStatusHistories.search(connection, {
    orderId: order.id,
    body: {},
  });
  typia.assert(searchResult);
  TestValidator.equals("total histories count")(searchResult.pagination.records)(3);
  TestValidator.equals("all returned histories")(searchResult.data.length)(3);
  for (const h of searchResult.data) {
    TestValidator.equals("belongs to correct order")(h.order_id)(order.id);
    TestValidator.equals("actor type is seller")(h.actor_type)("seller");
    TestValidator.predicate("required fields exist")(
      !!h.id && !!h.previous_status && !!h.new_status && !!h.actor_id && !!h.occurred_at
    );
  }

  // 4. Search with filter: previous_status = "paid"
  const filteredResult = await api.functional.shoppingMallAiBackend.seller.orders.orderStatusHistories.search(connection, {
    orderId: order.id,
    body: { previous_status: "paid" },
  });
  typia.assert(filteredResult);
  TestValidator.equals("filtered results count")(filteredResult.pagination.records)(1);
  TestValidator.equals("filtered by previous_status")(filteredResult.data[0].previous_status)("paid");
  TestValidator.equals("filtered by previous_status")(filteredResult.data[0].order_id)(order.id);

  // 5. Pagination test: limit = 2, page = 1
  const pageResult = await api.functional.shoppingMallAiBackend.seller.orders.orderStatusHistories.search(connection, {
    orderId: order.id,
    body: { limit: 2, page: 1 },
  });
  typia.assert(pageResult);
  TestValidator.equals("pagination page")(pageResult.pagination.current)(1);
  TestValidator.equals("pagination limit")(pageResult.pagination.limit)(2);
  // Data length may be 2 or less, check for correct length
  TestValidator.predicate("pagination data length")(pageResult.data.length <= 2);
}

