import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrder";
import type { IShoppingMallAiBackendOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderStatusHistory";

/**
 * Validate that an admin retrieves complete details of an order status history record.
 *
 * This test ensures the order status auditing API operates correctly and returns all required business and audit fields:
 *
 * 1. Create a new order as a customer, recording the orderId for status auditing.
 * 2. As an admin, create a new status history entry for that order (generating an orderStatusHistoryId).
 * 3. Retrieve this status history via the admin status history detail API.
 * 4. Assert that the data returned exactly matches what was set in the creation step for the status transition: previous/new status, actor info, audit metadata, occurrence timestamp, and all contractually agreed fields.
 *
 * This scenario validates that auditing records are created, persisted, and retrievable with all metadata for compliance and workflow transparency.
 */
export async function test_api_order_status_history_get_detail_admin_success(
  connection: api.IConnection,
) {
  // 1. Create a new customer order for status history testing
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const orderBody: IShoppingMallAiBackendOrder.ICreate = {
    customer_id: customerId,
    order_number: RandomGenerator.alphaNumeric(12),
    total_amount: 10000,
    currency_code: "KRW",
    current_status: "created",
    note: RandomGenerator.paragraph()(),
  };
  const order = await api.functional.shoppingMallAiBackend.customer.orders.create(
    connection,
    { body: orderBody },
  );
  typia.assert(order);

  // 2. As admin, add a new status history event for that order
  const statusHistoryBody: IShoppingMallAiBackendOrderStatusHistory.ICreate = {
    previous_status: order.current_status,
    new_status: "processing",
    actor_type: "admin",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    event_context: RandomGenerator.paragraph()(),
    occurred_at: new Date().toISOString(),
  };
  const statusHistory =
    await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.create(
      connection,
      {
        orderId: order.id,
        body: statusHistoryBody,
      },
    );
  typia.assert(statusHistory);

  // 3. Retrieve this status history by detail API
  const detail =
    await api.functional.shoppingMallAiBackend.admin.orders.orderStatusHistories.at(
      connection,
      {
        orderId: order.id,
        orderStatusHistoryId: statusHistory.id,
      },
    );
  typia.assert(detail);

  // 4. Assert every critical field and audit metadata matches expectations
  TestValidator.equals("status history ID")(detail.id)(statusHistory.id);
  TestValidator.equals("order ID")(detail.order_id)(order.id);
  TestValidator.equals("previous status")(detail.previous_status)(statusHistoryBody.previous_status);
  TestValidator.equals("new status")(detail.new_status)(statusHistoryBody.new_status);
  TestValidator.equals("actor type")(detail.actor_type)(statusHistoryBody.actor_type);
  TestValidator.equals("actor ID")(detail.actor_id)(statusHistoryBody.actor_id);
  TestValidator.equals("event context")(detail.event_context)(statusHistoryBody.event_context);
  TestValidator.equals("occurred at")(detail.occurred_at)(statusHistoryBody.occurred_at);
}

