/**
 * Validate that a seller can successfully retrieve the details of an order status history record for an order they own.
 *
 * Business context: Sellers must be able to audit the workflow and track all state changes for orders associated with their products. This test ensures compliance, auditability, and correct application of business access controls.
 *
 * Steps:
 * 1. Register a seller account (to own product/orders).
 * 2. Register a product for this seller.
 * 3. Register a customer account (to place the order).
 * 4. Place an order as the customer for the seller's product (and get order ID).
 * 5. As the seller, update the status of the order – this will create a status history record.
 * 6. Retrieve the status history record by orderId and statusHistoryId as the seller.
 * 7. Assert that all important fields (before/after status, actor_type, actor_id, context, occurred_at) are correct and match the generated record.
 */
export async function test_api_order_status_history_detail_retrieval_by_seller_success(connection: api.IConnection) {
  // 1. Register seller
  const seller_signup = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "securePass!23",
      companyName: RandomGenerator.name(),
      businessNumber: "1234567890",
      representativeName: RandomGenerator.name(),
      address: RandomGenerator.paragraph()(),
      phone: RandomGenerator.mobile(),
    }
  });
