 *   3. Favorite the newly created inquiry
 *   4. Update the favorite inquiry's metadata (soft-unfavorite by setting deleted_at)
 *   5. Confirm that the unfavorited state is persisted
 *   6. Attempt to update an inquiry not owned by the customer (expect error)
 *   7. Try an invalid data update (e.g., wrong type for deleted_at, expect error)
 *
 * Each step is validated with typia assertions and business logic checks. Negative paths (unauthorized and invalid input) are covered to ensure robustness.
 */
export async function test_api_favorite_inquiry_update_metadata(connection: api.IConnection) {
  // 1. Customer registers (and connection JWT is set)
  const customerSignUpResp = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(customerSignUpResp);
  const customer = customerSignUpResp.customer;

  // 2. Create a product inquiry for the customer
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, {
    body: {
      customer_id: customer.id,
      product_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(3)(10),
      public: true
    } satisfies IShoppingMallAiBackendProductInquiry.ICreate
  });
  typia.assert(inquiry);

  // 3. Favorite the product inquiry
  const favorite = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.create(connection, {
    body: {
      inquiry_id: inquiry.id
    } satisfies IShoppingMallAiBackendFavoriteInquiry.ICreate
  });
  typia.assert(favorite);
  TestValidator.equals("favorite inquiry customer matches")(favorite.customer_id)(customer.id);
  TestValidator.equals("favorite inquiry linked to inquiry")(favorite.inquiry_id)(inquiry.id);
  TestValidator.equals("favorite is active")(favorite.deleted_at)(null);

  // 4. Update the favorite inquiry (mark as unfavorited/soft-delete)
  const now = new Date().toISOString();
  const updated = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.update(connection, {
    favoriteInquiryId: favorite.id,
    body: {
      deleted_at: now
    } satisfies IShoppingMallAiBackendFavoriteInquiry.IUpdate
  });
  typia.assert(updated);
  TestValidator.equals("favorite unfavored")(updated.deleted_at)(now);

  // 5. Confirm important fields after update
  TestValidator.equals("favorite inquiry still belongs to customer")(updated.customer_id)(customer.id);
  TestValidator.equals("favorite inquiry links to original inquiry")(updated.inquiry_id)(inquiry.id);

  // 6. Attempt to update a non-owned favorite inquiry
  // Register another customer (JWT now set for new user)
  const otherUser = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "OtherPass#456",
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(9),
      phone: RandomGenerator.mobile()
    } satisfies ICustomerSignUp.Request
  });
  typia.assert(otherUser);
  // Confirm an error is thrown when updating a favorite not owned by this user
  TestValidator.error("cannot update another user's favorite inquiry")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.update(connection, {
        favoriteInquiryId: favorite.id,
        body: {
          deleted_at: new Date().toISOString()
        } satisfies IShoppingMallAiBackendFavoriteInquiry.IUpdate
      });
    }
  );

  // 7. Attempt invalid update (bad deleted_at type)
  TestValidator.error("invalid deleted_at type is rejected")(
    async () => {
      await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.update(connection, {
        favoriteInquiryId: favorite.id,
        body: {
          // Force type error at runtime
          deleted_at: 12345 as any
        } as any
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendProductInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductInquiry";
import type { IShoppingMallAiBackendFavoriteInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteInquiry";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * Test soft-deleting a favorite inquiry entry by ID.
 *
 * Business context:
 * - Customers can favorite inquiries for tracking or notifications.
 * - Unfavoriting should not hard-delete but rather soft-delete (marking deleted_at).
 * - Only the owner (authenticated customer) can perform unfavorite (soft-delete) on their own favorite inquiry record.
 *
 * Steps:
 * 1. Register and authenticate a customer.
 * 2. Create a product inquiry as that customer (need an inquiry to favorite).
 * 3. Favorite the inquiry (create a favorite inquiry record).
 * 4. Soft-delete (unfavorite) the favorite inquiry by its ID (API DELETE call).
 * 5. Attempt to access or refavorite after deletion to confirm it is gone/blocked.
 * 6. Attempt deleting again (idempotency: should error or grace).
 * 7. Try deleting a non-existent favorite inquiry ID.
 * 8. Register a second customer, attempt to delete the original customer's favorite (should fail: ownership enforced).
 *
 *  All relevant negative cases (ownership, idempotency, not found) must be validated.
 */
export async function test_api_favorite_inquiry_soft_delete(connection: api.IConnection) {
  // 1. Register and authenticate a customer.
  const customerInput: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongP@ssw0rd!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const regRes = await api.functional.auth.customer.register.signUp(connection, { body: customerInput });
  typia.assert(regRes);
  const customerId = regRes.customer.id;

  // 2. Create a product inquiry as this customer.
  const inquiryInput: IShoppingMallAiBackendProductInquiry.ICreate = {
    customer_id: customerId,
    product_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    public: true,
  };
  const inquiry = await api.functional.shoppingMallAiBackend.customer.productInquiries.create(connection, { body: inquiryInput });
  typia.assert(inquiry);

  // 3. Favorite the inquiry.
  const favoriteRes = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.create(connection, { body: { inquiry_id: inquiry.id } });
  typia.assert(favoriteRes);

  // 4. Unfavorite (soft-delete) by its ID.
  await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.erase(connection, { favoriteInquiryId: favoriteRes.id });

  // 5. Try to favorite it again (should create a new one or error if not allowed).
  // (Depending on API: may recreate or fail; check post-delete state positively.)
  let favoriteResAgain = null;
  try {
    favoriteResAgain = await api.functional.shoppingMallAiBackend.customer.favoriteInquiries.create(connection, { body: { inquiry_id: inquiry.id } });
    typia.assert(favoriteResAgain);
  } catch (err) {
    // If fails, pass as valid if API blocks refavorite of soft-deleted
  }

  // 6. Attempt deleting again (should be idempotent or return error)
  await TestValidator.error("Idempotent delete should error or pass silently")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteInquiries.erase(connection, { favoriteInquiryId: favoriteRes.id }),
  );

  // 7. Deleting a non-existent favoriteInquiryId
  await TestValidator.error("Non-existent favoriteInquiryId fails")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteInquiries.erase(connection, { favoriteInquiryId: typia.random<string & tags.Format<"uuid">>() }),
  );

  // 8. Register second customer, attempt to delete other's favorite (should fail)
  const customerInput2: ICustomerSignUp.Request = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongP@ssw0rd2!",
    name: RandomGenerator.name(),
    nickname: RandomGenerator.alphabets(8),
    phone: RandomGenerator.mobile(),
  };
  const regRes2 = await api.functional.auth.customer.register.signUp(connection, { body: customerInput2 });
  typia.assert(regRes2);
  // Now try delete as this new customer
  await TestValidator.error("Non-owner cannot delete other's favorite")(() =>
    api.functional.shoppingMallAiBackend.customer.favoriteInquiries.erase(connection, { favoriteInquiryId: favoriteRes.id }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomerAddress";
import type { IPageIShoppingMallAiBackendCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendCustomerAddress";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IShoppingMallAiBackendFavoriteAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteAddress";
import type { IPageIShoppingMallAiBackendFavoriteAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendFavoriteAddress";
import type { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import type { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";

/**
 * End-to-end test for listing and filtering a customer's favorite addresses, supporting business pagination and filter scenarios.
 *
 * Business goals:
 * - Ensure favorite address listing/filtering works for an authenticated customer only (privacy)
 * - Correctly returns only active favorites, not soft-deleted
 * - Filtering: supports created_at date range and pagination on PATCH endpoint
 * - Negative test: handles invalid filters (invalid limit), rejects unauthenticated access
 *
 * Workflow:
 * 1. Register a new customer/account (retains connection authorization)
 * 2. Add/associate several addresses to the customer account (imitate address book by using those from test DB)
 * 3. Mark a subset of these addresses as favorites
 * 4. Run PATCH favoriteAddresses with default (no filters): must return all active favorite records for this customer
 * 5. Run PATCH again (with created_at_from/created_at_to and pagination - eg limit=2) and verify only valid/filtered records are returned
 * 6. Negative: try with invalid filter parameters (such as `limit=0`), expect errors
 * 7. Negative: logout/remove Authorization, try listing again — must be denied (unauthenticated)
 */
export async function test_api_favorite_addresses_list_pagination_filtering(
  connection: api.IConnection,
) {
  // 1. Register account
  const signup = await api.functional.auth.customer.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.name(),
      nickname: RandomGenerator.alphabets(8),
      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(signup);
  const customerId = signup.customer.id;

  // 2. Obtain addresses for this customer (admin listing — test DB must have test data)
  const addressesResp = await api.functional.shoppingMallAiBackend.admin.customers.addresses.search(connection, {
    customerId,
    body: {},
  });
  typia.assert(addressesResp);
  const addresses = addressesResp.data;
  if (!addresses.length)
    throw new Error("No addresses for customer found in test DB. Skipping favorite-address scenario.");

  // 3. Mark several as favorites (first up to 2)
  const favoriteTargets = addresses.slice(0, Math.min(2, addresses.length));
  for (let addr of favoriteTargets) {
    const fav = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.create(connection, {
      body: { customer_id: customerId, address_id: addr.id },
    });
    typia.assert(fav);
    TestValidator.equals("favorite mapped correctly")(fav.customer_id)(customerId);
    TestValidator.equals("favorited address ID matches")(fav.address_id)(addr.id);
  }

  // 4. List all favorites, no filters (should include all favorites just created above)
  const allFavsResp = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
    body: { customer_id: customerId },
  });
  typia.assert(allFavsResp);
  const allFavIds = allFavsResp.data.map((fa) => fa.address_id);
  for (const favTarget of favoriteTargets)
    TestValidator.predicate("favorite present in list")(allFavIds.includes(favTarget.id));

  // 5. Test filters (date ranges, pagination)
  // Filter by created_at date range of one favorite
  if (allFavsResp.data.length > 0) {
    const dateFrom = allFavsResp.data[0].created_at;
    const dateTo = allFavsResp.data[0].created_at;
    const byDate = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
      body: { customer_id: customerId, created_at_from: dateFrom, created_at_to: dateTo },
    });
    typia.assert(byDate);
    TestValidator.predicate("date-range filter result nonempty")(
      byDate.data.length > 0
    );
  }

  // Pagination (limit: 1)
  const paged = await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
    body: { customer_id: customerId, limit: 1, page: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("pagination (limit=1)")(paged.data.length)(1);

  // 6. Negative: invalid limit (0)
  await TestValidator.error("limit zero triggers error")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(connection, {
      body: { customer_id: customerId, limit: 0 },
    });
  });

  // 7. Privacy/unauthenticated: clear Authorization and try listing
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("privacy enforced: unauthenticated cannot list favorites")(async () => {
    await api.functional.shoppingMallAiBackend.customer.favoriteAddresses.search(
      unauthConn,
      {
        body: { customer_id: customerId },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
