      phone: RandomGenerator.mobile(),
    },
  });
  typia.assert(customerSignUpResponse);
  const ownerCustomer = customerSignUpResponse.customer;
  const ownerCustomerId = ownerCustomer.id;

  // 2. List addresses for the owner and pick the first one for updating
  const addressListPage = await api.functional.shoppingMallAiBackend.customer.customers.addresses.search(connection, {
    customerId: ownerCustomerId,
    body: {},
  });
  typia.assert(addressListPage);
  TestValidator.predicate("at least one address exists for new customer")(
    addressListPage.data.length > 0
  );
  const addressForUpdate = addressListPage.data[0];

  // 3. Successful update: change receiver_name and verify update
  const newReceiverName = RandomGenerator.name();
  const updatedAddress = await api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
    customerId: ownerCustomerId,
    body: {
      id: addressForUpdate.id,
      receiver_name: newReceiverName,
    },
  });
  typia.assert(updatedAddress);
  TestValidator.equals("receiver_name updated")(updatedAddress.receiver_name)(newReceiverName);
  TestValidator.equals("id unchanged")(updatedAddress.id)(addressForUpdate.id);

  // 4. Blank receiver_name: invalid blank name
  await TestValidator.error("blank receiver_name fails")(() =>
    api.functional.shoppingMallAiBackend.customer.customers.addresses.update(connection, {
      customerId: ownerCustomerId,
      body: {
        id: addressForUpdate.id,
        receiver_name: "",
      },
